        hc = _rescale(hc)
        hc = _lbfgs_log(hc, 400, deadline)
        hc = _prolongate(hc, n)
        _try_candidate(hc, "coarse%d" % Nc)

    # Phase shifts.
    for delta in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 3.0:
            break
        hp = _phase_shift(best, delta)
        _try_candidate(hp, "phase%+.2f" % delta)

    # Anneal path from best (only if time remains).
    if time.process_time() < deadline - 6.0:
        h = _anneal_softmax(best, deadline)
        r = R_of(h)
        print("anneal R=%.7f" % r)
        if alt is None or r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r

    # Final alternating polish until budget exhausted.
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
