        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _true_polish(h, deadline, rounds=2):
    cur = h
    cur_r = R_of(cur)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_log(cur, maxiter=400, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= deadline - 1.0:
            break
        cand = _window_polish_peak(cur, deadline, 0.10, 8, maxiter=400)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _hard_threshold(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = h.max()
    h = h.copy()
    h[h < 1e-3 * mx] = 0.0
    return h


def _block_perturb(h, rng):
    n = h.size
    B = int(rng.choice([64, 128, 256]))
    B = min(B, n)
    edges = np.linspace(0, n, B + 1).astype(int)
    out = h.copy()
    zero_frac = rng.uniform(0.10, 0.30)
    for i in range(B):
        lo, hi = edges[i], edges[i + 1]
        if hi <= lo:
            continue
        if rng.random() < zero_frac:
            out[lo:hi] = 0.0
        else:
            f = np.exp(rng.uniform(-1.0, 1.0))
            out[lo:hi] *= f
    if out.sum() <= 0:
        return h.copy()
    return _rescale(out)


def _sparse_seed(N, rng):
    nblk = int(rng.integers(20, 41))
    edges = np.linspace(0, N, nblk + 1).astype(int)
    out = np.zeros(N)
    zero_frac = rng.uniform(0.40, 0.70)
    for i in range(nblk):
        lo, hi = edges[i], edges[i + 1]
        if hi <= lo:
            continue
        if rng.random() < zero_frac:
            continue
        val = np.exp(rng.uniform(np.log(30.0), np.log(1000.0)))
        out[lo:hi] = val
    if out.sum() <= 0:
        out[:] = 1.0
    return _rescale(out)


def _homotopy(cand, deadline, betas=(2, 4, 8, 16, 32, 64, 128), maxiter=250):
    cur = cand
    cur_r = R_of(cur)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        c = _lbfgs_sm(cur, beta, maxiter=maxiter, deadline=deadline)
        r = R_of(c)
        if r > cur_r:
            cur, cur_r = c, r
    if time.process_time() < deadline - 1.0:
        c = _lbfgs_log(cur, maxiter=600, deadline=deadline)
        r = R_of(c)
        if r > cur_r:
            cur, cur_r = c, r
    if time.process_time() < deadline - 1.0:
        c = _window_polish_peak(cur, deadline, 0.10, 8, maxiter=400)
        r = R_of(c)
        if r > cur_r:
            cur, cur_r = c, r
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    N0 = 32768
    if cur.size != N0:
        cand = _coarsen(cur, N0)
        cand = _rescale(cand)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r

    improved = False
    for beta in (4, 8, 16, 32, 64):
        if time.process_time() >= deadline - 6.0:
            break
        cand = _lbfgs_sm(cur, beta, maxiter=300, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
            improved = True

    if time.process_time() < deadline - 4.0:
        cand, r = _true_polish(cur, deadline, rounds=2)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
            improved = True

    if improved and time.process_time() < deadline - 3.0:
        for N in (65536, 131072, 262144):
            if time.process_time() >= deadline - 4.0:
                break
            if cur.size == N:
                cand = cur.copy()
            else:
                cand = _prolongate(cur, N)
                cand = _rescale(cand)
            for beta in (16, 64):
                if time.process_time() >= deadline - 4.0:
                    break
                c2 = _lbfgs_sm(cand, beta, maxiter=200, deadline=deadline)
                r2 = R_of(c2)
                if r2 > R_of(cand):
                    cand = c2
            cand, r = _true_polish(cand, deadline, rounds=2)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

    # Restart loop: perturb incumbent / fresh sparse seeds, relock via homotopy
    rng = np.random.default_rng(12345)
    baseline = best_r
    near_count = 0
    restart_count = 0
    incumbent = cur.copy()
    inc_r = cur_r

    while time.process_time() < deadline - 1.0:
        if time.process_time() >= deadline - 1.0:
            break
        restart_count += 1
        # Alternate between perturbed incumbent and fresh sparse seed
        if restart_count % 2 == 1:
            cand = _block_perturb(incumbent, rng)
        else:
            cand = _sparse_seed(8192, rng)
        cand = _hard_threshold(cand)
        cand = _rescale(cand)
        if cand.sum() <= 0:
            continue
        cand, r = _homotopy(cand, deadline)
        cand = _hard_threshold(cand)
        cand = _rescale(cand)
        r = R_of(cand)
        if abs(r - baseline) < 1e-4:
            near_count += 1
        if r > inc_r:
            incumbent = cand.copy()
            inc_r = r
        if r > best_r:
            best, best_r = cand.copy(), r
            # Ladder improved candidate to 65536
            if time.process_time() < deadline - 2.0 and best.size != 65536:
                big = _prolongate(best, 65536)
                big = _rescale(big)
                big, rb = _homotopy(big, deadline)
                big = _hard_threshold(big)
                big = _rescale(big)
                rb = R_of(big)
                if rb > best_r:
                    best, best_r = big.copy(), rb

    # Final true-objective polish on best
    if time.process_time() < deadline - 0.5:
        c = _lbfgs_log(best, maxiter=800, deadline=deadline)
        r = R_of(c)
        if r > best_r:
            best, best_r = c, r
        if time.process_time() < deadline - 0.5:
            c = _window_polish_peak(best, deadline, 0.10, 8, maxiter=400)
            r = R_of(c)
            if r > best_r:
                best, best_r = c, r

    print(f"restarts={restart_count} near_baseline={near_count} best={best_r:.6f}")

    best = _rescale(best)
    if start_arr is not None:
        return {"best": best, "alternative": _rescale(start_arr)}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
