    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _smooth_conv(h, k):
    if k <= 1:
        return h
    ker = np.ones(k) / k
    out = np.convolve(h, ker, mode='same')
    return np.clip(out, 0, None)


def _shift_resample(h, delta):
    n = h.size
    x = np.arange(n) + delta
    return np.interp(x, np.arange(n), h, left=0.0, right=0.0)


def _mirror(h):
    return np.concatenate((h, h[::-1]))


def _unmirror(h):
    n = h.size
    return h[:n // 2]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    alt = best.copy()
    alt_r = best_r

    # 1) mirror symmetrisation: R is invariant to reversing f, so f+reverse
    #    has a symmetric autoconvolution. This is a genuinely new construction
    #    (symmetric support) and often reaches a better local optimum.
    if time.process_time() < deadline - 30.0:
        n0 = best.size
        hm = _mirror(best)
        hm = _rescale(hm)
        # polish the symmetric version at doubled resolution
        hm = _lbfgs_log(hm, maxiter=1500,
                        deadline=min(deadline, time.process_time() + 20.0))
        rm = R_of(hm)
        if rm > alt_r + 1e-9:
            alt, alt_r = hm, rm
        if rm > best_r + 1e-9:
            best, best_r = hm.copy(), rm

    # 2) coarse-to-fine polish of the working best
    cur = best.copy()
    cur_r = best_r
    n_cur = cur.size
    for Nc in [max(64, n_cur // 16), max(128, n_cur // 8),
               max(256, n_cur // 4), max(512, n_cur // 2)]:
        if time.process_time() >= deadline - 4.0:
            break
        if Nc >= cur.size:
            continue
        hc = _coarse(cur, Nc)
        hc = _rescale(hc)
        hc = _lbfgs_log(hc, maxiter=1200,
                        deadline=min(deadline, time.process_time() + 4.0))
        hf = _prolongate(hc, cur.size)
        hf = _smooth_conv(hf, 2)
        hf = _rescale(hf)
        hf = _lbfgs_log(hf, maxiter=800, deadline=deadline)
        r = R_of(hf)
        if r > cur_r + 1e-9:
            cur, cur_r = hf, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

    # 3) grow N and polish
    N = cur.size
    while time.process_time() < deadline - 4.0 and N < 1000000:
        N = min(1000000, max(N * 2, N + 50))
        if N <= cur.size:
            break
        cand = _prolongate(cur, N)
        cand = _smooth_conv(cand, 2)
        cand = _rescale(cand)
        cand = _lbfgs_log(cand, maxiter=2500, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if r <= best_r - 1e-6 and N > 4000:
            break

    # 4) peak-window polishing
    for frac, extra in [(0.5, 4), (0.25, 4), (0.1, 4), (0.05, 4)]:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _window_polish_peak(cur, deadline, frac, extra, maxiter=800)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

    # 5) final full polish
    if time.process_time() < deadline - 0.5:
        cand = _lbfgs_log(best, maxiter=3000, deadline=deadline)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            rs = R_of(s)
            if rs >= best_r:
                # keep the mirror construction as alternative if it differs
                if alt is not None and alt_r > rs:
                    return {"best": alt, "alternative": s}
                return {"best": best, "alternative": s}
    if alt is not None and alt_r > best_r:
        return {"best": alt, "alternative": best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _window_polish_tail(h, deadline, frac, maxiter=400):
    """Polish the low-amplitude tails (outside the peak region)."""
    n = h.size
    lo, hi = _peak_region(h, tol=0.99)
    span = hi - lo
    pad = max(8, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    mask = np.ones(n, dtype=bool)
    mask[lo:hi + 1] = False
    free = np.flatnonzero(mask)
    if free.size == 0:
        return h
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _full_polish(h, deadline, rounds=2):
    cur = h
    cur_r = R_of(cur)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_log(cur, maxiter=400, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= deadline - 1.0:
            break
        cand = _window_polish_peak(cur, deadline, 0.10, 8, maxiter=400)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= deadline - 1.0:
            break
        cand = _window_polish_tail(cur, deadline, 0.10, maxiter=300)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _hard_threshold(h, tol=1e-3):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = h.max()
    h = h.copy()
    h[h < tol * mx] = 0.0
    return h


def _block_perturb(h, rng):
    n = h.size
    B = int(rng.choice([64, 128, 256]))
    B = min(B, n)
    edges = np.linspace(0, n, B + 1).astype(int)
    out = h.copy()
    zero_frac = rng.uniform(0.10, 0.30)
    for i in range(B):
        lo, hi = edges[i], edges[i + 1]
        if hi <= lo:
            continue
        if rng.random() < zero_frac:
            out[lo:hi] = 0.0
        else:
            f = np.exp(rng.uniform(-1.0, 1.0))
            out[lo:hi] *= f
    if out.sum() <= 0:
        return h.copy()
    return _rescale(out)


def _sparse_seed(N, rng):
    nblk = int(rng.integers(20, 41))
    edges = np.linspace(0, N, nblk + 1).astype(int)
    out = np.zeros(N)
    zero_frac = rng.uniform(0.40, 0.70)
    for i in range(nblk):
        lo, hi = edges[i], edges[i + 1]
        if hi <= lo:
            continue
        if rng.random() < zero_frac:
            continue
        val = np.exp(rng.uniform(np.log(30.0), np.log(1000.0)))
        out[lo:hi] = val
    if out.sum() <= 0:
        out[:] = 1.0
    return _rescale(out)


def _homotopy(cand, deadline):
    cur = cand
    cur_r = R_of(cur)
    for beta in (2, 4, 8, 16, 32, 64, 128):
        if time.process_time() >= deadline - 1.0:
            break
        c = _lbfgs_sm(cur, beta, maxiter=250, deadline=deadline)
        r = R_of(c)
        if r > cur_r:
            cur, cur_r = c, r
    if time.process_time() < deadline - 1.0:
        c = _lbfgs_log(cur, maxiter=600, deadline=deadline)
        r = R_of(c)
        if r > cur_r:
            cur, cur_r = c, r
    if time.process_time() < deadline - 1.0:
        c = _window_polish_peak(cur, deadline, 0.10, 8, maxiter=400)
        r = R_of(c)
        if r > cur_r:
            cur, cur_r = c, r
    return cur, cur_r


# Smooth approximation objective for L-BFGS (defined here so _homotopy can use it)
def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    # Phase 1: full-log polish of the incumbent (exact objective)
    if time.process_time() < deadline - 4.0:
        cand = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

    # Phase 2: peak + tail window polish at current resolution
    if time.process_time() < deadline - 4.0:
        cand, r = _full_polish(cur, deadline, rounds=2)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

    # Phase 3: ladder to higher resolution, only if we improved on start
    improved_over_start = start_arr is None or best_r > R_of(start_arr)
    if improved_over_start and time.process_time() < deadline - 6.0:
        for N in (65536, 131072):
            if time.process_time() >= deadline - 5.0:
                break
            if cur.size == N:
                cand = cur.copy()
            else:
                cand = _prolongate(cur, N)
                cand = _rescale(cand)
            cand = _lbfgs_log(cand, maxiter=400, deadline=deadline)
            cand, r = _full_polish(cand, deadline, rounds=1)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

    # Phase 4: restart loop with perturbation + homotopy, keep improving
    rng = np.random.default_rng(987654321)
    incumbent = cur.copy()
    inc_r = cur_r
    restart_count = 0
    baseline = best_r

    while time.process_time() < deadline - 1.0:
        restart_count += 1
        if restart_count % 2 == 1:
            cand = _block_perturb(incumbent, rng)
        else:
            cand = _sparse_seed(8192, rng)
        cand = _hard_threshold(cand)
        cand = _rescale(cand)
        if cand.sum() <= 0:
            continue
        cand, r = _homotopy(cand, deadline)
        cand = _hard_threshold(cand)
        cand = _rescale(cand)
        r = R_of(cand)
        if r > inc_r:
            incumbent = cand.copy()
            inc_r = r
        if r > best_r:
            best, best_r = cand.copy(), r
            if time.process_time() < deadline - 3.0 and best.size != 65536:
                big = _prolongate(best, 65536)
                big = _rescale(big)
                big = _lbfgs_log(big, maxiter=300, deadline=deadline)
                big = _window_polish_peak(big, deadline, 0.10, 8, maxiter=300)
                big = _rescale(big)
                rb = R_of(big)
                if rb > best_r:
                    best, best_r = big.copy(), rb

    # Final polish on best with exact objective
    if time.process_time() < deadline - 0.5:
        c = _lbfgs_log(best, maxiter=800, deadline=deadline)
        r = R_of(c)
        if r > best_r:
            best, best_r = c, r
        if time.process_time() < deadline - 0.5:
            c = _window_polish_peak(best, deadline, 0.10, 8, maxiter=400)
            r = R_of(c)
            if r > best_r:
                best, best_r = c, r

    print(f"restarts={restart_count} best={best_r:.6f}")

    best = _rescale(best)
    if start_arr is not None:
        alt = _rescale(start_arr)
        if best_r <= R_of(start_arr):
            return {"best": alt, "alternative": best}
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _smooth(h, k):
    if k <= 1:
        return h
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0.0, None)


def _perturb(h, rng, scale):
    h2 = h.copy()
    nz = np.flatnonzero(h2 > 0)
    if nz.size == 0:
        return h2
    factors = np.exp(rng.normal(0.0, scale, nz.size))
    h2[nz] *= factors
    return h2


def _smoothstep_seed(N):
    x = np.linspace(0, 1, N)
    return (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(20240607)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = _smoothstep_seed(256)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    # Alternative: finer-resolution prolongation + polish, then coarsen back.
    alt = None
    alt_r = -1.0
    N_up = min(cur.size * 2, 500000)
    if time.process_time() < deadline - 20.0:
        up = _rescale(_prolongate(cur, N_up))
        up = _lbfgs_log(up, maxiter=300, deadline=deadline)
        up_r = R_of(up)
        if up_r > best_r:
            alt = _rescale(_coarsen(up, cur.size))
            alt_r = R_of(alt)
            if alt_r > best_r:
                best, best_r = alt.copy(), alt_r
        print("alt refine R = %.6f (N_up=%d)" % (up_r, N_up))

    # Coarsen-and-reprolong path
    if cur.size >= 16384 and time.process_time() < deadline - 15.0:
        c = _rescale(_coarsen(cur, 16384))
        c = _lbfgs_log(c, maxiter=400, deadline=deadline)
        c = _rescale(_prolongate(c, cur.size))
        c = _lbfgs_log(c, maxiter=400, deadline=deadline)
        rc = R_of(c)
        if rc > best_r:
            best, best_r = c.copy(), rc
        print("coarsen-reprolong R = %.6f" % rc)

    # Main loop: alternate full polish and peak-window polish.
    # Key change: window polish is done FIRST each round (cheap, local),
    # then a longer full polish.  Also: instead of expensive random
    # perturbations, we run a "defect-driven" peak sharpening — we shrink
    # the support window around the max of f*f and re-polish fully, which
    # tends to lift the peak relative to the L2 mass (the binding term).
    last_r = cur_r
    stall = 0
    while time.process_time() < deadline - 1.0:
        # window polish first
        for frac, extra in ((0.05, 4), (0.15, 10), (0.30, 20)):
            if time.process_time() >= deadline - 1.0:
                break
            cand = _window_polish_peak(cur, deadline, frac, extra, maxiter=500)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

        # full polish
        cand = _lbfgs_log(cur, maxiter=1200, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

        if cur_r <= last_r + 1e-9:
            stall += 1
            # Defect-driven sharpening: nudge the top region of f*f upward
            # by locally scaling heights around the peak of f.
            if stall >= 2 and time.process_time() < deadline - 3.0:
                n = cur.size
                lo, hi = _peak_region(cur, tol=0.95)
                # widen a bit and amplify
                pad = max(4, (hi - lo) // 2)
                lo2 = max(0, lo - pad); hi2 = min(n - 1, hi + pad)
                seed = cur.copy()
                seed[lo2:hi2 + 1] *= 1.0 + 0.01 * (1 + stall)
                seed = _rescale(seed)
                seed = _lbfgs_log(seed, maxiter=800, deadline=deadline)
                rs = R_of(seed)
                if rs > cur_r:
                    cur, cur_r = seed, rs
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                    stall = 0
                else:
                    # fall back to a small perturbation of best
                    scale = 0.01 * stall
                    perturbed = _perturb(best, rng, min(scale, 0.1))
                    cp = _lbfgs_log(_rescale(perturbed), maxiter=800,
                                    deadline=deadline)
                    rp = R_of(cp)
                    if rp > cur_r:
                        cur, cur_r = cp, rp
                        if cur_r > best_r:
                            best, best_r = cur.copy(), cur_r
                        stall = 0
                    else:
                        cur = best.copy(); cur_r = best_r
        else:
            stall = 0
        last_r = cur_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    if np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    if L.size == 0:
        return -1.0
    m = L.max()
    if m <= 0:
        return -1.0
    Lp = np.empty(L.size + 2, dtype=float)
    Lp[0] = 0.0
    Lp[1:-1] = L
    Lp[-1] = 0.0
    a = Lp[:-1]
    b = Lp[1:]
    sq = np.sum(a * a + a * b + b * b) / 3.0
    return sq / (s * s * m)


def _prolongate_mass(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    x_old = np.arange(n + 1) / n
    x_new = np.arange(N + 1) / N
    cm = np.interp(x_new, x_old, c)
    out = np.diff(cm) * (N / n)
    return np.maximum(out, 0.0)


def _rescale(h):
    m = h.max()
    if m > 0:
        return h / m
    return h


def _knots(h):
    L = np.convolve(h, h)
    Lp = np.empty(L.size + 2, dtype=float)
    Lp[0] = 0.0
    Lp[1:-1] = L
    Lp[-1] = 0.0
    return Lp


def _num_and_dq(h):
    Lp = _knots(h)
    a = Lp[:-1]
    b = Lp[1:]
    sq = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lp)
    dq[:-1] += (2.0 * a + b) / 3.0
    dq[1:] += (a + 2.0 * b) / 3.0
    return sq, dq, Lp


def _backprop(h, dL):
    n = h.size
    if n > 1500:
        g = 2.0 * fftconvolve(dL, h[::-1], mode='full')
        return g[n - 1:2 * n - 1]
    else:
        g = np.zeros(n)
        for j in range(dL.size):
            if dL[j] == 0.0:
                continue
            i_lo = max(0, j - (n - 1))
            i_hi = min(n - 1, j)
            for i in range(i_lo, i_hi + 1):
                k = j - i
                g[i] += dL[j] * h[k]
                g[k] += dL[j] * h[i]
        return g


def _fun_grad(x):
    h = np.exp(x)
    s = h.sum()
    if s <= 0:
        return 1e10, np.zeros_like(x)
    sq, dq, Lp = _num_and_dq(h)
    m = Lp.max()
    if m <= 0:
        return 1e10, np.zeros_like(x)
    R = sq / (s * s * m)
    gsq = _backprop(h, dq[1:-1])
    idx = np.argmax(Lp)
    dmask = np.zeros_like(Lp)
    dmask[idx] = 1.0
    gm = _backprop(h, dmask[1:-1])
    dR = gsq / (s * s * m) - R * (2.0 / s + gm / m)
    gx = dR * h
    return -R, -gx


def _fun_grad_sm(x, beta):
    h = np.exp(x)
    s = h.sum()
    if s <= 0:
        return 1e10, np.zeros_like(x)
    sq, dq, Lp = _num_and_dq(h)
    L = Lp[1:-1]
    m = L.max()
    if m <= 0:
        return 1e10, np.zeros_like(x)
    w = np.exp(beta * (L - m))
    W = w.sum()
    sm = m + np.log(W) / beta
    dsm_dL = w / W
    dsm = np.zeros_like(Lp)
    dsm[1:-1] = dsm_dL
    R = sq / (s * s * sm)
    gsq = _backprop(h, dq[1:-1])
    gsm = _backprop(h, dsm[1:-1])
    dR = gsq / (s * s * sm) - R * (2.0 / s + gsm / sm)
    gx = dR * h
    return -R, -gx


class _Timeout(Exception):
    pass


def _lbfgs_log(h0, maxiter, deadline):
    h0 = np.asarray(h0, dtype=float)
    if np.any(h0 <= 0):
        h0 = np.maximum(h0, 1e-12)
    best_h = h0.copy()
    best_R = _R_of(h0)
    x0 = np.log(h0)

    def f(x):
        if time.process_time() > deadline - 0.5:
            raise _Timeout()
        return _fun_grad(x)

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-14, 'gtol': 1e-12})
        h = np.exp(res.x)
        R = _R_of(h)
        if R > best_R:
            best_R = R
            best_h = h
    except _Timeout:
        pass
    except Exception:
        pass
    return best_h, best_R


def _lbfgs_sm(h0, beta, maxiter, deadline):
    h0 = np.asarray(h0, dtype=float)
    if np.any(h0 <= 0):
        h0 = np.maximum(h0, 1e-12)
    best_h = h0.copy()
    best_R = _R_of(h0)
    x0 = np.log(h0)

    def f(x):
        if time.process_time() > deadline - 0.5:
            raise _Timeout()
        return _fun_grad_sm(x, beta)

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-14, 'gtol': 1e-12})
        h = np.exp(res.x)
        R = _R_of(h)
        if R > best_R:
            best_R = R
            best_h = h
    except _Timeout:
        pass
    except Exception:
        pass
    return best_h, best_R


def _active_set_log(h, maxiter, deadline, tol=1e-10):
    """Log-LBFGS restricted to entries above tol*max; others frozen at tiny."""
    h = np.asarray(h, dtype=float)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return h, _R_of(h)
    active = h > tol * mx
    if active.sum() < 4:
        return h, _R_of(h)
    idx = np.where(active)[0]
    sub = h[idx].copy()
    best_h = h.copy()
    best_R = _R_of(h)
    x0 = np.log(sub)

    def f(x):
        if time.process_time() > deadline - 0.5:
            raise _Timeout()
        hh = h.copy()
        hh[idx] = np.exp(x)
        return _fun_grad(np.log(np.maximum(hh, 1e-300)))

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-14, 'gtol': 1e-12})
        hh = h.copy()
        hh[idx] = np.exp(res.x)
        R = _R_of(hh)
        if R > best_R:
            best_R = R
            best_h = hh
    except _Timeout:
        pass
    except Exception:
        pass
    return best_h, best_R


def _window_polish_peak(h, frac, extra, deadline, maxiter=200):
    h = np.asarray(h, dtype=float)
    n = h.size
    if n < 8:
        return h, _R_of(h)
    L = np.convolve(h, h)
    peak = int(np.argmax(L))
    center = peak / 2.0
    half = max(2, int(frac * n))
    lo = max(0, int(center) - half)
    hi = min(n, int(center) + half + extra)
    if hi - lo < 4:
        return h, _R_of(h)
    best_h = h.copy()
    best_R = _R_of(h)
    sub = h[lo:hi].copy()
    if np.any(sub <= 0):
        sub = np.maximum(sub, 1e-12)
    x0 = np.log(sub)

    def f(x):
        if time.process_time() > deadline - 0.5:
            raise _Timeout()
        hh = h.copy()
        hh[lo:hi] = np.exp(x)
        s = hh.sum()
        sq, dq, Lp = _num_and_dq(hh)
        m = Lp.max()
        if m <= 0 or s <= 0:
            return 1e10, np.zeros_like(x)
        R = sq / (s * s * m)
        gsq = _backprop(hh, dq[1:-1])
        idx = np.argmax(Lp)
        dmask = np.zeros_like(Lp)
        dmask[idx] = 1.0
        gm = _backprop(hh, dmask[1:-1])
        dR = gsq / (s * s * m) - R * (2.0 / s + gm / m)
        gx = dR * hh
        return -R, -gx[lo:hi]

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-14, 'gtol': 1e-12})
        hh = h.copy()
        hh[lo:hi] = np.exp(res.x)
        R = _R_of(hh)
        if R > best_R:
            best_R = R
            best_h = hh
    except _Timeout:
        pass
    except Exception:
        pass
    return best_h, best_R


def _prune(h, tol=1e-12):
    h = np.asarray(h, dtype=float)
    mx = h.max()
    if mx <= 0:
        return h
    h = h.copy()
    h[h < tol * mx] = 0.0
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(64)
    else:
        h = np.ones(64)
    h = _rescale(np.maximum(h, 0))

    best_h = h.copy()
    best_R = _R_of(h)
    print("start R=%.6f N=%d" % (best_R, h.size))

    # Prolongate to N=8192 by cumulative mass.
    if h.size < 8192:
        h8 = _prolongate_mass(h, 8192)
        h8 = _rescale(h8)
        R8 = _R_of(h8)
        print("prolongated to N=8192 R=%.6f" % R8)
        if R8 > best_R:
            best_R, best_h = R8, h8.copy()
    else:
        h8 = h.copy()

    betas = (32, 128, 512, 1024, 2048)
    polish_fracs = ((0.30, 16), (0.15, 8), (0.07, 4), (0.03, 2))

    cur_h = h8.copy()
    cur_R = _R_of(cur_h)

    # High-beta homotopy with active-set pruning.
    for beta in betas:
        if time.process_time() > deadline - 4.0:
            break
        h2, R2 = _lbfgs_sm(cur_h, beta, 250, deadline)
        print("beta=%d R=%.6f (cur %.6f)" % (beta, R2, cur_R))
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        # Prune and re-run exact log-LBFGS on active set.
        if time.process_time() < deadline - 3.0:
            hp = _prune(cur_h, 1e-12)
            h3, R3 = _active_set_log(hp, 200, deadline, tol=1e-10)
            print("  prune+exact R=%.6f" % R3)
            if R3 > cur_R:
                cur_h, cur_R = h3, R3
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()

    # Peak-window exact polishes.
    for frac, extra in polish_fracs:
        if time.process_time() > deadline - 3.0:
            break
        h2, R2 = _window_polish_peak(cur_h, frac, extra, deadline, maxiter=300)
        print("polish frac=%.2f R=%.6f" % (frac, R2))
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()

    # Alternate high-beta and exact polish until deadline.
    alt_betas = (2048, 1024, 512, 256)
    ai = 0
    while time.process_time() < deadline - 3.0:
        beta = alt_betas[ai % len(alt_betas)]
        ai += 1
        h2, R2 = _lbfgs_sm(cur_h, beta, 200, deadline)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if time.process_time() > deadline - 3.0:
            break
        h2, R2 = _window_polish_peak(cur_h, 0.15, 8, deadline, maxiter=250)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()
        print("  alt beta=%d R=%.6f best=%.6f" % (beta, cur_R, best_R))

    print("final R=%.6f N=%d" % (best_R, best_h.size))

    if start is not None:
        s = np.asarray(start, dtype=float)
        sR = _R_of(s)
        if sR >= best_R:
            return {"best": s, "alternative": best_h}
    return {"best": best_h, "alternative": best_h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _smooth(h, k):
    if k <= 1:
        return h
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0.0, None)


def _perturb(h, rng, scale):
    h2 = h.copy()
    nz = np.flatnonzero(h2 > 0)
    if nz.size == 0:
        return h2
    factors = np.exp(rng.normal(0.0, scale, nz.size))
    h2[nz] *= factors
    return h2


def _smoothstep_seed(N):
    x = np.linspace(0, 1, N)
    return (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(20240607)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = _smoothstep_seed(256)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    # ---- Primary new idea: refine on a finer grid, then map back and
    # accept only if the mapped-back version beats the start. ----
    alt_returned = None

    if time.process_time() < deadline - 25.0:
        N_up = min(cur.size * 2, 500000)
        up = _rescale(_prolongate(cur, N_up))
        up = _lbfgs_log(up, maxiter=400, deadline=deadline - 20.0)
        # polish peak window on the fine grid
        up2 = _window_polish_peak(up, deadline - 18.0, 0.15, 20, maxiter=300)
        if R_of(up2) > R_of(up):
            up = up2
        up_r = R_of(up)
        print("alt refine fine R = %.6f (N_up=%d)" % (up_r, N_up))
        # Map back to original size
        back = _rescale(_coarsen(up, cur.size))
        back_r = R_of(back)
        if back_r > best_r:
            best, best_r = back.copy(), back_r
            cur, cur_r = back.copy(), back_r
        elif up_r > best_r:
            # keep fine version directly if it scores better at fine N
            best, best_r = up.copy(), up_r
            cur, cur_r = up.copy(), up_r
        else:
            # alternative candidate: fine-grid result (genuinely different)
            alt_returned = up.copy()

    # Coarsen-and-reprolong
    if cur.size >= 16384 and time.process_time() < deadline - 15.0:
        c = _rescale(_coarsen(cur, 16384))
        c = _lbfgs_log(c, maxiter=400, deadline=deadline)
        c = _rescale(_prolongate(c, cur.size))
        c = _lbfgs_log(c, maxiter=400, deadline=deadline)
        rc = R_of(c)
        if rc > best_r:
            best, best_r = c.copy(), rc
            cur, cur_r = c.copy(), rc
        print("coarsen-reprolong R = %.6f" % rc)

    # Smoothing continuation
    for beta in (4, 16, 64):
        if time.process_time() >= deadline - 4.0:
            break
        c2 = _lbfgs_sm(cur, beta, maxiter=150, deadline=deadline)
        r2 = R_of(c2)
        if r2 > cur_r:
            cur, cur_r = c2, r2
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        print("  beta=%d R=%.6f" % (beta, cur_r))

    # Main loop
    restart_tries = 0
    no_improve = 0
    last_r = cur_r
    while time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(cur, maxiter=1200, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 1.0:
            break

        for frac, extra in ((0.05, 4), (0.15, 10), (0.30, 20)):
            if time.process_time() >= deadline - 1.0:
                break
            cand = _window_polish_peak(cur, deadline, frac, extra, maxiter=500)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        if cur_r <= last_r + 1e-9:
            no_improve += 1
            if no_improve >= 2 and time.process_time() < deadline - 3.0:
                k = 3 if restart_tries % 2 == 0 else 5
                seed = _rescale(_smooth(cur, k))
                seed = _lbfgs_log(seed, maxiter=800, deadline=deadline)
                rs = R_of(seed)
                if rs > cur_r:
                    cur, cur_r = seed, rs
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                    no_improve = 0
                else:
                    scale = 0.02 * (1 + restart_tries)
                    perturbed = _perturb(best, rng, min(scale, 0.2))
                    cand_p = _lbfgs_log(_rescale(perturbed), maxiter=1000,
                                        deadline=deadline)
                    rp = R_of(cand_p)
                    if rp > cur_r:
                        cur, cur_r = cand_p, rp
                        if cur_r > best_r:
                            best, best_r = cur.copy(), cur_r
                        no_improve = 0
                    else:
                        cur = best.copy(); cur_r = best_r
                restart_tries += 1
        else:
            no_improve = 0
        last_r = cur_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        out = {"best": best}
        if alt_returned is not None and alt_returned.size != best.size:
            out["alternative"] = alt_returned
        else:
            out["alternative"] = start_arr
        return out
    return best

