    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _support_trim(h, eps=1e-9):
    """Crop tiny-support tails to shrink N and speed up later polishing."""
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    thr = eps * h.max()
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return h
    return h[idx[0]:idx[-1] + 1].copy()


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    # ---- Prolongate to N=65536 ----
    N_big = 65536
    h = _prolongate(start_arr, N_big)
    h = _rescale(h)
    cur_r = R_of(h)
    print("prolong R=%.6f N=%d" % (cur_r, h.size))

    # ---- Descending-beta smooth-max continuation ----
    for beta in (1500.0, 800.0, 400.0, 200.0):
        if time.process_time() >= hard_end - 0.5:
            break
        c = _lbfgs_sm(h, beta, maxiter=200, deadline=hard_end)
        rc = R_of(c)
        if rc >= cur_r:
            h, cur_r = c, rc
        print("beta=%.0f R=%.6f" % (beta, cur_r))

    # ---- Exact-objective log L-BFGS ----
    if time.process_time() < hard_end - 0.5:
        c = _lbfgs_log(h, maxiter=600, deadline=hard_end)
        rc = R_of(c)
        if rc >= cur_r:
            h, cur_r = c, rc
        print("exact R=%.6f" % cur_r)

    # ---- Peak-window exact polish ----
    for frac, extra in ((0.05, 8), (0.10, 12), (0.20, 20)):
        if time.process_time() >= hard_end - 0.5:
            break
        c = _window_polish_peak(h, hard_end, frac, extra, maxiter=400, beta=None)
        rc = R_of(c)
        if rc >= cur_r:
            h, cur_r = c, rc
        print("win frac=%.2f R=%.6f" % (frac, cur_r))

    # ---- NEW: support-trimmed re-prolongation cycle ----
    # Trim tails and re-expand on a smaller grid, then re-polish. This lets the
    # optimiser re-allocate resolution to the active support region.
    if time.process_time() < hard_end - 2.0:
        ht = _support_trim(h, eps=1e-6)
        if ht.size < h.size and ht.size > 100:
            # shrink to a compact grid, then grow back with fresh resolution
            N_trim = min(65536, max(ht.size, int(ht.size * 1.2)))
            h2 = _prolongate(ht, N_trim)
            h2 = _rescale(h2)
            r2 = R_of(h2)
            if r2 >= cur_r - 0.001:
                c = _lbfgs_sm(h2, 400.0, maxiter=200, deadline=hard_end)
                rc = R_of(c)
                if rc > cur_r:
                    h, cur_r = c, rc
                    print("reprolong R=%.6f N=%d" % (cur_r, h.size))

    # ---- Alternate full exact polish and peak-window polish ----
    try:
        while time.process_time() < hard_end - 1.0:
            c = _lbfgs_log(h, maxiter=400, deadline=hard_end)
            rc = R_of(c)
            if rc >= cur_r:
                h, cur_r = c, rc
            if time.process_time() >= hard_end - 0.5:
                break
            for frac, extra in ((0.20, 20), (0.10, 12), (0.05, 8)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, extra,
                                        maxiter=300, beta=None)
                rc = R_of(c)
                if rc >= cur_r:
                    h, cur_r = c, rc
            if time.process_time() >= hard_end - 1.0:
                break
    except Exception:
        pass

    print("final R=%.6f N=%d" % (cur_r, h.size))

    if cur_r > best_r:
        return {"best": h, "alternative": best}
    return {"best": best, "alternative": h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _smoothstep_seed(N):
    x = np.linspace(0, 1, N)
    return (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)


def _multiscale_perturb(h, rng, nblocks_lo=8, nblocks_hi=24, sigma=0.15):
    n = h.size
    k = int(rng.integers(nblocks_lo, nblocks_hi + 1))
    widths = np.exp(rng.uniform(np.log(2.0), np.log(max(3.0, n / 4.0)), k))
    widths = np.maximum(2, widths.astype(int))
    h2 = h.copy()
    for w in widths:
        w = min(w, n)
        start = int(rng.integers(0, max(1, n - w + 1)))
        seg = slice(start, start + w)
        fac = np.exp(rng.normal(0.0, sigma))
        h2[seg] = h2[seg] * fac
    ker = np.array([0.25, 0.5, 0.25])
    h2 = np.convolve(h2, ker, mode='same')
    return np.clip(h2, 0.0, None)


def _fourier_perturb(h, rng, nmodes=6, amp=0.1):
    """Smooth low-frequency multiplicative perturbation."""
    n = h.size
    x = np.linspace(0, np.pi, n)
    logh = np.log(np.clip(h, 1e-12, None))
    pert = np.zeros(n)
    for _ in range(nmodes):
        k = int(rng.integers(1, 12))
        phase = rng.uniform(0, 2 * np.pi)
        a = rng.normal(0, amp)
        pert += a * np.sin(k * x + phase)
    h2 = logh + pert
    return np.clip(np.exp(h2), 0.0, None)


def _coarse_cycle(h_coarse, deadline, rng, n_perts=20, maxiter=300):
    best = h_coarse.copy()
    best_r = R_of(best)
    for i in range(n_perts):
        if time.process_time() >= deadline - 0.5:
            break
        if i % 2 == 0:
            cand = _multiscale_perturb(h_coarse, rng)
        else:
            cand = _fourier_perturb(h_coarse, rng)
        cand = _rescale(cand)
        cand = _lbfgs_log(cand, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r
    return best, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(20240607 + int(t0 * 1000) % 100000)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = _smoothstep_seed(256)
        best_r = R_of(best)

    h0 = _rescale(best.copy())
    h0_r = R_of(h0)
    if h0_r > best_r:
        best, best_r = h0.copy(), h0_r
    print("start R = %.6f, N = %d" % (best_r, best.size))

    N_big = best.size
    N_coarse = min(1024, max(64, N_big // 4))

    # Coarse-grid escape attempts combined with fine polishing
    n_cycles = 0
    while time.process_time() < deadline - 6.0 and n_cycles < 8:
        h_coarse = _coarsen(best, N_coarse)
        h_coarse = _rescale(h_coarse)
        rc0 = R_of(h_coarse)
        print("cycle %d coarsen R=%.6f" % (n_cycles, rc0))

        coarse_cands = []
        n_perts = 12
        for i in range(n_perts):
            if time.process_time() >= deadline - 5.0:
                break
            if i % 2 == 0:
                cand = _multiscale_perturb(h_coarse, rng)
            else:
                cand = _fourier_perturb(h_coarse, rng)
            cand = _rescale(cand)
            cand = _lbfgs_log(cand, maxiter=250, deadline=deadline)
            r = R_of(cand)
            coarse_cands.append((r, cand))
        coarse_cands.sort(key=lambda t: -t[0])
        top = coarse_cands[:2]
        if not top:
            break
        print("cycle %d best coarse R=%.6f" % (n_cycles, top[0][0]))

        for ci, (rc, hc) in enumerate(top):
            if time.process_time() >= deadline - 3.0:
                break
            hb = _prolongate(hc, N_big)
            hb = _rescale(hb)
            hb = _lbfgs_log(hb, maxiter=500, deadline=deadline)
            rb = R_of(hb)
            for frac in (0.10, 0.04, 0.015):
                if time.process_time() >= deadline - 1.5:
                    break
                cand = _window_polish_peak(hb, deadline, frac, 8, maxiter=400)
                r = R_of(cand)
                if r > rb:
                    hb, rb = cand, r
            if time.process_time() < deadline - 1.0:
                cand = _lbfgs_log(hb, maxiter=400, deadline=deadline)
                r = R_of(cand)
                if r > rb:
                    hb, rb = cand, r
            print("cycle %d cand %d R=%.6f" % (n_cycles, ci, rb))
            if rb > best_r:
                best, best_r = hb.copy(), rb
                print("  new best R=%.6f" % best_r)
        n_cycles += 1

    # Final polish
    if time.process_time() < deadline - 0.5:
        cand = _lbfgs_log(best, maxiter=400, deadline=deadline)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None and start_arr.size == best.size:
        return {"best": best, "alternative": start_arr}
    return best

