def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_smooth(h, eps):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = Lf.max()
    band = Lf > (m - eps * m)
    w = np.zeros_like(Lf)
    w[band] = np.exp((Lf[band] - m) / (eps * m + 1e-30))
    Z = w.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = w / Z
    softmax = np.dot(w, Lf)
    if softmax <= 0:
        return _fun_grad(h)
    gLf = -dq / num + w / softmax
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(softmax)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, eps=0.0, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif eps > 0:
        fg = (lambda hh: _fun_grad_smooth(hh, eps))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, eps=0.0, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif eps > 0:
        fg = (lambda hh: _fun_grad_smooth(hh, eps))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, eps=0.0, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline,
                        eps=eps, beta=beta)


def _revive_right_zeros(h, frac_lo=0.55, win=256, scale=1e-3):
    """Revive exact zeros whose index lies in [frac_lo*N, N) to
    scale * local mean of positive entries (256-step window)."""
    h = h.copy()
    n = h.size
    lo_cut = int(frac_lo * n)
    pos = h > 0
    if not np.any(pos):
        return h
    hp = np.where(pos, h, 0.0)
    cp = np.concatenate(([0.0], np.cumsum(hp)))
    cn = np.concatenate(([0.0], np.cumsum(pos.astype(float))))
    zeros = np.flatnonzero(h[lo_cut:] <= 0) + lo_cut
    for i in zeros:
        lo = max(0, i - win // 2)
        hi = min(n, i + win // 2 + 1)
        s = cp[hi] - cp[lo]
        c = cn[hi] - cn[lo]
        if c > 0:
            h[i] = scale * (s / c)
        else:
            h[i] = scale * h.max() * 1e-3
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # EXPERIMENT: revive zeros only in the RIGHT window [0.55N, N),
    # leaving the left window frozen. Then bounded log-space L-BFGS,
    # beta-softmax sweep with peak polishes, final sharp polish,
    # and remaining budget alternating full sharp + peak polish.

    # Step 1: revive right-window zeros.
    h_rev = _revive_right_zeros(best, frac_lo=0.55, win=256, scale=1e-3)
    h_rev = _rescale(h_rev)
    r_rev = R_of(h_rev)
    print("revived R=%.7f (zeros %.1f%%)" % (r_rev, 100.0 * np.mean(h_rev <= 0)))

    cur = h_rev
    if r_rev > bestR + 1e-12:
        best, bestR = h_rev, r_rev

    # Step 2: bounded log-space L-BFGS on all entries, 800 iters.
    if time.process_time() < deadline - 6.0:
        h = _lbfgs_log(cur, 800, deadline)
        r = R_of(h)
        print("log-lbfgs R=%.7f" % r)
        if r > bestR + 1e-12:
            best, bestR = h, r
            cur = h
        else:
            cur = h if r > bestR - 0.003 else cur

    # Step 3: softmax (beta) sweep alternating with peak polishes.
    for beta in (1e3, 1e4, 5e4, 2e5):
        if time.process_time() >= deadline - 4.0:
            break
        h = _lbfgs_log(cur, 250, deadline, beta=beta)
        r = R_of(h)
        print("beta=%.0e R=%.7f" % (beta, r))
        if r > bestR + 1e-12:
            best, bestR = h, r
        cur = h if r > bestR - 0.003 else cur
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 3.0:
                break
            hp = _window_polish_peak(cur, deadline, frac, 32,
                                     maxiter=200, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-12:
                best, bestR = hp, rp
                print("  peak frac=%.2f R=%.7f" % (frac, rp))
            cur = hp if rp > bestR - 0.003 else cur

    # Step 4: final sharp log-L-BFGS 500.
    if time.process_time() < deadline - 2.0:
        h = _lbfgs_log(best, 500, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("final sharp R=%.7f" % bestR)

    # Step 5: spend remaining budget alternating full sharp + peak polish.
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h = _lbfgs_log(best, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("  alt full #%d R=%.7f" % (it, bestR))
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 1.5:
                break
            hp = _window_polish_peak(best, deadline, frac, 32, maxiter=200)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("  alt peak #%d frac=%.2f R=%.7f" % (it, frac, rp))

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
