def _coarsen(h, k):
    n = h.size
    if n % k != 0:
        return None
    return h.reshape(n // k, k).sum(axis=1)


def _sharpen(h, deadline, rcur):
    cand = _lbfgs_log(h, maxiter=600, deadline=deadline)
    r = R_of(cand)
    if r > rcur:
        return cand, r
    return h, rcur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
    else:
        best, best_r = _fresh(deadline)
        start_r = best_r

    # ---- Step 1: coarsen by block-summing 8 adjacent heights ----
    coarse = None
    coarse_r = -1.0
    if best.size % 8 == 0:
        hc = _coarsen(best, 8)
        if hc is not None:
            rc = R_of(hc)
            if abs(rc - best_r) < 1e-10:
                coarse = hc
                coarse_r = rc
                print("coarsened to N=%d: R=%.9f (start %.9f)" % (hc.size, rc, best_r))
            else:
                print("coarsen mismatch %.9f vs %.9f" % (rc, best_r))

    # ---- Step 2: optimise hard on coarse grid (about 30% of remaining budget) ----
    if coarse is not None:
        coarse_deadline = min(deadline, time.process_time() + 0.30 * (deadline - time.process_time()))
        cc, cr = _sharpen(coarse, coarse_deadline, coarse_r)
        cc, cr = _homotopy(cc, (64, 256, 1024, 4096), 250, coarse_deadline)
        cc, cr = _polish(cc, coarse_deadline, cr,
                         fracs=(0.30, 0.15, 0.07, 0.03, 0.015), maxiter=400)
        if cr > coarse_r:
            coarse, coarse_r = cc, cr
        print("coarse optimised: R=%.6f" % coarse_r)

        # ---- Step 3: re-detail back to N=131072 ----
        fine = np.repeat(coarse, 8) / 8.0
        fine_r = R_of(fine)
        print("re-detailed to N=%d: R=%.6f" % (fine.size, fine_r))
        if fine_r > best_r:
            best, best_r = fine, fine_r

    # ---- Continue alternating on the fine grid ----
    cand = _lbfgs_log(best, maxiter=400, deadline=deadline)
    r = R_of(cand)
    if r > best_r:
        best, best_r = cand, r
    print("after log polish R=%.6f" % best_r)

    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        cand, r = _homotopy(best, (400, 1024, 2048, 4096, 8000), 250, deadline)
        if r > best_r:
            best, best_r = cand, r
        cand = _lbfgs_log(best, maxiter=400, deadline=deadline)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r
        cand, r = _polish(best, deadline, best_r,
                          fracs=(0.15, 0.07, 0.03, 0.015), maxiter=400)
        if r > best_r:
            best, best_r = cand, r
        print("  alt#%d R=%.6f" % (it, best_r))

    print("best R=%.6f (start %.6f)" % (best_r, start_r))
    best = _rescale(best)

    if start_arr is not None and start_r >= best_r:
        return {"best": start_arr, "alternative": best}
    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

