    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 2048:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, mode='log', beta=None, free=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    cb = _make_cb(deadline - 0.2)

    if mode == 'block':
        active = np.asarray(free, dtype=int)
        if active.size == 0:
            return h0
        x0 = h[active].copy()

        def f(x):
            hh = h.copy()
            hh[active] = np.clip(x, 0.0, None)
            val, g = _fun_grad(hh)
            return val, g[active]

        try:
            res = minimize(f, x0, jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * active.size,
                           callback=cb,
                           options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                    'ftol': 1e-20, 'gtol': 1e-16})
        except Exception:
            return h0
        if res is None:
            return h0
        h2 = h.copy()
        h2[active] = np.clip(res.x, 0.0, None)
        return _rescale(h2)

    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    if mode == 'log':
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = _fun_grad(hh)
            return val, g[active] * hh[active]
    else:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = _fun_grad_sm(hh, beta)
            return val, g[active] * hh[active]

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _homotopy(seed, betas, maxiter, deadline):
    cur = _rescale(seed.copy())
    cur_r = R_of(cur)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs(cur, maxiter=maxiter, deadline=deadline, mode='sm', beta=beta)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _polish(h, deadline, rcur, fracs, maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac) + 1)
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs(h, maxiter=maxiter, deadline=deadline, mode='block', free=free)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _coarsen(h, k):
    n = h.size
    if n % k != 0:
        return None
    return h.reshape(n // k, k).sum(axis=1)


def _upsample(h, k):
    return np.repeat(h, k) / float(k)


def _add_noise(h, rng, scale):
    nz = np.flatnonzero(h > 1e-13 * h.max())
    h2 = h.copy()
    if nz.size == 0:
        return h2
    factor = np.exp(rng.normal(0.0, scale, size=nz.size))
    h2[nz] *= factor
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    rng = np.random.default_rng(12345)

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
    else:
        N0 = 64
        x = np.linspace(0, 1, N0)
        best = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        best_r = R_of(best)
        start_r = best_r
        N = N0
        while N < 4096 and time.process_time() < deadline - 8.0:
            best = _lbfgs(best, maxiter=300, deadline=deadline, mode='log')
            best_r = R_of(best)
            N = min(N * 2, 4096)
            best = _rescale(_prolong(best, N))
            best_r = R_of(best)

    Ntarget = 65536
    if best.size < Ntarget:
        best = _rescale(_prolong(best, Ntarget))
        best_r = R_of(best)
        print("prolonged start to %d: R=%.6f" % (Ntarget, best_r))

    alt_best = None
    alt_r = -1.0

    # ---- multi-scale: coarsen to 1/8, optimize hard, re-detail ----
    if best.size % 8 == 0:
        hc = _coarsen(best, 8)
        if hc is not None:
            cd = min(deadline, time.process_time() + 0.35 * (deadline - time.process_time()))
            cc, cr = _lbfgs(hc, maxiter=800, deadline=cd, mode='log')
            cc, cr = _homotopy(cc, (64, 256, 1024, 4096), 300, cd)
            cc, cr = _polish(cc, cd, cr,
                             fracs=(0.30, 0.15, 0.07, 0.03, 0.015), maxiter=500)
            fine = _upsample(cc, 8)
            fine_r = R_of(fine)
            print("coarse8 R=%.9f -> fine R=%.9f" % (cr, fine_r))
            # quick log polish on the fine
            fine2 = _lbfgs(fine, maxiter=200, deadline=cd, mode='log')
            f2r = R_of(fine2)
            if f2r > fine_r:
                fine, fine_r = fine2, f2r
            if fine_r > best_r:
                best, best_r = fine, fine_r
            else:
                alt_best, alt_r = fine, fine_r

    # ---- main loop: homotopy / log / block polish, with restarts ----
    it = 0
    stall = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        prev_r = best_r

        cand, r = _homotopy(best, (400, 1024, 2048, 4096, 8000, 16000, 32000), 300, deadline)
        if r > best_r:
            best, best_r = cand, r

        cand = _lbfgs(best, maxiter=400, deadline=deadline, mode='log')
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r

        cand, r = _polish(best, deadline, best_r,
                          fracs=(0.30, 0.15, 0.07, 0.03, 0.015, 0.007, 0.003), maxiter=500)
        if r > best_r:
            best, best_r = cand, r

        # perturb + re-optimize (escape local optima)
        if time.process_time() < deadline - 4.0:
            for scale in (0.02, 0.005):
                if time.process_time() >= deadline - 4.0:
                    break
                hnoise = _add_noise(best, rng, scale)
                cn = _lbfgs(hnoise, maxiter=300, deadline=deadline, mode='log')
                rn = R_of(cn)
                if rn > best_r:
                    best, best_r = cn, rn
                    stall = 0

        if best_r - prev_r < 1e-9:
            stall += 1
        else:
            stall = 0

        print("  alt#%d R=%.9f (stall=%d)" % (it, best_r, stall))

    print("best R=%.9f (start %.9f)" % (best_r, start_r))
    best = _rescale(best)

    if start_arr is not None and start_r >= best_r:
        if alt_best is not None and alt_r > best_r:
            return {"best": start_arr, "alternative": alt_best}
        return {"best": start_arr, "alternative": best}
    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 4000:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 4000:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, active_mask=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if active_mask is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.flatnonzero(active_mask)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _refine_line(h, r, deadline, tag, rounds=1000):
    while time.process_time() < deadline - 1.5:
        cand = _lbfgs_log(h, maxiter=300, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        cand, r2 = _polish(h, deadline, r,
                           fracs=(0.40, 0.20, 0.10, 0.05, 0.02), maxiter=500)
        if r2 > r:
            h, r = cand, r2
        cand = _lbfgs_sm(h, 4096, maxiter=300, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        print("  %s R=%.6f" % (tag, r))
    return h, r


def _truncate(h, newn):
    """Resample h to newn steps preserving the cumulative mass shape."""
    return _prolong(h, newn)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    best = None
    best_r = -1.0

    if start_arr is not None:
        base = start_arr
        base_r = start_r
        print("start base R=%.6f N=%d" % (base_r, base.size))

        # NEW IDEA: the previous program climbed the ladder from the start's N.
        # Here we additionally try a *coarsening* first: aggressively truncate
        # to a smaller N, run a full smooth+sharp refinement there (fast, so
        # many iterations fit), then prolong back up. Coarse representations
        # escape plateaus that fine grids get stuck in, and the smooth objective
        # at low N reaches a different basin, which prolongation carries up.
        n0 = base.size
        all_candidates = [(base_r, base.copy())]

        # phase 1: coarsen-and-climb at a few small sizes
        for target in (max(64, n0 // 8), max(128, n0 // 4), max(256, n0 // 2)):
            if time.process_time() >= deadline - 8.0:
                break
            if target >= n0:
                continue
            c = _truncate(base, target)
            c = _rescale(c)
            rc = R_of(c)
            for _ in range(3):
                if time.process_time() >= deadline - 6.0:
                    break
                cc = _lbfgs_sm(c, 512, maxiter=400, deadline=deadline)
                rcc = R_of(cc)
                if rcc > rc:
                    c, rc = cc, rcc
                cc = _lbfgs_log(c, maxiter=400, deadline=deadline)
                rcc = R_of(cc)
                if rcc > rc:
                    c, rc = cc, rcc
                c, rc = _polish(c, deadline, rc,
                                fracs=(0.5, 0.25, 0.12, 0.06), maxiter=400)
            print("  coarse N=%d R=%.6f" % (target, rc))
            # prolong back to full size and refine there
            if time.process_time() < deadline - 5.0:
                up = _rescale(_prolong(c, n0))
                ru = R_of(up)
                up2 = _lbfgs_log(up, maxiter=300, deadline=deadline)
                ru2 = R_of(up2)
                if ru2 > ru:
                    up, ru = up2, ru2
                all_candidates.append((ru, up.copy()))
                print("  coarse->full R=%.6f" % ru)

        # phase 2: original ladder (kept, since it produced the start's gains)
        base = start_arr
        base_r = start_r
        schedule = []
        m = n0
        while m <= 1000000:
            schedule.append(m)
            if m == 1000000:
                break
            m = min(m * 2, 1000000)
        if len(schedule) < 3:
            schedule = sorted(set([n0, min(2 * n0, 1000000),
                                   min(4 * n0, 1000000)]))

        for m in schedule:
            if time.process_time() >= deadline - 3.0:
                break
            if m != base.size:
                base = _rescale(_prolong(base, m))
            base_r = R_of(base)
            for _ in range(2):
                if time.process_time() >= deadline - 2.5:
                    break
                c = _lbfgs_log(base, maxiter=300, deadline=deadline)
                rc = R_of(c)
                if rc > base_r:
