        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    return max(0, idx.min() - 1), min(h.size - 1, idx.max())


def _window_polish(h, deadline, frac, extra, maxiter=300, band=None):
    n = h.size
    lo, hi = _peak_region(h)
    pad = max(extra, int((hi - lo) * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    return _lbfgs_block(h, np.arange(lo, hi + 1), maxiter, deadline, band)


def _band_stats(h, delta):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, 0.0
    B = Lf >= (1.0 - delta) * mx
    nB = int(B.sum())
    if nB == 0:
        return 0, 0.0
    return nB, float(Lf[B].min() / mx)


def _refine_resample(h, factor):
    n = h.size
    n2 = min(int(n * factor), 900000)
    if n2 <= n:
        return h
    xi = np.linspace(0.0, n - 1, n2)
    return _rescale(np.interp(xi, np.arange(n), h))


def _perturb(h, rng, sigma):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    return _rescale(h * np.exp(sigma * rng.standard_normal(h.size)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(20240308)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 16384
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    cur, curR = best.copy(), bestR

    # Alternate band widths and window sizes for the peak plateau.
    band_seq = [0.05, 0.02, 0.08, 0.03, 0.01]
    win_seq = [0.10, 0.25, 0.05, 0.40, 0.15]
    pass_no = 0
    while time.process_time() < deadline - 4.0:
        pass_no += 1
        b = band_seq[pass_no % len(band_seq)]
        w = win_seq[pass_no % len(win_seq)]

        # Band surrogate
        if time.process_time() < deadline - 5.0:
            hb = _lbfgs_log(cur, 200, deadline, band=b)
            rb = R_of(hb)
            nB, ratio = _band_stats(hb, b)
            if rb > curR + 1e-14:
                cur, curR = hb, rb
            print("  pass %d band%.2f R=%.7f |B|=%d r=%.4f" %
                  (pass_no, b, rb, nB, ratio))

        # Window polish on peak
        if time.process_time() < deadline - 4.0:
            hp = _window_polish(cur, deadline, w, 32, maxiter=200)
            rp = R_of(hp)
            if rp > curR + 1e-14:
                cur, curR = hp, rp

        # Exact sharp polish
        if time.process_time() < deadline - 3.0:
            hs = _lbfgs_log(cur, 40, deadline)
            rs = R_of(hs)
            if rs > curR + 1e-14:
                cur, curR = hs, rs

        if curR > bestR + 1e-14:
            best, bestR = cur.copy(), curR
        print("  pass %d R=%.7f" % (pass_no, curR))

        # Perturbed restart
        if pass_no % 3 == 0 and time.process_time() < deadline - 8.0:
            cand = _perturb(best, rng, 0.004)
            hc = _lbfgs_log(cand, 60, deadline, band=0.03)
            rc = R_of(hc)
            if rc > bestR + 1e-14:
                best, bestR = hc.copy(), rc
                cur, curR = hc.copy(), rc

        # Refine resolution once
        if pass_no == 4 and best.size < 200000 and \
                time.process_time() < deadline - 12.0:
            hr = _refine_resample(best, 2.0)
            hrr = _lbfgs_log(hr, 80, deadline, band=0.05)
            rr = R_of(hrr)
            if rr > bestR + 1e-14:
                best, bestR = hrr.copy(), rr
                cur, curR = hrr.copy(), rr
                print("  refined N=%d R=%.7f" % (best.size, bestR))

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 300, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_lav(h, k):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    k = max(1, int(k))
    if k <= 1:
        return _fun_grad(h)
    ker = np.ones(k) / k
    sk = np.convolve(Lf, ker, mode='same')
    m = int(np.argmax(sk))
    sm = sk[m]
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    half = k // 2
    lo = m - half
    hi = lo + k
    if lo < 0:
        lo = 0; hi = k
    if hi > Lf.size:
        hi = Lf.size; lo = hi - k
    gLf[lo:hi] += (1.0 / sm) * (1.0 / k)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_box(h, eta, lam):
    """Two-level (box) surrogate: pull top mass-fraction of knots up to M,
    everything else down to 0, via a soft sigmoid assignment (majorise-then-polish)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad(h)
    # soft 'belongs to plateau' mask, threshold at 0.93*M
    z = eta * (Lf / M - 0.93)
    z = np.clip(z, -60.0, 60.0)
    p = 1.0 / (1.0 + np.exp(-z))
    T = M * p
    r = Lf - T
    n = Lf.size
    scale = M * M * n
    gLf = -dq / num + 2.0 * lam * r / scale
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + lam * np.sum(r * r) / scale
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _share(h, frac):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - frac) * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d share5%%=%.4f" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0, _share(best, 0.05)))

    cur = best.copy()
    curR = bestR

    # Box (two-level) surrogate ladder
    box_params = [(30, 0.05), (60, 0.1), (120, 0.05), (60, 0.3)]
    stage = 0
    while time.process_time() < deadline - 4.0:
        stage += 1
        for (eta, lam) in box_params:
            if time.process_time() >= deadline - 4.0:
                break
            fg = (lambda hh, e=eta, l=lam: _fun_grad_box(hh, e, l))
            hb = _lbfgs_log(cur, 120, deadline, fg=fg)
            hs = _lbfgs_log(hb, 10, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.10, 64, maxiter=150)
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            mx, m, near = _stats(cand)
            sh5 = _share(cand, 0.05)
            sh01 = _share(cand, 0.001)
            if rc > curR + 3e-13:
                cur, curR = cand, rc
                print("  stage %d eta=%d lam=%.2f R=%.7f Lmax=%.6e argmax=%d near=%.4f sh5=%.4f" %
                      (stage, eta, lam, curR, mx, m, sh01, sh5))
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
            else:
                print("  stage %d eta=%d lam=%.2f R=%.7f (no gain) Lmax=%.6e argmax=%d near=%.4f sh5=%.4f" %
                      (stage, eta, lam, rc, mx, m, sh01, sh5))

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 300, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d share5%%=%.4f" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near, _share(best, 0.05)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

