        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = (_fun_grad_beta(hh, beta) if beta > 0 else _fun_grad(hh))
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = (_fun_grad_beta(hh, beta) if beta > 0 else _fun_grad(hh))
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _perturb_peak(h, rng, scale=0.05):
    h = h.copy()
    n = h.size
    lo, hi = _peak_region(h, tol=0.98)
    pad = max(4, int(0.12 * n))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    W = hi - lo + 1
    if W < 4:
        return h
    nmodes = int(rng.integers(1, 4))
    x = np.linspace(0.0, 1.0, W)
    mod = np.ones(W)
    for _ in range(nmodes):
        k = int(rng.integers(1, 5))
        amp = rng.normal(0.0, scale)
        phase = rng.uniform(0, 2 * np.pi)
        mod *= (1.0 + amp * np.sin(2 * np.pi * k * x + phase))
    mod = np.clip(mod, 0.5, 1.5)
    h[lo:hi + 1] *= mod
    return _rescale(h)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.3

    start_arr = None
    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=2000, deadline=hard_end)
        return cur

    cur = best.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal cur, cur_r, best, best_r, alternative, alt_r
        if r > cur_r:
            cur, cur_r = cand, r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    n = cur.size

    # Stage 1: direct gradient polishing of start via L-BFGS with exact max
    # plus extended beta-continuation. This is the reliable baseline.
    h = cur.copy()
    for beta in (2000.0, 1000.0, 400.0, 150.0, 60.0, 20.0, 0.0):
        if time.process_time() >= hard_end - 0.5:
            break
        c = _lbfgs_log(h, maxiter=400, deadline=hard_end, beta=beta)
        if R_of(c) >= R_of(h):
            h = c
    _consider(h, R_of(h))
    print("beta-cont R=%.6f N=%d" % (best_r, best.size))

    # Stage 2: peak-window modulation experiments, then re-polish
    n_seeds = 12
    for seed in range(n_seeds):
        if time.process_time() >= hard_end - 1.0:
            break
        rng_s = np.random.default_rng(5000 + seed)
        h = _perturb_peak(cur, rng_s, scale=0.05)
        for beta in (600.0, 200.0, 60.0, 0.0):
            if time.process_time() >= hard_end - 0.5:
                break
            c = _lbfgs_log(h, maxiter=300, deadline=hard_end, beta=beta)
            if R_of(c) >= R_of(h):
                h = c
        _consider(h, R_of(h))
    print("peak-exp R=%.6f N=%d" % (best_r, best.size))

    # Stage 3: fine local polishing of best (block over full vector)
    try:
        while time.process_time() < hard_end - 1.0:
            h = best.copy()
            for beta in (120.0, 40.0, 10.0, 0.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_log(h, maxiter=500, deadline=hard_end, beta=beta)
                if R_of(c) > R_of(h):
                    h = c
            _consider(h, R_of(h))
            if time.process_time() >= hard_end - 1.0:
                break
        print("polish R=%.6f" % best_r)
    except Exception:
        pass

    if best_r < R_of(start_arr):
        best = start_arr.copy()
        best_r = R_of(best)

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

