    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, mode='sharp', param=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if mode == 'beta':
        fg = (lambda hh: _fun_grad_beta(hh, param))
    elif mode == 'pnorm':
        fg = (lambda hh: _fun_grad_pnorm(hh, param))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, mode='sharp', param=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if mode == 'beta':
        fg = (lambda hh: _fun_grad_beta(hh, param))
    elif mode == 'pnorm':
        fg = (lambda hh: _fun_grad_pnorm(hh, param))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150,
                        mode='sharp', param=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline,
                        mode=mode, param=param)


def _argmax_pos(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    m = int(np.argmax(Lf))
    return m / (Lf.size - 1)


def _bump(n, lo, hi, profile):
    """Return a length-n bump supported on [lo, hi)."""
    b = np.zeros(n)
    if hi <= lo:
        return b
    k = hi - lo
    x = np.linspace(0.0, 1.0, k, endpoint=False)
    if profile == 'const':
        w = np.ones(k)
    elif profile == 'ramp':
        w = x + 1e-3
    elif profile == 'cos':
        w = np.sin(np.pi * x)
    else:
        w = np.ones(k)
    b[lo:hi] = w
    return b


def _soft_threshold_move(h, q, s, profile):
    """Soft-threshold smallest nonzero cells, re-inject s*removed mass
    as a bump over the far region [0.55N, N)."""
    h = np.asarray(h, dtype=float)
    n = h.size
    pos = h[h > 0]
    if pos.size == 0:
        return h.copy()
    t = np.quantile(pos, q)
    removed = np.clip(h - t, 0.0, None)
    mass_removed = removed.sum()
    hnew = np.clip(h - t, 0.0, None)
    lo = int(0.55 * n)
    hi = n
    b = _bump(n, lo, hi, profile)
    bs = b.sum()
    if bs > 0 and mass_removed > 0:
        hnew = hnew + (s * mass_removed / bs) * b
    return _rescale(hnew)


def _ladder(h, deadline, best, bestR, tag=""):
    cur = h.copy()
    curR = R_of(cur)
    if curR > bestR:
        best, bestR = cur.copy(), curR
        print("  %s init R=%.7f" % (tag, bestR))

    p_list = (8, 16, 32, 64, 128)
    beta_list = (1e4, 1e5, 1e6, 1e7)

    for p in p_list:
        if time.process_time() >= deadline - 3.0:
            return best, bestR
        hp = _lbfgs_log(cur, 200, deadline, mode='pnorm', param=p)
        hs = _lbfgs_log(hp, 150, deadline)
        hw = _window_polish_peak(hs, deadline, 0.10, 32, maxiter=150)
        rs = R_of(hs); rw = R_of(hw)
        cand, rc = (hw, rw) if rw > rs else (hs, rs)
        if rc > curR + 1e-13:
            cur, curR = cand, rc
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
                print("  %s p=%d R=%.7f" % (tag, p, bestR))

    for beta in beta_list:
        if time.process_time() >= deadline - 3.0:
            return best, bestR
        hb = _lbfgs_log(cur, 150, deadline, mode='beta', param=beta)
        hs = _lbfgs_log(hb, 150, deadline)
        hw = _window_polish_peak(hs, deadline, 0.10, 32, maxiter=150)
        rs = R_of(hs); rw = R_of(hw)
        cand, rc = (hw, rw) if rw > rs else (hs, rs)
        if rc > curR + 1e-13:
            cur, curR = cand, rc
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
                print("  %s beta=%.0e R=%.7f" % (tag, beta, bestR))

    return best, bestR


def _polish_candidate(h, deadline):
    """Full polish pipeline for one candidate. Returns (h, R)."""
    cur = h.copy()
    curR = R_of(cur)
    if time.process_time() >= deadline - 2.0:
        return cur, curR
    # sharp global
    hs = _lbfgs_log(cur, 200, deadline)
    rs = R_of(hs)
    if rs > curR:
        cur, curR = hs, rs
    if time.process_time() >= deadline - 2.0:
        return cur, curR
    # bump region block polish
    n = cur.size
    lo = int(0.55 * n) - 128
    hi = n
    lo = max(0, lo)
    free = np.arange(lo, hi)
    hb = _lbfgs_block(cur, free, 150, deadline)
    rb = R_of(hb)
    if rb > curR:
        cur, curR = hb, rb
    # p-norm 8 and 32
    for p in (8, 32):
        if time.process_time() >= deadline - 2.0:
            return cur, curR
        hp = _lbfgs_log(cur, 150, deadline, mode='pnorm', param=p)
        hs = _lbfgs_log(hp, 150, deadline)
        r = R_of(hs)
        if r > curR:
            cur, curR = hs, r
    # final sharp + peak window
    if time.process_time() < deadline - 2.0:
        hf = _lbfgs_log(cur, 200, deadline)
        rf = R_of(hf)
        if rf > curR:
            cur, curR = hf, rf
    if time.process_time() < deadline - 2.0:
        hw = _window_polish_peak(cur, deadline, 0.10, 32, maxiter=150)
        rw = R_of(hw)
        if rw > curR:
            cur, curR = hw, rw
    return cur, curR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d) argmax=%.3f" %
          (bestR, best.size, _argmax_pos(best)))

    # (a) Soft-threshold sweep
    qs = (0.03, 0.06, 0.10)
    profiles = ('const', 'ramp', 'cos')
    ss = (0.5, 1.0)
    candidates = []
    for q in qs:
        for prof in profiles:
            for s in ss:
                if time.process_time() >= deadline - 8.0:
                    break
                hc = _soft_threshold_move(start_best, q, s, prof)
                rc = R_of(hc)
                am = _argmax_pos(hc)
                candidates.append((rc, q, prof, s, hc))
                print("  cand q=%.2f %s s=%.1f R=%.7f argmax=%.3f" %
                      (q, prof, s, rc, am))

    candidates.sort(key=lambda t: -t[0])
    top = candidates[:3]

    # (b) Polish top candidates
    for rc, q, prof, s, hc in top:
        if time.process_time() >= deadline - 4.0:
            break
        hp, rp = _polish_candidate(hc, deadline)
        print("  polish q=%.2f %s s=%.1f R=%.7f (was %.7f) argmax=%.3f" %
              (q, prof, s, rp, rc, _argmax_pos(hp)))
        if rp > bestR + 1e-13:
            best, bestR = hp.copy(), rp

    # (c) If improved, spend remaining time polishing
    if bestR > start_bestR + 1e-12:
        while time.process_time() < deadline - 2.0:
            hf = _lbfgs_log(best, 200, deadline)
            rf = R_of(hf)
            if rf > bestR + 1e-13:
                best, bestR = hf, rf
            if time.process_time() >= deadline - 2.0:
                break
            hw = _window_polish_peak(best, deadline, 0.10, 32, maxiter=150)
            rw = R_of(hw)
            if rw > bestR + 1e-13:
                best, bestR = hw, rw
            else:
                break
    else:
        # fall back: run base's ladder on a prolong2 to try to recover
        if time.process_time() < deadline - 6.0:
            n = start_best.size
            nxt = np.empty(n)
            nxt[:-1] = start_best[1:]
            nxt[-1] = start_best[-1]
            d = (nxt - start_best) / 4.0
            h2 = np.empty(2 * n)
            h2[0::2] = np.clip(start_best - d, 0, None)
            h2[1::2] = np.clip(start_best + d, 0, None)
            h2 = _rescale(h2)
            best, bestR = _ladder(h2, deadline, best, bestR, tag="2x")

    print("final R=%.7f (N=%d, zeros %.1f%%) argmax=%.3f" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           _argmax_pos(best)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6 and best.size == start_best.size:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(1234567)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = _rescale(s.copy())
            best_r = R_of(best)

    if best is None:
        x = np.linspace(0, 1, 512)
        best = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        best_r = R_of(best)

    print("start R = %.6f, N = %d" % (best_r, best.size))

    # Strategy 1: try refining at higher resolution (prolongate + polish + window)
    for mult in (2, 4):
        if time.process_time() >= deadline - 10.0:
            break
        Nbig = best.size * mult
        if Nbig > 1000000:
            continue
        cand = _prolongate(best, Nbig)
        cand = _rescale(cand)
        cand = _lbfgs_log(cand, maxiter=400, deadline=deadline)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand.copy(), r
            print("  refine x%d R=%.6f" % (mult, r))

    # Strategy 2: beta homotopy from current best
    if time.process_time() < deadline - 8.0:
        cur = best.copy()
        cur_r = best_r
        for beta in (16, 64, 256, 1024):
            if time.process_time() >= deadline - 4.0:
                break
            cand = _lbfgs_log(cur, maxiter=300, deadline=deadline, beta=beta)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
            print("  beta homotopy R=%.6f" % best_r)

    # Strategy 3: peak window polishing with decreasing windows
    if time.process_time() < deadline - 4.0:
        cur = best.copy()
        cur_r = best_r
        for frac in (0.15, 0.06, 0.025):
            if time.process_time() >= deadline - 1.5:
                break
            cand = _window_polish(cur, deadline, frac, 8, maxiter=300)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
            print("  window R=%.6f" % best_r)

    # Strategy 4: perturbation restarts inside peak region
    tries = 0
    while time.process_time() < deadline - 1.0:
        lo, hi = _peak_region(best)
        span = hi - lo
        pad = max(8, int(span * 0.12))
        lo = max(0, lo - pad)
        hi = min(best.size - 1, hi + pad)
        win = np.arange(lo, hi + 1)
        act = win[best[win] > 0]
        if act.size == 0:
            break
        scale = 0.015 * (1 + tries)
        cand = best.copy()
        cand[act] *= np.exp(rng.normal(0.0, min(scale, 0.15), act.size))
        cand = _rescale(cand)
        cand = _lbfgs_log(cand, maxiter=400, deadline=deadline)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand.copy(), r
            print("  perturb %d R=%.6f" % (tries, best_r))
        tries += 1

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
