        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _zero_runs(h):
    runs = []
    z = (h <= 1e-14 * max(h.max(), 1e-300))
    n = h.size
    i = 0
    while i < n:
        if z[i]:
            j = i
            while j < n and z[j]:
                j += 1
            runs.append((i, j - i))
            i = j
        else:
            i += 1
    return runs


def _end_amp(h, side, frac=0.05):
    n = h.size
    k = max(1, int(n * frac))
    if side == 'left':
        seg = h[:k]
    else:
        seg = h[-k:]
    seg = seg[seg > 0]
    if seg.size == 0:
        return h.max() * 0.01
    return float(np.mean(seg))


def _make_toe(ext, q, a):
    j = np.arange(ext, dtype=float)
    p = a * np.power(np.clip(1.0 - (j + 0.5) / ext, 0.0, None), q)
    return p


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    R0 = bestR

