    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _random_lift(h, alpha, rng):
    """Lift h to 2x resolution with per-cell Dirichlet(alpha) splits, mass-preserving."""
    n = h.size
    w = rng.dirichlet([alpha, alpha], size=n)  # shape (n, 2)
    out = np.empty(2 * n)
    out[0::2] = h * w[:, 0]
    out[1::2] = h * w[:, 1]
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    rng = np.random.default_rng(12345)
    alphas = [0.3, 0.7, 1.5]

    track_best = bestR
    best_pre = -1.0
    best_post = -1.0
    n_trials = 0
    n_polished = 0

    # Random-lift exploration loop
    while time.process_time() < deadline - 3.0:
        n_trials += 1
        alpha = alphas[rng.integers(0, len(alphas))]
        cand = _random_lift(best, alpha, rng)
        rc = R_of(cand)
        if rc > best_pre:
            best_pre = rc
        # Keep offspring only if close to track best
        if rc < track_best - 8e-3:
            continue
        n_polished += 1
        print("  trial %d alpha=%.1f pre R=%.7f" % (n_trials, alpha, rc))

        # Stage (c): polish with capped stages
        h = cand
        # sharp full polish, ~4s cap
        cap = min(deadline - 2.0, time.process_time() + 4.0)
        h = _lbfgs_log(h, 250, cap)
        # beta=1e3 pass
        if time.process_time() < deadline - 2.0:
            cap = min(deadline - 2.0, time.process_time() + 4.0)
            hb = _lbfgs_log(h, 120, cap, beta=1e3)
            if R_of(hb) > R_of(h):
                h = hb
        # peak-window block
        if time.process_time() < deadline - 2.0:
            cap = min(deadline - 2.0, time.process_time() + 4.0)
            hp = _window_polish_peak(h, cap, 0.06, 32, maxiter=150)
            if R_of(hp) > R_of(h):
                h = hp

        rp = R_of(h)
        if rp > best_post:
            best_post = rp
        print("  trial %d post R=%.7f" % (n_trials, rp))

        if rp > bestR + 1e-13:
            best, bestR = h, rp
            track_best = max(track_best, bestR)
            print("  improved incumbent R=%.7f" % bestR)

    print("trials=%d polished=%d best_pre=%.7f best_post=%.7f final R=%.7f" %
          (n_trials, n_polished, best_pre, best_post, bestR))

    if bestR > start_bestR + 1e-12:
        return best
    # Return the random-lift construction as alternative if genuinely different
    if bestR > start_bestR - 1e-6 and bestR > 0:
        return {"best": start_best, "alternative": best}
    return {"best": start_best, "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _fit_target(h0, t, deadline, maxiter=120):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    tn = t.size

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        c = fftconvolve(hh, hh)
        if c.size != tn:
            cc = np.zeros(tn)
            m = min(tn, c.size)
            cc[:m] = c[:m]
            c = cc
        r = c - t
        val = 0.5 * np.sum(r * r)
        gr = fftconvolve(r, hh[::-1], mode='valid')[:n]
        g = 2.0 * gr
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-18, 'gtol': 1e-14})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _mass_resample(h, Nnew):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    N = h.size
    if N == Nnew:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(Nnew) / Nnew
    x = np.linspace(0.0, 1.0, Nnew + 1)
    src_x = np.linspace(0.0, 1.0, N + 1)
    target_c = np.interp(x, src_x, c)
    out = np.diff(target_c)
    out = np.clip(out, 0, None)
    if out.sum() <= 0:
        return np.ones(Nnew) / Nnew
    return out * (total / out.sum())


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    record_R = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    # ---- NEW IDEA: multi-resolution refinement ----
    # Try a family of N resolutions. For each, resample the best, then run
    # sharp + peak polish. Also try inverse-target fits at each resolution.
    bestH = best.copy()
    bestRH = record_R
    N0 = best.size

    # Candidate resolutions: coarser (smoother, escapes local minima) and finer
    cand_Ns = []
    for f in (0.25, 0.5, 1.0, 2.0, 4.0):
        NN = int(round(N0 * f))
        if 256 <= NN <= 1000000 and NN not in cand_Ns:
            cand_Ns.append(NN)
    # also try a couple of absolute sizes
    for NN in (2048, 4096, 16384, 32768):
        if NN not in cand_Ns and NN <= 1000000:
            cand_Ns.append(NN)

    # Phase A: coarse->fine resample+polish
    for NN in cand_Ns:
        if time.process_time() >= deadline - 3.0:
            break
        hres = _mass_resample(bestH, NN)
        hres = _rescale(hres)
        # short sharp polish
        cap = min(deadline - 1.0, time.process_time() + 4.0)
        hp = _lbfgs_log(hres, 250, cap, beta=0.0)
        rp = R_of(hp)
        # peak polish
        if time.process_time() < deadline - 1.5:
            free = _peak_window(hp, frac=0.10)
            cap = min(deadline - 0.5, time.process_time() + 3.0)
            hq = _lbfgs_block(hp, free, 200, cap, beta=0.0)
            rq = R_of(hq)
            if rq > rp:
                hp, rp = hq, rq
        print("  N=%d R=%.7f" % (NN, rp))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("    NEW BEST R=%.7f at N=%d" % (bestRH, NN))

    # Phase B: inverse-target fits at current best resolution
    h_rec = bestH.copy()
    s = h_rec.sum()
    h_unit = h_rec / s
    L0 = fftconvolve(h_unit, h_unit)
    M = L0.max()
    if M > 0:
        L0n = L0 / M
        targets = []
        for gamma in (0.5, 0.7, 0.85, 0.95):
            t = np.power(np.clip(L0n, 0, None), gamma)
            targets.append(("gamma=%.2f" % gamma, t))
        for c in (0.80, 0.90, 0.95, 0.98):
            t = np.minimum(L0n, c)
            targets.append(("clip=%.2f" % c, t))
        for name, t in targets:
            if time.process_time() >= deadline - 2.0:
                break
            t = np.clip(t, 0, None)
            ts = t.sum()
            if ts <= 0:
                continue
            t = t / ts
            cap = min(deadline - 1.0, time.process_time() + 6.0)
            hf = _fit_target(h_rec, t, cap, maxiter=120)
            r_raw = R_of(hf)
            if r_raw >= bestRH - 2e-3:
                hp, rp = _polish(hf, min(deadline - 0.5, time.process_time() + 12.0), bestRH)
            else:
                hp, rp = hf, r_raw
            print("  target %-10s raw R=%.7f polished R=%.7f" % (name, r_raw, rp))
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("    NEW BEST R=%.7f" % bestRH)

    # Phase C: alternating sharp + peak polish on best
    rng = np.random.default_rng(1234567)
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        improved = False
        cap = min(loop_end, time.process_time() + 5.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            improved = True
        if time.process_time() < loop_end:
            frac = 0.05 + 0.10 * rng.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 4.0)
            hp = _lbfgs_block(bestH, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                improved = True
        if improved:
            print("  iter=%d R=%.7f" % (it, bestRH))
        else:
            if time.process_time() < loop_end - 2.0:
                beta = 10.0 ** rng.uniform(1.0, 4.0)
                cap = min(loop_end, time.process_time() + 3.0)
                hs = _lbfgs_log(bestH, 100, cap, beta=beta)
                rs = R_of(hs)
                if rs > bestRH + 1e-13:
                    bestH, bestRH = hs.copy(), rs
                    print("  soft beta=%.1e R=%.7f" % (beta, bestRH))

    print("final R=%.7f (best of experiment, N=%d)" % (bestRH, bestH.size))

    if bestRH > start_bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH
    else:
        best, bestR = start_best, start_bestR

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    if bestH.size == start_best.size and bestRH > start_bestR - 1e-6 and bestRH < start_bestR + 1e-12:
        return {"best": start_best, "alternative": bestH}
    return {"best": start_best, "alternative": bestH if bestH is not None else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _sharpen(h, deadline, iters=80):
    cur = h
    for beta in (2.0, 8.0, 32.0, 128.0, 0.0):
        if time.process_time() > deadline - 0.3:
            break
        cur = _lbfgs_log(cur, iters, deadline, beta=beta)
    return cur


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n == n_new:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    if c[-1] <= 0:
        return np.ones(n_new)
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def _prune(h, frac):
    h = np.asarray(h, dtype=float).copy()
    n = len(h)
    k = int(frac * n)
    if k <= 0:
        return h
    if k >= n:
        k = n - 1
    idx = np.argpartition(h, k - 1)[:k]
    h[idx] = 0.0
    mx = h.max()
    if mx > 0:
        floor = 1e-6 * mx
        pos = h > 0
        h[pos] = np.maximum(h[pos], floor)
    return h


def _seed_cosine(n):
    x = np.linspace(0, 1, n)
    return np.cos(np.pi * (x - 0.5))**2 + 1e-3


def _seed_asym(n):
    x = np.linspace(0, 1, n)
    return np.exp(-((x - 0.35) / 0.2)**2) + 1e-3


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.5
    best = None
    best_R = -1.0
    start_h = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            start_h = s.copy()
            best = s.copy()
            best_R = R_of(best)

    if start_h is None:
        seed_cap = t0 + min(12.0, budget_seconds * 0.25)
        best_seed = None
        best_seed_R = -1.0
        for seed_fn in (_seed_cosine, _seed_asym):
            h = seed_fn(256)
            h = _sharpen(h, seed_cap, iters=60)
            for n in (512, 1024, 2048):
                if time.process_time() > seed_cap:
                    break
                h = _prolong(h, n)
                h = _sharpen(h, seed_cap, iters=60)
            r = R_of(h)
            if r > best_seed_R:
                best_seed_R = r
                best_seed = h
        if best_seed is not None and best_seed_R > best_R:
            best = best_seed
            best_R = best_seed_R

    base = best.copy()
    if base is not None:
        cur = _sharpen(base, deadline, iters=120)
        curR = R_of(cur)
        if curR > best_R:
            best = cur.copy()
            best_R = curR
        base = cur

        ladder = [8192, 16384, 32768, 65536]
        for n_new in ladder:
            if time.process_time() > deadline - 1.0:
                break
            h = _prolong(base, n_new)
            for frac in (0.35, 0.5, 0.65):
                if time.process_time() > deadline - 1.0:
                    break
                hp = _prune(h, frac)
                if hp.sum() <= 0:
                    continue
                hp = _sharpen(hp, deadline, iters=100)
                r = R_of(hp)
                if r > best_R:
                    best = hp.copy()
                    best_R = r
                    h = hp
            if time.process_time() < deadline - 1.0:
                hs = _sharpen(h, deadline, iters=100)
                r = R_of(hs)
                if r > best_R:
                    best = hs.copy()
                    best_R = r
                    h = hs
            base = h

    alt_best = None
    alt_R = -1.0
    if best is not None:
        cur = best.copy()
        curR = best_R
        n = len(cur)
        while time.process_time() < deadline - 1.0:
            L = _knots(cur)
            m = int(np.argmax(L))
            lo = max(0, m - n // 2)
            hi = min(n, m + n // 2)
            w = max(8, (hi - lo) // 10)
            lo = max(0, lo - w)
            hi = min(n, hi + w)
            free = np.arange(lo, hi)
            trial = _lbfgs_block(cur, free, 200, deadline, beta=0.0)
            trial = _lbfgs_log(trial, 80, deadline, beta=8.0)
            trial = _lbfgs_log(trial, 80, deadline, beta=0.0)
            r = R_of(trial)
            if r > curR + 1e-9:
                cur = trial
                curR = r
                if r > best_R:
                    best = trial.copy()
                    best_R = r
            else:
                trial = _sharpen(cur, deadline, iters=120)
                r2 = R_of(trial)
                if r2 > curR + 1e-9:
                    cur = trial
                    curR = r2
                    if r2 > best_R:
                        best = trial.copy()
                        best_R = r2
                else:
                    break
        alt_best = cur
        alt_R = curR

    if best is None:
        best = np.ones(50)
    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(50)

    result = {"best": best}
    if alt_best is not None and alt_R < best_R - 1e-9 and start_h is not None:
        result["alternative"] = alt_best
    print(f"final R={R_of(best):.6f} N={len(best)}")
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    # soft-max surrogate for ||f*f||_inf: log-sum-exp approximation.
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _gauss_smooth(h, sigma):
    if sigma <= 0.5:
        return h.copy()
    r = int(3 * sigma) + 1
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return np.convolve(h, k, mode='same')


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt = None
    altR = 0.0
    N = best.size

    # NEW IDEA: warm up with a soft-max (log-sum-exp) surrogate of ||f*f||_inf.
    # This is differentiable everywhere, so it pulls the whole near-peak plateau
    # up together (rather than just the single argmax knot), which is exactly
    # the structure that R rewards. Then switch to the hard max for fine-tuning.
    # We do this at full resolution directly on the start, so we actually move
    # the start's basin rather than just re-finding it.
    if time.process_time() < deadline - 15.0:
        hb = _rescale(best.copy())
        for beta in (200.0, 500.0, 1000.0):
            if time.process_time() >= deadline - 12.0:
                break
            hb = _lbfgs_log(hb, 300, deadline, beta=beta)
            hb = _window_polish_peak(hb, deadline, 0.30, 16, maxiter=250, beta=beta)
            r = R_of(hb)
            print("beta %.0f R=%.7f" % (beta, r))
        # hard-max polish of the softened result
        hb = _lbfgs_log(hb, 500, deadline)
        hb = _window_polish_peak(hb, deadline, 0.35, 24)
        hb = _lbfgs_log(hb, 400, deadline)
        r = R_of(hb)
        print("softmax-then-hard R=%.7f" % r)
        if alt is None or r > altR:
            alt, altR = hb, r
        if r > bestR + 1e-15:
            best, bestR = hb, r
            print("softmax wins R=%.7f" % bestR)

    # Low-resolution re-optimisation with Gaussian-smoothed restart, then
    # prolongation back up (kept from p0004 as a complementary basin hop).
    for factor in (4, 2):
        if time.process_time() >= deadline - 10.0:
            break
        Nc = max(256, N // factor)
        hc = _coarse(best, Nc)
        hc = _rescale(hc)
        hc = _gauss_smooth(hc, sigma=max(1.0, Nc / 400.0))
        hc = _rescale(hc)
        hc = _lbfgs_log(hc, 500, deadline)
        hc = _window_polish_peak(hc, deadline, 0.5, 8)
        hc = _lbfgs_log(hc, 300, deadline)
        hp = _prolongate(hc, N)
        hp = _rescale(hp)
        hp = _lbfgs_log(hp, 400, deadline)
        hp = _window_polish_peak(hp, deadline, 0.4, 24)
        hp = _lbfgs_log(hp, 300, deadline)
        rp = R_of(hp)
        print("coarse %d->%d R=%.7f" % (Nc, N, rp))
        if alt is None or rp > altR:
            alt, altR = hp, rp
        if rp > bestR + 1e-15:
            best, bestR = hp, rp
            print("coarse wins R=%.7f" % bestR)

    # Peak-focused multi-scale polish on the current best.
    for frac, extra in ((0.10, 4), (0.20, 8), (0.35, 16), (0.50, 32), (0.75, 64)):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish_peak(best, deadline, frac, extra)
        h = _lbfgs_log(h, 400, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("peak(%.2f) R=%.7f" % (frac, bestR))

    # Final loop: alternate full and peak polish until budget exhausted.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and altR > startR + 1e-15 and altR >= bestR - 1e-15:
        return {"best": best, "alternative": alt}
    if alt is not None and altR <= startR + 1e-15:
        return {"best": best, "alternative": alt}
    return best

