def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _zero_runs(h, thresh):
    mask = h <= thresh
    if not mask.any():
        return []
    d = np.diff(mask.astype(np.int8))
    starts = np.flatnonzero(d == 1) + 1
    ends = np.flatnonzero(d == -1) + 1
    if mask[0]:
        starts = np.concatenate(([0], starts))
    if mask[-1]:
        ends = np.concatenate((ends, [h.size]))
    runs = [(int(s), int(e)) for s, e in zip(starts, ends) if e > s]
    return runs


def _near_max_share(h, frac=0.001):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(L >= (1.0 - frac) * mx))


def _upsample(h, factor):
    """Linear interpolation upsample by integer factor."""
    n = h.size
    m = (n - 1) * factor + 1
    x = np.linspace(0, n - 1, m)
    return np.interp(x, np.arange(n), h)


def _downsample(h, target_n):
    n = h.size
    if n <= target_n:
        return h
    # area-preserving block average
    edges = np.linspace(0, n, target_n + 1)
    out = np.zeros(target_n)
    for i in range(target_n):
        lo = int(edges[i]); hi = int(edges[i + 1])
        if hi <= lo:
            hi = lo + 1
        out[i] = h[lo:hi].mean()
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    N = best.size
    print("base R=%.7f (N=%d)" % (bestR, N))

    def _time_left():
        return deadline - time.process_time()

    # ---------- Refinement ladder: upsample + polish, keep best ----------
    print("=== refinement ladder ===")
    candidates = [(bestR, best.copy())]

    # Try refinement at higher resolution: upsample by 2, polish, evaluate.
    # Only accept if better (R is resolution-independent in principle but
    # discretization matters slightly).
    for factor in (2, 3):
        if _time_left() < 6.0:
            break
        if N * factor > 900000:
            break
        hu = _upsample(best, factor)
        hu = _rescale(hu)
        cap = min(_time_left() - 4.0, 12.0)
        if cap <= 1.0:
            break
        cap_deadline = min(deadline, time.process_time() + cap)
        # beta ladder at new resolution
        for beta in (0.0, 1e5, 1e7):
            if _time_left() < 3.0:
                break
            cap = min(_time_left() - 2.0, 5.0)
            if cap <= 0.5:
                break
            cap_deadline = min(deadline, time.process_time() + cap)
            hu = _lbfgs_log(hu, 200, cap_deadline, beta=beta)
        ru = R_of(hu)
        print("  upsample x%d -> R=%.7f (N=%d)" % (factor, ru, hu.size))
        candidates.append((ru, hu))

    # pick best candidate
    for r, h in candidates:
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
    N = best.size
    print("after ladder R=%.7f (N=%d)" % (bestR, N))

    # ---------- fine polish on the current best (full resolution) ----------
    print("=== fine polish ===")
    while _time_left() > 1.0:
        cap = min(_time_left() - 0.5, 8.0)
        if cap <= 0.3:
            break
        cap_deadline = min(deadline, time.process_time() + cap)
        h = _lbfgs_log(best, 400, cap_deadline, beta=0.0)
        r = R_of(h)
        print("  polish R=%.7f" % r)
        if r > bestR + 1e-13:
            best, bestR = h, r
        else:
            break

    # ---------- peak-window refinement at full resolution ----------
    print("=== peak windows ===")
    Lf = _knots(best)
    am = int(np.argmax(Lf))
    for w in (2001, 5001, 12001):
        if _time_left() < 1.5:
            break
        lo = max(0, am - w // 2)
        hi = min(N - 1, lo + w - 1)
        free = np.arange(lo, hi + 1)
        cap = min(_time_left() - 1.0, 5.0)
        if cap <= 0.3:
            break
        cap_deadline = min(deadline, time.process_time() + cap)
        h = _lbfgs_block(best, free, 200, cap_deadline)
        r = R_of(h)
        print("  peak w=%d R=%.7f" % (w, r))
        if r > bestR + 1e-13:
            best, bestR = h, r

    # ---------- zero revival on long runs ----------
    print("=== zero revival ===")
    if _time_left() > 2.0:
        thresh = 1e-13 * best.max()
        runs = _zero_runs(best, thresh)
        runs_sorted = sorted(runs, key=lambda se: se[1] - se[0], reverse=True)
        nz = np.flatnonzero(best > thresh)
        min_zero_len = max(1, N // 100)
        long_runs = [se for se in runs_sorted if (se[1] - se[0]) > min_zero_len]
        for (s, e) in long_runs[:8]:
            if _time_left() < 2.0:
                break
            L = e - s
            left = nz[nz < s]
            right = nz[nz >= e]
            near = np.concatenate((left[-100:], right[:100]))
            if near.size == 0:
                continue
            amp = best[near].mean()
            for rho in (0.01, 0.05):
                if _time_left() < 1.5:
                    break
                h = best.copy()
                h[s:e] = np.clip(rho * amp, 0.0, None)
                h = _rescale(h)
                lo = max(0, s - 300)
                hi = min(N - 1, e + 300)
                free = np.arange(lo, hi + 1)
                cap = min(_time_left() - 1.0, 4.0)
                if cap <= 0.3:
                    break
                cap_deadline = min(deadline, time.process_time() + cap)
                h = _lbfgs_block(h, free, 150, cap_deadline)
                r = R_of(h)
                print("  zero [%d,%d] rho=%.3f R=%.7f" % (s, e, rho, r))
                if r > bestR + 1e-13:
                    best, bestR = h, r

    # ---------- final sharp polish ----------
    if _time_left() > 1.0:
        cap = min(_time_left(), 6.0)
        cap_deadline = min(deadline, time.process_time() + cap)
        h = _lbfgs_log(best, 400, cap_deadline, beta=0.0)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r

    print("final R=%.7f (N=%d) startR=%.7f" % (bestR, best.size, startR))
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_clip(h, alpha):
    """Maximise mass under a cap c = alpha*M (scale invariant).
    Penalises the region near max in a soft way so that the optimum
    spreads the peak into a plateau instead of a single point."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad(h)
    c = alpha * M
    mask = (Lf < c)
    u = np.where(mask, Lf, 0.0)
    a = u[:-1]; b = u[1:]
    E = np.sum(a * a + a * b + b * b) / 3.0
    if E <= 0:
        return _fun_grad(h)
    dE = np.zeros_like(Lf)
    dE[:-1] += (2 * a + b)
    dE[1:] += (a + 2 * b)
    dE /= 3.0
    dE *= mask
    gLf = dE / E
    grad = _backprop(gLf, h) - 2.0 / s
    val = -np.log(E) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window_jitter(h, rng, sigma, width):
    """Multiply a random window centred near the peak by a smooth bump."""
    n = h.size
    lo_pk, hi_pk = _peak_region(h)
    c = (lo_pk + hi_pk) // 2
    w = min(width, n)
    lo = int(np.clip(c - w // 2 + rng.integers(-w, w + 1), 0, n - w))
    t = np.arange(w, dtype=float)
    center = w / 2.0 + rng.normal(0, w / 8.0)
    g = np.exp(-0.5 * ((t - center) / (w / 6.0)) ** 2)
    k = 9
    ker = np.ones(k) / k
    g = np.convolve(g, ker, mode='same')
    g = g / max(g.max(), 1e-300)
    bump = np.exp(sigma * (g - 1.0))
    hp = h.copy()
    hp[lo:lo + w] *= bump
    return np.clip(hp, 0, None)


def _smooth_peak(h, rng, sigma, width):
    """Broader plateau-encouraging perturbation: flatten the peak region."""
    n = h.size
    lo_pk, hi_pk = _peak_region(h)
    c = (lo_pk + hi_pk) // 2
    w = min(width, n)
    lo = int(np.clip(c - w // 2, 0, n - w))
    t = np.arange(w, dtype=float)
    g = np.exp(-0.5 * ((t - w / 2.0) / (w / 4.0)) ** 2)
    g = g / max(g.max(), 1e-300)
    hp = h.copy()
    hp[lo:lo + w] *= np.exp(-sigma * g)
    return np.clip(hp, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(20240607)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("start R=%.7f (N=%d)" % (start_bestR, start_best.size))

    best = start_best.copy()
    bestR = start_bestR

    # ---- Idea: block-refinement to double resolution ----
    # Interpolate start to 2x (linear between neighbours) and polish.
    n0 = start_best.size
    H = _rescale(np.repeat(start_best, 2))
    R2x = R_of(H)
    print("2x baseline R=%.7f (N=%d)" % (R2x, H.size))

    Hp = _lbfgs_log(H, 200, deadline)
    Hp = _window_polish_peak(Hp, deadline, 0.10, 200, maxiter=200)
    # clip-based smoothing to spread the peak into a plateau
    for alpha in (0.999, 0.995, 0.99, 0.98):
        if time.process_time() >= deadline - 3.0:
            break
        hc = _lbfgs_log(Hp, 150, deadline, fg=lambda hh, a=alpha: _fun_grad_clip(hh, a))
        rc = R_of(hc)
        if rc > R_of(Hp):
            Hp = hc
    R2x_pol = R_of(Hp)
    print("2x polished R=%.7f" % R2x_pol)
    if R2x_pol > bestR + 1e-13:
        best, bestR = Hp.copy(), R2x_pol

    # ---- end-spike scan on H ----
    n = H.size
    cands = []
    for side in ("left", "right"):
        for k in (1, 2, 4, 8, 16, 32):
            if k > n:
                continue
            if side == "left":
                seg = H[0:k]
                adj = H[k:k + 64]
            else:
                seg = H[-k:]
                adj = H[-k - 64:-k]
            adj_mean = float(adj.mean()) if adj.size > 0 else float(H.mean())
            for mult in (1.5, 2.0, 3.0, 5.0, 8.0, 12.0):
                for mode in ("scale", "set"):
                    Hc = H.copy()
                    if mode == "scale":
                        if side == "left":
                            Hc[0:k] = seg * mult
                        else:
                            Hc[-k:] = seg * mult
                    else:
                        if side == "left":
                            Hc[0:k] = mult * adj_mean
                        else:
                            Hc[-k:] = mult * adj_mean
                    Hc = _rescale(Hc)
                    r = R_of(Hc)
                    cands.append((r, side, k, mult, mode, Hc))
                    if time.process_time() > deadline - 12.0:
                        break
                if time.process_time() > deadline - 12.0:
                    break
            if time.process_time() > deadline - 12.0:
                break
        if time.process_time() > deadline - 12.0:
            break

    cands.sort(key=lambda t: -t[0])
    top = cands[:3]
    if top:
        print("top candidates: " + ", ".join(
            "%s k=%d mult=%.1f %s R=%.7f" % (c[1], c[2], c[3], c[4], c[0]) for c in top))

    def full_polish(hc, deadline, iters=200):
        h = _lbfgs_log(hc, iters, deadline)
        h = _window_polish_peak(h, deadline, 0.10, 128, maxiter=150)
        r = R_of(h)
        for beta in (1e5, 1e7, 1e9):
            if time.process_time() >= deadline - 3.0:
                break
            hb = _lbfgs_log(h, 120, deadline, beta=beta)
            rb = R_of(hb)
            if rb > r:
                h, r = hb, rb
        return h, r

    for (r0, side, k, mult, mode, Hc) in top:
        if time.process_time() >= deadline - 6.0:
            break
        h, r = full_polish(Hc, deadline)
        if time.process_time() < deadline - 4.0:
            hp = _peak_window_jitter(h, rng, 0.01, 128)
            hp = _rescale(hp)
            h2 = _lbfgs_log(hp, 120, deadline)
            h2 = _window_polish_peak(h2, deadline, 0.10, 128, maxiter=120)
            r2 = R_of(h2)
            if r2 > r:
                h, r = h2, r2
        print("  polished %s k=%d mult=%.1f %s -> R=%.7f" %
              (side, k, mult, mode, r))
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            print("  NEW BEST R=%.7f" % bestR)

    # ---- alternating stochastic + sharp polish loop ----
    cur = best.copy()
    curR = bestR
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        # alternate between jitter and peak-flattening perturbations
        if it % 3 == 0:
            width = int(rng.choice([96, 192, 384]))
            sigma = float(rng.choice([0.003, 0.006, 0.012]))
            hp = _smooth_peak(cur, rng, sigma, width)
        else:
            width = int(rng.choice([64, 128, 256, 512]))
            sigma = float(rng.choice([0.005, 0.01, 0.02]))
            hp = _peak_window_jitter(cur, rng, sigma, width)
        hp = _rescale(hp)
        h1 = _lbfgs_log(hp, 150, deadline)
        h2 = _window_polish_peak(h1, deadline, 0.10, 128, maxiter=150)
        r2 = R_of(h2)
        if r2 > curR + 3e-13:
            cur, curR = h2, r2
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
                print("  loop %d accept R=%.7f (w=%d s=%.3f)" %
                      (it, bestR, width, sigma))

    # final sharp polish
    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 250, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(beta * (Lf - mx))
    Z = np.sum(e)
    Lmax_s = mx + np.log(Z) / beta
    gLf = -dq / num + e / Z
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lmax_s)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    u = Lf / mx
    up = np.power(u, p)
    S = up.sum()
    if S <= 0:
        return 1e18, np.zeros(h.size)
    sm = np.power(S / Lf.size, 1.0 / p) * mx
    # d log(sm) / d Lf = u^(p-1) / sum(u^p)
    gLf = -dq / num + np.power(u, p - 1.0) / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
