import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_topm(h, m):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    m = min(m, n)
    idx = np.argpartition(Lf, -m)[-m:]
    sup = Lf[idx].mean()
    if sup <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[idx] += 1.0 / (m * sup)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sup)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    r = np.clip(Lf / mx, 0.0, None)
    rp = r ** p
    S = rp.sum()
    if S <= 0:
        return _fun_grad(h)
    sup = mx * (S / Lf.size) ** (1.0 / p)
    # d sup / d L_k = (1/n) * sup^(1-p) * L_k^(p-1) ... derive:
    # sup = (mean(L^p))^(1/p); dsup/dL_k = (1/n) * sup^(1-p) * L_k^(p-1)
    w = (1.0 / Lf.size) * (sup ** (1.0 - p)) * np.clip(Lf, 0.0, None) ** (p - 1.0)
    gLf = -dq / num + w / sup
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sup)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _zero_runs(h, thresh):
    mask = h <= thresh
    if not mask.any():
        return []
    d = np.diff(mask.astype(np.int8))
    starts = np.flatnonzero(d == 1) + 1
    ends = np.flatnonzero(d == -1) + 1
    if mask[0]:
        starts = np.concatenate(([0], starts))
    if mask[-1]:
        ends = np.concatenate((ends, [h.size]))
    runs = [(int(s), int(e)) for s, e in zip(starts, ends) if e > s]
    return runs


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    x = np.linspace(0, n - 1, m)
    return np.interp(x, np.arange(n), h)


def _diag(h, tag):
    s = h.sum()
    if s <= 0:
        print("  %s: empty" % tag)
        return
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    inf = L.max()
    am = int(np.argmax(L))
    print("  %s: num=%.6f inf=%.6f argmax=%d (%.3f) R=%.7f"
          % (tag, num / (s * s), inf / (s * s), am, am / L.size,
             R_of(h)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    startR = bestR
    N = best.size
    print("base R=%.7f (N=%d)" % (bestR, N))
    _diag(best, "base")

    def _time_left():
        return deadline - time.process_time()

    def _short_polish(h, cap=2.0):
        if _time_left() < 0.5:
            return h
        c = min(_time_left() - 0.3, cap)
        if c <= 0.2:
            return h
        cd = min(deadline, time.process_time() + c)
        return _lbfgs_log(h, 200, cd, beta=0.0)

    # ---------- surrogate-based spike flattening ----------
    print("=== surrogate flattening (topm / pnorm) ===")
    trials = []
    trials.append(("topm16", lambda hh: _fun_grad_topm(hh, 16)))
    trials.append(("topm64", lambda hh: _fun_grad_topm(hh, 64)))
    trials.append(("topm256", lambda hh: _fun_grad_topm(hh, 256)))
    trials.append(("pnorm20", lambda hh: _fun_grad_pnorm(hh, 20)))
    trials.append(("pnorm8", lambda hh: _fun_grad_pnorm(hh, 8)))

    for name, fg in trials:
        if _time_left() < 4.0:
            break
        c = min(_time_left() - 2.0, 6.0)
        if c <= 0.5:
            break
        cd = min(deadline, time.process_time() + c)
        h = _lbfgs_log(best, 200, cd, fg=fg)
        _diag(h, name + " pre-polish")
        h = _short_polish(h, 2.0)
        r = R_of(h)
        _diag(h, name + " post-polish")
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("  -> accepted %s R=%.7f" % (name, bestR))

    # ---------- multiplicative spike-flattenings ----------
    print("=== spike flattening (multiplicative) ===")
    for fac in (0.99, 0.97, 0.95, 0.93):
        if _time_left() < 3.0:
            break
        Lf = _knots(best)
        m0 = int(np.argmax(Lf))
        lo = max(0, m0 - int(0.20 * N))
        hi = min(N, m0 + int(0.05 * N))
        if hi <= lo:
            continue
        h = best.copy()
        h[lo:hi] *= fac
        h = _rescale(h)
        _diag(h, "flat%.2f pre" % fac)
        h = _short_polish(h, 2.0)
        r = R_of(h)
        _diag(h, "flat%.2f post" % fac)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("  -> accepted flat%.2f R=%.7f" % (fac, bestR))

    # ---------- alternating polish until deadline ----------
    print("=== alternating polish ===")
    toggle = 0
    while _time_left() > 1.0:
        c = min(_time_left() - 0.5, 6.0)
        if c <= 0.3:
            break
        cd = min(deadline, time.process_time() + c)
        beta = 0.0 if (toggle % 2 == 0) else 1e3
        h = _lbfgs_log(best, 300, cd, beta=beta)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("  polish beta=%.0f R=%.7f" % (beta, bestR))
        toggle += 1

    _diag(best, "final")
    print("final R=%.7f (N=%d) startR=%.7f" % (bestR, best.size, startR))
    return {"best": best, "alternative": best}

