def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    Lp = np.clip(Lf / mx, 0.0, None)
    sp = np.sum(Lp ** p)
    if sp <= 0:
        return _fun_grad(h)
    sm = mx * sp ** (1.0 / p)
    dsm = sp ** (1.0 / p - 1.0) * Lp ** (p - 1.0)
    gLf = -dq / num + dsm / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
