        if stall >= 3 and best.size < 200000 and time.process_time() < deadline - 5.0:
            Nb = min(best.size * 2, 200000)
            hp = _rescale(_prolongate(best, Nb))
            hp = _lbfgs_log(hp, 400, deadline)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                best, bestR = hp, rp
            stall = 0
        if time.process_time() >= deadline - 1.5:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if start is not None:
        b = np.clip(np.asarray(start, dtype=float), 0, None)
        if b.sum() > 0:
            sr = R_of(_rescale(b))
            if bestR > sr + 1e-12:
                return best
            return {"best": _rescale(b), "alternative": best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _upsample(h, factor):
    n = h.size
    x_old = np.arange(n, dtype=float)
    x_new = np.arange(n * factor, dtype=float) / factor
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    best = None
    bestR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))
    start_best = best.copy()
    start_R = bestR
    alt = None
    altR = 0.0

    def record(h, tag):
        nonlocal best, bestR, alt, altR
        r = R_of(h)
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("%s R=%.7f" % (tag, bestR))
            return True
        return False

    # ---- Phase 1: coarse beta-homotopy polish (smoothed max) ----
    if time.process_time() < deadline - 4.0:
        work = best
        for beta in (30.0, 80.0, 200.0, 500.0):
            if time.process_time() >= deadline - 3.0:
                break
            h = _lbfgs_log(work, 300, deadline, beta=beta)
            record(h, "beta%.0f" % beta)
            work = best
        # finish exact
        h = _lbfgs_log(best, 400, deadline)
        record(h, "exact")

    # ---- Phase 2: refinement at higher resolution (the key new idea) ----
    # Upsample the current solution to a finer grid and re-optimize.
    # Finer grids resolve the peak plateau better and can gain a bit of R.
    for factor in (2, 2):
        if time.process_time() >= deadline - 3.0:
            break
        if best.size * factor > 400000:
            break
        hu = _upsample(best, factor)
        hu = _rescale(hu)
        # quick exact polish on the fine grid
        h1 = _lbfgs_log(hu, 400, deadline)
        record(h1, "up%d" % factor)
        # beta polish around the peak window at fine grid
        for beta in (100.0, 300.0):
            if time.process_time() >= deadline - 2.5:
                break
            free = _peak_window(best if best.size == h1.size else h1, 0.20)
            if free.size > 0 and free[-1] < h1.size:
                h2 = _lbfgs_block(h1, free, 300, deadline, beta=beta)
                record(h2, "up%d-b%.0f" % (factor, beta))
        h3 = _lbfgs_log(best, 400, deadline)
        record(h3, "up%d-exact" % factor)

    # ---- Phase 3: peak window polish at coarse/fine mix ----
    for frac in (0.10, 0.20, 0.35):
        if time.process_time() >= deadline - 2.5:
            break
        free = _peak_window(best, frac)
        h = _lbfgs_block(best, free, 400, deadline)
        record(h, "win%.2f" % frac)

    # ---- Phase 4: alternating polish to convergence ----
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 500, deadline)
        if record(h, "full"):
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        free = _peak_window(best, 0.30)
        h2 = _lbfgs_block(best, free, 400, deadline)
        if record(h2, "win"):
            improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and altR > 0 and bestR <= start_R + 1e-15:
        return {"best": start_best, "alternative": alt}
    return best

