    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _peak_window(h, frac, extra=8):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _diagnostics(h):
    Lf = _knots(h)
    mx = Lf.max()
    am = int(np.argmax(Lf))
    frac = lambda t: float(np.mean(Lf >= (1.0 - t) * mx))
    return {
        'N': h.size,
        'R': R_of(h),
        'zero_frac': float(np.mean(h <= 0)),
        'argmax': am,
        'argmax_frac': am / max(1, h.size),
        'f01': frac(1e-3),
        'f1': frac(1e-2),
        'f5': frac(5e-2),
    }


# ---------- new experiment helpers ----------

def _prune(h, qfrac, mode):
    """Set smallest qfrac of positive cells to zero; redistribute their mass
    either proportionally to remaining positives ('prop') or wholly into the
    current h-peak window ('peak')."""
    h = h.copy()
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h
    k = int(round(qfrac * pos.size))
    if k <= 0:
        return h
    order = pos[np.argsort(h[pos])]
    sel = order[:k]
    mass = h[sel].sum()
    h[sel] = 0.0
    if mass <= 0:
        return _rescale(h)
    if mode == 'prop':
        rem = np.flatnonzero(h > 0)
        if rem.size == 0:
            return _rescale(h)
        w = h[rem]
        tot = w.sum()
        if tot <= 0:
            return _rescale(h)
        h[rem] = h[rem] + mass * w / tot
    else:  # peak
        lo, hi = _peak_region(h)
        win = np.arange(lo, hi + 1)
        win = win[h[win] > 0]
        if win.size == 0:
            win = np.flatnonzero(h > 0)
        if win.size == 0:
            return _rescale(h)
        w = h[win]
        tot = w.sum()
        if tot <= 0:
            h[win] += mass / win.size
        else:
            h[win] = h[win] + mass * w / tot
    return _rescale(h)


def _two_sided_revive(h, winL, winR, q2, beta_amp, mode, source='top'):
    """Fill q2 fraction of zero cells in each of winL, winR with constant or
    linear ramp at amplitude beta_amp*mean(positive h). Remove added mass from
    top 1% tallest cells."""
    h = h.copy()
    n = h.size
    pos = h > 0
    if not np.any(pos):
        return h
    mpos = h[pos].mean()
    amp = beta_amp * mpos
    if amp <= 0:
        return h
    zidx = np.flatnonzero(h <= 0)
    if zidx.size == 0:
        return h

    def pick(lo, hi):
        z = zidx[(zidx >= lo) & (zidx < hi)]
        if z.size == 0:
            return np.array([], dtype=int)
        k = int(round(q2 * z.size))
        if k <= 0:
            return np.array([], dtype=int)
        return z[np.linspace(0, z.size - 1, k).astype(int)]

    selL = pick(*winL)
    selR = pick(*winR)
    sel = np.concatenate([selL, selR])
    if sel.size == 0:
        return h
    vals = np.empty(sel.size)
    if mode == 'const':
        vals[:] = amp
    else:
        # linear ramp across each window separately
        for s, (lo, hi) in ((selL, winL), (selR, winR)):
            if s.size == 0:
                continue
            span = max(1, hi - lo)
            t = (s - lo) / span
            # map vals by matching order
        # build vals in sel order
        parts = []
        for s, (lo, hi) in ((selL, winL), (selR, winR)):
            if s.size == 0:
                continue
            span = max(1, hi - lo)
            t = (s - lo) / span
            parts.append(amp * (0.2 + 0.8 * t))
        vals = np.concatenate(parts) if parts else np.full(sel.size, amp)
    added = vals.sum()
    h[sel] = vals
    # remove mass from top 1% tallest (excluding newly added)
    nz = np.flatnonzero(h > 0)
    nz = np.setdiff1d(nz, sel, assume_unique=False)
    if nz.size == 0:
        return _rescale(h)
    topn = max(1, int(0.01 * nz.size))
    order = nz[np.argsort(-h[nz])[:topn]]
    w = h[order]
    tot = w.sum()
    if tot <= 0:
        return _rescale(h)
    h[order] = np.clip(h[order] - added * w / tot, 0.0, None)
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR

    d = _diagnostics(best)
    print("start N=%d R=%.7f zero=%.3f argmax=%d (%.3f) f01=%.3f f1=%.3f f5=%.3f"
          % (d['N'], d['R'], d['zero_frac'], d['argmax'], d['argmax_frac'],
             d['f01'], d['f1'], d['f5']))

    def _try(h, tag):
        nonlocal best, bestR
        if h is None:
            return False
        r = R_of(h)
        print("  %s R=%.7f" % (tag, r))
        if r > bestR + 1e-13:
            best, bestR = h, r
            return True
        return False

    # ---- Step A: quick sharp polish of start ----
    if time.process_time() < deadline - 20.0:
        h = _lbfgs_log(best, 200, min(deadline - 18.0, time.process_time() + 4.0),
                       beta=0.0)
        _try(h, "A sharp")

    # ---- New experiment: rank-prune + two-sided revival ----
    prunes = (0.05, 0.10, 0.20)
    prune_modes = ('prop', 'peak')
    q2s = (0.20, 0.50)
    betas = (0.005, 0.02, 0.05)
    rev_modes = ('const', 'ramp')

    def _sweep(hbase, tag):
        n = hbase.size
        winL = (int(0.05 * n), int(0.30 * n))
        winR = (int(0.55 * n), int(0.95 * n))
        cands = []
        for qp in prunes:
            for pm in prune_modes:
                hp = _prune(hbase, qp, pm)
                for q2 in q2s:
                    for beta in betas:
                        for rm in rev_modes:
                            hc = _two_sided_revive(hp, winL, winR, q2, beta, rm)
                            r = R_of(hc)
                            cands.append((r, hc, (qp, pm, q2, beta, rm)))
        cands.sort(key=lambda x: -x[0])
        top = cands[:3]
        print("  %s top raw: %s" % (tag,
              ", ".join("%.7f" % c[0] for c in top)))
        return top

    def _polish_and_try(hc, params, tag, tleft):
        hp = _lbfgs_log(hc, 200,
                        min(deadline - tleft, time.process_time() + 4.0),
                        beta=0.0)
        got = _try(hp, "%s b0 %s" % (tag, params))
        for beta in (1e3, 1e4, 1e5):
            if time.process_time() >= deadline - tleft + 1.0:
                break
            hp = _lbfgs_log(hp, 150,
                            min(deadline - tleft + 1.0,
                                time.process_time() + 2.0),
                            beta=beta)
            if _try(hp, "%s b%.0e" % (tag, beta)):
                got = True
        if time.process_time() < deadline - tleft + 1.0:
            n = best.size
            free = np.union1d(
                np.union1d(np.arange(int(0.05 * n), int(0.30 * n)),
                           np.arange(int(0.55 * n), int(0.95 * n))),
                _peak_window(best, 0.10, extra=8))
            hp = _lbfgs_block(best, free, 150,
                              min(deadline - tleft + 1.0,
                                  time.process_time() + 3.0),
                              beta=0.0)
            if _try(hp, "%s block" % tag):
                got = True
        return got

    top = _sweep(best, "P1")
    for i, (r, hc, params) in enumerate(top):
        if time.process_time() >= deadline - 12.0:
            break
        _polish_and_try(hc, params, "P2#%d" % i, 10.0)

    # repeat once around new best if time remains
    if time.process_time() < deadline - 8.0:
        top = _sweep(best, "P3")
        for i, (r, hc, params) in enumerate(top):
            if time.process_time() >= deadline - 6.0:
                break
            _polish_and_try(hc, params, "P4#%d" % i, 4.0)

    # ---- Final sharp polish ----
    while time.process_time() < deadline - 1.0:
        hp = _lbfgs_log(best, 250,
                        min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        if not _try(hp, "D sharp"):
            break

    d = _diagnostics(best)
    print("final R=%.7f (N=%d) zero=%.3f f01=%.3f"
          % (bestR, best.size, d['zero_frac'], d['f01']))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    c = np.concatenate(([0.0], np.cumsum(h)))
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            best_R = R_of(best)

    if best is None:
        best = np.ones(1024)
        best_R = R_of(best)

    rng = np.random.RandomState(13579)

    cur = best.copy()
    cur_R = best_R

    # Try to increase resolution beyond start; keep whichever is better.
    if len(cur) < 32768:
        cand = _prolong(cur, 32768)
        cand = _lbfgs_log(cand, 200, deadline)
        r = R_of(cand)
        if r > cur_R:
            cur = cand
            cur_R = r
            if r > best_R:
                best = cand.copy()
                best_R = r

    betas = [8.0, 32.0, 128.0, 512.0, 2048.0, 8192.0, 32768.0]
    peak_fracs = [0.25, 0.12, 0.06, 0.03, 0.015]
    cycle = 0

    while time.process_time() < deadline:
        cycle += 1

        # Global log-space polish with beta homotopy
        for beta in betas:
            if time.process_time() >= deadline:
                break
            cand = _lbfgs_log(cur, 200, deadline, beta=beta)
            r = R_of(cand)
            if r > cur_R + 1e-12:
                cur = cand
                cur_R = r
                if r > best_R + 1e-12:
                    best = cand.copy()
                    best_R = r

        # Peak-window block polish at multiple scales
        for frac in peak_fracs:
            if time.process_time() >= deadline:
                break
            free = _peak_window(cur, frac=frac)
            cand = _lbfgs_block(cur, free, 200, deadline)
            r = R_of(cand)
            if r > cur_R + 1e-12:
                cur = cand
                cur_R = r
                if r > best_R + 1e-12:
                    best = cand.copy()
                    best_R = r

        # Random-window perturbation, accept only on improvement
        if time.process_time() < deadline:
            n = len(cur)
            w = max(8, int(0.05 * n))
            st = rng.randint(0, max(1, n - w))
            pert = cur.copy()
            pert[st:st+w] *= np.exp(rng.normal(0, 0.02, w))
            pert = _lbfgs_log(pert, 150, deadline)
            r = R_of(pert)
            if r > cur_R + 1e-12:
                cur = pert
                cur_R = r
                if r > best_R + 1e-12:
                    best = pert.copy()
                    best_R = r

        print(f"cycle {cycle} N={len(cur)} cur={cur_R:.6f} best={best_R:.6f}")

        if time.process_time() - t0 > budget_seconds * 0.85:
            break

    # Final full polish
    if time.process_time() < deadline:
        cand = _lbfgs_log(best, 400, deadline)
        r = R_of(cand)
        if r > best_R:
            best = cand
            best_R = r

    best = np.clip(best, 0, None)
    if best.sum() <= 0:
        best = np.ones(50)
    print(f"final R={best_R:.6f} N={len(best)}")

    start_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            start_R = R_of(s)

    if best_R >= start_R:
        return best
    return {"best": np.asarray(start, dtype=float), "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _gauss_smooth(h, sigma):
    if sigma <= 0.5:
        return h.copy()
    r = int(3 * sigma) + 1
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return np.convolve(h, k, mode='same')


def _smooth_perturb(h, sigma, amp, seed):
    n = h.size
    rng = np.random.RandomState(seed)
    m = max(16, n // 64)
    noise = rng.randn(m)
    xp = np.linspace(0, 1, m)
    xi = np.linspace(0, 1, n)
    p = np.interp(xi, xp, noise)
    return np.clip(h * np.exp(amp * p), 0, None)


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))
    N = best.size
    alt = None
    altR = 0.0

    betas = [2.0, 8.0, 32.0, 128.0, 512.0, 2048.0]

    def anneal_polish(h0, dl, bs, iters):
        h = h0
        for beta in bs:
            if time.process_time() >= dl - 1.0:
                break
            h = _lbfgs_log(h, iters, dl, beta=beta)
            h = _window_polish_peak(h, dl, 0.35, 16, maxiter=iters, beta=beta)
        return h

    # NEW primary idea: the true optimum has an extremely flat top plateau
    # (many knots within 0.1% of max). The exact max objective is non-smooth
    # there and stalls. We instead reparametrise: at very high beta, log-sum-exp
    # becomes a smooth surrogate for max, letting the optimizer equalise a
    # broad plateau. The key change vs. p0291 is to (a) push beta much higher
    # (up to ~5e4) with a geometric ramp, and (b) after each high-beta step,
    # run a *plateau-flattening* pass that penalises the spread of near-max
    # knots, encouraging the broad plateau that maximises R for a given mass.

    def plateau_flatten(h0, dl, iters=300):
        # minimise variance of top-region knots relative to max, via softmax weighting
        h = h0
        for beta in (4096.0, 16384.0, 65536.0):
            if time.process_time() >= dl - 1.0:
                break
            h = _lbfgs_log(h, iters, dl, beta=beta)
        return h

    # Pass 1: high-beta anneal from start
    if time.process_time() < deadline - 25.0:
        h = anneal_polish(best, deadline - 18.0, betas, 300)
        h = plateau_flatten(h, deadline - 14.0, 250)
        h = _lbfgs_log(h, 600, deadline - 12.0)
        h = _window_polish_peak(h, deadline - 10.0, 0.45, 32)
        r = R_of(h)
        print("anneal R=%.7f" % r)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("anneal wins R=%.7f" % bestR)
        elif r > altR:
            alt, altR = h, r

    # Pass 2: perturb + anneal
    perturb_specs = [
        (max(2.0, N / 300.0), 0.04, 21),
        (max(4.0, N / 150.0), 0.05, 22),
        (max(8.0, N / 80.0), 0.04, 23),
    ]
    for sigma, amp, seed in perturb_specs:
        if time.process_time() >= deadline - 12.0:
            break
        hp = _rescale(_smooth_perturb(best, sigma, amp, seed))
        hp = anneal_polish(hp, deadline - 8.0, betas[:4], 220)
        hp = plateau_flatten(hp, deadline - 6.0, 180)
        hp = _lbfgs_log(hp, 500, deadline - 5.0)
        hp = _window_polish_peak(hp, deadline - 4.0, 0.40, 24)
        r = R_of(hp)
        print("perturb s=%.1f a=%.2f R=%.7f" % (sigma, amp, r))
        if r > altR:
            alt, altR = hp, r
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("perturb wins R=%.7f" % bestR)

    # Pass 3: multi-scale refine
    if time.process_time() < deadline - 8.0:
        for factor in (3, 2):
            if time.process_time() >= deadline - 6.0:
                break
            Nc = max(256, N // factor)
            hc = _rescale(_gauss_smooth(_coarse(best, Nc), sigma=max(1.0, Nc / 400.0)))
            hc = anneal_polish(hc, deadline - 5.0, betas[:4], 220)
            hp = _rescale(_prolongate(hc, N))
            hp = _lbfgs_log(hp, 500, deadline - 4.0)
            hp = plateau_flatten(hp, deadline - 3.0, 180)
            hp = _window_polish_peak(hp, deadline - 2.0, 0.45, 32)
            r = R_of(hp)
            print("prolong %d->%d R=%.7f" % (Nc, N, r))
            if r > altR:
                alt, altR = hp, r
            if r > bestR + 1e-15:
                best, bestR = hp, r

    # Final: alternate exact full/peak polish with high-beta flattening.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 2.0:
            break
        h = plateau_flatten(best, deadline - 1.0, 200)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.45, 32)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and bestR <= startR + 1e-15:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _short_polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 0.5:
        hs = _lbfgs_log(best, 120, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, frac=0.08)
        hs = _lbfgs_block(best, free, 100, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _block_additive(h0, B, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    B = max(1, min(B, n))
    edges = (np.arange(B + 1) * n) // B
    counts = np.diff(edges).astype(float)
    hmax = h.max()
    d0 = np.zeros(B)
    lo_bound = -0.5 * hmax

    def f(d):
        hh = h + np.repeat(d, counts.astype(int))
        hh = np.clip(hh, 0.0, None)
        val, g = _fun_grad(hh)
        gb = np.add.reduceat(g, edges[:-1])
        return val, gb

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, d0, jac=True, method='L-BFGS-B',
                       bounds=[(lo_bound, None)] * B,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    d = res.x
    hh = h + np.repeat(d, counts.astype(int))
    hh = np.clip(hh, 0.0, None)
    return _rescale(hh)


# ---------- Coarsening / prolongation ----------

def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _prolongate(hc, n_target):
    mc = hc.size
    cum_c = np.concatenate(([0.0], np.cumsum(hc)))
    xc = np.linspace(0.0, 1.0, mc + 1)
    xn = np.linspace(0.0, 1.0, n_target + 1)
    cum_n = np.interp(xn, xc, cum_c)
    hn = np.diff(cum_n)
    hn = np.clip(hn, 0.0, None)
    return _rescale(hn)


def _aggregate(h, k, o):
    n = h.size
    if o >= n:
        o = 0
    body = h[o:]
    m = body.size
    full = m // k
    used = full * k
    if full == 0:
        return _rescale(np.array([h.mean()]))
    core = body[:used].reshape(full, k).mean(axis=1)
    tail = body[used:]
    if tail.size > 0:
        extra = tail.sum() / k
        core = np.concatenate((core, [extra]))
    if o > 0:
        head = h[:o].sum() / k
        core = np.concatenate(([head], core))
    return _rescale(np.clip(core, 0.0, None))


def _prolongate_replicate(hc, n_target, k, o):
    rep = np.repeat(hc, k)
    if rep.size == n_target:
        return _rescale(rep)
    return _prolongate(hc, n_target)


# ---------- Gauss-Newton on near-max plateau ----------

def _Jd(h, d, A):
    """J d at indices A, where (J d)_j = 2*conv(h,d)[j-1] for knot index j."""
    c = _conv(h * 1.0) if False else None
    # conv(h,d) length 2N-1; knot index j corresponds to conv index j-1
    if h.size > 1500:
        cd = fftconvolve(h, d)
    else:
        cd = np.convolve(h, d)
    return 2.0 * cd[A - 1]


def _JT(h, y, A, n):
    """J^T y for y defined on A (knot indices). Returns length-n vector.
    (J^T y)_i = 2 * sum_{j in A} y_j * h[j-1-i] (convolution index j-1, valid range)."""
    yp = np.zeros(2 * n - 1)
    valid = (A >= 1) & (A <= 2 * n - 1)
    idx = A[valid] - 1
    yp[idx] = y[valid]
    if n > 1500:
        c = fftconvolve(yp, h[::-1], mode='valid')
    else:
        c = np.correlate(yp, h, mode='valid')
    # c has length n (when yp length 2n-1 and h length n, valid length = n)
    out = np.zeros(n)
    m = min(n, c.size)
    out[:m] = 2.0 * c[:m]
    return out


def _gn_step(h, kappa, lam_scale, deadline, cg_iters=40):
    n = h.size
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return h
    thresh = (1.0 - kappa) * mx
    A = np.flatnonzero(L >= thresh)
    A = A[(A >= 1) & (A <= 2 * n - 1)]
    if A.size == 0:
        return h
    r = L[A] - mx
    # rhs = J^T r
    b = _JT(h, r, A, n)
    bn = np.linalg.norm(b)
    if bn <= 0:
        return h
    lam = lam_scale * bn

    # CG on (J^T J + lam I) d = b
    d = np.zeros(n)
    res = b.copy()
    p = res.copy()
    rs = res @ res
    for it in range(cg_iters):
        if time.process_time() > deadline:
            break
        Jp = _Jd(h, p, A)
        Ap = _JT(h, Jp, A, n) + lam * p
        pAp = p @ Ap
        if pAp <= 1e-300:
            break
        alpha = rs / pAp
        d += alpha * p
        res -= alpha * Ap
        rs_new = res @ res
        if rs_new < 1e-20 * (b @ b):
            break
        beta = rs_new / rs
        p = res + beta * p
        rs = rs_new
    return d


def _gn_try(h, bestR, kappa, lam_scale, deadline):
    d = _gn_step(h, kappa, lam_scale, deadline)
    if d is None or not np.any(d):
        return h, bestR
    alpha = 1.0
    for _ in range(20):
        if time.process_time() > deadline:
            break
        hn = np.clip(h + alpha * d, 0.0, None)
        if hn.sum() <= 0:
            alpha *= 0.5
            continue
        rn = R_of(hn)
        if rn > bestR + 1e-14:
            return hn, rn
        alpha *= 0.5
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    n_fine = best.size
    bestH = best.copy()
    bestRH = bestR
    experiment_best = best.copy()
    experiment_bestR = bestR

    # ---- Gauss-Newton on coarsened (pairwise-mean) representation ----
    h2 = _coarsen(bestH)
    r2 = R_of(h2)
    print("coarsen N=%d R=%.9f (orig %.9f, diff %.2e)" %
          (h2.size, r2, bestRH, r2 - bestRH))
    gn_h = h2.copy()
    gn_R = r2

    def diag(h):
        L = _knots(h)
        mx = L.max()
        # RMS deviation of near-max plateau (top 20% within 0.1% of max)
        sel = L >= 0.999 * mx
        if sel.sum() == 0:
            return 0.0
        return float(np.sqrt(np.mean((L[sel] - mx) ** 2)))

    d0 = diag(gn_h)
    print("GN start: R=%.9f plateau RMS=%.3e" % (gn_R, d0))

    kappas = [0.05, 0.02, 0.01]
    lams = [1e-6, 1e-4, 1e-2]
    gn_deadline = min(deadline - 3.0, t0 + budget_seconds * 0.55)

    round_i = 0
    while time.process_time() < gn_deadline:
        round_i += 1
        improved = False
        for kappa in kappas:
            if time.process_time() >= gn_deadline:
                break
            for lam in lams:
                if time.process_time() >= gn_deadline:
                    break
                hn, rn = _gn_try(gn_h, gn_R, kappa, lam,
                                 min(gn_deadline, time.process_time() + 3.0))
                if rn > gn_R + 1e-14:
                    gn_h, gn_R = hn, rn
                    improved = True
                    print("  GN round=%d kappa=%.2f lam=%.0e -> R=%.9f" %
                          (round_i, kappa, lam, gn_R))
        if not improved:
            break
        # 2 s polish after each GN step
        if time.process_time() < gn_deadline - 1.0:
            cap = min(gn_deadline, time.process_time() + 2.0)
            hp, rp = _short_polish(gn_h, cap, gn_R)
            if rp > gn_R:
                gn_h, gn_R = hp, rp
                print("  GN polish -> R=%.9f" % gn_R)

    d1 = diag(gn_h)
    print("GN end: R=%.9f plateau RMS=%.3e (was %.3e)" % (gn_R, d1, d0))

    # Prolongate GN result back to fine and polish
    if gn_R > r2 + 1e-14:
        hf = _prolongate(gn_h, n_fine)
        rf = R_of(hf)
        print("  prolong GN -> R=%.9f" % rf)
        if time.process_time() < deadline - 3.0:
            cap = min(deadline - 2.0, time.process_time() + 6.0)
            hp, rp = _polish(hf, cap, rf)
            print("  prolong GN polished -> R=%.9f" % rp)
            if rp > experiment_bestR + 1e-13:
                experiment_best, experiment_bestR = hp.copy(), rp
                print("  NEW EXPERIMENT BEST R=%.9f" % experiment_bestR)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  NEW BEST R=%.9f" % bestRH)

    # ---- Full-N GN attempt if time remains ----
    if time.process_time() < deadline - 8.0:
        gn_hf = bestH.copy()
        gn_Rf = bestRH
        gn_deadline2 = min(deadline - 4.0, time.process_time() + 8.0)
        for kappa in kappas:
            if time.process_time() >= gn_deadline2:
                break
            for lam in lams:
                if time.process_time() >= gn_deadline2:
                    break
                hn, rn = _gn_try(gn_hf, gn_Rf, kappa, lam,
                                 min(gn_deadline2, time.process_time() + 3.0))
                if rn > gn_Rf + 1e-14:
                    gn_hf, gn_Rf = hn, rn
                    print("  fullN GN kappa=%.2f lam=%.0e -> R=%.9f" %
                          (kappa, lam, gn_Rf))
        if gn_Rf > bestRH + 1e-13:
            bestH, bestRH = gn_hf, gn_Rf
            print("  NEW BEST (fullN GN) R=%.9f" % bestRH)
        if gn_Rf > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = gn_hf.copy(), gn_Rf

    # ---- Remaining time: block-additive passes on best ----
    for B in (256, 512, 1024):
        if time.process_time() >= deadline - 2.0:
            break
        cap_t = min(deadline - 1.0, time.process_time() + 6.0)
        hb = _block_additive(bestH, B, cap_t, maxiter=150)
        r_raw = R_of(hb)
        if r_raw >= bestRH - 2e-3:
            hp, rp = _polish(hb, min(deadline - 0.5, time.process_time() + 6.0), bestRH)
        else:
            hp, rp = hb, r_raw
        print("  B=%-4d raw R=%.9f polished R=%.9f" % (B, r_raw, rp))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("    NEW BEST R=%.9f" % bestRH)

    # final polish loop
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap_t = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap_t, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, bestRH))
            continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.05 + 0.10 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 150, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, bestRH))

    print("final R=%.9f (best of experiment)" % bestRH)
    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        alt = experiment_best if experiment_bestR > start_bestR + 1e-12 else start_best
        return {"best": bestH, "alternative": alt}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.15):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(32, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _upsample_lin(h, factor):
    n = h.size
    m = n * factor
    x = np.linspace(0, n - 1, m)
    return np.interp(x, np.arange(n), h)


def _coarse_refine(h, deadline, factor=2):
    """Upsample linearly, polish coarse, return upsampled-polished result.

    Idea: at fine resolution the max-knot term is nearly flat over a wide
    plateau, so L-BFGS crawls. Solving a coarser problem (where the peak
    is sharper relative to grid) then refining breaks that plateau."""
    n = h.size
    hu = _upsample_lin(h, factor)
    hu = _rescale(hu)
    sub_dl = min(deadline, time.process_time() + 6.0)
    hp = _lbfgs_log(hu, 400, sub_dl)
    return hp


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f N=%d" % (bestR, best.size))

    bestH = best.copy()
    bestRH = bestR

    # (1) Beta-smoothed polish of the peak region: main blocker at fine N
    # is that the max knot is flat over a plateau; smoothing helps.
    if time.process_time() < deadline - 25.0:
        win = _peak_window(bestH, frac=0.20)
        for beta in (20.0, 80.0, 300.0, 1200.0, 5000.0):
            if time.process_time() > deadline - 22.0:
                break
            sub_dl = min(deadline - 20.0, time.process_time() + 4.0)
            hp = _lbfgs_block(bestH, win, 150, sub_dl, beta=beta)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  beta=%.0f peak R=%.7f" % (beta, bestRH))

    # (2) Beta-smoothed full polish
    if time.process_time() < deadline - 16.0:
        for beta in (50.0, 200.0, 800.0):
            if time.process_time() > deadline - 15.0:
                break
            sub_dl = min(deadline - 13.0, time.process_time() + 4.0)
            hp = _lbfgs_log(bestH, 200, sub_dl, beta=beta)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  beta=%.0f full R=%.7f" % (beta, bestRH))

    # (3) NEW: upsample -> coarse-refine -> downscale-to-original comparison.
    #     A coarser problem has a sharper peak relative to grid, so L-BFGS
    #     makes more progress against the flat max plateau.
    if time.process_time() < deadline - 8.0 and bestH.size <= 250000:
        factor = 2
        try:
            hu = _upsample_lin(bestH, factor)
            hu = _rescale(hu)
            sub_dl = min(deadline - 6.0, time.process_time() + 8.0)
            hp = _lbfgs_log(hu, 500, sub_dl)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  upsample x%d R=%.7f" % (factor, bestRH))
        except Exception:
            pass

    # (4) Final sharp full polish
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 600, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d zeros %.1f%%) argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

