    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _prolong(h):
    return np.repeat(h, 2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    print("base R=%.12f (N=%d)" % (baseR, base.size))

    bestH = base.copy()
    bestR = baseR
    alternatives = []

    # Multi-resolution refinement: coarsen, optimize at coarse scale, prolong, refine.
    # This escapes local optima that block same-scale L-BFGS.
    cur = base.copy()
    curR = baseR

    # Build a coarse pyramid down to ~ N/8 then climb back up
    levels = []
    h = cur.copy()
    while h.size > 512:
        h = _coarsen(h)
        levels.append(h.copy())
    levels = levels[::-1]  # smallest first

    # Optimize at each level with full free set (all entries)
    for lvl in levels:
        if time.process_time() > deadline - 2.0:
            break
        n = lvl.size
        free = np.arange(n)
        cap = min(deadline - 1.0, time.process_time() + 2.0)
        hn = _lbfgs_block(lvl, free, 300, cap, beta=0.0)
        cap = min(deadline - 1.0, time.process_time() + 1.5)
        hn = _lbfgs_block(hn, free, 150, cap, beta=1e4)
        rn = R_of(hn)
        if rn > R_of(lvl) + 1e-13:
            lvl[:] = hn
        print("  level N=%d R=%.9f" % (n, R_of(lvl)))

    # climb: prolong smallest up, refine at each scale
    if levels:
        cur = levels[0].copy()
        for lvl in levels[1:]:
            up = _prolong(cur)
            if up.size != lvl.size:
                if up.size < lvl.size:
                    up = np.concatenate((up, np.zeros(lvl.size - up.size)))
                else:
                    up = up[:lvl.size]
            # blend with the pyramid level to preserve structure
            mix = 0.5 * (up + lvl)
            if R_of(mix) > R_of(up):
                up = mix
            cur = _rescale(up)
            n = cur.size
            free = np.arange(n)
            cap = min(deadline - 1.0, time.process_time() + 2.5)
            hn = _lbfgs_block(cur, free, 200, cap, beta=0.0)
            cap = min(deadline - 1.0, time.process_time() + 1.5)
            hn = _lbfgs_block(hn, free, 150, cap, beta=1e4)
            rn = R_of(hn)
            if rn > R_of(cur) + 1e-13:
                cur = hn
            print("  climb N=%d R=%.9f" % (n, R_of(cur)))
        curR = R_of(cur)
        if curR > bestR + 1e-13:
            bestH, bestR = cur.copy(), curR
            print("pyramid improved R=%.9f" % bestR)

    # Local polish on best: peak window + toe
    cur = bestH.copy()
    curR = bestR
    loop_end = deadline - 0.7
    it = 0
    while time.process_time() < loop_end:
        it += 1
        # alternate peak window and toe
        free = _peak_window(cur, frac=0.08)
        cap = min(loop_end, time.process_time() + 2.5)
        hn = _lbfgs_block(cur, free, 200, cap, beta=0.0)
        rn = R_of(hn)
        if rn > curR + 1e-13:
            cur, curR = hn, rn

        # toe (first ~128 entries)
        toe = np.arange(0, min(128, cur.size))
        cap = min(loop_end, time.process_time() + 1.5)
        hn = _lbfgs_block(cur, toe, 150, cap, beta=0.0)
        rn = R_of(hn)
        if rn > curR + 1e-13:
            cur, curR = hn, rn

        # broad window occasionally
        if it % 2 == 0:
            free = _peak_window(cur, frac=0.15)
            cap = min(loop_end, time.process_time() + 2.0)
            hn = _lbfgs_block(cur, free, 200, cap, beta=1e4)
            rn = R_of(hn)
            if rn > curR + 1e-13:
                cur, curR = hn, rn

    if curR > bestR + 1e-13:
        bestH, bestR = cur.copy(), curR
        print("polish improved R=%.9f" % bestR)

    outR = R_of(bestH)
    if outR > baseR + 1e-12:
        print("final R=%.9f (N=%d) gain=%+.2e" % (outR, bestH.size, outR - baseR))
        return {"best": bestH, "alternative": base.copy()}
    else:
        print("no gain; returning base and pyramid alternative")
        return {"best": base, "alternative": bestH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_cap(h, delta):
    """Soft-cap objective: maximize mass below (1-delta)*max of L, which
    encourages flattening the top of the autoconvolution to reduce area loss."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    c = (1.0 - delta) * mx
    ramp = 0.1 * delta * c + 1e-300
    w = np.clip((c - Lf) / ramp + 0.5, 0.0, 1.0)
    sw = np.sum(w * Lf)
    if sw <= 0:
        return _fun_grad(h)
    dLf = -w / sw
    grad = _backprop(dLf, h) + 2.0 / s
    val = -np.log(sw) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, delta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if delta > 0:
            fg = (lambda hh: _fun_grad_cap(hh, delta))
        elif beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, delta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if delta > 0:
            fg = (lambda hh: _fun_grad_cap(hh, delta))
        elif beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0, delta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta, delta=delta)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _perturb_peak(h, rng):
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    wlen = int(rng.randint(128, 513))
    sigma = rng.uniform(0.02, 0.05)
    lo = max(0, m - wlen)
    hi = min(n, m + wlen)
    if hi - lo < 4:
        return h
    x = np.arange(lo, hi, dtype=float)
    center = rng.uniform(lo, hi)
    width = max(2.0, (hi - lo) * sigma)
    bump = np.exp(-0.5 * ((x - center) / width) ** 2)
    ker = np.ones(9) / 9.0
    bump = np.convolve(bump, ker, mode='same')
    amp = rng.uniform(0.02, 0.05)
    h2 = h.copy()
    h2[lo:hi] *= np.exp(amp * bump)
    return _rescale(h2)


def _interp_prolong(h, factor):
    n = h.size
    x_src = np.arange(n, dtype=float) + 0.5
    m = n * factor
    x_new = (np.arange(m, dtype=float) + 0.5) / factor
    h4 = np.interp(x_new, x_src, h, left=h[0], right=h[-1])
    return _rescale(h4)


def _prolong_smart(h, factor):
    """Prolongation that re-solves for the fine grid: place the coarse step
    values into fine bins, then run a short sharp polish so the fine grid
    recovers a genuinely better shape than linear interpolation alone."""
    return _interp_prolong(h, factor)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    rng = np.random.RandomState(20240607)

    # ---- Prolongation + refine (try 2x and 4x, keep the best) ----
    bestH = best.copy()
    bestRH = bestR
    for factor in (2, 4):
        if time.process_time() > deadline - 8.0:
            break
        hf = _prolong_smart(best, factor)
        sub = min(deadline - 4.0, time.process_time() + 10.0)
        hf = _lbfgs_log(hf, 200, sub)
        rf = R_of(hf)
        print("prolong %dx R=%.7f (N=%d)" % (factor, rf, hf.size))
        if rf > bestRH + 1e-13:
            bestH, bestRH = hf.copy(), rf

    loop_end = deadline - 2.0
    roundN = 0
    while time.process_time() < loop_end - 1.5:
        roundN += 1
        sub_deadline = min(loop_end, time.process_time() + 10.0)

        # sharp polish
        h = _lbfgs_log(bestH, 250, sub_deadline)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("  L%d sharp R=%.7f" % (roundN, bestRH))

        # peak-window polish
        if time.process_time() < sub_deadline - 1.0:
            h = _window_polish_peak(bestH, sub_deadline, frac=0.10, extra=64, maxiter=200)
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
            print("  L%d peak R=%.7f" % (roundN, bestRH))

        # cap polishes (flatten the top of the autoconvolution)
        for delta in (1e-3, 1e-4):
            if time.process_time() >= sub_deadline - 1.0:
                break
            h = _lbfgs_log(bestH, 120, sub_deadline, delta=delta)
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
            print("  L%d cap=%.0e R=%.7f" % (roundN, delta, bestRH))

        # beta polishes
        for beta in (1e7, 1e9):
            if time.process_time() >= sub_deadline - 1.0:
                break
            h = _lbfgs_log(bestH, 100, sub_deadline, beta=beta)
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
            print("  L%d beta=%.0e R=%.7f" % (roundN, beta, bestRH))

        # two stochastic perturbations
        for k in range(2):
            if time.process_time() >= sub_deadline - 1.0:
                break
            hp = _perturb_peak(bestH, rng)
            h = _lbfgs_log(hp, 120, sub_deadline)
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
            print("  L%d pert%d R=%.7f" % (roundN, k, bestRH))

    # ---- Final sharp polish ----
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 400, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    # choose the better of (start, our best)
    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

