    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    """Softmax-smoothed ||f*f||_inf so gradients flow to all near-max knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _largest_zero_gap(h):
    n = h.size
    thresh = 1e-9 * h.max() if h.max() > 0 else 0.0
    zero = h <= thresh
    best_len = 0
    best_mid = None
    i = 0
    while i < n:
        if zero[i]:
            j = i
            while j < n and zero[j]:
                j += 1
            if i > 0 and j < n:
                L = j - i
                if L > best_len:
                    best_len = L
                    best_mid = (i + j) // 2
            i = j
        else:
            i += 1
    if best_mid is None:
        return n // 2
    return best_mid


def _shift_right(h, k, delta):
    n = h.size
    out = np.zeros(n)
    out[:k] = h[:k]
    right = h[k:]
    m = right.size
    if delta == 0:
        out[k:] = right
        return out
    if delta > 0:
        d = min(delta, n - k)
        out[k + d:k + d + m] = right[:max(0, n - (k + d))]
    else:
        d = -delta
        start = max(0, k - d)
        end = min(n, start + m)
        out[start:end] = right[:end - start]
    return out


def _stretch_right(h, k, factor):
    n = h.size
    out = np.zeros(n)
    out[:k] = h[:k]
    right = h[k:]
    m = right.size
    if m < 2:
        out[k:] = right
        return out
    S = np.concatenate(([0.0], np.cumsum(right)))
    new_len = int(round(m * factor))
    new_len = max(2, min(new_len, n - k))
    xs = np.linspace(0.0, 1.0, m + 1)
    xb = np.linspace(0.0, 1.0, new_len + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    new_right = np.clip(np.diff(Sb), 0.0, None)
    out[k:k + new_len] = new_right
    return out


def _subdivide(h):
    """Split each step into two equal halves (exact refinement)."""
    out = np.empty(h.size * 2)
    out[0::2] = h
    out[1::2] = h
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    orig_deadline = deadline

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_h = best.copy()
    start_R = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alternative = None

    # ---- Phase 1: softmax-polish the start at its native resolution ----
    # The key new idea: use a smoothed ||f*f||_inf (log-sum-exp) so gradient
    # flows into ALL near-max knots, not just the single argmax. This is
    # especially effective when many knots are within 0.1% of the max.
    for beta in (30.0, 100.0, 300.0, 1000.0):
        if time.process_time() >= deadline - 3.0:
            break
        h = _lbfgs_log(best, 500, deadline, beta=beta)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("softbeta %.0f R=%.7f" % (beta, bestR))

    # ---- Phase 2: peak-window polish with softmax ----
    if time.process_time() < deadline - 3.0:
        h = _window_polish_peak(best, deadline, 0.40, 24, maxiter=600, beta=300.0)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win soft R=%.7f" % bestR)

    # ---- Phase 3: try refinement (subdivide) then re-polish ----
    # On a finer grid the optimizer has more freedom near the peak.
    if best.size < 400000 and time.process_time() < deadline - 6.0:
        hf = _subdivide(best)
        hf = _rescale(hf)
        # polish only after a short run to test; keep if better
        h2 = _lbfgs_log(hf, 300, deadline, beta=100.0)
        r = R_of(h2)
        print("subdiv R=%.7f" % r)
        if r > bestR + 1e-15:
            best, bestR = h2, r
            print("  -> new best %.7f" % bestR)
        else:
            if alternative is None:
                alternative = h2

    # ---- Phase 4: shift/stretch exploration of the right cluster ----
    k = _largest_zero_gap(best)
    print("split at %d (of %d)" % (k, best.size))

    def _try_shift(hp, tag):
        nonlocal best, bestR
        if hp.sum() <= 0:
            return
        hp = _rescale(hp)
        hp = _lbfgs_log(hp, 300, deadline, beta=200.0)
        if time.process_time() < deadline - 2.0:
            hp = _window_polish_peak(hp, deadline, 0.35, 16, maxiter=300, beta=200.0)
        r = R_of(hp)
        print("%s R=%.7f" % (tag, r))
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("  -> new best %.7f" % bestR)

    for delta in (1, -1, 2, -2, 4, -4, 8, -8):
        if time.process_time() >= deadline - 4.0:
            break
        hp = _shift_right(best, k, delta)
        _try_shift(hp, "shift %+d" % delta)

    for factor in (0.99, 1.01, 1.02):
        if time.process_time() >= deadline - 4.0:
            break
        hp = _stretch_right(best, k, factor)
        _try_shift(hp, "stretch %.2f" % factor)

    # ---- Phase 5: alternate full / peak polish with softmax, until time ----
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        for beta in (100.0, 300.0, 0.0):
            if time.process_time() >= deadline - 1.5:
                break
            h = _lbfgs_log(best, 600, deadline, beta=beta)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h, r
                improved = True
                print("full b%.0f R=%.7f" % (beta, bestR))
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24, maxiter=400, beta=300.0)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    # Ensure we never regress below the start
    if R_of(best) < start_R:
        best = start_h
        bestR = start_R

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    if alternative is not None and R_of(alternative) > start_R + 1e-12 and R_of(alternative) < bestR:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    c = np.concatenate(([0.0], np.cumsum(h)))
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def _prolongate(h, n_new):
    r0 = R_of(h)
    cand = _prolong(h, n_new)
    cand = cand * (h.sum() / max(cand.sum(), 1e-300))
    cand = _rescale(cand)
    r1 = R_of(cand)
    if abs(r1 - r0) > 1e-6 * max(1.0, abs(r0)):
        rep = int(round(n_new / len(h)))
        if rep >= 1 and rep * len(h) == n_new:
            cand = np.repeat(h, rep)
        else:
            cand = _prolong(h, n_new)
        cand = _rescale(cand)
    return cand


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _cycle(cur, cur_R, best, best_R, deadline, betas, fracs,
           it_beta=60, it_frac=100, it_sharp=80, tag=""):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        cand = _lbfgs_log(cur, it_beta, deadline, beta=beta)
        r = R_of(cand)
        if r > cur_R + 1e-12:
            cur = cand
            cur_R = r
            if r > best_R + 1e-12:
                best = cand.copy()
                best_R = r
        print(f"  {tag} beta={beta:.0e} R={cur_R:.6f} best={best_R:.6f}")
    for frac in fracs:
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(cur, frac=frac)
        cand = _lbfgs_block(cur, free, it_frac, deadline)
        r = R_of(cand)
        if r > cur_R + 1e-12:
            cur = cand
            cur_R = r
            if r > best_R + 1e-12:
                best = cand.copy()
                best_R = r
        print(f"  {tag} frac={frac} R={cur_R:.6f} best={best_R:.6f}")
    if time.process_time() < deadline - 0.5:
        cand = _lbfgs_log(cur, it_sharp, deadline, beta=0.0)
        r = R_of(cand)
        if r > cur_R + 1e-12:
            cur = cand
            cur_R = r
            if r > best_R + 1e-12:
                best = cand.copy()
                best_R = r
        print(f"  {tag} sharp R={cur_R:.6f} best={best_R:.6f}")
    return cur, cur_R, best, best_R


def _zero_revival(h, deadline, frac):
    n = h.size
    zeros = np.flatnonzero(h <= 1e-13 * max(h.max(), 1e-300))
    if zeros.size == 0:
        return h, 0.0
    # adjacent to nonzero support
    nz = h > 1e-13 * max(h.max(), 1e-300)
    adj = np.zeros(n, dtype=bool)
    if n > 1:
        adj[1:] |= nz[:-1]
        adj[:-1] |= nz[1:]
    cand_z = zeros[adj[zeros]]
    if cand_z.size == 0:
        return h, 0.0
    rng = np.random.default_rng(12345)
    k = max(1, int(frac * cand_z.size))
    pick = rng.choice(cand_z, size=k, replace=False)
    h2 = h.copy()
    for i in pick:
        nb = []
        if i > 0 and h[i-1] > 0:
            nb.append(h[i-1])
        if i < n-1 and h[i+1] > 0:
            nb.append(h[i+1])
        if nb:
            h2[i] = 0.3 * np.mean(nb)
    h2 = _rescale(h2)
    r0 = R_of(h)
    cand = _lbfgs_log(h2, 60, deadline, beta=0.0)
    r1 = R_of(cand)
    return (cand, r1 - r0) if r1 > r0 else (h, r1 - r0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            best_R = R_of(best)

    if best is None:
        best = np.ones(1024)
        best_R = R_of(best)

    cur = best.copy()
    cur_R = best_R

    # Skip 32768: go straight to 65536.
    if len(cur) < 65536:
        cand = _prolongate(cur, 65536)
        cand = _lbfgs_log(cand, 200, deadline, beta=0.0)
        r = R_of(cand)
        if r > cur_R - 1e-9:
            cur = cand
