                                              tag=f"h{c+1}")
            print(f"cycle128 {c+1} N={len(cur)} cur={cur_R:.6f} best={best_R:.6f}")

    # (4) Final full-vector beta=0 polish at largest N.
    if time.process_time() < deadline - 0.5:
        cand = _lbfgs_log(best, 600, deadline, beta=0.0)
        r = R_of(cand)
        if r > best_R:
            best = cand
            best_R = r

    best = np.clip(best, 0, None)
    if best.sum() <= 0:
        best = np.ones(50)
    print(f"final R={best_R:.6f} N={len(best)}")

    start_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            start_R = R_of(s)

    if best_R >= start_R:
        return best
    return {"best": np.asarray(start, dtype=float), "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _gauss_smooth(h, sigma=1.5):
    r = 3
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    hp = np.concatenate((np.full(r, h[0]), h, np.full(r, h[-1])))
    return np.convolve(hp, k, mode='valid')


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _upsample_lin(h, factor):
    n = h.size
    m = n * factor
    x = np.linspace(0, n - 1, m)
    return np.interp(x, np.arange(n), h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None and np.asarray(start).size > 0 and np.sum(start) > 0:
        base = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = R_of(base)
        best = base.copy()
    else:
        N = 4096
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)
    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f N=%d" % (bestR, best.size))

    def try_fine(name, cand):
        nonlocal best, bestR
        r = R_of(cand)
        if r > bestR + 1e-13:
            best, bestR = cand.copy(), r
            print("  %s NEW R=%.9f" % (name, bestR))
            return True
        return False

    loop_end = deadline - 1.0
    it = 0
    stall = 0
    # Track a "refined" high-res candidate separately: try upsampling the
    # best solution and locally polishing at higher resolution. This is the
    # main new lever: finer discretization can squeeze out extra R.
    hi_best = None
    hi_bestR = -1.0
    next_hi_time = time.process_time() + 8.0

    while time.process_time() < loop_end:
        it += 1
        improved = False
        cap = min(loop_end, time.process_time() + 6.0)
        hs = _lbfgs_log(best, 400, cap)
        if try_fine("full it=%d" % it, hs):
            improved = True
        else:
            stall += 1

        if time.process_time() < loop_end - 1.0 and stall >= 1:
            free = _peak_window(best, frac=0.04)
            cap = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(best, free, 150, cap)
            if try_fine("peak it=%d" % it, hp):
                improved = True
                stall = 0

        # Periodically attempt a resolution upgrade: upsample best by 2x
        # and do a short log-param optimization at the finer grid.
        now = time.process_time()
        if now >= next_hi_time and now < loop_end - 5.0:
            next_hi_time = now + 12.0
            try:
                up = _rescale(_upsample_lin(best, 2))
                cap = min(loop_end, now + 5.0)
                hup = _lbfgs_log(up, 250, cap)
                rup = R_of(hup)
                if rup > bestR + 1e-13:
                    best, bestR = hup, rup
                    print("  up2 it=%d NEW R=%.9f N=%d" % (it, bestR, best.size))
                    improved = True
                    stall = 0
                if hi_best is None or rup > hi_bestR:
                    hi_best, hi_bestR = hup, rup
            except Exception:
                pass

        if time.process_time() < loop_end - 1.0 and stall >= 2:
            A = _rescale(np.repeat(best, 2))
            B = _rescale(np.repeat(_gauss_smooth(best, 1.5), 2))
            RA, RB = R_of(A), R_of(B)
            cand = A if RA >= RB else B
            cap = min(loop_end, time.process_time() + 4.0)
            hc = _lbfgs_log(cand, 200, cap)
            if try_fine("prolong it=%d" % it, hc):
                improved = True
                stall = 0
            else:
                stall = 0

    if bestR < start_bestR:
        best, bestR = start_best, start_bestR

    print("final R=%.9f N=%d" % (bestR, best.size))

    # Return alternative as the best genuinely-different high-res attempt.
    alt = hi_best if (hi_best is not None and hi_best.size != start_best.size) else None
    if alt is not None and R_of(alt) <= start_bestR:
        return {"best": best, "alternative": alt}
    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

