    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _refine_at_N(cur, curR, deadline, betas, tag=""):
    gained = False
    while time.process_time() < deadline - 3.0:
        hb = _lbfgs_log(cur, 250, deadline)
        rb = R_of(hb)
        if rb > curR + 1e-13:
            cur, curR = hb, rb
            gained = True
            print("    %slbfgs R=%.7f (N=%d)" % (tag, curR, cur.size))
        for beta in betas:
            if time.process_time() >= deadline - 4.0:
                break
            hb = _lbfgs_log(cur, 120, deadline, beta=beta)
            hs = _lbfgs_log(hb, 5, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.10, 64, maxiter=150)
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            if rc > curR + 1e-13:
                cur, curR = cand, rc
                gained = True
                print("    %sbeta=%.0e R=%.7f (N=%d)" % (tag, beta, curR, cur.size))
        if time.process_time() < deadline - 3.0:
            hp = _window_polish_peak(cur, deadline, 0.03, 32, maxiter=150)
            rp = R_of(hp)
            if rp > curR + 1e-13:
                cur, curR = hp, rp
                gained = True
                print("    %speak R=%.7f (N=%d)" % (tag, curR, cur.size))
    return cur, curR, gained


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    betas = (1e4, 1e5, 1e6, 1e7, 1e8)

    # Key change: instead of duplicating (which never gains), do a strong
    # refinement pass at the *original* N first, then try 2x only if it helps.
    cur, curR = best.copy(), bestR
    cur, curR, _ = _refine_at_N(cur, curR, t0 + budget_seconds * 0.55, betas, tag="N0 ")
    if curR > bestR + 1e-13:
        best, bestR = cur.copy(), curR

    # Try one doubling; accept only if it clearly helps (keeps alternative otherwise).
    if time.process_time() < deadline - 8.0:
        h2 = np.repeat(best, 2)
        h2 = _rescale(h2 * rng.lognormal(0.0, 1e-5, size=h2.size))
        r2 = R_of(h2)
        cur2, cur2R = h2, r2
        cur2, cur2R, _ = _refine_at_N(cur2, cur2R, deadline, betas, tag="N2 ")
        if cur2R > bestR + 1e-12:
            best, bestR = cur2.copy(), cur2R

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 200, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 1e-300, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w / Pm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _report(tag, h, R):
    mean = h.mean()
    ratio = (h.max() / mean) if mean > 0 else 0.0
    print("  %s R=%.7f zeros=%.1f%% max/mean=%.2f" %
          (tag, R, 100.0 * np.mean(h <= 0), ratio))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 16384
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    _report("base", best, bestR)

    cur = best.copy()
    curR = bestR

    # Phase 1: p-norm polish to break plateaus near the peak.
    for p in (40.0, 100.0, 300.0):
        if time.process_time() > deadline - 3.0:
            break
        h = _lbfgs_log(cur, 120, min(deadline - 2.0,
                                     time.process_time() + 5.0),
                       fg=(lambda hh, pp=p: _fun_grad_pnorm(hh, pp)))
        r = R_of(h)
        if r > curR + 1e-13:
            cur, curR = h.copy(), r
            best, bestR = cur.copy(), curR

    # Phase 2: multi-scale prolongation. Try a couple of factors, polish
    # with p-norm + peak-window block.
    scale_end = t0 + budget_seconds * 0.50
    factors = [2, 3, 2]
    fi = 0
    while time.process_time() < scale_end - 5.0:
        factor = factors[fi % len(factors)]
        fi += 1
        seed = np.repeat(cur, factor).astype(float)
        seed = _rescale(seed)
        sub_end = min(scale_end, time.process_time() + 9.0)
        h = _lbfgs_log(seed, 200, sub_end)
        r = R_of(h)
        if time.process_time() < sub_end - 2.0:
            m = int(np.argmax(_knots(h)))
            w = 250 * factor
            wlo = max(0, m - w)
            whi = min(h.size - 1, m + w)
            h2 = _lbfgs_block(h, np.arange(wlo, whi + 1), 150, sub_end)
            r2 = R_of(h2)
            if r2 > r:
                h, r = h2, r2
        if time.process_time() < sub_end - 2.0:
            h3 = _lbfgs_log(h, 100, sub_end,
                            fg=(lambda hh: _fun_grad_pnorm(hh, 80.0)))
            r3 = R_of(h3)
            if r3 > r:
                h, r = h3, r3
        print("  scale x%d R=%.7f (cur=%.7f best=%.7f)" %
              (factor, r, curR, bestR))
        if r > curR + 1e-13:
            cur, curR = h.copy(), r
            if r > bestR + 1e-13:
                best, bestR = h.copy(), r
                _report("scale x%d keep" % factor, best, bestR)

    # Phase 3: full-array polish + p-norm rounds until deadline.
    full = np.arange(cur.size)
    round_idx = 0
    while time.process_time() < deadline - 1.5:
        round_idx += 1
        sub_deadline = min(deadline - 0.8, time.process_time() + 7.0)
        h = _lbfgs_block(cur, full, 120, sub_deadline)
        r = R_of(h)
        if r > curR + 1e-13:
            cur, curR = h.copy(), r
        if time.process_time() < sub_deadline - 1.0:
            h = _lbfgs_log(cur, 100, sub_deadline)
            r = R_of(h)
            if r > curR + 1e-13:
                cur, curR = h.copy(), r
        if round_idx % 2 == 0 and time.process_time() < sub_deadline - 1.0:
            h = _lbfgs_log(cur, 80, sub_deadline,
                           fg=(lambda hh: _fun_grad_pnorm(hh, 80.0)))
            r = R_of(h)
            if r > curR + 1e-13:
                cur, curR = h.copy(), r
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR

    _report("final", best, bestR)

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    n = h.size
    if n > 1500:
        L = fftconvolve(h, h)[:2 * n - 1]
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    m = L.max()
    if m <= 0:
        return -1.0
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    return float(num / (s * s * m))


def _num_and_dq(L):
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(L)
    dq[:-1] += (2.0 * a + b) / 3.0
    dq[1:] += (a + 2.0 * b) / 3.0
    return num, dq


def _backprop(gLf, h):
    n = h.size
    gL = gLf[1:-1]
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _fun_grad(h, beta=0.0):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    L = _knots(h)
    num, dq = _num_and_dq(L)
    if num <= 0:
        return 1e18, np.zeros(h.size)
    M = L.max()
    if beta > 0:
        e = np.exp(beta * (L - M))
        Z = e.sum()
        sm = M + np.log(Z) / beta
        w = e / Z
        gL = -dq / num + w / sm
        val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    else:
        k = int(np.argmax(L))
        gL = -dq / num
        gL[k] += 1.0 / M
        val = -np.log(num) + 2.0 * np.log(s) + np.log(M)
    gh = _backprop(gL, h) + 2.0 / s
    return val, gh


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolongate(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    xs = np.linspace(0.0, total, N + 1)
    out = np.interp(xs, c, np.arange(M + 1, dtype=float))
    idx = np.clip(np.floor(out).astype(int), 0, M - 1)
    return np.maximum(h[idx], 0.0)


def _peak_window(h, frac=0.15):
    L = _knots(h)
    m = int(np.argmax(L))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    def time_left():
        return time.process_time() < deadline - 0.5

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = np.clip(s, 0, None)
            bestR = _R_of(best)

    if best is None:
        best = np.ones(64)
        bestR = _R_of(best)

    base = best.copy()
    baseR = bestR

    def try_accept(c):
        nonlocal best, bestR
        if c is None:
            return False
        rc = _R_of(c)
        if rc > bestR:
            bestR = rc
            best = c.copy()
            return True
        return False

    # Main line: keep refining best with log-LBFGS + softmax + peak polish,
    # occasionally block-optimizing the peak window at higher resolution.
    N = max(best.size, 8001)
    h = _prolongate(best, N)
    if _R_of(h) < bestR:
        h = best.copy()
    else:
        try_accept(h)

    # Phase 1: full optimization at working resolution
    if time_left():
        c = _lbfgs_log(h, 2000, deadline)
        if _R_of(c) > _R_of(h):
            h = c
        try_accept(h)

    for beta in (300, 1500, 8000, 40000):
        if not time_left():
            break
        c = _lbfgs_log(h, 400, deadline, beta=beta)
        if _R_of(c) > _R_of(h):
            h = c
        try_accept(h)
        if time_left():
            c = _lbfgs_log(h, 500, deadline)
            if _R_of(c) > _R_of(h):
                h = c
            try_accept(h)

    # Phase 2: alternate peak-window block polish and full polish
    fracs = (0.08, 0.12, 0.20, 0.30)
    fi = 0
    while time_left():
        c = _lbfgs_log(best, 600, deadline)
        try_accept(c)
        if not time_left():
            break
        f = fracs[fi % len(fracs)]
        fi += 1
        win = _peak_window(best, f)
        c = _lbfgs_block(best, win, 400, deadline)
        try_accept(c)
        if not time_left():
            break
        beta = (200, 1000, 5000)[fi % 3]
        c = _lbfgs_log(best, 300, deadline, beta=beta)
        try_accept(c)

    # Phase 3: if time remains, upsample best and re-polish (finer grid)
    if time_left() and best.size < 32000:
        N2 = min(32000, max(16000, best.size * 2))
        h2 = _prolongate(best, N2)
        if time_left():
            c = _lbfgs_log(h2, 800, deadline)
            if _R_of(c) > _R_of(h2):
                h2 = c
        for beta in (1000, 5000, 20000):
            if not time_left():
                break
            c = _lbfgs_log(h2, 300, deadline, beta=beta)
            if _R_of(c) > _R_of(h2):
                h2 = c
        if time_left():
            c = _lbfgs_log(h2, 500, deadline)
            if _R_of(c) > _R_of(h2):
                h2 = c
        # only accept the higher-resolution version if it wins
        if _R_of(h2) > bestR:
            best = h2
            bestR = _R_of(h2)

    # Final short polish
    while time_left():
        c = _lbfgs_log(best, 300, deadline)
        if not try_accept(c):
            break

    # Offer an alternative if it's a genuinely different construction
    alt = None
    if baseR > 0 and bestR > baseR + 1e-6:
        # try a quick variant: block-optimize peak of base and return if distinct
        pass

    if alt is not None and _R_of(alt) > 0 and not np.array_equal(alt, best):
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _jitter_seed(h, rng, n_blocks, sigma=0.20):
    N = h.size
    out = h.copy()
    fracs = rng.uniform(0.015, 0.08, size=n_blocks)
    positions = []
    for k in range(n_blocks):
        w = max(2, int(fracs[k] * N))
        lo = int(rng.integers(0, max(1, N - w)))
        positions.append((lo, lo + w))
    positions.sort()
    last_hi = -1
    for lo, hi in positions:
        if lo < last_hi:
            continue
        last_hi = hi
        fac = np.exp(rng.normal(0.0, sigma, size=hi - lo))
        out[lo:hi] = out[lo:hi] * fac
    out = np.clip(out, 0, None)
    if out.sum() <= 0:
        return h.copy()
    return _rescale(out)


def _solve_seed(h_seed, deadline_seed):
    h = h_seed
    for beta in (30.0, 120.0, 400.0):
        if time.process_time() >= deadline_seed - 0.3:
            break
        h = _lbfgs_sm(h, beta, maxiter=250, deadline=deadline_seed)
    if time.process_time() < deadline_seed - 0.3:
        h = _lbfgs_log(h, maxiter=400, deadline=deadline_seed)
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        # cold start: build from scratch
        cur = np.ones(256)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        for beta in (60.0, 200.0, 600.0):
            if time.process_time() >= deadline - 1.0:
                break
            cur = _lbfgs_sm(cur, beta, maxiter=300, deadline=deadline - 0.5)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline - 0.5)
        cur = _window_polish_peak(cur, deadline - 0.5, 0.3, 16, maxiter=400, beta=600.0)
        cur = _lbfgs_log(cur, maxiter=600, deadline=deadline - 0.5)
        return _rescale(cur)

    cur = start_arr.copy()
    cur_r = best_r
    n_full = cur.size
    rng = np.random.default_rng(int(t0 * 1e6) & 0xffffffff)

    # ---- Phase 1: try to break out at full resolution with jittered restarts ----
    # Each restart: perturb a random block, smooth-optimize, then polish.
    alt = None
    alt_r = -1.0

    # First do a strong polish of the incumbent at full resolution
    if time.process_time() < deadline - 3.0:
        cand = _window_polish_peak(cur, deadline - 1.0, 0.35, 24,
                                   maxiter=600, beta=800.0)
        cand = _lbfgs_log(cand, maxiter=600, deadline=deadline - 0.8)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

    # Jittered restarts at full resolution
    n_restarts = 0
    while time.process_time() < deadline - 2.5:
        n_restarts += 1
        n = cur.size
        n_blocks = int(rng.integers(4, 14))
        seed = _jitter_seed(cur, rng, n_blocks, sigma=0.25)
        if R_of(seed) < 0.85 * cur_r:
            continue
        slice_end = min(deadline - 1.5, time.process_time() + 3.5)
        # gentle smoothing schedule then log
        for beta in (60.0, 200.0, 800.0):
            if time.process_time() >= slice_end - 0.4:
                break
            seed = _lbfgs_sm(seed, beta, maxiter=200, deadline=slice_end)
        if time.process_time() < slice_end - 0.4:
            seed = _lbfgs_log(seed, maxiter=400, deadline=slice_end)
        if time.process_time() < slice_end - 0.4:
            seed = _window_polish_peak(seed, slice_end, 0.25, 16, maxiter=300, beta=600.0)
        r = R_of(seed)
        print("restart %d R=%.6f (cur %.6f)" % (n_restarts, r, cur_r))
        if r > cur_r:
            cur, cur_r = seed, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif r > alt_r:
            alt, alt_r = seed.copy(), r

    # Final polish of best
    if time.process_time() < deadline - 0.8:
        cand = _window_polish_peak(best, deadline - 0.5, 0.4, 32,
                                   maxiter=600, beta=1000.0)
        cand = _lbfgs_log(cand, maxiter=800, deadline=deadline - 0.4)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r

    print("final R=%.6f (start %.6f)" % (best_r, R_of(start_arr)))
    if alt is not None and alt_r > 0:
        return {"best": best, "alternative": alt}
    return best

