    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _perturb_peak(h, rng, scale):
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    wlen = int(rng.integers(n // 8, n // 3))
    lo = max(0, m - wlen)
    hi = min(n, m + wlen)
    seg = h[lo:hi].copy()
    if seg.size < 4:
        return h.copy()
    noise = rng.standard_normal(seg.size)
    k = max(2, seg.size // 32)
    kernel = np.ones(k) / k
    noise = np.convolve(noise, kernel, mode='same')
    noise /= (np.abs(noise).max() + 1e-12)
    h2 = h.copy()
    h2[lo:hi] = np.clip(seg * (1.0 + scale * noise), 0.0, None)
    return h2


# ---------- New idea: direct maximisation of the min over a plateau ----------
# Instead of raising the max, we drive a wide set of knots to the maximum.

def _fun_grad_min(h, tau):
    # Maximise a soft-min of the top knots: penalise knots BELOW the top.
    # Equivalent objective: minimise sum of exp(-(L - Lmax)/tau) weighted...
    # We use: minimise  log(sum exp(-(L-Lmax)/tau)) - log(N) approx equals -min.
    # Simpler: softmin of L (we want knots close to Lmax, i.e. many at the top).
    # Maximise -(softmin) => minimise softmin.
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    L = Lf  # includes the two zero end caps
    mx = L.max()
    if mx <= 0:
        return _fun_grad(h)
    # softmin over the "top region": use only knots within a band
    e = np.exp(-(L - mx) / tau)  # small for large L, big for small L
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z  # weights the smallest knots most
    # softmin value ~ mx - tau*log(Z)  (approx)
    smin = mx - tau * np.log(Z)
    # d(smin)/dL_j = w_j (since mx is max, d mx/dL_j = 0 for non-max)
    # plus, at the max, w contributes; but we want to push L up (reduce smin)
    # so we minimise smin: gradient wrt L is w.
    gLf = -dq / num + w / max(smin, 1e-12)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(max(smin, 1e-12))
    return val, grad


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size

    # --- Stage A: softmin (flatten the peak region) at full resolution. ---
    # The new idea: directly encourage many knots near the max.
    h = best.copy()
    for tau in (0.002, 0.001, 0.0005, 0.0002):
        if time.process_time() >= deadline - 25.0:
            break
        fg = (lambda hh, t=tau: _fun_grad_min(hh, t))
        hp = _lbfgs_log(h, 400, deadline, fg=fg)
        r = R_of(hp)
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("softmin tau=%.4f R=%.7f" % (tau, bestR))
        if r > bestR - 1e-6:
            h = hp

    # --- Stage B: softmax beta homotopy (original idea, still useful). ---
    for beta in (4.0, 16.0, 64.0):
        if time.process_time() >= deadline - 18.0:
            break
        hp = _lbfgs_log(best, 400, deadline, beta=beta)
        r = R_of(hp)
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("beta %.1f R=%.7f" % (beta, bestR))

    # --- Stage C: coarse-to-fine polish. ---
    for f in (3, 2):
        Nc = max(256, N // f)
        if time.process_time() >= deadline - 12.0:
            break
        hc = _coarse(best, Nc)
        for beta in (16.0, 64.0):
            hc = _lbfgs_log(hc, 400, deadline, beta=beta)
        hc = _window_polish_peak(hc, deadline, 0.35, 12)
        hp = _prolongate(hc, N)
        hp = _lbfgs_log(hp, 400, deadline)
        r = R_of(hp)
        print("c2f N=%d R=%.7f" % (Nc, r))
        if r > bestR + 1e-15:
            best, bestR = hp, r

    # --- Stage D: perturb-and-recover around the peak. ---
    rng = np.random.default_rng(20240613)
    stall = 0
    while time.process_time() < deadline - 6.0 and stall < 12:
        scale = float(rng.choice([0.03, 0.06, 0.12, 0.20]))
        hp = _perturb_peak(best, rng, scale)
        hp = _rescale(hp)
        hp = _lbfgs_log(hp, 500, deadline)
        hp = _window_polish_peak(hp, deadline, 0.45, 32)
        r = R_of(hp)
        if r > bestR + 1e-9:
            best, bestR = hp, r
            stall = 0
            print("perturb s=%.2f R=%.7f" % (scale, bestR))
        else:
            stall += 1

    # --- Stage E: final polish. ---
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _prolong(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    xs = np.linspace(0.0, total, N + 1)
    out = np.interp(xs, c, np.arange(M + 1, dtype=float))
    idx = np.clip(np.floor(out).astype(int), 0, M - 1)
    return np.maximum(h[idx], 0.0)


def _smooth_to(h, N, sigma):
    hp = _prolong(h, N)
    if sigma <= 0:
        return hp
    k = int(max(1, round(sigma * 3)))
    x = np.arange(-k, k + 1)
    g = np.exp(-0.5 * (x / sigma) ** 2)
    g /= g.sum()
    pad = k
    ext = np.concatenate((hp[pad - 1::-1], hp, hp[:-pad - 1:-1]))
    sm = np.convolve(ext, g, mode='same')
    out = sm[pad:pad + N]
    return np.maximum(out, 0.0)


def _zero_runs(h, minlen=8):
    z = (h <= 0)
    runs = []
    n = z.size
    i = 0
    while i < n:
        if z[i]:
            j = i
            while j < n and z[j]:
                j += 1
            if j - i >= minlen:
                runs.append((i, j))
            i = j
        else:
            i += 1
    return runs


def _revive(h, a):
    h2 = h.copy()
    runs = _zero_runs(h2, 8)
    if not runs:
        return None
    mx = h2.max()
    if mx <= 0:
        return None
    for (i, j) in runs:
        h2[i:j] = a * mx
    return h2


def _refine(h, deadline, tag, best_ref, max_rounds=200):
    """Iterative refinement: alternate whole-vector log-LBFGS and peak-window block LBFGS.
    best_ref is a list [bestR, best_h] updated in place."""
    cur = h.copy()
    curR = R_of(cur)
    if curR > best_ref[0]:
        best_ref[0] = curR
        best_ref[1] = cur.copy()
    betas = (0.0, 1e3, 1e4, 1e5, 1e6, 1e7)
    r = 0
    while time.process_time() < deadline - 0.5 and r < max_rounds:
        r += 1
        improved = False
        for beta in betas:
            if time.process_time() >= deadline - 0.5:
                break
            c = _lbfgs_log(cur, 200, deadline, beta=beta)
            rc = R_of(c)
            if rc > curR + 1e-9:
                cur = c; curR = rc; improved = True
                if rc > best_ref[0]:
                    best_ref[0] = rc; best_ref[1] = c.copy()
        if time.process_time() >= deadline - 0.5:
            break
        for frac in (0.03, 0.08, 0.15, 0.25):
            if time.process_time() >= deadline - 0.5:
                break
            lo, hi = _peak_region(cur, tol=0.999)
            span = max(1, hi - lo)
            pad = max(16, int(span * frac))
            lo2 = max(0, lo - pad)
            hi2 = min(cur.size - 1, hi + pad)
            free = np.arange(lo2, hi2 + 1)
            c = _lbfgs_block(cur, free, 150, deadline, beta=1e5)
            rc = R_of(c)
            if rc > curR + 1e-9:
                cur = c; curR = rc; improved = True
                if rc > best_ref[0]:
                    best_ref[0] = rc; best_ref[1] = c.copy()
        if not improved:
            # try a small perturbation to escape local plateau
            if time.process_time() >= deadline - 1.0:
                break
            rng = np.random.default_rng(1234 + r)
            pert = cur * (1.0 + 0.02 * rng.standard_normal(cur.size))
            pert = np.clip(pert, 0, None)
            c = _lbfgs_log(pert, 100, deadline, beta=1e5)
            rc = R_of(c)
            if rc > curR + 1e-9:
                cur = c; curR = rc
            else:
                break
    return cur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    def time_left():
        return time.process_time() < deadline

    best_ref = [-1.0, None]
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best_ref[0] = R_of(s)
            best_ref[1] = s.copy()

    if best_ref[1] is None:
        best_ref[1] = np.ones(64)
        best_ref[0] = R_of(best_ref[1])

    print(f"start R={best_ref[0]:.6f} N={best_ref[1].size}")

    # Alternatives we may hand back
    alt_ref = [-1.0, None]

    def consider_alt(cand):
        rc = R_of(cand)
        if rc > alt_ref[0] and (alt_ref[1] is None or cand.size != best_ref[1].size):
            alt_ref[0] = rc
            alt_ref[1] = cand.copy()

    base = best_ref[1].copy()
    base_N = base.size

    # First: refine at current resolution
    if time_left():
        cur = _refine(base, deadline, "base", best_ref)
        consider_alt(cur)
        print(f"refine base R={best_ref[0]:.6f}")

    # Escalate resolution with a couple of sigma choices; stop when budget exhausted.
    current = best_ref[1].copy()
    currentR = best_ref[0]
    schedule = [(4, 1.5), (2, 1.0), (2, 2.0), (2, 1.0), (2, 2.0), (2, 1.0)]
    for mult, sigma in schedule:
        if not time_left():
            break
        N = current.size * mult
        if N > 1000000:
            continue
        hw = _smooth_to(current, N, sigma=sigma)
        r0 = R_of(hw)
        if r0 < currentR - 5e-3:
            hw = _prolong(current, N)
            r0 = R_of(hw)
        print(f"upsample x{mult} sigma={sigma} N={N} R0={r0:.6f}")
        # try reviving zeros
        cands = [hw]
        for a in (1e-4, 1e-3, 3e-3):
            hr = _revive(hw, a)
            if hr is not None:
                cands.append(hr)
        hw_best = hw; r_best = r0
        for cand in cands:
            rc = R_of(cand)
            if rc > r_best:
                r_best = rc; hw_best = cand
        hw = hw_best
        if time_left():
            hw = _refine(hw, deadline, f"N={N}", best_ref)
        rc = R_of(hw)
        consider_alt(hw)
        if rc > currentR:
            current = hw; currentR = rc
        print(f"level N={N}: R={currentR:.6f}")

    # Final continuous refinement at best resolution until time runs out.
    if time_left():
        _refine(best_ref[1].copy(), deadline, "final", best_ref)

    print(f"final best R={best_ref[0]:.6f} N={best_ref[1].size}")
    best = best_ref[1]
    if alt_ref[1] is not None and alt_ref[0] > 0 and alt_ref[1].size != best.size:
        return {"best": best, "alternative": alt_ref[1]}
    return best

