def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


# ---------- NEW: adaptive refinement / coarsening of the step grid ----------

def _refine(h, factor=2):
    """Subdivide every step into `factor` equal sub-steps (mass preserving)."""
    if factor == 1:
        return h.copy()
    n = h.size * factor
    if n > 1000000:
        return h.copy()
    return np.repeat(h / factor, factor)


def _coarsen(h, factor=2):
    """Merge blocks of `factor` steps (mass preserving)."""
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor).sum(axis=1)
    return hh


def _best_R_grid(h, factors=(1, 2, 3, 4), deadline=None, fg=None, iters=60):
    """Try several grid resolutions; return (h, R) of the best polished candidate."""
    best = h.copy()
    bestR = R_of(best)
    for fac in factors:
        if time.process_time() >= deadline - 1.0:
            break
        if fac == 1:
            cand = best.copy()
        else:
            cand = _refine(best, fac)
            if cand.size == best.size:
                continue
        cand = _rescale(cand)
        sub = min(deadline - 0.5, time.process_time() + 3.0)
        hp = _lbfgs_log(cand, iters, sub, fg=fg)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            best, bestR = hp, rp
    return best, bestR


def _peak_polish(bestH, bestRH, iters, deadline, frac=0.15):
    if time.process_time() >= deadline - 1.0:
        return bestH, bestRH
    lo, hi = _peak_region(bestH)
    span = hi - lo
    pad = max(64, int(span * frac))
    lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
    if hi2 > lo2:
        free = np.arange(lo2, hi2 + 1)
        hp = _lbfgs_block(bestH, free, iters, deadline)
        rp = R_of(hp)
        if rp > bestRH + 1e-13:
            return hp.copy(), rp
    return bestH, bestRH


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    # ---- Main new idea: multi-resolution search around the start ----
    # (1) First, coarsen then refine: a coarse problem is cheaper and can escape
    #     local structure; refining then re-polishes at the target resolution.
    if time.process_time() < deadline - 8.0:
        # coarsen to a few scales and re-polish from each
        for cf in (2, 3, 4):
            if time.process_time() >= deadline - 6.0:
                break
            hc = _coarsen(bestH, cf)
            if hc.size < 64:
                continue
            # re-refine back and polish
            hc = _rescale(hc)
            sub = min(deadline - 4.0, time.process_time() + 3.0)
            hc = _lbfgs_log(hc, 100, sub)
            rc = R_of(hc)
            hr = _refine(hc, cf)
            hr = _rescale(hr)
            sub = min(deadline - 3.0, time.process_time() + 3.5)
            hr = _lbfgs_log(hr, 100, sub)
            rr = R_of(hr)
            if rr > bestRH + 1e-13:
                bestH, bestRH = hr.copy(), rr
            print("  coarse%d->refine R=%.7f (best %.7f)" % (cf, rr, bestRH))

    # (2) Fine-grid trial: subdivide the start once more and polish, then compare.
    if time.process_time() < deadline - 8.0:
        for fac in (2, 3):
            if time.process_time() >= deadline - 5.0:
                break
            hf = _refine(bestH, fac)
            if hf.size == bestH.size:
                continue
            hf = _rescale(hf)
            sub = min(deadline - 3.0, time.process_time() + 4.0)
            hf = _lbfgs_log(hf, 120, sub)
            rf = R_of(hf)
            if rf > bestRH + 1e-13:
                bestH, bestRH = hf.copy(), rf
            print("  refine%d R=%.7f (best %.7f)" % (fac, rf, bestRH))

    # (3) Iterate p-norm ladder + peak polish on the current best.
    ladder = (4, 8, 16, 32, 64, 128)
    while time.process_time() < deadline - 3.0:
        improved = False
        for p in ladder:
            if time.process_time() >= deadline - 2.5:
                break
            sub = min(deadline - 1.5, time.process_time() + 4.0)
            fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
            h = _lbfgs_log(bestH, 80, sub, fg=fg)
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
                improved = True
            print("  p=%d R=%.7f" % (p, bestRH))

        if time.process_time() < deadline - 2.0:
            bestH, bestRH = _peak_polish(bestH, bestRH, 80,
                                         min(deadline - 1.0, time.process_time() + 3.0))
            print("  peak R=%.7f" % bestRH)

        if not improved and time.process_time() > deadline - 5.0:
            break

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_Q(h, c, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    Q = np.sum(Lf * sig)
    if Q <= 0:
        return 1e18, np.zeros(h.size)
    dQ = sig + beta * Lf * sig * (1.0 - sig)
    gLf = dQ / Q
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(Q) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))
    N = best.size
    alt = None
    altR = 0.0

    # NEW IDEA: continuation / refinement path using the smooth-max (softmax)
    # surrogate _fun_grad_Q with gradually increasing beta.  This raises the
    # effective L2/Linf balance more gently than the hard-max objective and
    # lets the optimizer move mass across the near-tied peak band, then we
    # switch back to exact-max polishing.
    schedules = [(0.999, 50.0), (0.9995, 200.0), (0.9998, 800.0),
                 (0.99995, 3000.0)]

    def try_update(h, tag):
        nonlocal best, bestR, alt, altR
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("%s R=%.7f" % (tag, bestR))
        else:
            if alt is None or r > altR:
                alt, altR = h, r

    # Phase 1: softmax continuation on the full vector
    for c, beta in schedules:
        if time.process_time() >= deadline - 6.0:
            break
        fg = (lambda c=c, beta=beta: (lambda hh: _fun_grad_Q(hh, c, beta)))()
        h = _lbfgs_log(best, 300, deadline, fg=fg)
        try_update(h, "soft(c=%.4f,b=%g)" % (c, beta))

    # Phase 2: exact-max polish + peak windows
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        for frac in (0.05, 0.12, 0.25):
            if time.process_time() >= deadline - 1.5:
                break
            free = _peak_window(best, frac=frac)
            h = _lbfgs_block(best, free, 400, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h, r
                improved = True
                print("win(%.2f) R=%.7f" % (frac, bestR))
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if start is not None:
        try:
            startR = R_of(np.asarray(start, dtype=float))
        except Exception:
            startR = 0.0
        if alt is not None and altR > 0 and bestR <= startR + 1e-12:
            return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
