                _consider(c, r)

    print("phaseB R=%.6f N=%d" % (best_r, best.size))

    if best_r < start_r:
        best = start_arr.copy()
        best_r = start_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_Q(h, c, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    Q = np.sum(Lf * sig)
    if Q <= 0:
        return 1e18, np.zeros(h.size)
    dQ = sig + beta * Lf * sig * (1.0 - sig)
    gLf = dQ / Q
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(Q) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def _Q_value(h, c, beta):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    return float(np.sum(Lf * sig))


def _support(h):
    nz = np.flatnonzero(h > 1e-12 * h.max())
    if nz.size == 0:
        return 0, h.size - 1
    return int(nz[0]), int(nz[-1])


def _edge_profile(W, eps):
    i = np.arange(W, dtype=float)
    p = 2.0 * (np.sqrt(i + 1.0 + eps) - np.sqrt(i + eps))
    return p


def _tail_experiment(base, deadline):
    """F759-style capped inverse-sqrt tail replacement."""
    best = base.copy()
    bestR = R_of(best)
    best_info = None
    i0, i1 = _support(best)
    span = i1 - i0 + 1
    if span < 8:
        return best, bestR, None
    W = max(128, int(0.08 * span))
    W = min(W, span // 2)

    eps_list = [1e-3, 1e-2, 1e-1, 1.0]
    cap_mults = [1.0, 2.0, 4.0, 8.0]
    ws = [0.25, 0.5, 0.75, 1.0]
    alphas = [0.25, 0.5, 1.0]

    # Precompute candidate blends
    candidates = []
    for eps in eps_list:
        prof = _edge_profile(W, eps)
        for cap_mult in cap_mults:
            for side in ('L', 'R'):
                if side == 'L':
                    seg = best[i0:i0 + W].copy()
                    idx = np.arange(i0, i0 + W)
                    p = prof.copy()
                else:
                    seg = best[i1 - W + 1:i1 + 1].copy()
                    idx = np.arange(i1 - W + 1, i1 + 1)
                    p = prof[::-1].copy()
                mseg = seg.mean()
                if mseg <= 0:
                    continue
                cap = cap_mult * mseg
                pc = np.clip(p, 0.0, cap)
                ps = pc.sum()
                if ps <= 0:
                    continue
                pc = pc * (seg.sum() / ps)
                for w in ws:
                    hnew = best.copy()
                    hnew[idx] = (1.0 - w) * seg + w * pc
                    candidates.append(('add', side, eps, cap_mult, w, None, idx, hnew))
                for a in alphas:
                    pn = pc / (pc.mean() + 1e-300)
                    hnew = best.copy()
                    hnew[idx] = np.clip(seg * (1.0 + a * pn), 0.0, None)
                    candidates.append(('mul', side, eps, cap_mult, None, a, idx, hnew))

    # Score all candidates
    scored = []
    for cand in candidates:
        if time.process_time() > deadline - 5.0:
            break
        r = R_of(cand[7])
        scored.append((r, cand))
    scored.sort(key=lambda x: -x[0])

    print("  tail: %d candidates, top raw R=%.9f (base %.9f)" %
          (len(scored), scored[0][0] if scored else 0.0, bestR))

    # Polish top few
    for r, cand in scored[:6]:
        if time.process_time() > deadline - 3.0:
            break
        kind, side, eps, cap_mult, w, a, idx, hnew = cand
        cap_t = min(deadline - 2.0, time.process_time() + 2.0)
        hb = _lbfgs_block(hnew, idx, 80, cap_t, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR + 1e-13:
            hp, rp = _polish(hb, min(deadline - 1.0, time.process_time() + 3.0))
            if rp > bestR:
                best, bestR = hp, rp
                best_info = (kind, side, eps, cap_mult, w, a, r, rp)
                print("    new best R=%.9f from %s side=%s eps=%.0e cap=%.1f w=%s a=%s raw=%.9f" %
                      (bestR, kind, side, eps, cap_mult, w, a, r))

    return best, bestR, best_info


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    hard = t0 + budget_seconds - 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # --- Tail experiment first ---
    tail_best, tail_R, tail_info = _tail_experiment(best, min(hard, t0 + budget_seconds * 0.55))
    if tail_R > bestR + 1e-13:
        best, bestR = tail_best, tail_R
        print("tail experiment improved to R=%.9f" % bestR)
    else:
        print("tail experiment: no improvement (best raw info=%s)" % (tail_info,))

    # --- Continue base sweep from (possibly improved) best ---
    grid = [(0.90, 1e3), (0.95, 1e3), (0.95, 1e5),
            (0.99, 1e4), (0.99, 1e5)]

    sweep = 0
    while time.process_time() < hard - 3.0:
        sweep += 1
        improved = False
        for (c, beta) in grid:
            if time.process_time() >= hard - 3.0:
                break
            fg = (lambda hh, cc=c, bb=beta: _fun_grad_Q(hh, cc, bb))
            q0 = _Q_value(best, c, beta)
            cap = min(hard - 2.0, time.process_time() + 3.5)
            hq = _lbfgs_log(best, 150, cap, fg=fg)
            q1 = _Q_value(hq, c, beta)
            rq = R_of(hq)
            hp, rp = _polish(hq, min(hard - 1.0, time.process_time() + 6.0))
            beat = rp > bestR + 1e-14
            print("  [sweep%d c=%.2f beta=%.0e] Q %.6f->%.6f Rq=%.9f "
                  "polish=%.9f %s" %
                  (sweep, c, beta, q0, q1, rq, rp, "BEAT" if beat else ""))
            if beat:
                best, bestR = hp, rp
                improved = True
                print("    new best R=%.9f" % bestR)
        if not improved and sweep > 2:
            if time.process_time() < hard - 3.0:
                cap = min(hard - 2.0, time.process_time() + 3.0)
                hp = _lbfgs_log(best, 300, cap, fg=_fun_grad)
                rp = R_of(hp)
                if rp > bestR + 1e-12:
                    best, bestR = hp, rp
                    print("    fallback best R=%.9f" % bestR)

    if time.process_time() < hard - 0.5:
        hp, rp = _polish(best, hard)
        if rp > bestR:
            best, bestR = hp, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    z = np.clip(beta * (Lf - mx), -60.0, 0.0)
    e = np.exp(z)
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _surrogate(h, beta):
    Lf = _knots(h)
    mx = Lf.max()
    z = np.clip(beta * (Lf - mx), -60.0, 0.0)
    Z = np.exp(z).sum()
    return mx + np.log(Z) / beta


def _n_active(h, beta, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    return int(np.sum(Lf >= mx - tol))


# ---------- main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Cyclical beta path: high -> low -> high.
    betas = [1e8, 1e6, 1e4, 1e3, 1e2, 10, 1, 10, 1e2, 1e3, 1e4, 1e6, 1e8]
    fracs = [0.02, 0.05, 0.10]

    # Working construction for the cycle (may dip and recover).
    work = best.copy()

    cycle = 0
    while time.process_time() < deadline - 0.5:
        cycle += 1
        improved_cycle = False
        for beta in betas:
            if time.process_time() >= deadline - 0.5:
                break
            cap = min(deadline - 0.3, time.process_time() + 2.0)
            hp = _lbfgs_log(work, 150, cap, beta=beta)
            rp = R_of(hp)
            sm = _surrogate(hp, beta)
            na = _n_active(hp, beta)
            work = hp  # continue from smooth-max result
            print("  cyc=%d beta=%.0e sm=%.6f R=%.9f nact=%d bestR=%.9f"
                  % (cycle, beta, sm, rp, na, bestR))
            if rp > bestR + 1e-15:
                best, bestR = hp.copy(), rp
                improved_cycle = True

            # exact-R peak-window polish between stages
            if time.process_time() >= deadline - 0.5:
                break
            for frac in fracs:
                if time.process_time() >= deadline - 0.5:
                    break
                free = _peak_window(work, frac=frac)
                cap = min(deadline - 0.3, time.process_time() + 1.0)
                hb = _lbfgs_block(work, free, 100, cap, beta=0.0)
                rb = R_of(hb)
                work = hb
                if rb > bestR + 1e-15:
                    best, bestR = hb.copy(), rb
                    improved_cycle = True
                    print("    block frac=%.2f R=%.9f" % (frac, bestR))

        if not improved_cycle and cycle > 1:
            break

    # After the cycle, run p0861's full final polish from the best.
    work = best.copy()
    while time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 3.0)
        hp = _lbfgs_log(work, 300, cap, beta=0.0)
        rp = R_of(hp)
        work = hp
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp
            print("  final hard R=%.9f" % bestR)
        else:
            break

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _refine_n(h, N, deadline):
    n = h.size
    if N == n:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    h2 = np.interp(x_new, x_old, h)
    h2 = np.clip(h2, 0, None)
    if h2.sum() <= 0:
        return h
    h2 *= (h.sum() / h2.sum()) * (n / N)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_polish(bestH, bestRH, iters, deadline):
    if time.process_time() >= deadline - 1.0:
        return bestH, bestRH
    lo, hi = _peak_region(bestH)
    span = hi - lo
    pad = max(64, int(span * 0.15))
    lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
    if hi2 > lo2:
        free = np.arange(lo2, hi2 + 1)
        hp = _lbfgs_block(bestH, free, iters, deadline)
        rp = R_of(hp)
        if rp > bestRH + 1e-13:
            return hp.copy(), rp
    return bestH, bestRH


def _local_bumps(h, rng, n_bumps, max_frac=0.05, amp=0.3):
    """Return a perturbed copy with smooth localized bumps."""
    n = h.size
    hn = h.copy()
    for _ in range(n_bumps):
        c = rng.integers(0, n)
        w = max(4, int(max_frac * n * rng.random()))
        lo = max(0, c - w); hi = min(n, c + w)
        x = np.linspace(-1.0, 1.0, hi - lo)
        bump = np.exp(-4.0 * x * x) * (2 * rng.random() - 1) * amp
        hn[lo:hi] *= np.clip(1.0 + bump, 0.0, None)
    return _rescale(hn)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None and len(start) > 0:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR
    rng = np.random.default_rng(987654321)

    # ---------- Phase A: coarse-to-fine ladder with p-norm continuation ----------
    N0 = bestH.size
    ladder_N = []
    Nc = max(2048, N0 // 8)
    while Nc < N0:
        ladder_N.append(Nc)
        Nc = min(Nc * 2, N0)
    ladder_N.append(N0)

    ladder_p = (4, 8, 16, 32, 64, 128)

    phase1_end = t0 + budget_seconds * 0.55

    h_cur = _refine_n(bestH, ladder_N[0], deadline)
    r_cur = R_of(h_cur)
    print("  ladder start N=%d R=%.7f" % (h_cur.size, r_cur))

    for N in ladder_N:
        if time.process_time() >= phase1_end - 2.0:
            break
        hN = _refine_n(h_cur, N, deadline)
        rN = R_of(hN)
        inner_end = min(phase1_end, time.process_time() + 5.0)
        for p in ladder_p:
            if time.process_time() >= inner_end:
                break
            sub = min(inner_end, time.process_time() + 2.5)
            fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
            hN = _lbfgs_log(hN, 100, sub, fg=fg)
            rN = R_of(hN)
        if time.process_time() < inner_end:
            hN = _lbfgs_log(hN, 150, inner_end)
            rN = R_of(hN)
            hN, rN = _peak_polish(hN, rN, 120, inner_end)
        h_cur = hN
        print("  ladder N=%d R=%.7f" % (N, rN))
        if rN > bestRH + 1e-13:
            bestH, bestRH = h_cur.copy(), rN

    # ---------- Phase B: stochastic bump restarts (escape basins) ----------
    phase2_end = deadline - 3.0
    trial = 0
    while time.process_time() < phase2_end - 3.0:
        trial += 1
        if time.process_time() >= phase2_end - 3.0:
            break
        # perturb the current best with a few smooth bumps
        h_try = _local_bumps(bestH, rng, n_bumps=rng.integers(2, 7),
                             max_frac=0.04, amp=0.25)
        sub = min(phase2_end, time.process_time() + 5.0)
        # short p-norm continuation to escape
        for p in (8, 32, 128):
            if time.process_time() >= sub:
                break
            sub2 = min(sub, time.process_time() + 1.8)
            fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
            h_try = _lbfgs_log(h_try, 80, sub2, fg=fg)
        if time.process_time() < sub:
            h_try = _lbfgs_log(h_try, 200, sub)
            h_try, r_try = _peak_polish(h_try, R_of(h_try), 120, sub)
        else:
            r_try = R_of(h_try)
        if r_try > bestRH + 1e-13:
            bestH, bestRH = h_try.copy(), r_try
            print("  bump%d -> R=%.7f *" % (trial, bestRH))
        elif trial % 3 == 0:
            print("  bump%d -> R=%.7f" % (trial, r_try))

    # ---------- Final sharp polish on best ----------
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 400, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        hp, rp = _peak_polish(bestH, bestRH, 200, deadline - 0.3)
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp, rp
        print("final sharp R=%.7f" % bestRH)

    if bestRH > start_bestR + 1e-13:
        best = bestH.copy()
        bestR = bestRH
    else:
        best = start_best.copy()
        bestR = start_bestR

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if R_of(bestH) > start_bestR - 1e-6 else None}

