    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_shoulder(h, c, beta):
    """Shoulder-weighted numerator: down-weight top band L > c*Linf."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    # weight per knot: 1 - sigmoid(beta*(L - c*mx))
    z = np.clip(beta * (Lf - c * mx), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    w = 1.0 - sig
    a = Lf[:-1]; b = Lf[1:]
    wq = w[:-1] * (a * a + a * b + b * b) / 3.0
    num_w = wq.sum()
    if num_w <= 0:
        return _fun_grad(h)
    # d(num_w)/dL_k
    dq = np.zeros_like(Lf)
    dq[:-1] += w[:-1] * (2 * a + b)
    dq[1:] += w[1:] * (a + 2 * b)
    dq /= 3.0
    m = int(np.argmax(Lf))
    gLf = -dq / num_w
    gLf[m] += 1.0 / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num_w) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _frac_within(h, tol=0.01):
    Lf = _knots(h)
    mx = Lf.max()
    return float(np.mean(Lf >= mx * (1.0 - tol)))


def _exact_polish(best, bestR, deadline, fracs=(0.02, 0.05, 0.10)):
    """Exact-R log L-BFGS + peak-window block polish. Returns (best, bestR)."""
    if time.process_time() >= deadline - 0.3:
        return best, bestR
    cap = min(deadline - 0.3, time.process_time() + 3.0)
    hp = _lbfgs_log(best, 300, cap, _fun_grad)
    rp = R_of(hp)
    if rp > bestR + 1e-15:
        best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.3, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 150, cap, _fun_grad)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d) f1%%=%.4f"
          % (bestR, best.size, _frac_within(best)))

    cs = [0.98, 0.95, 0.90, 0.80]
    betas = [1e2, 1e3, 1e4]

    # ---- ladder ----
    for c in cs:
        for beta in betas:
            if time.process_time() >= deadline - 0.5:
                break
            fg = (lambda hh, cc=c, bb=beta: _fun_grad_shoulder(hh, cc, bb))
            cap = min(deadline - 0.3, time.process_time() + 3.0)
            hs = _lbfgs_log(best, 300, cap, fg)
            rs_pre = R_of(hs)
            hb, rb = _exact_polish(hs, rs_pre, deadline)
            f1 = _frac_within(hb)
            print("  c=%.2f beta=%.0e Rpre=%.9f Rpost=%.9f f1%%=%.4f"
                  % (c, beta, rs_pre, rb, f1))
            if rb > bestR + 1e-15:
                best, bestR = hb, rb

    # ---- alternate best shoulder stage with exact polish ----
    # pick best (c,beta) empirically: try each once more briefly, keep best
    best_cb = (0.95, 1e3)
    best_cb_R = -1.0
    for c in cs:
        for beta in betas:
            if time.process_time() >= deadline - 0.5:
                break
            fg = (lambda hh, cc=c, bb=beta: _fun_grad_shoulder(hh, cc, bb))
            cap = min(deadline - 0.3, time.process_time() + 1.5)
            hs = _lbfgs_log(best, 150, cap, fg)
            hb, rb = _exact_polish(hs, R_of(hs), deadline,
                                   fracs=(0.02, 0.05))
            if rb > best_cb_R:
                best_cb_R = rb
                best_cb = (c, beta)
            if rb > bestR + 1e-15:
                best, bestR = hb, rb
    print("  chosen c=%.2f beta=%.0e" % best_cb)

    while time.process_time() < deadline - 0.5:
        c, beta = best_cb
        fg = (lambda hh, cc=c, bb=beta: _fun_grad_shoulder(hh, cc, bb))
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hs = _lbfgs_log(best, 200, cap, fg)
        hb, rb = _exact_polish(hs, R_of(hs), deadline)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
            print("  alt R=%.9f f1%%=%.4f" % (bestR, _frac_within(best)))
        else:
            # try exact polish directly on best to squeeze
            hb2, rb2 = _exact_polish(best, bestR, deadline)
            if rb2 > bestR + 1e-15:
                best, bestR = hb2, rb2
            else:
                break

    # final exact polish
    best, bestR = _exact_polish(best, bestR, deadline)

    print("final R=%.9f (N=%d) f1%%=%.4f"
          % (bestR, best.size, _frac_within(best)))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_phi(h, M, w):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if num <= 0:
        return 1e18, np.zeros(h.size)
    r = np.maximum(Lf - M, 0.0)
    pen = w * np.sum(r * r)
    gLf = -dq / num
    gLf += 2.0 * w * r
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + pen
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def _Q_value(h, c, beta):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    return float(np.sum(Lf * sig))


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _prolong(h):
    return np.repeat(h, 2)


def _peak_sweep(h, deadline, tag):
    """Run the M x w peak-lowering sweep. Returns best (h, R)."""
    h = _rescale(h)
    Lf = _knots(h)
    Linf = Lf.max()
    if Linf <= 0:
        return h, R_of(h)
    best = h.copy()
    bestR = R_of(h)
    Ms = [0.9999, 0.9995, 0.999, 0.996, 0.992]
    ws = [1e2, 1e4, 1e6]
    cur = h.copy()
    for mf in Ms:
        M = mf * Linf
        for w in ws:
            if time.process_time() >= deadline - 1.0:
                break
            fg = (lambda hh, MM=M, ww=w: _fun_grad_phi(hh, MM, ww))
            cap = min(deadline - 0.5, time.process_time() + 2.5)
            hq = _lbfgs_log(cur, 200, cap, fg=fg)
            # renormalise so knots max = 1
            mx = _knots(hq).max()
            if mx > 0:
                hq = hq / np.sqrt(mx)
            s = hq.sum()
            num, _, Lf2 = _num_and_dq(hq)
            Li = Lf2.max()
            rq = R_of(hq)
            print("  [%s M=%.4f w=%.0e] num=%.6f s=%.6f Linf=%.6f R=%.9f" %
                  (tag, mf, w, num, s, Li, rq))
            if rq > bestR + 1e-14:
                best, bestR = hq.copy(), rq
            cur = hq
        if time.process_time() >= deadline - 1.0:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    hard = t0 + budget_seconds - 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # --- Peak-lowering sweep at coarse N ---
    hc = _coarsen(best)
    hc = _rescale(hc)
    print("coarse N=%d R=%.9f" % (hc.size, R_of(hc)))
    if time.process_time() < hard - 5.0:
        cap = min(hard - 3.0, time.process_time() + 4.0)
        hc, rc = _peak_sweep(hc, cap, "coarse")
        print("coarse best R=%.9f" % rc)
        # prolongate
        hf = _prolong(hc)
        hf = _rescale(hf)
        rf = R_of(hf)
        print("prolongated N=%d R=%.9f" % (hf.size, rf))
        if rf > bestR + 1e-14:
            best, bestR = hf.copy(), rf
            print("  new best from coarse path R=%.9f" % bestR)

    # --- Peak-lowering sweep at full N ---
    if time.process_time() < hard - 5.0:
        cap = min(hard - 3.0, time.process_time() + 8.0)
        hfull, rfull = _peak_sweep(best, cap, "full")
        if rfull > bestR + 1e-14:
            best, bestR = hfull, rfull
            print("  new best from full path R=%.9f" % bestR)

    # --- Original Q-sweep as fallback (kept from base) ---
    grid = [(0.90, 1e3), (0.95, 1e3), (0.95, 1e5),
            (0.99, 1e4), (0.99, 1e5)]
    sweep = 0
    while time.process_time() < hard - 3.0:
        sweep += 1
        improved = False
        for (c, beta) in grid:
            if time.process_time() >= hard - 3.0:
                break
            fg = (lambda hh, cc=c, bb=beta: _fun_grad_Q(hh, cc, bb))
            q0 = _Q_value(best, c, beta)
            cap = min(hard - 2.0, time.process_time() + 3.0)
            hq = _lbfgs_log(best, 150, cap, fg=fg)
            q1 = _Q_value(hq, c, beta)
            rq = R_of(hq)
            hp, rp = _polish(hq, min(hard - 1.0, time.process_time() + 5.0))
            beat = rp > bestR + 1e-14
            print("  [sweep%d c=%.2f beta=%.0e] Q %.6f->%.6f Rq=%.9f "
                  "polish=%.9f %s" %
                  (sweep, c, beta, q0, q1, rq, rp, "BEAT" if beat else ""))
            if beat:
                best, bestR = hp, rp
                improved = True
                print("    new best R=%.9f" % bestR)
        if not improved and sweep > 2:
            if time.process_time() < hard - 3.0:
                cap = min(hard - 2.0, time.process_time() + 3.0)
                hp = _lbfgs_log(best, 300, cap, fg=_fun_grad)
                rp = R_of(hp)
                if rp > bestR + 1e-12:
                    best, bestR = hp, rp
                    print("    fallback best R=%.9f" % bestR)

    if time.process_time() < hard - 0.5:
        hp, rp = _polish(best, hard)
        if rp > bestR:
            best, bestR = hp, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}


def _fun_grad_Q(h, c, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    Q = np.sum(Lf * sig)
    if Q <= 0:
        return 1e18, np.zeros(h.size)
    dQ = sig + beta * Lf * sig * (1.0 - sig)
    gLf = dQ / Q
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(Q) + 2.0 * np.log(s)
    return val, grad

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
