            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def _Q_value(h, c, beta):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    return float(np.sum(Lf * sig))


def _upsample2(h):
    return np.repeat(h, 2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    hard = t0 + budget_seconds - 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # --- Stage 1: 2x refinement with symmetry-breaking perturbations ---
    h2 = _rescale(_upsample2(best))
    N2 = h2.size
    rng = np.random.RandomState(12345)

    trials = []
    # deterministic perturbation parameters
    amps = [0.01, 0.03, 0.10]
    freqs = [1, 2, 4, 8]
    signs = [(1.0, -1.0), (1.0, 1.0)]
    idx = np.arange(N2 // 2, dtype=float)
    trial_count = 0
    max_trials = 8
    for a in amps:
        for f in freqs:
            if trial_count >= max_trials:
                break
            phase = rng.uniform(0, 2 * np.pi)
            s = signs[trial_count % 2]
            v = np.sin(2 * np.pi * f * idx / (N2 // 2) + phase)
            # per-cell multiplier for the two children
            mult = np.empty(N2)
            mult[0::2] = 1.0 + a * s[0] * v
            mult[1::2] = 1.0 + a * s[1] * v
            # random jitter on a contiguous window
            w = max(1, N2 // 8)
            lo = rng.randint(0, max(1, N2 - w))
            jitter = 1.0 + rng.uniform(-0.03, 0.03, size=w)
            mult[lo:lo + w] *= jitter
            ht = _rescale(h2 * mult)
            rt = R_of(ht)
            trials.append((rt, ht))
            trial_count += 1
        if trial_count >= max_trials:
            break

    trials.sort(key=lambda x: -x[0])
    candidates = [t[1] for t in trials[:2]]
    for rt, _ in trials[:2]:
        print("  trial R=%.9f" % rt)

    # --- Stage 2: Q-sweep on each candidate ---
    grid = [(c, beta) for c in (0.985, 0.99, 0.995, 0.999)
            for beta in (1e3, 1e4, 1e5, 1e6, 1e7)]

    best_ref = None
    best_refR = -1.0
    for ci, cand in enumerate(candidates):
        cur = cand
        curR = R_of(cur)
        for (c, beta) in grid:
            if time.process_time() >= hard - 3.0:
                break
            fg = (lambda hh, cc=c, bb=beta: _fun_grad_Q(hh, cc, bb))
            cap = min(hard - 2.0, time.process_time() + 2.5)
            hq = _lbfgs_log(cur, 120, cap, fg=fg)
            rq = R_of(hq)
            if rq > curR + 1e-14:
                hp, rp = _polish(hq, min(hard - 1.0,
                                         time.process_time() + 4.0))
                if rp > curR:
                    cur, curR = hp, rp
        print("  cand%d final R=%.9f" % (ci, curR))
        if curR > best_refR:
            best_ref, best_refR = cur, curR

    # --- Stage 3: final polish with remaining budget ---
    if best_ref is not None and best_refR > bestR + 1e-14:
        best, bestR = best_ref, best_refR
        print("  refinement beat base: R=%.9f" % bestR)

    if time.process_time() < hard - 0.5:
        hp, rp = _polish(best, hard)
        if rp > bestR:
            best, bestR = hp, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_Q(h, c, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    Q = np.sum(Lf * sig)
    if Q <= 0:
        return 1e18, np.zeros(h.size)
    dQ = sig + beta * Lf * sig * (1.0 - sig)
    gLf = dQ / Q
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(Q) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def _Q_value(h, c, beta):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    return float(np.sum(Lf * sig))


def _full_block_polish(h, bestR, deadline, block=1024, per_block=0.4):
    """Coordinate-wise block refinement over the full array, accepting only
    blocks that improve exact R. Returns (h, R, n_accepted)."""
    n = h.size
    accepted = 0
    cur = h
    curR = bestR
    starts = list(range(0, n, block))
    for lo in starts:
        if time.process_time() >= deadline - 0.3:
            break
        hi = min(n, lo + block)
        free = np.arange(lo, hi)
        cap = min(deadline - 0.2, time.process_time() + per_block)
        cand = _lbfgs_block(cur, free, 30, cap, fg=_fun_grad)
        rc = R_of(cand)
        if rc > curR + 1e-14:
            cur = cand
            curR = rc
            accepted += 1
    return cur, curR, accepted


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    hard = t0 + budget_seconds - 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    cs = [0.99, 0.995, 0.999]
    betas = [1e2, 3e2, 1e3, 3e3, 1e4, 3e4, 1e5, 3e5,
             1e6, 3e6, 1e7, 3e7, 1e8]

    sweep = 0
    while time.process_time() < hard - 3.0:
        sweep += 1
        improved = False
        for c in cs:
            for beta in betas:
                if time.process_time() >= hard - 3.0:
                    break
                fg = (lambda hh, cc=c, bb=beta: _fun_grad_Q(hh, cc, bb))
                cap = min(hard - 2.0, time.process_time() + 1.0)
                hq = _lbfgs_log(best, 120, cap, fg=fg)
                rq = R_of(hq)
                # full-array block coordinate refinement
                hb, rb, nacc = _full_block_polish(
                    hq, max(rq, bestR), min(hard - 1.0,
                                             time.process_time() + 6.0))
                beat = rb > bestR + 1e-14
                print("  [s%d c=%.3f b=%.0e] Rq=%.9f block=%.9f acc=%d %s" %
                      (sweep, c, beta, rq, rb, nacc,
                       "BEAT" if beat else ""))
                if beat:
                    best, bestR = hb, rb
                    improved = True
                    print("    new best R=%.9f" % bestR)
            if time.process_time() >= hard - 3.0:
                break
        if not improved and sweep > 1:
            if time.process_time() < hard - 3.0:
                cap = min(hard - 2.0, time.process_time() + 3.0)
                hp = _lbfgs_log(best, 300, cap, fg=_fun_grad)
                rp = R_of(hp)
                if rp > bestR + 1e-12:
                    best, bestR = hp, rp
                    print("    fallback best R=%.9f" % bestR)

    if time.process_time() < hard - 0.5:
        hp, rp = _polish(best, hard)
        if rp > bestR:
            best, bestR = hp, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
