    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0,
                        tol=0.999):
    n = h.size
    lo, hi = _peak_region(h, tol=tol)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolong2(h, soften=1.0):
    n = h.size
    h = np.asarray(h, dtype=float)
    nxt = np.empty(n)
    nxt[:-1] = h[1:]
    nxt[-1] = h[-1]
    d = (nxt - h) / 4.0 * soften
    a = np.clip(h - d, 0.0, None)
    b = np.clip(h + d, 0.0, None)
    out = np.empty(2 * n)
    out[0::2] = a
    out[1::2] = b
    return out


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    cur = start_best.copy()
    curR = start_bestR

    # NEW: multi-tolerance peak windows. The start has a wide plateau
    # (~43% of knots within 5% of max). Shrinking tol progressively
    # concentrates effort near the true peak and breaks the plateau.
    tol_schedule = (0.999, 0.99, 0.97, 0.95, 0.90, 0.80, 0.60, 0.40)
    for tol in tol_schedule:
        if time.process_time() >= deadline - 3.0:
            break
        improved = False
        for frac, extra in ((0.05, 32), (0.15, 64), (0.30, 128)):
            if time.process_time() >= deadline - 3.0:
                break
            hw = _window_polish_peak(cur, deadline, frac, extra,
                                     maxiter=200, tol=tol)
            rw = R_of(hw)
            if rw > curR + 1e-13:
                cur, curR = hw, rw
                improved = True
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
        # sharp polish after each tolerance tier
        if time.process_time() < deadline - 3.0:
            hf = _lbfgs_log(cur, 200, deadline)
            rf = R_of(hf)
            if rf > curR + 1e-13:
                cur, curR = hf, rf
                improved = True
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
        print("  tol=%.3f R=%.7f near=%.4f" %
              (tol, curR, _frac_near_max(cur)))
        if not improved and tol < 0.5:
            break

    # High-beta ladder to sharpen the peak (make it more "spiky")
    for beta in (1e6, 1e7, 1e8, 1e9):
        if time.process_time() >= deadline - 3.0:
            break
        hb = _window_polish_peak(cur, deadline, 0.15, 64,
                                 maxiter=200, beta=beta, tol=0.95)
        rb = R_of(hb)
        hs = _window_polish_peak(hb, deadline, 0.15, 64,
                                 maxiter=150, tol=0.95)
        rs = R_of(hs)
        cand, rc = (hs, rs) if rs > rb else (hb, rb)
        if rc > curR + 1e-13:
            cur, curR = cand, rc
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
        print("  beta=%.0e R=%.7f near=%.4f" %
              (beta, curR, _frac_near_max(cur)))

    # Alternative finer grid: prolong 2x, polish, and take if better
    if time.process_time() < deadline - 8.0:
        h2 = _rescale(_prolong2(start_best, soften=0.3))
        r2 = R_of(h2)
        print("prolong2 R=%.7f (N=%d)" % (r2, h2.size))
        # polish on the finer grid with multi-tol windows
        c2 = h2.copy()
        c2R = r2
        for tol in (0.999, 0.97, 0.90, 0.70):
            if time.process_time() >= deadline - 4.0:
                break
            hw = _window_polish_peak(c2, deadline, 0.15, 128,
                                     maxiter=200, tol=tol)
            rw = R_of(hw)
            if rw > c2R + 1e-13:
                c2, c2R = hw, rw
        if time.process_time() < deadline - 3.0:
            hf = _lbfgs_log(c2, 300, deadline)
            rf = R_of(hf)
            if rf > c2R:
                c2, c2R = hf, rf
        print("  2x polished R=%.7f" % c2R)
        if c2R > bestR + 1e-13:
            best, bestR = c2, c2R
            print("  2x WINS R=%.7f" % bestR)

    # Final sharp polish
    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 300, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_band(h, lo, hi):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    Lm = Lf.max()
    if Lm <= 0:
        return _fun_grad(h)
    mask = (Lf > lo * Lm) & (Lf < hi * Lm)
    d = (Lm - Lf) * mask
    val = np.sum(d * d) / (Lm * Lm)
    gLf = -2.0 * d / (Lm * Lm)
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, band=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if band is not None:
        lo, hi = band
        fg = (lambda hh: _fun_grad_band(hh, lo, hi))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _band_stats(h, lo, hi):
    Lf = _knots(h)
    Lm = Lf.max()
    if Lm <= 0:
        return 0.0, 0.0
    mask = (Lf > lo * Lm) & (Lf < hi * Lm)
    frac = np.mean(mask)
    if not np.any(mask):
        return frac, 0.0
    gap = np.mean((Lm - Lf[mask]) / Lm)
    return frac, gap


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    cur = start_best.copy()
    curR = start_bestR

    bands = [(0.5, 0.999), (0.3, 0.99), (0.7, 0.999)]
    cycle = 0
    while time.process_time() < deadline - 3.0:
        cycle += 1
        for (lo, hi) in bands:
            if time.process_time() >= deadline - 3.0:
                break
            f0, g0 = _band_stats(cur, lo, hi)
            r_before = curR
            hb = _lbfgs_log(cur, 200, deadline, band=(lo, hi))
            f1, g1 = _band_stats(hb, lo, hi)
            rb = R_of(hb)
            hs = _lbfgs_log(hb, 150, deadline)
            rs = R_of(hs)
            hw = _window_polish_peak(hs, deadline, 0.10, 64,
                                     maxiter=200, beta=1e7)
            rw = R_of(hw)
            cand, rc = (hw, rw) if rw > rs else (hs, rs)
            if rc > curR + 1e-13:
                cur, curR = cand, rc
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
            print("cyc %d band(%.2f,%.3f) frac=%.3f gap %.4f->%.4f R %.7f->%.7f"
                  % (cycle, lo, hi, f0, g0, g1, r_before, curR))

        # Keep the base's full-array softmax + sharp polish.
        if time.process_time() < deadline - 3.0:
            hb = _lbfgs_log(best, 200, deadline, beta=1e7)
            rb = R_of(hb)
            if rb > bestR + 1e-13:
                best, bestR = hb, rb
                cur, curR = hb.copy(), rb
        if time.process_time() < deadline - 3.0:
            hs = _lbfgs_log(best, 200, deadline)
            rs = R_of(hs)
            if rs > bestR + 1e-13:
                best, bestR = hs, rs
                cur, curR = hs.copy(), rs
        zf = 100.0 * np.mean(best <= 0)
        print("cycle %d R=%.7f zeros=%.1f%%" % (cycle, bestR, zf))

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 200, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

