    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolong2(h, soften=1.0):
    n = h.size
    h = np.asarray(h, dtype=float)
    x = np.arange(n, dtype=float)
    xn = np.linspace(0.0, n - 1.0, 2 * n - 1)
    hn = np.interp(xn, x, h)
    if soften != 1.0:
        s = hn.sum()
        if s > 0:
            k = np.ones(3) / 3.0
            hs = np.convolve(hn, k, mode='same')
            hn = soften * hn + (1.0 - soften) * hs
    return np.clip(hn, 0, None)


def _refine_peak_only(h, deadline, iters=400):
    lo, hi = _peak_region(h, tol=0.995)
    pad = max(8, (hi - lo) // 4)
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h, free, maxiter=iters, deadline=deadline)
    r1 = R_of(h2)
    r0 = R_of(h)
    if r1 > r0:
        return h2
    lo2 = max(0, lo - 2 * pad)
    hi2 = min(h.size - 1, hi + 2 * pad)
    free2 = np.arange(lo2, hi2 + 1)
    h3 = _lbfgs_block(h, free2, maxiter=iters, deadline=deadline)
    return h3 if R_of(h3) > r0 else h


def _subsample(h, k):
    """Downsample by factor k (block-average), keeping total mass shape."""
    n = h.size
    m = n // k
    if m < 1:
        return h.copy()
    hh = h[:m * k].reshape(m, k).mean(axis=1)
    return np.clip(hh, 0, None)


def _upsample_block(h, k):
    """Upsample by factor k using piecewise-constant (repeat) expansion."""
    return np.repeat(np.clip(h, 0, None), k).astype(float)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    cur = start_best.copy()
    curR = start_bestR
    rng = np.random.default_rng(99991)
    betas = [0.0, 1e6, 1e7, 1e8, 1e9]
    extras = [32, 64, 128, 256]

    # NEW: coarse-to-fine search. Try both downsampling (to smooth out
    # discretization noise, giving a cleaner global optimum at low N)
    # and upsampling back. This attacks the plateau of near-optimal
    # shapes from a different scale, which the local polish can't.
    alt_best = None
    alt_bestR = 0.0

    def _try_scale(n_target, src, iters=400, label=""):
        nonlocal best, bestR, cur, curR, alt_best, alt_bestR
        if time.process_time() >= deadline - 3.0:
            return
        n0 = src.size
        if n_target < n0:
            k = max(1, int(round(n0 / n_target)))
            hs = _subsample(src, k)
        elif n_target > n0:
            k = max(1, int(round(n_target / n0)))
            hs = _upsample_block(src, k)
        else:
            hs = src.copy()
        if hs.size < 8:
            return
        hs = _rescale(hs)
        # polish the whole thing at new resolution
        hs = _lbfgs_log(hs, iters, deadline)
        rs = R_of(hs)
        if rs > bestR + 1e-13:
            best, bestR = hs.copy(), rs
            cur, curR = hs.copy(), rs
            print("  scale %s N=%d R=%.7f" % (label, hs.size, rs))
        elif rs > alt_bestR + 1e-13:
            alt_best, alt_bestR = hs.copy(), rs
        # bring result back to original scale and polish
        if time.process_time() < deadline - 3.0 and hs.size != n0:
            if hs.size > n0:
                k = max(1, int(round(hs.size / n0)))
                hb = _subsample(hs, k)
            else:
                k = max(1, int(round(n0 / hs.size)))
                hb = _upsample_block(hs, k)
            hb = _rescale(hb)
            hb = _lbfgs_log(hb, iters, deadline)
            rb = R_of(hb)
            if rb > bestR + 1e-13:
                best, bestR = hb.copy(), rb
                cur, curR = hb.copy(), rb
                print("  back  %s N=%d R=%.7f" % (label, hb.size, rb))
            elif rb > alt_bestR + 1e-13:
                alt_best, alt_bestR = hb.copy(), rb

    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        frac = float(np.exp(rng.uniform(np.log(0.02), np.log(0.45))))
        extra = int(extras[rng.integers(len(extras))])
        beta = float(betas[rng.integers(len(betas))])

        hw = _window_polish_peak(cur, deadline, frac, extra,
                                 maxiter=300, beta=beta)
        rw = R_of(hw)
        if rw > curR + 1e-13:
            cur, curR = hw, rw
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR

        if it % 3 == 0 and time.process_time() < deadline - 2.0:
            mx = cur.max()
            if mx > 0:
                cur = cur.copy()
                cur[cur < 1e-4 * mx] = 0.0
                curR = R_of(cur)
            if time.process_time() < deadline - 2.0:
                hs = _lbfgs_log(cur, 200, deadline)
                rs = R_of(hs)
                if rs > curR + 1e-13:
                    cur, curR = hs, rs
                    if curR > bestR + 1e-13:
                        best, bestR = cur.copy(), curR

        if it % 5 == 0 and time.process_time() < deadline - 2.0:
            hb = _lbfgs_log(best, 200, deadline, beta=1e7)
            rb = R_of(hb)
            if rb > bestR + 1e-13:
                best, bestR = hb, rb
                cur, curR = hb.copy(), rb
            if time.process_time() < deadline - 2.0:
                hs = _lbfgs_log(best, 200, deadline)
                rs = R_of(hs)
                if rs > bestR + 1e-13:
                    best, bestR = hs, rs
                    cur, curR = hs.copy(), rs

        # NEW: multi-scale steps every 4th iteration
        if it % 4 == 0 and time.process_time() < deadline - 6.0:
            n = best.size
            # try a coarser and a finer scale
            scale_opts = [max(64, n // 4), max(64, n // 2),
                          min(900000, n * 2)]
            nt = int(scale_opts[rng.integers(len(scale_opts))])
            _try_scale(nt, best, iters=250,
                       label="it%d" % it)

        # Every 7th: prolong2 refinement (original behavior)
        if it % 7 == 0 and time.process_time() < deadline - 4.0:
            if best.size < 900000:
                try:
                    hd = _prolong2(best, soften=1.0)
                    hd = _refine_peak_only(hd, deadline, iters=200)
                    rd = R_of(hd)
                    if rd > bestR + 1e-13:
                        best, bestR = hd, rd
                        cur, curR = hd.copy(), rd
                        print("  -> doubled to N=%d R=%.7f" % (hd.size, rd))
                except Exception:
                    pass

        zf = 100.0 * np.mean(best <= 0)
        print("it %d R=%.7f zeros=%.1f%% N=%d" % (it, bestR, zf, best.size))

    while time.process_time() < deadline - 0.5:
        if time.process_time() >= deadline - 0.6:
            break
        hf = _lbfgs_log(best, 200, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf
        else:
            break

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    alt = best if bestR > start_bestR - 1e-6 else (alt_best if alt_best is not None else None)
    return {"best": start_best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    """Log-sum-exp smooth approximation of the max (higher beta = sharper)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, int(idx.min()) - 1)
    hi = min(h.size - 1, int(idx.max()) + 1)
    return lo, hi


def _polish(h, deadline, betas=(0.0,)):
    """Polish with a sequence of beta values (continuation)."""
    best = h
    bestR = R_of(h)
    for beta in betas:
        if time.process_time() >= deadline - 0.3:
            break
        cap = min(deadline - 0.2, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, beta=beta)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    # peak-window block refinement at several scales
    for frac in (0.02, 0.05, 0.10, 0.20):
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, beta=0.0)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def _area_average(h, M):
    n = h.size
    if M >= n:
        return h.copy()
    edges = np.linspace(0, n, M + 1)
    out = np.zeros(M)
    for i in range(M):
        a = int(np.floor(edges[i])); b = int(np.ceil(edges[i + 1]))
        a = max(0, min(n, a)); b = max(a + 1, min(n, b))
        out[i] = h[a:b].mean()
    return out


def _prolongate_linear(h, N):
    n = h.size
    if N <= n:
        return h.copy()
    xo = np.linspace(0, 1, n)
    xn = np.linspace(0, 1, N)
    return np.interp(xn, xo, h)


def _dup_prolongate(h, factor):
    if factor <= 1:
        return h.copy()
    return np.repeat(h, factor)


def _coarse_refine(h, Nc, deadline, betas=(0.0, 1e2, 1e3, 1e4)):
    """Work at coarse resolution: average down, optimize with beta continuation."""
    if time.process_time() >= deadline - 0.5:
        return h, R_of(h)
    if Nc >= h.size:
        hc = h.copy()
    else:
        hc = _area_average(h, Nc)
    hc = _rescale(hc)
    bestR = R_of(hc)
    cur = hc
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hn = _lbfgs_log(cur, 200, cap, beta=beta)
        rn = R_of(hn)
        if rn > bestR:
            cur, bestR = hn, rn
    # return prolongated back to original size
    factor = h.size // Nc
    if factor * Nc == h.size and factor > 1:
        hN = _dup_prolongate(cur, factor)
    else:
        hN = _prolongate_linear(cur, h.size)
    return hN, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    hard = t0 + budget_seconds - 1.2

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    N = best.size

    # ---------- Phase 1: coarse-to-fine beta-continuation refinement ----------
    # Work at coarser resolutions first (cheaper, smoother), prolongate, then refine at full N.
    coarse_levels = []
    for divisor in (8, 4, 2):
        if N // divisor >= 256:
            coarse_levels.append(N // divisor)

    # beta continuation schedule: sharpening sequence
    beta_schedule = [0.0, 1e2, 5e2, 2e3, 1e4, 5e4]

    for Nc in coarse_levels:
        if time.process_time() >= hard - 2.0:
            break
        cap = min(hard - 1.5, time.process_time() + 8.0)
        hN, rc = _coarse_refine(best, Nc, cap, betas=beta_schedule)
        # polish at full resolution and keep only if it beats best
        if time.process_time() < hard - 1.0:
            cap2 = min(hard - 0.8, time.process_time() + 4.0)
            hp, rp = _polish(hN, cap2, betas=(0.0, 1e3, 1e4))
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("  coarse Nc=%d -> R=%.9f" % (Nc, bestR))

    # ---------- Phase 2: full-resolution beta continuation + polish ----------
    sweep = 0
    while time.process_time() < hard - 2.0:
        sweep += 1
        improved = False
        for beta in beta_schedule:
            if time.process_time() >= hard - 1.5:
                break
            cap = min(hard - 1.0, time.process_time() + 3.0)
            hq = _lbfgs_log(best, 150, cap, beta=beta)
            rq = R_of(hq)
            if rq > bestR + 1e-14:
                # polish this candidate
                cap2 = min(hard - 0.8, time.process_time() + 4.0)
                hp, rp = _polish(hq, cap2, betas=(0.0, 1e3))
                if rp > bestR + 1e-13:
                    best, bestR = hp, rp
                    improved = True
                    print("  [sweep%d beta=%.0e] R=%.9f" % (sweep, beta, bestR))
        if not improved and sweep > 2:
            # fallback: pure exact-max L-BFGS
            if time.process_time() < hard - 1.5:
                cap = min(hard - 1.0, time.process_time() + 4.0)
                hp, rp = _polish(best, cap, betas=(0.0,))
                if rp > bestR + 1e-13:
                    best, bestR = hp, rp
                    print("  fallback R=%.9f" % bestR)

    if time.process_time() < hard - 0.5:
        hp, rp = _polish(best, hard)
        if rp > bestR:
            best, bestR = hp, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    """L-BFGS over all steps in linear space, allowing zeros to stay zero."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size

    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        # (a) global linear polish
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(best, 600, deadline - 2.0, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        # (b) global linear polish with softmax peak
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(best, 300, deadline - 2.0, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        # (c) window polish ladder
        for (frac, extra, beta) in [(0.05, 64, 1e7), (0.10, 64, 1e8),
                                    (0.25, 128, 1e8), (0.40, 256, 1e8)]:
            if time.process_time() >= deadline - 2.0:
                break
            ht = _window_polish_peak(best, deadline - 2.0, frac, extra,
                                     maxiter=300, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        # (d) sharp full-array polish
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_log(best, 250, deadline - 2.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r

        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, 100.0 * np.mean(best <= 0), am, N))

    # Final: two sharp full-array polishes
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 2000, deadline - 0.2)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

