    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # First global polish on the start (keep base's good behavior).
    if time.process_time() < deadline - 8.0:
        h_try = _lbfgs_all_pos(best, 800, deadline - 6.0)
        r = R_of(h_try)
        if r > bestR + 1e-14:
            best, bestR = h_try.copy(), r
            print("global polish: R=%.7f" % bestR)

    N = best.size
    n_idx = np.arange(N, dtype=float)

    # --- Experiment: antisymmetric sub-lattice split ---
    accepted = False
    eps_list = [3e-3, 3e-2, 0.15]
    k_list = [1, 2, 3, 5]
    phi_list = [0.0, np.pi / 2, np.pi, 3 * np.pi / 2]

    for eps in eps_list:
        if accepted:
            break
        for k in k_list:
            if accepted:
                break
            for phi in phi_list:
                if time.process_time() >= deadline - 6.0:
                    break
                m = np.cos(2.0 * np.pi * k * n_idx / N + phi)
                h2 = np.empty(2 * N)
                h2[0::2] = best * (1.0 + eps * m)
                h2[1::2] = best * (1.0 - eps * m)
                h2 = h2 / 2.0
                h2 = _rescale(h2)
                h2 = _lbfgs_all_pos(h2, 500, deadline - 3.0, beta=0.0)
                if time.process_time() >= deadline - 3.0:
                    break
                h2 = _window_polish_peak(h2, deadline - 3.0, 0.15, 128,
                                         maxiter=250, beta=1e8)
                r = R_of(h2)
                if r > bestR + 1e-14:
                    best, bestR = h2.copy(), r
                    accepted = True
                    print("eps=%.0e k=%d phi=%.2f R=%.7f N=%d"
                          % (eps, k, phi, bestR, best.size))
                    break

    # --- After acceptance (or if grid exhausted): cycle polish at N=84992 ---
    N2 = 2 * N
    if best.size != N2:
        # upsample best to N2 via linear interpolation (keeps symmetry)
        idx_old = np.linspace(0.0, N2 - 1.0, N) * (N - 1.0) / (N2 - 1.0)
        # simpler: linear interp of best onto 2N grid
        x_old = np.arange(N, dtype=float)
        x_new = np.arange(N2, dtype=float) * (N - 1.0) / (N2 - 1.0)
        h_up = np.interp(x_new, x_old, best)
        h_up = _rescale(h_up)
        r_up = R_of(h_up)
        if r_up > bestR - 1e-6:
            # only adopt as working vector for cycling; keep best if better
            work = h_up
            workR = r_up
        else:
            work = best.copy()
            workR = bestR
    else:
        work = best.copy()
        workR = bestR

    if accepted or work.size == N2:
        while time.process_time() < deadline - 2.0:
            h_try = _lbfgs_all_pos(work, 400, deadline - 1.5)
            r = R_of(h_try)
            if r > workR + 1e-15:
                work, workR = h_try.copy(), r
                if workR > bestR + 1e-14:
                    best, bestR = work.copy(), workR
                    print("cycle all-pos R=%.7f" % bestR)
            if time.process_time() >= deadline - 2.0:
                break
            h_try = _window_polish_peak(work, deadline - 1.0, 0.15, 128,
                                        maxiter=250, beta=1e8)
            r = R_of(h_try)
            if r > workR + 1e-15:
                work, workR = h_try.copy(), r
                if workR > bestR + 1e-14:
                    best, bestR = work.copy(), workR
                    print("cycle window R=%.7f" % bestR)
            if time.process_time() >= deadline - 2.0:
                break
            h_try = _window_polish_peak(work, deadline - 1.0, 0.5, 256,
                                        maxiter=250, beta=0.0)
            r = R_of(h_try)
            if r > workR + 1e-15:
                work, workR = h_try.copy(), r
                if workR > bestR + 1e-14:
                    best, bestR = work.copy(), workR
                    print("cycle window2 R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

