        Lf = _knots(h)
        am = int(np.argmax(Lf))
        zf = 100.0 * np.mean(h <= 0)
        print("cycle=%d R=%.7f zeros=%.1f%% argmax=%d best=%.7f"
              % (cycle, r, zf, am, bestR))
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            print("  ACCEPT cycle=%d new best=%.7f" % (cycle, bestR))

    # --- Final residual budget: two global linear polishes ---
    if time.process_time() < deadline - 1.0:
        hf = _lbfgs_all_pos(best, 3000, deadline - 0.5)
        rf = R_of(hf)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf
    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_all_pos(best, 2000, deadline - 0.2)
        rf = R_of(hf)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    """L-BFGS over all steps in linear space, allowing zeros to stay zero."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _relocate_quarter(h, quarter, shift):
    """Move the heights of one quarter by `shift` steps (right if positive).
    Vacated edge steps are zero-filled; anything pushed past the ends is dropped."""
    n = h.size
    h2 = h.copy()
    q = n // 4
    lo = quarter * q
    hi = n if quarter == 3 else (quarter + 1) * q
    block = h[lo:hi].copy()
    h2[lo:hi] = 0.0
    nlo = lo + shift
    nhi = hi + shift
    # clip destination to [0, n)
    src_lo = max(0, -nlo)
    src_hi = block.size - max(0, nhi - n)
    if src_hi <= src_lo:
        return h2
    dlo = nlo + src_lo
    dhi = dlo + (src_hi - src_lo)
    h2[dlo:dhi] += block[src_lo:src_hi]
    return h2


def _short_cycle(h, deadline):
    """A shortened cycle: global polish + two window passes + log polish."""
    best = h
    if time.process_time() < deadline - 0.3:
        ht = _lbfgs_all_pos(best, 600, deadline, beta=0.0)
        if R_of(ht) > R_of(best):
            best = ht
    for (frac, extra, beta) in [(0.10, 64, 1e8), (0.25, 128, 1e8)]:
        if time.process_time() >= deadline - 0.3:
            break
        ht = _window_polish_peak(best, deadline, frac, extra,
                                 maxiter=300, beta=beta)
        if R_of(ht) > R_of(best):
            best = ht
    if time.process_time() < deadline - 0.3:
        ht = _lbfgs_log(best, 200, deadline)
        if R_of(ht) > R_of(best):
            best = ht
    return best


def _relocation_sweep(best, bestR, deadline):
    """Try relocating each quarter by a few shifts; return (best, bestR, accepted)."""
    shifts = [-16, -8, -4, 4, 8, 16]
    for quarter in range(4):
        for shift in shifts:
            if time.process_time() >= deadline - 0.5:
                return best, bestR, False
            h2 = _relocate_quarter(best, quarter, shift)
            h2 = _rescale(h2)
            r0 = R_of(h2)
            h2 = _short_cycle(h2, deadline)
            r = R_of(h2)
            Lf = _knots(h2)
            am = int(np.argmax(Lf))
            print("reloc q=%d shift=%+d R0=%.7f R=%.7f argmax=%d/%d"
                  % (quarter, shift, r0, r, am, h2.size))
            if r > bestR + 1e-13:
                return h2, r, True
    return best, bestR, False


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size

    # Pre-loop relocation attempt
    if time.process_time() < deadline - 3.0:
        best, bestR, acc = _relocation_sweep(best, bestR, deadline - 2.0)
        if acc:
            print("pre-loop relocation accepted R=%.7f" % bestR)

    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        # (a) global linear polish
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(best, 600, deadline - 2.0, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        # (b) global linear polish with softmax peak
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(best, 300, deadline - 2.0, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        # (c) window polish ladder
        for (frac, extra, beta) in [(0.05, 64, 1e7), (0.10, 64, 1e8),
                                    (0.25, 128, 1e8), (0.40, 256, 1e8)]:
            if time.process_time() >= deadline - 2.0:
                break
            ht = _window_polish_peak(best, deadline - 2.0, frac, extra,
                                     maxiter=300, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        # (d) sharp full-array polish
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_log(best, 250, deadline - 2.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r

        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, 100.0 * np.mean(best <= 0), am, N))

        # Relocation attempt every 2 cycles
        if cycle % 2 == 0 and time.process_time() < deadline - 3.0:
            best, bestR, acc = _relocation_sweep(best, bestR, deadline - 2.0)
            if acc:
                print("relocation accepted after cycle %d R=%.7f" % (cycle, bestR))

    # Final: two sharp full-array polishes
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 2000, deadline - 0.2)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

