    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _window_polish_peak(h, deadline, frac, extra, maxiter=300):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Precompute the sorted-by-value order of knots once per N for the
    # "support-trimming" move below.
    N = best.size

    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        # Global polish on the exact single-max objective.
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(best, 1500, deadline - 2.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r

        # Multi-scale peak-window polish (different from previous program: no
        # beta-smoothing; instead progressively wider windows around the argmax).
        for (frac, extra) in [(0.03, 48), (0.08, 96), (0.18, 192),
                              (0.35, 384), (0.60, 640)]:
            if time.process_time() >= deadline - 2.0:
                break
            ht = _window_polish_peak(best, deadline - 2.0, frac, extra,
                                     maxiter=400)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r

        # Targeted trimming: try zeroing the smallest-height entries in a
        # small contiguous band and re-polish; this can escape a local max
        # where a low tail is holding ||f*f||_1 up without helping the norm.
        if time.process_time() < deadline - 3.0:
            h = best
            Lf = _knots(h)
            m = int(np.argmax(Lf))
            # candidate trim: entries far from the peak on the smaller tail side
            left = np.arange(0, min(m, h.size))
            right = np.arange(min(m + 1, h.size), h.size)
            cands = []
            if left.size > 8:
                cands.append(("L", left[:max(1, left.size // 20)]))
            if right.size > 8:
                cands.append(("R", right[-max(1, right.size // 20):]))
            for tag, idxs in cands:
                if time.process_time() >= deadline - 3.0:
                    break
                h2 = h.copy()
                h2[idxs] = 0.0
                if h2.sum() <= 0:
                    continue
                h2 = _rescale(h2)
                ht = _lbfgs_all_pos(h2, 400, deadline - 2.0)
                r = R_of(ht)
                if r > bestR + 1e-13:
                    best, bestR = ht.copy(), r
                    break

        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, 100.0 * np.mean(best <= 0), am, N))

    # Final long polish.
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 8000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _window_polish_peak(best, deadline - 0.2, 0.5, 512, maxiter=1000)
