def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16, 'maxcor': 20})
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16, 'maxcor': 20})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _polish(h, deadline, budget_sub):
    cur = _rescale(np.asarray(h, dtype=float))
    cur_r = R_of(cur)
    t_end = min(deadline - 0.5, time.process_time() + budget_sub)

    for _ in range(3):
        if time.process_time() >= t_end:
            break
        c = _lbfgs_all_pos(cur, maxiter=800, deadline=t_end)
        r = R_of(c)
        if r > cur_r:
            cur, cur_r = c, r
        for beta in (32, 64, 128):
            if time.process_time() >= t_end:
                break
            c = _lbfgs_all_pos(cur, maxiter=400, deadline=t_end, beta=beta)
            r = R_of(c)
            if r > cur_r:
                cur, cur_r = c, r
        for frac, extra in ((0.05, 4), (0.10, 8), (0.20, 16)):
            if time.process_time() >= t_end:
                break
            free = _peak_window(cur, tol=0.999, pad_frac=frac, extra=extra)
            c = _lbfgs_block(cur, free, maxiter=600, deadline=t_end)
            r = R_of(c)
            if r > cur_r:
                cur, cur_r = c, r
        if time.process_time() >= t_end:
            break
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    start_arr = None
    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(64)
        best_r = R_of(best)

    print("start R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None and start_arr.size >= 64:
        levels = []
        n = start_arr.size
        for _ in range(4):
            n = max(64, n // 2)
            levels.append(n)
        levels = sorted(set(levels))
        seed = _rescale(best.copy())
        for N in levels:
            if time.process_time() > deadline - 6.0:
                break
            small = _rescale(_coarsen(seed, N)) if seed.size != N else seed
            frac = 0.30 if N <= 256 else 0.20
            sub = max(1.0, (deadline - time.process_time()) * frac)
            small, sr = _polish(small, deadline, budget_sub=sub)
            up = _rescale(_prolongate(small, min(start_arr.size, max(N * 2, N + 32))))
            up, ur = _polish(up, deadline, budget_sub=max(1.0,
                            (deadline - time.process_time()) * 0.20))
            seed = up
            print("  coarsen/grow N=%d -> R=%.6f" % (up.size, ur))

        if seed.size != start_arr.size:
            seed = _rescale(_prolongate(seed, start_arr.size))
        cur, cur_r = _polish(seed, deadline,
                             budget_sub=max(1.0, deadline - time.process_time() - 0.5))
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
            print("  coarsen pipeline -> R=%.6f" % best_r)

    if time.process_time() < deadline - 1.0:
        cur, cur_r = _polish(best.copy(), deadline,
                             budget_sub=max(1.0, deadline - time.process_time() - 0.5))
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
            print("  final polish -> R=%.6f" % best_r)

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    m = L.max()
    if m <= 0:
        return -1.0
    a = L[:-1]; b = L[1:]
    sq = np.sum(a * a + a * b + b * b) / 3.0
    return float(sq / (s * s * m))


def _num_and_dq(h):
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(L)
    dq[:-1] += (2.0 * a + b) / 3.0
    dq[1:] += (a + 2.0 * b) / 3.0
    return num, dq, L


def _backprop(gL, h):
    n = h.size
    g = gL[1:-1]
    if n > 1500:
        return 2.0 * fftconvolve(g, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(g, h, mode='valid')[:n]


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, L = _num_and_dq(h)
    k = int(np.argmax(L))
    m = L[k]
    if m <= 0 or num <= 0:
        return 1e18, np.zeros(h.size)
    gL = -dq / num
    gL[k] += 1.0 / m
    gh = _backprop(gL, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(m)
    return val, gh


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(np.asarray(h0, dtype=float), 0, None)
    if h.sum() <= 0:
        return h0
    u0 = np.log(np.clip(h, 1e-12, None))

    def f(u):
        hh = np.exp(np.clip(u, -50.0, 50.0))
        val, g = _fun_grad(hh)
        return val, g * hh

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    return np.exp(np.clip(res.x, -50.0, 50.0))


def _lbfgs_block(h0, lo, hi, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(np.asarray(h0, dtype=float), 0, None)
    if h.sum() <= 0 or hi <= lo:
        return h0
    x0 = np.log(np.clip(h[lo:hi], 1e-12, None))

    def f(x):
        hh = h.copy()
        hh[lo:hi] = np.exp(np.clip(x, -50.0, 50.0))
        val, g = _fun_grad(hh)
        return val, g[lo:hi] * hh[lo:hi]

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    out = h.copy()
    out[lo:hi] = np.exp(np.clip(res.x, -50.0, 50.0))
    return out


def _resample_lin(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    edges = np.linspace(0.0, total, N + 1)
    vals = np.interp(edges, c, np.arange(M + 1, dtype=float))
    F = np.interp(vals, np.arange(M + 1, dtype=float), c)
    width = edges[1] - edges[0]
    out = np.diff(F) / width
    return np.maximum(out, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    def left():
        return deadline - time.process_time()

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            bestR = _R_of(best)

    if best is None:
        best = np.ones(256)
        bestR = _R_of(best)

    # Multi-resolution search: try going up and down, keep the best.
    # Start with fine full polish at current size.
    cur = best.copy()
    curR = bestR

    # Full polish first.
    c = _lbfgs_log(cur, 400, deadline)
    r = _R_of(c)
    if r > curR:
        cur, curR = c, r

    # Try a ladder of resolutions; at each, run full + window polishing.
    base_n = max(64, cur.size)
    targets = []
    for mult in (0.5, 1.0, 2.0, 4.0, 8.0):
        N = int(base_n * mult)
        if 32 <= N <= 100000:
            targets.append(N)
    targets = sorted(set(targets))

    for N in targets:
        if left() < 1.0:
            break
        cand = _resample_lin(cur, N) if N != cur.size else cur.copy()
        r0 = _R_of(cand)
        if r0 < curR - 0.05:
            continue
        it = max(60, min(300, int(left() * 15)))
        c1 = _lbfgs_log(cand, it, deadline)
        r1 = _R_of(c1)
        if r1 > r0:
            cand, r0 = c1, r1
        if r0 > curR:
            cur, curR = cand, r0
        if curR > bestR:
            best, bestR = cur.copy(), curR

    # Window polish loop on best, targeting the peak region.
    fracs = (0.03, 0.06, 0.10, 0.18, 0.30)
    fi = 0
    while left() > 0.4:
        n = best.size
        L = _knots(best)
        k = int(np.argmax(L))
        f = fracs[fi % len(fracs)]
        fi += 1
        half = max(4, int(f * n))
        lo = max(0, (k - half) // 2 - 6)
        hi = min(n, (k + half) // 2 + 7)
        it = max(40, min(400, int(left() * 20)))
        cand = _lbfgs_block(best, lo, hi, it, deadline)
        r = _R_of(cand)
        if r > bestR:
            best, bestR = cand, r
        # Occasionally do a full polish.
        if fi % 4 == 0 and left() > 1.0:
            it = max(60, min(300, int(left() * 15)))
            cand = _lbfgs_log(best, it, deadline)
            r = _R_of(cand)
            if r > bestR:
                best, bestR = cand, r

    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _refine_upsample(best, deadline):
    """2x duplication upsample + halo, then polish at finer resolution."""
    h1 = np.repeat(best, 2)
    r_before = R_of(h1)
    print("upsample R=%.7f vs base R=%.7f (N=%d)"
          % (r_before, R_of(best), h1.size))
    pad = 6000
    halo = 1e-3 * h1.mean()
    h1 = np.concatenate((np.full(pad, halo), h1, np.full(pad, halo)))
    h1 = _rescale(h1)
    r1 = R_of(h1)
    print("refined R=%.7f (N=%d)" % (r1, h1.size))
    best1, bestR1 = h1.copy(), r1
    # 3 beta-softmax peak-window block passes
    for frac in (0.25, 0.40, 0.60):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best1, pad_frac=frac, extra=512)
        ht = _lbfgs_block(best1, win, maxiter=250, deadline=deadline - 0.5,
                          beta=1e8)
        r = R_of(ht)
        if r > bestR1 + 1e-13:
            best1, bestR1 = ht.copy(), r
    # global beta=0
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best1, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR1 + 1e-13:
            best1, bestR1 = ht.copy(), r
    print("refined after polish R=%.7f" % bestR1)
    return best1, bestR1


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Phase C: base cycle loop, but leave time for the refine ----
    # Reserve ~40% of the budget for the upsample+polish phase.
    refine_start = t0 + budget_seconds * 0.55
    cycle = 0
    while time.process_time() < refine_start - 1.0:
        cycle += 1
        prevR = bestR
        best, bestR, drefine = run_cycle(best, bestR, refine_start - 0.5)
        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f dR=%.2e drefine=%.2e zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, bestR - prevR, drefine,
                 100.0 * np.mean(best <= 0), am, best.size))
        if bestR - prevR < 1e-13 and cycle > 2:
            if time.process_time() > refine_start - 3.0:
                break

    # ---- Phase D: 2x duplication refine ----
    best1, bestR1 = None, 0.0
    if time.process_time() < deadline - 3.0:
        best1, bestR1 = _refine_upsample(best, deadline - 1.0)

    # ---- Phase E: alternate polishing whichever is better ----
    if best1 is not None:
        cycle2 = 0
        while time.process_time() < deadline - 2.0:
            cycle2 += 1
            prevR1 = bestR1
            best1, bestR1, _ = run_cycle(best1, bestR1, deadline - 1.0)
            print("ref cycle %d R=%.7f dR=%.2e zeros=%.1f%%"
                  % (cycle2, bestR1, bestR1 - prevR1,
                     100.0 * np.mean(best1 <= 0)))
            if bestR1 - prevR1 < 1e-13 and cycle2 > 2:
                break
            # also keep polishing the coarse best if it's still competitive
            if bestR > bestR1 - 1e-6 and time.process_time() < deadline - 4.0:
                best, bestR, _ = run_cycle(best, bestR, deadline - 3.0)

    # pick the winner
    if best1 is not None and bestR1 > bestR:
        winner, winnerR = best1, bestR1
    else:
        winner, winnerR = best, bestR

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(winner, 3000, deadline - 0.5)
        r = R_of(ht)
        if r > winnerR + 1e-14:
            winner, winnerR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (winnerR, winner.size, 100.0 * np.mean(winner <= 0)))

    if winnerR > start_bestR + 1e-12:
        return winner
    out = {"best": start_best}
    if winnerR > start_bestR - 1e-6:
        out["alternative"] = winner
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    eps = 1e-12
    u0 = np.log(np.clip(h, eps, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        hh = np.exp(np.clip(u, -50.0, 50.0))
        val, g = fg(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(np.clip(res.x, -50.0, 50.0)))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, beta=0.0):
    best = h
    bestR = R_of(h)
    if time.process_time() >= deadline - 0.3:
        return best, bestR
    cap = min(deadline - 0.2, time.process_time() + 2.0)
    hp = _lbfgs_log(best, 300, cap, beta=beta)
    rp = R_of(hp)
    if rp > bestR:
        best, bestR = hp, rp
    for frac in (0.02, 0.05, 0.10, 0.20):
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, beta=beta)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard = t0 + budget_seconds - 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Phase 1: polish the start with a full log-LBFGS + block polish
    if time.process_time() < hard - 5.0:
        cap = min(hard - 3.0, time.process_time() + 8.0)
        hp, rp = _polish(best, cap)
        if rp > bestR + 1e-14:
            best, bestR = hp, rp
            print("  polish start -> R=%.9f" % bestR)

    # Phase 2: beta-continuation sweep on smoothed max
    betas = [1e2, 1e3, 1e4, 1e5, 1e6]
    sweep = 0
    stall = 0
    while time.process_time() < hard - 3.0:
        sweep += 1
        improved = False
        for b in betas:
            if time.process_time() >= hard - 3.0:
                break
            cap = min(hard - 2.0, time.process_time() + 3.0)
            hq = _lbfgs_log(best, 200, cap, beta=b)
            rq = R_of(hq)
            # polish with true objective
            cap2 = min(hard - 1.0, time.process_time() + 4.0)
            hp, rp = _polish(hq, cap2, beta=0.0)
            beat = rp > bestR + 1e-14
            print("  [sweep%d beta=%.0e] Rq=%.9f polish=%.9f %s" %
                  (sweep, b, rq, rp, "BEAT" if beat else ""))
            if beat:
                best, bestR = hp, rp
                improved = True
                stall = 0
                print("    new best R=%.9f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < hard - 4.0:
                # fallback: full log-LBFGS from best
                cap = min(hard - 2.0, time.process_time() + 5.0)
                hp = _lbfgs_log(best, 500, cap, beta=0.0)
                rp = R_of(hp)
                if rp > bestR + 1e-13:
                    best, bestR = hp, rp
                    print("    fallback best R=%.9f" % bestR)
                    stall = 0
                else:
                    break

    if time.process_time() < hard - 0.5:
        hp, rp = _polish(best, hard)
        if rp > bestR:
            best, bestR = hp, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _prune(h, q):
    h = np.clip(h, 0, None).copy()
    pos = np.flatnonzero(h > 0)
    npos = pos.size
    if npos == 0:
        return _rescale(h)
    k = int(q * npos)
    if k <= 0:
        return _rescale(h)
    if k >= npos:
        k = npos - 1
    vals = h[pos]
    order = np.argsort(vals)
    kill = pos[order[:k]]
    h[kill] = 0.0
    return _rescale(h)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _shift(h, k):
    """Shift support by k steps (positive = right), padding with zeros."""
    if k == 0:
        return h
    n = h.size
    out = np.zeros(n)
    if k > 0:
        if k < n:
            out[k:] = h[:n - k]
    else:
        k = -k
        if k < n:
            out[:n - k] = h[k:]
    return out


def _compress_support(h):
    """Trim leading/trailing zeros to reduce N (shape unchanged)."""
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h
    lo, hi = nz[0], nz[-1]
    if hi - lo + 1 < h.size:
        return h[lo:hi + 1]
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase A: global linear polish
    if time.process_time() < deadline - 5.0:
        h_try = _lbfgs_all_pos(best, 2000, deadline - 3.0)
        r = R_of(h_try)
        if r > bestR:
            best, bestR = h_try.copy(), r
            print("global linear polish: R=%.7f" % bestR)

    # Phase B: peak window polishes
    if time.process_time() < deadline - 4.0:
        for frac, extra, beta in [(2.0, 512, 0.0), (1.0, 256, 0.0),
                                  (0.5, 128, 1e7), (0.25, 64, 1e8)]:
            if time.process_time() >= deadline - 3.0:
                break
            h_try = _window_polish_peak(best, deadline - 2.0, frac, extra,
                                        maxiter=400, beta=beta)
            r = R_of(h_try)
            if r > bestR + 1e-14:
                best, bestR = h_try.copy(), r
                print("window polish frac=%.2f beta=%.0e R=%.7f" % (frac, beta, bestR))

    # Phase C: prune + regrow search with multiple restarts
    qs = [0.01, 0.03, 0.08, 0.15]
    rng = np.random.RandomState(98765)
    pass_no = 0
    while time.process_time() < deadline - 2.0:
        pass_no += 1
        order = list(qs)
        rng.shuffle(order)
        for q in order:
            if time.process_time() >= deadline - 2.0:
                break
            hp = _prune(best, q)
            pruned_pos = np.flatnonzero((best > 0) & (hp <= 0))
            hp = _lbfgs_all_pos(hp, 1200, deadline - 2.0, beta=0.0)
            if time.process_time() >= deadline - 2.0:
                break
            hp = _window_polish_peak(hp, deadline - 2.0, 0.25, 128,
                                     maxiter=250, beta=1e8)
            if time.process_time() >= deadline - 2.0:
                break
            hp = _lbfgs_log(hp, 250, deadline - 2.0)
            r = R_of(hp)
            revived = int(np.sum(hp[pruned_pos] > 0)) if pruned_pos.size else 0
            zf = 100.0 * np.mean(hp <= 0)
            print("prune pass=%d q=%.2f R=%.7f revived=%d/%d zeros=%.1f%% best=%.7f"
                  % (pass_no, q, r, revived, pruned_pos.size, zf, bestR))
            if r > bestR + 1e-13:
                best, bestR = hp.copy(), r
                print("  ACCEPT q=%.2f new best=%.7f" % (q, bestR))

    # Phase D: coordinate resampling — random sub-block optimization on random
    # windows to escape local optima (the key new idea)
    n = best.size
    block_attempts = 0
    while time.process_time() < deadline - 1.5:
        block_attempts += 1
        # pick a random window length and location
        wlen = int(n * rng.uniform(0.02, 0.25))
        wlen = max(32, min(n, wlen))
        lo = rng.randint(0, max(1, n - wlen))
        hi = lo + wlen
        free = np.arange(lo, hi)
        h_try = _lbfgs_block(best, free, maxiter=400, deadline=deadline - 1.0,
                             beta=0.0)
        r = R_of(h_try)
        if r > bestR + 1e-14:
            best, bestR = h_try, r
            print("block (D) wlen=%d R=%.7f" % (wlen, bestR))
            # follow with a peak polish
            h_try2 = _window_polish_peak(best, deadline - 1.0, 0.25, 128,
                                         maxiter=200, beta=1e8)
            r2 = R_of(h_try2)
            if r2 > bestR + 1e-14:
                best, bestR = h_try2, r2
        if block_attempts % 8 == 0 and time.process_time() < deadline - 2.0:
            # re-seed zeros and do a global polish to consolidate
            hs = _seed_zeros(best)
            hs = _lbfgs_all_pos(hs, 800, deadline - 1.0, beta=0.0)
            r = R_of(hs)
            if r > bestR + 1e-14:
                best, bestR = _compress_support(hs), r
                print("reseed+global R=%.7f (N=%d)" % (bestR, best.size))

    # Final aggressive polish
    if time.process_time() < deadline - 0.8:
        hf = _lbfgs_all_pos(best, 3000, deadline - 0.4)
        rf = R_of(hf)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf
        hf = _window_polish_peak(best, deadline - 0.3, 0.5, 128, maxiter=400)
        rf = R_of(hf)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf
        hf = _lbfgs_log(_seed_zeros(best), 400, deadline - 0.2)
        rf = R_of(hf)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    eps = 1e-12
    u0 = np.log(np.clip(h, eps, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        hh = np.exp(np.clip(u, -50.0, 50.0))
        val, g = fg(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(np.clip(res.x, -50.0, 50.0)))


def _refine_knots(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h0
    idx = np.flatnonzero(Lf >= 0.98 * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    win = np.arange(lo, hi + 1)
    zeros = win[h[win] <= 0]
    if zeros.size == 0:
        return h0
    h2 = h.copy()
    h2[zeros] = 1e-3 * h.mean()
    return _lbfgs_block(h2, win, maxiter, deadline, beta=1e8)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _grow_boundary(h, grow):
    if grow <= 0:
        return h.copy()
    eps = 1e-3 * h.mean() if h.mean() > 0 else 1e-3
    pad = np.full(grow, eps)
    return np.concatenate([pad, h, pad])


def _upsample2(h):
    out = np.empty(2 * h.size, dtype=float)
    out[0::2] = h
    out[1::2] = h
    return out


def _run_cycle(best, bestR, deadline, cycle_limit=1000):
    cycle = 0
    stale = 0
    while time.process_time() < deadline - 1.5 and cycle < cycle_limit:
        cycle += 1
        prev = bestR
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_all_pos(best, 800, deadline - 1.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_all_pos(best, 400, deadline - 1.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        for frac, extra, beta in ((0.05, 64, 1e7), (0.10, 64, 1e8),
                                  (0.25, 128, 1e8), (0.40, 256, 1e8),
                                  (0.60, 512, 1e8)):
            if time.process_time() >= deadline - 1.5:
                break
            win = _peak_window(best, pad_frac=frac, extra=extra)
            ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 1.5,
                              beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_log(best, 300, deadline - 1.5, beta=1e8)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 1.5:
            ht = _refine_knots(best, 300, deadline - 1.5)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, 100.0 * np.mean(best <= 0), am, best.size))
        if bestR - prev < 1e-12:
            stale += 1
            if stale >= 2:
                break
        else:
            stale = 0
    return best, bestR


def _extend_and_cycle(best, bestR, pad, deadline, tag):
    """Insert one support-extension round then run cycles until plateau."""
    if time.process_time() >= deadline - 8.0:
        return best, bestR
    if best.size + 2 * pad > 1000000:
        pad = max(0, (1000000 - best.size) // 2)
    if pad <= 0:
        return best, bestR
    eps = 1e-3 * best.mean() if best.mean() > 0 else 1e-3
    padarr = np.full(pad, eps)
    h2 = np.concatenate([padarr, best, padarr])
    h2 = _rescale(h2)
    r2 = R_of(h2)
    print("ext %s pad=%d N=%d R=%.7f" % (tag, pad, h2.size, r2))
    cur, curR = h2, r2
    if curR > bestR:
        best, bestR = cur.copy(), curR
    # run cycles repeatedly until plateau or deadline
    while time.process_time() < deadline - 8.0:
        prev = curR
        cur, curR = _run_cycle(cur, curR, deadline - 8.0)
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR
        if curR - prev < 1e-8:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    alt = None
    altR = 0.0
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Phase A: quick polish of start -------
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 600, deadline - 2.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 400, deadline - 2.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    # ---- Phase B: 2x duplication upsample + halo grow -------
    refined = None
    refinedR = 0.0
    if time.process_time() < deadline - 4.0:
        n0 = best.size
        if 2 * n0 <= 1000000:
            h1 = _upsample2(best)
            h1 = _rescale(h1)
            r1 = R_of(h1)
            print("upsample2 N=%d R=%.7f" % (h1.size, r1))
            grow = 8000
            if h1.size + 2 * grow > 1000000:
                grow = max(0, (1000000 - h1.size) // 2)
            if grow > 0:
                h2 = _grow_boundary(h1, grow)
                h2 = _rescale(h2)
                r2 = R_of(h2)
                print("halo grow=%d N=%d R=%.7f" % (grow, h2.size, r2))
                if r2 > r1:
                    h1, r1 = h2, r2
            refined, refinedR = h1, r1
            if refinedR > bestR + 1e-13:
                best, bestR = refined.copy(), refinedR

    # ---- Phase C: beta-softmax window ladder on refined array -------
    if refined is not None and time.process_time() < deadline - 3.0:
        cur, curR = refined.copy(), refinedR
        for frac, extra in ((0.30, 128), (0.40, 128), (0.50, 256), (0.60, 256)):
            if time.process_time() >= deadline - 3.0:
                break
            win = _peak_window(cur, pad_frac=frac, extra=extra)
            ht = _lbfgs_block(cur, win, maxiter=250, deadline=deadline - 3.0,
                              beta=1e8)
            r = R_of(ht)
            if r > curR + 1e-14:
                cur, curR = ht, r
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        refined, refinedR = cur, curR
        print("ladder R=%.7f (N=%d)" % (refinedR, refined.size))

    # ---- Phase D: global polish on refined -------
    if refined is not None and time.process_time() < deadline - 2.5:
        ht = _lbfgs_all_pos(refined, 500, deadline - 2.5, beta=0.0)
        r = R_of(ht)
        if r > refinedR + 1e-14:
            refined, refinedR = ht, r
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if refined is not None and time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(refined, 400, deadline - 2.0, beta=1e7)
        r = R_of(ht)
        if r > refinedR + 1e-14:
            refined, refinedR = ht, r
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if refined is not None:
        alt, altR = refined.copy(), refinedR
        print("refined R=%.7f (N=%d)" % (altR, alt.size))

    # ---- Phase E: run_cycle on refined array -------
    if refined is not None and time.process_time() < deadline - 2.0:
        best, bestR = _run_cycle(best, bestR, deadline - 0.5)
        if refinedR > altR:
            alt, altR = refined, refinedR

    # ---- Phase F: support-extension rounds (the experiment) -------
    # Round 1: pad=5000
    if time.process_time() < deadline - 8.0:
        best, bestR = _extend_and_cycle(best, bestR, 5000, deadline, "1")
    # Round 2: pad=3000
    if time.process_time() < deadline - 8.0:
        best, bestR = _extend_and_cycle(best, bestR, 3000, deadline, "2")

    # ---- final polish -------
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        if alt is not None and altR < bestR - 1e-9 and altR > start_bestR:
            return {"best": best, "alternative": alt}
        return best
    out = {"best": start_best}
    if alt is not None and altR > start_bestR - 1e-6 and altR > 0:
        out["alternative"] = alt
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

