def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _extend(h, pad):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = 1e-3 * h.mean()
    filler = np.full(pad, eps)
    out = np.concatenate((filler, h, filler))
    return _rescale(out)


def _pick_window(best, rng):
    n = best.size
    w = int(rng.choice([400, 1200, 3600]))
    if w >= n:
        return np.arange(n)
    u = rng.random()
    if u < 0.6:
        pw = _peak_window(best, pad_frac=float(rng.uniform(0.03, 0.25)),
                          extra=128)
        lo_p, hi_p = int(pw[0]), int(pw[-1])
        if hi_p - lo_p + 1 <= w:
            center = (lo_p + hi_p) // 2
        else:
            center = int(rng.integers(lo_p, hi_p + 1))
    elif u < 0.8:
        if rng.random() < 0.5:
            center = int(rng.integers(0, max(1, n // 10)))
        else:
            center = int(rng.integers(max(0, n - n // 10), n))
    else:
        center = int(rng.integers(0, n))
    lo = max(0, center - w // 2)
    hi = min(n, lo + w)
    lo = max(0, hi - w)
    return np.arange(lo, hi)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Phase C: base cycle loop ----
    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        prevR = bestR
        best, bestR, drefine = run_cycle(best, bestR, deadline - 1.5)
        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f dR=%.2e drefine=%.2e zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, bestR - prevR, drefine,
                 100.0 * np.mean(best <= 0), am, best.size))
        if bestR - prevR < 1e-13 and cycle > 2:
            if time.process_time() > deadline - 6.0:
                break

    # ---- Phase D: long random sub-block loop ----
    rng = np.random.default_rng(12345)
    it = 0
    accepted = 0
    total_gain = 0.0
    while time.process_time() < deadline - 0.8:
        it += 1
        win = _pick_window(best, rng)
        h = best.copy()
        if rng.random() < 0.5:
            m = h.mean()
            if m > 0:
                z = win[h[win] <= 0]
                if z.size > 0:
                    h[z] = 1e-6 * m
        ht = _lbfgs_block(h, win, maxiter=120, deadline=deadline - 0.8,
                          beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            dR = r - bestR
            best, bestR = ht, r
            accepted += 1
            total_gain += dR
            print("acc it=%d dR=%.2e R=%.7f zeros=%.1f%%"
                  % (it, dR, bestR, 100.0 * np.mean(best <= 0)))

        if it % 25 == 0 and time.process_time() < deadline - 0.8:
            win2 = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win2, maxiter=150, deadline=deadline - 0.8,
                              beta=1e8)
            r = R_of(ht)
            if r > bestR + 1e-13:
                dR = r - bestR
                best, bestR = ht, r
                accepted += 1
                total_gain += dR
                print("acc peak it=%d dR=%.2e R=%.7f" % (it, dR, bestR))

        if it % 60 == 0 and time.process_time() < deadline - 0.8:
            ht = _lbfgs_all_pos(best, 200, deadline - 0.8, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                dR = r - bestR
                best, bestR = ht, r
                accepted += 1
                total_gain += dR
                print("acc global it=%d dR=%.2e R=%.7f" % (it, dR, bestR))

        if it % 120 == 0 and time.process_time() < deadline - 0.8:
            ht = _refine_knots(best, 200, deadline - 0.8)
            r = R_of(ht)
            if r > bestR + 1e-13:
                dR = r - bestR
                best, bestR = ht, r
                accepted += 1
                total_gain += dR
                print("acc refine it=%d dR=%.2e R=%.7f" % (it, dR, bestR))

        if it % 50 == 0:
            Lf = _knots(best)
            am = int(np.argmax(Lf))
            print("it=%d acc=%d R=%.7f gain=%.2e zeros=%.1f%% argmax=%d/%d"
                  % (it, accepted, bestR, total_gain,
                     100.0 * np.mean(best <= 0), am, best.size))

    print("final R=%.7f (N=%d, zeros %.1f%%, accepted=%d)"
          % (bestR, best.size, 100.0 * np.mean(best <= 0), accepted))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    eps = 1e-12
    u0 = np.log(np.clip(h, eps, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        hh = np.exp(np.clip(u, -50.0, 50.0))
        val, g = fg(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(np.clip(res.x, -50.0, 50.0)))


def _refine_knots(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h0
    idx = np.flatnonzero(Lf >= 0.98 * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    win = np.arange(lo, hi + 1)
    zeros = win[h[win] <= 0]
    if zeros.size == 0:
        return h0
    h2 = h.copy()
    h2[zeros] = 1e-3 * h.mean()
    return _lbfgs_block(h2, win, maxiter, deadline, beta=1e8)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _grow_boundary(h, grow):
    if grow <= 0:
        return h.copy()
    eps = 1e-3 * h.mean() if h.mean() > 0 else 1e-3
    pad = np.full(grow, eps)
    return np.concatenate([pad, h, pad])


def _upsample2(h):
    out = np.empty(2 * h.size, dtype=float)
    out[0::2] = h
    out[1::2] = h
    return out


def _run_cycle(best, bestR, deadline, cycle_limit=1000):
    cycle = 0
    stale = 0
    while time.process_time() < deadline - 1.5 and cycle < cycle_limit:
        cycle += 1
        prev = bestR
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_all_pos(best, 800, deadline - 1.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_all_pos(best, 400, deadline - 1.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        for frac, extra, beta in ((0.05, 64, 1e7), (0.10, 64, 1e8),
                                  (0.25, 128, 1e8), (0.40, 256, 1e8),
                                  (0.60, 512, 1e8)):
            if time.process_time() >= deadline - 1.5:
                break
            win = _peak_window(best, pad_frac=frac, extra=extra)
            ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 1.5,
                              beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_log(best, 300, deadline - 1.5, beta=1e8)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 1.5:
            ht = _refine_knots(best, 300, deadline - 1.5)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, 100.0 * np.mean(best <= 0), am, best.size))
        if bestR - prev < 1e-12:
            stale += 1
            if stale >= 2:
                break
        else:
            stale = 0
    return best, bestR


def _phaseD(best, bestR, deadline, rng):
    """Many-small-solves regime tuned for sparse, long arrays."""
    n = best.size
    eps = 1e-6 * best.mean() if best.mean() > 0 else 1e-6
    it = 0
    accepted = 0
    widths = (800, 2400, 6000)
    while time.process_time() < deadline - 0.8:
        it += 1
        # choose window
        u = rng.random()
        if u < 0.50:
            frac = rng.uniform(0.03, 0.30)
            win = _peak_window(best, pad_frac=frac, extra=192)
        elif u < 0.75:
            w = widths[rng.integers(0, len(widths))]
            w = min(w, n)
            if rng.random() < 0.5:
                lo = 0
            else:
                lo = max(0, n - w)
            win = np.arange(lo, min(n, lo + w))
        else:
            w = widths[rng.integers(0, len(widths))]
            w = min(w, n)
            lo = int(rng.integers(0, max(1, n - w + 1)))
            win = np.arange(lo, min(n, lo + w))
        if win.size == 0:
            continue
        h2 = best.copy()
        if rng.random() < 0.7:
            zeros = win[h2[win] <= 0]
            if zeros.size > 0:
                h2[zeros] = eps
        ht = _lbfgs_block(h2, win, maxiter=120, deadline=deadline - 0.8,
                          beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
            accepted += 1

        if it % 20 == 0 and time.process_time() < deadline - 0.8:
            win = _peak_window(best, pad_frac=0.15, extra=192)
            ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.8,
                              beta=1e8)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                accepted += 1

        if it % 50 == 0 and time.process_time() < deadline - 0.8:
            ht = _lbfgs_all_pos(best, 200, deadline - 0.8, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                accepted += 1
            Lf = _knots(best)
            am = int(np.argmax(Lf))
            print("D it=%d acc=%d R=%.7f zeros=%.1f%% argmax=%d/%d"
                  % (it, accepted, bestR, 100.0 * np.mean(best <= 0),
                     am, best.size))

        if it % 100 == 0 and time.process_time() < deadline - 0.8:
            ht = _refine_knots(best, 200, deadline - 0.8)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                accepted += 1

    print("PhaseD done it=%d accepted=%d R=%.7f" % (it, accepted, bestR))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    alt = None
    altR = 0.0
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Phase A: quick polish of start -------
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 600, deadline - 2.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 400, deadline - 2.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    # ---- Phase B: 2x duplication upsample + halo grow -------
    refined = None
    refinedR = 0.0
    if time.process_time() < deadline - 4.0:
        n0 = best.size
        if 2 * n0 <= 1000000:
            h1 = _upsample2(best)
            h1 = _rescale(h1)
            r1 = R_of(h1)
            print("upsample2 N=%d R=%.7f" % (h1.size, r1))
            grow = 8000
            if h1.size + 2 * grow > 1000000:
                grow = max(0, (1000000 - h1.size) // 2)
            if grow > 0:
                h2 = _grow_boundary(h1, grow)
                h2 = _rescale(h2)
                r2 = R_of(h2)
                print("halo grow=%d N=%d R=%.7f" % (grow, h2.size, r2))
                if r2 > r1:
                    h1, r1 = h2, r2
            refined, refinedR = h1, r1
            if refinedR > bestR + 1e-13:
                best, bestR = refined.copy(), refinedR

    # ---- Phase C: beta-softmax window ladder on refined array -------
    if refined is not None and time.process_time() < deadline - 3.0:
        cur, curR = refined.copy(), refinedR
        for frac, extra in ((0.30, 128), (0.40, 128), (0.50, 256), (0.60, 256)):
            if time.process_time() >= deadline - 3.0:
                break
            win = _peak_window(cur, pad_frac=frac, extra=extra)
            ht = _lbfgs_block(cur, win, maxiter=250, deadline=deadline - 3.0,
                              beta=1e8)
            r = R_of(ht)
            if r > curR + 1e-14:
                cur, curR = ht, r
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        refined, refinedR = cur, curR
        print("ladder R=%.7f (N=%d)" % (refinedR, refined.size))

    # ---- Phase D: global polish on refined -------
    if refined is not None and time.process_time() < deadline - 2.5:
        ht = _lbfgs_all_pos(refined, 500, deadline - 2.5, beta=0.0)
        r = R_of(ht)
        if r > refinedR + 1e-14:
            refined, refinedR = ht, r
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if refined is not None and time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(refined, 400, deadline - 2.0, beta=1e7)
        r = R_of(ht)
        if r > refinedR + 1e-14:
            refined, refinedR = ht, r
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if refined is not None:
        alt, altR = refined.copy(), refinedR
        print("refined R=%.7f (N=%d)" % (altR, alt.size))

    # ---- Phase E: run_cycle on refined array -------
    if refined is not None and time.process_time() < deadline - 2.0:
        best, bestR = _run_cycle(best, bestR, deadline - 0.5)
        if refinedR > altR:
            alt, altR = refined, refinedR

    # ---- Phase F: many-small-solves regime (replaces extension rounds) ----
    if time.process_time() < deadline - 1.0:
        best, bestR = _phaseD(best, bestR, deadline, rng)

    # ---- final polish ----
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        if alt is not None and altR < bestR - 1e-9 and altR > start_bestR:
            return {"best": best, "alternative": alt}
        return best
    out = {"best": start_best}
    if alt is not None and altR > start_bestR - 1e-6 and altR > 0:
        out["alternative"] = alt
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log_active(h0, maxiter, deadline, beta=0.0):
    """Log-space L-BFGS on currently-positive steps."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _smooth_peak(h, deadline, passes=2):
    """Reduce the sharpness of the peak by locally re-fitting with a softmax
    (beta) objective, which lets the optimizer trade a slightly lower peak
    for a wider, more mass-balanced plateau near the maximum."""
    best = h
    bestR = R_of(h)
    for beta in (1e5, 1e6, 1e7):
        if time.process_time() >= deadline - 0.5:
            break
        for _ in range(passes):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _window_polish_peak(best, deadline, 0.5, 256,
                                     maxiter=250, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size
    n_idx = np.arange(N, dtype=float)

    # Phase A: global linear-space polish.
    if time.process_time() < deadline - 6.0:
        h_try = _lbfgs_all_pos(best, 1500, deadline - 5.0)
        r = R_of(h_try)
        if r > bestR:
            best, bestR = h_try.copy(), r
            print("global linear polish: R=%.7f" % bestR)

    # Phase B: smooth-peak rebalancing (new idea). Iteratively soften the
    # max-knot constraint with a softmax to escape the sharp-peak local optimum,
    # then re-tighten with linear polish.
    if time.process_time() < deadline - 4.0:
        h_s, r_s = _smooth_peak(best, deadline - 3.5)
        if r_s > bestR + 1e-14:
            best, bestR = h_s, r_s
            print("smooth peak: R=%.7f" % bestR)
        if time.process_time() < deadline - 3.0:
            h_try = _lbfgs_all_pos(best, 800, deadline - 2.5)
            r = R_of(h_try)
            if r > bestR + 1e-14:
                best, bestR = h_try, r
                print("post-smooth linear: R=%.7f" % bestR)

    # Phase C: window polish at multiple scales.
    if time.process_time() < deadline - 2.0:
        for frac, extra, beta in [(2.0, 512, 0.0), (1.0, 256, 0.0),
                                  (0.5, 128, 1e7), (0.25, 64, 1e8)]:
            if time.process_time() >= deadline - 1.5:
                break
            h_try = _window_polish_peak(best, deadline - 1.0, frac, extra,
                                        maxiter=350, beta=beta)
            r = R_of(h_try)
            if r > bestR + 1e-14:
                best, bestR = h_try.copy(), r
                print("window frac=%.2f beta=%.0e R=%.7f" % (frac, beta, bestR))

    # Phase D: perturbation search with a mix of linear and log-space polish.
    ks = [1, 2, 3, 4, 6, 8]
    phis = [0.0, np.pi / 2, np.pi, 3 * np.pi / 2]
    amps = [1e-3, 3e-3, 1e-2]

    rng = np.random.RandomState(99991)
    sweep = 0
    while time.process_time() < deadline - 2.0:
        sweep += 1
        grid = [(k, phi, a) for k in ks for phi in phis for a in amps]
        rng.shuffle(grid)
        for (k, phi, a) in grid:
            if time.process_time() >= deadline - 2.0:
                break
            mode = np.cos(2.0 * np.pi * k * n_idx / N + phi)
            h2 = np.clip(best * (1.0 + a * mode), 0.0, None)
            if h2.sum() <= 0:
                continue
            h2 = _rescale(h2)
            # Alternate order: sometimes log-space first, sometimes linear.
            if (k + int(phi)) % 2 == 0:
                h2 = _lbfgs_log_active(h2, 150, deadline - 1.0, beta=1e7)
                h2 = _window_polish_peak(h2, deadline - 1.0, 0.25, 128,
                                         maxiter=200, beta=1e8)
            else:
                h2 = _window_polish_peak(h2, deadline - 1.0, 0.10, 64,
                                         maxiter=200, beta=1e7)
                h2 = _lbfgs_log_active(h2, 150, deadline - 1.0, beta=0.0)
            if time.process_time() >= deadline - 1.5:
                break
            r1 = R_of(h2)
            if r1 > bestR + 1e-13:
                best, bestR = h2.copy(), r1
                print("sweep %d k=%d a=%.0e R=%.7f ACCEPT" % (sweep, k, a, bestR))
        print("sweep %d done best=%.7f" % (sweep, bestR))

    # Final polish.
    if time.process_time() < deadline - 0.8:
        hf = _lbfgs_all_pos(best, 2000, deadline - 0.4)
        rf = R_of(hf)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf
        hf = _window_polish_peak(best, deadline - 0.2, 0.5, 128, maxiter=400)
        rf = R_of(hf)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

