    return _rescale(h2)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _perturb(h, rng, sigma):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    return _rescale(h * np.exp(sigma * rng.standard_normal(h.size)))


def _refine_resample(h, factor):
    n = h.size
    n2 = min(int(n * factor), 900000)
    if n2 <= n:
        return h
    xi = np.linspace(0.0, n - 1, n2)
    return _rescale(np.interp(xi, np.arange(n), h))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(1234567)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 16384
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Track the best "genuinely different" construction (resampled resolution)
    alt_best = None
    alt_bestR = 0.0

    cur, curR = best.copy(), bestR

    # First: try resolution refinement of the start, since it often unlocks
    # improvement when the optimum is resolution-limited.
    if best.size < 400000 and time.process_time() < deadline - 15.0:
        for factor in (1.5, 2.0):
            if time.process_time() > deadline - 15.0:
                break
            hr = _refine_resample(best, factor)
            if hr.size == best.size:
                continue
            # warm-up: brief band optimization then sharp
            ht = _lbfgs_all_pos(hr, 80, deadline, beta=0.0)
            rt = R_of(ht)
            if rt > curR + 1e-14:
                cur, curR = ht, rt
                if curR > bestR + 1e-14:
                    best, bestR = cur.copy(), curR
                print("  refine x%.1f N=%d R=%.7f" % (factor, best.size, bestR))
                break

    # Beta-schedule: gradually sharpen toward the exact max surrogate.
    beta_seq = [200.0, 800.0, 3000.0, 0.0]
    pass_no = 0
    while time.process_time() < deadline - 3.0:
        pass_no += 1
        b = beta_seq[pass_no % len(beta_seq)]

        if time.process_time() < deadline - 4.0:
            hb = _lbfgs_all_pos(cur, 250, deadline, beta=b)
            rb = R_of(hb)
            if rb > curR + 1e-14:
                cur, curR = hb, rb
            print("  pass %d beta=%.0f R=%.7f" % (pass_no, b, rb))

        if curR > bestR + 1e-14:
            best, bestR = cur.copy(), curR

        # Perturbation restart with growing sigma
        if pass_no % 4 == 0 and time.process_time() < deadline - 8.0:
            sigma = 0.002 + 0.002 * ((pass_no // 4) % 4)
            cand = _perturb(best, rng, sigma)
            hc = _lbfgs_all_pos(cand, 120, deadline, beta=0.0)
            rc = R_of(hc)
            if rc > bestR + 1e-14:
                best, bestR = hc.copy(), rc
                cur, curR = hc.copy(), rc
                print("  perturb s=%.3f R=%.7f" % (sigma, bestR))

        # Periodically re-refine resolution on best
        if pass_no % 5 == 0 and best.size < 400000 and \
                time.process_time() < deadline - 12.0:
            hr = _refine_resample(best, 1.5)
            if hr.size > best.size:
                ht = _lbfgs_all_pos(hr, 100, deadline, beta=1000.0)
                rt = R_of(ht)
                if rt > bestR + 1e-14:
                    best, bestR = ht.copy(), rt
                    cur, curR = ht.copy(), rt
                    print("  re-refine N=%d R=%.7f" % (best.size, bestR))

    # Final exact sharp polish
    if time.process_time() < deadline - 1.0:
        hf = _lbfgs_all_pos(best, 400, deadline, beta=0.0)
        rf = R_of(hf)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    # If our own construction is different from start and beats it, return it as best.
    if bestR > start_bestR + 1e-12:
        return best
    # Otherwise offer our distinct construction as alternative if meaningfully different.
    if best.size != start_best.size:
        alt_best = best
        alt_bestR = bestR
    if alt_best is not None and alt_bestR > start_bestR - 1e-6:
        return {"best": start_best, "alternative": alt_best}
    return start_best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _refine_knots(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h0
    idx = np.flatnonzero(Lf >= 0.98 * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    win = np.arange(lo, hi + 1)
    zeros = win[h[win] <= 0]
    if zeros.size == 0:
        return h0
    h2 = h.copy()
    h2[zeros] = 1e-3 * h.mean()
    return _lbfgs_block(h2, win, maxiter, deadline, beta=1e8)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _run_cycle(best, bestR, deadline, cycle_limit=1000):
    cycle = 0
    stale = 0
    while time.process_time() < deadline - 1.5 and cycle < cycle_limit:
        cycle += 1
        prev = bestR
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_all_pos(best, 800, deadline - 1.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_all_pos(best, 400, deadline - 1.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        for frac, extra, beta in ((0.05, 64, 1e7), (0.10, 64, 1e8),
                                  (0.25, 128, 1e8), (0.40, 256, 1e8),
                                  (0.60, 512, 1e8)):
            if time.process_time() >= deadline - 1.5:
                break
            win = _peak_window(best, pad_frac=frac, extra=extra)
            ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 1.5,
                              beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 1.5:
            ht = _refine_knots(best, 300, deadline - 1.5)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        print("cycle %d R=%.7f zeros=%.1f%%" % (cycle, bestR,
              100.0 * np.mean(best <= 0)))
        if bestR - prev < 1e-12:
            stale += 1
            if stale >= 2:
                break
        else:
            stale = 0
    return best, bestR


def _nonuniform_resample(h, target):
    """Resample step function onto target steps via cumulative mass."""
    s = h.sum()
    if s <= 0 or target <= 0:
        return h
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    xnew = np.linspace(0.0, total, target + 1)
    xold = c
    vals = np.interp(xnew, xold, np.arange(h.size + 1, dtype=float))
    # integrate piecewise-constant h over each new cell
    dens = np.interp(xnew, xold, np.concatenate(([0.0], np.arange(h.size, dtype=float) + 0.5)))
    # Instead: use cumulative of values at midpoints
    mids = 0.5 * (xnew[:-1] + xnew[1:])
    idx = np.searchsorted(c, mids, side='right') - 1
    idx = np.clip(idx, 0, h.size - 1)
    out = h[idx]
    return out


def _grow_halo(h, grow):
    if grow <= 0:
        return h.copy()
    eps = 1e-4 * h.mean() if h.mean() > 0 else 1e-4
    pad = np.full(grow, eps)
    return np.concatenate([pad, h, pad])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    alt = None
    altR = 0.0
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Phase A: polish start and run full cycle ----
    best, bestR = _run_cycle(best, bestR, deadline - 2.0)

    # ---- Phase B: non-uniform downsample experiment ----
    # Try reducing step count to a coarser grid; the shape's structure
    # often lives at coarser resolution, freeing steps to grow the support.
    if time.process_time() < deadline - 6.0:
        for target in (max(2000, best.size // 4), max(2000, best.size // 2)):
            if time.process_time() >= deadline - 6.0:
                break
            if target >= best.size:
                continue
            hr = _nonuniform_resample(best, target)
            hr = _rescale(hr)
            r = R_of(hr)
            if r > bestR - 0.02:
                hr, hrR = _run_cycle(hr, r, deadline - 4.0)
                if hrR > bestR + 1e-12:
                    best, bestR = hr.copy(), hrR
                    print("resample target=%d -> R=%.7f N=%d" %
                          (target, bestR, best.size))

    # ---- Phase C: halo grow to expand support ----
    if time.process_time() < deadline - 5.0 and best.size < 900000:
        grow = min((900000 - best.size) // 2, max(2000, best.size // 2))
        h2 = _grow_halo(best, grow)
        h2 = _rescale(h2)
        r2 = R_of(h2)
        print("halo grow=%d N=%d R0=%.7f" % (grow, h2.size, r2))
        h2, h2R = _run_cycle(h2, r2, deadline - 3.0)
        if h2R > bestR + 1e-12:
            best, bestR = h2.copy(), h2R
        elif h2R > start_bestR - 1e-9:
            alt, altR = h2.copy(), h2R

    # ---- Phase D: final cycle + polish ----
    best, bestR = _run_cycle(best, bestR, deadline - 0.6)

    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.4)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    out = {}
    if bestR >= start_bestR - 1e-12:
        out["best"] = best
    else:
        out["best"] = start_best
    if alt is not None and altR > start_bestR + 1e-9 and altR < bestR - 1e-9:
        out["alternative"] = alt
    elif bestR < start_bestR - 1e-12 and bestR > start_bestR - 1e-3:
        out["alternative"] = best
    return out

