def _coarsen(h, f):
    n = h.size
    m = n // f
    if m <= 0:
        return None
    hh = h[:m * f].reshape(m, f)
    return hh.mean(axis=1)


def _refine_up(g, n_target):
    m = g.size
    C = np.concatenate(([0.0], np.cumsum(g)))
    u_new = np.linspace(0.0, 1.0, m + 1)
    u_old = np.linspace(0.0, 1.0, n_target + 1)
    h_up = np.diff(np.interp(u_old, u_new, C)) * (n_target / m)
    h_up = _rescale(np.clip(h_up, 0, None))
    tilt = 1.0 + 0.01 * ((-1.0) ** np.arange(n_target))
    h_up = _rescale(np.clip(h_up * tilt, 0, None))
    return h_up


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Experiment: coarse-level ladder with round-trips ----
    N = best.size
    levels = [f for f in (4, 8) if N // f >= 8000]
    for li, f in enumerate(levels):
        now = time.process_time()
        if now >= deadline - 6.0:
            break
        remaining = deadline - 6.0 - now
        n_left = len(levels) - li
        level_deadline = now + remaining / n_left

        g = _coarsen(best, f)
        if g is None or g.sum() <= 0:
            continue
        g = _rescale(g)
        gR = R_of(g)
        print("coarse f=%d M=%d R0=%.7f" % (f, g.size, gR))

        cur, curR = g, gR
        while time.process_time() < level_deadline - 0.5:
            prev = curR
            cur, curR, _ = run_cycle(cur, curR, level_deadline - 0.5)
            if curR - prev < 1e-9:
                break
        print("coarse f=%d M=%d R=%.7f" % (f, cur.size, curR))

        h_up = _refine_up(cur, N)
        r_up = R_of(h_up)
        print("refine f=%d R=%.7f" % (f, r_up))

        # run_cycle on h_up with remaining level time
        now2 = time.process_time()
        if now2 < level_deadline - 0.5:
            h_up, r_up, _ = run_cycle(h_up, r_up, level_deadline - 0.5)
            print("refined cycle f=%d R=%.7f" % (f, r_up))

        if r_up > bestR + 1e-13:
            best, bestR = h_up.copy(), r_up
            print("accepted f=%d R=%.7f zeros=%.1f%% band01=%.2f%%"
                  % (f, bestR, 100.0 * np.mean(best <= 0), 100.0 * _band01(best)))

    # ---- Final: two peak-ladder rungs + one all-pos ----
    for frac, extra, beta in [(0.10, 128, 1e8), (0.25, 256, 1e8)]:
        if time.process_time() >= deadline - 1.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 1.0,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 400, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), 100.0 * _band01(best)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

