    sigmas = [0.1, 0.25, 0.4]
    hop = 0
    accepted = 0
    hop_base = best.copy()
    hop_baseR = bestR
    while time.process_time() < deadline - 1.0:
        hop += 1
        now = time.process_time()
        remaining = deadline - 1.0 - now
        if remaining <= 0.5:
            break
        per_hop = max(2.5, remaining / 4.0)
        hop_deadline = min(deadline - 1.0, now + per_hop)

        w = int(N * rng.uniform(0.03, 0.20))
        w = max(4, min(w, span))
        st = lo_act + int(rng.integers(0, max(1, span - w + 1)))
        en = min(N, st + w)
        cand = hop_base.copy()
        if rng.random() < 0.3:
            cand[st:en] = 0.0
            sigma = 0.0
        else:
            sigma = float(rng.choice(sigmas))
            noise = rng.normal(0.0, sigma, size=en - st)
            cand[st:en] = cand[st:en] * np.exp(noise)
        cand = _rescale(np.clip(cand, 0, None))
        r0 = R_of(cand)
        print("hop k=%d w=%d sigma=%.2f R0=%.7f" % (hop, w, sigma, r0))

        cur, curR = cand, r0
        # Run cycle on the candidate with the per-hop deadline.
        if time.process_time() < hop_deadline - 0.5:
            cur, curR, _ = run_cycle(cur, curR, hop_deadline - 0.5)
        # Leftover -> one all-pos polish.
        if time.process_time() < hop_deadline - 0.3:
            ht = _lbfgs_all_pos(cur, 400, hop_deadline - 0.3, beta=0.0)
            r = R_of(ht)
            if r > curR + 1e-14:
                cur, curR = ht, r

        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR
            hop_base, hop_baseR = cur.copy(), curR
            accepted += 1
            print("hop k=%d R=%.7f dR=%.2e zeros=%.1f%% ACCEPT"
                  % (hop, curR, curR - r0, 100.0 * np.mean(cur <= 0)))
        else:
            hop_base, hop_baseR = best.copy(), bestR
            print("hop k=%d R=%.7f dR=%.2e zeros=%.1f%% revert"
                  % (hop, curR, curR - bestR, 100.0 * np.mean(cur <= 0)))

    # Final polish on best.
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r

    print("final R=%.7f (N=%d, zeros %.1f%%, hops=%d accepted=%d)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), hop, accepted))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- New idea: local knot-shifting / resampling moves on the support ----

def _local_support_refine(h, deadline, rounds=6):
    """Refine by moving mass between adjacent steps guided by the gradient
    of R with respect to step heights, using a small line search. This is a
    cheap coordinate-wise step that can escape L-BFGS plateaus."""
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    best = h.copy()
    bestR = R_of(best)
    n = best.size
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.2:
            break
        num, dq, Lf = _num_and_dq(best)
        s = best.sum()
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, best) + 2.0 / s
        # Normalize gradient direction, try a few step sizes
        gn = np.linalg.norm(grad)
        if gn <= 0:
            break
        d = grad / gn
        improved = False
        for step in (1e-3, 3e-3, 1e-4, 3e-4):
            cand = best + step * d * best.mean()
            cand = np.clip(cand, 0, None)
            if cand.sum() <= 0:
                continue
            cand = _rescale(cand)
            r = R_of(cand)
            if r > bestR + 1e-14:
                best, bestR = cand, r
                improved = True
                break
        if not improved:
            break
    return best


def _insert_peak_step(h, deadline):
    """Try inserting a single new step near the peak of f*f to add a degree
    of freedom. This is a structural change that L-BFGS on fixed N cannot do."""
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h, R_of(h)
    best = h.copy()
    bestR = R_of(best)
    Lf = _knots(best)
    m = int(np.argmax(Lf))
    # peak of f*f is at knot m, i.e. between f indices; try inserting nearby
    n = best.size
    # candidate insertion positions around the peak region
    center = m  # knot index ~ f index
    tries = set()
    for off in (-3, -2, -1, 0, 1, 2, 3):
        p = center + off
        if 1 <= p < n:
            tries.add(p)
    for p in sorted(tries):
        if time.process_time() >= deadline - 0.2:
            break
        val = 0.5 * (best[p - 1] + best[p]) if p < n else best[p - 1]
        cand = np.concatenate([best[:p], [val], best[p:]])
        # small local L-BFGS around insertion
        win = np.arange(max(0, p - 8), min(cand.size, p + 9))
        cand2 = _lbfgs_block(cand, win, maxiter=80, deadline=deadline, beta=0.0)
        r = R_of(cand2)
        if r > bestR + 1e-14:
            best, bestR = cand2, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: full L-BFGS polish of the start (cheap, small gain expected).
    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 2 (NEW): structural exploration -- insert steps near the peak
    # and then re-run the local cycle. This is what distinguishes this run
    # from the start, which only does coordinate polishing.
    n_insert_rounds = 0
    while time.process_time() < deadline - 2.0 and n_insert_rounds < 6:
        before = bestR
        ht, rt = _insert_peak_step(best, deadline - 1.5)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        n_insert_rounds += 1
        print("insert round %d: R=%.7f (dR=%.2e, N=%d)"
              % (n_insert_rounds, bestR, bestR - before, best.size))
        if bestR - before < 1e-10:
            break

    # Phase 3 (NEW): local coordinate-wise gradient refinement.
    if time.process_time() < deadline - 1.0:
        ht = _local_support_refine(best, deadline - 0.8, rounds=8)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
            print("local refine R=%.7f" % bestR)

    # Phase 4: final full L-BFGS polish.
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 600, deadline - 0.6, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

