    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


# ---- Key change: Richardson-style subsample + re-expand (grid coarsening) ----
# Instead of only refining upward (which the old program did and stalled on),
# we periodically *coarsen* the grid (averaging pairs of cells), re-optimise
# at the coarser level, then upsample back. This acts as a smoothing /
# regularisation step that lets the optimizer escape the fine-grid local
# minimum and find a genuinely better shape.

def _downsample(h, factor=2):
    n = h.size
    m = n // factor
    if m < 1:
        return h
    hh = h[:m * factor].reshape(m, factor)
    return hh.mean(axis=1)


def _upsample(h, new_n):
    n = h.size
    if new_n <= n:
        return h.copy()
    xc = np.arange(n) + 0.5
    xs = (np.arange(new_n) + 0.5) * (n / new_n)
    return np.interp(xs, xc, h, left=h[0], right=h[-1])


def _peak_window(h, frac=0.15):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, budget_slice):
    best = h.copy()
    bestR = R_of(best)
    end = min(deadline - 0.3, time.process_time() + budget_slice)
    if time.process_time() < end:
        hs = _lbfgs_log(best, 400, end, beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 0.5:
            break
        end = min(deadline - 0.3, time.process_time() + budget_slice * 0.5)
        hs = _lbfgs_log(best, 200, end, beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(99999)

    bestH = best.copy()
    bestRH = bestR
    alt = best.copy()
    altR = bestR

    # ---- Phase A: coarse/up cycle with downsampling ----
    # The new lever: downsample to escape local minima, re-optimise, upsample.
    cycle = 0
    while time.process_time() < deadline - 6.0 and cycle < 6:
        cycle += 1
        # downsample to a coarser grid (factor 2 or 3)
        factor = 2 if cycle % 2 == 1 else 3
        hc = _downsample(bestH, factor)
        hc = _rescale(hc)
        r_coarse_pre = R_of(hc)
        # polish at coarse level
        slice_t = min(deadline - 5.0, time.process_time() + 3.0) - time.process_time()
        hc, r_coarse = _polish(hc, deadline - 4.0, max(1.0, slice_t))
        # upsample back to original (or larger) grid and re-polish
        new_n = bestH.size
        hu = _upsample(hc, new_n)
        hu = _rescale(hu)
        slice_t = min(deadline - 3.0, time.process_time() + 4.0) - time.process_time()
        hu, r_up = _polish(hu, deadline - 2.0, max(1.0, slice_t))
        print("  cycle %d down x%d: pre=%.9f coarse=%.9f up=%.9f" %
              (cycle, factor, r_coarse_pre, r_coarse, r_up))
        if r_up > bestRH + 1e-13:
            bestH, bestRH = hu.copy(), r_up
            print("    NEW BEST (down/up) R=%.9f" % bestRH)
        elif r_coarse > altR + 1e-13 and hc.size != bestH.size:
            alt, altR = hc.copy(), r_coarse

    # ---- Phase B: progressive upsampling ----
    factor_up = 1.4
    N_MAX = 400000
    while bestH.size * factor_up <= N_MAX and time.process_time() < deadline - 6.0:
        new_n = int(bestH.size * factor_up)
        cand = _upsample(bestH, new_n)
        cand = _rescale(cand)
        r_pre = R_of(cand)
        slice_t = min(deadline - 4.0, time.process_time() + 5.0) - time.process_time()
        cand, r_post = _polish(cand, deadline - 3.0, max(1.0, slice_t))
        print("  upsample x%.2f (N=%d): pre=%.9f post=%.9f" %
              (factor_up, cand.size, r_pre, r_post))
        if r_post > bestRH + 1e-13:
            bestH, bestRH = cand.copy(), r_post
            print("    NEW BEST (up) R=%.9f" % bestRH)
        else:
            if r_post > altR + 1e-13:
                alt, altR = cand.copy(), r_post
            factor_up = min(1.8, factor_up * 1.15)
            if bestH.size * factor_up > N_MAX:
                break

    # ---- Phase C: random perturbations + peak polish ----
    n = bestH.size
    sigma = 0.02
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        M = int(rng.integers(2, 7))
        x = (np.arange(n, dtype=float) + 0.5) / n
        field = np.zeros(n)
        for m in range(1, M + 1):
            field += rng.normal(0.0, sigma) * np.sin(2.0 * np.pi * m * x + rng.uniform(0, 2 * np.pi))
        cand = _rescale(bestH * np.exp(field))
        if time.process_time() < deadline - 2.5:
            free = _peak_window(cand, frac=0.08)
            end = min(deadline - 1.5, time.process_time() + 1.5)
            # block polish via masked log
            hh = cand.copy()
            mask = np.zeros(n, dtype=bool)
            mask[free] = True
            # apply log-lbfgs on full but with tmp; simpler: full log quickly
            cand = _lbfgs_log(cand, 60, end, beta=0.0)
            if R_of(cand) > altR + 1e-13:
                alt, altR = cand.copy(), R_of(cand)
        if R_of(cand) > bestRH + 1e-13:
            slice_t = min(deadline - 0.8, time.process_time() + 2.5) - time.process_time()
            cand, r_new = _polish(cand, deadline - 0.5, max(1.0, slice_t))
            if r_new > bestRH + 1e-13:
                bestH, bestRH = cand.copy(), r_new
                sigma = max(0.005, sigma * 0.75)
                print("  pert it=%d NEW BEST R=%.9f" % (it, bestRH))
                continue
        if it % 7 == 0:
            sigma = min(0.10, sigma * 1.4)

    # ---- Phase D: final polish loop ----
    loop_end = deadline - 0.3
    it2 = 0
    while time.process_time() < loop_end:
        it2 += 1
        end = min(loop_end, time.process_time() + 2.5)
        hs = _lbfgs_log(bestH, 200, end, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            print("  final it=%d R=%.9f" % (it2, bestRH))
            continue
        if time.process_time() < loop_end - 1.0:
            # try a short downsample-and-up
            hc = _rescale(_downsample(bestH, 2))
            end = min(loop_end, time.process_time() + 1.5)
            hc = _lbfgs_log(hc, 100, end, beta=0.0)
            hu = _rescale(_upsample(hc, bestH.size))
            ru = R_of(hu)
            if ru > bestRH + 1e-13:
                bestH, bestRH = hu, ru
                print("  final down/up it=%d R=%.9f" % (it2, bestRH))

    print("final R=%.9f (N=%d)" % (bestRH, bestH.size))

    if bestRH > start_bestR + 1e-12:
        if altR > start_bestR + 1e-12 and altR < bestRH and alt.size != bestH.size:
            return {"best": bestH, "alternative": alt}
        return bestH
    else:
        if altR > start_bestR + 1e-12:
            return {"best": alt, "alternative": start_best}
        return start_best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band01(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= 0.999 * mx))


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _coarsen(h, f):
    N = h.size
    m = N // f
    if m <= 0:
        return None, 0
    hh = h[:m * f].reshape(m, f)
    g = hh.mean(axis=1)
    return g, m


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Coarse round-trip ladder, iterated with accept-if-better.
    N = best.size
    for rnd in (1, 2):
        for f in (4, 8, 16):
            if N // f < 6000:
                continue
            now = time.process_time()
            if now >= deadline - 1.5:
                break
            remaining = deadline - 1.5 - now
            share = remaining / 3.0
            share = max(1.0, min(share, 6.0))
            g, m = _coarsen(best, f)
            if g is None or g.sum() <= 0:
                continue
            g = _rescale(g)
            gR = R_of(g)
            g, gR, _ = run_cycle(g, gR, now + share)
            # prolongate back with alternating per-cell tilt
            hp = np.repeat(g, f)
            if hp.size < N:
                hp = np.concatenate([hp, np.full(N - hp.size, hp[-1] if hp.size else 0.0)])
            elif hp.size > N:
                hp = hp[:N]
            idx = np.arange(N)
            sgn = 1.0 if (rnd + f) % 2 == 0 else -1.0
            tilt = 1.0 + 0.02 * sgn * ((-1.0) ** idx)
            hp = np.clip(hp * tilt, 0.0, None)
            hp = _rescale(hp)
            hpR = R_of(hp)
            now2 = time.process_time()
            share2 = max(1.0, min(share, 6.0))
            hp, hpR, _ = run_cycle(hp, hpR, now2 + share2)
            dR = hpR - bestR
            print("round %d f=%d R=%.7f dR=%.2e zeros=%.1f%% band01=%.2f%% band1=%.2f%%"
                  % (rnd, f, hpR, dR, 100.0 * np.mean(hp <= 0),
                     100.0 * _band_frac(hp, 0.001), 100.0 * _band_frac(hp, 0.01)))
            if hpR > bestR + 1e-9:
                best, bestR = hp.copy(), hpR

    while time.process_time() < deadline - 1.0:
        prev = bestR
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        if bestR - prev < 1e-9:
            break

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.6, beta=0.0)
        r = R_of(ht)
