        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Phase C: one base cycle ----
    if time.process_time() < deadline - 12.0:
        prevR = bestR
        best, bestR, drefine = run_cycle(best, bestR, deadline - 11.0)
        print("cycle 1 R=%.7f dR=%.2e drefine=%.2e zeros=%.1f%%"
              % (bestR, bestR - prevR, drefine, 100.0 * np.mean(best <= 0)))

    # ---- Phase E: coarse basin hopping ----
    hc = _coarsen4(best)
    hcR = R_of(hc)
    print("coarse baseline R=%.7f (N=%d)" % (hcR, hc.size))

    rng = np.random.default_rng(12345)
    candidates = []
    ncoarse = hc.size
    mean_hc = hc.mean() if hc.size > 0 else 1.0
    eps_seed = 1e-3 * mean_hc if mean_hc > 0 else 1e-6

    restart = 0
    while time.process_time() < deadline - 12.0:
        restart += 1
        hc_r = hc.copy()
        pos = hc_r > 0
        noise = rng.normal(0.0, 0.05, size=hc_r.size)
        hc_r[pos] = hc_r[pos] * np.exp(noise[pos])
        zeros = np.flatnonzero(hc_r <= 0)
        if zeros.size > 0:
            k = max(1, int(0.10 * zeros.size))
            pick = rng.choice(zeros, size=min(k, zeros.size), replace=False)
            hc_r[pick] = eps_seed
        hc_r = _rescale(hc_r)
        try:
            ht = _lbfgs_all_pos(hc_r, 300, deadline - 12.0, beta=1e7)
            ht = _lbfgs_all_pos(ht, 300, deadline - 12.0, beta=0.0)
        except Exception:
            continue
        r = R_of(ht)
        print("restart %d coarse R=%.7f (d=%.2e)"
              % (restart, r, r - hcR))
        duplicate = False
        for (rr, hh) in candidates:
            if hh.size == ht.size and np.allclose(hh, ht, rtol=1e-6, atol=1e-12):
                duplicate = True
                break
        if duplicate:
            continue
        candidates.append((r, ht.copy()))
        candidates.sort(key=lambda x: -x[0])
        if len(candidates) > 3:
            candidates = candidates[:3]

    # ---- Phase F: prolongate best coarse candidates and refine ----
    best_fine = best.copy()
    best_fineR = bestR
    for (rr, hh) in candidates:
        if time.process_time() >= deadline - 2.0:
            break
        hf = np.repeat(hh, 4)
        hf = _rescale(hf)
        cur, curR = hf, R_of(hf)
        for _ in range(2):
            if time.process_time() >= deadline - 2.0:
                break
            cur, curR, _ = run_cycle(cur, curR, deadline - 1.5)
        print("prolongated R=%.7f (coarse %.7f)" % (curR, rr))
        if curR > best_fineR + 1e-13:
            best_fine, best_fineR = cur.copy(), curR

    # ---- NEW Phase H: aggressive narrow polish on the local support ----
    # The support window is where h>0; polish within a tight band around it,
    # with beta continuation, to squeeze out the last digits of R.
    if time.process_time() < deadline - 0.5:
        win = _support_window(best_fine, frac=0.10)
        for beta in (1e8, 1e9, 1e10):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_block(best_fine, win, maxiter=400,
                              deadline=deadline - 0.4, beta=beta)
            r = R_of(ht)
            if r > best_fineR + 1e-14:
                best_fine, best_fineR = ht.copy(), r
        # widen and polish all-positive
        if time.process_time() < deadline - 0.5:
            ht = _polish(best_fine, deadline - 0.3)
            r = R_of(ht)
            if r > best_fineR + 1e-14:
                best_fine, best_fineR = ht.copy(), r

    # ---- Phase G: final polish (existing) ----
    if time.process_time() < deadline - 1.0:
        ht = _refine_knots(best_fine, 400, deadline - 0.6)
        r = R_of(ht)
        if r > best_fineR + 1e-14:
            best_fine, best_fineR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best_fine, 600, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > best_fineR + 1e-14:
            best_fine, best_fineR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (best_fineR, best_fine.size, 100.0 * np.mean(best_fine <= 0)))

    if best_fineR > start_bestR + 1e-12:
        return best_fine
    out = {"best": start_best}
    if best_fineR > start_bestR - 1e-6:
        out["alternative"] = best_fine
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _active_range(h):
    thr = 1e-9 * h.max()
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return 0, h.size - 1
    return int(idx[0]), int(idx[-1])


def _smooth_perturb(h, rng, scale):
    # smooth multiplicative perturbation: low-frequency random field
    n = h.size
    k = max(4, n // 400)
    knots = rng.normal(0.0, scale, size=k + 1)
    x = np.linspace(0, k, n)
    xi = np.clip(x.astype(int), 0, k - 1)
    t = x - xi
    field = knots[xi] * (1 - t) + knots[xi + 1] * t
    return h * np.exp(field)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(20240607)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Global cycle on start.
    if time.process_time() < deadline - 1.5:
        best, bestR = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Smooth-perturbation hopping with multi-scale windows.
    hop = 0
    accepted = 0
    while time.process_time() < deadline - 1.0:
        hop += 1
        now = time.process_time()
        remaining = deadline - 1.0 - now
        if remaining <= 0.5:
            break
        per_hop = max(2.0, remaining / 3.0)
        hop_deadline = min(deadline - 1.0, now + per_hop)

        cand = best.copy()
        mode = rng.random()
        if mode < 0.5:
            cand = _smooth_perturb(cand, rng, 0.15)
        else:
            lo_act, hi_act = _active_range(cand)
            span = max(1, hi_act - lo_act + 1)
            w = int(span * rng.uniform(0.02, 0.15))
            w = max(4, min(w, span))
            st = lo_act + int(rng.integers(0, max(1, span - w + 1)))
            en = min(cand.size, st + w)
            sigma = float(rng.choice([0.05, 0.12, 0.25]))
            cand[st:en] *= np.exp(rng.normal(0.0, sigma, size=en - st))
        cand = _rescale(np.clip(cand, 0, None))
        r0 = R_of(cand)

        cur, curR = cand, r0
        if time.process_time() < hop_deadline - 0.4:
            cur, curR = run_cycle(cur, curR, hop_deadline - 0.4)
        if time.process_time() < hop_deadline - 0.2:
            ht = _lbfgs_all_pos(cur, 400, hop_deadline - 0.2, beta=0.0)
            r = R_of(ht)
            if r > curR + 1e-14:
                cur, curR = ht, r

        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR
            accepted += 1
            print("hop %d R=%.7f dR=%.2e ACCEPT" % (hop, curR, curR - r0))
        else:
            print("hop %d R=%.7f dR=%.2e revert" % (hop, curR, curR - bestR))

    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r

    print("final R=%.7f (N=%d, hops=%d accepted=%d)" %
          (bestR, best.size, hop, accepted))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6 and bestR > 0:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_clip(h, c, beta):
    """Objective: L2 energy of the profile clipped at c*softmax, plus log of
    the soft max. Gradient pressure goes to knots below the threshold."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num_full, dq_full, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    Mb = mx + np.log(Z) / beta
    t = c * Mb
    mask = Lf < t
    u = np.minimum(Lf, t)
    a = u[:-1]; b = u[1:]
    num_c = np.sum(a * a + a * b + b * b) / 3.0
    if num_c <= 0:
        return _fun_grad(h)
    dqc = np.zeros_like(u)
    dqc[:-1] += (2 * a + b)
    dqc[1:] += (a + 2 * b)
    dqc /= 3.0
    # dLf: where below threshold, dqc; where at/above, c * sum(dqc above) * w
    above = ~mask
    sum_above = dqc[above].sum()
    dLf = np.where(mask, dqc, c * sum_above * w)
    grad = _backprop(dLf, h) + 2.0 / s
    val = -np.log(num_c) + 2.0 * np.log(s) + np.log(Mb)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_block_clip(h0, free, maxiter, deadline, c, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_clip(hh, c, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _local_support_refine(h, deadline, rounds=6):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    best = h.copy()
    bestR = R_of(best)
    n = best.size
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.2:
            break
        num, dq, Lf = _num_and_dq(best)
        s = best.sum()
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, best) + 2.0 / s
        gn = np.linalg.norm(grad)
        if gn <= 0:
            break
        d = grad / gn
        improved = False
        for step in (1e-3, 3e-3, 1e-4, 3e-4):
            cand = best + step * d * best.mean()
            cand = np.clip(cand, 0, None)
            if cand.sum() <= 0:
                continue
            cand = _rescale(cand)
            r = R_of(cand)
            if r > bestR + 1e-14:
                best, bestR = cand, r
                improved = True
                break
        if not improved:
            break
    return best


def _insert_peak_step(h, deadline):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h, R_of(h)
    best = h.copy()
    bestR = R_of(best)
    Lf = _knots(best)
    m = int(np.argmax(Lf))
    n = best.size
    center = m
    tries = set()
    for off in (-3, -2, -1, 0, 1, 2, 3):
        p = center + off
        if 1 <= p < n:
            tries.add(p)
    for p in sorted(tries):
        if time.process_time() >= deadline - 0.2:
            break
        val = 0.5 * (best[p - 1] + best[p]) if p < n else best[p - 1]
        cand = np.concatenate([best[:p], [val], best[p:]])
        win = np.arange(max(0, p - 8), min(cand.size, p + 9))
        cand2 = _lbfgs_block(cand, win, maxiter=80, deadline=deadline, beta=0.0)
        r = R_of(cand2)
        if r > bestR + 1e-14:
            best, bestR = cand2, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: base polish cycle.
    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 2 (NEW): clipped-L2 ladder to push valley knots up.
    clip_ladder = [(0.95, 1e4), (0.97, 1e4), (0.985, 1e4),
                   (0.995, 1e5), (0.999, 1e5)]
    for c, beta in clip_ladder:
        if time.process_time() >= deadline - 2.0:
            break
        free = _peak_window(best, tol=0.999, pad_frac=0.25, extra=256)
        ht = _lbfgs_block_clip(best, free, 300, deadline - 2.0, c, beta)
        ht = _rescale(ht)
        r = R_of(ht)
        b01 = _band_frac(ht, 0.001)
        b1 = _band_frac(ht, 0.01)
        print("clip c=%.3f beta=%.0e R=%.7f band1=%.4f band01=%.4f"
              % (c, beta, r, b1, b01))
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    # Phase 3: run_cycle after the clip ladder.
    if time.process_time() < deadline - 1.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        print("post-clip cycle R=%.7f" % bestR)

    # Phase 4: final full L-BFGS polish.
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.6, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
