    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- NEW: Newton-CG (trust-ncg) on a log-parametrised free block ----

def _newton_window(h0, free, deadline, beta, maxiter):
    """Second-order step on a free block, parametrised as h[free]=exp(x).
    Uses trust-ncg with exact Hessian-vector products via finite differences
    of the analytic gradient. Returns (rescaled h, final free-block grad norm)."""
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0, np.inf
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0, np.inf
    if time.process_time() >= deadline - 0.3:
        return h0, np.inf
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    base = h.copy()
    scale = max(1e-12, 1e-12 * float(base.max()))
    x0 = np.log(np.clip(base[active], 0.0, None) + scale)

    def _unpack(x):
        hh = base.copy()
        hh[active] = np.exp(x)
        return hh

    def f(x):
        hh = _unpack(x)
        val, g = fg(hh)
        return val, g[active]

    def hessp(x, p):
        # central finite difference of analytic gradient in x-space
        pn = np.max(np.abs(p)) if p.size else 0.0
        if pn <= 0:
            return np.zeros_like(x)
        eps = 1e-6 / pn
        _, gp = f(x + eps * p)
        _, gm = f(x - eps * p)
        return (gp - gm) / (2.0 * eps)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, hessp=hessp, method='trust-ncg',
                       callback=cb,
                       options={'maxiter': maxiter, 'gtol': 1e-14})
    except (TimeoutError, Exception):
        return h0, np.inf
    if res is None:
        return h0, np.inf
    hh = _unpack(res.x)
    hh = _rescale(np.clip(hh, 0.0, None))
    _, gfin = fg(hh)
    gnorm = float(np.max(np.abs(gfin[active]))) if active.size else np.inf
    return hh, gnorm


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: full L-BFGS polish of the start.
    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 2 (NEW): trust-ncg Newton-CG on a log-parametrised peak window.
    for beta in (1e6, 1e8):
        if time.process_time() >= deadline - 2.5:
            break
        free = _peak_window(best, tol=0.9995, pad_frac=0.10, extra=128)
        if free.size > 6000:
            order = np.argsort(best[free])[::-1][:6000]
            free = np.sort(free[order])
        ht, gn = _newton_window(best, free, deadline - 2.5, beta, 40)
        r = R_of(ht)
        print("newton beta=%.0e nfree=%d R=%.7f gnorm=%.2e"
              % (beta, free.size, r, gn))
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    # Phase 3: run_cycle polish.
    if time.process_time() < deadline - 1.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        print("post-newton cycle R=%.7f" % bestR)

    # Phase 4: final full L-BFGS polish.
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.6, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

