def _shape_weight(h, alpha, kind):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    if h.sum() <= 0:
        return h
    act = np.flatnonzero(h > 1e-9 * h.max())
    if act.size < 2:
        return h
    lo = int(act.min())
    hi = int(act.max())
    span = hi - lo
    if span <= 0:
        return h
    idx = np.arange(n, dtype=float)
    t = (idx - lo) / span
    phi = np.sin(np.pi * t) ** 2
    outside = (idx < lo) | (idx > hi)
    phi = np.clip(phi, 0.0, 1.0)
    phi[outside] = 0.0
    if kind == 'edge':
        phi = 1.0 - phi
        phi[outside] = 0.0
    w = 1.0 + alpha * phi
    w = np.clip(w, 0.0, None)
    return _rescale(h * w)


def _upsample(h, factor):
    """Smoothly resample h to factor*h.size steps via linear interpolation."""
    n = h.size
    m = factor * n
    xi = np.linspace(0, n - 1, m)
    lo = np.floor(xi).astype(int)
    hi = np.minimum(lo + 1, n - 1)
    t = xi - lo
    return (1.0 - t) * h[lo] + t * h[hi]


def _downsample(h, n_new):
    """Resample h to n_new steps by averaging over bins."""
    n = h.size
    if n_new == n:
        return h
    xi = np.linspace(0, n - 1, n_new + 1)
    lo = np.floor(xi).astype(int)
    hi = np.minimum(np.ceil(xi).astype(int), n - 1)
    out = np.zeros(n_new)
    for k in range(n_new):
        a = lo[k]; b = max(a + 1, hi[k + 1] if k + 1 < n_new + 1 else hi[k])
        a = min(a, n - 1); b = min(b, n)
        if b <= a:
            out[k] = h[min(a, n - 1)]
        else:
            out[k] = h[a:b].mean()
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # New idea: upsampling / resampling exploration.  The optimum is a limit
    # shape; a finer grid can resolve sharper structure.  Try both upsample
    # (finer) and downsample (coarser) restarts, refine, and keep improvements.
    now = time.process_time()
    if now < deadline - 3.0:
        # First do a quick base cycle at current resolution
        best, bestR, _ = run_cycle(best, bestR, min(deadline - 2.0, now + (deadline - now) * 0.25))
        print("base cycle R=%.7f" % bestR)

    # Resampling explorations
    resamples = []
    n0 = best.size
    for f in (2, 3):
        if n0 * f <= 900000:
            resamples.append(('up%d' % f, _upsample(best, f)))
    for f in (2, 3):
        if n0 // f >= 512:
            resamples.append(('dn%d' % f, _downsample(best, n0 // f)))

    n_left = len(resamples)
    for name, hr in resamples:
        now = time.process_time()
        if now >= deadline - 2.0:
            break
        remaining = deadline - 2.0 - now
        cand_deadline = now + remaining / max(1, n_left)
        n_left -= 1
        cur = _rescale(hr)
        curR = R_of(cur)
        print("resample %s R0=%.7f N=%d" % (name, curR, cur.size))
        while time.process_time() < cand_deadline - 0.5:
            prev = curR
            cur, curR, _ = run_cycle(cur, curR, cand_deadline - 0.5)
            if curR - prev < 1e-9:
                break
        dR = curR - bestR
        print("resample %s R=%.7f dR=%.2e" % (name, curR, dR))
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR

    # Shape-perturbation candidates from the improved best
    candidates = [(0.5, 'int'), (2.0, 'int'), (8.0, 'int'),
                  (-0.5, 'int'), (-0.5, 'edge'), (4.0, 'int')]
    n_left = len(candidates)
    for (alpha, kind) in candidates:
        now = time.process_time()
        if now >= deadline - 1.5:
            break
        remaining = deadline - 1.5 - now
        cand_deadline = now + remaining / n_left
        n_left -= 1
        hw = _shape_weight(best, alpha, kind)
        R0 = R_of(hw)
        cur, curR = hw, R0
        while time.process_time() < cand_deadline - 0.5:
            prev = curR
            cur, curR, _ = run_cycle(cur, curR, cand_deadline - 0.5)
            if curR - prev < 1e-9:
                break
        dR = curR - bestR
        print("shape alpha=%.1f kind=%s R=%.7f dR=%.2e" % (alpha, kind, curR, dR))
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR

    while time.process_time() < deadline - 1.0:
        prev = bestR
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        if bestR - prev < 1e-9:
            break

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.6, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- NEW: Newton-CG (trust-ncg) on a log-parametrised free block ----

def _newton_window(h0, free, deadline, beta, maxiter):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0, np.inf
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0, np.inf
    if time.process_time() >= deadline - 0.3:
        return h0, np.inf
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    base = h.copy()
    scale = max(1e-12, 1e-12 * float(base.max()))
    x0 = np.log(np.clip(base[active], 0.0, None) + scale)

    def _unpack(x):
        hh = base.copy()
        hh[active] = np.exp(x)
        return hh

    def f(x):
        hh = _unpack(x)
        val, g = fg(hh)
        return val, g[active]

    def hessp(x, p):
        pn = np.max(np.abs(p)) if p.size else 0.0
        if pn <= 0:
            return np.zeros_like(x)
        eps = 1e-6 / pn
        _, gp = f(x + eps * p)
        _, gm = f(x - eps * p)
        return (gp - gm) / (2.0 * eps)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, hessp=hessp, method='trust-ncg',
                       callback=cb,
                       options={'maxiter': maxiter, 'gtol': 1e-14})
    except (TimeoutError, Exception):
        return h0, np.inf
    if res is None:
        return h0, np.inf
    hh = _unpack(res.x)
    hh = _rescale(np.clip(hh, 0.0, None))
    _, gfin = fg(hh)
    gnorm = float(np.max(np.abs(gfin[active]))) if active.size else np.inf
    return hh, gnorm


# ---- NEW: multi-resolution resampling lift ----

def _resample_up(h, factor):
    """Upsample h by linear interpolation to (len-1)*factor+1 samples, scaled
    so the discrete mass (sum * step) is preserved when step shrinks by factor."""
    n = h.size
    if factor <= 1:
        return h.copy()
    xi = np.arange(n, dtype=float)
    xo = np.arange((n - 1) * factor + 1, dtype=float) / factor
    out = np.interp(xo, xi, h)
    return out / factor


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: full L-BFGS polish of the start.
    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 2 (NEW): multi-resolution lift — upsample the current best to a
    # finer grid, then re-optimise. This lets structure at sub-step scale
    # develop, which the fixed-grid L-BFGS cannot access.
    if best.size < 500000 and time.process_time() < deadline - 5.0:
        factor = 2
        while best.size * factor < 500000 and best.size * factor <= 400000:
            factor += 1
        factor = max(2, min(factor, 4))
        hl = _resample_up(best, factor)
        hl = _seed_zeros(hl)
        ht = _lbfgs_all_pos(hl, 600, deadline - 4.0, beta=0.0)
        r = R_of(ht)
        print("lift x%d R=%.7f N=%d" % (factor, r, ht.size))
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            # shrink again by merging adjacent steps (mass-preserving)
            if best.size > 400000:
                m = best.size // 2 * 2
                best = 0.5 * (best[:m:2] + best[1:m:2])
                best = _rescale(best)
                bestR = R_of(best)

    # Phase 3: trust-ncg Newton-CG on a log-parametrised peak window.
    for beta in (1e6, 1e8):
        if time.process_time() >= deadline - 2.5:
            break
        free = _peak_window(best, tol=0.9995, pad_frac=0.10, extra=128)
        if free.size > 6000:
            order = np.argsort(best[free])[::-1][:6000]
            free = np.sort(free[order])
        ht, gn = _newton_window(best, free, deadline - 2.5, beta, 40)
        r = R_of(ht)
        print("newton beta=%.0e nfree=%d R=%.7f gnorm=%.2e"
              % (beta, free.size, r, gn))
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    # Phase 4: run_cycle polish.
    if time.process_time() < deadline - 1.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        print("post-newton cycle R=%.7f" % bestR)

    # Phase 5: final full L-BFGS polish.
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.6, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def _band01(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= 0.999 * mx))


def _coarsen(h, f):
    n = h.size
    m = n // f
    if m <= 0:
        return None
    hh = h[:m * f].reshape(m, f)
    return hh.mean(axis=1)


def _refine_up(g, n_target):
    m = g.size
    C = np.concatenate(([0.0], np.cumsum(g)))
    u_new = np.linspace(0.0, 1.0, m + 1)
    u_old = np.linspace(0.0, 1.0, n_target + 1)
    h_up = np.diff(np.interp(u_old, u_new, C)) * (n_target / m)
    h_up = _rescale(np.clip(h_up, 0, None))
    tilt = 1.0 + 0.01 * ((-1.0) ** np.arange(n_target))
    h_up = _rescale(np.clip(h_up * tilt, 0, None))
    return h_up


def _jitter(h, rng, amp):
    """Multiply heights by random lognormal perturbation."""
    n = h.size
    noise = np.exp(amp * rng.standard_normal(n))
    return _rescale(np.clip(h * noise, 0, None))


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: base cycle
    if time.process_time() < deadline - 1.5:
        best, bestR = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 2: multi-scale coarsening experiments
    N = best.size
    levels = [f for f in (2, 4, 8) if N // f >= 6000]
    total_level_time = (deadline - 4.0) - time.process_time()
    if total_level_time > 0 and levels:
        per_level = total_level_time / len(levels)
        for f in levels:
            now = time.process_time()
            if now >= deadline - 4.0:
                break
            level_deadline = min(deadline - 4.0, now + per_level)
            g = _coarsen(best, f)
            if g is None or g.sum() <= 0:
                continue
            g = _rescale(g)
            cur, curR = g, R_of(g)
            while time.process_time() < level_deadline - 0.5:
                prev = curR
                cur, curR = run_cycle(cur, curR, level_deadline - 0.5)
                if curR - prev < 1e-9:
                    break
            h_up = _refine_up(cur, N)
            r_up = R_of(h_up)
            if time.process_time() < level_deadline - 0.5:
                h_up, r_up = run_cycle(h_up, r_up, level_deadline - 0.5)
            if r_up > bestR + 1e-13:
                best, bestR = h_up.copy(), r_up
            print("coarse f=%d R=%.7f -> up R=%.7f (best %.7f)"
                  % (f, curR, r_up, bestR))

    # Phase 3: perturb-and-reoptimize loop until deadline
    print("perturb phase start R=%.7f t=%.1f" %
          (bestR, time.process_time() - t0))
    amps = [0.02, 0.005, 0.001, 0.0002, 0.05]
    ai = 0
    n_tries = 0
    while time.process_time() < deadline - 1.5:
        amp = amps[ai % len(amps)]
        ai += 1
        n_tries += 1
        cand = _jitter(best, rng, amp)
        r0 = R_of(cand)
        # short local reconverge
        sub_deadline = min(deadline - 1.0, time.process_time() + 4.0)
        ht = _lbfgs_all_pos(cand, 200, sub_deadline, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("perturb amp=%.4f R=%.7f" % (amp, bestR))
        if time.process_time() >= deadline - 1.5:
            break
        # occasional targeted peak window
        if n_tries % 3 == 0:
            win = _peak_window(best, pad_frac=0.2, extra=128)
            sub_deadline = min(deadline - 1.0, time.process_time() + 3.0)
            ht = _lbfgs_block(best, win, maxiter=200, deadline=sub_deadline,
                              beta=1e8)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
                print("perturb peak R=%.7f" % bestR)

    # Final polish
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), 100.0 * _band01(best)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_clip(h, c, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num_full, dq_full, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    Mb = mx + np.log(Z) / beta
    t = c * Mb
    mask = Lf < t
    u = np.minimum(Lf, t)
    a = u[:-1]; b = u[1:]
    num_c = np.sum(a * a + a * b + b * b) / 3.0
    if num_c <= 0:
        return _fun_grad(h)
    dqc = np.zeros_like(u)
    dqc[:-1] += (2 * a + b)
    dqc[1:] += (a + 2 * b)
    dqc /= 3.0
    above = ~mask
    sum_above = dqc[above].sum()
    dLf = np.where(mask, dqc, c * sum_above * w)
    grad = _backprop(dLf, h) + 2.0 / s
    val = -np.log(num_c) + 2.0 * np.log(s) + np.log(Mb)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_block_clip(h0, free, maxiter, deadline, c, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_clip(hh, c, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _upsample2(h):
    h = np.clip(h, 0, None)
    out = np.empty(2 * h.size, dtype=float)
    out[0::2] = h
    out[1::2] = h
    return out


def _grow_halo(h, P=4096, decay_frac=0.05):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    left = h[0] if h[0] > 0 else h.mean() * 1e-3
    right = h[-1] if h[-1] > 0 else h.mean() * 1e-3
    scale = decay_frac * P
    d = np.arange(1, P + 1, dtype=float)
    hl = left * np.exp(-d / scale)
    hr = right * np.exp(-d / scale)
    out = np.concatenate([hl[::-1], h, hr])
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94 - 1.0

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("base R=%.7f (N=%d)" % (start_bestR, start_best.size))

    # (a) upsample 2x, (b) grow halo, rescale
    h2 = _upsample2(start_best)
    h2 = _grow_halo(h2, P=4096, decay_frac=0.05)
    h2 = _rescale(h2)
    best = h2
    bestR = R_of(best)
    print("upsample+halo R=%.7f (N=%d, band01=%.4f, band1=%.4f)"
          % (bestR, best.size, _band_frac(best, 0.001), _band_frac(best, 0.01)))

    # (c) one run_cycle
    if time.process_time() < deadline - 2.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 2.0)
        print("cycle R=%.7f (N=%d, band01=%.4f, band1=%.4f)"
              % (bestR, best.size, _band_frac(best, 0.001),
                 _band_frac(best, 0.01)))

    # (d) clip ladder
    clip_ladder = [(0.95, 1e4), (0.985, 1e4), (0.995, 1e5), (0.999, 1e5)]
    for c, beta in clip_ladder:
        if time.process_time() >= deadline - 1.5:
            break
        free = _peak_window(best, tol=0.999, pad_frac=0.25, extra=256)
        ht = _lbfgs_block_clip(best, free, 300, deadline - 1.5, c, beta)
        ht = _rescale(ht)
        r = R_of(ht)
        print("clip c=%.3f beta=%.0e R=%.7f band1=%.4f band01=%.4f"
              % (c, beta, r, _band_frac(ht, 0.01), _band_frac(ht, 0.001)))
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    # (e) final polish
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 600, deadline - 0.6, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _refine_knots(best, 300, deadline - 0.3)
        r = R_of(ht)
        if r > bestR + 1e-13:
