        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- NEW: coarse control-point parametrisation ----

def _ctrl(h, K):
    n = h.size
    if K >= n:
        return h.copy()
    xk = np.linspace(0, n - 1, K)
    return np.interp(np.arange(n), xk, h)


def _raster(c, N):
    K = c.size
    if K == N:
        return c.copy()
    return np.interp(np.arange(N), np.linspace(0, N - 1, K), c)


def _interp_matrix_apply(g, N, K):
    """Given gradient g w.r.t. raster h (length N), return gradient w.r.t.
    control values c (length K) for h = interp(c)."""
    if K == N:
        return g.copy()
    xo = np.arange(N, dtype=float)
    xk = np.linspace(0, N - 1, K)
    # For each output index, find bracketing control indices and weights
    idx = np.searchsorted(xk, xo, side='right') - 1
    idx = np.clip(idx, 0, K - 2)
    x0 = xk[idx]
    x1 = xk[idx + 1]
    w1 = (xo - x0) / (x1 - x0)
    w0 = 1.0 - w1
    gc = np.zeros(K)
    np.add.at(gc, idx, g * w0)
    np.add.at(gc, idx + 1, g * w1)
    return gc


def _lbfgs_ctrl(c0, N, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return c0
    c0 = np.clip(c0, 0, None)
    if c0.sum() <= 0:
        return c0
    K = c0.size
    scale = max(1e-12, 1e-9 * float(c0.max()))
    x0 = np.log(c0 + scale)
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        c = np.exp(x)
        h = _raster(c, N)
        val, gh = fg(h)
        gc = _interp_matrix_apply(gh, N, K)
        gx = gc * c
        return val, gx

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    return np.exp(res.x)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: full L-BFGS polish of the start.
    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 2 (NEW): coarse control-point ladder.
    N = best.size
    for K in (384, 1536, 6144):
        if time.process_time() >= deadline - 6.0:
            break
        c0 = _ctrl(best, K)
        c = _lbfgs_ctrl(c0, N, 400, deadline - 6.0, beta=0.0)
        if K == 6144 and time.process_time() < deadline - 5.0:
            # windowed beta pass on the control points
            c = _lbfgs_ctrl(c, N, 200, deadline - 5.0, beta=1e7)
        h = _raster(c, N)
        h = _seed_zeros(h)
        r0 = R_of(h)
        if time.process_time() < deadline - 3.0:
            h, r0, _ = run_cycle(h, r0, deadline - 3.0)
        Lf = _knots(h)
        am = float(np.argmax(Lf)) / max(1, Lf.size - 1)
        print("ctrl K=%d R=%.7f argmax=%.3f band01=%.2f%%"
              % (K, r0, am, 100.0 * _band_frac(h, 0.001)))
        if r0 > bestR + 1e-13:
            best, bestR = h.copy(), r0

    # Phase 3: final full L-BFGS polish.
    if time.process_time() < deadline - 1.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 1.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline, maxiter_scale=1.0):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, int(800 * maxiter_scale), deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, int(400 * maxiter_scale), deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        if win.size > 40000:
            continue
        ht = _lbfgs_block(best, win, maxiter=int(250 * maxiter_scale),
                          deadline=deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, int(300 * maxiter_scale), deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, int(300 * maxiter_scale), deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _newton_window(h0, free, deadline, beta, maxiter):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0, np.inf
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0, np.inf
    if time.process_time() >= deadline - 0.3:
        return h0, np.inf
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    base = h.copy()
    scale = max(1e-12, 1e-12 * float(base.max()))
    x0 = np.log(np.clip(base[active], 0.0, None) + scale)

    def _unpack(x):
        hh = base.copy()
        hh[active] = np.exp(x)
        return hh

    def f(x):
        hh = _unpack(x)
        val, g = fg(hh)
        return val, g[active]

    def hessp(x, p):
        pn = np.max(np.abs(p)) if p.size else 0.0
        if pn <= 0:
            return np.zeros_like(x)
        eps = 1e-6 / pn
        _, gp = f(x + eps * p)
        _, gm = f(x - eps * p)
        return (gp - gm) / (2.0 * eps)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, hessp=hessp, method='trust-ncg',
                       callback=cb,
                       options={'maxiter': maxiter, 'gtol': 1e-14})
    except (TimeoutError, Exception):
        return h0, np.inf
    if res is None:
        return h0, np.inf
    hh = _unpack(res.x)
    hh = _rescale(np.clip(hh, 0.0, None))
    _, gfin = fg(hh)
    gnorm = float(np.max(np.abs(gfin[active]))) if active.size else np.inf
    return hh, gnorm


def _resample_up(h, factor):
    n = h.size
    if factor <= 1:
        return h.copy()
    xi = np.arange(n, dtype=float)
    xo = np.arange((n - 1) * factor + 1, dtype=float) / factor
    out = np.interp(xo, xi, h)
    return out / factor


def _antisym_split(h):
    """Build h2 of length 2N with h2[2i]=h[i]*(1+d[i]), h2[2i+1]=h[i]*(1-d[i])."""
    n = h.size
    i = np.arange(n, dtype=float)
    f1 = np.random.uniform(3.0, 12.0)
    f2 = np.random.uniform(20.0, 60.0)
    p1 = np.random.uniform(0.0, 2.0 * np.pi)
    p2 = np.random.uniform(0.0, 2.0 * np.pi)
    d = 0.03 * (np.sin(2.0 * np.pi * f1 * i / n + p1)
                + 0.6 * np.sin(2.0 * np.pi * f2 * i / n + p2))
    h2 = np.empty(2 * n, dtype=float)
    h2[0::2] = h * (1.0 + d)
    h2[1::2] = h * (1.0 - d)
    h2 = np.clip(h2, 0.0, None)
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: full L-BFGS polish of the start.
    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 2 (NEW): antisymmetric even/odd split at doubled grid.
    doubled_ok = False
    if best.size <= 500000 and time.process_time() < deadline - 6.0:
        h2 = _antisym_split(best)
        r2 = R_of(h2)
        print("2x antisym init R=%.7f N=%d" % (r2, h2.size))
        # run_cycle on doubled grid with reduced maxiter to fit time.
        if time.process_time() < deadline - 3.0:
            h2, r2, _ = run_cycle(h2, r2, deadline - 3.0, maxiter_scale=0.75)
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_all_pos(h2, 400, deadline - 1.5, beta=0.0)
            rt = R_of(ht)
            if rt > r2 + 1e-13:
                h2, r2 = ht, rt
        if time.process_time() < deadline - 0.8:
            ht = _lbfgs_all_pos(h2, 300, deadline - 0.8, beta=0.0)
            rt = R_of(ht)
            if rt > r2 + 1e-13:
                h2, r2 = ht, rt
        # report
        ev = h2[0::2]
        od = h2[1::2]
        spread = float(np.std(ev / np.maximum(od, 1e-30) - 1.0))
        Lf2 = _knots(h2)
        argmax = float(np.argmax(Lf2)) / max(1, Lf2.size - 1)
        print("2x antisym R=%.7f N=%d argmax=%.3f spread=%.3e"
              % (r2, h2.size, argmax, spread))
        if r2 > bestR + 1e-13:
            best, bestR = h2.copy(), r2
            doubled_ok = True
        else:
            # merge back and re-polish on original grid
            m = (h2.size // 2) * 2
            hm = 0.5 * (h2[:m:2] + h2[1:m:2])
            hm = _rescale(hm)
            if time.process_time() < deadline - 0.8:
                ht = _lbfgs_all_pos(hm, 300, deadline - 0.8, beta=0.0)
                rm = R_of(ht)
                if rm > bestR + 1e-13:
                    best, bestR = ht.copy(), rm

    # Phase 3: run_cycle polish on best.
    if time.process_time() < deadline - 1.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        print("post cycle R=%.7f" % bestR)

    # Phase 4: final full L-BFGS polish.
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.6, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_clip(h, c, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num_full, dq_full, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    Mb = mx + np.log(Z) / beta
    t = c * Mb
    mask = Lf < t
    u = np.minimum(Lf, t)
    a = u[:-1]; b = u[1:]
    num_c = np.sum(a * a + a * b + b * b) / 3.0
    if num_c <= 0:
        return _fun_grad(h)
    dqc = np.zeros_like(u)
    dqc[:-1] += (2 * a + b)
    dqc[1:] += (a + 2 * b)
    dqc /= 3.0
    above = ~mask
    sum_above = dqc[above].sum()
    dLf = np.where(mask, dqc, c * sum_above * w)
    grad = _backprop(dLf, h) + 2.0 / s
    val = -np.log(num_c) + 2.0 * np.log(s) + np.log(Mb)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_block_clip(h0, free, maxiter, deadline, c, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_clip(hh, c, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _resample(h, N):
    n = h.size
    if n == N:
        return h.copy()
    xp = (np.arange(n) + 0.5) / n
    xq = (np.arange(N) + 0.5) / N
    return np.interp(xq, xp, h)


def _local_refine(h, deadline, rounds=3):
    """Local refinement via block L-BFGS on alternating windows."""
    n = h.size
    best = h.copy()
    bestR = R_of(best)
    for rd in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        # alternating halves + thirds
        wins = [np.arange(0, n // 2), np.arange(n // 2, n)]
        step = max(64, n // 8)
        for s in range(0, n, step):
            wins.append(np.arange(s, min(n, s + 2 * step)))
        for win in wins:
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_block(best, win, maxiter=80, deadline=deadline - 0.5,
                              beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: base polish cycle.
    if time.process_time() < deadline - 1.5:
        best, bestR = run_cycle(best, bestR, deadline - 1.5)

    # NEW Phase A: multi-resolution resample + refine. The idea is that
    # the optimum on a coarser grid is easier to find, then upsample and
    # refine on the fine grid, escaping the local optimum on the fine grid.
    n0 = best.size
    for N in [max(2048, n0 // 8), max(4096, n0 // 4), max(8192, n0 // 2)]:
        if time.process_time() >= deadline - 4.0:
            break
        if N >= n0:
            continue
        hr = _resample(best, N)
        hr = _rescale(hr)
        hr, rr = run_cycle(hr, R_of(hr), deadline - 4.0)
        hu = _resample(hr, n0)
        hu = _rescale(hu)
        ru = R_of(hu)
        print("multires N=%d R=%d upsample R=%.7f" % (N, rr, ru))
        if ru > bestR + 1e-13:
            best, bestR = hu.copy(), ru

    # Phase 2: clipped-L2 anneal (as in original).
    anneal = [(0.40, 1e2), (0.55, 1e2), (0.70, 1e3), (0.82, 1e3),
              (0.90, 1e4), (0.95, 1e4), (0.98, 1e5), (0.995, 1e5),
              (0.999, 1e5)]
    for i, (c, beta) in enumerate(anneal):
        if time.process_time() >= deadline - 2.0:
            break
        free = _peak_window(best, tol=0.90, pad_frac=0.6, extra=1024)
        ht = _lbfgs_block_clip(best, free, 500, deadline - 2.0, c, beta)
        ht = _rescale(ht)
        r = R_of(ht)
        print("anneal c=%.3f R=%.7f" % (c, r))
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        if (i % 2 == 1) and time.process_time() < deadline - 2.0:
            hp = _lbfgs_all_pos(best, 200, deadline - 2.0, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp.copy(), rp

    # Phase 3: full run_cycle.
    if time.process_time() < deadline - 1.0:
        best, bestR = run_cycle(best, bestR, deadline - 1.0)
        print("post-anneal cycle R=%.7f" % bestR)

    # NEW Phase B: alternating-window local refinement (different from
    # global L-BFGS) to escape global optimum stalls.
    if time.process_time() < deadline - 0.8:
        ht, rt = _local_refine(best, deadline - 0.8, rounds=4)
        if rt > bestR + 1e-13:
            best, bestR = ht.copy(), rt
            print("local refine R=%.7f" % bestR)

    # Phase 4: refine knots.
    if time.process_time() < deadline - 0.8:
        ht = _refine_knots(best, 300, deadline - 0.6)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    # Phase 5: final full L-BFGS polish.
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-5:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _resample(h, N):
    n = h.size
    if n == N:
        return h.copy()
    xp = (np.arange(n) + 0.5) / n
    xq = (np.arange(N) + 0.5) / N
    return np.interp(xq, xp, h)


def _smooth(h, w):
    """Box-smooth then rescale; keeps nonneg."""
    if w <= 1:
        return h
    k = np.ones(w) / w
    out = np.convolve(h, k, mode='same')
    return _rescale(out)


def _perturb_and_refine(best, bestR, deadline, amp, smooth_w, seed):
    rng = np.random.RandomState(seed)
    n = best.size
    # Smooth random field via random walk low-freq, applied multiplicatively.
    noise = rng.randn(n)
    if smooth_w > 1:
        noise = np.convolve(noise, np.ones(smooth_w) / smooth_w, mode='same')
    noise /= (np.std(noise) + 1e-12)
    h = best * np.exp(amp * noise)
    h = _rescale(h)
    if time.process_time() >= deadline - 0.5:
        return best, bestR
    ht = _lbfgs_all_pos(h, 300, deadline - 0.5, beta=0.0)
    r = R_of(ht)
    if r > bestR + 1e-13:
        return ht, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: cheap polish.
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.8, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    # NEW: multiplicative smooth-noise basin hopping. Each round perturbs
    # the current best with a smooth multiplicative field and re-polishes
    # globally. Different from prior clipped/gradient tricks: pure stochastic
    # exploration of the fine-grid landscape, kept only on improvement.
    best_alt = best.copy()
    best_altR = bestR
    seed = 12345
    round_i = 0
    amp_sched = [0.015, 0.025, 0.04, 0.06]
    sw_sched = [max(4, best.size // 400), max(8, best.size // 200),
                max(16, best.size // 100)]
    while time.process_time() < deadline - 0.6:
        amp = amp_sched[round_i % len(amp_sched)]
        sw = sw_sched[(round_i // len(amp_sched)) % len(sw_sched)]
        ht, rt = _perturb_and_refine(best, bestR, deadline, amp, sw, seed)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            print("hop amp=%.3f sw=%d R=%.7f" % (amp, sw, bestR))
        seed += 1
        round_i += 1

    # Final global polish.
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 600, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-5:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


# ---------- two-window mass transfer ----------

def _apply_transfer(h, a1, b1, a2, b2, alpha):
    hn = h.copy()
    m1 = h[a1:b1].sum()
    m2 = h[a2:b2].sum()
    if m1 <= 0 or m2 <= 0:
        return None
    hn[a1:b1] = h[a1:b1] * (1.0 + alpha)
    hn[a2:b2] = h[a2:b2] * (1.0 - alpha * m1 / m2)
    if np.any(hn < 0):
        return None
    return hn


def _best_alpha(h, a1, b1, a2, b2, lo=-0.45, hi=0.45, iters=24):
    gr = (np.sqrt(5.0) - 1.0) / 2.0
    c = hi - gr * (hi - lo)
    d = lo + gr * (hi - lo)
    hc = _apply_transfer(h, a1, b1, a2, b2, c)
    hd = _apply_transfer(h, a1, b1, a2, b2, d)
    fc = R_of(hc) if hc is not None else -1.0
    fd = R_of(hd) if hd is not None else -1.0
    for _ in range(iters):
        if fc > fd:
            hi = d; d = c; fd = fc
            c = hi - gr * (hi - lo)
            hc = _apply_transfer(h, a1, b1, a2, b2, c)
            fc = R_of(hc) if hc is not None else -1.0
        else:
            lo = c; c = d; fc = fd
            d = lo + gr * (hi - lo)
            hd = _apply_transfer(h, a1, b1, a2, b2, d)
            fd = R_of(hd) if hd is not None else -1.0
    alpha = 0.5 * (lo + hi)
    ha = _apply_transfer(h, a1, b1, a2, b2, alpha)
    if ha is None:
        return 0.0, h
    return alpha, ha


def _best_flatten(h, a, b, lo=-0.45, hi=0.45, iters=20):
    win = h[a:b]
    if win.size == 0:
        return 0.0, h
    mean = h.mean()
    gr = (np.sqrt(5.0) - 1.0) / 2.0
    def ev(alpha):
        hn = h.copy()
        hn[a:b] = (1.0 - alpha) * win + alpha * mean
        if np.any(hn < 0):
            return -1.0, None
        return R_of(hn), hn
    c = hi - gr * (hi - lo)
    d = lo + gr * (hi - lo)
    fc, hc = ev(c)
    fd, hd = ev(d)
    for _ in range(iters):
        if fc > fd:
            hi = d; d = c; fd = fc; hd = hc
            c = hi - gr * (hi - lo)
            fc, hc = ev(c)
        else:
            lo = c; c = d; fc = fd; hc = hd
            d = lo + gr * (hi - lo)
            fd, hd = ev(d)
    alpha = 0.5 * (lo + hi)
    fa, ha = ev(alpha)
    if ha is None:
        return 0.0, h
    return alpha, ha


def _build_pairs(n, Lf):
    widths = [256, 1024, 4096, 16384]
    stride = 1024
    m = int(np.argmax(Lf))
    starts = list(range(0, max(1, n - 1), stride))
    pairs = []
    seen = set()
    def add(a1, b1, a2, b2):
        if a1 < 0 or b1 > n or a2 < 0 or b2 > n:
            return
        if b1 <= a1 or b2 <= a2:
            return
        if not (b1 <= a2 or b2 <= a1):
            return
        key = (a1, b1, a2, b2)
        if key in seen:
            return
        seen.add(key)
        pairs.append(key)
    for w in widths:
        for s in starts:
            a1 = s; b1 = s + w
            a2 = m - w // 2; b2 = a2 + w
            if a2 < 0:
                a2 = 0; b2 = w
            add(a1, b1, a2, b2)
            add(a2, b2, a1, b1)
    plateau_lo = max(0, m - 4096)
    plateau_hi = min(n, m + 4096)
    for w in widths:
        for s in starts:
            a1 = s; b1 = s + w
            a2 = plateau_lo; b2 = min(n, plateau_lo + w)
            add(a1, b1, a2, b2)
            add(a2, b2, a1, b1)
            a2 = max(0, plateau_hi - w); b2 = plateau_hi
            add(a1, b1, a2, b2)
            add(a2, b2, a1, b1)
    for w in widths:
        for s in starts:
            a1 = s; b1 = s + w
            a2 = n - s - w; b2 = n - s
            add(a1, b1, a2, b2)
    if len(pairs) > 400:
        idx = np.linspace(0, len(pairs) - 1, 400).astype(int)
        pairs = [pairs[i] for i in idx]
    return pairs


def _scan(h, bestR, deadline, verbose=False):
    n = h.size
    Lf = _knots(h)
    pairs = _build_pairs(n, Lf)
    best_delta = -np.inf
    best_h = None
    for (a1, b1, a2, b2) in pairs:
        if time.process_time() >= deadline:
            break
        alpha, hn = _best_alpha(h, a1, b1, a2, b2)
        if hn is None:
            continue
        rn = R_of(hn)
        d = rn - bestR
        if d > best_delta:
            best_delta = d
            best_h = hn
    for w in [256, 1024, 4096, 16384]:
        for s in range(0, max(1, n - 1), 1024):
            if time.process_time() >= deadline:
                break
            a = s; b = min(n, s + w)
            alpha, hn = _best_flatten(h, a, b)
            if hn is None:
                continue
            rn = R_of(hn)
            d = rn - bestR
            if d > best_delta:
                best_delta = d
                best_h = hn
    return best_delta, best_h


# ---------- main ----------

def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    for frac in fracs:
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.3, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, beta=0.0)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Multi-scale refinement using beta-smoothing at several temperatures,
    # which is a different search direction than the q-perturbation approach
    # of the parent program.
    for beta in (0.0, 20.0, 80.0, 300.0, 1000.0):
        if time.process_time() >= deadline - 1.0:
            break
        cap = min(deadline - 0.5, time.process_time() + 6.0)
        hp = _lbfgs_log(best, 250, cap, beta=beta)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp, rp
            print("  beta=%.1f full R=%.9f" % (beta, bestR))

    # Alternating polish + scan cycles
    cycle = 0
    while time.process_time() < deadline - 0.5:
        cycle += 1
        if time.process_time() < deadline - 0.5:
            hp, rp = _polish(best, deadline)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                print("  cyc=%d polish R=%.9f" % (cycle, bestR))
        if time.process_time() < deadline - 0.5:
            cap2 = min(deadline - 0.5, time.process_time() + 4.0)
            bd, bh = _scan(best, bestR, cap2)
            if bd > 1e-13 and bh is not None:
                rb = R_of(bh)
                if rb > bestR:
                    best, bestR = bh, rb
                    print("  cyc=%d scan R=%.9f" % (cycle, bestR))
        if time.process_time() < deadline - 0.5:
            cap = min(deadline - 0.3, time.process_time() + 5.0)
            hp = _lbfgs_log(best, 200, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                print("  cyc=%d full R=%.9f" % (cycle, bestR))

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_clip(h, c):
    """Clipped-L2 objective: penalise knots above c*max via squared hinge."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    thr = c * mx
    over = Lf > thr
    # penalty = sum over knots of max(0, L - thr)^2, scaled
    d = np.where(over, Lf - thr, 0.0)
    pen = np.sum(d * d)
    scale = 1.0 / (mx * mx + 1e-30)
    gLf = -dq / num
    # gradient of penalty wrt Lf: 2*d*scale, plus effect of thr=c*mx
    # thr depends on mx; treat mx as constant (envelope-safe enough)
    gLf += 2.0 * d * scale
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + pen * scale
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_block_clip(h0, free, maxiter, deadline, c):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_clip(hh, c)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline, maxiter_scale=1.0):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, int(800 * maxiter_scale), deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, int(400 * maxiter_scale), deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        if win.size > 40000:
            continue
        ht = _lbfgs_block(best, win, maxiter=int(250 * maxiter_scale),
                          deadline=deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, int(300 * maxiter_scale), deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, int(300 * maxiter_scale), deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR, 0.0


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _argmax_loc(h):
    Lf = _knots(h)
    if Lf.size < 2:
        return 0.0
    return float(np.argmax(Lf)) / max(1, Lf.size - 1)


def _report(tag, h, R):
    print("%s R=%.7f N=%d zeros=%.1f%% band01=%.2f%% band1=%.2f%% argmax=%.3f"
          % (tag, R, h.size, 100.0 * np.mean(h <= 0),
             100.0 * _band_frac(h, 0.001), 100.0 * _band_frac(h, 0.01),
             _argmax_loc(h)))


def _hop(h, bestR, deadline, rng):
    """One hop: perturb a random window, repair with beta=1e7 halo + sharp polish."""
    n = h.size
    if n < 8:
        return h, bestR
    # pick a random window
    wlen = int(rng.integers(max(8, n // 20), max(16, n // 4)))
    wlen = min(wlen, n)
    lo = int(rng.integers(0, n - wlen + 1))
    hi = lo + wlen
    hp = h.copy()
    # multiplicative perturbation
    amp = rng.uniform(0.02, 0.15)
    noise = 1.0 + amp * rng.standard_normal(wlen)
    hp[lo:hi] = np.clip(hp[lo:hi] * noise, 0.0, None)
    hp = _rescale(hp)
    rp = R_of(hp)
    # repair: 64-cell halo around window with beta=1e7
    halo = 64
    flo = max(0, lo - halo)
    fhi = min(n, hi + halo)
    free = np.arange(flo, fhi)
    if free.size > 0 and time.process_time() < deadline - 0.5:
        ht = _lbfgs_block(hp, free, 200, deadline - 0.5, beta=1e7)
        rt = R_of(ht)
        if rt > rp:
            hp, rp = ht, rt
    # sharp polish on peak window
    if time.process_time() < deadline - 0.5:
        win = _peak_window(hp, tol=0.95, pad_frac=0.5, extra=512)
        if win.size <= 40000:
            ht = _lbfgs_block(hp, win, 250, deadline - 0.5, beta=0.0)
            rt = R_of(ht)
            if rt > rp:
                hp, rp = ht, rt
    if rp > bestR + 1e-13:
        return hp, rp
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Stage (a): one run_cycle.
    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        _report("(a) cycle", best, bestR)

    # Stage (b): clipped-L2 ladder.
    c_ladder = [0.55, 0.75, 0.90, 0.95, 0.985]
    beta_ladder = [1e3, 1e3, 1e4, 1e4, 1e5]
    for c, beta in zip(c_ladder, beta_ladder):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, tol=0.95, pad_frac=0.5, extra=512)
        if win.size == 0 or win.size > 60000:
            continue
        ht = _lbfgs_block_clip(best, win, 500, deadline - 1.0, c=c)
        rt = R_of(ht)
        if rt > bestR + 1e-13:
            best, bestR = ht.copy(), rt
        # follow with full polish
        if time.process_time() < deadline - 0.8:
            ht = _lbfgs_all_pos(best, 200, deadline - 0.8, beta=0.0)
            rt = R_of(ht)
            if rt > bestR + 1e-13:
                best, bestR = ht.copy(), rt
        _report("(b) c=%.3f" % c, best, bestR)

    # Stage (c): hop loop.
    rng = np.random.default_rng(12345)
    n_hops = 0
    n_accept = 0
    while time.process_time() < deadline - 1.6:
        n_hops += 1
        hnew, rnew = _hop(best, bestR, deadline - 1.6, rng)
        if rnew > bestR + 1e-13:
            best, bestR = hnew, rnew
            n_accept += 1
            _report("(c) hop %d accept" % n_hops, best, bestR)
        if n_hops > 200:
            break
    print("(c) hops=%d accepted=%d" % (n_hops, n_accept))
    _report("(c) end", best, bestR)

    # Stage (d): final run_cycle + full polish.
    if time.process_time() < deadline - 1.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        _report("(d) cycle", best, bestR)
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.6, beta=0.0)
        rt = R_of(ht)
        if rt > bestR + 1e-13:
            best, bestR = ht.copy(), rt
    _report("final", best, bestR)

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_q(h, q, beta):
    """q-power surrogate energy for numerator, log-sum-exp for max."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    n = Lf.size
    w = np.ones(n)
    w[0] = 0.5; w[-1] = 0.5
    Lp = np.maximum(Lf, 1e-12)
    Eq = np.sum(w * Lp ** q)
    if Eq <= 0:
        return 1e18, np.zeros(h.size)
    dEq = q * w * Lp ** (q - 1.0)
    # softmax for max
    mx = Lf.max()
    if mx <= 0:
        mx = 1e-12
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        wsm = np.zeros(n); wsm[int(np.argmax(Lf))] = 1.0
        sm = mx
    else:
        wsm = e / Z
        sm = mx + np.log(Z) / beta
    gLf = -dEq / Eq + wsm / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(Eq) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_block_q(h0, free, maxiter, deadline, q, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_q(hh, q, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- hop moves ----

def _move_m1(best, rng):
    n = best.size
    w = int(rng.uniform(0.02, 0.15) * n)
    w = max(1, min(w, n))
    lo = int(rng.integers(0, n - w + 1))
    win = np.arange(lo, lo + w)
    h = best.copy()
    z = rng.standard_normal(w)
    h[win] = h[win] * np.exp(0.05 * z)
    return h, win


def _move_m2(best, rng):
    _, g = _fun_grad(best)
    zeros = np.flatnonzero(best <= 0)
    if zeros.size == 0:
        return None, None
    gz = g[zeros]
    order = np.argsort(gz)[::-1]
    k = int(rng.choice([16, 64, 256]))
    k = min(k, zeros.size)
    pick = zeros[order[:k]]
    h = best.copy()
    amp = 1e-3 * best.mean()
    h[pick] = h[pick] + amp
    return h, pick


def _move_m3(best, rng):
    n = best.size
    P = int(rng.choice([1000, 3000]))
    P = min(P, 200000)
    amp = 1e-3 * best.mean()
    pad = np.full(P, amp)
    if rng.random() < 0.5:
        h = np.concatenate((pad, best))
        touched = np.arange(0, P)
    else:
        h = np.concatenate((best, pad))
        touched = np.arange(n, n + P)
    h = _rescale(h)
    return h, touched


def _move_m4(best, rng):
    n = best.size
    w = max(1, int(0.10 * n))
    lo = int(rng.integers(0, n - w + 1))
    win = np.arange(lo, lo + w)
    h = best.copy()
    amp = 0.02 * best.mean()
    t = np.linspace(0, np.pi, w)
    h[win] = h[win] + amp * np.sin(t)
    return h, win


def _halo(touched, n, halo=64):
    if touched is None or touched.size == 0:
        return np.arange(n)
    lo = max(0, int(touched.min()) - halo)
    hi = min(n - 1, int(touched.max()) + halo)
    return np.arange(lo, hi + 1)


def _q_ladder(best, bestR, deadline):
    qs = [1.0, 1.25, 1.5, 1.75]
    for q in qs:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, tol=0.90, pad_frac=0.5, extra=512)
        ht = _lbfgs_block_q(best, win, 400, deadline - 0.5, q=q, beta=1e5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        # short exact polish
        if time.process_time() < deadline - 0.5:
            ht2 = _lbfgs_all_pos(best, 150, deadline - 0.5, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-13:
                best, bestR = ht2.copy(), r2
        if time.process_time() < deadline - 0.5:
            pw = _peak_window(best, pad_frac=0.15, extra=128)
            ht3 = _lbfgs_block(best, pw, 80, deadline - 0.5, beta=1e7)
            r3 = R_of(ht3)
            if r3 > bestR + 1e-13:
                best, bestR = ht3.copy(), r3
        Lf = _knots(best)
        mx = Lf.max()
        s = best.sum()
        ratio = 1e-2 * mx / s if s > 0 else 0.0
        print("q=%.2f R=%.7f band01=%.2f%% band1=%.2f%% ratio=%.5f" %
              (q, bestR, 100.0 * _band_frac(best, 0.001),
               100.0 * _band_frac(best, 0.01), ratio))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: q-homotopy ladder (the experiment).
    if time.process_time() < deadline - 1.5:
        best, bestR = _q_ladder(best, bestR, deadline - 1.5)
        print("after q ladder R=%.7f" % bestR)

    # Phase 2: full run_cycle.
    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 3: hop loop.
    hop = 0
    acc = 0
    moves = [_move_m1, _move_m2, _move_m3, _move_m4]
    while time.process_time() < deadline - 1.6:
        hop += 1
        mv = moves[int(rng.integers(0, 4))]
        try:
            h_try, touched = mv(best, rng)
        except Exception:
            h_try, touched = None, None
        if h_try is None:
            continue
        h_try = np.clip(h_try, 0, None)
        if h_try.sum() <= 0:
            continue
        n = h_try.size
        free = _halo(touched, n, 64)
        ht = _lbfgs_block(h_try, free, 150, deadline - 1.0, beta=1e7)
        if time.process_time() < deadline - 1.0:
            pw = _peak_window(ht, pad_frac=0.15, extra=128)
            ht = _lbfgs_block(ht, pw, 80, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            acc += 1
        if hop % 5 == 0:
            print("hop %d acc %d bestR=%.7f" % (hop, acc, bestR))

    print("hops done: %d accepted %d bestR=%.7f" % (hop, acc, bestR))

    # Phase 4: final polish.
    if time.process_time() < deadline - 1.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- hop moves ----

def _move_m1(best, rng):
    n = best.size
    w = int(rng.uniform(0.02, 0.15) * n)
    w = max(1, min(w, n))
    lo = int(rng.integers(0, n - w + 1))
    win = np.arange(lo, lo + w)
    h = best.copy()
    z = rng.standard_normal(w)
    h[win] = h[win] * np.exp(0.05 * z)
    return h, win


def _move_m2(best, rng):
    _, g = _fun_grad(best)
    zeros = np.flatnonzero(best <= 0)
    if zeros.size == 0:
        return None, None
    gz = g[zeros]
    order = np.argsort(gz)[::-1]
    k = int(rng.choice([16, 64, 256]))
    k = min(k, zeros.size)
    pick = zeros[order[:k]]
    h = best.copy()
    amp = 1e-3 * best.mean()
    h[pick] = h[pick] + amp
    return h, pick


def _move_m3(best, rng):
    n = best.size
    P = int(rng.choice([1000, 3000]))
    P = min(P, 200000)
    amp = 1e-3 * best.mean()
    pad = np.full(P, amp)
    if rng.random() < 0.5:
        h = np.concatenate((pad, best))
        touched = np.arange(0, P)
    else:
        h = np.concatenate((best, pad))
        touched = np.arange(n, n + P)
    h = _rescale(h)
    return h, touched


def _move_m4(best, rng):
    n = best.size
    w = max(1, int(0.10 * n))
    lo = int(rng.integers(0, n - w + 1))
    win = np.arange(lo, lo + w)
    h = best.copy()
    amp = 0.02 * best.mean()
    t = np.linspace(0, np.pi, w)
    h[win] = h[win] + amp * np.sin(t)
    return h, win


def _halo(touched, n, halo=64):
    if touched is None or touched.size == 0:
        return np.arange(n)
    lo = max(0, int(touched.min()) - halo)
    hi = min(n - 1, int(touched.max()) + halo)
    return np.arange(lo, hi + 1)


def _polish(h, deadline):
    """(i) all-pos linear, (ii) peak-window beta then sharp, (iii) refine."""
    if time.process_time() < deadline - 0.5:
        h = _lbfgs_all_pos(h, 400, deadline - 0.5, beta=0.0)
    if time.process_time() < deadline - 0.5:
        win = _peak_window(h, tol=0.99, pad_frac=0.4, extra=256)
        h = _lbfgs_block(h, win, 300, deadline - 0.5, beta=1e7)
    if time.process_time() < deadline - 0.5:
        win = _peak_window(h, tol=0.99, pad_frac=0.4, extra=256)
        h = _lbfgs_block(h, win, 200, deadline - 0.5, beta=0.0)
    if time.process_time() < deadline - 0.5:
        h = _refine_knots(h, 300, deadline - 0.5)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: initial run_cycle to confirm plateau.
    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 2: PRUNE experiment.
    prune_best = best.copy()
    prune_bestR = bestR
    for q in [0.70, 0.50, 0.35, 0.25]:
        if time.process_time() >= deadline - 2.0:
            break
        p = best[best > 0]
        if p.size == 0:
            break
        thr = np.quantile(p, 1.0 - q)
        hp = best.copy()
        hp[hp < thr] = 0.0
        hp = _rescale(hp)
        if hp.sum() <= 0:
            continue
        hq = _polish(hp, deadline - 1.5)
        rq = R_of(hq)
        print("prune q=%.2f R=%.7f zeros=%.1f%% band01=%.2f%% band1=%.2f%%" %
              (q, rq, 100.0 * np.mean(hq <= 0),
               100.0 * _band_frac(hq, 0.001), 100.0 * _band_frac(hq, 0.01)))
        if rq > prune_bestR + 1e-13:
            prune_best, prune_bestR = hq.copy(), rq
        if rq > bestR + 1e-13:
            best, bestR = hq.copy(), rq

    # Regrow if pruned best is close to base.
    if prune_bestR > bestR - 1e-6 and time.process_time() < deadline - 2.0:
        # reconstruct a pruned version at q=0.5 and regrow removed cells
        p = best[best > 0]
        if p.size > 0:
            thr = np.quantile(p, 0.5)
            removed = (best > 0) & (best < thr)
            hr = best.copy()
            hr[removed] = 1e-6 * best.mean()
            hr = _rescale(hr)
            hr = _polish(hr, deadline - 1.5)
            rr = R_of(hr)
            print("regrow R=%.7f zeros=%.1f%%" % (rr, 100.0 * np.mean(hr <= 0)))
            if rr > prune_bestR + 1e-13:
                prune_best, prune_bestR = hr.copy(), rr
            if rr > bestR + 1e-13:
                best, bestR = hr.copy(), rr

    # Phase 3: hop loop on best.
    hop = 0
    acc = 0
    moves = [_move_m1, _move_m2, _move_m3, _move_m4]
    while time.process_time() < deadline - 1.6:
        hop += 1
        mv = moves[int(rng.integers(0, 4))]
        try:
            h_try, touched = mv(best, rng)
        except Exception:
            h_try, touched = None, None
        if h_try is None:
            continue
        h_try = np.clip(h_try, 0, None)
        if h_try.sum() <= 0:
            continue
        n = h_try.size
        free = _halo(touched, n, 64)
        ht = _lbfgs_block(h_try, free, 150, deadline - 1.0, beta=1e7)
        if time.process_time() < deadline - 1.0:
            pw = _peak_window(ht, pad_frac=0.15, extra=128)
            ht = _lbfgs_block(ht, pw, 80, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            acc += 1
        if hop % 5 == 0:
            print("hop %d acc %d bestR=%.7f" % (hop, acc, bestR))

    print("hops done: %d accepted %d bestR=%.7f" % (hop, acc, bestR))

    # Phase 4: final polish.
    if time.process_time() < deadline - 1.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _upsample(h, factor):
    n = h.size
    m = n * factor
    x = (np.arange(m) + 0.5) / factor
    return np.interp(x, np.arange(n) + 0.5, h, left=h[0], right=h[-1])


def _refine_support(h, deadline, maxiter=200):
    """L-BFGS on all positive entries but with a monotone tightening of
    the max-knot penalty (beta schedule) to sharpen the peak."""
    cur = h
    curR = R_of(h)
    for beta in (1e5, 1e6, 1e7, 1e8, 1e9, 1e10):
        if time.process_time() >= deadline - 0.5:
            break
        hb = _lbfgs_log(cur, maxiter, deadline, beta=beta)
        rb = R_of(hb)
        if rb > curR + 1e-13:
            cur, curR = hb, rb
    # final crisp polish on true objective
    if time.process_time() < deadline - 0.5:
        hs = _lbfgs_log(cur, maxiter, deadline)
        rs = R_of(hs)
        if rs > curR + 1e-13:
            cur, curR = hs, rs
    return cur, curR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Upsample FIRST if it helps: get to a finer grid early so all
    # subsequent optimization happens at the higher resolution.
    if best.size * 2 <= 1000000 and time.process_time() < deadline - 20.0:
        up = _rescale(_upsample(best, 2))
        ru = R_of(up)
        print("upsample x2 -> R=%.7f (N=%d)" % (ru, up.size))
        if ru > bestR - 1e-6:
            best, bestR = up, ru
            # quick coarse refine at new resolution
            hb, rb = _refine_support(best, deadline, maxiter=200)
            if rb > bestR:
                best, bestR = hb, rb
            print("after upsample refine R=%.7f" % bestR)

    # Alternating schedule: global-ish refine, then local peak window polish.
    schedule = [
        (0.05, 64, 0.0),
        (0.05, 64, 1e6),
        (0.10, 128, 1e7),
        (0.15, 256, 1e8),
        (0.25, 512, 1e9),
        (0.40, 1024, 1e9),
        (0.60, 2048, 1e10),
        (0.90, 4096, 1e10),
    ]

    cur = best.copy()
    curR = bestR
    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        for frac, extra, beta in schedule:
            if time.process_time() >= deadline - 2.0:
                break
            hw = _window_polish_peak(cur, deadline, frac, extra,
                                     maxiter=300, beta=beta)
            rw = R_of(hw)
            if rw > curR + 1e-13:
                cur, curR = hw, rw
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR

        # A full-scale multi-beta refine from the best point occasionally.
        if time.process_time() < deadline - 6.0:
            hb, rb = _refine_support(best, min(deadline - 2.0, time.process_time() + 6.0),
                                     maxiter=200)
            if rb > bestR + 1e-13:
                best, bestR = hb, rb
                cur, curR = hb.copy(), rb

        zf = 100.0 * np.mean(best <= 0)
        am = int(np.argmax(_knots(best)))
        print("cycle %d R=%.7f argmax=%d zeros=%.1f%%" %
              (cycle, bestR, am, zf))

        # One more upsample opportunity if there's plenty of time left
        if best.size * 2 <= 1000000 and time.process_time() < deadline - 15.0:
            up = _rescale(_upsample(best, 2))
            ru = R_of(up)
            if ru > bestR - 1e-6:
                print("upsample x2 -> R=%.7f (N=%d)" % (ru, up.size))
                best, bestR = up, ru
                cur, curR = up.copy(), ru
                hb, rb = _refine_support(best, deadline, maxiter=200)
                if rb > bestR:
                    best, bestR = hb, rb
                    cur, curR = hb.copy(), rb

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 200, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h, M):
    h = np.asarray(h, dtype=float)
    N = h.size
    if M == N:
        return h.copy()
    cm = np.concatenate(([0.0], np.cumsum(h)))
    total = cm[-1]
    if total <= 0:
        return np.ones(M)
    edges = np.linspace(0.0, N, M + 1)
    mass_at = np.interp(edges, np.arange(N + 1), cm)
    new_h = np.diff(mass_at)
    s = new_h.sum()
    if s > 0:
        new_h *= total / s
    return np.clip(new_h, 0, None)


def _downsample(h, M):
    h = np.asarray(h, dtype=float)
    N = h.size
    if M == N:
        return h.copy()
    cm = np.concatenate(([0.0], np.cumsum(h)))
    total = cm[-1]
    if total <= 0:
        return np.ones(M)
    edges = np.linspace(0.0, N, M + 1)
    mass_at = np.interp(edges, np.arange(N + 1), cm)
    new_h = np.diff(mass_at) * (M / N)
    s = new_h.sum()
    if s > 0:
        new_h *= total / s
    return np.clip(new_h, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    base = start_arr.copy()
    base_r = R_of(base)
    best = base.copy()
    best_r = base_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # New idea 1: round-trip through a coarser grid to smooth out discretisation
    # artifacts, then refine. Coarsening + re-fining can escape local optima
    # that pure upsample+refine cannot.
    n0 = base.size
    if time.process_time() < hard_end - 8.0:
        for down_target in (max(64, n0 // 4), max(64, n0 // 2)):
            if time.process_time() >= hard_end - 6.0:
                break
            h_down = _downsample(base, down_target)
            h_down = _lbfgs_log(h_down, maxiter=800, deadline=hard_end - 2.0)
            h_up = _prolongate(h_down, n0)
            h_up = _lbfgs_log(h_up, maxiter=800, deadline=hard_end - 1.0)
            r_up = R_of(h_up)
            print("downup %d->%d R=%.6f" % (down_target, n0, r_up))
            if r_up > base_r - 1e-9:
                _consider(h_up, r_up)

    # New idea 2: upsample to 2x grid and refine.
    n_up = min(1000000, max(n0 * 2, n0))
    if n_up != n0 and time.process_time() < hard_end - 6.0:
        h_up = _prolongate(base, n_up)
        h_up = _lbfgs_log(h_up, maxiter=800, deadline=hard_end - 3.0)
        r_up = R_of(h_up)
        print("upsample %d R=%.6f (base %.6f)" % (n_up, r_up, base_r))
        if r_up > base_r - 1e-9:
            _consider(h_up, r_up)

    print("experiment R=%.6f N=%d | base R=%.6f N=%d"
          % (best_r, best.size, base_r, base.size))

    # Continue local refinement on `best` until the deadline.
    try:
        cur = best.copy()
        cur_r = best_r
        while time.process_time() < hard_end - 1.0:
            h = cur.copy()
            for beta in (120.0, 60.0, 30.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_sm(h, beta, maxiter=250, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=600, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, extra,
                                        maxiter=400, beta=None)
                if R_of(c) > R_of(h):
                    h = c
            if R_of(h) > cur_r + 1e-12:
                cur, cur_r = h, R_of(h)
                _consider(h, cur_r)
            else:
                # no progress this round: try a coarsen/refine kick
                if time.process_time() < hard_end - 4.0:
                    nd = max(64, cur.size // 3)
                    hk = _downsample(cur, nd)
                    hk = _lbfgs_log(hk, maxiter=400, deadline=hard_end - 1.0)
                    hk = _prolongate(hk, cur.size)
                    hk = _lbfgs_log(hk, maxiter=400, deadline=hard_end - 0.5)
                    if R_of(hk) > cur_r + 1e-12:
                        cur, cur_r = hk, R_of(hk)
                        _consider(hk, cur_r)
                    else:
                        break
            if time.process_time() >= hard_end - 1.0:
                break
        print("finish R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    if best_r < base_r:
        best = base.copy()
        best_r = base_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

