    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_clip(hh, c)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def _split_refine(h, deadline, factor=2):
    """Interpolate h by `factor` (per-step upsample), then re-optimise log.

    This is the key new idea vs the previous program: it lets the
    resolution grow, giving the optimiser fresh degrees of freedom to
    sharpen the peak plateau.  A split in N is exactly representable
    in the step-function class, so R can only improve if optimisation
    succeeds; we only keep the result if R actually increases."""
    n = h.size
    if n * factor > 900000:
        return h, R_of(h)
    if time.process_time() >= deadline - 1.0:
        return h, R_of(h)
    xo = np.arange(n, dtype=float)
    xn = (np.arange(n * factor, dtype=float) + 0.5) / factor - 0.5
    hn = np.interp(xn, xo, h)
    hn = np.clip(hn, 0, None)
    hn = _rescale(hn)
    r0 = R_of(h)
    cap = min(deadline - 0.5, time.process_time() + 4.0)
    h2 = _lbfgs_log(hn, 300, cap)
    r2 = R_of(h2)
    if r2 > r0:
        return h2, r2
    return h, r0


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard = t0 + budget_seconds - 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # -------- split-refinement: increase resolution iteratively ------
    for factor in (2, 2):
        if time.process_time() >= hard - 6.0:
            break
        if best.size * factor > 900000:
            break
        hnew, rnew = _split_refine(best, hard, factor=factor)
        print("  split x%d -> R=%.9f (N=%d)" % (factor, rnew, hnew.size))
        if rnew > bestR + 1e-13:
            best, bestR = hnew, rnew

    # -------- smooth-max (beta) refinement on the (now denser) grid --
    if time.process_time() < hard - 8.0:
        for beta, tcap in ((200.0, 3.0), (1000.0, 3.0), (5000.0, 3.0), (0.0, 3.0)):
            if time.process_time() >= hard - 5.0:
                break
            cap = min(hard - 4.0, time.process_time() + tcap)
            hb = _lbfgs_log(best, 300, cap, beta=beta)
            rb = R_of(hb)
            if rb > bestR:
                best, bestR = hb, rb
        print("  beta-refine -> %.9f" % bestR)

    # -------- plateau-clip: penalise knots just below max to flatten ---
    if time.process_time() < hard - 6.0:
        for c in (0.998, 0.999):
            if time.process_time() >= hard - 4.0:
                break
            cap = min(hard - 3.0, time.process_time() + 3.0)
            free = np.arange(best.size)
            hb = _lbfgs_block_clip(best, free, 200, cap, c)
            rb = R_of(hb)
            if rb > bestR:
                best, bestR = hb, rb
            else:
                # try a small local polish of the peak window
                free2 = _peak_window(best, 0.05)
                cap2 = min(hard - 3.0, time.process_time() + 2.0)
                hc = _lbfgs_block_clip(best, free2, 150, cap2, c)
                rc = R_of(hc)
                if rc > bestR:
                    best, bestR = hc, rc
        print("  clip-refine -> %.9f" % bestR)

    # -------- multi-scale peak polish --------
    if time.process_time() < hard - 4.0:
        cap2 = min(hard - 2.0, time.process_time() + 3.0)
        hp, rp = _polish(best, cap2, fracs=(0.02, 0.05, 0.10, 0.20, 0.35))
        if rp > bestR:
            best, bestR = hp, rp
        print("  polish -> %.9f" % bestR)

    # -------- final full log-space pass --------
    if time.process_time() < hard - 0.5:
        cap = min(hard - 0.3, time.process_time() + 3.0)
        hp = _lbfgs_log(best, 800, cap)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    new_best = best
    if bestR > start_bestR + 1e-13:
        return {"best": new_best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": new_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


# ---- Phase functions (each takes h, end) ----
def P1(h, end):
    return _lbfgs_all_pos(h, 200, end, beta=0.0)


def P2(h, end):
    return _lbfgs_all_pos(h, 200, end, beta=1e6)


def P3(h, end):
    win = _peak_window(h, pad_frac=0.15, extra=128)
    return _lbfgs_block(h, win, 250, end, beta=1e7)


def P4(h, end):
    win = _peak_window(h, pad_frac=0.40, extra=256)
    return _lbfgs_block(h, win, 250, end, beta=1e8)


def P5(h, end):
    return _refine_knots(h, 200, end)


PHASES = [P1, P2, P3, P4, P5]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    n_ph = len(PHASES)
    rate = [1e-12] * n_ph
    count = [0] * n_ph
    acc = [0.0] * n_ph

    # ---- (1) Calibration ----
    for k in range(n_ph):
        now = time.process_time()
        if now >= deadline - 2.0:
            break
        end = min(now + 4.0, deadline - 0.8)
        r_before = bestR
        h_in = best.copy()
        t_a = time.process_time()
        h_out = PHASES[k](h_in, end)
        t_b = time.process_time()
        dt = max(t_b - t_a, 1e-9)
        r_out = R_of(h_out)
        dR = r_out - r_before
        rate[k] = max(dR, 0.0) / dt
        count[k] = 1
        acc[k] = max(dR, 0.0)
        if r_out > bestR + 1e-13:
            best, bestR = h_out.copy(), r_out
        print("calib phase %d rate=%.3e dR=%.2e dt=%.2f bestR=%.7f"
              % (k + 1, rate[k], dR, dt, bestR))

    # ---- (2) Epoch loop ----
    epoch = 0
    rng = np.random.default_rng(12345)
    while time.process_time() < deadline - 1.0:
        epoch += 1
        now = time.process_time()
        if now >= deadline - 1.0:
            break
        if rng.random() < 0.2:
            k = int(rng.integers(0, n_ph))
        else:
            scores = [rate[i] * (1.0 + 0.1 * np.log1p(count[i]))
                      for i in range(n_ph)]
            k = int(np.argmax(scores))
        end = min(now + 4.0, deadline - 0.8)
        r_before = bestR
        h_in = best.copy()
        t_a = time.process_time()
        h_out = PHASES[k](h_in, end)
        t_b = time.process_time()
        dt = max(t_b - t_a, 1e-9)
        r_out = R_of(h_out)
        gain = r_out - r_before
        obs = max(gain, 0.0) / dt
        rate[k] = 0.5 * rate[k] + 0.5 * obs
        count[k] += 1
        acc[k] += max(gain, 0.0)
        if r_out > bestR + 1e-13:
            best, bestR = h_out.copy(), r_out
        if epoch % 3 == 0:
            msg = " ".join("ph%d c=%d r=%.2e acc=%.1e"
                           % (i + 1, count[i], rate[i], acc[i])
                           for i in range(n_ph))
            print("epoch %d %s bestR=%.7f" % (epoch, msg, bestR))

    # ---- (3) Final: P1 + stochastic hops repaired by P3 ----
    if time.process_time() < deadline - 0.8:
        h_out = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r_out = R_of(h_out)
        if r_out > bestR + 1e-13:
            best, bestR = h_out.copy(), r_out

    N = best.size
    for it in range(25):
        if time.process_time() >= deadline - 0.8:
            break
        frac = 0.02 + 0.13 * rng.random()
        width = max(8, int(frac * N * np.exp(0.05 * rng.standard_normal())))
        width = min(width, N)
        center = int(rng.integers(0, N))
        lo = max(0, center - width // 2)
        hi = min(N, lo + width)
        lo = max(0, hi - width)
        cand = best.copy()
        # random perturbation of the window
        noise = 1.0 + 0.3 * rng.standard_normal(hi - lo)
        cand[lo:hi] = np.clip(cand[lo:hi] * noise, 0.0, None)
        cand = _rescale(cand)
        end = min(time.process_time() + 2.0, deadline - 0.5)
        cand = P3(cand, end)
        r_c = R_of(cand)
        if r_c > bestR + 1e-13:
            best, bestR = cand.copy(), r_c
            print("hop %d R=%.7f" % (it, bestR))

    # Final polish
    if time.process_time() < deadline - 0.5:
        h_out = _lbfgs_all_pos(best, 500, deadline - 0.3, beta=0.0)
        r_out = R_of(h_out)
        if r_out > bestR + 1e-13:
            best, bestR = h_out.copy(), r_out

    # Report phase ranking
    order = np.argsort(-np.array(rate))
    print("phase ranking by rate: " +
          " ".join("P%d(%.2e)" % (i + 1, rate[i]) for i in order))
    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

