                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- discrete moves ----

def _move_shift(best, rng):
    n = best.size
    w = int(rng.uniform(0.05, 0.35) * n)
    w = max(1, min(w, n))
    lo = int(rng.integers(0, n - w + 1))
    s = int(rng.choice([-3, -2, -1, 1, 2, 3]))
    h = np.zeros_like(best)
    if s > 0:
        # block moves right: vacated [lo, lo+s) -> 0, block at [lo+s, lo+w+s)
        h[:lo] = best[:lo]
        hi_end = min(n, lo + w + s)
        h[lo + s:hi_end] = best[lo:hi_end - s]
        if hi_end < n:
            h[hi_end:] = best[hi_end:]
    else:
        d = -s
        h[:max(0, lo - d)] = best[:max(0, lo - d)]
        start_dst = max(0, lo - d)
        start_src = start_dst + d
        end = min(n, lo + w - d)
        if end > start_dst:
            h[start_dst:end] = best[start_src:start_src + (end - start_dst)]
        if lo + w < n:
            h[lo + w:] = best[lo + w:]
    return h, ("SHIFT", s, lo, w)


def _move_mirror(best, rng):
    n = best.size
    w = int(rng.uniform(0.05, 0.35) * n)
    w = max(1, min(w, n))
    lo = int(rng.integers(0, n - w + 1))
    h = best.copy()
    h[lo:lo + w] = h[lo:lo + w][::-1]
    return h, ("MIRROR", 0, lo, w)


def _move_swap(best, rng):
    n = best.size
    w = int(rng.uniform(0.05, 0.20) * n)
    w = max(1, min(w, n // 2))
    if n - 2 * w <= 0:
        return None, None
    lo = int(rng.integers(0, n - 2 * w + 1))
    lo2 = int(rng.integers(lo + w, n - w + 1))
    h = best.copy()
    h[lo:lo + w], h[lo2:lo2 + w] = best[lo2:lo2 + w].copy(), best[lo:lo + w].copy()
    return h, ("SWAP", 0, lo, w, lo2)


def _junction_free(touched, n, halo=128):
    kind = touched[0]
    lo = touched[2]; w = touched[3]
    wins = [(lo - halo, lo + halo), (lo + w - halo, lo + w + halo)]
    if kind == "SWAP":
        lo2 = touched[4]
        wins += [(lo2 - halo, lo2 + halo), (lo2 + w - halo, lo2 + w + halo)]
    idx = []
    for a, b in wins:
        a = max(0, a); b = min(n - 1, b)
        if b >= a:
            idx.append(np.arange(a, b + 1))
    if not idx:
        return np.arange(n)
    return np.unique(np.concatenate(idx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(98765)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: confirm plateau.
    if time.process_time() < deadline - 1.8:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.8)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 2: discrete hop loop.
    moves = [_move_shift, _move_mirror, _move_swap]
    hop = 0
    acc = 0
    acc_kind = {"SHIFT": 0, "MIRROR": 0, "SWAP": 0}
    while time.process_time() < deadline - 1.8:
        hop += 1
        mv = moves[int(rng.integers(0, 3))]
        try:
            h_try, touched = mv(best, rng)
        except Exception:
            h_try, touched = None, None
        if h_try is None or touched is None:
            continue
        h_try = np.clip(h_try, 0, None)
        if h_try.sum() <= 0:
            continue
        n = h_try.size
        free = _junction_free(touched, n, halo=128)
        ht = _lbfgs_block(h_try, free, 200, deadline - 1.2, beta=1e7)
        if time.process_time() < deadline - 1.2:
            pw = _peak_window(ht, pad_frac=0.15, extra=128)
            ht = _lbfgs_block(ht, pw, 100, deadline - 1.2, beta=0.0)
        if time.process_time() < deadline - 1.2:
            ht = _refine_knots(ht, 150, deadline - 1.2)
        r = R_of(ht)
        kind = touched[0]
        s = touched[1]
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            acc += 1
            acc_kind[kind] += 1
        print("hop %d move=%s s=%d R=%.7f acc=%d bestR=%.7f" %
              (hop, kind, s, r, acc, bestR))

    print("hops done: %d accepted %d (SHIFT %d MIRROR %d SWAP %d) bestR=%.7f" %
          (hop, acc, acc_kind["SHIFT"], acc_kind["MIRROR"], acc_kind["SWAP"], bestR))

    # Phase 3: final polish.
    if time.process_time() < deadline - 1.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _spectral_invert(Lf, c, mx):
    T = Lf.copy()
    T[T >= c * mx] = mx
    # smooth once with [0.25,0.5,0.25], reflect at ends
    if T.size >= 3:
        Tm = T.copy()
        Tm[1:-1] = 0.25 * T[:-2] + 0.5 * T[1:-1] + 0.25 * T[2:]
        Tm[0] = T[0]
        Tm[-1] = T[-1]
        T = Tm
    T[0] = 0.0
    T[-1] = 0.0
    G = np.fft.rfft(T)
    gmax = np.abs(G).max()
    if gmax <= 0:
        return None
    Gc = np.maximum(G, 1e-10 * gmax)
    f0 = np.fft.irfft(np.sqrt(Gc), n=T.size)
    f0 = np.clip(f0, 0, None)
    if f0.size > 1:
        f0 = f0[:-1]
    if f0.sum() <= 0:
        return None
    return _rescale(f0)


def _polish(f0, deadline):
    h = f0
    if time.process_time() < deadline - 0.5:
        h = _lbfgs_all_pos(h, 250, deadline - 0.5, beta=0.0)
    ladder = [(0.05, 64, 1e7), (0.15, 128, 1e8), (0.40, 256, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=frac, extra=extra)
        h = _lbfgs_block(h, win, 250, deadline - 0.5, beta=beta)
    if time.process_time() < deadline - 0.5:
        h = _refine_knots(h, 300, deadline - 0.5)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Spectral inversion experiment
    Lf = _knots(best)
    mx = Lf.max()
    inv_best = None
    inv_bestR = -1.0
    for c in [0.985, 0.95, 0.90]:
        if time.process_time() >= deadline - 1.5:
            break
        f0 = _spectral_invert(Lf, c, mx)
        if f0 is None:
            continue
        rraw = R_of(f0)
        print("invert c=%.3f R_raw=%.7f N=%d" % (c, rraw, f0.size))
        hp = _polish(f0, deadline - 1.0)
        rp = R_of(hp)
        print("c=%.3f R_final=%.7f" % (c, rp))
        if rp > inv_bestR:
            inv_best, inv_bestR = hp.copy(), rp

    if inv_best is not None and inv_bestR > bestR + 1e-13:
        best, bestR = inv_best.copy(), inv_bestR

    # Spend remainder on run_cycle from the better candidate.
    if time.process_time() < deadline - 1.0:
        best, bestR = run_cycle(best, bestR, deadline - 0.8)
        print("cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if inv_best is not None and inv_bestR > start_bestR - 1e-6:
        out["alternative"] = inv_best
    return out

