    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- discrete moves ----

def _move_shift(best, rng):
    n = best.size
    w = int(rng.uniform(0.05, 0.35) * n)
    w = max(1, min(w, n))
    lo = int(rng.integers(0, n - w + 1))
    s = int(rng.choice([-3, -2, -1, 1, 2, 3]))
    h = np.zeros_like(best)
    if s > 0:
        h[:lo] = best[:lo]
        hi_end = min(n, lo + w + s)
        h[lo + s:hi_end] = best[lo:hi_end - s]
        if hi_end < n:
            h[hi_end:] = best[hi_end:]
    else:
        d = -s
        h[:max(0, lo - d)] = best[:max(0, lo - d)]
        start_dst = max(0, lo - d)
        start_src = start_dst + d
        end = min(n, lo + w - d)
        if end > start_dst:
            h[start_dst:end] = best[start_src:start_src + (end - start_dst)]
        if lo + w < n:
            h[lo + w:] = best[lo + w:]
    return h, ("SHIFT", s, lo, w)


def _move_mirror(best, rng):
    n = best.size
    w = int(rng.uniform(0.05, 0.35) * n)
    w = max(1, min(w, n))
    lo = int(rng.integers(0, n - w + 1))
    h = best.copy()
    h[lo:lo + w] = h[lo:lo + w][::-1]
    return h, ("MIRROR", 0, lo, w)


def _move_swap(best, rng):
    n = best.size
    w = int(rng.uniform(0.05, 0.20) * n)
    w = max(1, min(w, n // 2))
    if n - 2 * w <= 0:
        return None, None
    lo = int(rng.integers(0, n - 2 * w + 1))
    lo2 = int(rng.integers(lo + w, n - w + 1))
    h = best.copy()
    h[lo:lo + w], h[lo2:lo2 + w] = best[lo2:lo2 + w].copy(), best[lo:lo + w].copy()
    return h, ("SWAP", 0, lo, w, lo2)


def _junction_free(touched, n, halo=128):
    kind = touched[0]
    lo = touched[2]; w = touched[3]
    wins = [(lo - halo, lo + halo), (lo + w - halo, lo + w + halo)]
    if kind == "SWAP":
        lo2 = touched[4]
        wins += [(lo2 - halo, lo2 + halo), (lo2 + w - halo, lo2 + w + halo)]
    idx = []
    for a, b in wins:
        a = max(0, a); b = min(n - 1, b)
        if b >= a:
            idx.append(np.arange(a, b + 1))
    if not idx:
        return np.arange(n)
    return np.unique(np.concatenate(idx))


def _densify(h):
    h = np.clip(h, 0, None)
    pos = h[h > 0]
    if pos.size == 0:
        return h
    eps = 1e-6 * pos.mean()
    out = h.copy()
    out[out <= 0] = eps
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(98765)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: confirm plateau with one run_cycle.
    if time.process_time() < deadline - 1.8:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.8)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 2: densify + long global polish loop.
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        hp = _densify(best)
        hp = _lbfgs_all_pos(hp, 1500, deadline - 1.2, beta=0.0)
        if time.process_time() >= deadline - 1.2:
            r = R_of(hp)
            print("iter %d R=%.7f (timeout)" % (it, r))
            if r > bestR + 1e-13:
                best, bestR = hp.copy(), r
            break
        for beta in [1e4, 1e5, 1e6, 1e7]:
            if time.process_time() >= deadline - 1.2:
                break
            hp = _lbfgs_all_pos(hp, 200, deadline - 1.2, beta=beta)
        if time.process_time() < deadline - 1.2:
            win = _peak_window(hp, tol=0.99, pad_frac=0.3, extra=256)
            hp = _lbfgs_block(hp, win, 250, deadline - 1.2, beta=1e8)
        if time.process_time() < deadline - 1.2:
            win = _peak_window(hp, tol=0.99, pad_frac=0.3, extra=256)
            hp = _lbfgs_block(hp, win, 250, deadline - 1.2, beta=0.0)
        if time.process_time() < deadline - 1.2:
            hp = _lbfgs_all_pos(hp, 300, deadline - 1.2, beta=0.0)
        r = R_of(hp)
        z = 100.0 * np.mean(hp <= 0)
        b01 = 100.0 * _band_frac(hp, 0.001)
        b1 = 100.0 * _band_frac(hp, 0.01)
        acc = r > bestR + 1e-13
        print("iter %d R=%.7f zeros=%.1f%% band01=%.2f%% band1=%.2f%% acc=%s bestR=%.7f" %
              (it, r, z, b01, b1, acc, bestR))
        if acc:
            best, bestR = hp.copy(), r

    # Phase 3: final polish.
    if time.process_time() < deadline - 1.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _edge_height(h, side, span=32):
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return 0.0
    if side == 'L':
        idx = nz[:span]
    else:
        idx = nz[-span:]
    return float(h[idx].max())


def _grow_tails(h, P, tail_ratio):
    n = h.size
    hL = _edge_height(h, 'L')
    hR = _edge_height(h, 'R')
    if hL <= 0:
        hL = h.max()
    if hR <= 0:
        hR = h.max()
    r = float(tail_ratio) ** (1.0 / P)
    new = np.zeros(n + 2 * P)
    new[P:P + n] = h
    ks = np.arange(1, P + 1)
    new[P - ks] = hL * (r ** ks)
    new[P + n - 1 + ks] = hR * (r ** ks)
    return _rescale(new)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(98765)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # (1) One run_cycle.
    if time.process_time() < deadline - 2.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 2.0)
        print("cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # (2)-(4) Tail growth rounds.
    rounds = [(6000, 4e-3), (12000, 2e-3), (24000, 1e-3)]
    for ri, (P, ratio) in enumerate(rounds):
        if time.process_time() >= deadline - 3.0:
            print("round %d skipped (time)" % (ri + 1))
            break
        n_old = best.size
        h_new = _grow_tails(best, P, ratio)
        n_new = h_new.size
        r0 = R_of(h_new)
        print("round %d P=%d grow R=%.7f N=%d" % (ri + 1, P, r0, n_new))

        # Left tail polish.
        if time.process_time() < deadline - 2.5:
            win = np.arange(0, min(n_new, P + 2000))
            h_new = _lbfgs_block(h_new, win, 150, deadline - 2.5, beta=1e7)
            h_new = _lbfgs_block(h_new, win, 150, deadline - 2.5, beta=0.0)
        # Right tail polish (mirror window).
        if time.process_time() < deadline - 2.5:
            lo = max(0, n_old + P - 2000)
            win = np.arange(lo, n_new)
            h_new = _lbfgs_block(h_new, win, 150, deadline - 2.5, beta=1e7)
            h_new = _lbfgs_block(h_new, win, 150, deadline - 2.5, beta=0.0)
        # Global polish.
        if time.process_time() < deadline - 2.5:
            h_new = _lbfgs_all_pos(h_new, 300, deadline - 2.5, beta=0.0)
        if time.process_time() < deadline - 2.5:
            pw = _peak_window(h_new, pad_frac=0.3, extra=256)
            h_new = _lbfgs_block(h_new, pw, 250, deadline - 2.5, beta=1e8)
            h_new = _lbfgs_block(h_new, pw, 250, deadline - 2.5, beta=0.0)
        if time.process_time() < deadline - 2.0:
            h_new, r_new, _ = run_cycle(h_new, R_of(h_new), deadline - 2.0)
        else:
            r_new = R_of(h_new)

        if r_new > bestR + 1e-13:
            best, bestR = h_new.copy(), r_new
            print("round %d ACCEPT R=%.7f N=%d zeros=%.1f%% band01=%.2f%%" %
                  (ri + 1, bestR, best.size,
                   100.0 * np.mean(best <= 0), 100.0 * _band_frac(best, 0.001)))
        else:
            print("round %d reject R=%.7f (best %.7f)" % (ri + 1, r_new, bestR))

    # (5) Final polish.
    if time.process_time() < deadline - 1.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

