    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta) if False else _lbfgs_block(
            best, win, maxiter=250, deadline=deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _insert_peak_step(h, deadline):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h, R_of(h)
    best = h.copy()
    bestR = R_of(best)
    n = best.size
    Lf = _knots(best)
    m = int(np.argmax(Lf))
    tries = set()
    for off in (-3, -2, -1, 0, 1, 2, 3):
        p = m + off
        if 1 <= p < n:
            tries.add(p)
    for p in sorted(tries):
        if time.process_time() >= deadline - 0.2:
            break
        val = 0.5 * (best[p - 1] + best[p]) if p < n else best[p - 1]
        cand = np.concatenate([best[:p], [val], best[p:]])
        win = np.arange(max(0, p - 8), min(cand.size, p + 9))
        cand2 = _lbfgs_block(cand, win, maxiter=80, deadline=deadline, beta=0.0)
        r = R_of(cand2)
        if r > bestR + 1e-14:
            best, bestR = cand2, r
    return best, bestR


def _downsample(h, target):
    """Merge adjacent steps to reduce N while preserving shape."""
    n = h.size
    if n <= target:
        return h
    # integrate into target bins
    edges = np.linspace(0, n, target + 1).astype(int)
    out = np.empty(target)
    for i in range(target):
        a, b = edges[i], edges[i + 1]
        if b > a:
            out[i] = h[a:b].mean()
        else:
            out[i] = 0.0
    return out


def _coarse_restart(h, deadline):
    """Downsample then polish, then re-upsample by interpolation of piecewise
    structure. This changes the effective N and can escape the fixed-N basin."""
    n = h.size
    results = []
    for target in (int(n * 0.6), int(n * 0.4), int(n * 0.75)):
        if time.process_time() >= deadline - 1.0:
            break
        if target < 64:
            continue
        hd = _downsample(h, target)
        hd = _rescale(hd)
        hd = _lbfgs_all_pos(hd, 400, deadline - 0.8, beta=0.0)
        rd = R_of(hd)
        results.append((rd, hd))
    if not results:
        return h, R_of(h)
    results.sort(key=lambda t: -t[0])
    return results[0][1], results[0][0]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: full polish of start.
    if time.process_time() < deadline - 2.0:
        best, bestR = run_cycle(best, bestR, deadline - 2.0)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 2: coarse-downsample restarts (structural N change).
    if time.process_time() < deadline - 3.0:
        hc, rc = _coarse_restart(best, deadline - 2.0)
        if rc > bestR + 1e-13:
            best, bestR = hc, rc
            best, bestR = run_cycle(best, bestR, deadline - 2.0)
        print("coarse restart R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 3: insertion near peak.
    rounds = 0
    while time.process_time() < deadline - 2.5 and rounds < 4:
        before = bestR
        ht, rt = _insert_peak_step(best, deadline - 2.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            best, bestR = run_cycle(best, bestR, deadline - 2.0)
        rounds += 1
        print("insert round %d: R=%.7f (dR=%.2e, N=%d)"
              % (rounds, bestR, bestR - before, best.size))
        if bestR - before < 1e-10:
            break

    # Phase 4: final polish.
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 600, deadline - 0.8, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-5:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_clip(h, c):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    thr = c * mx
    over = Lf > thr
    d = np.where(over, Lf - thr, 0.0)
    pen = np.sum(d * d)
    scale = 1.0 / (mx * mx + 1e-30)
    gLf = -dq / num
    gLf += 2.0 * d * scale
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + pen * scale
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_block_clip(h0, free, maxiter, deadline, c):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_clip(hh, c)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline, maxiter_scale=1.0):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, int(800 * maxiter_scale), deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, int(400 * maxiter_scale), deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        if win.size > 40000:
            continue
        ht = _lbfgs_block(best, win, maxiter=int(250 * maxiter_scale),
                          deadline=deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, int(300 * maxiter_scale), deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, int(300 * maxiter_scale), deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR, 0.0


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _argmax_loc(h):
    Lf = _knots(h)
    if Lf.size < 2:
        return 0.0
    return float(np.argmax(Lf)) / max(1, Lf.size - 1)


def _report(tag, h, R):
    print("%s R=%.7f N=%d zeros=%.1f%% band01=%.2f%% band1=%.2f%% argmax=%.3f"
          % (tag, R, h.size, 100.0 * np.mean(h <= 0),
             100.0 * _band_frac(h, 0.001), 100.0 * _band_frac(h, 0.01),
             _argmax_loc(h)))


def _hop(h, bestR, deadline, rng):
    n = h.size
    if n < 8:
        return h, bestR
    wlen = int(rng.integers(max(8, n // 20), max(16, n // 4)))
    wlen = min(wlen, n)
    lo = int(rng.integers(0, n - wlen + 1))
    hi = lo + wlen
    hp = h.copy()
    amp = rng.uniform(0.02, 0.15)
    noise = 1.0 + amp * rng.standard_normal(wlen)
    hp[lo:hi] = np.clip(hp[lo:hi] * noise, 0.0, None)
    hp = _rescale(hp)
    rp = R_of(hp)
    halo = 64
    flo = max(0, lo - halo)
    fhi = min(n, hi + halo)
    free = np.arange(flo, fhi)
    if free.size > 0 and time.process_time() < deadline - 0.5:
        ht = _lbfgs_block(hp, free, 200, deadline - 0.5, beta=1e7)
        rt = R_of(ht)
        if rt > rp:
            hp, rp = ht, rt
    if time.process_time() < deadline - 0.5:
        win = _peak_window(hp, tol=0.95, pad_frac=0.5, extra=512)
        if win.size <= 40000:
            ht = _lbfgs_block(hp, win, 250, deadline - 0.5, beta=0.0)
            rt = R_of(ht)
            if rt > rp:
                hp, rp = ht, rt
    if rp > bestR + 1e-13:
        return hp, rp
    return h, bestR


def _split_perturb(h, t):
    """Build h_try with even cells m+t*d and odd cells m-t*d."""
    n = h.size
    if n < 4:
        return h.copy()
    even = (n // 2) * 2
    S = h[:even].reshape(-1, 2)
    m = 0.5 * (S[:, 0] + S[:, 1])
    d = 0.5 * (S[:, 0] - S[:, 1])
    out = np.empty_like(h)
    out[:even:2] = m + t * d
    out[1:even:2] = m - t * d
    if even < n:
        out[even:] = h[even:]
    out = np.clip(out, 0.0, None)
    return _rescale(out)


def _polish_split(h_try, deadline):
    """Polish: global beta=0, then peak window beta=1e7, then beta=0."""
    h = h_try
    r = R_of(h)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(h, 350, deadline - 0.5, beta=0.0)
        rt = R_of(ht)
        if rt > r:
            h, r = ht, rt
    if time.process_time() < deadline - 0.5:
        win = _peak_window(h, pad_frac=0.15, extra=128)
        if win.size <= 60000:
            ht = _lbfgs_block(h, win, 250, deadline - 0.5, beta=1e7)
            rt = R_of(ht)
            if rt > r:
                h, r = ht, rt
    if time.process_time() < deadline - 0.5:
        win = _peak_window(h, pad_frac=0.15, extra=128)
        if win.size <= 60000:
            ht = _lbfgs_block(h, win, 250, deadline - 0.5, beta=0.0)
            rt = R_of(ht)
            if rt > r:
                h, r = ht, rt
    return h, r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Stage (1): one run_cycle to confirm plateau.
    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        _report("(1) cycle", best, bestR)

    # Stage (2): split-amplitude sweep.
    t_values = [0.0, 0.5, 0.75, 1.0, 1.25, 1.5, 1.75, 2.0]
    best_t = 1.0
    best_t_R = bestR
    for t in t_values:
        if time.process_time() >= deadline - 1.0:
            break
        h_try = _split_perturb(best, t)
        h_try, r_try = _polish_split(h_try, deadline - 1.0)
        dR = r_try - bestR
        acc = r_try > bestR + 1e-13
        print("(2) t=%.2f R=%.7f dR=%+.2e %s" % (t, r_try, dR, "ACCEPT" if acc else ""))
        if acc:
            best, bestR = h_try.copy(), r_try
            best_t, best_t_R = t, r_try
        elif r_try > best_t_R:
            best_t, best_t_R = t, r_try

    # One run_cycle from best.
    if time.process_time() < deadline - 1.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        _report("(2b) cycle", best, bestR)

    # Parabolic refinement of t around best_t.
    if time.process_time() < deadline - 1.0 and best_t > 0.0:
        # sample three nearby t values
        span = 0.25
        t_ref = [max(0.0, best_t - span), best_t, best_t + span]
        best_local = best_t
        best_local_R = bestR
        for t in t_ref:
            if time.process_time() >= deadline - 1.0:
                break
            h_try = _split_perturb(best, t)
            h_try, r_try = _polish_split(h_try, deadline - 1.0)
            print("(2c) t=%.3f R=%.7f dR=%+.2e" % (t, r_try, r_try - bestR))
            if r_try > bestR + 1e-13:
                best, bestR = h_try.copy(), r_try
                best_local, best_local_R = t, r_try

    # Remaining time: alternate global and peak-window sharp L-BFGS.
    rng = np.random.default_rng(12345)
    it = 0
    while time.process_time() < deadline - 0.8:
        it += 1
        if it % 2 == 1:
            ht = _lbfgs_all_pos(best, 400, deadline - 0.8, beta=0.0)
            rt = R_of(ht)
            if rt > bestR + 1e-13:
                best, bestR = ht.copy(), rt
                _report("(3) global %d" % it, best, bestR)
        else:
            win = _peak_window(best, tol=0.95, pad_frac=0.5, extra=512)
            if win.size <= 50000:
                ht = _lbfgs_block(best, win, 300, deadline - 0.8, beta=0.0)
                rt = R_of(ht)
                if rt > bestR + 1e-13:
                    best, bestR = ht.copy(), rt
                    _report("(3) peak %d" % it, best, bestR)
        if it > 100:
            break

    _report("final", best, bestR)

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _support_window(h, pad_frac=0.15, extra=64):
    """Window covering the nonzero support of h, plus padding."""
    n = h.size
    idx = np.flatnonzero(h > 0)
    if idx.size == 0:
        return np.arange(n)
    lo = idx.min()
    hi = idx.max()
    pad = max(extra, int((hi - lo) * pad_frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _split_merge_hop(best, bestR, rng, deadline):
    """Structural move: split a positive cell into two, or merge two adjacent
    positive cells into one.  Then locally re-fit the affected window."""
    n = best.size
    S = np.flatnonzero(best > 0)
    if S.size < 3:
        return best, bestR
    cand = None
    candR = bestR
    info = None
    for _ in range(48):
        if time.process_time() >= deadline - 1.0:
            break
        mode = rng.integers(0, 2)
        a = int(S[int(rng.integers(0, S.size))])
        if mode == 0:
            # split: move half of best[a] into neighbor b
            b = a + (1 if rng.random() < 0.5 else -1)
            if b < 0 or b > n - 1:
                continue
            m = best[a]
            if m <= 0:
                continue
            h_try = best.copy()
            h_try[a] = m * 0.5
            h_try[b] = h_try[b] + m * 0.5
            r = R_of(h_try)
            if r > candR + 1e-12:
                cand, candR, info = h_try, r, (a, b)
        else:
            # merge: move best[a] into nearest positive neighbor b
            pos = S[S != a]
            if pos.size == 0:
                continue
            j = int(np.argmin(np.abs(pos - a)))
            b = int(pos[j])
            if abs(a - b) > 8:
                continue
            m = best[a]
            if m <= 0:
                continue
            h_try = best.copy()
            h_try[a] = 0.0
            h_try[b] = h_try[b] + m
            r = R_of(h_try)
            if r > candR + 1e-12:
                cand, candR, info = h_try, r, (a, b)
    if cand is None:
        return best, bestR
    a, b = info
    lo = max(0, min(a, b) - 96)
    hi = min(n - 1, max(a, b) + 96)
    free = np.arange(lo, hi + 1)
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_block(cand, free, 60, deadline - 1.0, beta=0.0)
        r2 = R_of(ht)
        if r2 >= candR - 1e-13:
            cand, candR = ht, r2
    if candR > bestR + 1e-12:
        return cand, candR
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: confirm plateau.
    if time.process_time() < deadline - 3.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 3.0)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 2: structural hops (split/merge) plus translation screening.
    batches = 0
    trials = 0
    accepted = 0
    largest_dr = 0.0
    last_consolidate = time.process_time()
    deltas = np.array([-3, -2, -1, 1, 2, 3], dtype=int)
    while time.process_time() < deadline - 3.0:
        batches += 1
        # Structural split/merge attempt.
        best, bestR = _split_merge_hop(best, bestR, rng, deadline - 3.0)

        S = np.flatnonzero(best > 0)
        if S.size == 0:
            break
        n = best.size
        best_cand = None
        best_cand_R = bestR
        best_cand_info = None
        for _ in range(64):
            a = int(S[int(rng.integers(0, S.size))])
            m = best[a]
            if m <= 0:
                continue
            delta = int(deltas[int(rng.integers(0, deltas.size))])
            b = a + delta
            if b < 0 or b > n - 1:
                continue
            trials += 1
            h_try = best.copy()
            h_try[a] -= m
            h_try[b] += m
            r = R_of(h_try)
            if r > best_cand_R + 1e-12:
                best_cand = h_try
                best_cand_R = r
                best_cand_info = (a, b)
        if best_cand is not None:
            a, b = best_cand_info
            lo = max(0, min(a, b) - 64)
            hi = min(n - 1, max(a, b) + 64)
            free = np.arange(lo, hi + 1)
            if time.process_time() < deadline - 3.0:
                ht = _lbfgs_block(best_cand, free, 40, deadline - 3.0, beta=0.0)
                r2 = R_of(ht)
                if r2 >= best_cand_R - 1e-13:
                    best_cand = ht
                    best_cand_R = r2
            dr = best_cand_R - bestR
            if dr > 1e-12:
                best = best_cand
                bestR = best_cand_R
                accepted += 1
                if dr > largest_dr:
                    largest_dr = dr

        # Consolidation.
        now = time.process_time()
        if (batches % 200 == 0 or now - last_consolidate > 5.0) and now < deadline - 3.5:
            last_consolidate = now
            ht = _lbfgs_all_pos(best, 150, deadline - 3.0, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
            if time.process_time() < deadline - 3.0:
                pw = _peak_window(best, pad_frac=0.3, extra=256)
                ht = _lbfgs_block(best, pw, 100, deadline - 3.0, beta=0.0)
                r = R_of(ht)
                if r > bestR + 1e-13:
                    best, bestR = ht.copy(), r

        if batches % 20 == 0:
            print("batch %d trials %d accepted %d maxdR %.3e bestR=%.7f" %
                  (batches, trials, accepted, largest_dr, bestR))

    print("hops done: batches %d trials %d accepted %d maxdR %.3e bestR=%.7f" %
          (batches, trials, accepted, largest_dr, bestR))

    # Phase 3: final polish.
    if time.process_time() < deadline - 1.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- discrete moves ----

def _move_shift(best, rng):
    n = best.size
    w = int(rng.uniform(0.05, 0.35) * n)
    w = max(1, min(w, n))
    lo = int(rng.integers(0, n - w + 1))
    s = int(rng.choice([-3, -2, -1, 1, 2, 3]))
    h = np.zeros_like(best)
    if s > 0:
        h[:lo] = best[:lo]
        hi_end = min(n, lo + w + s)
        h[lo + s:hi_end] = best[lo:hi_end - s]
        if hi_end < n:
            h[hi_end:] = best[hi_end:]
    else:
        d = -s
        h[:max(0, lo - d)] = best[:max(0, lo - d)]
        start_dst = max(0, lo - d)
        start_src = start_dst + d
        end = min(n, lo + w - d)
        if end > start_dst:
            h[start_dst:end] = best[start_src:start_src + (end - start_dst)]
        if lo + w < n:
            h[lo + w:] = best[lo + w:]
    return h, ("SHIFT", s, lo, w)


def _move_mirror(best, rng):
    n = best.size
    w = int(rng.uniform(0.05, 0.35) * n)
    w = max(1, min(w, n))
    lo = int(rng.integers(0, n - w + 1))
    h = best.copy()
    h[lo:lo + w] = h[lo:lo + w][::-1]
    return h, ("MIRROR", 0, lo, w)


def _move_swap(best, rng):
    n = best.size
    w = int(rng.uniform(0.05, 0.20) * n)
    w = max(1, min(w, n // 2))
    if n - 2 * w <= 0:
        return None, None
    lo = int(rng.integers(0, n - 2 * w + 1))
    lo2 = int(rng.integers(lo + w, n - w + 1))
    h = best.copy()
    h[lo:lo + w], h[lo2:lo2 + w] = best[lo2:lo2 + w].copy(), best[lo:lo + w].copy()
    return h, ("SWAP", 0, lo, w, lo2)


def _junction_free(touched, n, halo=128):
    kind = touched[0]
    lo = touched[2]; w = touched[3]
    wins = [(lo - halo, lo + halo), (lo + w - halo, lo + w + halo)]
    if kind == "SWAP":
        lo2 = touched[4]
        wins += [(lo2 - halo, lo2 + halo), (lo2 + w - halo, lo2 + w + halo)]
    idx = []
    for a, b in wins:
        a = max(0, a); b = min(n - 1, b)
        if b >= a:
            idx.append(np.arange(a, b + 1))
    if not idx:
        return np.arange(n)
    return np.unique(np.concatenate(idx))


def _mirror_extend(best, r, deadline):
    """Phase-preserving mirror continuation of outer active comb pattern."""
    S = np.flatnonzero(best > 0)
    if S.size == 0:
        return best, R_of(best)
    i0 = int(S.min()); i1 = int(S.max())
    L = min(12000, i1 - i0 + 1)
    if L <= 0:
        return best, R_of(best)
    left_ext = best[i0 + 1: min(i0 + L + 1, best.size)][::-1] * r
    right_ext = best[max(i1 - L, 0): i1][::-1] * r
    h_new = np.concatenate([left_ext, best, right_ext])
    h_new = _rescale(np.clip(h_new, 0, None))
    nL = left_ext.size
    nB = best.size
    # free = two new blocks plus 512 halo around each old boundary
    halo = 512
    idxs = []
    if nL > 0:
        idxs.append(np.arange(0, nL))
        lo = max(0, nL - halo); hi = min(h_new.size - 1, nL + halo)
        idxs.append(np.arange(lo, hi + 1))
    if nB > 0:
        lo = max(0, nL + nB - halo); hi = min(h_new.size - 1, nL + nB + halo)
        idxs.append(np.arange(lo, hi + 1))
        if right_ext.size > 0:
            idxs.append(np.arange(nL + nB, h_new.size))
    free = np.unique(np.concatenate(idxs)) if idxs else np.arange(h_new.size)
    ht = _lbfgs_block(h_new, free, 700, deadline - 1.5, beta=0.0)
    return ht, R_of(ht)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(98765)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: one run_cycle
    if time.process_time() < deadline - 1.8:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.8)
        print("cycle1 R=%.7f zeros=%.1f%% N=%d" %
              (bestR, 100.0 * np.mean(best <= 0), best.size))

    # Phase 2: mirror continuation experiment
    accepted_r = None
    first_delta = None
    for r in [0.5, 1.0]:
        if time.process_time() >= deadline - 1.5:
            break
        if r == 1.0 and accepted_r is None and first_delta is not None:
            # still test r=1.0 once
            pass
        try:
            ht, rt = _mirror_extend(best, r, deadline)
        except Exception:
            continue
        if first_delta is None:
            first_delta = rt - bestR
        print("mirror r=%.2f R=%.7f dR=%+.7f N=%d" %
              (r, rt, rt - bestR, ht.size))
        if rt > bestR + 1e-13:
            best, bestR = ht.copy(), rt
            accepted_r = r
            # run_cycle after acceptance
            if time.process_time() < deadline - 1.5:
                best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
                print("post-mirror cycle R=%.7f" % bestR)

    print("mirror accepted r=%s first_dR=%s" %
          (accepted_r, first_delta))

    # Phase 3: spend remaining time on run_cycle + lbfgs_all_pos
    while time.process_time() < deadline - 1.5:
        prev = bestR
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        if time.process_time() < deadline - 0.8:
            ht = _lbfgs_all_pos(best, 400, deadline - 0.8, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if bestR <= prev + 1e-13:
            break

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_clip(h, c):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    thr = c * mx
    d = np.where(Lf > thr, Lf - thr, 0.0)
    pen = np.sum(d * d)
    scale = 1.0 / (mx * mx + 1e-30)
    gLf = -dq / num + 2.0 * d * scale
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + pen * scale
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_block_clip(h0, free, maxiter, deadline, c):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_clip(hh, c)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _plateau_clip(h, deadline, cs=(0.85, 0.90, 0.94, 0.97, 0.99)):
    best = h.copy()
    bestR = R_of(best)
    win = _peak_window(h, tol=0.98, pad_frac=0.6, extra=512)
    for c in cs:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_block_clip(best, win, 200, deadline - 0.5, c)
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(ht, win, 150, deadline - 0.5, beta=1e7)
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(ht, win, 150, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    for frac, extra, beta in [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
                              (0.40, 256, 1e8), (0.60, 512, 1e8)]:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _move_jitter(best, rng):
    """Local multiplicative jitter on a random window (small scale)."""
    n = best.size
    w = max(1, min(n, int(rng.uniform(0.01, 0.08) * n)))
    lo = int(rng.integers(0, n - w + 1))
    win = np.arange(lo, lo + w)
    h = best.copy()
    h[win] = h[win] * np.exp(0.02 * rng.standard_normal(w))
    return h, win


def _move_additive(best, rng):
    """Add a small smooth bump to a random window."""
    n = best.size
    w = max(1, min(n, int(rng.uniform(0.03, 0.20) * n)))
    lo = int(rng.integers(0, n - w + 1))
    win = np.arange(lo, lo + w)
    h = best.copy()
    t = np.linspace(0, np.pi, w)
    h[win] = h[win] + 0.01 * best.mean() * np.sin(t)
    return h, win


def _move_fill_zeros(best, rng):
    """Fill a few zero entries where the gradient is most positive."""
    _, g = _fun_grad(best)
    zeros = np.flatnonzero(best <= 0)
    if zeros.size == 0:
        return None, None
    order = np.argsort(g[zeros])[::-1]
    k = min(int(rng.choice([8, 32, 128])), zeros.size)
    pick = zeros[order[:k]]
    h = best.copy()
    h[pick] += 1e-3 * best.mean()
    return h, pick


def _halo(touched, n, halo=64):
    if touched is None or touched.size == 0:
        return np.arange(n)
    lo = max(0, int(touched.min()) - halo)
    hi = min(n - 1, int(touched.max()) + halo)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(20240608)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = np.sqrt(i + 1.0) - np.sqrt(i)
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase A: quick standard cycle first (most reliable gains).
    if time.process_time() < deadline - 2.0:
        best, bestR = run_cycle(best, bestR, deadline - 1.5)
        print("cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase B: plateau clip pass.
    if time.process_time() < deadline - 1.5:
        hc, rc = _plateau_clip(best, deadline - 1.5)
        print("clip R=%.7f" % rc)
        if rc > bestR + 1e-13:
            best, bestR = hc.copy(), rc

    # Phase C: many small, cheap local hops (these are what actually find
    # tiny improvements once the big moves stop paying off). Alternate
    # between beta>0 and beta=0 refinements.
    hop = 0; acc = 0
    moves = [_move_jitter, _move_additive, _move_fill_zeros]
    while time.process_time() < deadline - 1.6:
        hop += 1
        mv = moves[int(rng.integers(0, 3))]
        try:
            h_try, touched = mv(best, rng)
        except Exception:
            continue
        if h_try is None:
            continue
        h_try = np.clip(h_try, 0, None)
        if h_try.sum() <= 0:
            continue
        free = _halo(touched, h_try.size, 48)
        # Short sharp pass, then a plain pass (cheap, so more hops).
        ht = _lbfgs_block(h_try, free, 100, deadline - 1.0, beta=1e7)
        if time.process_time() < deadline - 1.0:
            ht = _lbfgs_block(ht, free, 100, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            acc += 1
        if hop % 20 == 0:
            print("hop %d acc %d bestR=%.7f" % (hop, acc, bestR))

    print("hops done: %d accepted %d bestR=%.7f" % (hop, acc, bestR))

    # Phase D: final polish.
    if time.process_time() < deadline - 1.0:
        best, bestR = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def _report(tag, h, R):
    print("%s R=%.7f N=%d" % (tag, R, h.size))


def _hop(h, bestR, deadline, rng):
    n = h.size
    if n < 8:
        return h, bestR
    wlen = int(rng.integers(max(8, n // 20), max(16, n // 4)))
    wlen = min(wlen, n)
    lo = int(rng.integers(0, n - wlen + 1))
    hi = lo + wlen
    hp = h.copy()
    amp = rng.uniform(0.02, 0.15)
    noise = 1.0 + amp * rng.standard_normal(wlen)
    hp[lo:hi] = np.clip(hp[lo:hi] * noise, 0.0, None)
    hp = _rescale(hp)
    rp = R_of(hp)
    halo = 64
    flo = max(0, lo - halo); fhi = min(n, hi + halo)
    free = np.arange(flo, fhi)
    if free.size > 0 and time.process_time() < deadline - 0.5:
        ht = _lbfgs_block(hp, free, 200, deadline - 0.5, beta=1e7)
        rt = R_of(ht)
        if rt > rp:
            hp, rp = ht, rt
    if time.process_time() < deadline - 0.5:
        win = _peak_window(hp, tol=0.95, pad_frac=0.5, extra=512)
        if win.size <= 40000:
            ht = _lbfgs_block(hp, win, 250, deadline - 0.5, beta=0.0)
            rt = R_of(ht)
            if rt > rp:
                hp, rp = ht, rt
    if rp > bestR + 1e-13:
        return hp, rp
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Stage (a): full polish + beta smoothing.
    if time.process_time() < deadline - 1.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 1.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 1.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 1.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    _report("(a)", best, bestR)

    # Stage (b): peak-window refinements at multiple scales.
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        if win.size > 40000:
            continue
        ht = _lbfgs_block(best, win, 250, deadline - 1.0, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    _report("(b)", best, bestR)

    # Stage (c): hop loop with acceptance.
    rng = np.random.default_rng(987654321)
    n_hops = 0
    n_accept = 0
    while time.process_time() < deadline - 1.2:
        n_hops += 1
        hnew, rnew = _hop(best, bestR, deadline - 1.2, rng)
        if rnew > bestR + 1e-13:
            best, bestR = hnew, rnew
            n_accept += 1
        if n_hops > 400:
            break
    print("(c) hops=%d accepted=%d" % (n_hops, n_accept))
    _report("(c)", best, bestR)

    # Stage (d): final broad polish.
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 500, deadline - 0.6, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        hs = _seed_zeros(best)
        ht = _lbfgs_all_pos(hs, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    _report("final", best, bestR)

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _refine_beta(h, deadline, betas=(8.0, 20.0, 50.0, 120.0)):
    best = h
    bestR = R_of(best)
    for beta in betas:
        if time.process_time() >= deadline - 0.4:
            break
        cap = min(deadline - 0.3, time.process_time() + 3.0)
        hb = _lbfgs_block(best, np.arange(best.size), 200, cap, beta=beta)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None and np.asarray(start).size > 0 and np.asarray(start).sum() > 0:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        best = _rescale(base)
        bestR = R_of(best)
    else:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Phase 1: full-vector log-space polish
    cap = min(deadline - 1.0, time.process_time() + 6.0)
    hp = _lbfgs_log(best, 400, cap)
    rp = R_of(hp)
    if rp > bestR + 1e-15:
        best, bestR = hp, rp
        print("  log polish R=%.9f" % bestR)

    # Phase 2: smooth-max (beta) full-vector polish — targets the near-ties at the peak
    while time.process_time() < deadline - 2.0:
        hb, rb = _refine_beta(best, deadline)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
            print("  beta polish R=%.9f" % bestR)
        else:
            break

    # Phase 3: peak-window block polishes (log and beta)
    for tol, pad in ((0.999, 0.5), (0.99, 0.8), (0.95, 1.0)):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, tol=tol, pad_frac=pad)
        cap = min(deadline - 0.5, time.process_time() + 4.0)
        hb = _lbfgs_block(best, free, 300, cap)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
            print("  block tol=%.3f R=%.9f" % (tol, bestR))
        cap = min(deadline - 0.5, time.process_time() + 3.0)
        hb = _lbfgs_block(best, free, 200, cap, beta=40.0)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
            print("  block-beta tol=%.3f R=%.9f" % (tol, bestR))

    # Phase 4: keep cycling beta + log polishes while budget remains
    while time.process_time() < deadline - 1.0:
        improved = False
        cap = min(deadline - 0.5, time.process_time() + 3.0)
        hp = _lbfgs_log(best, 200, cap)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp, rp
            improved = True
            print("  cycle log R=%.9f" % bestR)
        hb, rb = _refine_beta(best, min(deadline, time.process_time() + 6.0),
                              betas=(30.0, 80.0))
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
            improved = True
            print("  cycle beta R=%.9f" % bestR)
        if not improved:
            break

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    return {"best": start_best, "alternative": best}

