    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: one run_cycle.
    if time.process_time() < deadline - 2.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 2.0)
        print("cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 2: long-range discrete mass transfers.
    k = 0
    acc = 0
    min_sep_frac = 0.05
    ts = (0.25, 0.5, 1.0)
    while time.process_time() < deadline - 2.0:
        n = best.size
        S = np.flatnonzero(best > 0)
        if S.size < 2:
            break
        min_sep = max(1, int(min_sep_frac * n))
        a = b = -1
        for _ in range(32):
            a = int(S[int(rng.integers(0, S.size))])
            b = int(S[int(rng.integers(0, S.size))])
            if abs(a - b) >= min_sep:
                break
        if abs(a - b) < min_sep:
            continue
        t = float(ts[int(rng.integers(0, len(ts)))])
        h_try = best.copy()
        m = h_try[a]
        if m <= 0:
            continue
        h_try[a] = m * (1.0 - t)
        h_try[b] = h_try[b] + t * m
        lo1 = max(0, a - 256); hi1 = min(n - 1, a + 256)
        lo2 = max(0, b - 256); hi2 = min(n - 1, b + 256)
        free = np.union1d(np.arange(lo1, hi1 + 1), np.arange(lo2, hi2 + 1))
        if time.process_time() >= deadline - 1.0:
            break
        ht = _lbfgs_block(h_try, free, 150, deadline - 1.0, beta=1e7)
        if time.process_time() < deadline - 1.0:
            pw = _peak_window(ht, pad_frac=0.15, extra=128)
            ht = _lbfgs_block(ht, pw, 100, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        k += 1
        accepted = r > bestR + 1e-13
        if accepted:
            best, bestR = ht.copy(), r
            acc += 1
        print("LR %d |a-b|=%d t=%.2f R=%.7f acc=%d bestR=%.7f" %
              (k, abs(a - b), t, r, acc, bestR))

    # Phase 3: final polish.
    if time.process_time() < deadline - 1.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(np.clip(z, -60, 60))
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _downsample(h, N2):
    n = h.size
    if n <= N2:
        return h.copy()
    x = np.linspace(0.0, n, N2 + 1)
    out = np.empty(N2)
    for k in range(N2):
        a = int(np.floor(x[k])); b = int(np.ceil(x[k + 1]))
        b = max(b, a + 1)
        out[k] = h[a:b].mean()
    return out


def _upsample(h, N2):
    n = h.size
    if n >= N2:
        return h.copy()
    x = np.linspace(0.0, n, N2 + 1)
    out = np.empty(N2)
    for k in range(N2):
        a = int(np.floor(x[k])); b = int(np.ceil(x[k + 1]))
        b = max(b, a + 1)
        out[k] = h[a:b].mean()
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt = None
    altR = 0.0

    def try_improve(h, tag):
        nonlocal best, bestR, alt, altR
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("%s R=%.7f" % (tag, bestR))
            return True
        else:
            if alt is None or r > altR:
                alt, altR = h, r
            return False

    # Smooth-max polish
    for beta in (5.0e4, 2.0e5, 8.0e5, 3.0e6):
        if time.process_time() >= deadline - 3.0:
            break
        n = best.size
        thresh = 1e-13 * best.max()
        active = np.flatnonzero(best > thresh)
        if active.size == 0:
            break
        u0 = np.log(np.clip(best[active], 1e-300, None))

        def f(u, beta=beta):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = _fun_grad_sm(hh, beta)
            return val, g[active] * hh[active]

        cb = _make_cb(deadline - 0.3)
        try:
            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-30.0, 30.0)] * active.size,
                           callback=cb,
                           options={'maxiter': 300, 'maxfun': 600,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            h2 = _rescale(h2)
            h2 = _lbfgs_log(h2, 400, deadline)
            try_improve(h2, "sm%.0e" % beta)
        except (TimeoutError, Exception):
            break

    # NEW: multi-resolution refinement. Downsample, optimize coarser, upsample.
    # This escapes fine-scale local minima by smoothing, then re-resolves detail.
    for N2 in (best.size // 2, best.size // 4):
        if N2 < 512:
            continue
        if time.process_time() >= deadline - 4.0:
            break
        hc = _downsample(best, N2)
        hc = _rescale(hc)
        hc = _lbfgs_log(hc, 600, deadline)
        hc = _lbfgs_block(hc, np.arange(N2), 400, deadline)
        try_improve(hc, "coarse%d" % N2)
        # upsample back and re-polish at full resolution
        if time.process_time() < deadline - 2.0:
            hu = _upsample(hc, best.size)
            hu = _rescale(hu)
            hu = _lbfgs_log(hu, 500, deadline)
            try_improve(hu, "up%d" % N2)
            try_improve(_lbfgs_block(best, np.arange(best.size), 400, deadline),
                        "full_after_coarse")

    # Main loop: alternate exact full polish and peak-window polishes.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        if try_improve(h, "full"):
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        for frac, extra in ((0.40, 24), (0.20, 12), (0.10, 8)):
            if time.process_time() >= deadline - 1.0:
                break
            h = _window_polish_peak(best, deadline, frac, extra)
            if try_improve(h, "win%.2f" % frac):
                improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    # Final exact polish with remaining time
    if time.process_time() < deadline - 0.5:
        h = _lbfgs_block(best, np.arange(best.size), 300, deadline)
        try_improve(h, "final_exact")

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if start is not None and alt is not None and altR > 0 and bestR <= startR + 1e-12:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
import math
from scipy.optimize import minimize
from scipy.signal import fftconvolve


# ---------- core evaluation ----------

def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


# ---------- objectives ----------

def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


# ---------- L-BFGS wrappers ----------

def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


# ---------- helpers ----------

def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0,
                        tol=0.999):
    n = h.size
    lo, hi = _peak_region(h, tol=tol)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


# ---------- new idea: adaptive reparametrisation via cumulative mass ----------

def _to_cum(h):
    return np.cumsum(h)


def _from_cum(c):
    return np.clip(np.diff(np.concatenate(([0.0], c))), 0.0, None)


def _lbfgs_cum(h0, maxiter, deadline, beta=0.0):
    """Optimise in the cumulative-mass coordinate, which behaves like a
    monotone reparameterisation: the optimizer can move mass between
    steps without the harsh positivity boundary of the raw heights."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    s = h.sum()
    if s <= 0:
        return h0
    n = h.size
    c0 = np.cumsum(h)
    # normalise so the last cumulative value is 1; unconstrained interior
    c0 = c0 / c0[-1]
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(c):
        cc = c.copy()
        # enforce monotonicity by cumulative max plus small epsilon
        cc = np.maximum.accumulate(np.clip(cc, 0.0, 1.0))
        hh = np.diff(np.concatenate(([0.0], cc)))
        hh = np.clip(hh, 0.0, None)
        if hh.sum() <= 0:
            return 1e18, np.zeros(n)
        val, g = fg(hh)
        # chain rule: d val / d c_k = sum_{j>k} g_j  (since h_j = c_j - c_{j-1})
        gc = np.cumsum(g[::-1])[::-1]
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, 1.0)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    cc = np.maximum.accumulate(np.clip(res.x, 0.0, 1.0))
    hh = np.diff(np.concatenate(([0.0], cc)))
    return _rescale(np.clip(hh, 0.0, None))


# ---------- main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    cur = start_best.copy()
    curR = start_bestR

    # ---- Phase 1: multi-tolerance peak-window polishing ----
    tol_schedule = (0.999, 0.99, 0.97, 0.95, 0.90, 0.80, 0.60, 0.40)
    for tol in tol_schedule:
        if time.process_time() >= deadline - 4.0:
            break
        improved = False
        for frac, extra in ((0.05, 32), (0.15, 64), (0.30, 128)):
            if time.process_time() >= deadline - 4.0:
                break
            hw = _window_polish_peak(cur, deadline, frac, extra,
                                     maxiter=200, tol=tol)
            rw = R_of(hw)
            if rw > curR + 1e-13:
                cur, curR = hw, rw
                improved = True
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
        if time.process_time() < deadline - 4.0:
            hf = _lbfgs_log(cur, 250, deadline)
            rf = R_of(hf)
            if rf > curR + 1e-13:
                cur, curR = hf, rf
                improved = True
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
        print("  tol=%.3f R=%.7f near=%.4f" %
              (tol, curR, _frac_near_max(cur)))
        if not improved and tol < 0.5:
            break

    # ---- Phase 2: high-beta ladder ----
    for beta in (1e6, 1e7, 1e8, 1e9):
        if time.process_time() >= deadline - 4.0:
            break
        hb = _window_polish_peak(cur, deadline, 0.15, 64,
                                 maxiter=200, beta=beta, tol=0.95)
        rb = R_of(hb)
        hs = _window_polish_peak(hb, deadline, 0.15, 64,
                                 maxiter=150, tol=0.95)
        rs = R_of(hs)
        cand, rc = (hs, rs) if rs > rb else (hb, rb)
        if rc > curR + 1e-13:
            cur, curR = cand, rc
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
        print("  beta=%.0e R=%.7f near=%.4f" %
              (beta, curR, _frac_near_max(cur)))

    # ---- Phase 3: NEW cumulative-coordinate polish ----
    # This is the substantial new idea: reparametrise heights as
    # cumulative mass with a monotone constraint, which lets L-BFGS
    # redistribute mass between the plateau and the tails without
    # hitting the h>=0 boundary as hard. Run it from best and from cur.
    for src, rsrc in ((best, bestR), (cur, curR)):
        if time.process_time() >= deadline - 6.0:
            break
        hc = _lbfgs_cum(src, 400, deadline)
        rcv = R_of(hc)
        print("  cum-coord R=%.7f (from %.7f)" % (rcv, rsrc))
        if rcv > bestR + 1e-13:
            best, bestR = hc.copy(), rcv
            cur, curR = hc.copy(), rcv

    # Then a normal-coordinate polish on the result
    if time.process_time() < deadline - 4.0:
        hf = _lbfgs_log(best, 400, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf
            cur, curR = hf, rf
            print("  post-cum polish R=%.7f" % bestR)

    # ---- Phase 4: beta-sharpened cumulative polish, if time allows ----
    if time.process_time() < deadline - 6.0:
        for beta in (1e7, 1e9):
            if time.process_time() >= deadline - 4.0:
                break
            hc = _lbfgs_cum(best, 250, deadline, beta=beta)
            rcv = R_of(hc)
            hs = _window_polish_peak(hc, deadline, 0.15, 64,
                                     maxiter=150, tol=0.95)
            rs = R_of(hs)
            cand, rc = (hs, rs) if rs > rcv else (hc, rcv)
            if rc > bestR + 1e-13:
                best, bestR = cand, rc
                cur, curR = cand, rc
            print("  cum-beta=%.0e R=%.7f" % (beta, bestR))

    # ---- Phase 5: final normal-coordinate polish ----
    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 400, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _polish_windows(h, S, deadline, beta, it1, it2):
    n = h.size
    if S.size > 0:
        lo = max(0, int(S.min()) - 128)
        hi = min(n - 1, int(S.max()) + 128)
        free = np.arange(lo, hi + 1)
        h = _lbfgs_block(h, free, it1, deadline, beta=beta)
    h = _lbfgs_all_pos(h, it2, deadline, beta=0.0)
    return h


# ---------------- sub-cell phase machinery ----------------

def _segment(h):
    """Split positive cells into runs -> list of (start, end) inclusive."""
    pos = h > 0
    runs = []
    n = h.size
    i = 0
    while i < n:
        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _spikes_from_runs(h, runs):
    """Each run -> (center, width, height)."""
    spikes = []
    for (a, b) in runs:
        length = b - a + 1
        mass = h[a:b + 1].sum()
        center = a + (length - 1) / 2.0
        spikes.append([center, float(length), mass / max(length, 1)])
    return spikes


def _rasterize(spikes, N):
    """Rasterize spikes (center, width, height) onto N cells by box overlap."""
    out = np.zeros(N)
    for (c, w, ht) in spikes:
        if w <= 0 or ht <= 0:
            continue
        lo = c - w / 2.0
        hi = c + w / 2.0
        i0 = int(np.floor(lo))
        i1 = int(np.ceil(hi))
        i0 = max(i0, 0)
        i1 = min(i1, N)
        for i in range(i0, i1):
            ov = min(hi, i + 1) - max(lo, i)
            if ov > 0:
                out[i] += ht * ov
    return out


def _phase_search(best, bestR, deadline, rng, log):
    """Pattern search over sub-cell offsets and widths of spikes."""
    N = best.size
    runs = _segment(best)
    if len(runs) == 0:
        return best, bestR
    spikes = _spikes_from_runs(best, runs)
    # store offsets (delta) and width multipliers per spike
    deltas = np.zeros(len(spikes))
    wmults = np.ones(len(spikes))

    def build(deltas, wmults):
        sp = []
        for k, (c, w, ht) in enumerate(spikes):
            sp.append([c + deltas[k], w * wmults[k], ht])
        return _rasterize(sp, N)

    def evaluate(deltas, wmults):
        h = build(deltas, wmults)
        if h.sum() <= 0:
            return -1.0, h
        # local refit around perturbed region
        S = np.flatnonzero(h > 0)
        if S.size > 0:
            lo = max(0, int(S.min()) - 64)
            hi = min(N - 1, int(S.max()) + 64)
            free = np.arange(lo, hi + 1)
            h2 = _lbfgs_block(h, free, 120, deadline, beta=0.0)
            h2 = _lbfgs_block(h2, free, 80, deadline, beta=1e7)
            r = R_of(h2)
            if r > R_of(h):
                h = h2
        return R_of(h), h

    curR, curH = evaluate(deltas, wmults)
    log.append(("phase init", curR))
    if curR > bestR:
        best, bestR = curH.copy(), curR

    steps = [0.25, 0.125, 0.0625, 0.03]
    for step in steps:
        if time.process_time() >= deadline - 1.0:
            break
        improved = True
        passes = 0
        while improved and passes < 3:
            improved = False
            passes += 1
            for k in range(len(spikes)):
                if time.process_time() >= deadline - 1.0:
                    break
                # try delta +/-
                for sgn in (+1, -1):
                    nd = deltas.copy()
                    nd[k] = np.clip(nd[k] + sgn * step, -0.5, 0.5)
                    r, h = evaluate(nd, wmults)
                    if r > curR + 1e-13:
                        curR, curH = r, h
                        deltas = nd
                        improved = True
                        if r > bestR:
                            best, bestR = h.copy(), r
                        break
                # try width mult +/-
                for sgn in (+1, -1):
                    nw = wmults.copy()
                    nw[k] = np.clip(nw[k] + sgn * step, 0.6, 1.6)
                    r, h = evaluate(deltas, nw)
                    if r > curR + 1e-13:
                        curR, curH = r, h
                        wmults = nw
                        improved = True
                        if r > bestR:
                            best, bestR = h.copy(), r
                        break
        log.append(("phase step %.4f" % step, curR))

    # (d) try splitting the largest spike
    if time.process_time() < deadline - 2.0 and len(spikes) > 0:
        masses = [s[2] * s[1] for s in spikes]
        k = int(np.argmax(masses))
        c, w, ht = spikes[k]
        # split into two sub-cell spikes
        new_spikes = [list(s) for s in spikes]
        half = w / 2.0
        new_spikes[k] = [c - w / 4.0, half, ht]
        new_spikes.insert(k + 1, [c + w / 4.0, half, ht])
        nd = np.zeros(len(new_spikes))
        nw = np.ones(len(new_spikes))
        sp = []
        for j, (cc, ww, hh) in enumerate(new_spikes):
            sp.append([cc + nd[j], ww * nw[j], hh])
        hsplit = _rasterize(sp, N)
        S = np.flatnonzero(hsplit > 0)
        if S.size > 0:
            lo = max(0, int(S.min()) - 64)
            hi = min(N - 1, int(S.max()) + 64)
            free = np.arange(lo, hi + 1)
            hsplit = _lbfgs_block(hsplit, free, 150, deadline, beta=0.0)
            hsplit = _lbfgs_block(hsplit, free, 100, deadline, beta=1e7)
        rs = R_of(hsplit)
        log.append(("split", rs))
        if rs > bestR + 1e-13:
            best, bestR = hsplit.copy(), rs

    # report delta histogram
    nz = np.sum(np.abs(deltas) > 1e-6)
    log.append(("deltas nonzero", float(nz) / max(1, len(deltas))))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)
    log = []

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # (1) One run_cycle to confirm plateau.
    if time.process_time() < deadline - 3.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 3.0)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # (2) Sub-cell phase search.
    if time.process_time() < deadline - 2.0:
        r_before = bestR
        best, bestR = _phase_search(best, bestR, deadline - 2.0, rng, log)
        print("phase dR=%.3e -> R=%.7f" % (bestR - r_before, bestR))
        for name, val in log:
            print("  %s: %.7f" % (name, val))

    # (3) Population of multiplicatively perturbed spike-height vectors.
    K = 3
    members = []
    S_all = np.flatnonzero(best > 0)
    for k in range(K):
        if time.process_time() >= deadline - 3.0:
            break
        h_k = best.copy()
        if S_all.size > 0:
            m = max(1, int(0.08 * S_all.size))
            S = rng.choice(S_all, size=m, replace=False)
            h_k[S] *= np.exp(rng.normal(0.0, 0.35, S.size))
            h_k = np.clip(h_k, 0.0, None)
        else:
            S = np.array([], dtype=int)
        r_pre = R_of(h_k)
        h_k = _polish_windows(h_k, S, deadline - 3.0, 1e7, 80, 120)
        r_post = R_of(h_k)
        members.append((r_post, h_k))
        print("member %d pre %.7f post %.7f" % (k, r_pre, r_post))

    if members:
        members.sort(key=lambda t: -t[0])
        if members[0][0] > bestR + 1e-13:
            best, bestR = members[0][1].copy(), members[0][0]

    # (4) Final run_cycle and polish.
    if time.process_time() < deadline - 1.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _envelope_trial(best, bestR, deadline, rng):
    """Far-field smooth multiplicative envelope over a wide window."""
    n = best.size
    L = float(n)
    sigmas = [0.3, 0.6, 1.0]
    sigma = sigmas[int(rng.integers(0, 3))]
    W = rng.uniform(0.3, 0.7) * L
    W = max(8.0, min(W, L))
    l = rng.uniform(0.0, max(0.0, L - W))
    lo = int(round(l))
    hi = int(round(l + W))
    lo = max(0, min(lo, n - 1))
    hi = max(lo + 1, min(hi, n))
    x = np.arange(lo, hi, dtype=float)
    B = np.zeros_like(x)
    for _ in range(3):
        k = rng.integers(1, 5)
        a = rng.normal(0.0, sigma)
        phi = rng.uniform(0.0, 1.0)
        B += a * np.cos(2.0 * np.pi * (k * x / L + phi))
    B = np.clip(B, -6.0, 6.0)
    h_try = best.copy()
    h_try[lo:hi] = h_try[lo:hi] * np.exp(B)
    h_try = np.clip(h_try, 0.0, None)
    if h_try.sum() <= 0:
        return best, bestR, None
    # mass renormalization
    h_try *= best.sum() / h_try.sum()
    h_try = _rescale(h_try)
    r_pre = R_of(h_try)
    return h_try, r_pre, (sigma, W, lo, hi)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # (1) One run_cycle to confirm plateau.
    if time.process_time() < deadline - 3.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 3.0)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # (2) Far-field envelope trials replacing the hop loop.
    n = best.size
    n_trials = 0
    n_promoted = 0
    accepted = []
    while time.process_time() < deadline - 4.0:
        h_try, r_pre, params = _envelope_trial(best, bestR, deadline, rng)
        if params is None:
            continue
        n_trials += 1
        sigma, W, lo, hi = params
        r_post = r_pre
        if r_pre >= bestR - 2e-3:
            n_promoted += 1
            free = np.arange(max(0, lo - 128), min(n, hi + 128))
            h_p = _lbfgs_block(h_try, free, 80, deadline - 3.0, beta=1e7)
            h_p = _lbfgs_block(h_p, free, 80, deadline - 3.0, beta=0.0)
            if time.process_time() < deadline - 3.0:
                h_p = _lbfgs_all_pos(h_p, 150, deadline - 3.0, beta=0.0)
            r_post = R_of(h_p)
            if r_post > bestR + 1e-13:
                best, bestR = h_p.copy(), r_post
                accepted.append((sigma, W, r_post))
                print("ACCEPT trial %d sigma=%.2f W=%.3f pre=%.7f post=%.7f newR=%.7f"
                      % (n_trials, sigma, W, r_pre, r_post, bestR))
            else:
                print("trial %d sigma=%.2f W=%.3f pre=%.7f post=%.7f (no gain)"
                      % (n_trials, sigma, W, r_pre, r_post))
        if n_trials % 10 == 0:
            print("  ... %d trials, %d promoted, %d accepted, R=%.7f"
                  % (n_trials, n_promoted, len(accepted), bestR))

    print("envelope phase: %d trials, %d promoted, %d accepted" %
          (n_trials, n_promoted, len(accepted)))
    if accepted:
        print("accepted (sigma, W): " +
              ", ".join("(%.2f,%.3f)" % (s, w) for s, w, _ in accepted))

    # (3) Final run_cycle and polish.
    if time.process_time() < deadline - 1.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

