    # Main idea: coordinate-block ascent on the peak band. The peak (flat top
    # of f*f) is what controls R; locally flattening / refitting the cells that
    # feed the peak gives real gains that full-vector LBFGS can't make.
    # We sweep progressively wider windows around the peak and do many
    # alternating beta-polish passes; the wider plateau of f*f is what we want.

    # Phase A: many alternating polish passes on the whole vector (cheap since
    # start is already near a local optimum).
    if time.process_time() < deadline - 2.0:
        best, bestR = _polish(best, min(deadline - 2.0, time.process_time() + budget_seconds * 0.15), 4)
        print("A R=%.7f" % bestR)

    # Phase B: expanding-peak local block ascent. Sweep pad_frac from small
    # to large, doing alternating beta polish on each window. This is the
    # "shape of the plateau" search.
    ladder = [(0.02, 32), (0.05, 64), (0.10, 128), (0.20, 256),
              (0.35, 512), (0.55, 768), (0.80, 1024)]
    for (pf, extra) in ladder:
        if time.process_time() >= deadline - 1.5:
            break
        win = _peak_window(best, pad_frac=pf, extra=extra)
        cur = best
        curR = bestR
        for beta in (0.0, 1e7, 1e8, 0.0):
            if time.process_time() >= deadline - 1.5:
                break
            ht = _lbfgs_block(cur, win, 200, deadline - 1.5, beta=beta)
            rr = R_of(ht)
            if rr > curR + 1e-13:
                cur, curR = ht, rr
        if curR > bestR + 1e-13:
            best, bestR = cur, curR
        print("B pf=%.2f R=%.7f" % (pf, bestR))

    # Phase C: full-vector alternating polish again, since Phase B changed
    # the peak shape and full refinement can lock in.
    if time.process_time() < deadline - 1.0:
        ht, rr = _polish(best, deadline - 1.0, 6)
        if rr > bestR + 1e-13:
            best, bestR = ht, rr
        print("C R=%.7f" % bestR)

    # Phase D: if time remains, one more expanding sweep centered on the
    # (possibly moved) peak, but starting from a smaller pad and going wider.
    if time.process_time() < deadline - 1.0:
        for (pf, extra) in [(0.15, 192), (0.40, 640), (0.70, 900)]:
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(best, pad_frac=pf, extra=extra)
            ht = _lbfgs_block(best, win, 200, deadline - 1.0, beta=1e7)
            rr = R_of(ht)
            if rr > bestR + 1e-13:
                best, bestR = ht, rr
        print("D R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def run_cycle(best, bestR, deadline):
    """Aggressive multi-scale polish: full, then peak-window blocks at growing widths."""
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 1000, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    # peak-focused window passes at increasing widths with beta smoothing
    ladder = [(0.05, 64, 1e7), (0.10, 96, 1e8), (0.20, 160, 1e8),
              (0.35, 320, 1e8), (0.55, 640, 1e8), (0.80, 1024, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=300, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _spike_perturb(h, rng, frac=0.10, sigma=0.30):
    """Multiplicative perturbation on a random subset of positive steps."""
    out = h.copy()
    S = np.flatnonzero(h > 0)
    if S.size == 0:
        return out
    m = max(1, int(frac * S.size))
    S = rng.choice(S, size=m, replace=False)
    out[S] *= np.exp(rng.normal(0.0, sigma, S.size))
    return np.clip(out, 0.0, None)


def _smooth_perturb(h, rng, width=8, sigma=0.10):
    """Smooth (low-frequency) multiplicative perturbation via boxcar noise."""
    n = h.size
    k = max(1, n // width)
    noise = rng.normal(0.0, sigma, k)
    # upsample by repeat
    up = np.repeat(noise, width)[:n]
    if up.size < n:
        up = np.concatenate([up, np.zeros(n - up.size)])
    return np.clip(h * np.exp(up), 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(int(t0 * 1000) & 0xffffffff)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # (1) First polish cycle on the given start.
    if time.process_time() < deadline - 4.0:
        best, bestR = run_cycle(best, bestR, deadline - 4.0)
        print("cycle1 R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # (2) Population of perturbed variants; polish each and keep the best.
    K = 5
    members = []
    for k in range(K):
        if time.process_time() >= deadline - 3.0:
            break
        if k % 2 == 0:
            h_k = _spike_perturb(best, rng, frac=0.10, sigma=0.30)
        else:
            h_k = _smooth_perturb(best, rng, width=max(4, best.size // 512),
                                  sigma=0.08)
        r_pre = R_of(h_k)
        h_k = _lbfgs_all_pos(h_k, 250, deadline - 3.0, beta=0.0)
        r_post = R_of(h_k)
        members.append((r_post, h_k))
        print("member %d pre %.7f post %.7f" % (k, r_pre, r_post))

    if members:
        members.sort(key=lambda t: -t[0])
        if members[0][0] > bestR + 1e-13:
            best, bestR = members[0][1].copy(), members[0][0]

    # (3) Crossover between top members, then polish the affected window.
    if len(members) >= 2 and time.process_time() < deadline - 3.0:
        A = members[0][1]; B = members[1][1]
        n = best.size
        lo = int(rng.uniform(0.25, 0.65) * n)
        hi = min(n, lo + int(rng.uniform(0.2, 0.4) * n))
        child = A.copy()
        child[lo:hi] = B[lo:hi]
        free = np.arange(max(0, lo - 512), min(n, hi + 512))
        child = _lbfgs_block(child, free, 200, deadline - 3.0, beta=1e7)
        child = _lbfgs_all_pos(child, 250, deadline - 3.0, beta=0.0)
        rc = R_of(child)
        print("crossover R=%.7f (parents %.7f, %.7f)" %
              (rc, members[0][0], members[1][0]))
        if rc > bestR + 1e-13:
            best, bestR = child.copy(), rc

    # (4) Repeated polish cycles until deadline.
    cyc = 0
    while time.process_time() < deadline - 1.5:
        cyc += 1
        best, bestR = run_cycle(best, bestR, deadline - 1.0)
        print("cycle %d R=%.7f" % (cyc + 1, bestR))

    # (5) Final full polish.
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

