    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_band(h, mu, tol):
    """Quadratic penalty pushing near-tied knots toward frozen max M."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad(h)
    m = int(np.argmax(Lf))
    band = Lf >= tol * M
    nb = int(band.sum())
    if nb == 0:
        return _fun_grad(h)
    diff = M - Lf[band]
    pen = mu * np.mean(diff * diff) / (M * M)
    # d/dq_j of pen: -2*mu*(M-Lf_j)/(nb*M^2) for j in band
    dq_band = np.zeros_like(Lf)
    dq_band[band] = -2.0 * mu * diff / (nb * M * M)
    # total dq used in gradient: dq_total = dq + dq_band (since val has -dq/num)
    gLf = -(dq + dq_band) / num
    gLf[m] += 1.0 / M
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M) + pen
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, band=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if band is not None:
        tol, mu = band
        fg = (lambda hh: _fun_grad_band(hh, mu, tol))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, band=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if band is not None:
        tol, mu = band
        fg = (lambda hh: _fun_grad_band(hh, mu, tol))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _band_counts(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, 0, Lf.size
    return (int(np.sum(Lf >= 0.999 * mx)),
            int(np.sum(Lf >= 0.99 * mx)),
            Lf.size)


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _runs(h):
    pos = h > 0
    runs = []
    n = h.size
    i = 0
    while i < n:
        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _repair(h, deadline):
    S = np.flatnonzero(h > 0)
    if S.size == 0:
        return h
    lo = max(0, int(S.min()) - 96)
    hi = min(h.size - 1, int(S.max()) + 96)
    free = np.arange(lo, hi + 1)
    h = _lbfgs_block(h, free, 100, deadline, beta=0.0)
    h = _lbfgs_block(h, free, 80, deadline, beta=1e7)
    return _rescale(h)


def _draw_move(h, rng):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return None, "none"
    runs = _runs(h)
    mode = rng.integers(0, 5)
    if mode == 0:  # split
        w = h[pos]
        a = int(rng.choice(pos, p=w / w.sum()))
        side = 1 if rng.random() < 0.5 else -1
        b = a + side
        if b < 0 or b >= n:
            return None, "split"
        h2 = h.copy()
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
        return h2, "split"
    elif mode == 1:  # merge
        a = int(rng.choice(pos))
        left = pos[pos < a]
        right = pos[pos > a]
        cands = []
        if left.size:
            cands.append(int(left[-1]))
        if right.size:
            cands.append(int(right[0]))
        if not cands:
            return None, "merge"
        b = cands[int(rng.integers(0, len(cands)))]
        h2 = h.copy()
        h2[b] += h2[a]
        h2[a] = 0.0
        return h2, "merge"
    elif mode == 2:  # birth
        cands = []
        for (i0, i1) in runs:
            if i0 - 1 >= 0 and h[i0 - 1] <= 0:
                cands.append(i0 - 1)
            if i1 + 1 < n and h[i1 + 1] <= 0:
                cands.append(i1 + 1)
        if not cands:
            return None, "birth"
        a = int(cands[int(rng.integers(0, len(cands)))])
        h2 = h.copy()
        h2[a] = h[pos].mean() * 0.5
        return h2, "birth"
    elif mode == 3:  # death
        short = [(i0, i1) for (i0, i1) in runs if (i1 - i0 + 1) <= 4]
        if not short:
            return None, "death"
        i0, i1 = short[int(rng.integers(0, len(short)))]
        seg = h[i0:i1 + 1]
        a = i0 + int(np.argmin(seg))
        h2 = h.copy()
        h2[a] = 0.0
        return h2, "death"
    else:  # transfer
        a = int(rng.choice(pos))
        side = 1 if rng.random() < 0.5 else -1
        b = a + side
        if b < 0 or b >= n:
            return None, "transfer"
        h2 = h.copy()
        mv = h2[a] * 0.5
        h2[a] -= mv
        h2[b] += mv
        return h2, "transfer"


def _hop_loop(best, bestR, deadline, rng):
    modes = ["split", "merge", "birth", "death", "transfer"]
    acc = {m: 0 for m in modes}
    best_dR = {m: 0.0 for m in modes}
    n_acc = 0
    n_rej = 0
    trials = 0
    while time.process_time() < deadline - 0.5:
        trials += 1
        h2, mode = _draw_move(best, rng)
        if h2 is None:
            n_rej += 1
            continue
        h2 = _repair(h2, deadline)
        r = R_of(h2)
        if r > bestR + 1e-13:
            dR = r - bestR
            best, bestR = h2.copy(), r
            acc[mode] = acc.get(mode, 0) + 1
            if dR > best_dR.get(mode, 0.0):
                best_dR[mode] = dR
            n_acc += 1
            n_rej = 0
        else:
            n_rej += 1
        if n_acc >= 15 or n_rej >= 40:
            best, bestR = _mini_cycle(best, bestR, deadline)
            n_acc = 0
            n_rej = 0
    return best, bestR, acc, best_dR, trials


def _band_ladder(best, bestR, deadline):
    """The D7 experiment: quadratic penalty on near-tied knots."""
    ladder = [(0.999, 1.0), (0.999, 10.0), (0.995, 10.0), (0.99, 100.0)]
    for tol, mu in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        b0, b1, tot = _band_counts(best)
        ht = _lbfgs_all_pos(best, 250, deadline - 0.5, band=(tol, mu))
        r = R_of(ht)
        b0n, b1n, _ = _band_counts(ht)
        improved = r > bestR + 1e-13
        if improved:
            best, bestR = ht.copy(), r
        print("  band tol=%.3f mu=%.1f: R=%.7f dR=%.2e band01 %d->%d band1 %d->%d %s"
              % (tol, mu, r, r - bestR, b0, b0n, b1, b1n,
                 "ACCEPT" if improved else "reject"))
    # beta=1e7 pass
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    # sharp beta=0 pass
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # D7 experiment first: band penalty ladder on the start
    if time.process_time() < deadline - 3.0:
        r_before = bestR
        best, bestR = _band_ladder(best, bestR, deadline - 3.0)
        print("band ladder dR=%.3e -> R=%.7f" % (bestR - r_before, bestR))

    if time.process_time() < deadline - 3.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 3.0)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    if time.process_time() < deadline - 2.0:
        r_before = bestR
        best, bestR, acc, best_dR, trials = _hop_loop(best, bestR, deadline - 2.0, rng)
        print("hop dR=%.3e -> R=%.7f trials=%d" % (bestR - r_before, bestR, trials))
        for m in ["split", "merge", "birth", "death", "transfer"]:
            print("  %s: acc=%d bestdR=%.3e" % (m, acc.get(m, 0), best_dR.get(m, 0.0)))

    if time.process_time() < deadline - 1.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _runs(h):
    pos = h > 0
    runs = []
    n = h.size
    i = 0
    while i < n:
        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _repair(h, deadline):
    S = np.flatnonzero(h > 0)
    if S.size == 0:
        return h
    lo = max(0, int(S.min()) - 96)
    hi = min(h.size - 1, int(S.max()) + 96)
    free = np.arange(lo, hi + 1)
    h = _lbfgs_block(h, free, 100, deadline, beta=0.0)
    h = _lbfgs_block(h, free, 80, deadline, beta=1e7)
    return _rescale(h)


def _draw_move(h, rng):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return None, "none"
    runs = _runs(h)
    mode = rng.integers(0, 5)
    if mode == 0:
        w = h[pos]
        a = int(rng.choice(pos, p=w / w.sum()))
        side = 1 if rng.random() < 0.5 else -1
        b = a + side
        if b < 0 or b >= n:
            return None, "split"
        h2 = h.copy()
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
        return h2, "split"
    elif mode == 1:
        a = int(rng.choice(pos))
        left = pos[pos < a]
        right = pos[pos > a]
        cands = []
        if left.size:
            cands.append(int(left[-1]))
        if right.size:
            cands.append(int(right[0]))
        if not cands:
            return None, "merge"
        b = cands[int(rng.integers(0, len(cands)))]
        h2 = h.copy()
        h2[b] += h2[a]
        h2[a] = 0.0
        return h2, "merge"
    elif mode == 2:
        cands = []
        for (i0, i1) in runs:
            if i0 - 1 >= 0 and h[i0 - 1] <= 0:
                cands.append(i0 - 1)
            if i1 + 1 < n and h[i1 + 1] <= 0:
                cands.append(i1 + 1)
        if not cands:
            return None, "birth"
        a = int(cands[int(rng.integers(0, len(cands)))])
        h2 = h.copy()
        h2[a] = h[pos].mean() * 0.5
        return h2, "birth"
    elif mode == 3:
        short = [(i0, i1) for (i0, i1) in runs if (i1 - i0 + 1) <= 4]
        if not short:
            return None, "death"
        i0, i1 = short[int(rng.integers(0, len(short)))]
        seg = h[i0:i1 + 1]
        a = i0 + int(np.argmin(seg))
        h2 = h.copy()
        h2[a] = 0.0
        return h2, "death"
    else:
        a = int(rng.choice(pos))
        side = 1 if rng.random() < 0.5 else -1
        b = a + side
        if b < 0 or b >= n:
            return None, "transfer"
        h2 = h.copy()
        mv = h2[a] * 0.5
        h2[a] -= mv
        h2[b] += mv
        return h2, "transfer"


def _lognormal_hit(h, rng):
    """Multiplicative lognormal hit on a random width 1-3% window."""
    n = h.size
    wfrac = rng.uniform(0.01, 0.03)
    w = max(2, int(n * wfrac))
    if w >= n:
        w = n - 1
    lo = int(rng.integers(0, n - w))
    hi = lo + w
    h2 = h.copy()
    sig = 0.3
    fac = np.exp(rng.normal(0.0, sig, size=w))
    h2[lo:hi] = h2[lo:hi] * fac
    return h2, (lo, hi)


def _anneal_loop(state, stateR, best, bestR, deadline, t_start, t_end, rng):
    """Metropolis on log R with geometric cooling. Returns best, bestR."""
    T0 = 5e-6
    Tmin = 2e-7
    total = max(1e-9, t_end - t_start)
    n_moves = 0
    n_acc = 0
    # decade accept tracking: key = floor(log10(T))
    dec_acc = {}
    dec_tot = {}
    best_traj = []
    while time.process_time() < t_end - 0.5:
        now = time.process_time()
        frac = min(1.0, max(0.0, (now - t_start) / total))
        T = T0 * (Tmin / T0) ** frac
        n_moves += 1
        use_hit = rng.random() < 0.5
        if use_hit:
            h2, win = _lognormal_hit(state, rng)
            lo = max(0, win[0] - 64)
            hi = min(state.size - 1, win[1] + 64)
            free = np.arange(lo, hi + 1)
            h2 = _lbfgs_block(h2, free, 60, t_end, beta=0.0)
            mode = "hit"
        else:
            h2, mode = _draw_move(state, rng)
            if h2 is None:
                continue
            h2 = _repair(h2, t_end)
        r2 = R_of(h2)
        dR = r2 - stateR
        dec = int(np.floor(np.log10(max(T, 1e-12))))
        dec_tot[dec] = dec_tot.get(dec, 0) + 1
        accept = False
        if dR >= 0:
            accept = True
        else:
            p = np.exp(dR / T)
            if rng.random() < p:
                accept = True
        if accept:
            state = h2
            stateR = r2
            n_acc += 1
            dec_acc[dec] = dec_acc.get(dec, 0) + 1
            if stateR > bestR + 1e-13:
                best = state.copy()
                bestR = stateR
                best_traj.append((now - t_start, bestR))
        if n_moves % 25 == 0:
            st2, r2b = _mini_cycle(state, stateR, t_end)
            if r2b > stateR + 1e-13:
                state, stateR = st2, r2b
                if stateR > bestR + 1e-13:
                    best = state.copy()
                    bestR = stateR
                    best_traj.append((now - t_start, bestR))
    print("anneal moves=%d acc=%d rate=%.3f" %
          (n_moves, n_acc, n_acc / max(1, n_moves)))
    for dec in sorted(dec_tot.keys()):
        print("  T~1e%d: acc=%d/%d (%.2f)" %
              (dec, dec_acc.get(dec, 0), dec_tot[dec],
               dec_acc.get(dec, 0) / max(1, dec_tot[dec])))
    if best_traj:
        print("best traj: " + " ".join("%.1fs:%.7f" % (t, r) for t, r in best_traj[-5:]))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Short polish of the start first (keeps what base does well)
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Metropolis annealing on the current state
    if time.process_time() < deadline - 1.0:
        t_start = time.process_time()
        t_end = deadline - 1.0
        state = best.copy()
        stateR = bestR
        best, bestR = _anneal_loop(state, stateR, best, bestR, deadline,
                                    t_start, t_end, rng)
        print("anneal done R=%.7f" % bestR)

    # Final polish
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.3:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.3)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


