    free = np.arange(lo, hi + 1)
    h = _lbfgs_block(h, free, 100, deadline, beta=0.0)
    h = _lbfgs_block(h, free, 80, deadline, beta=1e7)
    return _rescale(h)


def _draw_move(h, rng):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return None, "none"
    runs = _runs(h)
    mode = rng.integers(0, 5)
    if mode == 0:
        w = h[pos]
        a = int(rng.choice(pos, p=w / w.sum()))
        side = 1 if rng.random() < 0.5 else -1
        b = a + side
        if b < 0 or b >= n:
            return None, "split"
        h2 = h.copy()
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
        return h2, "split"
    elif mode == 1:
        a = int(rng.choice(pos))
        left = pos[pos < a]
        right = pos[pos > a]
        cands = []
        if left.size:
            cands.append(int(left[-1]))
        if right.size:
            cands.append(int(right[0]))
        if not cands:
            return None, "merge"
        b = cands[int(rng.integers(0, len(cands)))]
        h2 = h.copy()
        h2[b] += h2[a]
        h2[a] = 0.0
        return h2, "merge"
    elif mode == 2:
        cands = []
        for (i0, i1) in runs:
            if i0 - 1 >= 0 and h[i0 - 1] <= 0:
                cands.append(i0 - 1)
            if i1 + 1 < n and h[i1 + 1] <= 0:
                cands.append(i1 + 1)
        if not cands:
            return None, "birth"
        a = int(cands[int(rng.integers(0, len(cands)))])
        h2 = h.copy()
        h2[a] = h[pos].mean() * 0.5
        return h2, "birth"
    elif mode == 3:
        short = [(i0, i1) for (i0, i1) in runs if (i1 - i0 + 1) <= 4]
        if not short:
            return None, "death"
        i0, i1 = short[int(rng.integers(0, len(short)))]
        seg = h[i0:i1 + 1]
        a = i0 + int(np.argmin(seg))
        h2 = h.copy()
        h2[a] = 0.0
        return h2, "death"
    else:
        a = int(rng.choice(pos))
        side = 1 if rng.random() < 0.5 else -1
        b = a + side
        if b < 0 or b >= n:
            return None, "transfer"
        h2 = h.copy()
        mv = h2[a] * 0.5
        h2[a] -= mv
        h2[b] += mv
        return h2, "transfer"


def _hop_loop(best, bestR, deadline, rng):
    modes = ["split", "merge", "birth", "death", "transfer"]
    acc = {m: 0 for m in modes}
    best_dR = {m: 0.0 for m in modes}
    n_acc = 0
    n_rej = 0
    trials = 0
    while time.process_time() < deadline - 0.5:
        trials += 1
        h2, mode = _draw_move(best, rng)
        if h2 is None:
            n_rej += 1
            continue
        h2 = _repair(h2, deadline)
        r = R_of(h2)
        if r > bestR + 1e-13:
            dR = r - bestR
            best, bestR = h2.copy(), r
            acc[mode] = acc.get(mode, 0) + 1
            if dR > best_dR.get(mode, 0.0):
                best_dR[mode] = dR
            n_acc += 1
            n_rej = 0
        else:
            n_rej += 1
        if n_acc >= 15 or n_rej >= 40:
            best, bestR = _mini_cycle(best, bestR, deadline)
            n_acc = 0
            n_rej = 0
    return best, bestR, acc, best_dR, trials


def _block_sum(h, L):
    n = h.size
    nb = n // L
    if nb < 1:
        return None
    hh = h[:nb * L].reshape(nb, L)
    return hh.sum(axis=1)


def _coarse_hop(best_full, bestR_full, L, deadline, rng):
    """Run a hop loop on the L-block-summed array; transfer improvements back."""
    hL = _block_sum(best_full, L)
    if hL is None or hL.size < 8:
        return best_full, bestR_full, 0, 0, 0
    hL = _rescale(hL)
    rL = R_of(hL)
    n_acc = 0
    n_rej = 0
    n_transfer_try = 0
    n_transfer_ok = 0
    while time.process_time() < deadline - 0.5:
        h2, mode = _draw_move(hL, rng)
        if h2 is None:
            n_rej += 1
            continue
        # repair in coarse units with smaller window
        S = np.flatnonzero(h2 > 0)
        if S.size == 0:
            n_rej += 1
            continue
        lo = max(0, int(S.min()) - 48)
        hi = min(h2.size - 1, int(S.max()) + 48)
        free = np.arange(lo, hi + 1)
        h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
        h2 = _lbfgs_block(h2, free, 50, deadline, beta=1e7)
        h2 = _rescale(h2)
        r2 = R_of(h2)
        if r2 > rL + 1e-13:
            hL = h2
            rL = r2
            n_acc += 1
            n_rej = 0
        else:
            n_rej += 1
        if n_acc >= 6 or n_rej >= 20:
            # try transfer to full resolution
            n_transfer_try += 1
            full_cand = np.repeat(hL, L)
            # pad to original size if needed
            if full_cand.size < best_full.size:
                full_cand = np.concatenate(
                    [full_cand, np.zeros(best_full.size - full_cand.size)])
            elif full_cand.size > best_full.size:
                full_cand = full_cand[:best_full.size]
            full_cand = _rescale(full_cand)
            # short run_cycle
            fc, fr, _ = run_cycle(full_cand, R_of(full_cand),
                                  min(deadline, time.process_time() + 2.0))
            if fr > bestR_full + 1e-13:
                best_full, bestR_full = fc.copy(), fr
                n_transfer_ok += 1
                # re-derive coarse from new best
                hL2 = _block_sum(best_full, L)
                if hL2 is not None and hL2.size >= 8:
                    hL = _rescale(hL2)
                    rL = R_of(hL)
            n_acc = 0
            n_rej = 0
    return best_full, bestR_full, n_acc, n_transfer_try, n_transfer_ok


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    if time.process_time() < deadline - 3.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 3.0)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Coarse-scale structural moves at L=2 and L=4
    for L in [2, 4]:
        if time.process_time() >= deadline - 2.0:
            break
        seg_deadline = min(deadline - 1.5, time.process_time() + 12.0)
        r_before = bestR
        best, bestR, n_acc, n_try, n_ok = _coarse_hop(
            best, bestR, L, seg_deadline, rng)
        rate = (n_ok / n_try) if n_try > 0 else 0.0
        print("L=%d: coarse acc=%d transfer %d/%d (%.2f) dR=%.3e -> R=%.7f"
              % (L, n_acc, n_ok, n_try, rate, bestR - r_before, bestR))

    if time.process_time() < deadline - 1.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 600, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.25, 128, 1e8), (0.40, 256, 1e8),
              (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _runs(h):
    pos = h > 0
    runs = []
    n = h.size
    i = 0
    while i < n:
        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _repair(h, deadline):
    S = np.flatnonzero(h > 0)
    if S.size == 0:
        return h
    lo = max(0, int(S.min()) - 64)
    hi = min(h.size - 1, int(S.max()) + 64)
    free = np.arange(lo, hi + 1)
    h = _lbfgs_block(h, free, 80, deadline, beta=0.0)
    return _rescale(h)


def _mutation(h, rng):
    """Structural mutation: split/merge/birth/death/transfer."""
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return None
    runs = _runs(h)
    mode = rng.integers(0, 5)
    if mode == 0:
        # split a point, move half to neighbor
        a = int(rng.choice(pos))
        side = 1 if rng.random() < 0.5 else -1
        b = a + side
        if b < 0 or b >= n:
            return None
        h2 = h.copy()
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
        return h2
    elif mode == 1:
        # merge into adjacent support
        a = int(rng.choice(pos))
        left = pos[pos < a]
        right = pos[pos > a]
        cands = []
        if left.size:
            cands.append(int(left[-1]))
        if right.size:
            cands.append(int(right[0]))
        if not cands:
            return None
        b = cands[int(rng.integers(0, len(cands)))]
        h2 = h.copy()
        h2[b] += h2[a]
        h2[a] = 0.0
        return h2
    elif mode == 2:
        # birth: sprout next to a run
        cands = []
        for (i0, i1) in runs:
            if i0 - 1 >= 0 and h[i0 - 1] <= 0:
                cands.append(i0 - 1)
            if i1 + 1 < n and h[i1 + 1] <= 0:
                cands.append(i1 + 1)
        if not cands:
            return None
        a = int(cands[int(rng.integers(0, len(cands)))])
        h2 = h.copy()
        h2[a] = h[pos].mean() * 0.3
        return h2
    elif mode == 3:
        # death: kill a small support point
        short = [(i0, i1) for (i0, i1) in runs if (i1 - i0 + 1) <= 4]
        if not short:
            return None
        i0, i1 = short[int(rng.integers(0, len(short)))]
        seg = h[i0:i1 + 1]
        a = i0 + int(np.argmin(seg))
        h2 = h.copy()
        h2[a] = 0.0
        return h2
    else:
        # transfer mass to neighbor
        a = int(rng.choice(pos))
        side = 1 if rng.random() < 0.5 else -1
        b = a + side
        if b < 0 or b >= n:
            return None
        h2 = h.copy()
        mv = h2[a] * 0.5
        h2[a] -= mv
        h2[b] += mv
        return h2


def _lognormal_hit(h, rng):
    n = h.size
    wfrac = rng.uniform(0.005, 0.02)
    w = max(2, int(n * wfrac))
    if w >= n:
        w = n - 1
    lo = int(rng.integers(0, n - w))
    hi = lo + w
    h2 = h.copy()
    sig = 0.25
    fac = np.exp(rng.normal(0.0, sig, size=w))
    h2[lo:hi] = h2[lo:hi] * fac
    return h2, (lo, hi)


def _anneal_loop(state, stateR, best, bestR, t_end, rng):
    T0 = 3e-6
    Tmin = 1e-7
    t_start = time.process_time()
    total = max(1e-9, t_end - t_start)
    n_moves = 0
    n_acc = 0
    while time.process_time() < t_end - 0.4:
        now = time.process_time()
        frac = min(1.0, max(0.0, (now - t_start) / total))
        T = T0 * (Tmin / T0) ** frac
        n_moves += 1
        if rng.random() < 0.5:
            h2, win = _lognormal_hit(state, rng)
            lo = max(0, win[0] - 48)
            hi = min(state.size - 1, win[1] + 48)
            free = np.arange(lo, hi + 1)
            h2 = _lbfgs_block(h2, free, 50, t_end, beta=0.0)
        else:
            h2 = _mutation(state, rng)
            if h2 is None:
                continue
            h2 = _repair(h2, t_end)
        r2 = R_of(h2)
        dR = r2 - stateR
        accept = dR >= 0 or rng.random() < np.exp(dR / T)
        if accept:
            state = h2
            stateR = r2
            n_acc += 1
            if stateR > bestR + 1e-13:
                best = state.copy()
                bestR = stateR
        if n_moves % 30 == 0:
            st2 = _lbfgs_all_pos(state, 100, t_end, beta=1e7)
            r2b = R_of(st2)
            if r2b > stateR + 1e-13:
                state, stateR = st2, r2b
                if stateR > bestR + 1e-13:
                    best = state.copy()
                    bestR = stateR
    print("anneal moves=%d acc=%d rate=%.3f" %
          (n_moves, n_acc, n_acc / max(1, n_moves)))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(987654321)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    if time.process_time() < deadline - 4.0:
        best, bestR = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f" % bestR)

    if time.process_time() < deadline - 1.0:
        t_end = deadline - 1.0
        state = best.copy()
        stateR = bestR
        best, bestR = _anneal_loop(state, stateR, best, bestR, t_end, rng)
        print("anneal done R=%.7f" % bestR)

    if time.process_time() < deadline - 0.5:
        best, bestR = run_cycle(best, bestR, deadline - 0.5)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_band(h, mu, tol):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad(h)
    m = int(np.argmax(Lf))
    band = Lf >= tol * M
    nb = int(band.sum())
    if nb == 0:
        return _fun_grad(h)
    diff = M - Lf[band]
    pen = mu * np.mean(diff * diff) / (M * M)
    dq_band = np.zeros_like(Lf)
    dq_band[band] = -2.0 * mu * diff / (nb * M * M)
    gLf = -(dq + dq_band) / num
    gLf[m] += 1.0 / M
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M) + pen
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, band=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if band is not None:
        tol, mu = band
        fg = (lambda hh: _fun_grad_band(hh, mu, tol))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, band=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if band is not None:
        tol, mu = band
        fg = (lambda hh: _fun_grad_band(hh, mu, tol))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_counts(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, 0, Lf.size
    return (int(np.sum(Lf >= 0.999 * mx)),
            int(np.sum(Lf >= 0.99 * mx)),
            Lf.size)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _runs(h):
    pos = h > 0
    runs = []
    n = h.size
    i = 0
    while i < n:
        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _repair(h, deadline):
    S = np.flatnonzero(h > 0)
    if S.size == 0:
        return h
    lo = max(0, int(S.min()) - 96)
    hi = min(h.size - 1, int(S.max()) + 96)
    free = np.arange(lo, hi + 1)
    h = _lbfgs_block(h, free, 100, deadline, beta=0.0)
    h = _lbfgs_block(h, free, 80, deadline, beta=1e7)
    return _rescale(h)


def _draw_move(h, rng):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return None, "none"
    runs = _runs(h)
    mode = rng.integers(0, 5)
    if mode == 0:
        w = h[pos]
        a = int(rng.choice(pos, p=w / w.sum()))
        side = 1 if rng.random() < 0.5 else -1
        b = a + side
        if b < 0 or b >= n:
            return None, "split"
        h2 = h.copy()
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
        return h2, "split"
    elif mode == 1:
        a = int(rng.choice(pos))
        left = pos[pos < a]
        right = pos[pos > a]
        cands = []
        if left.size:
            cands.append(int(left[-1]))
        if right.size:
            cands.append(int(right[0]))
        if not cands:
            return None, "merge"
        b = cands[int(rng.integers(0, len(cands)))]
        h2 = h.copy()
        h2[b] += h2[a]
        h2[a] = 0.0
        return h2, "merge"
    elif mode == 2:
        cands = []
        for (i0, i1) in runs:
            if i0 - 1 >= 0 and h[i0 - 1] <= 0:
                cands.append(i0 - 1)
            if i1 + 1 < n and h[i1 + 1] <= 0:
                cands.append(i1 + 1)
        if not cands:
            return None, "birth"
        a = int(cands[int(rng.integers(0, len(cands)))])
        h2 = h.copy()
        h2[a] = h[pos].mean() * 0.5
        return h2, "birth"
    elif mode == 3:
        short = [(i0, i1) for (i0, i1) in runs if (i1 - i0 + 1) <= 4]
        if not short:
            return None, "death"
        i0, i1 = short[int(rng.integers(0, len(short)))]
        seg = h[i0:i1 + 1]
        a = i0 + int(np.argmin(seg))
        h2 = h.copy()
        h2[a] = 0.0
        return h2, "death"
    else:
        a = int(rng.choice(pos))
        side = 1 if rng.random() < 0.5 else -1
        b = a + side
        if b < 0 or b >= n:
            return None, "transfer"
        h2 = h.copy()
        mv = h2[a] * 0.5
        h2[a] -= mv
        h2[b] += mv
        return h2, "transfer"


def _hop_loop(best, bestR, deadline, rng):
    modes = ["split", "merge", "birth", "death", "transfer"]
    acc = {m: 0 for m in modes}
    best_dR = {m: 0.0 for m in modes}
    n_acc = 0
    n_rej = 0
    trials = 0
    while time.process_time() < deadline - 0.5:
        trials += 1
        h2, mode = _draw_move(best, rng)
        if h2 is None:
            n_rej += 1
            continue
        h2 = _repair(h2, deadline)
        r = R_of(h2)
        if r > bestR + 1e-13:
            dR = r - bestR
            best, bestR = h2.copy(), r
            acc[mode] = acc.get(mode, 0) + 1
            if dR > best_dR.get(mode, 0.0):
                best_dR[mode] = dR
            n_acc += 1
            n_rej = 0
        else:
            n_rej += 1
        if n_acc >= 15 or n_rej >= 40:
            best, bestR = _mini_cycle(best, bestR, deadline)
            n_acc = 0
            n_rej = 0
    return best, bestR, acc, best_dR, trials


def _band_ladder(best, bestR, deadline):
    ladder = [(0.999, 1.0), (0.999, 10.0), (0.995, 10.0), (0.99, 100.0)]
    for tol, mu in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        b0, b1, tot = _band_counts(best)
        ht = _lbfgs_all_pos(best, 250, deadline - 0.5, band=(tol, mu))
        r = R_of(ht)
        b0n, b1n, _ = _band_counts(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _upsample(h, factor):
    """Piecewise-linear resample of heights onto a finer grid."""
    n = h.size
    m = n * factor
    x = np.linspace(0.0, n, m, endpoint=False) + 0.5 / factor
    xp = np.arange(n) + 0.5
    return np.interp(x, xp, h, left=h[0], right=h[-1])


def _downsample(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h
    return h[:m * factor].reshape(m, factor).mean(axis=1)


def _try_resolution(best, bestR, deadline, factor, rng):
    """Change resolution then re-optimise; keep if better."""
    if time.process_time() >= deadline - 0.5:
        return best, bestR
    if factor > 1:
        h2 = _upsample(best, factor)
    else:
        h2 = _downsample(best, -factor)
    h2 = _rescale(h2)
    h2 = _lbfgs_all_pos(h2, 350, deadline - 0.5, beta=0.0)
    h2 = _lbfgs_all_pos(h2, 250, deadline - 0.5, beta=1e7)
    r = R_of(h2)
    if r > bestR + 1e-13:
        return h2, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW: resolution search — try up-sampling and down-sampling, keep better.
    for factor in (2, -2, 4, -3):
        if time.process_time() >= deadline - 4.0:
            break
        h2, r2 = _try_resolution(best, bestR, deadline - 4.0, factor, rng)
        if r2 > bestR + 1e-13:
            print("  res x%.0f -> R=%.7f N=%d" % (factor, r2, h2.size))
            best, bestR = h2, r2

    if time.process_time() < deadline - 3.0:
        r_before = bestR
        best, bestR = _band_ladder(best, bestR, deadline - 3.0)
        print("band ladder dR=%.3e -> R=%.7f" % (bestR - r_before, bestR))

    if time.process_time() < deadline - 3.0:
        best, bestR = run_cycle(best, bestR, deadline - 3.0)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    if time.process_time() < deadline - 2.0:
        r_before = bestR
        best, bestR, acc, best_dR, trials = _hop_loop(best, bestR, deadline - 2.0, rng)
        print("hop dR=%.3e -> R=%.7f trials=%d" % (bestR - r_before, bestR, trials))

    if time.process_time() < deadline - 1.0:
        best, bestR = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    """Gradient of log R w.r.t. h (no 2/s term needed for ranking edits)."""
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    """Return list of (pred_delta, a, b, kind) candidate edits, ranked."""
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []  # (pred, a, b, kind)
    # split/half-transfer to a+1 and a-1
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    # full transfer to nearest positive neighbour on each side
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    # death of a
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    # birth at interior zero adjacent to a positive run
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    # greedy selection with index separation >= 4
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    total_acc = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        n_screen = len(cands)
        best_pred = cands[0][0]
        best_cand = None
        best_cand_R = bestR
        best_realized = 0.0
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
                best_realized = r2 - bestR
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
            total_acc += 1
            print("round %d: screened=%d pred=%.3e realized=%.3e R=%.7f" %
                  (round_no, n_screen, best_pred, best_realized, bestR))
        else:
            print("round %d: screened=%d pred=%.3e no accept R=%.7f" %
                  (round_no, n_screen, best_pred, bestR))
            # try mini cycle to escape
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    print("  mini_cycle R=%.7f" % bestR)
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    print("  mini_cycle R=%.7f" % bestR)
    print("edit loop: rounds=%d accepted=%d" % (round_no, total_acc))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    if time.process_time() < deadline - 1.0:
        best, bestR = _greedy_edit_loop(best, bestR, deadline - 1.0, rng)
        print("edit loop done R=%.7f" % bestR)

    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.3:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.3)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _bands(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0
    return float(np.mean(Lf >= 0.999 * mx)), float(np.mean(Lf >= 0.99 * mx))


def _prolong_linear(h, N2):
    N = h.size
    F = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.arange(N + 1, dtype=float) * (N2 / float(N))
    j = np.arange(N2 + 1, dtype=float)
    G = np.interp(j, xs, F)
    return np.diff(G)


def _prolong_stair(h, N2):
    N = h.size
    idx = (np.arange(N2, dtype=float) * (N / float(N2))).astype(int)
    idx = np.clip(idx, 0, N - 1)
    return h[idx] * (N / float(N2))


def _run_cycle(h, bestR, deadline, cycles=2):
    best = h.copy()
    for _ in range(cycles):
        if time.process_time() >= deadline - 2.0:
            break
        ht = _lbfgs_all_pos(best, 600, deadline - 2.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        if time.process_time() >= deadline - 2.0:
            break
        ht = _lbfgs_all_pos(best, 300, deadline - 2.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        for (frac, extra, beta) in [(0.05, 64, 1e7), (0.10, 64, 1e8),
                                    (0.25, 128, 1e8), (0.40, 256, 1e8)]:
            if time.process_time() >= deadline - 2.0:
                break
            ht = _window_polish_peak(best, deadline - 2.0, frac, extra,
                                     maxiter=300, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
    return best, bestR


def _hop_loop(h, bestR, deadline, seconds):
    """Gradient-screened hop: perturb, re-optimise, keep if better."""
    stop = min(deadline - 1.0, time.process_time() + seconds)
    rng = np.random.default_rng(12345)
    best = h.copy()
    while time.process_time() < stop:
        cand = best.copy()
        n = cand.size
        # screen: perturb in the peak region with small noise
        lo, hi = _peak_region(best)
        span = max(1, hi - lo)
        k = max(4, span // 8)
        idx = rng.integers(lo, min(n, hi + span // 4 + 1), size=k)
        idx = np.clip(idx, 0, n - 1)
        noise = rng.normal(0.0, 0.02, size=k)
        cand[idx] = np.clip(cand[idx] * (1.0 + noise), 0.0, None)
        cand = _rescale(cand)
        ht = _lbfgs_all_pos(cand, 200, stop + 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _refine_knots(h, deadline):
    # final sharp polishes
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 2000, deadline - 0.2)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size
    N2 = 104992
    if N2 <= 900000:
        # prolongation (a): mass-preserving piecewise-linear
        cands = []
        try:
            pl = _prolong_linear(best, N2)
            pl = _rescale(np.clip(pl, 0, None))
            cands.append(("linear", pl))
        except Exception:
            pass
        # prolongation (b): staircase repeat
        try:
            st = _prolong_stair(best, N2)
            st = _rescale(np.clip(st, 0, None))
            cands.append(("stair", st))
        except Exception:
            pass

        results = []
        for name, cand in cands:
            if time.process_time() >= deadline - 3.0:
                break
            r0 = R_of(cand)
            b01, b1 = _bands(cand)
            print("prolong %s R=%.7f band01=%.4f band1=%.4f"
                  % (name, r0, b01, b1))
            # full run_cycle twice
            hc, rc = _run_cycle(cand, r0, deadline, cycles=2)
            # gradient-screened hop loop for ~15 s
            if time.process_time() < deadline - 2.0:
                hc, rc = _hop_loop(hc, rc, deadline, 15.0)
            # final polishes
            if time.process_time() < deadline - 1.0:
                hc, rc = _refine_knots(hc, deadline)
            b01, b1 = _bands(hc)
            Lf = _knots(hc)
            am = int(np.argmax(Lf))
            print("prolong %s done R=%.7f zeros=%.1f%% argmax=%d/%d band01=%.4f band1=%.4f"
                  % (name, rc, 100.0 * np.mean(hc <= 0), am, hc.size, b01, b1))
            results.append((rc, hc, name))

        for rc, hc, name in results:
            if rc > bestR + 1e-12:
                best, bestR = hc.copy(), rc
                print("new best from %s R=%.7f" % (name, bestR))

    # If nothing beat start, still fall back to base's own cycle polish
    if bestR <= start_bestR + 1e-12 and time.process_time() < deadline - 2.0:
        hc, rc = _run_cycle(best, bestR, deadline, cycles=1)
        if rc > bestR + 1e-13:
            best, bestR = hc, rc

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    if best.size != start_best.size and bestR > start_bestR - 1e-6:
        return {"best": start_best, "alternative": best}
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _runs(h):
    pos = h > 0
    runs = []
    n = h.size
    i = 0
    while i < n:
        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _repair(h, deadline):
    S = np.flatnonzero(h > 0)
    if S.size == 0:
        return h
    lo = max(0, int(S.min()) - 96)
    hi = min(h.size - 1, int(S.max()) + 96)
    free = np.arange(lo, hi + 1)
    h = _lbfgs_block(h, free, 100, deadline, beta=0.0)
    h = _lbfgs_block(h, free, 80, deadline, beta=1e7)
    return _rescale(h)


def _draw_move(h, rng):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return None, "none"
    runs = _runs(h)
    mode = rng.integers(0, 5)
    if mode == 0:
        w = h[pos]
        a = int(rng.choice(pos, p=w / w.sum()))
        side = 1 if rng.random() < 0.5 else -1
        b = a + side
        if b < 0 or b >= n:
            return None, "split"
        h2 = h.copy()
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
        return h2, "split"
    elif mode == 1:
        a = int(rng.choice(pos))
        left = pos[pos < a]
        right = pos[pos > a]
        cands = []
        if left.size:
            cands.append(int(left[-1]))
        if right.size:
            cands.append(int(right[0]))
        if not cands:
            return None, "merge"
        b = cands[int(rng.integers(0, len(cands)))]
        h2 = h.copy()
        h2[b] += h2[a]
        h2[a] = 0.0
        return h2, "merge"
    elif mode == 2:
        cands = []
        for (i0, i1) in runs:
            if i0 - 1 >= 0 and h[i0 - 1] <= 0:
                cands.append(i0 - 1)
            if i1 + 1 < n and h[i1 + 1] <= 0:
                cands.append(i1 + 1)
        if not cands:
            return None, "birth"
        a = int(cands[int(rng.integers(0, len(cands)))])
        h2 = h.copy()
        h2[a] = h[pos].mean() * 0.5
        return h2, "birth"
    elif mode == 3:
        short = [(i0, i1) for (i0, i1) in runs if (i1 - i0 + 1) <= 4]
        if not short:
            return None, "death"
        i0, i1 = short[int(rng.integers(0, len(short)))]
        seg = h[i0:i1 + 1]
        a = i0 + int(np.argmin(seg))
        h2 = h.copy()
        h2[a] = 0.0
        return h2, "death"
    else:
        a = int(rng.choice(pos))
        side = 1 if rng.random() < 0.5 else -1
        b = a + side
        if b < 0 or b >= n:
            return None, "transfer"
        h2 = h.copy()
        mv = h2[a] * 0.5
        h2[a] -= mv
        h2[b] += mv
        return h2, "transfer"


def _lognormal_hit(h, rng):
    n = h.size
    wfrac = rng.uniform(0.01, 0.03)
    w = max(2, int(n * wfrac))
    if w >= n:
        w = n - 1
    lo = int(rng.integers(0, n - w))
    hi = lo + w
    h2 = h.copy()
    sig = 0.3
    fac = np.exp(rng.normal(0.0, sig, size=w))
    h2[lo:hi] = h2[lo:hi] * fac
    return h2, (lo, hi)


def _anneal_loop(state, stateR, best, bestR, deadline, t_start, t_end, rng):
    T0 = 5e-6
    Tmin = 2e-7
    total = max(1e-9, t_end - t_start)
    n_moves = 0
    n_acc = 0
    dec_acc = {}
    dec_tot = {}
    best_traj = []
    while time.process_time() < t_end - 0.5:
        now = time.process_time()
        frac = min(1.0, max(0.0, (now - t_start) / total))
        T = T0 * (Tmin / T0) ** frac
        n_moves += 1
        use_hit = rng.random() < 0.5
        if use_hit:
            h2, win = _lognormal_hit(state, rng)
            lo = max(0, win[0] - 64)
            hi = min(state.size - 1, win[1] + 64)
            free = np.arange(lo, hi + 1)
            h2 = _lbfgs_block(h2, free, 60, t_end, beta=0.0)
            mode = "hit"
        else:
            h2, mode = _draw_move(state, rng)
            if h2 is None:
                continue
            h2 = _repair(h2, t_end)
        r2 = R_of(h2)
        dR = r2 - stateR
        dec = int(np.floor(np.log10(max(T, 1e-12))))
        dec_tot[dec] = dec_tot.get(dec, 0) + 1
        accept = False
        if dR >= 0:
            accept = True
        else:
            p = np.exp(dR / T)
            if rng.random() < p:
                accept = True
        if accept:
            state = h2
            stateR = r2
            n_acc += 1
            dec_acc[dec] = dec_acc.get(dec, 0) + 1
            if stateR > bestR + 1e-13:
                best = state.copy()
                bestR = stateR
                best_traj.append((now - t_start, bestR))
        if n_moves % 25 == 0:
            st2, r2b = _mini_cycle(state, stateR, t_end)
            if r2b > stateR + 1e-13:
                state, stateR = st2, r2b
                if stateR > bestR + 1e-13:
                    best = state.copy()
                    bestR = stateR
                    best_traj.append((now - t_start, bestR))
    print("anneal moves=%d acc=%d rate=%.3f" %
          (n_moves, n_acc, n_acc / max(1, n_moves)))
    for dec in sorted(dec_tot.keys()):
        print("  T~1e%d: acc=%d/%d (%.2f)" %
              (dec, dec_acc.get(dec, 0), dec_tot[dec],
               dec_acc.get(dec, 0) / max(1, dec_tot[dec])))
    if best_traj:
        print("best traj: " + " ".join("%.1fs:%.7f" % (t, r) for t, r in best_traj[-5:]))
    return best, bestR


# ---------------- slot-1 style screening machinery ----------------

def _screen(h, rng, n_cand=512):
    """Generate candidate single moves and return list of (dR, delta_vector, touched_idx).

    Each candidate is a small structural move applied to h, then repaired locally
    with a short L-BFGS on a narrow window, and the resulting delta and dR recorded.
    """
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    cands = []
    for _ in range(n_cand):
        h2, mode = _draw_move(h, rng)
        if h2 is None:
            continue
        # local repair window: around changed cells
        diff = np.flatnonzero(np.abs(h2 - h) > 0)
        if diff.size == 0:
            continue
        lo = max(0, int(diff.min()) - 24)
        hi = min(n - 1, int(diff.max()) + 24)
        free = np.arange(lo, hi + 1)
        h2 = _lbfgs_block(h2, free, 40, time.process_time() + 0.2, beta=0.0)
        r2 = R_of(h2)
        dR = r2 - R_of(h)
        delta = h2 - h
        cands.append((dR, delta, diff))
    return cands


def _select_top(cands, M=256, sep=8):
    """Pick top-M candidates by dR with index separation >= sep between touched sets."""
    if not cands:
        return []
    cands = sorted(cands, key=lambda c: -c[0])
    chosen = []
    used = []
    for dR, delta, diff in cands:
        if dR <= 0:
            break
        ok = True
        for u in used:
            if np.min(np.abs(diff[:, None] - u[None, :])) < sep:
                ok = False
                break
        if ok:
            chosen.append((dR, delta, diff))
            used.append(diff)
            if len(chosen) >= M:
                break
    return chosen


def _batched_round(h, bestR, rng, deadline):
    """One batched superposition round. Returns (h_new, R_new, info)."""
    if time.process_time() >= deadline - 1.0:
        return h, bestR, None
    cands = _screen(h, rng, n_cand=400)
    if not cands:
        return h, bestR, None
    chosen = _select_top(cands, M=256, sep=8)
    if len(chosen) < 4:
        return h, bestR, None
    delta = np.zeros_like(h)
    touched = []
    for dR, d, diff in chosen:
        delta += d
        touched.append(diff)
    touched = np.unique(np.concatenate(touched))
    # free window: +-24 around every touched index
    mask = np.zeros(h.size, dtype=bool)
    for t in touched:
        lo = max(0, t - 24)
        hi = min(h.size, t + 25)
        mask[lo:hi] = True
    free = np.flatnonzero(mask)
    if free.size > 30000:
        free = None
    best_alpha = None
    best_h = h
    best_r = bestR
    for alpha in [0.15, 0.35, 0.6, 1.0]:
        if time.process_time() >= deadline - 0.8:
            break
        h_a = np.clip(h + alpha * delta, 0, None)
        if h_a.sum() <= 0:
            continue
        h_a = _rescale(h_a)
        if free is not None:
            h_a = _lbfgs_block(h_a, free, 80, deadline - 0.6, beta=0.0)
            h_a = _lbfgs_block(h_a, free, 60, deadline - 0.6, beta=1e8)
        else:
            h_a = _lbfgs_all_pos(h_a, 120, deadline - 0.6, beta=0.0)
            h_a = _lbfgs_all_pos(h_a, 80, deadline - 0.6, beta=1e8)
        r_a = R_of(h_a)
        if r_a > best_r + 1e-13:
            best_r = r_a
            best_h = h_a
            best_alpha = alpha
    info = (len(chosen), best_alpha, best_r - bestR)
    return best_h, best_r, info


def _single_round(h, bestR, rng, deadline):
    """Slot-1 style single-move round: try a few moves, keep best."""
    if time.process_time() >= deadline - 0.8:
        return h, bestR, None
    best_h = h
    best_r = bestR
    for _ in range(6):
        if time.process_time() >= deadline - 0.6:
            break
        h2, mode = _draw_move(h, rng)
        if h2 is None:
            continue
        h2 = _repair(h2, deadline - 0.5)
        r2 = R_of(h2)
        if r2 > best_r + 1e-13:
            best_r = r2
            best_h = h2
    return best_h, best_r, (best_r - bestR)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Short polish of the start first
    if time.process_time() < deadline - 5.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 5.0)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Main loop: alternate batched rounds and single-move rounds
    round_idx = 0
    while time.process_time() < deadline - 3.0:
        round_idx += 1
        if round_idx % 2 == 1:
            h_new, r_new, info = _batched_round(best, bestR, rng, deadline - 2.0)
            if info is not None:
                M, alpha, dR = info
                print("batch %d: M=%d alpha=%s dR=%.3e" %
                      (round_idx, M, str(alpha), dR))
        else:
            h_new, r_new, dR = _single_round(best, bestR, rng, deadline - 2.0)
            if dR is not None:
                print("single %d: dR=%.3e" % (round_idx, dR))
        if r_new > bestR + 1e-13:
            best, bestR = h_new, r_new
        if round_idx % 10 == 0 and time.process_time() < deadline - 3.0:
            best, bestR = _mini_cycle(best, bestR, deadline - 2.0)
            print("mini_cycle R=%.7f" % bestR)

    # Final polish
    if time.process_time() < deadline - 1.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def _report(tag, h, R):
    print("%s R=%.7f N=%d" % (tag, R, h.size))


def _hop(h, bestR, deadline, rng):
    n = h.size
    if n < 8:
        return h, bestR
    wlen = int(rng.integers(max(8, n // 20), max(16, n // 4)))
    wlen = min(wlen, n)
    lo = int(rng.integers(0, n - wlen + 1))
    hi = lo + wlen
    hp = h.copy()
    amp = rng.uniform(0.02, 0.15)
    noise = 1.0 + amp * rng.standard_normal(wlen)
    hp[lo:hi] = np.clip(hp[lo:hi] * noise, 0.0, None)
    hp = _rescale(hp)
    rp = R_of(hp)
    halo = 64
    flo = max(0, lo - halo); fhi = min(n, hi + halo)
    free = np.arange(flo, fhi)
    if free.size > 0 and time.process_time() < deadline - 0.5:
        ht = _lbfgs_block(hp, free, 200, deadline - 0.5, beta=1e7)
        rt = R_of(ht)
        if rt > rp:
            hp, rp = ht, rt
    if time.process_time() < deadline - 0.5:
        win = _peak_window(hp, tol=0.95, pad_frac=0.5, extra=512)
        if win.size <= 40000:
            ht = _lbfgs_block(hp, win, 250, deadline - 0.5, beta=0.0)
            rt = R_of(ht)
            if rt > rp:
                hp, rp = ht, rt
    if rp > bestR + 1e-13:
        return hp, rp
    return h, bestR


def _mutate(h, bestR, deadline, rng):
    """Block-replace: zero a random block and let L-BFGS rebuild it."""
    n = h.size
    hp = h.copy()
    blen = int(rng.integers(max(8, n // 40), max(16, n // 8)))
    blen = min(blen, n)
    lo = int(rng.integers(0, n - blen + 1))
    hi = lo + blen
    hp[lo:hi] = 0.0
    hp = _rescale(hp)
    rp = R_of(hp)
    halo = 128
    free = np.arange(max(0, lo - halo), min(n, hi + halo))
    if free.size > 0 and time.process_time() < deadline - 0.5:
        ht = _lbfgs_block(hp, free, 300, deadline - 0.5, beta=0.0)
        rt = R_of(ht)
        if rt > rp:
            hp, rp = ht, rt
    if rp > bestR + 1e-13:
        return hp, rp
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Stage (a): full polish + beta smoothing.
    if time.process_time() < deadline - 1.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 1.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 1.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 1.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    _report("(a)", best, bestR)

    # Stage (b): peak-window refinements at multiple scales.
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        if win.size > 40000:
            continue
        ht = _lbfgs_block(best, win, 250, deadline - 1.0, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    _report("(b)", best, bestR)

    # Stage (c): hop loop with acceptance, alternating with block-replace.
    rng = np.random.default_rng(987654321)
    n_hops = 0
    n_accept = 0
    while time.process_time() < deadline - 1.2:
        n_hops += 1
        if n_hops % 3 == 0:
            hnew, rnew = _mutate(best, bestR, deadline - 1.2, rng)
        else:
            hnew, rnew = _hop(best, bestR, deadline - 1.2, rng)
        if rnew > bestR + 1e-13:
            best, bestR = hnew, rnew
            n_accept += 1
        if n_hops > 400:
            break
    print("(c) hops=%d accepted=%d" % (n_hops, n_accept))
    _report("(c)", best, bestR)

    # Stage (d): final broad polish.
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 500, deadline - 0.6, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        hs = _seed_zeros(best)
        ht = _lbfgs_all_pos(hs, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    _report("final", best, bestR)

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

