    val, grad = _fun_grad(np.clip(h, 0, None))
    g = -grad
    hmax = h.max() if h.size else 0.0
    zero_mask = h <= 1e-12 * hmax
    pos_mask = ~zero_mask
    gz = g[zero_mask]
    gp = g[pos_mask]
    def stats(a):
        if a.size == 0:
            return (0.0, 0.0, 0.0)
        return (float(a.max()), float(a.mean()), float(np.median(a)))
    sz = stats(gz)
    sp = stats(gp)
    print("KKT: zeros n=%d max=%.3e mean=%.3e med=%.3e | pos n=%d max=%.3e mean=%.3e med=%.3e"
          % (gz.size, sz[0], sz[1], sz[2], gp.size, sp[0], sp[1], sp[2]))
    return g, zero_mask


def _upsample(h, factor):
    """Split each step into `factor` equal sub-steps (block replication)."""
    if factor <= 1:
        return h.copy()
    out = np.repeat(h, factor) / factor
    return _rescale(out)


def _try_upsample_refine(best, bestR, deadline, factor):
    """Upsample the current best by `factor` and refine all cells; keep if better."""
    if time.process_time() >= deadline - 1.0:
        return best, bestR
    hu = _upsample(best, factor)
    r0 = R_of(hu)
    # short global polish on the finer grid
    hu2 = _lbfgs_all_pos(hu, 400, deadline - 0.5, beta=0.0)
    r1 = R_of(hu2)
    if r1 > bestR + 1e-13:
        print("upsample x%d: R=%.7f (base %.7f, raw %.7f)"
              % (factor, r1, bestR, r0))
        return hu2, r1
    # even raw upsample may already be better (same R, but different param)
    if r0 > bestR + 1e-13:
        return hu, r0
    print("upsample x%d: no gain (raw %.7f, refined %.7f vs %.7f)"
          % (factor, r0, r1, bestR))
    return best, bestR


def _perturb_and_polish(best, bestR, deadline, rng, scale, n_pert, maxiter):
    """Add random bumps to some cells, then polish; accept if better."""
    if time.process_time() >= deadline - 1.0:
        return best, bestR
    n = best.size
    cand = best.copy()
    idx = rng.integers(0, n, size=n_pert)
    # perturb multiplicatively
    factors = np.exp(rng.normal(0.0, scale, size=n_pert))
    cand[idx] *= factors
    cand = _rescale(cand)
    # polish with global
    cand = _lbfgs_all_pos(cand, maxiter, deadline - 0.5, beta=0.0)
    # peak-window polish
    if time.process_time() < deadline - 0.5:
        win = _peak_window(cand, pad_frac=0.2, extra=256)
        cand = _lbfgs_block(cand, win, maxiter=200, deadline=deadline - 0.5,
                            beta=1e8)
    r = R_of(cand)
    if r > bestR + 1e-13:
        print("perturb n=%d scale=%.2e -> R=%.7f (dR=%.2e)"
              % (n_pert, scale, r, r - bestR))
        return cand, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Phase 0: one base cycle ----
    prevR = bestR
    best, bestR, drefine = run_cycle(best, bestR, deadline - 1.5)
    print("cycle 0 R=%.7f dR=%.2e drefine=%.2e zeros=%.1f%%"
          % (bestR, bestR - prevR, drefine, 100.0 * np.mean(best <= 0)))

    # ---- Phase 1: upsample-and-refine (new idea) ----
    # The construction is a step function on a coarse grid; refining the grid
    # and re-solving on the finer discretisation gives a different point in
    # function space and often a small gain.
    for factor in (2,):
        if time.process_time() >= deadline - 30.0:
            break
        best, bestR = _try_upsample_refine(best, bestR, deadline, factor)
        print("after upsample x%d: R=%.7f N=%d" % (factor, bestR, best.size))

    # ---- Phase 2: peak-window fine tuning on the (possibly finer) grid ----
    for frac, extra, beta in [(0.03, 64, 1e7), (0.08, 128, 1e8),
                              (0.20, 256, 1e8), (0.45, 512, 1e8)]:
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        cand = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                            beta=beta)
        r = R_of(cand)
        if r > bestR + 1e-13:
            best, bestR = cand, r
            print("peak frac=%.2f R=%.7f" % (frac, bestR))

    # ---- Phase 3: perturbation restarts ----
    rng = np.random.default_rng(12345)
    while time.process_time() < deadline - 2.0:
        # alternate between small and large perturbations
        scale = float(rng.choice([1e-3, 1e-2, 5e-2]))
        n_pert = int(rng.integers(50, 2000))
        best, bestR = _perturb_and_polish(
            best, bestR, deadline, rng, scale, n_pert, maxiter=300)
        # occasionally re-polish the peak window
        if time.process_time() < deadline - 2.0:
            win = _peak_window(best, pad_frac=0.15, extra=256)
            cand = _lbfgs_block(best, win, maxiter=150,
                                deadline=deadline - 0.5, beta=1e8)
            r = R_of(cand)
            if r > bestR + 1e-13:
                best, bestR = cand, r

    # ---- Closing global polish ----
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def _resample(h, N):
    # Resample a step function to N equal steps over the same support.
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    if n == N:
        return h.copy()
    edges_old = np.linspace(0.0, 1.0, n + 1)
    edges_new = np.linspace(0.0, 1.0, N + 1)
    # cumulative integral of h (piecewise constant)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    total = cum[-1]
    if total <= 0:
        return np.zeros(N)
    # integral from 0 to t (fractional t on old edges)
    def integ(t):
        x = t * n
        i = np.clip(np.floor(x).astype(int), 0, n - 1)
        frac = x - i
        return cum[i] + frac * h[i]
    lo = integ(edges_new[:-1])
    hi = integ(edges_new[1:])
    out = (hi - lo) / (1.0 / N)  # average height per new step
    return out


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _spectral_invert(Lf, c, mx):
    T = Lf.copy()
    T[T >= c * mx] = mx
    if T.size >= 3:
        Tm = T.copy()
        Tm[1:-1] = 0.25 * T[:-2] + 0.5 * T[1:-1] + 0.25 * T[2:]
        Tm[0] = T[0]
        Tm[-1] = T[-1]
        T = Tm
    T[0] = 0.0
    T[-1] = 0.0
    G = np.fft.rfft(T)
    gmax = np.abs(G).max()
    if gmax <= 0:
        return None
    Gc = np.maximum(G, 1e-10 * gmax)
    f0 = np.fft.irfft(np.sqrt(Gc), n=T.size)
    f0 = np.clip(f0, 0, None)
    if f0.size > 1:
        f0 = f0[:-1]
    if f0.sum() <= 0:
        return None
    return _rescale(f0)


def _polish(f0, deadline):
    h = f0
    if time.process_time() < deadline - 0.5:
        h = _lbfgs_all_pos(h, 250, deadline - 0.5, beta=0.0)
    ladder = [(0.05, 64, 1e7), (0.15, 128, 1e8), (0.40, 256, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=frac, extra=extra)
        h = _lbfgs_block(h, win, 250, deadline - 0.5, beta=beta)
    if time.process_time() < deadline - 0.5:
        h = _refine_knots(h, 300, deadline - 0.5)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # --- New idea: resample to a different resolution and re-optimize.
    # A different discretisation breaks the local optimum that traps the
    # start at a fixed N; then a short polish at the new N can push R up.
    alt_candidates = []
    baseN = best.size
    for fac in (1.5, 0.7, 2.0, 0.5):
        if time.process_time() >= deadline - 3.0:
            break
        N2 = int(np.clip(int(baseN * fac), 512, 900000))
        if N2 == baseN:
            continue
        try:
            h2 = _resample(best, N2)
        except Exception:
            continue
        if h2.sum() <= 0:
            continue
        h2 = _rescale(h2)
        r0 = R_of(h2)
        print("resample N=%d R=%.7f" % (N2, r0))
        hp = _polish(h2, min(deadline - 1.0,
                             time.process_time() + (deadline - time.process_time()) * 0.4))
        rp = R_of(hp)
        print("  polished R=%.7f" % rp)
        if rp > bestR + 1e-13:
            best, bestR = hp.copy(), rp
        if rp > start_bestR - 1e-6:
            alt_candidates.append((rp, hp))

    # Spectral inversion experiment (as before)
    Lf = _knots(best)
    mx = Lf.max()
    inv_best = None
    inv_bestR = -1.0
    for c in [0.985, 0.95]:
        if time.process_time() >= deadline - 2.0:
            break
        f0 = _spectral_invert(Lf, c, mx)
        if f0 is None:
            continue
        rraw = R_of(f0)
        print("invert c=%.3f R_raw=%.7f N=%d" % (c, rraw, f0.size))
        hp = _polish(f0, min(deadline - 1.0,
                             time.process_time() + (deadline - time.process_time()) * 0.5))
        rp = R_of(hp)
        print("c=%.3f R_final=%.7f" % (c, rp))
        if rp > inv_bestR:
            inv_best, inv_bestR = hp.copy(), rp

    if inv_best is not None and inv_bestR > bestR + 1e-13:
        best, bestR = inv_best.copy(), inv_bestR

    if time.process_time() < deadline - 1.0:
        best, bestR = run_cycle(best, bestR, deadline - 0.8)
        print("cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    # Return the best genuinely-different construction as an alternative.
    alt_candidates.sort(key=lambda p: -p[0])
    if alt_candidates and alt_candidates[0][0] > start_bestR - 1e-6:
        out["alternative"] = alt_candidates[0][1]
    elif inv_best is not None and inv_bestR > start_bestR - 1e-6:
        out["alternative"] = inv_best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    """Gradient of log R w.r.t. h (no 2/s term needed for ranking edits)."""
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    """Return list of (pred_delta, a, b, kind) candidate edits, ranked."""
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []  # (pred, a, b, kind)
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _pinned_for(kind, a, b):
    """Indices to pin (exclude from free set) during first repair passes."""
    if kind == 'split':
        return [a]
    if kind in ('transfer', 'death'):
        return [a]
    if kind == 'birth':
        return [a]
    return []


def _repair_edit_frozen(h2, a, b, kind, deadline):
    """Frozen-donor repair: pin donor cells through first two passes."""
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    window = np.arange(lo, hi + 1)
    pinned = set(_pinned_for(kind, a, b))
    free1 = np.array([i for i in window if i not in pinned], dtype=int)
    if free1.size > 0:
        h2 = _lbfgs_block(h2, free1, 40, deadline, beta=0.0)
        h2 = _lbfgs_block(h2, free1, 25, deadline, beta=1e7)
    # free polish of full window
    h2 = _lbfgs_block(h2, window, 20, deadline, beta=0.0)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    total_acc = 0
    consec_reject = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        n_screen = len(cands)
        # cheap filter: raw R_of on top 24 by predicted delta
        top = cands[:24]
        raw = []
        for pred, a, b, kind in top:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            r2 = R_of(h2)
            raw.append((r2, pred, a, b, kind))
        raw.sort(key=lambda t: -t[0])
        to_repair = raw[:8]
        best_cand = None
        best_cand_R = bestR
        best_realized = 0.0
        n_rep = 0
        for r2_raw, pred, a, b, kind in to_repair:
            if time.process_time() >= deadline - 0.5:
                break
            n_rep += 1
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit_frozen(h2, a, b, kind, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
                best_realized = r2 - bestR
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
            total_acc += 1
            consec_reject = 0
            print("round %d: screened=%d repaired=%d ACCEPT realised=%.3e R=%.7f acc=%d" %
                  (round_no, n_screen, n_rep, best_realized, bestR, total_acc))
        else:
            consec_reject += 1
            print("round %d: screened=%d repaired=%d no accept R=%.7f consec=%d" %
                  (round_no, n_screen, n_rep, bestR, consec_reject))
            if consec_reject >= 5:
                if time.process_time() < deadline - 1.0:
                    st, r = _mini_cycle(best, bestR, deadline - 0.5)
                    if r > bestR + 1e-13:
                        best, bestR = st, r
                        print("  mini_cycle R=%.7f" % bestR)
                        consec_reject = 0
                        continue
                break
    print("edit loop: rounds=%d accepted=%d" % (round_no, total_acc))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # reserve last 8 s for run_cycle polish
    edit_deadline = deadline - 8.0
    if time.process_time() < edit_deadline - 1.0:
        best, bestR = _greedy_edit_loop(best, bestR, edit_deadline, rng)
        print("edit loop done R=%.7f" % bestR)

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final polish R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
