        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    total_acc = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        n_screen = len(cands)
        best_pred = cands[0][0]
        best_cand = None
        best_cand_R = bestR
        best_realized = 0.0
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
                best_realized = r2 - bestR
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
            total_acc += 1
            print("round %d: screened=%d pred=%.3e realized=%.3e R=%.7f" %
                  (round_no, n_screen, best_pred, best_realized, bestR))
        else:
            print("round %d: screened=%d pred=%.3e no accept R=%.7f" %
                  (round_no, n_screen, best_pred, bestR))
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    print("  mini_cycle R=%.7f" % bestR)
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    print("  mini_cycle R=%.7f" % bestR)
    print("edit loop: rounds=%d accepted=%d" % (round_no, total_acc))
    return best, bestR


def _block_multistart(best, bestR, deadline, rng):
    """Block-coordinate descent with genuine multi-start inside each window."""
    n = best.size
    Lf = _knots(best)
    mx = Lf.max()
    peak_idx = np.flatnonzero(Lf >= 0.97 * mx) if mx > 0 else np.array([0])
    pos_idx = np.flatnonzero(best > 0)
    if pos_idx.size == 0:
        return best, bestR

    windows_tried = 0
    accepted = 0
    best_gain = 0.0
    last_report = 0

    while time.process_time() < deadline - 1.0:
        windows_tried += 1
        w = int(rng.choice([64, 128, 256]))
        if rng.random() < 0.5:
            c = int(rng.choice(pos_idx))
        else:
            j = int(rng.choice(peak_idx))
            c = j // 2
        lo = max(0, c - w // 2)
        hi = min(n - 1, lo + w - 1)
        lo = max(0, hi - w + 1)
        free = np.arange(lo, hi + 1)
        ww = free.size

        block_best = None
        block_bestR = bestR
        for k in range(8):
            if time.process_time() >= deadline - 1.0:
                break
            h2 = best.copy()
            noise = np.exp(np.clip(rng.normal(0.0, 0.6, ww), -3.0, 3.0))
            h2[free] = h2[free] * noise
            if rng.random() < 0.3:
                posf = free[h2[free] > 0]
                if posf.size > 0:
                    nz = max(1, int(0.2 * posf.size))
                    kill = rng.choice(posf, size=nz, replace=False)
                    h2[kill] = 0.0
            h2 = np.clip(h2, 0.0, None)
            if h2.sum() <= 0:
                continue
            h2 = _lbfgs_block(h2, free, 20, deadline, beta=0.0)
            r2 = R_of(h2)
            if r2 > block_bestR + 1e-13:
                block_best = h2
                block_bestR = r2

        if block_best is not None and block_bestR > bestR + 1e-12:
            # polish with beta
            h2 = _lbfgs_block(block_best, free, 40, deadline, beta=1e7)
            r2 = R_of(h2)
            if r2 > block_bestR - 1e-13:
                cand, candR = h2, r2
            else:
                cand, candR = block_best, block_bestR
            if candR > bestR + 1e-12:
                gain = candR - bestR
                best, bestR = cand, candR
                accepted += 1
                if gain > best_gain:
                    best_gain = gain
                if accepted - last_report >= 10:
                    last_report = accepted
                    print("block-ms: windows=%d accepted=%d R=%.7f best_gain=%.3e" %
                          (windows_tried, accepted, bestR, best_gain))

        if windows_tried % 40 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    print("  mini_cycle R=%.7f" % bestR)

    print("block-ms done: windows=%d accepted=%d R=%.7f best_gain=%.3e" %
          (windows_tried, accepted, bestR, best_gain))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Reserve ~8s at the end for run_cycle.
    reserve = min(8.0, 0.15 * budget_seconds)
    ms_deadline = deadline - reserve

    if time.process_time() < ms_deadline - 2.0:
        best, bestR = _block_multistart(best, bestR, ms_deadline, rng)
        print("block multistart R=%.7f" % bestR)

    if time.process_time() < deadline - 1.0:
        best, bestR = _greedy_edit_loop(best, bestR, deadline - 1.0, rng)
        print("edit loop done R=%.7f" % bestR)

    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.3:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.3)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    total_acc = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        n_screen = len(cands)
        best_pred = cands[0][0]
        best_cand = None
        best_cand_R = bestR
        best_realized = 0.0
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
                best_realized = r2 - bestR
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
            total_acc += 1
            print("round %d: screened=%d pred=%.3e realized=%.3e R=%.7f" %
                  (round_no, n_screen, best_pred, best_realized, bestR))
        else:
            print("round %d: screened=%d pred=%.3e no accept R=%.7f" %
                  (round_no, n_screen, best_pred, bestR))
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    print("  mini_cycle R=%.7f" % bestR)
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    print("  mini_cycle R=%.7f" % bestR)
    print("edit loop: rounds=%d accepted=%d" % (round_no, total_acc))
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    """Targeted dip-filling: find interior minima of Lf, try transfers/births
    with exact 1-D line search on R, accept best with a small local polish."""
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    # interior local minima of Lf
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1  # index into Lf
    if idx.size == 0:
        return best, bestR
    # filter by depth
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()

    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None  # (a, b, t, kind)

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            # transfers
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            # births
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    # one local polish around a
    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    # polish reverted the gain; still accept if raw was positive
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # quick base cycle to establish a good starting point
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # main loop: alternate dip moves with mini_cycle every ~30 s
    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    loop_start = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    print("  mini_cycle R=%.7f" % bestR)
        if time.process_time() - loop_start > 1e9:
            break
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    # last 6 s: run_cycle
    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64), (0.10, 64), (0.25, 128),
              (0.40, 256), (0.60, 512)]
    for frac, extra in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # multiple passes of full + windowed refinement until time runs out
    it = 0
    while time.process_time() < deadline - 0.5:
        it += 1
        prev = bestR
        best, bestR = run_cycle(best, bestR, deadline - 0.3)
        print("cycle %d R=%.7f" % (it, bestR))
        if bestR <= prev + 1e-12 and it >= 3:
            break

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _resample(h, N):
    n = h.size
    if n == N:
        return h.copy()
    xp = (np.arange(n) + 0.5) / n
    xq = (np.arange(N) + 0.5) / N
    return np.interp(xq, xp, h)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _smooth_shrink(h, factor, thr_frac):
    """NEW: shrink small heights toward zero to create true zeros,
    then re-optimize from that sparser support."""
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = h.max()
    out = h.copy()
    out[out < thr_frac * mx] *= factor
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    if time.process_time() < deadline - 1.5:
        best, bestR = run_cycle(best, bestR, deadline - 1.5)
        print("after cycle1 R=%.7f" % bestR)

    # NEW Phase: support sparsification. The optimum is a "spiky" shape:
    # aggressive shrinking of small heights plus re-optimization on the
    # existing (large) support often reshapes the tail usefully.
    for thr, fac in [(0.02, 0.1), (0.05, 0.05), (0.10, 0.02)]:
        if time.process_time() >= deadline - 2.0:
            break
        hs = _smooth_shrink(best, fac, thr)
        hs = _rescale(hs)
        hs, rs = run_cycle(hs, R_of(hs), deadline - 2.0)
        print("shrink thr=%.2f R=%.7f" % (thr, rs))
        if rs > bestR + 1e-13:
            best, bestR = hs.copy(), rs

    # Local window polish.
    if time.process_time() < deadline - 1.0:
        n = best.size
        step = max(256, n // 16)
        for s in range(0, n, step):
            if time.process_time() >= deadline - 1.0:
                break
            win = np.arange(s, min(n, s + 2 * step))
            ht = _lbfgs_block(best, win, 150, deadline - 1.0, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r

    # Final full polish.
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(_seed_zeros(best), 500, deadline - 0.6, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-5:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR, 0.0


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


# ---- Level-set / band shaping move -------------------------------------
# The optimum seems to want a wide flat top in f*f. We push the knots Lf
# toward a target that flattens a wide band around the max, via a soft
# surrogate: -log(num) + 2 log s + log(softmax_beta(Lf)).  This is the existing
# beta trick but we additionally reweight so the band is broad, and we use a
# "min-of-knots" style softmin to lift the notch below the peak.

def _fun_grad_softmin(h, beta):
    """Maximize num / (s^2 * softmin_beta(Lf)).  softmin approximates min,
    penalizing low knots, which pushes the whole profile up toward the max."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    # softmin over interior knots
    Li = Lf[1:-1]
    mn = Li.min()
    e = np.exp(np.clip(-beta * (Li - mn), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z  # weight on small knots
    sm = mn - np.log(Z) / beta  # <= mn, approximates min
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[1:-1] += -w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _lbfgs_softmin(h0, maxiter, deadline, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_softmin(hh, beta)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_softmin_block(h0, free, maxiter, deadline, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_softmin(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _softmin_cycle(best, bestR, deadline):
    """Dedicated pass: gently flatten the f*f profile via softmin surrogate,
    then restore exact R with a full L-BFGS polish."""
    for beta in (50.0, 200.0, 800.0):
        if time.process_time() >= deadline - 0.6:
            break
        ht = _lbfgs_softmin(best, 200, deadline - 0.6, beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    # polish with true objective
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    # block softmin on peak window
    if time.process_time() < deadline - 0.5:
        win = _peak_window(best, pad_frac=0.3, extra=128)
        ht = _lbfgs_softmin_block(best, win, 200, deadline - 0.5, 300.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW: softmin-shaping pass first, aimed at flattening f*f profile
    if time.process_time() < deadline - 4.0:
        best, bestR = _softmin_cycle(best, bestR, deadline - 4.0)
        print("softmin cycle R=%.7f" % bestR)

    # quick base cycle
    if time.process_time() < deadline - 3.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 3.0)
        print("base cycle R=%.7f" % bestR)

    # alternate softmin cycles and standard mini cycles until time runs out
    last_print = time.process_time()
    while time.process_time() < deadline - 1.5:
        prevR = bestR
        best, bestR = _softmin_cycle(best, bestR, deadline - 1.5)
        if time.process_time() < deadline - 1.2:
            st, r = _mini_cycle(best, bestR, deadline - 1.2)
            if r > bestR + 1e-13:
                best, bestR = st, r
        if bestR - prevR < 1e-10:
            # no progress from softmin; fall back to a full run_cycle
            if time.process_time() < deadline - 1.2:
                st, r, _ = run_cycle(best, bestR, deadline - 1.2)
                if r > bestR + 1e-13:
                    best, bestR = st, r
        if time.process_time() - last_print > 8.0:
            last_print = time.process_time()
            print("iter R=%.7f band01 %.2f%%" %
                  (bestR, 100.0 * _band_frac(best, 0.001)))

    # final polish
    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

