# ---- NEW: exact-peak (subgradient) refinement on the support of the knot
# maximum. The true objective's nonsmoothness at the peak is the main
# bottleneck. Instead of guessing which knot is the max, we fix a set of
# near-maximal knots, use a soft-max over them with growing beta, and run
# a shrinking-window block polish. This directly attacks the last 1e-6.

def _fun_grad_band(h, beta, band):
    """Softmax restricted to a chosen band of knots (indices into Lf)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lb = Lf[band]
    mx = Lb.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lb - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num
    gLf[band] += w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _lbfgs_band(h0, band, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    band = np.asarray(band, dtype=int)

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_band(hh, beta, band)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _peak_band(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.array([0])
    idx = np.flatnonzero(Lf >= (1.0 - tol) * mx)
    if idx.size == 0:
        idx = np.array([int(np.argmax(Lf))])
    return idx


def _peak_band_cycle(best, bestR, deadline):
    """Refine with softmax over the near-maximal knot band, tightening tol."""
    for tol, beta, it in [(0.02, 2e3, 400), (0.005, 2e4, 400),
                          (0.002, 2e5, 400), (0.001, 1e6, 500)]:
        if time.process_time() >= deadline - 0.5:
            break
        band = _peak_band(best, tol)
        ht = _lbfgs_band(best, band, beta, it, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        # polish with true objective after each band tightening
        if time.process_time() < deadline - 0.5:
            hp = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
            r = R_of(hp)
            if r > bestR + 1e-13:
                best, bestR = hp.copy(), r
    return best, bestR


# ---- NEW: coordinate-wise height bumping on the support of f.
# A cheap local random search / pattern move that can escape tiny flat
# regions L-BFGS cannot. We only try a few hundred trials within budget.

def _random_bump(best, bestR, deadline, trials=400):
    h = best.copy()
    n = h.size
    if n == 0:
        return best, bestR
    supp = np.flatnonzero(h > 0)
    if supp.size == 0:
        return best, bestR
    rng = np.random.default_rng(12345)
    step = 0.02 * h.max()
    for _ in range(trials):
        if time.process_time() >= deadline - 0.3:
            break
        i = int(supp[rng.integers(0, supp.size)])
        delta = step * (rng.random() * 2.0 - 1.0)
        old = h[i]
        nh = max(0.0, old + delta)
        if nh == old:
            continue
        h[i] = nh
        r = R_of(h)
        if r > bestR + 1e-13:
            bestR = r
            best = h.copy()
        else:
            h[i] = old
        # occasionally shrink step
        if rng.random() < 0.01:
            step *= 0.9
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW: peak-band refinement first, directly attacking the nonsmooth max
    if time.process_time() < deadline - 4.0:
        best, bestR = _peak_band_cycle(best, bestR, deadline - 4.0)
        print("peak-band cycle R=%.7f" % bestR)

    # quick base cycle
    if time.process_time() < deadline - 3.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 3.0)
        print("base cycle R=%.7f" % bestR)

    # alternate peak-band refinement and standard mini cycles
    last_print = time.process_time()
    while time.process_time() < deadline - 1.5:
        prevR = bestR
        best, bestR = _peak_band_cycle(best, bestR, deadline - 1.5)
        if time.process_time() < deadline - 1.2:
            st, r = _mini_cycle(best, bestR, deadline - 1.2)
            if r > bestR + 1e-13:
                best, bestR = st, r
        if bestR - prevR < 1e-10:
            if time.process_time() < deadline - 1.2:
                st, r, _ = run_cycle(best, bestR, deadline - 1.2)
                if r > bestR + 1e-13:
                    best, bestR = st, r
        if time.process_time() - last_print > 8.0:
            last_print = time.process_time()
            print("iter R=%.7f band01 %.2f%%" %
                  (bestR, 100.0 * _band_frac(best, 0.001)))

    # final polish: exact objective plus tiny random bumps
    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.3:
        best, bestR = _random_bump(best, bestR, deadline - 0.3, trials=300)
        print("bump R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _report(tag, h, R):
    print("%s R=%.7f N=%d" % (tag, R, h.size))


def _hop(h, bestR, deadline, rng):
    n = h.size
    if n < 8:
        return h, bestR
    wlen = int(rng.integers(max(8, n // 20), max(16, n // 4)))
    wlen = min(wlen, n)
    lo = int(rng.integers(0, n - wlen + 1))
    hi = lo + wlen
    hp = h.copy()
    amp = rng.uniform(0.02, 0.15)
    noise = 1.0 + amp * rng.standard_normal(wlen)
    hp[lo:hi] = np.clip(hp[lo:hi] * noise, 0.0, None)
    hp = _rescale(hp)
    rp = R_of(hp)
    halo = 64
    free = np.arange(max(0, lo - halo), min(n, hi + halo))
    if free.size > 0 and time.process_time() < deadline - 0.5:
        ht = _lbfgs_block(hp, free, 200, deadline - 0.5, beta=1e7)
        rt = R_of(ht)
        if rt > rp:
            hp, rp = ht, rt
    if rp > bestR + 1e-13:
        return hp, rp
    return h, bestR


def _mutate(h, bestR, deadline, rng):
    n = h.size
    hp = h.copy()
    blen = int(rng.integers(max(8, n // 40), max(16, n // 8)))
    blen = min(blen, n)
    lo = int(rng.integers(0, n - blen + 1))
    hi = lo + blen
    hp[lo:hi] = 0.0
    hp = _rescale(hp)
    rp = R_of(hp)
    halo = 128
    free = np.arange(max(0, lo - halo), min(n, hi + halo))
    if free.size > 0 and time.process_time() < deadline - 0.5:
        ht = _lbfgs_block(hp, free, 300, deadline - 0.5, beta=0.0)
        rt = R_of(ht)
        if rt > rp:
            hp, rp = ht, rt
    if rp > bestR + 1e-13:
        return hp, rp
    return h, bestR


def _refine_local(h, bestR, deadline, rng, n_iter):
    """New idea: coordinate-descent style local polish on free support.

    Key change vs p1108: instead of only optimising a peak-centered window,
    we iteratively optimise the *entire* support region (where h>0 or near it)
    using beta-smoothed max over several decreasing betas. This attacks the
    known bottleneck that R is limited by the width of the ||f*f||_inf plateau.
    """
    for _ in range(n_iter):
        if time.process_time() >= deadline - 0.6:
            break
        # Find all free indices: positive entries plus their neighbours.
        pos = np.flatnonzero(h > 1e-9)
        if pos.size == 0:
            break
        lo = max(0, pos.min() - 8)
        hi = min(h.size, pos.max() + 8)
        free = np.arange(lo, hi)
        if free.size > 60000:
            # Split into chunks to keep per-call cost bounded.
            step = 40000
            improved = False
            for st in range(lo, hi, step):
                if time.process_time() >= deadline - 0.6:
                    break
                en = min(hi, st + step + 200)
                sub = np.arange(st, en)
                ht = _lbfgs_block(h, sub, 150, deadline - 0.6, beta=1e8)
                rt = R_of(ht)
                if rt > bestR + 1e-14:
                    h, bestR = ht, rt
                    improved = True
            if not improved:
                break
        else:
            ht = _lbfgs_block(h, free, 200, deadline - 0.6, beta=1e8)
            rt = R_of(ht)
            if rt > bestR + 1e-14:
                h, bestR = ht, rt
            else:
                ht = _lbfgs_block(h, free, 200, deadline - 0.6, beta=0.0)
                rt = R_of(ht)
                if rt > bestR + 1e-14:
                    h, bestR = ht, rt
                else:
                    break
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Stage (a): full polish + beta smoothing.
    if time.process_time() < deadline - 1.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 1.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 1.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 1.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    _report("(a)", best, bestR)

    # Stage (b): peak-window refinements at multiple scales.
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        if win.size > 40000:
            continue
        ht = _lbfgs_block(best, win, 250, deadline - 1.0, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    _report("(b)", best, bestR)

    # Stage (c): NEW — support-wide beta-swept local polish.
    rng = np.random.default_rng(987654321)
    best, bestR = _refine_local(best, bestR, deadline, rng, n_iter=6)
    _report("(c)", best, bestR)

    # Stage (d): hop/mutate loop with acceptance.
    n_hops = 0
    n_accept = 0
    while time.process_time() < deadline - 1.2:
        n_hops += 1
        if n_hops % 3 == 0:
            hnew, rnew = _mutate(best, bestR, deadline - 1.2, rng)
        else:
            hnew, rnew = _hop(best, bestR, deadline - 1.2, rng)
        if rnew > bestR + 1e-13:
            best, bestR = hnew, rnew
            n_accept += 1
        if n_hops > 400:
            break
    print("(d) hops=%d accepted=%d" % (n_hops, n_accept))
    _report("(d)", best, bestR)

    # Stage (e): final broad polish.
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 500, deadline - 0.6, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        hs = _seed_zeros(best)
        ht = _lbfgs_all_pos(hs, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    _report("final", best, bestR)

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

