    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _rebalance(h, deadline):
    """Key improvement: resample support onto uniform grid with local L-BFGS."""
    h = np.clip(h, 0, None)
    return h


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()
    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    stats['best_raw'] = max(stats['best_raw'], best_r - bestR)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


# ---------------- Key new idea: fine-grid resampling ----------------

def _resample(h, factor):
    """Resample step function h onto a grid `factor` times finer, preserving
    the piecewise-constant function exactly (as a finer step function)."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    m = n * factor
    # each fine cell i covers [i/m, (i+1)/m) in [0,1]; original cell j covers [j/n,(j+1)/n)
    # mass of fine cell i = h[j] where j = floor(i/factor)
    idx = np.arange(m) // factor
    return h[idx]


def _subsample(h, factor):
    """Coarsen by factor (averaging blocks) — used only for coarse refinement."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    m = n // factor
    if m < 1:
        return h
    return h[:m * factor].reshape(m, factor).mean(axis=1)


def _fine_refine(best, bestR, deadline, factor=2, budget_frac=0.5):
    """Resample onto finer grid, then L-BFGS on all cells."""
    if time.process_time() >= deadline - 1.0:
        return best, bestR
    hf = _resample(best, factor)
    rf = R_of(hf)
    # resampling doesn't change R (exact representation), but let's verify
    if rf < bestR - 1e-6:
        return best, bestR
    sub_deadline = deadline - 0.5
    ht = _lbfgs_all_pos(hf, 400, sub_deadline, beta=0.0)
    r = R_of(ht)
    if r > bestR + 1e-13:
        return ht, r
    return best, bestR


def _multi_scale_refine(best, bestR, deadline):
    """Try resampling at several scales and take the best."""
    if time.process_time() >= deadline - 1.0:
        return best, bestR
    results = []
    for factor in (2, 3):
        if time.process_time() >= deadline - 1.0:
            break
        sub_dl = deadline - (0.5 if factor == 2 else 0.3)
        hf = _resample(best, factor)
        ht = _lbfgs_all_pos(hf, 300, sub_dl, beta=0.0)
        r = R_of(ht)
        results.append((r, ht))
    if not results:
        return best, bestR
    results.sort(key=lambda t: -t[0])
    r, ht = results[0]
    if r > bestR + 1e-13:
        return ht, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- Key new idea: multi-scale resampling refine ----
    if time.process_time() < deadline - 20.0:
        try:
            ht, rt = _multi_scale_refine(best, bestR, deadline - 15.0)
            if rt > bestR + 1e-13:
                best, bestR = ht, rt
                print("multiscale wins: R=%.7f (N=%d)" % (bestR, best.size))
                # save as alternative
                alt_cand = best.copy()
                altR = bestR
            else:
                print("multiscale no change: %.7f" % rt)
        except Exception as e:
            print("multiscale failed: %s" % e)

    # ---- Base machinery ----
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()

    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


# ---------------- Experiment: affine warp + continuous split ----------------

def _find_runs(h, peak_thresh_frac=0.5):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    pos = h > 0
    if not pos.any():
        return []
    gmax = h.max()
    thr = peak_thresh_frac * gmax
    runs = []
    i = 0
    while i < n:
        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            if h[i:j + 1].max() >= thr:
                runs.append(np.arange(i, j + 1))
            i = j + 1
        else:
            i += 1
    return runs


def _warp(h, runs, s, r):
    """Affine warp of each run: cell j -> center j + s_k + r_k*(j - c_k),
    c_k = run center. Mass m_j spread linearly onto fine cells."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    out = h.copy()
    for k, cells in enumerate(runs):
        sk = float(s[k]); rk = float(r[k])
        masses = h[cells]
        out[cells] -= masses
        ck = 0.5 * (cells[0] + cells[-1])
        for j, m in zip(cells, masses):
            if m == 0.0:
                continue
            center = j + sk + rk * (j - ck)
            i0 = int(np.floor(center - 1.0))
            i1 = int(np.ceil(center + 1.0))
            for i in range(i0, i1 + 1):
                if i < 0 or i >= n:
                    continue
                w = 1.0 - abs(i - center)
                if w > 0.0:
                    out[i] += m * w
    return np.clip(out, 0.0, None)


def _warp_grad(h, runs, s, r, dRdh):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    K = len(runs)
    gs = np.zeros(K)
    gr = np.zeros(K)
    for k, cells in enumerate(runs):
        sk = float(s[k]); rk = float(r[k])
        masses = h[cells]
        ck = 0.5 * (cells[0] + cells[-1])
        acc_s = 0.0
        acc_r = 0.0
        for j, m in zip(cells, masses):
            if m == 0.0:
                continue
            center = j + sk + rk * (j - ck)
            i0 = int(np.floor(center - 1.0))
            i1 = int(np.ceil(center + 1.0))
            for i in range(i0, i1 + 1):
                if i < 0 or i >= n:
                    continue
                d = i - center
                if abs(d) < 1.0:
                    dw_dd = -np.sign(d)
                    # dcenter/ds = 1, dcenter/dr = (j - ck)
                    acc_s += dRdh[i] * m * dw_dd * (-1.0)
                    acc_r += dRdh[i] * m * dw_dd * (-(j - ck))
        gs[k] = acc_s
        gr[k] = acc_r
    return gs, gr


def _warp_opt(h, runs, s0, r0, maxiter, deadline, free_heights=False,
              height_cells=None):
    if time.process_time() >= deadline - 0.3:
        return h, s0, r0
    K = len(runs)
    if K == 0:
        return h, s0, r0
    s = np.clip(s0.copy(), -0.5, 0.5)
    r = np.clip(r0.copy(), 0.5, 1.5)
    h = np.clip(h, 0, None)

    if free_heights and height_cells is not None:
        hcells = np.asarray(height_cells, dtype=int)
        x0 = np.concatenate([s, r, h[hcells]])

        def unpack(x):
            ss = np.clip(x[:K], -0.5, 0.5)
            rr = np.clip(x[K:2 * K], 0.5, 1.5)
            hh = h.copy()
            hh[hcells] = np.clip(x[2 * K:], 0.0, None)
            return ss, rr, hh

        def f(x):
            ss, rr, hh = unpack(x)
            h2 = _warp(hh, runs, ss, rr)
            val, g2 = _fun_grad(h2)
            gs, gr = _warp_grad(hh, runs, ss, rr, g2)
            gh = g2[hcells]
            return val, np.concatenate([gs, gr, gh])

        bounds = [(-0.5, 0.5)] * K + [(0.5, 1.5)] * K + [(0.0, None)] * hcells.size
    else:
        x0 = np.concatenate([s, r])

        def f(x):
            ss = np.clip(x[:K], -0.5, 0.5)
            rr = np.clip(x[K:], 0.5, 1.5)
            h2 = _warp(h, runs, ss, rr)
            val, g2 = _fun_grad(h2)
            gs, gr = _warp_grad(h, runs, ss, rr, g2)
            return val, np.concatenate([gs, gr])

        bounds = [(-0.5, 0.5)] * K + [(0.5, 1.5)] * K

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h, s0, r0
    if res is None:
        return h, s0, r0
    if free_heights and height_cells is not None:
        ss, rr, hh = unpack(res.x)
        return _warp(hh, runs, ss, rr), ss, rr
    ss = np.clip(res.x[:K], -0.5, 0.5)
    rr = np.clip(res.x[K:], 0.5, 1.5)
    return _warp(h, runs, ss, rr), ss, rr


def _split(h, runs, d, f):
    """For each run k, split its mass: fraction f_k moved to a new cell
    offset d_k (sub-cell) to the right of the run's peak cell."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    out = h.copy()
    for k, cells in enumerate(runs):
        dk = float(d[k]); fk = float(f[k])
        if fk <= 0.0:
            continue
        masses = h[cells]
        pk = cells[int(np.argmax(masses))]
        tot = masses.sum()
        move = fk * tot
        # remove move from run proportionally
        if tot <= 0:
            continue
        out[cells] -= masses * (move / tot)
        center = pk + dk
        i0 = int(np.floor(center - 1.0))
        i1 = int(np.ceil(center + 1.0))
        for i in range(i0, i1 + 1):
            if i < 0 or i >= n:
                continue
            w = 1.0 - abs(i - center)
            if w > 0.0:
                out[i] += move * w
    return np.clip(out, 0.0, None)


def _split_grad(h, runs, d, f, dRdh):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    K = len(runs)
    gd = np.zeros(K)
    gf = np.zeros(K)
    for k, cells in enumerate(runs):
        dk = float(d[k]); fk = float(f[k])
        masses = h[cells]
        pk = cells[int(np.argmax(masses))]
        tot = masses.sum()
        if tot <= 0:
            continue
        move = fk * tot
        # gradient wrt move: sum over target cells dRdh * w
        # gradient wrt f = tot * (that)
        center = pk + dk
        i0 = int(np.floor(center - 1.0))
        i1 = int(np.ceil(center + 1.0))
        acc_move = 0.0
        acc_d = 0.0
        for i in range(i0, i1 + 1):
            if i < 0 or i >= n:
                continue
            dd = i - center
            w = 1.0 - abs(dd)
            if w > 0.0:
                acc_move += dRdh[i] * w
                if abs(dd) < 1.0:
                    dw_dd = -np.sign(dd)
                    acc_d += dRdh[i] * move * dw_dd * (-1.0)
        # removal from run: subtract move/tot * masses from cells
        # d/d(move) of removal term: -sum dRdh[cells]*masses/tot
        rem = 0.0
        for j, m in zip(cells, masses):
            rem += dRdh[j] * m
        rem /= tot
        gmove = acc_move - rem
        gf[k] = tot * gmove
        gd[k] = acc_d
    return gd, gf


def _split_opt(h, runs, d0, f0, maxiter, deadline, free_heights=False,
               height_cells=None):
    if time.process_time() >= deadline - 0.3:
        return h, d0, f0
    K = len(runs)
    if K == 0:
        return h, d0, f0
    d = np.clip(d0.copy(), 0.0, 8.0)
    f = np.clip(f0.copy(), 0.0, 0.9)
    h = np.clip(h, 0, None)

    if free_heights and height_cells is not None:
        hcells = np.asarray(height_cells, dtype=int)
        x0 = np.concatenate([d, f, h[hcells]])

        def unpack(x):
            dd = np.clip(x[:K], 0.0, 8.0)
            ff = np.clip(x[K:2 * K], 0.0, 0.9)
            hh = h.copy()
            hh[hcells] = np.clip(x[2 * K:], 0.0, None)
            return dd, ff, hh

        def f_(x):
            dd, ff, hh = unpack(x)
            h2 = _split(hh, runs, dd, ff)
            val, g2 = _fun_grad(h2)
            gd, gf = _split_grad(hh, runs, dd, ff, g2)
            gh = g2[hcells]
            return val, np.concatenate([gd, gf, gh])

        bounds = [(0.0, 8.0)] * K + [(0.0, 0.9)] * K + [(0.0, None)] * hcells.size
    else:
        x0 = np.concatenate([d, f])

        def f_(x):
            dd = np.clip(x[:K], 0.0, 8.0)
            ff = np.clip(x[K:], 0.0, 0.9)
            h2 = _split(h, runs, dd, ff)
            val, g2 = _fun_grad(h2)
            gd, gf = _split_grad(h, runs, dd, ff, g2)
            return val, np.concatenate([gd, gf])

        bounds = [(0.0, 8.0)] * K + [(0.0, 0.9)] * K

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f_, x0, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h, d0, f0
    if res is None:
        return h, d0, f0
    if free_heights and height_cells is not None:
        dd, ff, hh = unpack(res.x)
        return _split(hh, runs, dd, ff), dd, ff
    dd = np.clip(res.x[:K], 0.0, 8.0)
    ff = np.clip(res.x[K:], 0.0, 0.9)
    return _split(h, runs, dd, ff), dd, ff


def _alternating_experiment(base, baseR, deadline, rng):
    best = np.clip(base, 0, None).copy()
    bestR = baseR
    alt_h = best.copy()
    altR = bestR

    s = None; r = None; d = None; f = None

    for rnd in range(4):
        if time.process_time() >= deadline - 10.0:
            break
        runs = _find_runs(best, 0.5)
        K = len(runs)
        if K == 0:
            break
        if s is None or s.size != K:
            s = np.zeros(K); r = np.ones(K)
            d = np.zeros(K); f = np.zeros(K)
        hcells = np.concatenate(runs)

        round_start = best.copy()
        round_startR = bestR

        # (a) warp + heights
        h1, s1, r1 = _warp_opt(best, runs, s, r, 200, deadline - 8.0,
                               free_heights=True, height_cells=hcells)
        r1v = R_of(h1)
        if r1v > bestR + 1e-13:
            best, bestR = h1, r1v
            s, r = s1, r1
        else:
            s, r = s, r

        # (b) split + heights
        runs2 = _find_runs(best, 0.5)
        if len(runs2) != K:
            d = np.zeros(len(runs2)); f = np.zeros(len(runs2))
        hcells2 = np.concatenate(runs2) if runs2 else np.array([], dtype=int)
        if len(runs2) > 0:
            h2, d2, f2 = _split_opt(best, runs2, d, f, 200, deadline - 6.0,
                                    free_heights=True, height_cells=hcells2)
            r2v = R_of(h2)
            if r2v > bestR + 1e-13:
                best, bestR = h2, r2v
                d, f = d2, f2

        # (c) full polish
        if time.process_time() < deadline - 4.0:
            ht = _lbfgs_all_pos(best, 300, deadline - 4.0, beta=0.0)
            rv = R_of(ht)
            if rv > bestR + 1e-13:
                best, bestR = ht, rv
        if time.process_time() < deadline - 4.0:
            win = _peak_window(best, pad_frac=0.25, extra=128)
            ht = _lbfgs_block(best, win, 200, deadline - 4.0, beta=1e7)
            rv = R_of(ht)
            if rv > bestR + 1e-13:
                best, bestR = ht, rv
        if time.process_time() < deadline - 4.0:
            best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)

        if bestR > altR + 1e-13:
            alt_h, altR = best.copy(), bestR

        max_s = float(np.max(np.abs(s))) if s is not None and s.size else 0.0
        max_r = float(np.max(np.abs(r - 1.0))) if r is not None and r.size else 0.0
        max_d = float(np.max(d)) if d is not None and d.size else 0.0
        nsplit = int(np.sum(f > 0.1)) if f is not None and f.size else 0
        print("alt round %d: R=%.7f runs=%d max|s|=%.4f max|r-1|=%.4f "
              "maxd=%.3f splits=%d" %
              (rnd + 1, bestR, len(_find_runs(best, 0.5)), max_s, max_r,
               max_d, nsplit))

        if bestR <= round_startR + 1e-13:
            # no gain this round; keep going with other mechanism anyway
            pass

    return best, bestR, alt_h, altR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    if time.process_time() < deadline - 20.0:
        try:
            exp_h, expR, alt_h, altR_exp = _alternating_experiment(
                best, bestR, deadline - 12.0, rng)
            if alt_h is not None:
                alt_cand, altR = alt_h.copy(), altR_exp
            if expR > bestR + 1e-13:
                best, bestR = exp_h.copy(), expR
                print("alternating wins: R=%.7f (was %.7f)" %
                      (bestR, start_bestR))
            else:
                print("alternating did not beat base: %.7f vs %.7f" %
                      (expR, bestR))
        except Exception as e:
            print("alternating experiment failed: %s" % e)

    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR, 0.0


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        best_cand = None
        best_cand_R = bestR
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
        else:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()
    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


# ---------------- Experiment: affine warp of tall runs ----------------

def _find_runs(h, peak_thresh_frac=0.25):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    pos = h > 0
    if not pos.any():
        return []
    gmax = h.max()
    thr = peak_thresh_frac * gmax
    runs = []
    i = 0
    while i < n:
        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            if h[i:j + 1].max() >= thr:
                runs.append(np.arange(i, j + 1))
            i = j + 1
        else:
            i += 1
    return runs


def _warp(h, runs, s, r):
    """Affine warp each kept run: p -> c_k + (p-c_k)*r_k + s_k.
    Mass-preserving linear re-splat. Unkept cells stay fixed."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    out = h.copy()
    for k, cells in enumerate(runs):
        sk = float(s[k]); rk = float(r[k])
        masses = h[cells]
        tot = masses.sum()
        if tot <= 0:
            continue
        c = float(np.dot(cells.astype(float), masses) / tot)
        out[cells] -= masses
        for j, m in zip(cells, masses):
            if m == 0.0:
                continue
            center = c + (float(j) - c) * rk + sk
            i0 = int(np.floor(center - 1.0))
            i1 = int(np.ceil(center + 1.0))
            for i in range(i0, i1 + 1):
                if i < 0 or i >= n:
                    continue
                w = 1.0 - abs(i - center)
                if w > 0.0:
                    out[i] += m * w
    return np.clip(out, 0.0, None)


def _warp_grad(h, runs, s, r, dRdh):
    """Exact dR/ds_k and dR/dr_k given dR/dh2."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    K = len(runs)
    gs = np.zeros(K)
    gr = np.zeros(K)
    for k, cells in enumerate(runs):
        sk = float(s[k]); rk = float(r[k])
        masses = h[cells]
        tot = masses.sum()
        if tot <= 0:
            continue
        c = float(np.dot(cells.astype(float), masses) / tot)
        acc_s = 0.0
        acc_r = 0.0
        for j, m in zip(cells, masses):
            if m == 0.0:
                continue
            center = c + (float(j) - c) * rk + sk
            dcenter_dr = float(j) - c
            i0 = int(np.floor(center - 1.0))
            i1 = int(np.ceil(center + 1.0))
            for i in range(i0, i1 + 1):
                if i < 0 or i >= n:
                    continue
                d = i - center
                if abs(d) < 1.0:
                    dw_dd = -np.sign(d)
                    dw_ds = dw_dd * (-1.0)
                    dw_dr = dw_dd * (-dcenter_dr)
                    acc_s += dRdh[i] * m * dw_ds
                    acc_r += dRdh[i] * m * dw_dr
        gs[k] = acc_s
        gr[k] = acc_r
    return gs, gr


def _fd_check_warp(h, runs, s, r, dRdh, k, eps=1e-6):
    s_p = s.copy(); s_p[k] += eps
    s_m = s.copy(); s_m[k] -= eps
    fd_s = (R_of(_warp(h, runs, s_p, r)) - R_of(_warp(h, runs, s_m, r))) / (2 * eps)
    r_p = r.copy(); r_p[k] += eps
    r_m = r.copy(); r_m[k] -= eps
    fd_r = (R_of(_warp(h, runs, s, r_p)) - R_of(_warp(h, runs, s, r_m))) / (2 * eps)
    gs, gr = _warp_grad(h, runs, s, r, dRdh)
    return fd_s, gs[k], fd_r, gr[k]


def _warp_opt(h, runs, s0, r0, maxiter, deadline,
              free_s=True, free_r=True, free_heights=False,
              height_cells=None):
    if time.process_time() >= deadline - 0.3:
        return h, s0, r0
    K = len(runs)
    if K == 0:
        return h, s0, r0
    s = np.clip(s0.copy(), -1.0, 1.0)
    r = np.clip(r0.copy(), 0.8, 1.25)
    h = np.clip(h, 0, None)

    parts = []
    bounds = []
    n_s = K if free_s else 0
    n_r = K if free_r else 0
    if free_s:
        parts.append(s); bounds += [(-1.0, 1.0)] * K
    if free_r:
        parts.append(r); bounds += [(0.8, 1.25)] * K
    n_h = 0
    if free_heights and height_cells is not None:
        hcells = np.asarray(height_cells, dtype=int)
        n_h = hcells.size
        parts.append(h[hcells]); bounds += [(0.0, None)] * n_h
    if not parts:
        return h, s0, r0
    x0 = np.concatenate(parts)

    def unpack(x):
        idx = 0
        ss = np.clip(x[idx:idx + n_s], -1.0, 1.0) if free_s else s0
        idx += n_s
        rr = np.clip(x[idx:idx + n_r], 0.8, 1.25) if free_r else r0
        idx += n_r
        hh = h.copy()
        if n_h > 0:
            hh[hcells] = np.clip(x[idx:idx + n_h], 0.0, None)
        return ss, rr, hh

    def f(x):
        ss, rr, hh = unpack(x)
        h2 = _warp(hh, runs, ss, rr)
        val, g2 = _fun_grad(h2)
        gs, gr = _warp_grad(hh, runs, ss, rr, g2)
        grads = []
        if free_s:
            grads.append(gs)
        if free_r:
            grads.append(gr)
        if n_h > 0:
            grads.append(g2[hcells])
        return val, np.concatenate(grads)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h, s0, r0
    if res is None:
        return h, s0, r0
    ss, rr, hh = unpack(res.x)
    h2 = _warp(hh, runs, ss, rr)
    return h2, ss, rr


def _warp_experiment(base, baseR, deadline, rng):
    h = np.clip(base, 0, None).copy()
    n = h.size
    runs = _find_runs(h, peak_thresh_frac=0.25)
    print("warp: %d runs kept (of %d cells, N=%d)" %
          (len(runs), int(np.sum(h > 0)), n))
    if len(runs) == 0:
        return h, baseR, None, -1.0

    K = len(runs)
    s = np.zeros(K)
    r = np.ones(K)

    # FD check
    h_test = _warp(h, runs, s, r)
    _, g_test = _fun_grad(h_test)
    fd_s, an_s, fd_r, an_r = _fd_check_warp(h, runs, s, r, g_test, 0)
    den_s = max(abs(fd_s), abs(an_s), 1e-12)
    den_r = max(abs(fd_r), abs(an_r), 1e-12)
    print("warp: FD s rel=%.3e (fd=%.3e an=%.3e) r rel=%.3e (fd=%.3e an=%.3e)" %
          (abs(fd_s - an_s) / den_s, fd_s, an_s,
           abs(fd_r - an_r) / den_r, fd_r, an_r))

    best_h = h.copy()
    bestR = baseR
    best_s = s.copy()
    best_r = r.copy()

    for rnd in range(3):
        if time.process_time() >= deadline - 10.0:
            break
        # 1) shifts + scales only
        h1, s1, r1 = _warp_opt(best_h, runs, best_s, best_r, 200,
                               deadline - 8.0, free_s=True, free_r=True,
                               free_heights=False)
        R1 = R_of(h1)
        if R1 > bestR + 1e-13:
            best_h, bestR, best_s, best_r = h1, R1, s1, r1
        # 2) heights only
        if time.process_time() < deadline - 8.0:
            hcells = np.concatenate(runs)
            h2, s2, r2 = _warp_opt(best_h, runs, best_s, best_r, 200,
                                   deadline - 6.0, free_s=False, free_r=False,
                                   free_heights=True, height_cells=hcells)
            R2 = R_of(h2)
            if R2 > bestR + 1e-13:
                best_h, bestR, best_s, best_r = h2, R2, s2, r2
        # 3) joint
        if time.process_time() < deadline - 8.0:
            hcells = np.concatenate(runs)
            h3, s3, r3 = _warp_opt(best_h, runs, best_s, best_r, 400,
                                   deadline - 4.0, free_s=True, free_r=True,
                                   free_heights=True, height_cells=hcells)
            R3 = R_of(h3)
            if R3 > bestR + 1e-13:
                best_h, bestR, best_s, best_r = h3, R3, s3, r3
        max_s = float(np.max(np.abs(best_s))) if K else 0.0
        max_r = float(np.max(np.abs(best_r - 1.0))) if K else 0.0
        print("warp round %d: R=%.7f max|s|=%.4f max|r-1|=%.4f" %
              (rnd + 1, bestR, max_s, max_r))

    return best_h, bestR, best_h.copy(), bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- Experiment: affine warp of tall runs ----
    if time.process_time() < deadline - 20.0:
        try:
            exp_h, expR, alt_h, altR_exp = _warp_experiment(
                best, bestR, deadline - 12.0, rng)
            if alt_h is not None:
                alt_cand, altR = alt_h.copy(), altR_exp
            if expR > bestR + 1e-13:
                best, bestR = exp_h.copy(), expR
                print("warp wins: R=%.7f (was %.7f)" % (bestR, start_bestR))
            else:
                print("warp did not beat base: %.7f vs %.7f" % (expR, bestR))
        except Exception as e:
            print("warp experiment failed: %s" % e)

    # ---- Keep the base's proven machinery ----
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    total_acc = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        best_cand = None
        best_cand_R = bestR
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
            total_acc += 1
        else:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()

    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


# ---------------- Experiment: continuous run splitting ----------------

def _find_runs(h, peak_thresh_frac=0.7, K_cap=32):
    """Maximal blocks of consecutive positive cells; keep those whose peak
    height >= peak_thresh_frac * global max, capped at K_cap by peak height."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    pos = h > 0
    if not pos.any():
        return []
    gmax = h.max()
    thr = peak_thresh_frac * gmax
    runs = []
    i = 0
    while i < n:
        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            pk = h[i:j + 1].max()
            if pk >= thr:
                runs.append((pk, np.arange(i, j + 1)))
            i = j + 1
        else:
            i += 1
    runs.sort(key=lambda t: -t[0])
    runs = [r for _, r in runs[:K_cap]]
    return runs


def _sigmoid(x):
    return 1.0 / (1.0 + np.exp(-np.clip(x, -60.0, 60.0)))


def _split(h, runs, d, x):
    """Split each run into two copies of its own shape, scaled by f and 1-f,
    shifted by -d/2 and +d/2 respectively, re-splatted linearly."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    out = h.copy()
    K = len(runs)
    for k, cells in enumerate(runs):
        dk = float(d[k])
        fk = float(_sigmoid(x[k]))
        masses = h[cells]
        out[cells] -= masses
        half = 0.5 * dk
        for j, m in zip(cells, masses):
            if m == 0.0:
                continue
            for (shift, frac) in ((-half, fk), (half, 1.0 - fk)):
                center = j + shift
                i0 = int(np.floor(center - 1.0))
                i1 = int(np.ceil(center + 1.0))
                for i in range(i0, i1 + 1):
                    if i < 0 or i >= n:
                        continue
                    w = 1.0 - abs(i - center)
                    if w > 0.0:
                        out[i] += m * frac * w
    return np.clip(out, 0.0, None)


def _split_grad(h, runs, d, x, dRdh):
    """Exact gradient of R w.r.t. d_k and x_k via chain rule."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    K = len(runs)
    gd = np.zeros(K)
    gx = np.zeros(K)
    for k, cells in enumerate(runs):
        dk = float(d[k])
        fk = float(_sigmoid(x[k]))
        masses = h[cells]
        half = 0.5 * dk
        acc_d = 0.0
        acc_x = 0.0
        for j, m in zip(cells, masses):
            if m == 0.0:
                continue
            for (shift, frac, dshift_dd, dfrac_dx) in (
                    (-half, fk, -0.5, fk * (1.0 - fk)),
                    (half, 1.0 - fk, 0.5, -fk * (1.0 - fk))):
                center = j + shift
                i0 = int(np.floor(center - 1.0))
                i1 = int(np.ceil(center + 1.0))
                for i in range(i0, i1 + 1):
                    if i < 0 or i >= n:
                        continue
                    dd = i - center
                    w = 1.0 - abs(dd)
                    if w > 0.0:
                        # dw/d(shift) = -dw/dd = sign(dd) for |dd|<1
                        dw_dshift = np.sign(dd)
                        acc_d += dRdh[i] * m * frac * dw_dshift * dshift_dd
                        acc_x += dRdh[i] * m * w * dfrac_dx
        gd[k] = acc_d
        gx[k] = acc_x
    return gd, gx


def _fd_check_split(h, runs, d, x, dRdh, k, eps=1e-6):
    d_plus = d.copy(); d_plus[k] += eps
    d_minus = d.copy(); d_minus[k] -= eps
    R_plus = R_of(_split(h, runs, d_plus, x))
    R_minus = R_of(_split(h, runs, d_minus, x))
    fd_d = (R_plus - R_minus) / (2 * eps)
    x_plus = x.copy(); x_plus[k] += eps
    x_minus = x.copy(); x_minus[k] -= eps
    R_plus = R_of(_split(h, runs, d, x_plus))
    R_minus = R_of(_split(h, runs, d, x_minus))
    fd_x = (R_plus - R_minus) / (2 * eps)
    gd, gx = _split_grad(h, runs, d, x, dRdh)
    return fd_d, gd[k], fd_x, gx[k]


def _split_opt(h, runs, d0, x0, maxiter, deadline,
               free_split=True, free_heights=False, height_cells=None):
    if time.process_time() >= deadline - 0.3:
        return h, d0, x0
    K = len(runs)
    if K == 0:
        return h, d0, x0
    d = np.clip(d0.copy(), 0.0, 4.0)
    x = x0.copy()
    h = np.clip(h, 0, None)
    n = h.size

    if free_heights and height_cells is not None:
        hcells = np.asarray(height_cells, dtype=int)
        n_h = hcells.size
        if free_split:
            x0v = np.concatenate([d, x, h[hcells]])
            n_s = 2 * K
        else:
            x0v = np.concatenate([d, x, h[hcells]])
            n_s = 2 * K

        def unpack(xv):
            dd = np.clip(xv[:K], 0.0, 4.0)
            xx = xv[K:2 * K]
            hh = h.copy()
            hh[hcells] = np.clip(xv[2 * K:], 0.0, None)
            return dd, xx, hh

        def f(xv):
            dd, xx, hh = unpack(xv)
            h2 = _split(hh, runs, dd, xx)
            val, g2 = _fun_grad(h2)
            gd, gx = _split_grad(hh, runs, dd, xx, g2)
            gh = g2[hcells]
            return val, np.concatenate([gd, gx, gh])

        bounds = [(0.0, 4.0)] * K + [(None, None)] * K + [(0.0, None)] * n_h
    else:
        x0v = np.concatenate([d, x])

        def f(xv):
            dd = np.clip(xv[:K], 0.0, 4.0)
            xx = xv[K:2 * K]
            h2 = _split(h, runs, dd, xx)
            val, g2 = _fun_grad(h2)
            gd, gx = _split_grad(h, runs, dd, xx, g2)
            return val, np.concatenate([gd, gx])

        bounds = [(0.0, 4.0)] * K + [(None, None)] * K

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0v, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h, d0, x0
    if res is None:
        return h, d0, x0

    if free_heights and height_cells is not None:
        dd, xx, hh = unpack(res.x)
        h2 = _split(hh, runs, dd, xx)
        return h2, dd, xx
    else:
        dd = np.clip(res.x[:K], 0.0, 4.0)
        xx = res.x[K:2 * K]
        h2 = _split(h, runs, dd, xx)
        return h2, dd, xx


def _split_experiment(base, baseR, deadline, rng):
    h = np.clip(base, 0, None).copy()
    n = h.size
    runs = _find_runs(h, peak_thresh_frac=0.7, K_cap=32)
    K = len(runs)
    print("split: K=%d runs kept (of %d cells, N=%d)" %
          (K, int(np.sum(h > 0)), n))
    if K == 0:
        return h, baseR, None, -1.0

    d = np.zeros(K)
    x = np.zeros(K)

    # FD check for k=0
    h_test = _split(h, runs, d, x)
    _, g_test = _fun_grad(h_test)
    fd_d, an_d, fd_x, an_x = _fd_check_split(h, runs, d, x, g_test, 0)
    rel_d = abs(fd_d - an_d) / max(abs(fd_d), abs(an_d), 1e-12)
    rel_x = abs(fd_x - an_x) / max(abs(fd_x), abs(an_x), 1e-12)
    print("split: FD k=0 d: fd=%.6e an=%.6e rel=%.3e | x: fd=%.6e an=%.6e rel=%.3e" %
          (fd_d, an_d, rel_d, fd_x, an_x, rel_x))

    best_h = h.copy()
    bestR = baseR
    best_d = d.copy()
    best_x = x.copy()

    for rnd in range(3):
        if time.process_time() >= deadline - 10.0:
            break
        # 1) split params only
        h1, d1, x1 = _split_opt(best_h, runs, best_d, best_x, 200,
                                deadline - 8.0, free_split=True,
                                free_heights=False)
        r1 = R_of(h1)
        if r1 > bestR + 1e-13:
            best_h, bestR, best_d, best_x = h1, r1, d1, x1
        # 2) heights only
        if time.process_time() < deadline - 8.0:
            hcells = np.concatenate(runs)
            h2, d2, x2 = _split_opt(best_h, runs, best_d, best_x, 200,
                                    deadline - 6.0, free_split=False,
                                    free_heights=True, height_cells=hcells)
            r2 = R_of(h2)
            if r2 > bestR + 1e-13:
                best_h, bestR, best_d, best_x = h2, r2, d2, x2
        # 3) joint
        if time.process_time() < deadline - 8.0:
            hcells = np.concatenate(runs)
            h3, d3, x3 = _split_opt(best_h, runs, best_d, best_x, 400,
                                    deadline - 4.0, free_split=True,
                                    free_heights=True, height_cells=hcells)
            r3 = R_of(h3)
            if r3 > bestR + 1e-13:
                best_h, bestR, best_d, best_x = h3, r3, d3, x3
        fvals = _sigmoid(best_x)
        order = np.argsort(-best_d)
        top = order[:min(5, K)]
        info = ", ".join("d=%.3f f=%.3f" % (best_d[i], fvals[i]) for i in top)
        nz = int(np.sum(best_d > 0.1))
        print("split round %d: R=%.7f nz(d>0.1)=%d | %s" %
              (rnd + 1, bestR, nz, info))

    return best_h, bestR, best_h.copy(), bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- Experiment: continuous run splitting ----
    if time.process_time() < deadline - 20.0:
        try:
            exp_h, expR, alt_h, altR_exp = _split_experiment(
                best, bestR, deadline - 12.0, rng)
            if alt_h is not None:
                alt_cand, altR = alt_h.copy(), altR_exp
            if expR > bestR + 1e-13:
                best, bestR = exp_h.copy(), expR
                print("split wins: R=%.7f (was %.7f)" % (bestR, start_bestR))
            else:
                print("split did not beat base: %.7f vs %.7f" %
                      (expR, bestR))
        except Exception as e:
            print("split experiment failed: %s" % e)

    # ---- Keep the base's proven machinery ----
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 600, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.25, 128, 1e8), (0.40, 256, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=200, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


# ---------- New mechanism: local peak-flattening on the plateau ----------

def _flatten_step(best, bestR, deadline, rng):
    """Pick knots near the max and push them toward the max by
    reallocating height at their preimage cells, then polish."""
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    # knots just below max: candidates to "raise"
    idx = np.flatnonzero(Lf < 0.9995 * M)
    if idx.size == 0:
        return best, bestR
    order = np.argsort(-Lf[idx])
    idx = idx[order][:30]
    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()
    improved = False
    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 150)
            hi = min(n - 1, a + 150)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in np.geomspace(0.01 * mean_pos, 1.0 * mean_pos, 20):
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > bestR + 1e-13:
                    # polish locally
                    lo2 = max(0, a - 96)
                    hi2 = min(n - 1, a + 96)
                    free = np.arange(lo2, hi2 + 1)
                    hp = _lbfgs_block(h2, free, 50, deadline, beta=0.0)
                    rp = R_of(hp)
                    if rp > bestR + 1e-13:
                        best, bestR = hp, rp
                        improved = True
                        break
            if improved:
                break
        if improved:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(1234567)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: aggressive flattening loop near the plateau
    iters = 0
    while time.process_time() < deadline - 12.0:
        iters += 1
        prev = bestR
        best, bestR = _flatten_step(best, bestR, deadline - 10.0, rng)
        if bestR <= prev + 1e-13:
            # small polish cycle then break
            best, bestR = run_cycle(best, bestR, deadline - 10.0)
            break
    print("flatten iters=%d R=%.7f" % (iters, bestR))

    # Phase 2: full polish
    if time.process_time() < deadline - 5.0:
        best, bestR = run_cycle(best, bestR, deadline - 5.0)
        print("cycle R=%.7f" % bestR)

    # Phase 3: another flatten round with remaining budget
    while time.process_time() < deadline - 3.0:
        prev = bestR
        best, bestR = _flatten_step(best, bestR, deadline - 2.5, rng)
        if bestR <= prev + 1e-13:
            break

    if time.process_time() < deadline - 0.5:
        best, bestR = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6 and not np.array_equal(best, start_best):
        out["alternative"] = best
    return out

