    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------------------------------------------------------------------------
# New: local grid resampling / adaptive-resolution move.
#
# The idea: R for a step function depends only on the knot values of f*f.
# The optimum is "flat-topped" (many knots hug the max). The current program
# only ever perturbs single cells or small windows. Here we exploit a
# different degree of freedom: locally coarsen / refine the discretisation by
# merging or splitting adjacent cells, which lets the optimiser move mass
# across the support in a way single-cell edits cannot, and then re-optimise
# the affected window. This is a genuinely different construction channel.
# ---------------------------------------------------------------------------

def _merge_cells(h, i0, k):
    """Merge k consecutive cells starting at i0 into one (mass-conserving)."""
    n = h.size
    i1 = min(n, i0 + k)
    if i1 - i0 < 2:
        return None
    mass = float(h[i0:i1].sum())
    out = np.concatenate([h[:i0], [mass], h[i1:]])
    return out


def _split_cells(h, i0, k):
    """Split cell i0 into k equal-mass subcells."""
    n = h.size
    if i0 < 0 or i0 >= n:
        return None
    mass = float(h[i0])
    if mass <= 0:
        return None
    parts = np.full(k, mass / k)
    out = np.concatenate([h[:i0], parts, h[i0 + 1:]])
    return out


def _coarsen_refine(best, bestR, deadline, rng):
    """Try merging/splitting cells in the peak region and re-optimise."""
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    # peak region of f*f in cell coordinates
    idx = np.flatnonzero(Lf >= 0.999 * M)
    if idx.size == 0:
        return best, bestR
    lo = max(0, int(idx.min()) - 8)
    hi = min(n - 1, int(idx.max()) + 8)
    span = max(1, hi - lo + 1)
    # sample a handful of merge positions in the peak region
    tries = 0
    improved = False
    for _ in range(24):
        if time.process_time() >= deadline - 0.6:
            break
        tries += 1
        i0 = int(rng.integers(lo, hi + 1))
        k = int(rng.integers(2, 6))
        h2 = _merge_cells(best, i0, k)
        if h2 is None:
            continue
        # re-optimise a window around the change
        win_lo = max(0, i0 - 96)
        win_hi = min(h2.size - 1, i0 + 96)
        free = np.arange(win_lo, win_hi + 1)
        h3 = _lbfgs_block(h2, free, 80, deadline, beta=0.0)
        r3 = R_of(h3)
        if r3 > bestR + 1e-13:
            best, bestR = h3, r3
            improved = True
        else:
            # try a split instead
            j0 = int(rng.integers(lo, hi + 1))
            h4 = _split_cells(best, j0, 2)
            if h4 is None:
                continue
            win_lo = max(0, j0 - 96)
            win_hi = min(h4.size - 1, j0 + 96)
            free = np.arange(win_lo, win_hi + 1)
            h5 = _lbfgs_block(h4, free, 80, deadline, beta=0.0)
            r5 = R_of(h5)
            if r5 > bestR + 1e-13:
                best, bestR = h5, r5
                improved = True
    return best, bestR, improved


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- First: the proven full cycle from the start ----
    if time.process_time() < deadline - 4.0:
        best, bestR = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- New move: coarsen/refine in the peak region ----
    alt_cand = None
    altR = -1.0
    if time.process_time() < deadline - 6.0:
        h_cr, r_cr, improved = _coarsen_refine(best, bestR,
                                               deadline - 5.0, rng)
        if improved and r_cr > bestR + 1e-13:
            best, bestR = h_cr, r_cr
            print("coarsen/refine wins: R=%.7f" % bestR)
        elif r_cr > start_bestR + 1e-9:
            alt_cand, altR = h_cr, r_cr

    # ---- Alternate between full cycle and coarsen/refine ----
    rounds = 0
    while time.process_time() < deadline - 1.5:
        rounds += 1
        before = bestR
        if time.process_time() < deadline - 1.5:
            h_cr, r_cr, improved = _coarsen_refine(best, bestR,
                                                   deadline - 1.0, rng)
            if improved and r_cr > bestR + 1e-13:
                best, bestR = h_cr, r_cr
        if time.process_time() < deadline - 1.0:
            best, bestR = run_cycle(best, bestR, deadline - 0.8)
        if bestR <= before + 1e-13:
            # no progress: try a fresh coarse re-seed via up/down sampling
            if time.process_time() < deadline - 1.5 and best.size > 64:
                # downsample by 2 (mass-conserving), re-opt, then upsample back
                n = best.size
                if n % 2 == 0:
                    hd = best.reshape(-1, 2).sum(axis=1)
                else:
                    hd = best[:-1].reshape(-1, 2).sum(axis=1)
                hd = _rescale(hd)
                hd, rd = run_cycle(hd, R_of(hd), deadline - 1.0)
                # upsample back to original resolution
                hu = np.repeat(hd / 2.0, 2)
                if hu.size < best.size:
                    hu = np.concatenate([hu, np.zeros(best.size - hu.size)])
                hu = _rescale(hu[:best.size])
                ru = R_of(hu)
                if ru > bestR + 1e-13:
                    best, bestR = hu, ru
            if time.process_time() >= deadline - 1.0:
                break
            if bestR <= before + 1e-13:
                break

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _num_dq_p(h, p):
    """Exact piecewise-linear integral of g^p over each segment, and its
    adjoint contributions to the knot values."""
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    d = b - a
    pp = p + 1.0
    num = np.empty_like(a)
    dqa = np.empty_like(a)
    dqb = np.empty_like(a)
    big = np.abs(d) > 1e-12
    # non-degenerate: I = (b^pp - a^pp)/(pp*d)
    an = a[big]; bn = b[big]; dn = d[big]
    ap = np.power(np.clip(an, 0.0, None), pp)
    bp = np.power(np.clip(bn, 0.0, None), pp)
    num[big] = (bp - ap) / (pp * dn)
    # dI/da = [ -pp*a^(pp-1)*pp*d + (b^pp-a^pp) ] / (pp*d)^2
    denom = (pp * dn) ** 2
    dqa[big] = (-pp * np.power(np.clip(an, 0.0, None), p) * pp * dn
                + (bp - ap)) / denom
    dqb[big] = (pp * np.power(np.clip(bn, 0.0, None), p) * pp * dn
                - (bp - ap)) / denom
    # degenerate: I = a^p, dI/da = dI/db = p*a^(p-1)/2 (split evenly)
    ad = a[~big]
    apow = np.power(np.clip(ad, 0.0, None), p)
    num[~big] = apow
    g = p * np.power(np.clip(ad, 0.0, None), p - 1.0)
    dqa[~big] = 0.5 * g
    dqb[~big] = 0.5 * g
    dq = np.zeros_like(Lf)
    dq[:-1] += dqa
    dq[1:] += dqb
    return float(np.sum(num)), dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_p(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_dq_p(h, p)
    if num <= 0:
        return 1e18, np.zeros(h.size)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    if Lm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[m] += p / Lm
    grad = _backprop(gLf, h) + 2.0 * p / s
    val = -np.log(num) + 2.0 * p * np.log(s) + p * np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, p=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if p > 0:
        fg = (lambda hh: _fun_grad_p(hh, p))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, p=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if p > 0:
        fg = (lambda hh: _fun_grad_p(hh, p))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
