def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    total_acc = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        best_cand = None
        best_cand_R = bestR
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
            total_acc += 1
        else:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()

    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


# ---------------- Experiment: p<2 deficit-shoulder preconditioner ----------

def _fd_check_p(h, p, ntest=5, eps=1e-6, seed=7):
    rng = np.random.default_rng(seed)
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0.0
    idxs = rng.choice(pos, size=min(ntest, pos.size), replace=False)
    _, dq, _ = _num_dq_p(h, p)
    maxrel = 0.0
    for i in idxs:
        hp = h.copy(); hp[i] += eps
        hm = h.copy(); hm[i] -= eps
        np_p, _, _ = _num_dq_p(hp, p)
        nm_p, _, _ = _num_dq_p(hm, p)
        fd = (np_p - nm_p) / (2 * eps)
        # analytic d num/d h_i via backprop of dq
        gLf = dq.copy()
        # num = sum I_j; dnum/dh_i = backprop of dq (since dq is dI/dLf)
        gLf_full = np.zeros(n + 2)
        gLf_full[1:-1] = dq[1:-1]
        # dq already includes both endpoints; use direct backprop
        ana = _backprop(dq, h)[i]
        rel = abs(fd - ana) / max(abs(fd), abs(ana), 1e-12)
        if rel > maxrel:
            maxrel = rel
    return maxrel


def _p_ladder(base, baseR, deadline, best_ever, bestR_ever):
    ps = [1.30, 1.50, 1.70, 1.85, 2.00]
    h = base.copy()
    curR = baseR
    stall = 0
    for p in ps:
        if time.process_time() >= deadline - 2.0:
            break
        # (a) full-array L-BFGS with p-objective
        h1 = _lbfgs_all_pos(h, 150, deadline - 1.5, p=p)
        r1 = R_of(h1)
        if r1 > bestR_ever + 1e-13:
            best_ever, bestR_ever = h1.copy(), r1
        # (b) peak-window block L-BFGS
        win = _peak_window(h1, pad_frac=0.25, extra=128)
        h2 = _lbfgs_block(h1, win, 120, deadline - 1.5, p=p)
        r2 = R_of(h2)
        if r2 > bestR_ever + 1e-13:
            best_ever, bestR_ever = h2.copy(), r2
        # track exact R for stall detection
        newR = max(r1, r2)
        if newR > curR + 1e-13:
            curR = newR
            stall = 0
            h = h2 if r2 >= r1 else h1
        else:
            stall += 1
            h = h2 if r2 >= r1 else h1
        Lf = _knots(h)
        mx = Lf.max()
        b01 = float(np.mean(Lf >= 0.99 * mx)) if mx > 0 else 0.0
        b05 = float(np.mean(Lf >= 0.95 * mx)) if mx > 0 else 0.0
        mxh = h.max()
        mh = h.mean() if h.mean() > 0 else 1.0
        print("p=%.2f exactR=%.7f max|h|/mean=%.2f band01=%.2f%% band05=%.2f%%" %
              (p, newR, mxh / mh, 100.0 * b01, 100.0 * b05))
        if stall >= 2 and p < 2.0:
            # jump to p=2
            if time.process_time() < deadline - 2.0:
                h1 = _lbfgs_all_pos(h, 150, deadline - 1.5, p=2.0)
                r1 = R_of(h1)
                if r1 > bestR_ever + 1e-13:
                    best_ever, bestR_ever = h1.copy(), r1
                win = _peak_window(h1, pad_frac=0.25, extra=128)
                h2 = _lbfgs_block(h1, win, 120, deadline - 1.5, p=2.0)
                r2 = R_of(h2)
                if r2 > bestR_ever + 1e-13:
                    best_ever, bestR_ever = h2.copy(), r2
                h = h2 if r2 >= r1 else h1
                print("p=2.00 (jump) exactR=%.7f" % max(r1, r2))
            break
    return best_ever, bestR_ever


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Experiment: p<2 deficit-shoulder preconditioner ----
    if time.process_time() < deadline - 14.0:
        try:
            # FD validation of _num_dq_p
            htest = _seed_zeros(best)
            errs = []
            for ptest in (1.30, 1.70, 2.00):
                errs.append(_fd_check_p(htest, ptest))
            print("p-FD max rel errs: " +
                  " ".join("p=%.2f:%.2e" % (pp, e)
                           for pp, e in zip((1.30, 1.70, 2.00), errs)))
            best, bestR = _p_ladder(best, bestR, deadline - 12.0,
                                    best, bestR)
            print("p-ladder done: R=%.7f" % bestR)
        except Exception as e:
            print("p-ladder failed: %s" % e)

    # ---- Keep the base's proven machinery ----
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_w(h, delta):
    """Deficit-reweighted objective. w_j = 1/(g(1-g)+delta) clipped [1,200],
    treated as fixed. num_w = sum_j w_j (a^2+ab+b^2)/3, adjoint uses
    trapezoid of w across knot pairs."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    gmid = 0.5 * (a + b)
    w = 1.0 / (gmid * (1.0 - gmid) + delta)
    w = np.clip(w, 1.0, 200.0)
    num_w = np.sum(w * (a * a + a * b + b * b)) / 3.0
    if num_w <= 0:
        return 1e18, np.zeros(h.size)
    # adjoint of num_w wrt Lf knots
    dq = np.zeros_like(Lf)
    # pair j uses a=Lf[j], b=Lf[j+1], weight w[j]
    # d/da of w*(a^2+ab+b^2)/3 = w*(2a+b)/3
    # d/db of w*(a^2+ab+b^2)/3 = w*(a+2b)/3
    dq[:-1] += w * (2 * a + b) / 3.0
    dq[1:] += w * (a + 2 * b) / 3.0
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num_w
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num_w) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_all_pos_w(h0, maxiter, deadline, delta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad_w(hh, delta)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_block_w(h0, free, maxiter, deadline, delta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_w(hh, delta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    total_acc = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        best_cand = None
        best_cand_R = bestR
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
            total_acc += 1
        else:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()

    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


# ---------------- Experiment: recursive 3-way run splitting ----------------

def _find_runs(h, peak_thresh_frac=0.7, K_cap=32):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    pos = h > 0
    if not pos.any():
        return []
    gmax = h.max()
    thr = peak_thresh_frac * gmax
    runs = []
    i = 0
    while i < n:
        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            pk = h[i:j + 1].max()
            if pk >= thr:
                runs.append((pk, np.arange(i, j + 1)))
            i = j + 1
        else:
            i += 1
    runs.sort(key=lambda t: -t[0])
    runs = [r for _, r in runs[:K_cap]]
    return runs


def _softmax3(f1, f2, f3):
    m = max(f1, f2, f3)
    e1 = np.exp(f1 - m); e2 = np.exp(f2 - m); e3 = np.exp(f3 - m)
    Z = e1 + e2 + e3
    return e1 / Z, e2 / Z, e3 / Z


def _splat3(h, runs, d1, d2, f1, f2, f3):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    out = h.copy()
    K = len(runs)
    for k, cells in enumerate(runs):
        a1 = float(f1[k]); a2 = float(f2[k]); a3 = float(f3[k])
        w1, w2, w3 = _softmax3(a1, a2, a3)
        s1 = float(d1[k]); s2 = 0.0; s3 = float(d2[k])
        masses = h[cells]
        out[cells] -= masses
        for j, m in zip(cells, masses):
            if m == 0.0:
                continue
            for (shift, frac) in ((s1, w1), (s2, w2), (s3, w3)):
                if frac <= 0.0:
                    continue
                center = j + shift
                i0 = int(np.floor(center - 1.0))
                i1 = int(np.ceil(center + 1.0))
                for i in range(i0, i1 + 1):
                    if i < 0 or i >= n:
                        continue
                    w = 1.0 - abs(i - center)
                    if w > 0.0:
                        out[i] += m * frac * w
    return np.clip(out, 0.0, None)


def _splat3_grad(h, runs, d1, d2, f1, f2, f3, dRdh):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    K = len(runs)
    gd1 = np.zeros(K); gd2 = np.zeros(K)
    gf1 = np.zeros(K); gf2 = np.zeros(K); gf3 = np.zeros(K)
    for k, cells in enumerate(runs):
        a1 = float(f1[k]); a2 = float(f2[k]); a3 = float(f3[k])
        w1, w2, w3 = _softmax3(a1, a2, a3)
        s1 = float(d1[k]); s3 = float(d2[k])
        masses = h[cells]
        w = np.array([w1, w2, w3])
        J = np.diag(w) - np.outer(w, w)
        acc_d1 = 0.0; acc_d2 = 0.0
        acc_f = np.zeros(3)
        for j, m in zip(cells, masses):
            if m == 0.0:
                continue
            for idx, (shift, frac, dshift_dd) in enumerate((
                    (s1, w1, 1.0), (0.0, w2, 0.0), (s3, w3, 1.0))):
                center = j + shift
                i0 = int(np.floor(center - 1.0))
                i1 = int(np.ceil(center + 1.0))
                for i in range(i0, i1 + 1):
                    if i < 0 or i >= n:
                        continue
                    dd = i - center
                    wgt = 1.0 - abs(dd)
                    if wgt > 0.0:
                        g = dRdh[i] * m
                        dw_dshift = np.sign(dd)
                        if idx == 0:
                            acc_d1 += g * frac * dw_dshift * dshift_dd
                        elif idx == 2:
                            acc_d2 += g * frac * dw_dshift * dshift_dd
                        acc_f += g * wgt * J[idx, :]
        gd1[k] = acc_d1
        gd2[k] = acc_d2
        gf1[k] = acc_f[0]
        gf2[k] = acc_f[1]
        gf3[k] = acc_f[2]
    return gd1, gd2, gf1, gf2, gf3


def _splat3_opt(h, runs, d1, d2, f1, f2, f3, maxiter, deadline,
                free_params=True, free_heights=False, height_cells=None):
    if time.process_time() >= deadline - 0.3:
        return h, d1, d2, f1, f2, f3
    K = len(runs)
    if K == 0:
        return h, d1, d2, f1, f2, f3
    h = np.clip(h, 0, None)
    n = h.size
    d1 = np.clip(d1.copy(), -1.5, 1.5)
    d2 = np.clip(d2.copy(), -1.5, 1.5)
    f1 = f1.copy(); f2 = f2.copy(); f3 = f3.copy()

    if free_heights and height_cells is not None:
        hcells = np.asarray(height_cells, dtype=int)
        n_h = hcells.size
        x0v = np.concatenate([d1, d2, f1, f2, f3, h[hcells]])

        def unpack(xv):
            dd1 = np.clip(xv[:K], -1.5, 1.5)
            dd2 = np.clip(xv[K:2 * K], -1.5, 1.5)
            ff1 = xv[2 * K:3 * K]
            ff2 = xv[3 * K:4 * K]
            ff3 = xv[4 * K:5 * K]
            hh = h.copy()
            hh[hcells] = np.clip(xv[5 * K:], 0.0, None)
            return dd1, dd2, ff1, ff2, ff3, hh

        def f(xv):
            dd1, dd2, ff1, ff2, ff3, hh = unpack(xv)
            h2 = _splat3(hh, runs, dd1, dd2, ff1, ff2, ff3)
            val, g2 = _fun_grad(h2)
            gd1, gd2, gf1, gf2, gf3 = _splat3_grad(
                hh, runs, dd1, dd2, ff1, ff2, ff3, g2)
            gh = g2[hcells]
            return val, np.concatenate([gd1, gd2, gf1, gf2, gf3, gh])

        bounds = ([( -1.5, 1.5)] * K + [(-1.5, 1.5)] * K +
                  [(None, None)] * (3 * K) + [(0.0, None)] * n_h)
    else:
        x0v = np.concatenate([d1, d2, f1, f2, f3])

        def f(xv):
            dd1 = np.clip(xv[:K], -1.5, 1.5)
            dd2 = np.clip(xv[K:2 * K], -1.5, 1.5)
            ff1 = xv[2 * K:3 * K]
            ff2 = xv[3 * K:4 * K]
            ff3 = xv[4 * K:5 * K]
            h2 = _splat3(h, runs, dd1, dd2, ff1, ff2, ff3)
            val, g2 = _fun_grad(h2)
            gd1, gd2, gf1, gf2, gf3 = _splat3_grad(
                h, runs, dd1, dd2, ff1, ff2, ff3, g2)
            return val, np.concatenate([gd1, gd2, gf1, gf2, gf3])

        bounds = ([(-1.5, 1.5)] * K + [(-1.5, 1.5)] * K +
                  [(None, None)] * (3 * K))

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0v, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h, d1, d2, f1, f2, f3
    if res is None:
        return h, d1, d2, f1, f2, f3

    if free_heights and height_cells is not None:
        dd1, dd2, ff1, ff2, ff3, hh = unpack(res.x)
        h2 = _splat3(hh, runs, dd1, dd2, ff1, ff2, ff3)
        return h2, dd1, dd2, ff1, ff2, ff3
    else:
        dd1 = np.clip(res.x[:K], -1.5, 1.5)
        dd2 = np.clip(res.x[K:2 * K], -1.5, 1.5)
        ff1 = res.x[2 * K:3 * K]
        ff2 = res.x[3 * K:4 * K]
        ff3 = res.x[4 * K:5 * K]
        h2 = _splat3(h, runs, dd1, dd2, ff1, ff2, ff3)
        return h2, dd1, dd2, ff1, ff2, ff3


def _local_repair_runs(h, runs, deadline, iters=80):
    h = np.clip(h, 0, None).copy()
    n = h.size
    for cells in runs:
        if time.process_time() >= deadline - 0.3:
            break
        lo = max(0, int(cells[0]) - 48)
        hi = min(n - 1, int(cells[-1]) + 48)
        free = np.arange(lo, hi + 1)
        h = _lbfgs_block(h, free, iters, deadline, beta=0.0)
    return h


def _split_experiment(base, baseR, deadline, rng):
    h = np.clip(base, 0, None).copy()
    n = h.size
    runs = _find_runs(h, peak_thresh_frac=0.7, K_cap=32)
    K = len(runs)
    print("splat3: K=%d runs kept (of %d cells, N=%d)" %
          (K, int(np.sum(h > 0)), n))
    if K == 0:
        return h, baseR, None, -1.0

    best_h = h.copy()
    bestR = baseR

    d1 = np.full(K, -0.5); d2 = np.full(K, 0.5)
    f1 = np.zeros(K); f2 = np.zeros(K); f3 = np.zeros(K)

    h1, d1, d2, f1, f2, f3 = _splat3_opt(
        best_h, runs, d1, d2, f1, f2, f3, 300, deadline - 6.0,
        free_params=True, free_heights=False)
    r1 = R_of(h1)
    if r1 > bestR + 1e-13:
        best_h, bestR = h1, r1
    if time.process_time() < deadline - 5.0:
        hr = _local_repair_runs(best_h, runs, deadline - 5.0, iters=80)
        rr = R_of(hr)
        if rr > bestR + 1e-13:
            best_h, bestR = hr, rr
    print("splat3 R1: R=%.7f" % bestR)

    if time.process_time() < deadline - 8.0:
        runs2 = _find_runs(best_h, peak_thresh_frac=0.7, K_cap=16)
        K2 = len(runs2)
        if K2 > 0:
            d1b = np.full(K2, -0.5); d2b = np.full(K2, 0.5)
            f1b = np.zeros(K2); f2b = np.zeros(K2); f3b = np.zeros(K2)
            h2, d1b, d2b, f1b, f2b, f3b = _splat3_opt(
                best_h, runs2, d1b, d2b, f1b, f2b, f3b, 300, deadline - 4.0,
                free_params=True, free_heights=False)
            r2 = R_of(h2)
            if r2 > bestR + 1e-13:
                best_h, bestR = h2, r2
            if time.process_time() < deadline - 3.5:
                hr = _local_repair_runs(best_h, runs2, deadline - 3.5, iters=80)
                rr = R_of(hr)
                if rr > bestR + 1e-13:
                    best_h, bestR = hr, rr
            print("splat3 R2: R=%.7f" % bestR)

    if time.process_time() < deadline - 4.0:
        runs_all = _find_runs(best_h, peak_thresh_frac=0.7, K_cap=32)
        K3 = len(runs_all)
        if K3 > 0:
            d1c = np.zeros(K3); d2c = np.zeros(K3)
            f1c = np.zeros(K3); f2c = np.zeros(K3); f3c = np.zeros(K3)
            hcells_list = []
            for cells in runs_all:
                lo = max(0, int(cells[0]) - 48)
                hi = min(n - 1, int(cells[-1]) + 48)
                hcells_list.append(np.arange(lo, hi + 1))
            hcells = np.unique(np.concatenate(hcells_list))
            hj, d1c, d2c, f1c, f2c, f3c = _splat3_opt(
                best_h, runs_all, d1c, d2c, f1c, f2c, f3c, 400,
                deadline - 2.0, free_params=True, free_heights=True,
                height_cells=hcells)
            rj = R_of(hj)
            if rj > bestR + 1e-13:
                best_h, bestR = hj, rj
            print("splat3 joint: R=%.7f" % bestR)

    return best_h, bestR, best_h.copy(), bestR


# ---------------- Experiment: deficit-reweighted gradient ----------------

def _mid_band_stats(h):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0, 0
    g = Lf / M
    mask = (g > 0.3) & (g < 0.9)
    cnt = int(np.sum(mask))
    mean_g = float(np.mean(g[mask])) if cnt > 0 else 0.0
    return mean_g, cnt


def _fd_check_w(h, delta, eps=1e-6):
    _, g = _fun_grad_w(h, delta)
    n = h.size
    idxs = np.linspace(0, n - 1, 8).astype(int)
    maxrel = 0.0
    for i in idxs:
        if h[i] <= 0:
            continue
        hp = h.copy(); hp[i] += eps
        hm = h.copy(); hm[i] -= eps
        vp, _ = _fun_grad_w(hp, delta)
        vm, _ = _fun_grad_w(hm, delta)
        fd = (vp - vm) / (2 * eps)
        an = g[i]
        rel = abs(fd - an) / max(abs(fd), abs(an), 1e-12)
        if rel > maxrel:
            maxrel = rel
    return maxrel


def _deficit_experiment(best, bestR, deadline):
    deltas = [0.02, 0.005, 0.002, 0.001]
    cur = best.copy()
    curR = bestR
    alt = None
    altR = -1.0
    fd_done = False
    for rnd, delta in enumerate(deltas):
        if time.process_time() >= deadline - 1.0:
            break
        if not fd_done:
            try:
                rel = _fd_check_w(cur, delta)
                print("deficit FD max rel err (delta=%.4f): %.2e" %
                      (delta, rel))
            except Exception as e:
                print("deficit FD failed: %s" % e)
            fd_done = True
        # full-array weighted L-BFGS
        h1 = _lbfgs_all_pos_w(cur, 200, deadline - 0.5, delta)
        # peak-window polish with same weighted gradient
        if time.process_time() < deadline - 0.5:
            win = _peak_window(h1, pad_frac=0.25, extra=128)
            h2 = _lbfgs_block_w(h1, win, 150, deadline - 0.5, delta)
        else:
            h2 = h1
        r2 = R_of(h2)
        mg, cnt = _mid_band_stats(h2)
        improved = r2 > curR + 1e-13
        print("deficit round %d (delta=%.4f): R=%.7f midband_mean_g=%.4f "
              "midband_count=%d %s" %
              (rnd, delta, r2, mg, cnt, "ACCEPT" if improved else "reject"))
        if alt is None or r2 > altR:
            alt = h2.copy()
            altR = r2
        if improved:
            cur = h2
            curR = r2
    return cur, curR, alt, altR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- Experiment: deficit-reweighted gradient ----
    if time.process_time() < deadline - 12.0:
        try:
            exp_h, expR, alt_h, altR_exp = _deficit_experiment(
                best, bestR, deadline - 10.0)
            if alt_h is not None:
                alt_cand, altR = alt_h.copy(), altR_exp
            if expR > bestR + 1e-13:
                best, bestR = exp_h.copy(), expR
                print("deficit wins: R=%.7f (was %.7f)" %
                      (bestR, start_bestR))
            else:
                print("deficit did not beat base: %.7f vs %.7f" %
                      (expR, bestR))
        except Exception as e:
            print("deficit experiment failed: %s" % e)

    # ---- Keep the base's proven machinery ----
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    out = {"best": best}
    if alt_cand is not None and altR > bestR + 1e-13:
        out["alternative"] = alt_cand
    elif alt_cand is not None:
        out["alternative"] = alt_cand
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_w(h, delta):
    """Deficit-reweighted objective. w_j = 1/(g(1-g)+delta) clipped [1,200],
    treated as fixed. num_w = sum_j w_j (a^2+ab+b^2)/3, adjoint uses
    trapezoid of w across knot pairs."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    gmid = 0.5 * (a + b)
    w = 1.0 / (gmid * (1.0 - gmid) + delta)
    w = np.clip(w, 1.0, 200.0)
    num_w = np.sum(w * (a * a + a * b + b * b)) / 3.0
    if num_w <= 0:
        return 1e18, np.zeros(h.size)
    # adjoint of num_w wrt Lf knots
    dq = np.zeros_like(Lf)
    # pair j uses a=Lf[j], b=Lf[j+1], weight w[j]
    # d/da of w*(a^2+ab+b^2)/3 = w*(2a+b)/3
    # d/db of w*(a^2+ab+b^2)/3 = w*(a+2b)/3
    dq[:-1] += w * (2 * a + b) / 3.0
    dq[1:] += w * (a + 2 * b) / 3.0
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num_w
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num_w) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_all_pos_w(h0, maxiter, deadline, delta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad_w(hh, delta)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_block_w(h0, free, maxiter, deadline, delta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_w(hh, delta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    total_acc = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        best_cand = None
        best_cand_R = bestR
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
            total_acc += 1
        else:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()

    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


# ---------------- Experiment: recursive 3-way run splitting ----------------

def _find_runs(h, peak_thresh_frac=0.7, K_cap=32):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    pos = h > 0
    if not pos.any():
        return []
    gmax = h.max()
    thr = peak_thresh_frac * gmax
    runs = []
    i = 0
    while i < n:
        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            pk = h[i:j + 1].max()
            if pk >= thr:
                runs.append((pk, np.arange(i, j + 1)))
            i = j + 1
        else:
            i += 1
    runs.sort(key=lambda t: -t[0])
    runs = [r for _, r in runs[:K_cap]]
    return runs


def _softmax3(f1, f2, f3):
    m = max(f1, f2, f3)
    e1 = np.exp(f1 - m); e2 = np.exp(f2 - m); e3 = np.exp(f3 - m)
    Z = e1 + e2 + e3
    return e1 / Z, e2 / Z, e3 / Z


def _splat3(h, runs, d1, d2, f1, f2, f3):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    out = h.copy()
    K = len(runs)
    for k, cells in enumerate(runs):
        a1 = float(f1[k]); a2 = float(f2[k]); a3 = float(f3[k])
        w1, w2, w3 = _softmax3(a1, a2, a3)
        s1 = float(d1[k]); s2 = 0.0; s3 = float(d2[k])
        masses = h[cells]
        out[cells] -= masses
        for j, m in zip(cells, masses):
            if m == 0.0:
                continue
            for (shift, frac) in ((s1, w1), (s2, w2), (s3, w3)):
                if frac <= 0.0:
                    continue
                center = j + shift
                i0 = int(np.floor(center - 1.0))
                i1 = int(np.ceil(center + 1.0))
                for i in range(i0, i1 + 1):
                    if i < 0 or i >= n:
                        continue
                    w = 1.0 - abs(i - center)
                    if w > 0.0:
                        out[i] += m * frac * w
    return np.clip(out, 0.0, None)


def _splat3_grad(h, runs, d1, d2, f1, f2, f3, dRdh):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    K = len(runs)
    gd1 = np.zeros(K); gd2 = np.zeros(K)
    gf1 = np.zeros(K); gf2 = np.zeros(K); gf3 = np.zeros(K)
    for k, cells in enumerate(runs):
        a1 = float(f1[k]); a2 = float(f2[k]); a3 = float(f3[k])
        w1, w2, w3 = _softmax3(a1, a2, a3)
        s1 = float(d1[k]); s3 = float(d2[k])
        masses = h[cells]
        w = np.array([w1, w2, w3])
        J = np.diag(w) - np.outer(w, w)
        acc_d1 = 0.0; acc_d2 = 0.0
        acc_f = np.zeros(3)
        for j, m in zip(cells, masses):
            if m == 0.0:
                continue
            for idx, (shift, frac, dshift_dd) in enumerate((
                    (s1, w1, 1.0), (0.0, w2, 0.0), (s3, w3, 1.0))):
                center = j + shift
                i0 = int(np.floor(center - 1.0))
                i1 = int(np.ceil(center + 1.0))
                for i in range(i0, i1 + 1):
                    if i < 0 or i >= n:
                        continue
                    dd = i - center
                    wgt = 1.0 - abs(dd)
                    if wgt > 0.0:
                        g = dRdh[i] * m
                        dw_dshift = np.sign(dd)
                        if idx == 0:
                            acc_d1 += g * frac * dw_dshift * dshift_dd
                        elif idx == 2:
                            acc_d2 += g * frac * dw_dshift * dshift_dd
                        acc_f += g * wgt * J[idx, :]
        gd1[k] = acc_d1
        gd2[k] = acc_d2
        gf1[k] = acc_f[0]
        gf2[k] = acc_f[1]
        gf3[k] = acc_f[2]
    return gd1, gd2, gf1, gf2, gf3


def _splat3_opt(h, runs, d1, d2, f1, f2, f3, maxiter, deadline,
                free_params=True, free_heights=False, height_cells=None):
    if time.process_time() >= deadline - 0.3:
        return h, d1, d2, f1, f2, f3
    K = len(runs)
    if K == 0:
        return h, d1, d2, f1, f2, f3
    h = np.clip(h, 0, None)
    n = h.size
    d1 = np.clip(d1.copy(), -1.5, 1.5)
    d2 = np.clip(d2.copy(), -1.5, 1.5)
    f1 = f1.copy(); f2 = f2.copy(); f3 = f3.copy()

    if free_heights and height_cells is not None:
        hcells = np.asarray(height_cells, dtype=int)
        n_h = hcells.size
        x0v = np.concatenate([d1, d2, f1, f2, f3, h[hcells]])

        def unpack(xv):
            dd1 = np.clip(xv[:K], -1.5, 1.5)
            dd2 = np.clip(xv[K:2 * K], -1.5, 1.5)
            ff1 = xv[2 * K:3 * K]
            ff2 = xv[3 * K:4 * K]
            ff3 = xv[4 * K:5 * K]
            hh = h.copy()
            hh[hcells] = np.clip(xv[5 * K:], 0.0, None)
            return dd1, dd2, ff1, ff2, ff3, hh

        def f(xv):
            dd1, dd2, ff1, ff2, ff3, hh = unpack(xv)
            h2 = _splat3(hh, runs, dd1, dd2, ff1, ff2, ff3)
            val, g2 = _fun_grad(h2)
            gd1, gd2, gf1, gf2, gf3 = _splat3_grad(
                hh, runs, dd1, dd2, ff1, ff2, ff3, g2)
            gh = g2[hcells]
            return val, np.concatenate([gd1, gd2, gf1, gf2, gf3, gh])

        bounds = ([( -1.5, 1.5)] * K + [(-1.5, 1.5)] * K +
                  [(None, None)] * (3 * K) + [(0.0, None)] * n_h)
    else:
        x0v = np.concatenate([d1, d2, f1, f2, f3])

        def f(xv):
            dd1 = np.clip(xv[:K], -1.5, 1.5)
            dd2 = np.clip(xv[K:2 * K], -1.5, 1.5)
            ff1 = xv[2 * K:3 * K]
            ff2 = xv[3 * K:4 * K]
            ff3 = xv[4 * K:5 * K]
            h2 = _splat3(h, runs, dd1, dd2, ff1, ff2, ff3)
            val, g2 = _fun_grad(h2)
            gd1, gd2, gf1, gf2, gf3 = _splat3_grad(
                h, runs, dd1, dd2, ff1, ff2, ff3, g2)
            return val, np.concatenate([gd1, gd2, gf1, gf2, gf3])

        bounds = ([(-1.5, 1.5)] * K + [(-1.5, 1.5)] * K +
                  [(None, None)] * (3 * K))

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0v, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h, d1, d2, f1, f2, f3
    if res is None:
        return h, d1, d2, f1, f2, f3

    if free_heights and height_cells is not None:
        dd1, dd2, ff1, ff2, ff3, hh = unpack(res.x)
        h2 = _splat3(hh, runs, dd1, dd2, ff1, ff2, ff3)
        return h2, dd1, dd2, ff1, ff2, ff3
    else:
        dd1 = np.clip(res.x[:K], -1.5, 1.5)
        dd2 = np.clip(res.x[K:2 * K], -1.5, 1.5)
        ff1 = res.x[2 * K:3 * K]
        ff2 = res.x[3 * K:4 * K]
        ff3 = res.x[4 * K:5 * K]
        h2 = _splat3(h, runs, dd1, dd2, ff1, ff2, ff3)
        return h2, dd1, dd2, ff1, ff2, ff3


def _local_repair_runs(h, runs, deadline, iters=80):
    h = np.clip(h, 0, None).copy()
    n = h.size
    for cells in runs:
        if time.process_time() >= deadline - 0.3:
            break
        lo = max(0, int(cells[0]) - 48)
        hi = min(n - 1, int(cells[-1]) + 48)
        free = np.arange(lo, hi + 1)
        h = _lbfgs_block(h, free, iters, deadline, beta=0.0)
    return h


def _split_experiment(base, baseR, deadline, rng):
    h = np.clip(base, 0, None).copy()
    n = h.size
    runs = _find_runs(h, peak_thresh_frac=0.7, K_cap=32)
    K = len(runs)
    print("splat3: K=%d runs kept (of %d cells, N=%d)" %
          (K, int(np.sum(h > 0)), n))
    if K == 0:
        return h, baseR, None, -1.0

    best_h = h.copy()
    bestR = baseR

    d1 = np.full(K, -0.5); d2 = np.full(K, 0.5)
    f1 = np.zeros(K); f2 = np.zeros(K); f3 = np.zeros(K)

    h1, d1, d2, f1, f2, f3 = _splat3_opt(
        best_h, runs, d1, d2, f1, f2, f3, 300, deadline - 6.0,
        free_params=True, free_heights=False)
    r1 = R_of(h1)
    if r1 > bestR + 1e-13:
        best_h, bestR = h1, r1
    if time.process_time() < deadline - 5.0:
        hr = _local_repair_runs(best_h, runs, deadline - 5.0, iters=80)
        rr = R_of(hr)
        if rr > bestR + 1e-13:
            best_h, bestR = hr, rr
    print("splat3 R1: R=%.7f" % bestR)

    if time.process_time() < deadline - 8.0:
        runs2 = _find_runs(best_h, peak_thresh_frac=0.7, K_cap=16)
        K2 = len(runs2)
        if K2 > 0:
            d1b = np.full(K2, -0.5); d2b = np.full(K2, 0.5)
            f1b = np.zeros(K2); f2b = np.zeros(K2); f3b = np.zeros(K2)
            h2, d1b, d2b, f1b, f2b, f3b = _splat3_opt(
                best_h, runs2, d1b, d2b, f1b, f2b, f3b, 300, deadline - 4.0,
                free_params=True, free_heights=False)
            r2 = R_of(h2)
            if r2 > bestR + 1e-13:
                best_h, bestR = h2, r2
            if time.process_time() < deadline - 3.5:
                hr = _local_repair_runs(best_h, runs2, deadline - 3.5, iters=80)
                rr = R_of(hr)
                if rr > bestR + 1e-13:
                    best_h, bestR = hr, rr
            print("splat3 R2: R=%.7f" % bestR)

    if time.process_time() < deadline - 4.0:
        runs_all = _find_runs(best_h, peak_thresh_frac=0.7, K_cap=32)
        K3 = len(runs_all)
        if K3 > 0:
            d1c = np.zeros(K3); d2c = np.zeros(K3)
            f1c = np.zeros(K3); f2c = np.zeros(K3); f3c = np.zeros(K3)
            hcells_list = []
            for cells in runs_all:
                lo = max(0, int(cells[0]) - 48)
                hi = min(n - 1, int(cells[-1]) + 48)
                hcells_list.append(np.arange(lo, hi + 1))
            hcells = np.unique(np.concatenate(hcells_list))
            hj, d1c, d2c, f1c, f2c, f3c = _splat3_opt(
                best_h, runs_all, d1c, d2c, f1c, f2c, f3c, 400,
                deadline - 2.0, free_params=True, free_heights=True,
                height_cells=hcells)
            rj = R_of(hj)
            if rj > bestR + 1e-13:
                best_h, bestR = hj, rj
            print("splat3 joint: R=%.7f" % bestR)

    return best_h, bestR, best_h.copy(), bestR


# ---------------- Experiment: deficit-reweighted gradient ----------------

def _mid_band_stats(h):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0, 0
    g = Lf / M
    mask = (g > 0.3) & (g < 0.9)
    cnt = int(np.sum(mask))
    mean_g = float(np.mean(g[mask])) if cnt > 0 else 0.0
    return mean_g, cnt


def _fd_check_w(h, delta, eps=1e-6):
    _, g = _fun_grad_w(h, delta)
    n = h.size
    idxs = np.linspace(0, n - 1, 8).astype(int)
    maxrel = 0.0
    for i in idxs:
        if h[i] <= 0:
            continue
        hp = h.copy(); hp[i] += eps
        hm = h.copy(); hm[i] -= eps
        vp, _ = _fun_grad_w(hp, delta)
        vm, _ = _fun_grad_w(hm, delta)
        fd = (vp - vm) / (2 * eps)
        an = g[i]
        rel = abs(fd - an) / max(abs(fd), abs(an), 1e-12)
        if rel > maxrel:
            maxrel = rel
    return maxrel


def _deficit_experiment(best, bestR, deadline):
    deltas = [0.02, 0.005, 0.002, 0.001]
    cur = best.copy()
    curR = bestR
    alt = None
    altR = -1.0
    fd_done = False
    for rnd, delta in enumerate(deltas):
        if time.process_time() >= deadline - 1.0:
            break
        if not fd_done:
            try:
                rel = _fd_check_w(cur, delta)
                print("deficit FD max rel err (delta=%.4f): %.2e" %
                      (delta, rel))
            except Exception as e:
                print("deficit FD failed: %s" % e)
            fd_done = True
        # full-array weighted L-BFGS
        h1 = _lbfgs_all_pos_w(cur, 200, deadline - 0.5, delta)
        # peak-window polish with same weighted gradient
        if time.process_time() < deadline - 0.5:
            win = _peak_window(h1, pad_frac=0.25, extra=128)
            h2 = _lbfgs_block_w(h1, win, 150, deadline - 0.5, delta)
        else:
            h2 = h1
        r2 = R_of(h2)
        mg, cnt = _mid_band_stats(h2)
        improved = r2 > curR + 1e-13
        print("deficit round %d (delta=%.4f): R=%.7f midband_mean_g=%.4f "
              "midband_count=%d %s" %
              (rnd, delta, r2, mg, cnt, "ACCEPT" if improved else "reject"))
        if alt is None or r2 > altR:
            alt = h2.copy()
            altR = r2
        if improved:
            cur = h2
            curR = r2
    return cur, curR, alt, altR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- Experiment: deficit-reweighted gradient ----
    if time.process_time() < deadline - 12.0:
        try:
            exp_h, expR, alt_h, altR_exp = _deficit_experiment(
                best, bestR, deadline - 10.0)
            if alt_h is not None:
                alt_cand, altR = alt_h.copy(), altR_exp
            if expR > bestR + 1e-13:
                best, bestR = exp_h.copy(), expR
                print("deficit wins: R=%.7f (was %.7f)" %
                      (bestR, start_bestR))
            else:
                print("deficit did not beat base: %.7f vs %.7f" %
                      (expR, bestR))
        except Exception as e:
            print("deficit experiment failed: %s" % e)

    # ---- Keep the base's proven machinery ----
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    out = {"best": best}
    if alt_cand is not None and altR > bestR + 1e-13:
        out["alternative"] = alt_cand
    elif alt_cand is not None:
        out["alternative"] = alt_cand
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------------- Experiment: edge-shaped support extension ----------------

def _active_support(h, thresh_frac=1e-6):
    mx = h.max()
    if mx <= 0:
        return 0, h.size - 1
    pos = np.flatnonzero(h > thresh_frac * mx)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


def _extend_side(h, side, tau, pad):
    """Return a new array with `pad` cells appended on `side` ('left'/'right')
    using geometric continuation from the edge value."""
    n = h.size
    if side == 'left':
        edge = h[0]
    else:
        edge = h[-1]
    k = np.arange(1, pad + 1, dtype=float)
    if tau is None:
        # constant continuation
        pad_vals = np.full(pad, edge, dtype=float)
    else:
        pad_vals = edge * np.exp(-k / tau)
    if side == 'left':
        return np.concatenate((pad_vals[::-1], h))
    else:
        return np.concatenate((h, pad_vals))


def _build_candidate(h, tau_l, tau_r, pad):
    h2 = h
    if tau_l is not None:
        h2 = _extend_side(h2, 'left', tau_l, pad)
    if tau_r is not None:
        h2 = _extend_side(h2, 'right', tau_r, pad)
    return _rescale(h2)


def _extension_experiment(best, bestR, deadline):
    """Try support extension with edge-shaped continuation."""
    n = best.size
    i0, i1 = _active_support(best)
    print("active support [%d,%d] len=%d (N=%d)" % (i0, i1, i1 - i0 + 1, n))
    lo5 = best[max(0, i0):min(n, i0 + 5)]
    hi5 = best[max(0, i1 - 4):min(n, i1 + 1)]
    print("left edge 5: " + " ".join("%.3e" % v for v in lo5))
    print("right edge 5: " + " ".join("%.3e" % v for v in hi5))

    pad = 4000
    taus = [150, 600, 2500]
    # 6 combos: (tau_l, tau_r) independently, plus constant variant
    combos = []
    for tl in taus:
        for tr in taus:
            combos.append((tl, tr, 'exp'))
    # constant continuation variant
    combos.append((None, None, 'const'))

    best_cand = None
    best_cand_R = bestR
    best_cand_desc = None
    for tl, tr, kind in combos:
        if time.process_time() >= deadline - 0.5:
            break
        h2 = _build_candidate(best, tl, tr, pad)
        r = R_of(h2)
        desc = "%s tl=%s tr=%s" % (kind, tl, tr)
        print("cand %s: R=%.9f (dR=%.3e)" % (desc, r, r - bestR))
        if r > best_cand_R + 1e-15:
            best_cand = h2
            best_cand_R = r
            best_cand_desc = desc

    if best_cand is None:
        print("no candidate beat start; extension closed")
        return best, bestR, 'none'

    print("best cand: %s R=%.9f" % (best_cand_desc, best_cand_R))

    # Polish: peak-window ladder restricted to outer 4000 cells + peak window
    cur = best_cand
    curR = best_cand_R
    n2 = cur.size
    outer = np.concatenate((np.arange(0, pad),
                            np.arange(n2 - pad, n2)))
    for frac in (0.05, 0.20, 0.50):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(cur, pad_frac=frac, extra=256)
        free = np.unique(np.concatenate((outer, win)))
        ht = _lbfgs_block(cur, free, 250, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        print("polish frac=%.2f R=%.9f" % (frac, r))
        if r > curR + 1e-15:
            cur = ht
            curR = r

    return cur, curR, best_cand_desc


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Experiment: edge-shaped support extension ----
    try:
        ext_h, ext_R, desc = _extension_experiment(
            best, bestR, deadline - 18.0)
        if ext_R > bestR + 1e-13:
            best, bestR = ext_h, ext_R
            origin = 'extension(%s)' % desc
            print("extension improved: R=%.7f origin=%s" % (bestR, origin))
        else:
            print("extension did not improve (best=%.7f)" % ext_R)
    except Exception as e:
        print("extension failed: %s" % e)

    # ---- Base's proven machinery on the best array ----
    if time.process_time() < deadline - 4.0:
        ht, rt = run_cycle(best, bestR, deadline - 4.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+cycle'
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # Final polish
    if time.process_time() < deadline - 0.5:
        ht, rt = run_cycle(best, bestR, deadline - 0.5)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+final'
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _extend(h, pad):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = 1e-3 * h.mean()
    filler = np.full(pad, eps)
    out = np.concatenate((filler, h, filler))
    return _rescale(out)


def _kkt_diagnostic(h):
    val, grad = _fun_grad(np.clip(h, 0, None))
    g = -grad
    hmax = h.max() if h.size else 0.0
    zero_mask = h <= 1e-12 * hmax
    pos_mask = ~zero_mask
    gz = g[zero_mask]
    gp = g[pos_mask]
    def stats(a):
        if a.size == 0:
            return (0.0, 0.0, 0.0)
        return (float(a.max()), float(a.mean()), float(np.median(a)))
    sz = stats(gz)
    sp = stats(gp)
    print("KKT: zeros n=%d max=%.3e mean=%.3e med=%.3e | pos n=%d max=%.3e mean=%.3e med=%.3e"
          % (gz.size, sz[0], sz[1], sz[2], gp.size, sp[0], sp[1], sp[2]))
    return g, zero_mask


def _warp(h, gamma):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    s = h.sum()
    if s <= 0:
        return h
    N = h.size
    C = np.concatenate(([0.0], np.cumsum(h))) / s
    u = np.linspace(0.0, 1.0, N + 1)
    v = u ** gamma
    newC = np.interp(v, u, C)
    out = np.diff(newC)
    return _rescale(np.clip(out, 0, None))


# ---------- fresh seed builders ----------

def _seed_comb(N, p, a):
    i = np.arange(N, dtype=float)
    u = (i + 0.5) / N
    env = (1.0 - (2.0 * u - 1.0) ** 2) ** a
    cell = (i.astype(int) % p) == 0
    h = env * cell.astype(float)
    return _rescale(h)


def _seed_random_sparse(N, q, rng):
    mask = rng.random(N) < q
    h = np.zeros(N)
    lo, hi = np.log(1e-3), np.log(1.0)
    vals = np.exp(rng.uniform(lo, hi, size=N))
    h[mask] = vals[mask]
    if h.sum() <= 0:
        h[:] = 1.0
    return _rescale(h)


def _seed_blocky(N, nblocks, rng):
    edges = np.linspace(0, N, nblocks + 1).astype(int)
    lo, hi = np.log(1e-3), np.log(1.0)
    vals = np.exp(rng.uniform(lo, hi, size=nblocks))
    h = np.empty(N)
    for b in range(nblocks):
        h[edges[b]:edges[b + 1]] = vals[b]
    return _rescale(h)


def _prolong(h, Nnew):
    """Cumulative-mass prolongation to Nnew steps."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    s = h.sum()
    if s <= 0:
        return np.ones(Nnew)
    N = h.size
    C = np.concatenate(([0.0], np.cumsum(h))) / s
    u = np.linspace(0.0, 1.0, N + 1)
    v = np.linspace(0.0, 1.0, Nnew + 1)
    newC = np.interp(v, u, C)
    out = np.diff(newC)
    return _rescale(np.clip(out, 0, None))


def _polish_ladder(h, deadline):
    """5s-ish polish: global beta=0, beta ladder, peak windows."""
    r = R_of(h)
    best, bestR = h, r
    if time.process_time() >= deadline - 0.3:
        return best, bestR
    ht = _lbfgs_all_pos(best, 400, deadline, beta=0.0)
    r = R_of(ht)
    if r > bestR:
        best, bestR = ht, r
    for beta in (1e3, 1e5, 1e7):
        if time.process_time() >= deadline - 0.3:
            break
        ht = _lbfgs_all_pos(best, 200, deadline, beta=beta)
        r = R_of(ht)
        if r > bestR:
            best, bestR = ht, r
    for frac in (0.2, 0.5):
        if time.process_time() >= deadline - 0.3:
            break
        win = _peak_window(best, pad_frac=frac, extra=128)
        ht = _lbfgs_block(best, win, maxiter=200, deadline=deadline, beta=1e7)
        r = R_of(ht)
        if r > bestR:
            best, bestR = ht, r
    if time.process_time() < deadline - 0.3:
        ht = _lbfgs_all_pos(best, 200, deadline, beta=0.0)
        r = R_of(ht)
        if r > bestR:
            best, bestR = ht, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ================= D8 FLIP: fresh seeds =================
    N0 = 4096
    rng = np.random.default_rng(12345)
    seeds = []
    # (i) analytic duty-combs
    seeds.append(("comb p=3 a=0.3", _seed_comb(N0, 3, 0.3)))
    seeds.append(("comb p=4 a=1.0", _seed_comb(N0, 4, 1.0)))
    seeds.append(("comb p=3 a=3.0", _seed_comb(N0, 3, 3.0)))
    # (ii) random sparse
    seeds.append(("rand q=0.20", _seed_random_sparse(N0, 0.20, rng)))
    seeds.append(("rand q=0.35", _seed_random_sparse(N0, 0.35, rng)))
    seeds.append(("rand q=0.50", _seed_random_sparse(N0, 0.50, rng)))
    # (iii) blocky
    seeds.append(("block 16", _seed_blocky(N0, 16, rng)))
    seeds.append(("block 32", _seed_blocky(N0, 32, rng)))

    # Budget split: give each seed ~5s at N=4096 (8 seeds = 40s), then escalate.
    # But we must reserve time for escalation + base fallback. Use adaptive.
    n_seeds = len(seeds)
    # reserve ~40% of budget for escalation + base run_cycle
    seed_phase_end = t0 + budget_seconds * 0.55
    per_seed = max(1.0, (seed_phase_end - time.process_time()) / n_seeds)

    seed_results = []
    for name, h0 in seeds:
        now = time.process_time()
        if now >= seed_phase_end - 0.5:
            print("seed %-16s SKIPPED (time)" % name)
            continue
        sd = min(seed_phase_end, now + per_seed)
        r0 = R_of(h0)
        h1, r1 = _polish_ladder(h0, sd)
        print("seed %-16s R0=%.5f -> R=%.7f" % (name, r0, r1))
        seed_results.append((name, h1, r1))

    seed_results.sort(key=lambda t: -t[2])
    print("--- seed ranking (N=%d) ---" % N0)
    for name, _, r in seed_results:
        print("  %-16s %.7f" % (name, r))

    # Take best two, escalate 4096 -> 16384 -> 65536
    top = seed_results[:2]
    escalated = []
    esc_end = t0 + budget_seconds * 0.80
    for name, h, r in top:
        cur, curR = h, r
        for Nnew in (16384, 65536):
            now = time.process_time()
            if now >= esc_end - 0.5:
                break
            # split remaining escalation time among remaining levels/seeds
            cur = _prolong(cur, Nnew)
            sd = min(esc_end, time.process_time() + max(1.0, (esc_end - now) / 2.0))
            cur, curR = _polish_ladder(cur, sd)
            print("  esc %-16s N=%d R=%.7f" % (name, Nnew, curR))
        escalated.append((name, cur, curR))

    # At N=65536 give the best seed the base's full run_cycle until deadline
    if escalated:
        escalated.sort(key=lambda t: -t[2])
        name, h, r = escalated[0]
        print("best fresh seed: %s R=%.7f (N=%d)" % (name, r, h.size))
        if time.process_time() < deadline - 2.0:
            h2, r2, _ = run_cycle(h, r, deadline - 1.0)
            print("fresh run_cycle: R=%.7f" % r2)
            escalated[0] = (name, h2, r2)

    # Track best fresh result
    fresh_best, fresh_bestR, fresh_name = None, 0.0, None
    for name, h, r in escalated:
        if r > fresh_bestR:
            fresh_best, fresh_bestR, fresh_name = h, r, name
    if fresh_best is not None:
        print("FRESH BEST: %s R=%.7f" % (fresh_name, fresh_bestR))

    # ================= Base fallback (p1003) =================
    # Run base's full pipeline on start_best if time remains
    if time.process_time() < deadline - 2.0:
        b, bR = start_best.copy(), start_bestR
        # warp restarts
        gammas = [0.90, 1.10]
        for gamma in gammas:
            if time.process_time() >= deadline - 6.0:
                break
            hw = _warp(start_best, gamma)
            r0 = R_of(hw)
            cur, curR, _ = run_cycle(hw, r0, deadline - 6.0)
            if curR > bR + 1e-13:
                b, bR = cur.copy(), curR
        # base cycle
        if time.process_time() < deadline - 2.0:
            b, bR, _ = run_cycle(b, bR, deadline - 1.5)
        # multi-zero activation
        g, zero_mask = _kkt_diagnostic(b)
        zero_idx = np.flatnonzero(zero_mask)
        if zero_idx.size > 0:
            order = np.argsort(-g[zero_idx])
            ranked_zeros = zero_idx[order]
            hmean = b.mean()
            for k in (32, 128):
                for a in (1e-2, 1e-1):
                    if time.process_time() >= deadline - 4.0:
                        break
                    kk = min(k, ranked_zeros.size)
                    cand = b.copy()
                    cand[ranked_zeros[:kk]] = a * hmean
                    cand = _rescale(cand)
                    win = _peak_window(cand, pad_frac=0.10, extra=128)
                    cand = _lbfgs_block(cand, win, maxiter=200,
                                        deadline=deadline - 4.0, beta=1e8)
                    cand = _lbfgs_all_pos(cand, 200, deadline - 4.0, beta=0.0)
                    r = R_of(cand)
                    if r > bR + 1e-13:
                        b, bR = cand.copy(), r
        # closing polish
        if time.process_time() < deadline - 0.8:
            ht = _lbfgs_all_pos(b, 3000, deadline - 0.5)
            r = R_of(ht)
            if r > bR + 1e-14:
                b, bR = ht.copy(), r
        if bR > bestR:
            best, bestR = b.copy(), bR

    print("final base R=%.7f (N=%d)" % (bestR, best.size))
    if fresh_best is not None:
        print("final fresh R=%.7f (N=%d)" % (fresh_bestR, fresh_best.size))

    # Return best exact-R among {base, fresh seeds}
    if fresh_best is not None and fresh_bestR > bestR + 1e-12:
        # fresh seed genuinely wins
        return fresh_best
    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    # keep fresh seed as alternative if it's a genuinely different construction
    if fresh_best is not None and fresh_bestR > start_bestR - 0.05:
        out["alternative"] = fresh_best
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _num_dq_p(h, p):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    d = b - a
    pp = p + 1.0
    num = np.empty_like(a)
    dqa = np.empty_like(a)
    dqb = np.empty_like(a)
    big = np.abs(d) > 1e-12
    an = a[big]; bn = b[big]; dn = d[big]
    ap = np.power(np.clip(an, 0.0, None), pp)
    bp = np.power(np.clip(bn, 0.0, None), pp)
    num[big] = (bp - ap) / (pp * dn)
    denom = (pp * dn) ** 2
    dqa[big] = (-pp * np.power(np.clip(an, 0.0, None), p) * pp * dn
                + (bp - ap)) / denom
    dqb[big] = (pp * np.power(np.clip(bn, 0.0, None), p) * pp * dn
                - (bp - ap)) / denom
    ad = a[~big]
    apow = np.power(np.clip(ad, 0.0, None), p)
    num[~big] = apow
    g = p * np.power(np.clip(ad, 0.0, None), p - 1.0)
    dqa[~big] = 0.5 * g
    dqb[~big] = 0.5 * g
    dq = np.zeros_like(Lf)
    dq[:-1] += dqa
    dq[1:] += dqb
    return float(np.sum(num)), dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_p(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_dq_p(h, p)
    if num <= 0:
        return 1e18, np.zeros(h.size)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    if Lm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[m] += p / Lm
    grad = _backprop(gLf, h) + 2.0 * p / s
    val = -np.log(num) + 2.0 * p * np.log(s) + p * np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, p=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if p > 0:
        fg = (lambda hh: _fun_grad_p(hh, p))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, p=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if p > 0:
        fg = (lambda hh: _fun_grad_p(hh, p))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    total_acc = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        best_cand = None
        best_cand_R = bestR
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
            total_acc += 1
        else:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()

    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


# ---------------- Experiment: continuous spike-density rasterisation ----------

def _runs(h, thresh_frac=1e-3):
    """Return (centers, heights) of maximal runs with h > thresh_frac*max."""
    mx = h.max()
    if mx <= 0:
        return np.array([]), np.array([])
    mask = h > thresh_frac * mx
    # find run boundaries
    d = np.diff(mask.astype(np.int8))
    starts = np.flatnonzero(d == 1) + 1
    ends = np.flatnonzero(d == -1) + 1
    if mask[0]:
        starts = np.concatenate(([0], starts))
    if mask[-1]:
        ends = np.concatenate((ends, [h.size]))
    centers = []
    heights = []
    for s, e in zip(starts, ends):
        seg = h[s:e]
        centers.append(s + int(np.argmax(seg)))
        heights.append(float(seg.max()))
    return np.array(centers, dtype=float), np.array(heights, dtype=float)


def _envelope(centers, heights, K):
    """E(u) for u in [0,1] via normalized-rank interpolation + 5pt smoothing."""
    if centers.size == 0:
        return np.ones(K)
    u = np.linspace(0.0, 1.0, centers.size)
    uu = np.linspace(0.0, 1.0, K)
    E = np.interp(uu, u, heights)
    if E.size >= 5:
        ker = np.ones(5) / 5.0
        Ep = np.convolve(E, ker, mode='same')
        # fix edges
        Ep[:2] = E[:2]
        Ep[-2:] = E[-2:]
        E = Ep
    return E


def _raster_uniform(c1, cK, P, E, N, total_mass):
    if P <= 0:
        return None
    KP = int(np.floor((cK - c1) / P)) + 1
    if KP < 2:
        return None
    h = np.zeros(N)
    k = np.arange(KP)
    pos = np.round(c1 + k * P).astype(int)
    pos = np.clip(pos, 0, N - 1)
    # envelope at normalized rank
    uu = k / max(1, KP - 1)
    EK = np.interp(uu, np.linspace(0, 1, E.size), E)
    # accumulate (positions may collide)
    np.add.at(h, pos, EK)
    s = h.sum()
    if s <= 0:
        return None
    h *= total_mass / s
    return h


def _raster_bresenham(c1, cK, mean_period, E, N, total_mass):
    """Gap sequence alternating 3/4 with given mean period."""
    if mean_period <= 0:
        return None
    span = cK - c1
    if span <= 0:
        return None
    K = int(np.floor(span / mean_period)) + 1
    if K < 2:
        return None
    # alternate gaps g1,g2 with mean = mean_period
    # choose g1 = floor(mean), g2 = ceil(mean); fraction of g2 to hit mean
    g1 = int(np.floor(mean_period))
    g2 = g1 + 1
    frac2 = mean_period - g1  # fraction of g2 steps
    if frac2 <= 0:
        gaps = np.full(K - 1, g1, dtype=int)
    elif frac2 >= 1:
        gaps = np.full(K - 1, g2, dtype=int)
    else:
        # Bresenham: cumulative
        gaps = np.empty(K - 1, dtype=int)
        acc = 0.0
        for i in range(K - 1):
            acc += frac2
            if acc >= 1.0:
                gaps[i] = g2
                acc -= 1.0
            else:
                gaps[i] = g1
    pos = np.empty(K, dtype=int)
    pos[0] = int(round(c1))
    for i in range(1, K):
        pos[i] = pos[i - 1] + gaps[i - 1]
    pos = np.clip(pos, 0, N - 1)
    h = np.zeros(N)
    uu = np.arange(K) / max(1, K - 1)
    EK = np.interp(uu, np.linspace(0, 1, E.size), E)
    np.add.at(h, pos, EK)
    s = h.sum()
    if s <= 0:
        return None
    h *= total_mass / s
    return h


def _polish_top(h, deadline, iters=250):
    """Peak-window ladder with beta 1e6 then 1e7, pad 0.20 and 0.50."""
    if time.process_time() >= deadline - 0.5:
        return h
    for beta in (1e6, 1e7):
        for frac in (0.20, 0.50):
            if time.process_time() >= deadline - 0.5:
                return h
            win = _peak_window(h, pad_frac=frac, extra=128)
            h = _lbfgs_block(h, win, iters, deadline - 0.5, beta=beta)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    N = best.size
    total_mass = best.sum()
    print("base R=%.7f (N=%d)" % (bestR, N))

    # ---- Experiment: continuous spike-density rasterisation ----
    alt_best = None
    alt_bestR = -1.0
    try:
        centers, heights = _runs(best, thresh_frac=1e-3)
        print("runs: K=%d, span=%.1f, mean_period=%.3f" %
              (centers.size,
               (centers[-1] - centers[0]) if centers.size else 0.0,
               ((centers[-1] - centers[0]) / max(1, centers.size - 1))
               if centers.size > 1 else 0.0))
        if centers.size >= 4:
            c1 = centers[0]
            cK = centers[-1]
            # envelope on a fine grid (K_ref = centers.size)
            E = _envelope(centers, heights, centers.size)
            # candidate periods
            Ps = [2.90, 2.94, 2.97, 3.00, 3.03, 3.06, 3.12]
            cands = []
            for P in Ps:
                h = _raster_uniform(c1, cK, P, E, N, total_mass)
                if h is None:
                    continue
                r = R_of(h)
                cands.append((r, 'P=%.2f' % P, h))
                print("raster P=%.2f R=%.7f" % (P, r))
            # Bresenham rasters
            for mp in (2.857, 3.20):
                h = _raster_bresenham(c1, cK, mp, E, N, total_mass)
                if h is None:
                    continue
                r = R_of(h)
                cands.append((r, 'B=%.3f' % mp, h))
                print("raster B=%.3f R=%.7f" % (mp, r))
            if cands:
                cands.sort(key=lambda t: -t[0])
                # track best alternative
                alt_bestR = cands[0][0]
                alt_best = cands[0][2].copy()
                # polish top two
                top2 = cands[:2]
                for r, name, h in top2:
                    if time.process_time() >= deadline - 6.0:
                        break
                    hp = _polish_top(h, deadline - 6.0, iters=250)
                    rp = R_of(hp)
                    print("polished %s: %.7f -> %.7f" % (name, r, rp))
                    if rp > alt_bestR:
                        alt_bestR = rp
                        alt_best = hp.copy()
                    if rp > bestR + 1e-13:
                        best = hp.copy()
                        bestR = rp
    except Exception as e:
        print("raster experiment failed: %s" % e)

    # ---- Keep the base's proven machinery ----
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    if alt_best is not None and alt_bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": alt_best}
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _perturb(h, rng, scale):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    act = h > 1e-9 * h.max()
    out = h.copy()
    noise = np.exp(scale * rng.standard_normal(h.size))
    out[act] = out[act] * noise[act]
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase A: aggressively refine the start via the full pipeline.
    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f" % bestR)

    # Phase B: NEW IDEA -- knot-level refinement. The autoconvolution knots
    # live on a finer grid (2N-1). Optimise the *knot* values directly via a
    # least-squares inverse problem to produce a smoother, flatter-topped
    # f*f, then map back to heights. This is a different basin than height
    # optimisation.

    def _knot_level_polish(h, deadline_local, iters=6):
        """Alternate: (i) fit an ideal f*f shape that is a wide flat-top
        with sharp shoulders, (ii) project back to heights via a damped
        least-squares update on the log-height."""
        h = np.clip(h, 0, None)
        if h.sum() <= 0:
            return h
        n = h.size
        for _ in range(iters):
            if time.process_time() >= deadline_local - 0.3:
                break
            Lf = _knots(h)
            mx = Lf.max()
            if mx <= 0:
                break
            # Target: keep current shape but flatten the top plateau
            # by reweighting; use a beta-smoothed max in an LBFGS step.
            first = max(1, int(0.05 * n))
            last = min(n - 1, int(0.95 * n))
            free = np.arange(first, last + 1)
            ht = _lbfgs_block(h, free, maxiter=400,
                              deadline=deadline_local, beta=2e8)
            r = R_of(ht)
            if r >= R_of(h) - 1e-12:
                h = ht
            else:
                break
        return h

    if time.process_time() < deadline - 2.0:
        ht = _knot_level_polish(best, min(deadline - 1.5,
                                          time.process_time() + 12.0))
        r = R_of(ht)
        print("knot-polish R=%.7f" % r)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    # Phase C: strong beta-continuation from a fresh high-beta smoothing.
    if time.process_time() < deadline - 2.0:
        hb = best.copy()
        for beta in (1e6, 1e7, 5e7, 2e8, 1e9):
            if time.process_time() >= deadline - 1.5:
                break
            tl = min(deadline - 1.5, time.process_time() + 6.0)
            hb = _lbfgs_all_pos(hb, 300, tl, beta=beta)
        r = R_of(hb)
        print("beta-continuation R=%.7f" % r)
        if r > bestR + 1e-13:
            best, bestR = hb.copy(), r

    # Phase D: local search via small perturbations, keeping the best.
    n_pert = 0
    while time.process_time() < deadline - 1.5:
        now = time.process_time()
        remaining = deadline - 1.5 - now
        if remaining < 2.0:
            break
        cdl = now + min(remaining * 0.5, 6.0)
        scale = max(0.01, min(0.3, 0.03 * (1.0 + 0.5 * rng.standard_normal())))
        hp = _perturb(best, rng, scale)
        rp = R_of(hp)
        c1, r1, _ = run_cycle(hp, rp, cdl)
        n_pert += 1
        if r1 > bestR + 1e-13:
            best, bestR = c1.copy(), r1
            print("perturb #%d scale=%.3f R=%.7f" % (n_pert, scale, bestR))

    # Phase E: final full refinement to squeeze the last bits.
    while time.process_time() < deadline - 1.0:
        prev = bestR
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        if bestR - prev < 1e-10:
            break

    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if best.size != start_best.size or bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        best_cand = None
        best_cand_R = bestR
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
        else:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()
    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    stats['best_raw'] = max(stats['best_raw'], best_r - bestR)
    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


# --------- NEW: block-coordinate descent on a coarse grid of segments -----

def _block_cd(h, bestR, deadline, passes=4):
    """Divide the array into contiguous blocks and optimise each block's
    heights jointly (others fixed), sweeping back and forth. Different
    search geometry than the peak-window ladders."""
    n = h.size
    if n < 64:
        return h, bestR
    nb = 16
    edges = np.linspace(0, n, nb + 1).astype(int)
    for it in range(passes):
        if time.process_time() >= deadline - 0.5:
            break
        rng = range(nb) if (it % 2 == 0) else range(nb - 1, -1, -1)
        improved = False
        for bi in rng:
            if time.process_time() >= deadline - 0.5:
                break
            lo = max(0, edges[bi] - 4)
            hi = min(n - 1, edges[bi + 1] + 4)
            free = np.arange(lo, hi + 1)
            ht = _lbfgs_block(h, free, 60, deadline, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                h, bestR = ht, r
                improved = True
        if not improved:
            break
    return h, bestR


# --------- NEW: simulated-annealing style random perturbations ------------

def _random_perturb(best, bestR, deadline, rng):
    """Apply a small random multiplicative perturbation to a random window,
    re-optimise that window, accept if better."""
    n = best.size
    if n < 128:
        return best, bestR
    while time.process_time() < deadline - 0.5:
        w = int(rng.integers(32, max(64, n // 4)))
        w = min(w, n)
        c = int(rng.integers(0, n))
        lo = max(0, c - w // 2)
        hi = min(n, lo + w)
        if hi - lo < 8:
            break
        h2 = best.copy()
        amp = 0.05 + 0.25 * rng.random()
        noise = 1.0 + amp * rng.standard_normal(hi - lo)
        h2[lo:hi] = np.clip(h2[lo:hi] * noise, 0.0, None)
        free = np.arange(lo, hi)
        h2 = _lbfgs_block(h2, free, 80, deadline, beta=0.0)
        r2 = R_of(h2)
        if r2 > bestR + 1e-13:
            # polish locally
            lo2 = max(0, lo - 48)
            hi2 = min(n - 1, hi + 48)
            free2 = np.arange(lo2, hi2 + 1)
            h3 = _lbfgs_block(h2, free2, 60, deadline, beta=0.0)
            r3 = R_of(h3)
            if r3 > bestR + 1e-13:
                best, bestR = h3, r3
                continue
            best, bestR = h2, r2
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(987654321)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: short cycle on the start (cheap polish).
    if time.process_time() < deadline - 0.7:
        best, bestR = run_cycle(best, bestR, min(deadline - 0.5,
                                                 t0 + 0.30 * budget_seconds))
        print("phase1 R=%.7f" % bestR)

    # Phase 2: block-coordinate descent sweeps.
    if time.process_time() < deadline - 0.7:
        best, bestR = _block_cd(best, bestR,
                                min(deadline - 0.5,
                                    t0 + 0.55 * budget_seconds), passes=6)
        print("block-CD R=%.7f" % bestR)

    # Phase 3: dip moves + mini cycles until ~75% of budget.
    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    phase3_end = t0 + 0.78 * budget_seconds
    while time.process_time() < min(phase3_end, deadline - 0.6):
        best, bestR = _dip_moves(best, bestR,
                                 min(deadline - 0.5, phase3_end), stats)
        now = time.process_time()
        if now - last_mini > 8.0:
            last_mini = now
            if time.process_time() < min(phase3_end, deadline - 0.7):
                st, r = _mini_cycle(best, bestR,
                                    min(deadline - 0.6, phase3_end))
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip phase R=%.7f (dips=%d acc=%d)" %
          (bestR, stats['dips'], stats['accepted']))

    # Phase 4: random perturb-and-reoptimise until ~90% of budget.
    phase4_end = t0 + 0.90 * budget_seconds
    if time.process_time() < phase4_end - 0.6:
        best, bestR = _random_perturb(best, bestR,
                                      min(deadline - 0.5, phase4_end), rng)
        print("perturb R=%.7f" % bestR)

    # Phase 5: final polish cycle.
    if time.process_time() < deadline - 0.5:
        best, bestR = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tight=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    if tight:
        opts['ftol'] = 0.0
        opts['gtol'] = 0.0
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------------- Experiment: long un-restarted L-BFGS ----------------

def _long_run_phase(best, bestR, deadline):
    """Loop up to 6 times calling _lbfgs_all_pos with tight tolerances."""
    cur = best
    curR = bestR
    total_delta = 0.0
    for k in range(6):
        if time.process_time() >= deadline - 0.5:
            print("long-run: out of time at restart %d" % k)
            break
        ht = _lbfgs_all_pos(cur, 1500, deadline - 0.5, beta=0.0, tight=True)
        r = R_of(ht)
        d = r - curR
        total_delta += d
        print("long-run restart %d: R=%.9f dR=%.3e (cum=%.3e)"
              % (k, r, d, total_delta))
        if r > curR + 1e-15:
            cur, curR = ht, r
        else:
            # no improvement; break early to save budget
            if d < 1e-12:
                print("long-run: converged (dR<1e-12), stopping")
                break
    print("long-run total delta=%.3e final R=%.9f" % (total_delta, curR))
    return cur, curR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Experiment: long un-restarted L-BFGS phase ----
    try:
        lr_h, lr_R = _long_run_phase(best, bestR, deadline - 18.0)
        if lr_R > bestR + 1e-13:
            best, bestR = lr_h, lr_R
            origin = 'longrun'
            print("long-run improved: R=%.7f" % bestR)
        else:
            print("long-run did not improve (best=%.7f)" % lr_R)
    except Exception as e:
        print("long-run failed: %s" % e)

    # ---- Base's proven machinery on the best array ----
    if time.process_time() < deadline - 4.0:
        ht, rt = run_cycle(best, bestR, deadline - 4.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+cycle'
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Tight peak-window block polish with last ~6s ----
    try:
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            print("tight polish beta=0: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+tight0'
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            print("tight polish beta=1e7: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+tight7'
    except Exception as e:
        print("tight polish failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

