def _curv_pen(Lf):
    c = Lf[2:] - 2.0 * Lf[1:-1] + Lf[:-2]
    P = float(np.sum(c * c))
    gP = np.zeros_like(Lf)
    gP[2:] += 2.0 * c
    gP[1:-1] += -4.0 * c
    gP[:-2] += 2.0 * c
    return P, gP


def _fun_grad_curv(h, lam):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    P, gP = _curv_pen(Lf)
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    if lam > 0:
        gLf += lam * gP / (Lm * Lm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    if lam > 0:
        val += lam * P / (Lm * Lm)
