        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    if tight:
        opts['ftol'] = 0.0
        opts['gtol'] = 0.0
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_interior_beta(h0, free, beta, maxiter, deadline):
    return _lbfgs_block(h0, free, maxiter, deadline, beta=beta)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _interior_beta_phase(best, bestR, deadline):
    h = np.clip(best, 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return best, bestR
    active = np.flatnonzero(h > 1e-6 * mx)
    if active.size < 4:
        return best, bestR
    i0 = int(active.min())
    i1 = int(active.max())
    L = i1 - i0 + 1
    lo = i0 + int(0.10 * L)
    hi = i0 + int(0.90 * L)
    if hi <= lo:
        return best, bestR
    free = np.arange(lo, hi + 1)
    betas = [1e4, 3e4, 1e5, 3e5, 1e6, 3e6, 1e7]
    cur = h
    curR = bestR
    bestArr = best.copy()
    bestR2 = bestR
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_interior_beta(cur, free, beta, 80, deadline - 0.5)
        r = R_of(ht)
        if r > bestR2 + 1e-15:
            bestArr, bestR2 = ht.copy(), r
        cur, curR = ht, r
    return bestArr, bestR2


# ---------------- Experiment: cell-scale toe shaping ----------------

def _active_support(h):
    mx = h.max()
    if mx <= 0:
        return 0, h.size - 1
    act = np.flatnonzero(h > 1e-6 * mx)
    if act.size == 0:
        return 0, h.size - 1
    return int(act.min()), int(act.max())


def _make_toe(h, side, pad, a, tau, increasing=False):
    h = np.clip(h, 0, None)
    if side == 'left':
        edge = h[0]
    else:
        edge = h[-1]
    k = np.arange(1, pad + 1, dtype=float)
    if increasing:
        vals = a * edge * (1.0 + k / pad)
        if side == 'left':
            vals = vals[::-1]
    else:
        vals = a * edge * np.exp(-k / tau)
        if side == 'left':
            vals = vals[::-1]
    if side == 'left':
        out = np.concatenate((vals, h))
    else:
        out = np.concatenate((h, vals))
    return _rescale(out)


def _toe_phase(best, bestR, deadline):
    i0, i1 = _active_support(best)
    print("active support [%d,%d] N=%d" % (i0, i1, best.size))
    print("left outer 8: %s" % np.array2string(best[max(0, i0):i0 + 8], precision=4))
    print("right outer 8: %s" % np.array2string(best[max(0, i1 - 7):i1 + 1], precision=4))

    pads = [4, 8, 16, 32]
    amps = [0.5, 1.0, 2.0]
    taus = [0.5, 0.75, 1.0, 2.0, 4.0]

    candidates = []
    for side in ('left', 'right'):
        for pad in pads:
            for a in amps:
                for tau in taus:
                    if time.process_time() >= deadline - 0.5:
                        break
                    ht = _make_toe(best, side, pad, a, tau, increasing=False)
                    r = R_of(ht)
                    candidates.append((r, side, pad, a, tau, False, ht))
                if time.process_time() >= deadline - 0.5:
                    break
                if time.process_time() >= deadline - 0.5:
                    break
                ht = _make_toe(best, side, pad, a, 0.0, increasing=True)
                r = R_of(ht)
                candidates.append((r, side, pad, a, 'inc', True, ht))
            if time.process_time() >= deadline - 0.5:
                break
        if time.process_time() >= deadline - 0.5:
            break

    if not candidates:
        return best, bestR

    candidates.sort(key=lambda t: -t[0])
    print("toe pre-polish best: R=%.9f (side=%s pad=%d a=%.2f tau=%s) start=%.9f" %
          (candidates[0][0], candidates[0][1], candidates[0][2],
           candidates[0][3], candidates[0][4], bestR))

    bestArr = best.copy()
    bestR2 = bestR
    top = candidates[:4]
    for (r0, side, pad, a, tau, inc, ht) in top:
        if time.process_time() >= deadline - 0.5:
            break
        n = ht.size
        if side == 'left':
            free = np.arange(0, min(1200, n))
        else:
            free = np.arange(max(0, n - 1200), n)
        hp = _lbfgs_block(ht, free, 200, deadline - 0.5, beta=0.0)
        rp = R_of(hp)
        if time.process_time() < deadline - 0.5:
            win = _peak_window(hp, pad_frac=0.10, extra=128)
            hp2 = _lbfgs_block(hp, win, 200, deadline - 0.5, beta=1e7)
            rp2 = R_of(hp2)
            if rp2 > rp:
                hp, rp = hp2, rp2
        print("toe polish side=%s pad=%d a=%.2f tau=%s inc=%s: pre=%.9f post=%.9f" %
              (side, pad, a, tau, inc, r0, rp))
        if rp > bestR2 + 1e-15:
            bestArr, bestR2 = hp.copy(), rp
    return bestArr, bestR2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Experiment: cell-scale toe shaping ----
    try:
        tb_h, tb_R = _toe_phase(best, bestR, deadline - 20.0)
        if tb_R > bestR + 1e-13:
            best, bestR = tb_h, tb_R
            origin = 'toe'
            print("toe improved: R=%.9f" % bestR)
        else:
            print("toe did not improve (best=%.9f)" % tb_R)
    except Exception as e:
        print("toe phase failed: %s" % e)

    # ---- Base's proven machinery on the best array ----
    if time.process_time() < deadline - 4.0:
        ht, rt = run_cycle(best, bestR, deadline - 4.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+cycle'
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Tight peak-window block polish ----
    try:
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            print("tight polish beta=0: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+tight0'
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            print("tight polish beta=1e7: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+tight7'
    except Exception as e:
        print("tight polish failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


# ---------- New idea: direct ascent on individual heights via
# coordinate sweeps using exact 1-D quadratic optimum per cell ----------

def _cell_partial(h, i):
    """Contribution to num and to the relevant knots, as a function of h_i,
    is quadratic: num(h_i) = A h_i^2 + B h_i + C (since f*f is quadratic in h).
    Returns (A, B, C) for ||f*f||_2^2 and the linear pieces of the knots that
    depend on h_i. Uses exact local formula."""
    n = h.size
    # f*f knot values L[1..2n-1] = conv(h,h). L[k] = sum_j h_j h_{k-1-j}.
    # Terms linear in h_i affect L[k] for k-1-j = i => j = k-1-i, and
    # also j=i => k-1-i. So knots affected: L[i+1+j] for each j (two symmetric).
    # num = sum_k (L_k^2 + L_k L_{k+1} + L_{k+1}^2)/3 over L[0..2n+1] with L0=0, L_{2n+1}=0.
    # Simplest: build the affected knot indices and compute A,B,C by evaluating
    # num at h_i = 0, 1, 2.
    orig = h[i]
    vals = []
    for hv in (0.0, 1.0, 2.0):
        h[i] = hv
        L = _knots(h)
        a = L[:-1]; b = L[1:]
        vals.append(np.sum(a * a + a * b + b * b) / 3.0)
    h[i] = orig
    # fit quadratic
    C = vals[0]
    B = (4 * vals[1] - vals[2] - 3 * vals[0]) / 2.0
    A = (vals[2] - 2 * vals[1] + vals[0]) / 2.0
    return A, B, C


def _coord_sweep(h, deadline, order=None):
    """One pass: maximise num subject to fixed sum and fixed max knot (via
    scaling). We instead directly try to raise R by 1-D exact per-cell updates
    of num while keeping sum & max ~ fixed (renormalise after)."""
    h = h.copy()
    n = h.size
    if order is None:
        order = np.argsort(-h)  # biggest heights first
    improved = 0
    for idx in order:
        if time.process_time() > deadline:
            break
        A, B, C = _cell_partial(h, idx)
        if A <= 0:
            continue
        hi_star = -B / (2 * A)
        if hi_star < 0:
            hi_star = 0.0
        old = h[idx]
        # try a few candidate values, pick best R after full rescale
        best_v = old; best_r = -1.0
        for cand in (hi_star, 0.5 * (old + hi_star), old * 0.5, old * 1.5):
            if cand < 0:
                continue
            h[idx] = cand
            r = R_of(h)
            if r > best_r:
                best_r = r; best_v = cand
        h[idx] = best_v
        improved += 1
    return _rescale(h)


def run(best, bestR, deadline):
    # alternate all-pos L-BFGS with peak-window block polish
    ladder = [(0.05, 64), (0.10, 128), (0.25, 256),
              (0.40, 512), (0.60, 1024), (1.0, 2048)]
    while time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 400, deadline - 1.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
        progressed = False
        for frac, extra in ladder:
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(best, pad_frac=frac, extra=extra)
            ht = _lbfgs_block(best, win, 200, deadline - 1.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                progressed = True
        if not progressed:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: coordinate sweeps (new attempt for fine per-cell gains)
    try:
        cur = _seed_zeros(best)
        # a few sweeps ordered by height, with a short deadline
        for sweep in range(3):
            if time.process_time() >= deadline - 20.0:
                break
            cur = _coord_sweep(cur, deadline - 20.0)
            r = R_of(cur)
            if r > bestR + 1e-13:
                best, bestR = cur.copy(), r
                origin = origin + '+coord'
            print("coord sweep %d: R=%.9f" % (sweep, r))
    except Exception as e:
        print("coord sweep failed: %s" % e)

    # Phase 2: L-BFGS block/all-pos cycle
    if time.process_time() < deadline - 0.5:
        ht, rt = run(best, bestR, deadline - 0.5)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+cycle'
        print("cycle R=%.9f" % bestR)

    print("final R=%.9f origin=%s (N=%d)" % (bestR, origin, best.size))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tight=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    if tight:
        opts['ftol'] = 0.0
        opts['gtol'] = 0.0
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_interior_beta(h0, free, beta, maxiter, deadline):
    return _lbfgs_block(h0, free, maxiter, deadline, beta=beta)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _interior_beta_phase(best, bestR, deadline):
    h = np.clip(best, 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return best, bestR
    active = np.flatnonzero(h > 1e-6 * mx)
    if active.size < 4:
        return best, bestR
    i0 = int(active.min())
    i1 = int(active.max())
    L = i1 - i0 + 1
    lo = i0 + int(0.10 * L)
    hi = i0 + int(0.90 * L)
    if hi <= lo:
        return best, bestR
    free = np.arange(lo, hi + 1)
    betas = [1e4, 3e4, 1e5, 3e5, 1e6, 3e6, 1e7]
    cur = h
    curR = bestR
    bestArr = best.copy()
    bestR2 = bestR
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            print("interior-beta: out of time at beta=%.0e" % beta)
            break
        ht = _lbfgs_interior_beta(cur, free, beta, 80, deadline - 0.5)
        r = R_of(ht)
        b1 = _band_frac(ht, 0.01)
        print("interior-beta %.0e: R=%.9f band1=%.4f" % (beta, r, b1))
        if r > bestR2 + 1e-15:
            bestArr, bestR2 = ht.copy(), r
        if r > curR + 1e-15:
            cur, curR = ht, r
        else:
            cur, curR = ht, r
    print("interior-beta done: best R=%.9f (start %.9f)" % (bestR2, bestR))
    return bestArr, bestR2


# ---------------- Experiment: conservative resample ----------------

def _conservative_resample(h, M):
    """Resample h (N cells) to M cells, preserving total mass and shape."""
    h = np.asarray(h, dtype=float)
    N = h.size
    w = N / float(M)
    # cumulative mass at old cell boundaries
    cum = np.concatenate(([0.0], np.cumsum(h)))
    # new cell boundaries in old-cell units
    edges = np.arange(M + 1, dtype=float) * w
    # cumulative mass at new edges via linear interpolation of cum
    # cum is defined at integer positions 0..N
    cm = np.interp(edges, np.arange(N + 1, dtype=float), cum)
    new_h = np.diff(cm) / w
    return new_h


def _resample_splat(h, M):
    """Fallback: cumulative-mass splat resample."""
    h = np.asarray(h, dtype=float)
    N = h.size
    w = N / float(M)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(M + 1, dtype=float) * w
    cm = np.interp(edges, np.arange(N + 1, dtype=float), cum)
    new_h = np.diff(cm) / w
    return np.clip(new_h, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Experiment: conservative resample to non-commensurate M ----
    M = 131072
    try:
        N0 = start_best.size
        ht = _conservative_resample(start_best, M)
        ht = _rescale(ht)
        r = R_of(ht)
        print("resample M=%d: R=%.9f (start %.9f, drop %.2e)" %
              (M, r, start_bestR, start_bestR - r))
        if start_bestR - r > 1e-4:
            print("resample drop too large, using splat fallback")
            ht = _rescale(_resample_splat(start_best, M))
            r = R_of(ht)
            print("splat fallback: R=%.9f" % r)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            origin = 'resample'
        # keep resample as candidate even if not better
        resample_arr = ht.copy()
        resample_R = r
    except Exception as e:
        print("resample failed: %s" % e)
        resample_arr, resample_R = None, 0.0

    # ---- Base's proven machinery on the best array ----
    if time.process_time() < deadline - 8.0:
        ht, rt = run_cycle(best, bestR, deadline - 8.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+cycle'
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Tight peak-window polish ----
    try:
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            print("tight polish beta=0: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+tight0'
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            print("tight polish beta=1e7: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+tight7'
    except Exception as e:
        print("tight polish failed: %s" % e)

    # ---- Outer-window passes on outermost 2000 cells of each end ----
    try:
        n = best.size
        k = min(2000, n // 4)
        if k > 0:
            outer = np.concatenate((np.arange(0, k), np.arange(n - k, n)))
            for beta in (0.0, 1e7):
                if time.process_time() >= deadline - 0.5:
                    break
                ht = _lbfgs_block(best, outer, 200, deadline - 0.5, beta=beta)
                r = R_of(ht)
                print("outer pass beta=%.0e: R=%.9f" % (beta, r))
                if r > bestR + 1e-13:
                    best, bestR = ht, r
                    origin = origin + '+outer%.0e' % beta
    except Exception as e:
        print("outer pass failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _refine(h, deadline, iters=120):
    """Resample by linear interpolation onto a finer grid, then L-BFGS."""
    n = h.size
    # upsample x2 by linear interpolation of step values (mass approx)
    xs_old = np.arange(n + 1, dtype=float)
    xs_new = np.linspace(0.0, n, 2 * n + 1)
    hf = np.interp(xs_new[:-1] + 0.5, xs_old[:-1] + 0.5, h, left=0.0, right=0.0)
    hf = _rescale(np.clip(hf, 0, None))
    cap = min(deadline - 1.0, time.process_time() + 6.0)
    hf = _lbfgs_log(hf, iters, cap, beta=0.0)
    return hf


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    print("base R=%.9f (N=%d)" % (baseR, baseH.size))

    bestH = baseH.copy()
    bestR = baseR
    experiment_best = baseH.copy()
    experiment_bestR = baseR

    # Phase 1: global L-BFGS on the start (careful, no resample yet)
    loop_end = deadline - 4.0
    local = bestH.copy()
    for beta in (0.0, 1e3, 1e4, 0.0):
        if time.process_time() >= loop_end:
            break
        cap = min(loop_end, time.process_time() + 6.0)
        hs = _lbfgs_log(local, 200, cap, beta=beta)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs
            local = hs.copy()
            print("  global beta=%.0e -> R=%.9f" % (beta, rs))
        else:
            local = hs.copy()

    # Phase 2: progressive refinement (upsample x2 + L-BFGS) — a genuinely
