    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _upsample_lin(h, factor):
    n = h.size
    m = n * factor
    x = np.linspace(0, n - 1, m)
    return np.interp(x, np.arange(n), h)


def _upsample_smooth(h, factor):
    """Upsample with a smooth (cosine) interpolation preserving total mass."""
    n = h.size
    m = n * factor
    x = np.linspace(0, n - 1, m)
    xi = np.arange(n)
    hs = np.interp(x, xi, h)
    # light smoothing to reduce grid artifacts
    if m > 8:
        k = np.array([0.25, 0.5, 0.25])
        hs = np.convolve(np.concatenate(([hs[0]], hs, [hs[-1]])), k, mode='valid')
    return hs * (h.sum() / max(hs.sum(), 1e-300))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None and np.asarray(start).size > 0 and np.sum(start) > 0:
        base = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = R_of(base)
        best = base.copy()
    else:
        N = 4096
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)
    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f N=%d" % (bestR, best.size))

    def try_fine(name, cand):
        nonlocal best, bestR
        if cand is None:
            return False
        r = R_of(cand)
        if r > bestR + 1e-13:
            best, bestR = cand.copy(), r
            print("  %s NEW R=%.9f" % (name, bestR))
            return True
        return False

    loop_end = deadline - 0.8
    it = 0

    # Phase 0: smoothed-max global passes.
    for beta in (200.0, 500.0, 1000.0):
        if time.process_time() >= loop_end - 2.0:
            break
        cap = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(best, 200, cap, fg=(lambda hh, b=beta: _fun_grad_beta(hh, b)))
        try_fine("beta=%g" % beta, hs)

    # Phase 1: alternating full + peak-window polish with upsample.
    stall = 0
    while time.process_time() < loop_end:
        it += 1
        improved = False
        cap = min(loop_end, time.process_time() + 5.0)
        hs = _lbfgs_log(best, 400, cap)
        if try_fine("full it=%d" % it, hs):
            improved = True
        else:
            stall += 1

        if time.process_time() < loop_end - 1.0:
            free = _peak_window(best, frac=0.04)
            cap = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(best, free, 150, cap)
            if try_fine("peak it=%d" % it, hp):
                improved = True
                stall = 0

        if time.process_time() < loop_end - 1.0 and stall >= 2:
            for fac in (2, 3):
                if time.process_time() >= loop_end - 1.0:
                    break
                A = _rescale(_upsample_smooth(best, fac))
                cap = min(loop_end, time.process_time() + 3.0)
                free = _peak_window(A, frac=0.08)
                hc = _lbfgs_block(A, free, 200, cap)
                if try_fine("up%d it=%d" % (fac, it), hc):
                    improved = True
                    stall = 0
                    break

    if bestR < start_bestR:
        best, bestR = start_best, start_bestR

    print("final R=%.9f N=%d" % (bestR, best.size))
    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

