    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tight=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    if tight:
        opts['ftol'] = 0.0
        opts['gtol'] = 0.0
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------------- Experiment: FISTA + Barzilai-Borwein ----------------

def _fista_beta(h0, deadline, beta=1e7, max_iter=4000,
                consolidate_every=300, beta_schedule=None):
    """Projected Nesterov accelerated gradient with BB step sizes
    on the smooth beta-softmax surrogate. Periodically consolidates with
    L-BFGS and tracks the best exact-R array."""
    h = np.clip(np.asarray(h0, dtype=float), 0, None)
    if h.sum() <= 0:
        return h0, R_of(h0)
    best = h.copy()
    bestR = R_of(best)

    x = _rescale(h)
    x_prev = x.copy()
    t = 1.0
    eta = None
    s_prev = None
    yg_prev = None

    if beta_schedule is None:
        beta_schedule = [(800, 1e5), (1600, 1e6)]

    def cur_beta(it):
        for thresh, b in beta_schedule:
            if it < thresh:
                return b
        return beta

    it = 0
    while it < max_iter:
        if time.process_time() >= deadline - 0.5:
            break
        b = cur_beta(it)
        t_next = 0.5 * (1.0 + np.sqrt(1.0 + 4.0 * t * t))
        mom = (t - 1.0) / t_next
        y = x + mom * (x - x_prev)
        y = np.clip(y, 0.0, None)

        val, g = _fun_grad_beta(y, b)

        # Barzilai-Borwein step
        if s_prev is not None and yg_prev is not None:
            sy = float(np.dot(s_prev, yg_prev))
            if sy > 1e-30:
                eta = float(np.dot(s_prev, s_prev)) / sy
            else:
                eta = None
        if eta is None or not np.isfinite(eta) or eta <= 0:
            gmax = float(np.max(np.abs(g))) if g.size else 1.0
            eta = 1e-2 / max(gmax, 1e-12)

        # backtracking
        step_ok = False
        for _ in range(12):
            x_new = np.clip(y - eta * g, 0.0, None)
            if x_new.sum() <= 0:
                eta *= 0.5
                continue
            val_new, _ = _fun_grad_beta(x_new, b)
            if val_new <= val + 1e-15:
                step_ok = True
                break
            eta *= 0.5
        if not step_ok:
            x_new = np.clip(y - eta * g, 0.0, None)
            if x_new.sum() <= 0:
                x_new = x.copy()

        s_prev = x_new - x
        _, g_new = _fun_grad_beta(x_new, b)
        yg_prev = g_new - g

        x_prev = x
        x = x_new
        t = t_next
        it += 1

        if it % consolidate_every == 0:
            if time.process_time() >= deadline - 0.5:
                break
            hc = _rescale(np.clip(x, 0.0, None))
            hc = _lbfgs_all_pos(hc, 200, deadline - 0.5, beta=b)
            r = R_of(hc)
            print("fista it=%d beta=%.0e: R=%.9f" % (it, b, r))
            if r > bestR + 1e-15:
                best, bestR = hc.copy(), r
            # also try exact polish occasionally
            if it % (consolidate_every * 3) == 0:
                hc2 = _lbfgs_all_pos(hc, 150, deadline - 0.5, beta=0.0)
                r2 = R_of(hc2)
                if r2 > bestR + 1e-15:
                    best, bestR = hc2.copy(), r2
                print("fista exact-polish it=%d: R=%.9f" % (it, r2))

    # final consolidation
    if time.process_time() < deadline - 0.5:
        hc = _rescale(np.clip(x, 0.0, None))
        hc = _lbfgs_all_pos(hc, 300, deadline - 0.5, beta=beta)
        r = R_of(hc)
        print("fista final beta=%.0e: R=%.9f" % (beta, r))
        if r > bestR + 1e-15:
            best, bestR = hc.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Base's proven machinery first (short) ----
    if time.process_time() < deadline - 30.0:
        ht, rt = run_cycle(best, bestR, deadline - 30.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+cycle'
        print("base cycle R=%.7f" % bestR)

    # ---- FISTA blocks alternating with L-BFGS polish ----
    fista_best = best.copy()
    fista_bestR = bestR
    block = 0
    while time.process_time() < deadline - 3.0:
        block += 1
        if time.process_time() >= deadline - 3.0:
            break
        ht, rt = _fista_beta(fista_best, deadline - 2.0, beta=1e7,
                             max_iter=1500, consolidate_every=300)
        print("fista block %d: R=%.9f" % (block, rt))
        if rt > fista_bestR + 1e-15:
            fista_best, fista_bestR = ht.copy(), rt
        # L-BFGS polish
        if time.process_time() < deadline - 2.0:
            hp = _lbfgs_all_pos(fista_best, 200, deadline - 2.0, beta=0.0)
            rp = R_of(hp)
            print("polish block %d exact: R=%.9f" % (block, rp))
            if rp > fista_bestR + 1e-15:
                fista_best, fista_bestR = hp.copy(), rp
            hp2 = _lbfgs_all_pos(fista_best, 200, deadline - 2.0, beta=1e7)
            rp2 = R_of(hp2)
            if rp2 > fista_bestR + 1e-15:
                fista_best, fista_bestR = hp2.copy(), rp2

    if fista_bestR > bestR + 1e-13:
        best, bestR = fista_best, fista_bestR
        origin = origin + '+fista'

    # ---- Final peak-window polish ----
    try:
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            print("final peak polish beta=1e7: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+peak'
    except Exception as e:
        print("final peak polish failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if beta > 0:
        mx = Lf.max()
        if mx <= 0:
            return 1e18, np.zeros(h.size)
        e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
        Z = e.sum()
        w = e / Z
        sm = mx + np.log(Z) / beta
        gLf = -dq / num + w / sm
        val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    else:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta))

    def f(x):
        return fg(np.clip(x, 0.0, None))

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta))

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None and np.asarray(start).size > 0 and np.asarray(start).sum() > 0:
        base = _rescale(np.clip(np.asarray(start, dtype=float).copy(), 0, None))
        start_best, start_bestR = base.copy(), R_of(base)
    else:
        N = 8192
        i = np.arange(N, dtype=float)
        h = np.sqrt(i + 1.0) - np.sqrt(i)
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Multi-stage polish: alternate global and peak-window block optimisations
    # with varying beta and pad_frac.  Each stage only accepts improvements.
    stages = [
        ('glob0', 'all', 0.0, 0.0, 400),
        ('glob7', 'all', 1e7, 0.0, 300),
        ('win05', 'win', 1e8, 0.05, 250),
        ('glob0b', 'all', 0.0, 0.0, 400),
        ('win10', 'win', 1e8, 0.10, 250),
        ('win25', 'win', 1e8, 0.25, 200),
        ('glob0c', 'all', 0.0, 0.0, 300),
        ('win05b', 'win', 1e7, 0.05, 200),
        ('win10b', 'win', 0.0, 0.10, 200),
        ('glob7b', 'all', 1e7, 0.0, 200),
        ('glob0d', 'all', 0.0, 0.0, 300),
        ('win02', 'win', 1e8, 0.02, 200),
        ('win15', 'win', 1e8, 0.15, 250),
        ('glob0e', 'all', 0.0, 0.0, 400),
    ]

    for name, kind, beta, pad, iters in stages:
        if time.process_time() >= deadline - 0.6:
            break
        if kind == 'all':
            ht = _lbfgs_all(best, iters, deadline - 0.5, beta=beta)
        else:
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht = _lbfgs_block(best, win, iters, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            gain = r - bestR
            best, bestR = ht, r
            print("%s: R=%.9f (+%.2e)" % (name, bestR, gain))
        else:
            print("%s: no gain (%.9f)" % (name, r))

    # Final fine-grained interior polish: seed any zeros with tiny values and
    # do full L-BFGS to allow small structural shifts.
    if time.process_time() < deadline - 1.0:
        hs = _seed_zeros(best)
        ht = _lbfgs_all(hs, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
            print("fine polish: R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, start_bestR, best.size))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
