def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tight=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    if tight:
        opts['ftol'] = 0.0
        opts['gtol'] = 0.0
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_interior_beta(h0, free, beta, maxiter, deadline):
    return _lbfgs_block(h0, free, maxiter, deadline, beta=beta)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _interior_beta_phase(best, bestR, deadline):
    h = np.clip(best, 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return best, bestR
    active = np.flatnonzero(h > 1e-6 * mx)
    if active.size < 4:
        return best, bestR
    i0 = int(active.min())
    i1 = int(active.max())
    L = i1 - i0 + 1
    lo = i0 + int(0.10 * L)
    hi = i0 + int(0.90 * L)
    if hi <= lo:
        return best, bestR
    free = np.arange(lo, hi + 1)
    betas = [1e4, 3e4, 1e5, 3e5, 1e6, 3e6, 1e7]
    cur = h
    curR = bestR
    bestArr = best.copy()
    bestR2 = bestR
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            print("interior-beta: out of time at beta=%.0e" % beta)
            break
        ht = _lbfgs_interior_beta(cur, free, beta, 80, deadline - 0.5)
        r = R_of(ht)
        b1 = _band_frac(ht, 0.01)
        print("interior-beta %.0e: R=%.9f band1=%.4f" % (beta, r, b1))
        if r > bestR2 + 1e-15:
            bestArr, bestR2 = ht.copy(), r
        if r > curR + 1e-15:
            cur, curR = ht, r
        else:
            cur, curR = ht, r
    print("interior-beta done: best R=%.9f (start %.9f)" % (bestR2, bestR))
    return bestArr, bestR2


# ---------------- Experiment: random mass-preserving split ----------------

def _random_split(h, seed, amp):
    h = np.asarray(h, dtype=float)
    N = h.size
    rng = np.random.default_rng(seed)
    d = rng.uniform(-amp, amp, size=N)
    out = np.empty(2 * N, dtype=float)
    out[0::2] = h * (1.0 + d)
    out[1::2] = h * (1.0 - d)
    return np.clip(out, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Experiment: random mass-preserving split screening ----
    split_candidates = []
    amps = [0.15, 0.35, 0.6]
    seeds = [0, 1, 2]
    screen_deadline = min(deadline - 8.0, t0 + budget_seconds * 0.45)
    for amp in amps:
        for seed in seeds:
            if time.process_time() >= screen_deadline:
                print("screen: out of time at amp=%.2f seed=%d" % (amp, seed))
                break
            try:
                hs = _random_split(start_best, seed, amp)
                hs = _rescale(hs)
                r0 = R_of(hs)
            except Exception as e:
                print("split amp=%.2f seed=%d failed: %s" % (amp, seed, e))
                continue
            # short polish
            try:
                hp, rp = run_cycle(hs, r0, min(screen_deadline, time.process_time() + 6.0))
            except Exception:
                hp, rp = hs, r0
            split_candidates.append((rp, hp, amp, seed, r0))
            print("split amp=%.2f seed=%d: pre=%.9f post=%.9f (start %.9f)" %
                  (amp, seed, r0, rp, start_bestR))
            if rp > bestR + 1e-13:
                best, bestR = hp.copy(), rp
                origin = 'split(%.2f,%d)' % (amp, seed)

    if split_candidates:
        split_candidates.sort(key=lambda x: -x[0])
        topR, topH, topAmp, topSeed, topPre = split_candidates[0]
        print("best split: amp=%.2f seed=%d post=%.9f" % (topAmp, topSeed, topR))
        # make sure the split array itself is a candidate even if not better
        if topR > bestR + 1e-13:
            best, bestR = topH.copy(), topR
            origin = 'split(%.2f,%d)' % (topAmp, topSeed)

    # ---- Base's proven machinery on the best array ----
    if time.process_time() < deadline - 8.0:
        ht, rt = run_cycle(best, bestR, deadline - 8.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+cycle'
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Alternating polishes on best ----
    try:
        for _ in range(100):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+all0'
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+all7'
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+pk0'
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+pk7'
    except Exception as e:
        print("polish loop failed: %s" % e)

    # ---- Outer-window passes ----
    try:
        n = best.size
        k = min(2000, n // 4)
        if k > 0:
            outer = np.concatenate((np.arange(0, k), np.arange(n - k, n)))
            for beta in (0.0, 1e7):
                if time.process_time() >= deadline - 0.5:
                    break
                ht = _lbfgs_block(best, outer, 200, deadline - 0.5, beta=beta)
                r = R_of(ht)
                print("outer pass beta=%.0e: R=%.9f" % (beta, r))
                if r > bestR + 1e-13:
                    best, bestR = ht, r
                    origin = origin + '+outer%.0e' % beta
    except Exception as e:
        print("outer pass failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tight=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    if tight:
