    betas = [1e4, 3e4, 1e5, 3e5, 1e6, 3e6, 1e7]
    cur = h
    curR = bestR
    bestArr = best.copy()
    bestR2 = bestR
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            print("interior-beta: out of time at beta=%.0e" % beta)
            break
        ht = _lbfgs_interior_beta(cur, free, beta, 80, deadline - 0.5)
        r = R_of(ht)
        b1 = _band_frac(ht, 0.01)
        print("interior-beta %.0e: R=%.9f band1=%.4f" % (beta, r, b1))
        if r > bestR2 + 1e-15:
            bestArr, bestR2 = ht.copy(), r
        if r > curR + 1e-15:
            cur, curR = ht, r
        else:
            cur, curR = ht, r
    print("interior-beta done: best R=%.9f (start %.9f)" % (bestR2, bestR))
    return bestArr, bestR2


# ---------------- Experiment: dedup / half-resolution cycles ----------------

def _dedup(h, k):
    h = np.asarray(h, dtype=float)
    N = h.size
    M = N // k
    if M < 1:
        return h.copy()
    hh = h[:M * k].reshape(M, k)
    return hh.mean(axis=1)


def _expand(v, k):
    return np.repeat(np.asarray(v, dtype=float), k)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    def consider(arr, tag):
        nonlocal best, bestR, origin
        arr = _rescale(np.clip(arr, 0, None))
        r = R_of(arr)
        if r > bestR + 1e-13:
            best, bestR = arr.copy(), r
            origin = origin + '+' + tag
        return r

    # ---- Experiment: dedup k=2, half-length cycle ----
    def try_dedup_round(h_full, hR, k, time_frac):
        N = h_full.size
        if N % k != 0:
            print("dedup k=%d: N=%d not divisible, skipping" % (k, N))
            return h_full, hR
        v = _dedup(h_full, k)
        v = _rescale(v)
        rv = R_of(v)
        # verify equality via expansion
        exp0 = _rescale(_expand(v, k))
        rexp = R_of(exp0)
        print("dedup k=%d: R(v)=%.9f R(expand)=%.9f R(full)=%.9f diff=%.2e" %
              (k, rv, rexp, hR, abs(rexp - hR)))
        if abs(rexp - hR) > 1e-6:
            print("dedup k=%d: mismatch, falling back" % k)
            return h_full, hR
        # spend time_frac of remaining budget on half-length cycle
        now = time.process_time()
        rem = deadline - now
        sub_deadline = now + max(0.0, rem * time_frac)
        vbest, vR = v.copy(), rv
        try:
            vbest, vR = run_cycle(v, vR, sub_deadline)
        except Exception as e:
            print("dedup k=%d cycle failed: %s" % (k, e))
        print("dedup k=%d half-cycle: R=%.9f (was %.9f)" % (k, vR, rv))
        # expand back
        exp = _rescale(_expand(vbest, k))
        rexp = R_of(exp)
        print("dedup k=%d expand: R=%.9f" % (k, rexp))
        # consider both half-length (as-is, but must be full length for scoring)
        # Only expansions are valid full-length candidates; but half-length
        # array is not a valid submission. So consider expansion.
        consider(exp, 'dedup%d' % k)
        return best, bestR

    try:
        best, bestR = try_dedup_round(best, bestR, 2, 0.75)
    except Exception as e:
        print("dedup k=2 failed: %s" % e)

    # ---- Full-length polish on current best ----
    try:
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            print("full lbfgs beta=0: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+full0'
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            print("tight polish beta=1e7: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+tight7'
    except Exception as e:
        print("full polish failed: %s" % e)

    # ---- If time remains, dedup k=4 round ----
    try:
        if time.process_time() < deadline - 5.0:
            best, bestR = try_dedup_round(best, bestR, 4, 0.7)
            if time.process_time() < deadline - 0.5:
                ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
                r = R_of(ht)
                print("post-k4 full lbfgs: R=%.9f" % r)
                if r > bestR + 1e-13:
                    best, bestR = ht, r
                    origin = origin + '+post4'
    except Exception as e:
        print("dedup k=4 failed: %s" % e)

    # ---- Final tight polish ----
    try:
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            print("final tight beta=0: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+ft0'
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            print("final tight beta=1e7: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+ft7'
    except Exception as e:
        print("final tight failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    pad = max(extra, int((hi - lo) * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _resample(h, factor):
    n = h.size
    if factor <= 1:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, n, endpoint=False)
    new_n = n * factor
    x_new = np.linspace(0.0, 1.0, new_n, endpoint=False)
    return np.interp(x_new, x_old, h, right=h[-1])


def _smooth(h, k):
    """Light box smoothing to break grid-alignment artifacts."""
    if k <= 1:
        return h
    ker = np.ones(k) / k
    return np.convolve(h, ker, mode='same')


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    n = best.size

    # NEW STRATEGY: The optimizer is stuck at R~0.94128. Try a genuinely
    # different move: perturb the shape via a small random multiplicative
    # noise on the peak region, and co-optimize the *peak-region + tail*
    # separately with alternating block L-BFGS, which can escape the flat
    # local optimum that global L-BFGS sits in.

    rng = np.random.RandomState(12345)

    def try_improve(h, R, dl, tag):
        # Multi-scale alternating block optimization.
        if time.process_time() >= dl - 0.5:
            return h, R, tag
        # 1) global then peak window blocks alternating.
        for it in range(3):
            if time.process_time() >= dl - 0.5:
                break
            win = _peak_window(h, tol=0.9999, pad_frac=0.15, extra=64)
            ht = _lbfgs_block(h, win, maxiter=250, deadline=dl - 0.5, beta=0.0)
            r = R_of(ht)
            if r > R + 1e-13:
                h, R = ht, r
            # Complementary: non-peak region
            if time.process_time() >= dl - 0.5:
                break
            mask = np.ones(h.size, dtype=bool)
            mask[win] = False
            comp = np.flatnonzero(mask)
            if comp.size > 0 and comp.size < 200000:
                ht = _lbfgs_block(h, comp, maxiter=200,
                                  deadline=dl - 0.5, beta=0.0)
                r = R_of(ht)
                if r > R + 1e-13:
                    h, R = ht, r
        return h, R, tag + '+alt'

    # Phase A: alternating block on the original grid.
    if time.process_time() < deadline - 6.0:
        h2, r2, o2 = try_improve(best, bestR, deadline - 6.0, origin)
        if r2 > bestR + 1e-13:
            best, bestR, origin = h2, r2, o2
        print("alt block R=%.9f" % bestR)

    # Phase B: resample x2 then alt-block, keep best.
    if time.process_time() < deadline - 4.0 and best.size * 2 <= 900000:
        try:
            hf = _resample(best, 2)
            hf = _rescale(_seed_zeros(hf))
            rf = R_of(hf)
            hf, rf, of = try_improve(hf, rf, deadline - 4.0, 'resample2')
            print("resample x2 alt R=%.9f (N=%d)" % (rf, hf.size))
            if rf > bestR + 1e-13:
                best, bestR, origin = hf, rf, origin + '+res2'
        except Exception as e:
            print("resample failed: %s" % e)

    # Phase C: random multiplicative perturbation basin-hop.
    # Small multiplicative noise on a fixed seed; if it improves, keep.
    hop_iters = 0
    while time.process_time() < deadline - 2.0 and hop_iters < 30:
        hop_iters += 1
        amp = 0.005 + 0.02 * rng.rand()
        noise = 1.0 + amp * (rng.randn(best.size))
        hc = _rescale(np.clip(best * noise, 0, None))
        rc = R_of(hc)
        # quick local polish on peak window only
        win = _peak_window(hc, tol=0.9999, pad_frac=0.10, extra=64)
        hc = _lbfgs_block(hc, win, maxiter=120,
                          deadline=deadline - 2.0, beta=0.0)
        rc = R_of(hc)
        if rc > bestR + 1e-13:
            best, bestR, origin = hc, rc, origin + '+hop%d' % hop_iters
    print("basin hop done: R=%.9f (hops=%d)" % (bestR, hop_iters))

    # Phase D: final tight polish on the peak window with beta=0 and beta=1e7.
    for beta in (0.0, 1e7):
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR, origin = ht, r, origin + ('+t%d' % int(beta))

    print("final R=%.7f origin=%s (N=%d)" % (bestR, origin, best.size))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

