    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _interior_beta_phase(best, bestR, deadline):
    h = np.clip(best, 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return best, bestR
    active = np.flatnonzero(h > 1e-6 * mx)
    if active.size < 4:
        return best, bestR
    i0 = int(active.min())
    i1 = int(active.max())
    L = i1 - i0 + 1
    lo = i0 + int(0.10 * L)
    hi = i0 + int(0.90 * L)
    if hi <= lo:
        return best, bestR
    free = np.arange(lo, hi + 1)
    betas = [1e4, 3e4, 1e5, 3e5, 1e6, 3e6, 1e7]
    cur = h
    curR = bestR
    bestArr = best.copy()
    bestR2 = bestR
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            print("interior-beta: out of time at beta=%.0e" % beta)
            break
        ht = _lbfgs_interior_beta(cur, free, beta, 80, deadline - 0.5)
        r = R_of(ht)
        b1 = _band_frac(ht, 0.01)
        print("interior-beta %.0e: R=%.9f band1=%.4f" % (beta, r, b1))
        if r > bestR2 + 1e-15:
            bestArr, bestR2 = ht.copy(), r
        if r > curR + 1e-15:
            cur, curR = ht, r
        else:
            cur, curR = ht, r
    print("interior-beta done: best R=%.9f (start %.9f)" % (bestR2, bestR))
    return bestArr, bestR2


# ---------------- Experiment: truncated-Newton with CG ----------------

def _hv(h, v, beta):
    """Hessian-vector product of the beta-smoothed objective at h, direction v."""
    eps = 1e-6 * max(1.0, np.abs(h).max())
    hp = h + eps * v
    hm = h - eps * v
    _, gp = _fun_grad_beta(hp, beta)
    _, gm = _fun_grad_beta(hm, beta)
    return (gp - gm) / (2.0 * eps)


def _newton_beta(h0, beta, deadline, max_cg=60, max_steps=8, verbose=True):
    h = _rescale(np.clip(h0, 0, None))
    if h.sum() <= 0:
        return h0
    best = h.copy()
    bestR = R_of(h)
    val, g = _fun_grad_beta(h, beta)
    prev_vals = [val]
    for step in range(max_steps):
        if time.process_time() >= deadline - 0.5:
            break
        val, g = _fun_grad_beta(h, beta)
        gnorm = np.linalg.norm(g)
        if verbose:
            print("newton beta=%.0e step=%d val=%.9f ||g||=%.3e" %
                  (beta, step, val, gnorm))
        if gnorm / max(1.0, abs(val)) < 1e-10:
            if verbose:
                print("newton: stationary point reached")
            break
        # CG on H p = -g
        p = np.zeros_like(h)
        r = -g.copy()
        d = r.copy()
        rr = float(r @ r)
        neg_curv = 0
        for it in range(max_cg):
            if time.process_time() >= deadline - 0.5:
                break
            Hd = _hv(h, d, beta)
            dHd = float(d @ Hd)
            if dHd <= -1e-8 * float(d @ d):
                neg_curv += 1
                if it == 0:
                    # use negative curvature direction directly
                    p = d.copy()
                    break
                else:
                    break
            if dHd <= 1e-30:
                break
            alpha = rr / dHd
            p += alpha * d
            r -= alpha * Hd
            rr_new = float(r @ r)
            if np.sqrt(rr_new) < 1e-9 * gnorm:
                rr = rr_new
                break
            beta_cg = rr_new / rr
            d = r + beta_cg * d
            rr = rr_new
        if verbose:
            print("  cg: iters=%d neg_curv=%d ||p||=%.3e" %
                  (it + 1, neg_curv, np.linalg.norm(p)))
        # clip step length
        pmax = np.abs(p).max()
        hmax = h.max()
        if pmax > 0 and pmax > 0.5 * hmax:
            p = p * (0.5 * hmax / pmax)
        # ensure non-negativity
        with np.errstate(divide='ignore', invalid='ignore'):
            neg = p < 0
            if np.any(neg):
                ratio = np.where(neg, -h / np.where(neg, p, -1.0), np.inf)
                max_t = float(np.min(ratio))
                if max_t < 1.0:
                    p = p * (0.95 * max_t)
        # backtracking line search (Armijo)
        c1 = 1e-4
        gp = float(g @ p)
        t = 1.0
        best_t = None
        best_val = val
        accepted = False
        for ls in range(12):
            ht = np.clip(h + t * p, 0.0, None)
            vt, _ = _fun_grad_beta(ht, beta)
            if vt < best_val:
                best_val = vt
                best_t = t
            if vt <= val + c1 * t * gp:
                best_t = t
                accepted = True
                break
            t *= 0.5
        if not accepted:
            # try fixed candidates
            for tc in (1.0, 0.5, 0.25, 0.1, 0.03):
                ht = np.clip(h + tc * p, 0.0, None)
                vt, _ = _fun_grad_beta(ht, beta)
                if vt < best_val:
                    best_val = vt
                    best_t = tc
        if best_t is None:
            if verbose:
                print("  line search failed, stopping")
            break
        h = np.clip(h + best_t * p, 0.0, None)
        h = _rescale(h)
        r_new = R_of(h)
        if r_new > bestR:
            best = h.copy()
            bestR = r_new
        prev_vals.append(best_val)
        if len(prev_vals) >= 4 and prev_vals[-1] > prev_vals[-2] > prev_vals[-3] > prev_vals[-4]:
            if verbose:
                print("  val increasing 3 steps, abort")
            break
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Experiment: truncated-Newton with CG on beta-smoothed objective ----
    newton_best = best.copy()
    newton_bestR = bestR
    try:
        cur = best.copy()
        for beta in (1e6, 1e8, 1e10):
            if time.process_time() >= deadline - 8.0:
                break
            ht = _newton_beta(cur, beta, deadline - 8.0,
                              max_cg=60, max_steps=6)
            r = R_of(ht)
            print("newton level beta=%.0e: R=%.9f" % (beta, r))
            if r > newton_bestR + 1e-13:
                newton_best, newton_bestR = ht.copy(), r
            cur = ht
            # polish after each level
            if time.process_time() < deadline - 8.0:
                hp = _lbfgs_all_pos(cur, 200, deadline - 8.0, beta=1e7)
                rp = R_of(hp)
                if rp > newton_bestR + 1e-13:
                    newton_best, newton_bestR = hp.copy(), rp
                cur = hp
            if time.process_time() < deadline - 8.0:
                win = _peak_window(cur, pad_frac=0.10, extra=128)
                hw = _lbfgs_block(cur, win, 200, deadline - 8.0, beta=0.0)
                rw = R_of(hw)
                if rw > newton_bestR + 1e-13:
                    newton_best, newton_bestR = hw.copy(), rw
                cur = hw
        print("newton done: best R=%.9f (start %.9f)" %
              (newton_bestR, start_bestR))
        if newton_bestR > bestR + 1e-13:
            best, bestR = newton_best.copy(), newton_bestR
            origin = 'start+newton'
    except Exception as e:
        print("newton failed: %s" % e)

    # ---- Base's proven machinery ----
    if time.process_time() < deadline - 0.5:
        ht, rt = run_cycle(best, bestR, deadline - 0.5)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+cycle'
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Tight peak-window polish ----
    try:
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            print("tight polish beta=0: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+tight0'
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            print("tight polish beta=1e7: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+tight7'
    except Exception as e:
        print("tight polish failed: %s" % e)

    # ---- Outer-window passes ----
    try:
        n = best.size
        k = min(2000, n // 4)
        if k > 0:
            outer = np.concatenate((np.arange(0, k), np.arange(n - k, n)))
            for beta in (0.0, 1e7):
                if time.process_time() >= deadline - 0.5:
                    break
                ht = _lbfgs_block(best, outer, 200, deadline - 0.5, beta=beta)
                r = R_of(ht)
                print("outer pass beta=%.0e: R=%.9f" % (beta, r))
                if r > bestR + 1e-13:
                    best, bestR = ht, r
                    origin = origin + '+outer%.0e' % beta
    except Exception as e:
        print("outer pass failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if newton_bestR > start_bestR + 1e-13 and newton_bestR < bestR - 1e-13:
        return {"best": best, "alternative": newton_best}
    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": newton_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _dq_of(Lf):
    a = Lf[:-1]; b = Lf[1:]
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return dq


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _hv(v, h, beta):
    """Exact Hessian-vector product of _fun_grad_beta at h along v."""
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    e = np.exp(np.clip(beta * (Lf - Lf[m]), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return np.zeros_like(h)
    w = e / Z
    sm = Lf[m] + np.log(Z) / beta
    # dLf = derivative of knots wrt h along v
    dLf = np.concatenate(([0.0], 2.0 * _conv(v), [0.0]))
    dnum = dq @ dLf
    dq2 = _dq_of(dLf)
    de = beta * e * (dLf - dLf[m])
    dZ = de.sum()
    dw = de / Z - e * dZ / (Z * Z)
    dsm = dLf[m] + (dZ / Z) / beta
    # gLf = -dq/num + w/sm
    dgLf = -(dq2 / num - dq * dnum / (num * num)) + (dw / sm - w * dsm / (sm * sm))
    gLf = -dq / num + w / sm
    Hv = _backprop(dgLf, h) + _backprop(gLf, v) - 2.0 * v.sum() / (s * s)
    return Hv


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tight=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    if tight:
        opts['ftol'] = 0.0
        opts['gtol'] = 0.0
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_interior_beta(h0, free, beta, maxiter, deadline):
    return _lbfgs_block(h0, free, maxiter, deadline, beta=beta)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _lanczos(h, beta, k, deadline):
    """Full-reorthogonalised Lanczos on _hv. Returns (eigvals, eigvecs)."""
    n = h.size
    Q = np.zeros((k + 1, n))
    alpha = np.zeros(k)
    betav = np.zeros(k)
    q = np.random.RandomState(0).randn(n)
    q /= np.linalg.norm(q)
    Q[0] = q
    for j in range(k):
        if time.process_time() > deadline:
            k = j
            break
        w = _hv(Q[j], h, beta)
        # full reorthogonalisation
        for _ in range(2):
            for i in range(j + 1):
                c = Q[i] @ w
                w -= c * Q[i]
        a = w @ Q[j]
        alpha[j] = a
        w -= a * Q[j]
        for _ in range(2):
            for i in range(j + 1):
                c = Q[i] @ w
                w -= c * Q[i]
        b = np.linalg.norm(w)
        betav[j] = b
        if b < 1e-12:
            k = j + 1
            break
        Q[j + 1] = w / b
    kk = min(k, len(alpha))
    T = np.diag(alpha[:kk])
    if kk > 1:
        T += np.diag(betav[:kk - 1], 1) + np.diag(betav[:kk - 1], -1)
    evals, evecs = np.linalg.eigh(T)
    # Ritz vectors
    V = Q[:kk].T @ evecs  # n x kk
    return evals, V


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    beta = 1e7
    h = best.copy()

    # ---- Verify _hv against finite differences ----
    try:
        rng = np.random.RandomState(1)
        v = np.zeros_like(h)
        idx = rng.choice(h.size, size=min(200, h.size), replace=False)
        v[idx] = rng.randn(idx.size)
        eps = 1e-6 * max(1.0, np.abs(h).max())
        _, g0 = _fun_grad_beta(h, beta)
        _, g1 = _fun_grad_beta(h + eps * v, beta)
        fd = (g1 - g0) / eps
        hv = _hv(v, h, beta)
        denom = max(np.linalg.norm(fd), 1e-12)
        rel = np.linalg.norm(fd - hv) / denom
        print("hv check rel err=%.3e" % rel)
    except Exception as e:
        print("hv check failed: %s" % e)

    # ---- Lanczos ----
    try:
        evals, V = _lanczos(h, beta, 40, deadline - 15.0)
        order = np.argsort(evals)
        print("lanczos: %d ritz values, smallest 10:" % len(evals))
        for i in order[:10]:
            print("  ritz %.6e" % evals[i])
    except Exception as e:
        print("lanczos failed: %s" % e)
        evals, V = np.array([]), np.zeros((h.size, 0))

    # ---- Candidate generation ----
    candidates = []
    if V.shape[1] > 0:
        order = np.argsort(evals)
        neg = [i for i in order if evals[i] < 0]
        if neg:
            chosen = neg[:6]
        else:
            chosen = order[:4]
        hmax = h.max()
        for ci in chosen:
            v = V[:, ci].copy()
            nv = np.linalg.norm(v)
            if nv <= 0:
                continue
            v /= nv
            vmax = np.abs(v).max()
            if vmax <= 0:
                continue
            for sign in (1.0, -1.0):
                vs = sign * v
                for f in (0.02, 0.1, 0.3):
                    t = f * hmax / vmax
                    cand = np.clip(h + t * vs, 0, None)
                    if cand.sum() <= 0:
                        continue
                    cand = _rescale(cand)
                    r = R_of(cand)
                    candidates.append((r, cand, ci, sign, f))
    candidates.sort(key=lambda x: -x[0])
    print("top candidates pre-polish:")
    for r, _, ci, sg, f in candidates[:6]:
        print("  R=%.9f (ritz %d sign %+d f %.2f)" % (r, ci, sg, f))

    # ---- Polish top 3 ----
    polished = []
    for r0, cand, ci, sg, f in candidates[:3]:
        if time.process_time() >= deadline - 8.0:
            break
        sub_deadline = min(deadline - 5.0, time.process_time() + 6.0)
        ht, rt = run_cycle(cand, r0, sub_deadline)
        if time.process_time() < deadline - 3.0:
            win = _peak_window(ht, pad_frac=0.10, extra=128)
            ht2 = _lbfgs_block(ht, win, 200, deadline - 3.0, beta=1e7)
            r2 = R_of(ht2)
            if r2 > rt:
                ht, rt = ht2, r2
        polished.append((rt, ht))
        print("polished ritz %d sign %+d f %.2f: R=%.9f" % (ci, sg, f, rt))

    polished.sort(key=lambda x: -x[0])
    if polished and polished[0][0] > bestR + 1e-13:
        best, bestR = polished[0][1].copy(), polished[0][0]
        origin = 'ritz'

    # ---- Remaining time: base alternating polish ----
    while time.process_time() < deadline - 0.5:
        prevR = bestR
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
        if bestR <= prevR + 1e-13:
            break

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if beta > 0:
        mx = Lf.max()
        if mx <= 0:
            return 1e18, np.zeros(h.size)
        e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
        Z = e.sum()
        w = e / Z
        sm = mx + np.log(Z) / beta
        gLf = -dq / num + w / sm
        val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    else:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta))

    def f(x):
        return fg(np.clip(x, 0.0, None))

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta))

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _coarsen(h, factor):
    # Average-pool h into fewer steps; keeps shape roughly, halves resolution.
    n = h.size
    m = n // factor
    if m < 2:
        return h
    hh = h[:m * factor].reshape(m, factor).sum(axis=1)
    return hh


def _refine(h, factor, deadline):
    # Upsample by linear interpolation between steps, then rescale.
    n = h.size
    xs = np.arange(n, dtype=float)
    newn = n * factor
    xn = np.linspace(0, n - 1, newn)
    out = np.interp(xn, xs, h)
    return _rescale(np.clip(out, 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None and np.asarray(start).size > 0 and np.asarray(start).sum() > 0:
        base = _rescale(np.clip(np.asarray(start, dtype=float).copy(), 0, None))
        start_best, start_bestR = base.copy(), R_of(base)
    else:
        N = 8192
        i = np.arange(N, dtype=float)
        h = np.sqrt(i + 1.0) - np.sqrt(i)
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # First: continue the fine polish from p1198's structure (this is where
    # the marginal gains have been coming from).
    stages = [
        ('glob0', 'all', 0.0, 0.0, 400),
        ('glob7', 'all', 1e7, 0.0, 300),
        ('win05', 'win', 1e8, 0.05, 250),
        ('glob0b', 'all', 0.0, 0.0, 400),
        ('win10', 'win', 1e8, 0.10, 250),
        ('win25', 'win', 1e8, 0.25, 200),
        ('glob0c', 'all', 0.0, 0.0, 300),
        ('win05b', 'win', 1e7, 0.05, 200),
        ('win10b', 'win', 0.0, 0.10, 200),
        ('glob7b', 'all', 1e7, 0.0, 200),
    ]

    for name, kind, beta, pad, iters in stages:
        if time.process_time() >= deadline - 0.6:
            break
        if kind == 'all':
            ht = _lbfgs_all(best, iters, deadline - 0.5, beta=beta)
        else:
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht = _lbfgs_block(best, win, iters, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            gain = r - bestR
            best, bestR = ht, r
            print("%s: R=%.9f (+%.2e)" % (name, bestR, gain))
        else:
            print("%s: no gain (%.9f)" % (name, r))

    # Seed zeros and do a last fine polish, as in p1198.
    if time.process_time() < deadline - 1.0:
        hs = _seed_zeros(best)
        ht = _lbfgs_all(hs, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
            print("fine polish: R=%.9f" % bestR)

    # New idea: multi-resolution smoothing.  Coarsen the current best to a
    # low-res representation, optimise there (cheap, escapes local minima
    # caused by high-frequency wiggle), then refine back up and re-polish.
    alt_best = best.copy()
    alt_bestR = bestR
    if time.process_time() < deadline - 3.0:
        try:
            for factor in (8, 4, 2):
                if time.process_time() >= deadline - 2.0:
                    break
                hc = _coarsen(best, factor)
                hc = _lbfgs_all(hc, 300, deadline - 1.5, beta=0.0)
                hr = _refine(hc, factor, deadline)
                if hr.size > best.size:
                    hr = hr[:best.size]
                elif hr.size < best.size:
                    pad = np.zeros(best.size - hr.size)
                    hr = np.concatenate([hr, pad])
                hr = _rescale(np.clip(hr, 0, None))
                hr = _lbfgs_all(hr, 300, deadline - 1.0, beta=0.0)
                r = R_of(hr)
                print("multires f=%d: R=%.9f" % (factor, r))
                if r > alt_bestR + 1e-14:
                    alt_best, alt_bestR = hr, r
        except Exception:
            pass

    if alt_bestR > bestR + 1e-14:
        best, bestR = alt_best, alt_bestR
        print("multires improved: R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, start_bestR, best.size))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
