    out[out <= 0] = eps
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None and np.asarray(start).size > 0 and np.asarray(start).sum() > 0:
        base = _rescale(np.clip(np.asarray(start, dtype=float).copy(), 0, None))
        start_best, start_bestR = base.copy(), R_of(base)
    else:
        N = 8192
        i = np.arange(N, dtype=float)
        h = np.sqrt(i + 1.0) - np.sqrt(i)
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # A fresh, structurally-different construction: run the polish on a
    # symmetric "bump" seed of the same length, which explores a different
    # basin than the incoming start.  We keep whichever is better.
    alt = None
    altR = -1.0
    n = best.size
    if n > 0 and time.process_time() < deadline - 5.0:
        # symmetric smooth bump seed of equal length
        x = np.linspace(-1.0, 1.0, n)
        seed = np.exp(-3.0 * x * x)
        seed = _rescale(seed)
        # quick polish on the seed to gauge whether it's competitive
        hseed = _lbfgs_all(seed, 200, deadline - 4.0, beta=0.0)
        hseed = _lbfgs_all(hseed, 200, deadline - 3.5, beta=1e7)
        rseed = R_of(hseed)
        if rseed > altR:
            alt, altR = hseed, rseed

    # Main alternating polish on the incoming start.
    stages = [
        ('glob0', 'all', 0.0, 0.0, 400),
        ('glob7', 'all', 1e7, 0.0, 300),
        ('win05', 'win', 1e8, 0.05, 250),
        ('glob0b', 'all', 0.0, 0.0, 400),
        ('win10', 'win', 1e8, 0.10, 250),
        ('win25', 'win', 1e8, 0.25, 200),
        ('glob0c', 'all', 0.0, 0.0, 300),
        ('win05b', 'win', 1e7, 0.05, 200),
        ('win10b', 'win', 0.0, 0.10, 200),
        ('glob7b', 'all', 1e7, 0.0, 200),
        ('glob0d', 'all', 0.0, 0.0, 300),
        ('win02', 'win', 1e8, 0.02, 200),
        ('win15', 'win', 1e8, 0.15, 250),
        ('glob0e', 'all', 0.0, 0.0, 400),
    ]

    for name, kind, beta, pad, iters in stages:
        if time.process_time() >= deadline - 0.6:
            break
        if kind == 'all':
            ht = _lbfgs_all(best, iters, deadline - 0.5, beta=beta)
        else:
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht = _lbfgs_block(best, win, iters, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            gain = r - bestR
            best, bestR = ht, r
            print("%s: R=%.9f (+%.2e)" % (name, bestR, gain))
        else:
            print("%s: no gain (%.9f)" % (name, r))

    # Fine-grained interior polish on the winner.
    if time.process_time() < deadline - 1.0:
        hs = _seed_zeros(best)
        ht = _lbfgs_all(hs, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
            print("fine polish: R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, alt %.9f, N=%d)" %
          (bestR, start_bestR, altR, best.size))

    if alt is not None and altR > start_bestR + 1e-13 and altR >= bestR - 1e-13:
        # alternative is genuinely different and at least as good
        if bestR > start_bestR + 1e-13:
            return {"best": best, "alternative": alt}
        return {"best": alt, "alternative": best}
    if bestR >= start_bestR - 1e-13:
        if alt is not None:
            return {"best": best, "alternative": alt}
        return best
    return {"best": best, "alternative": alt if alt is not None else best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tight=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    if tight:
        opts['ftol'] = 0.0
        opts['gtol'] = 0.0
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_interior_beta(h0, free, beta, maxiter, deadline):
    return _lbfgs_block(h0, free, maxiter, deadline, beta=beta)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _interior_beta_phase(best, bestR, deadline):
    h = np.clip(best, 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return best, bestR
    active = np.flatnonzero(h > 1e-6 * mx)
    if active.size < 4:
        return best, bestR
    i0 = int(active.min())
    i1 = int(active.max())
    L = i1 - i0 + 1
    lo = i0 + int(0.10 * L)
    hi = i0 + int(0.90 * L)
    if hi <= lo:
        return best, bestR
    free = np.arange(lo, hi + 1)
    betas = [1e4, 3e4, 1e5, 3e5, 1e6, 3e6, 1e7]
    cur = h
    curR = bestR
    bestArr = best.copy()
    bestR2 = bestR
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            print("interior-beta: out of time at beta=%.0e" % beta)
            break
        ht = _lbfgs_interior_beta(cur, free, beta, 80, deadline - 0.5)
        r = R_of(ht)
        b1 = _band_frac(ht, 0.01)
        print("interior-beta %.0e: R=%.9f band1=%.4f" % (beta, r, b1))
        if r > bestR2 + 1e-15:
            bestArr, bestR2 = ht.copy(), r
        if r > curR + 1e-15:
            cur, curR = ht, r
        else:
            cur, curR = ht, r
    print("interior-beta done: best R=%.9f (start %.9f)" % (bestR2, bestR))
    return bestArr, bestR2


# ---------------- Experiment: conservative resample ----------------

def _conservative_resample(h, M):
    h = np.asarray(h, dtype=float)
    N = h.size
    w = N / float(M)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(M + 1, dtype=float) * w
    cm = np.interp(edges, np.arange(N + 1, dtype=float), cum)
    new_h = np.diff(cm) / w
    return new_h


def _resample_splat(h, M):
    h = np.asarray(h, dtype=float)
    N = h.size
    w = N / float(M)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(M + 1, dtype=float) * w
    cm = np.interp(edges, np.arange(N + 1, dtype=float), cum)
    new_h = np.diff(cm) / w
    return np.clip(new_h, 0, None)


# ---------------- Experiment: edge spike ----------------

def _outer_decay_ratio(h, side):
    """Estimate the outer decay ratio of the active support on one side."""
    h = np.clip(h, 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return 0.9
    active = np.flatnonzero(h > 1e-6 * mx)
    if active.size < 4:
        return 0.9
    if side == 'left':
        i0 = int(active.min())
        # heights going outward from i0
        vals = h[i0:i0 + 6]
    else:
        i1 = int(active.max())
        vals = h[max(0, i1 - 5):i1 + 1][::-1]
    vals = vals[vals > 0]
    if vals.size < 2:
        return 0.9
    ratios = vals[1:] / np.maximum(vals[:-1], 1e-30)
    rho = float(np.median(ratios))
    return float(np.clip(rho, 0.5, 0.98))


def _edge_spike(h, side, pad, H, base):
    """Add `pad` extra cells at the given end. Inner cells = base*rho**k,
    outermost = H. Then rescale."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    rho = _outer_decay_ratio(h, side)
    # inner ramp cells (k = 0..pad-2), outermost is H
    ramp = np.array([base * (rho ** k) for k in range(pad - 1)], dtype=float)
    extra = np.concatenate((ramp, [float(H)]))
    if side == 'left':
        out = np.concatenate((extra, h))
    else:
        out = np.concatenate((h, extra))
    return _rescale(out)


def _outer_window(n, k):
    k = min(k, n // 4)
    if k <= 0:
        return np.arange(n)
    return np.concatenate((np.arange(0, k), np.arange(n - k, n)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Experiment: conservative resample to non-commensurate M ----
    M = 131072
    try:
        ht = _conservative_resample(start_best, M)
        ht = _rescale(ht)
        r = R_of(ht)
        print("resample M=%d: R=%.9f (start %.9f, drop %.2e)" %
              (M, r, start_bestR, start_bestR - r))
        if start_bestR - r > 1e-4:
            print("resample drop too large, using splat fallback")
            ht = _rescale(_resample_splat(start_best, M))
            r = R_of(ht)
            print("splat fallback: R=%.9f" % r)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            origin = 'resample'
    except Exception as e:
        print("resample failed: %s" % e)

    # ---- Base's proven machinery on the best array ----
    if time.process_time() < deadline - 8.0:
        ht, rt = run_cycle(best, bestR, deadline - 8.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+cycle'
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Tight peak-window polish ----
    try:
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            print("tight polish beta=0: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+tight0'
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            print("tight polish beta=1e7: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+tight7'
    except Exception as e:
        print("tight polish failed: %s" % e)

    # ---- Outer-window passes on outermost 2000 cells of each end ----
    try:
        n = best.size
        k = min(2000, n // 4)
        if k > 0:
            outer = np.concatenate((np.arange(0, k), np.arange(n - k, n)))
            for beta in (0.0, 1e7):
                if time.process_time() >= deadline - 0.5:
                    break
                ht = _lbfgs_block(best, outer, 200, deadline - 0.5, beta=beta)
                r = R_of(ht)
                print("outer pass beta=%.0e: R=%.9f" % (beta, r))
                if r > bestR + 1e-13:
                    best, bestR = ht, r
                    origin = origin + '+outer%.0e' % beta
    except Exception as e:
        print("outer pass failed: %s" % e)

    # ================= EXPERIMENT: edge spike =================
    # Screen candidates: H in {2,8,32,128}*outer-active and {0.05,0.2,1.0,5.0}*max,
    # pad in {2,4,8}, sides left/right/both. Each gets ~3 s of block polish.
    spike_best = best.copy()
    spike_bestR = bestR
    candidates = []

    try:
        h = np.clip(best, 0, None)
        n = h.size
        mx = h.max()
        active = np.flatnonzero(h > 1e-6 * mx) if mx > 0 else np.array([0])
        if active.size > 0:
            left_outer = h[int(active.min())]
            right_outer = h[int(active.max())]
        else:
            left_outer = right_outer = mx
        outer_ref = max(left_outer, right_outer, 1e-30)
        H_mults_outer = [2.0, 8.0, 32.0, 128.0]
        H_mults_max = [0.05, 0.2, 1.0, 5.0]
        pads = [2, 4, 8]
        sides = ['left', 'right', 'both']

        # Build candidate list (dedup by (side,pad,H,base) approx)
        cand_specs = []
        for side in sides:
            for pad in pads:
                for m in H_mults_outer:
                    cand_specs.append((side, pad, m * outer_ref, outer_ref))
                for m in H_mults_max:
                    cand_specs.append((side, pad, m * mx, mx * 0.5))

        # Screen each with ~3 s
        screen_deadline = deadline - 0.5
        # Reserve time for top-2 full cycles (~10 s each) + final polish
        reserve = 25.0
        screen_end = min(screen_deadline - reserve,
                         t0 + budget_seconds * 0.55)

        for (side, pad, H, base) in cand_specs:
            if time.process_time() >= screen_end:
                break
            try:
                if side == 'both':
                    hs = _edge_spike(h, 'left', pad, H, base)
                    hs = _edge_spike(hs, 'right', pad, H, base)
                else:
                    hs = _edge_spike(h, side, pad, H, base)
                r_pre = R_of(hs)
                # ~3 s block polish: outer 2000 cells, beta=0 then beta=1e7
                sub_deadline = min(screen_end, time.process_time() + 3.0)
                nn = hs.size
                outer = _outer_window(nn, 2000)
                ht = _lbfgs_block(hs, outer, 150, sub_deadline, beta=0.0)
                if time.process_time() < sub_deadline:
                    ht = _lbfgs_block(ht, _outer_window(ht.size, 2000),
                                      150, sub_deadline, beta=1e7)
                if time.process_time() < sub_deadline:
                    ht = _lbfgs_all_pos(ht, 150, sub_deadline, beta=0.0)
                r_post = R_of(ht)
                print("spike %s pad=%d H=%.3g base=%.3g: pre=%.9f post=%.9f" %
                      (side, pad, H, base, r_pre, r_post))
                candidates.append((r_post, ht.copy(), side, pad, H, base))
                if r_post > spike_bestR + 1e-13:
                    spike_best, spike_bestR = ht.copy(), r_post
                    origin = origin + '+spike'
            except Exception as e:
                print("spike candidate failed: %s" % e)
                continue

        # Take top 2 by exact R, give each a full run_cycle + outer beta=1e7
        candidates.sort(key=lambda x: -x[0])
        top2 = candidates[:2]
        for idx, (r0, arr, side, pad, H, base) in enumerate(top2):
            if time.process_time() >= deadline - 0.5:
                break
            print("spike top%d (%s pad=%d H=%.3g): R0=%.9f" %
                  (idx + 1, side, pad, H, r0))
            cyc_deadline = min(deadline - 0.5,
                               time.process_time() + 10.0)
            ht, rt = run_cycle(arr, r0, cyc_deadline)
            if rt > spike_bestR + 1e-13:
                spike_best, spike_bestR = ht.copy(), rt
                origin = origin + '+spikecycle%d' % (idx + 1)
            if time.process_time() < deadline - 0.5:
                outer = _outer_window(ht.size, 2000)
                ht2 = _lbfgs_block(ht, outer, 200, deadline - 0.5, beta=1e7)
                r2 = R_of(ht2)
                print("spike top%d outer beta=1e7: R=%.9f" % (idx + 1, r2))
                if r2 > spike_bestR + 1e-13:
                    spike_best, spike_bestR = ht2.copy(), r2
                    origin = origin + '+spikeouter%d' % (idx + 1)
    except Exception as e:
        print("edge spike experiment failed: %s" % e)

    if spike_bestR > bestR + 1e-13:
        best, bestR = spike_best, spike_bestR

    # ---- Final tight polish if time remains ----
    try:
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            print("final tight polish: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+finaltight'
    except Exception as e:
        print("final tight polish failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tight=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    if tight:
        opts['ftol'] = 0.0
        opts['gtol'] = 0.0
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_interior_beta(h0, free, beta, maxiter, deadline):
    return _lbfgs_block(h0, free, maxiter, deadline, beta=beta)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------------- Experiment: smooth multiplicative envelope ----------------

def _support_bounds(h):
    mx = h.max()
    if mx <= 0:
        return 0, h.size - 1
    act = np.flatnonzero(h > 1e-9 * mx)
    if act.size == 0:
        return 0, h.size - 1
    return int(act.min()), int(act.max())


def _make_basis(N, K, i0, i1):
    # B_k(i) = cos(pi*k*(i-i0)/(i1-i0)) for i in [i0,i1], else 0
    L = max(1, i1 - i0)
    idx = np.arange(i0, i1 + 1, dtype=float)
    x = (idx - i0) / float(L)
    B = np.zeros((K, N), dtype=float)
    for k in range(K):
        B[k, i0:i1 + 1] = np.cos(np.pi * k * x)
    return B


def _envelope_opt(h0, K, deadline, iters, c_init=None, additive=False):
    h0 = np.clip(h0, 0, None)
    if h0.sum() <= 0:
        return h0, 0.0, None
    N = h0.size
    i0, i1 = _support_bounds(h0)
    if i1 <= i0:
        return h0, R_of(h0), c_init
    B = _make_basis(N, K, i0, i1)
    if c_init is None:
        c = np.zeros(K)
    else:
        c = np.asarray(c_init, dtype=float).copy()
        if c.size != K:
            c2 = np.zeros(K)
            m = min(K, c.size)
            c2[:m] = c[:m]
            c = c2

    def build(cvec):
        if additive:
            h = h0 + (cvec @ B)
            h = np.clip(h, 0, None)
        else:
            e = np.exp(np.clip(cvec @ B, -20.0, 20.0))
            h = h0 * e
        return _rescale(h)

    def f(cvec):
        h = build(cvec)
        val, g = _fun_grad(h)
        # chain rule: dh/dc_k
        # multiplicative: dh_i/dc_k = h_i * B_k_i (before rescale; rescale
        # changes scale only, which the objective is invariant to, so we
        # can ignore the rescale factor in the gradient direction).
        if additive:
            # dh/dc_k = B_k (clipped)
            hraw = h0 + (cvec @ B)
            mask = (hraw > 0).astype(float)
            gc = np.array([np.sum(g * B[k] * mask) for k in range(K)])
        else:
            hraw = h0 * np.exp(np.clip(cvec @ B, -20.0, 20.0))
            gc = np.array([np.sum(g * hraw * B[k]) for k in range(K)])
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c, jac=True, method='L-BFGS-B',
                       bounds=[(-1.0, 1.0)] * K,
                       callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-16, 'gtol': 1e-16})
        c = res.x
    except (TimeoutError, Exception):
        pass
    h = build(c)
    return h, R_of(h), c


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Experiment: smooth multiplicative envelope ----
    env_best = best.copy()
    env_bestR = bestR
    env_origin = 'none'
    try:
        # gradient norm at c=0 diagnostic
        N = best.size
        i0, i1 = _support_bounds(best)
        if i1 > i0:
            B16 = _make_basis(N, 16, i0, i1)
            val0, g0 = _fun_grad(best)
            gc0 = np.array([np.sum(g0 * best * B16[k]) for k in range(16)])
            print("envelope grad norm at c=0 (K=16): %.3e" % np.linalg.norm(gc0))

        # Stage 1: K=16, 800 iters
        if time.process_time() < deadline - 5.0:
            hA, rA, cA = _envelope_opt(best, 16, deadline - 3.0, 800)
            print("envelope K=16: R=%.9f (start %.9f)" % (rA, bestR))
            if rA > env_bestR + 1e-13:
                env_best, env_bestR = hA.copy(), rA
                env_origin = 'env16'
            # Stage 2: K=48, 600 iters from cA
            if time.process_time() < deadline - 3.0:
                hB, rB, cB = _envelope_opt(best, 48, deadline - 2.0, 600,
                                           c_init=None)
                print("envelope K=48: R=%.9f" % rB)
                if rB > env_bestR + 1e-13:
                    env_best, env_bestR = hB.copy(), rB
                    env_origin = 'env48'
                # also try K=48 starting from padded cA
                if time.process_time() < deadline - 2.0 and cA is not None:
                    c48 = np.zeros(48)
                    c48[:16] = cA
                    hB2, rB2, _ = _envelope_opt(best, 48, deadline - 1.0, 400,
                                                c_init=c48)
                    print("envelope K=48 (from c16): R=%.9f" % rB2)
                    if rB2 > env_bestR + 1e-13:
                        env_best, env_bestR = hB2.copy(), rB2
                        env_origin = 'env48c16'

        # Additive fallback
        if time.process_time() < deadline - 3.0:
            hC, rC, _ = _envelope_opt(best, 16, deadline - 1.0, 400,
                                      additive=True)
            print("envelope additive K=16: R=%.9f" % rC)
            if rC > env_bestR + 1e-13:
                env_best, env_bestR = hC.copy(), rC
                env_origin = 'envadd16'
    except Exception as e:
        print("envelope stage failed: %s" % e)

    print("envelope best: R=%.9f origin=%s (start %.9f)" %
          (env_bestR, env_origin, start_bestR))

    if env_bestR > bestR + 1e-13:
        best, bestR = env_best.copy(), env_bestR
        origin = env_origin

    # ---- Base's proven machinery on the best array ----
    if time.process_time() < deadline - 8.0:
        ht, rt = run_cycle(best, bestR, deadline - 8.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+cycle'
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Alternating polishes on best ----
    try:
        for _ in range(100):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+all0'
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+all7'
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+pk0'
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+pk7'
    except Exception as e:
        print("polish loop failed: %s" % e)

    # ---- Outer-window passes ----
    try:
        n = best.size
        k = min(2000, n // 4)
        if k > 0:
            outer = np.concatenate((np.arange(0, k), np.arange(n - k, n)))
            for beta in (0.0, 1e7):
                if time.process_time() >= deadline - 0.5:
                    break
                ht = _lbfgs_block(best, outer, 200, deadline - 0.5, beta=beta)
                r = R_of(ht)
                print("outer pass beta=%.0e: R=%.9f" % (beta, r))
                if r > bestR + 1e-13:
                    best, bestR = ht, r
                    origin = origin + '+outer%.0e' % beta
    except Exception as e:
        print("outer pass failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": env_best}

