def _conservative_resample(h, M):
    h = np.asarray(h, dtype=float)
    N = h.size
    w = N / float(M)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(M + 1, dtype=float) * w
    cm = np.interp(edges, np.arange(N + 1, dtype=float), cum)
    new_h = np.diff(cm) / w
    return new_h


def _resample_splat(h, M):
    h = np.asarray(h, dtype=float)
    N = h.size
    w = N / float(M)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(M + 1, dtype=float) * w
    cm = np.interp(edges, np.arange(N + 1, dtype=float), cum)
    new_h = np.diff(cm) / w
    return np.clip(new_h, 0, None)


def _warp(h, M, p):
    """Mass-preserving resample to M cells with warped edges.
    edges = N*(arange(M+1)/M)**p."""
    h = np.asarray(h, dtype=float)
    N = h.size
    cum = np.concatenate(([0.0], np.cumsum(h)))
    u = np.arange(M + 1, dtype=float) / M
    edges = N * (u ** p)
    cm = np.interp(edges, np.arange(N + 1, dtype=float), cum)
    new_h = np.diff(cm) / (N / float(M))
    return np.clip(new_h, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Experiment: chirped comb sweep ----
    M = start_best.size if start_best.size > 0 else 104992
    ps = [0.94, 0.97, 1.03, 1.06]
    candidates = []  # (post_polish_R, p, array)
    for p in ps:
        if time.process_time() >= deadline - 8.0:
            print("warp p=%.2f: skipped (time)" % p)
            break
        try:
            hw = _rescale(_warp(start_best, M, p))
            r0 = R_of(hw)
            drop = start_bestR - r0
            print("warp p=%.2f: raw R=%.9f drop=%.2e" % (p, r0, drop))
            if drop > 2e-3:
                print("warp p=%.2f: drop too large, skipping polish" % p)
                continue
            # ~8s polish
            tsub = time.process_time() + 8.0
            sub_deadline = min(deadline - 0.5, tsub)
            hw2 = _lbfgs_all_pos(hw, 150, sub_deadline, beta=0.0)
            win = _peak_window(hw2, pad_frac=0.25, extra=512)
            hw2 = _lbfgs_block(hw2, win, 150, sub_deadline, beta=0.0)
            win = _peak_window(hw2, pad_frac=0.25, extra=512)
            hw2 = _lbfgs_block(hw2, win, 150, sub_deadline, beta=1e7)
            rp = R_of(hw2)
            print("warp p=%.2f: post-polish R=%.9f" % (p, rp))
            candidates.append((rp, p, hw2))
        except Exception as e:
            print("warp p=%.2f failed: %s" % (p, e))

    # Take best two p by post-polish exact R
    candidates.sort(key=lambda t: -t[0])
    top = candidates[:2]
    for rp, p, arr in top:
        if rp > bestR + 1e-13:
            best, bestR = arr.copy(), rp
            origin = 'warp%.2f' % p
    print("after warp sweep best R=%.9f origin=%s" % (bestR, origin))

    # Full run_cycle on best two p
    for rp, p, arr in top:
        if time.process_time() >= deadline - 0.5:
            break
        ht, rt = run_cycle(arr.copy(), rp, deadline - 0.5)
        print("warp p=%.2f run_cycle: R=%.9f" % (p, rt))
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+cycle%.2f' % p
        # outer-window pass on first/last 4000 cells
        if time.process_time() < deadline - 0.5:
            n = ht.size
            k = min(4000, n // 4)
            if k > 0:
                outer = np.concatenate((np.arange(0, k), np.arange(n - k, n)))
                ht2 = _lbfgs_block(ht, outer, 200, deadline - 0.5, beta=1e7)
                r2 = R_of(ht2)
                print("warp p=%.2f outer beta=1e7: R=%.9f" % (p, r2))
                if r2 > bestR + 1e-13:
                    best, bestR = ht2, r2
                    origin = origin + '+outer%.2f' % p

    # ---- Base's proven machinery on the best array ----
    if time.process_time() < deadline - 8.0:
        ht, rt = run_cycle(best, bestR, deadline - 8.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+cycle'
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Tight peak-window polish ----
    try:
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            print("tight polish beta=0: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+tight0'
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            print("tight polish beta=1e7: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+tight7'
    except Exception as e:
        print("tight polish failed: %s" % e)

    # ---- Outer-window passes on outermost 2000 cells of each end ----
    try:
        n = best.size
        k = min(2000, n // 4)
        if k > 0:
            outer = np.concatenate((np.arange(0, k), np.arange(n - k, n)))
            for beta in (0.0, 1e7):
                if time.process_time() >= deadline - 0.5:
                    break
                ht = _lbfgs_block(best, outer, 200, deadline - 0.5, beta=beta)
                r = R_of(ht)
                print("outer pass beta=%.0e: R=%.9f" % (beta, r))
                if r > bestR + 1e-13:
                    best, bestR = ht, r
                    origin = origin + '+outer%.0e' % beta
    except Exception as e:
        print("outer pass failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_hinge(h, lam, eps):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    M = Lf[m]
    if M <= 0:
        return _fun_grad(h)
    K = Lf.size
    u = np.maximum((1.0 - eps) * M - Lf, 0.0) / M
    q = float(np.mean(u * u)) + 1e-12
    gLf = -dq / num
    gLf[m] += 1.0 / M
    # d/du of mean(u^2) = 2u/K ; du/dM = (1-eps)/M - u/M ; du/dLf = -1/M
    # dJ/dM from hinge term: lam/q * dq/dM ; dq/dM = mean(2u * du/dM)
    du_dM = (1.0 - eps) / M - u / M
    dq_dM = float(np.mean(2.0 * u * du_dM))
    gLf[m] += (lam / q) * dq_dM
    # dq/dLf_k = mean over knots of 2u * (-1/M) (only where u>0)
    gLf += -(2.0 * lam / (M * K * q)) * u
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M) + lam * np.log(q)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tight=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    if tight:
        opts['ftol'] = 0.0
        opts['gtol'] = 0.0
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, hinge=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if hinge is not None:
        lam, eps = hinge
        fg = (lambda hh: _fun_grad_hinge(hh, lam, eps))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------------- Experiment: smooth multiplicative envelope ----------------

def _support_bounds(h):
    mx = h.max()
    if mx <= 0:
        return 0, h.size - 1
    act = np.flatnonzero(h > 1e-9 * mx)
    if act.size == 0:
        return 0, h.size - 1
    return int(act.min()), int(act.max())


def _make_basis(N, K, i0, i1):
    L = max(1, i1 - i0)
    idx = np.arange(i0, i1 + 1, dtype=float)
    x = (idx - i0) / float(L)
    B = np.zeros((K, N), dtype=float)
    for k in range(K):
        B[k, i0:i1 + 1] = np.cos(np.pi * k * x)
    return B


def _envelope_opt(h0, K, deadline, iters, c_init=None, additive=False):
    h0 = np.clip(h0, 0, None)
    if h0.sum() <= 0:
        return h0, 0.0, None
    N = h0.size
    i0, i1 = _support_bounds(h0)
    if i1 <= i0:
        return h0, R_of(h0), c_init
    B = _make_basis(N, K, i0, i1)
    if c_init is None:
        c = np.zeros(K)
    else:
        c = np.asarray(c_init, dtype=float).copy()
        if c.size != K:
            c2 = np.zeros(K)
            m = min(K, c.size)
            c2[:m] = c[:m]
            c = c2

    def build(cvec):
        if additive:
            h = h0 + (cvec @ B)
            h = np.clip(h, 0, None)
        else:
            e = np.exp(np.clip(cvec @ B, -20.0, 20.0))
            h = h0 * e
        return _rescale(h)

    def f(cvec):
        h = build(cvec)
        val, g = _fun_grad(h)
        if additive:
            hraw = h0 + (cvec @ B)
            mask = (hraw > 0).astype(float)
            gc = np.array([np.sum(g * B[k] * mask) for k in range(K)])
        else:
            hraw = h0 * np.exp(np.clip(cvec @ B, -20.0, 20.0))
            gc = np.array([np.sum(g * hraw * B[k]) for k in range(K)])
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c, jac=True, method='L-BFGS-B',
                       bounds=[(-1.0, 1.0)] * K,
                       callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-16, 'gtol': 1e-16})
        c = res.x
    except (TimeoutError, Exception):
        pass
    h = build(c)
    return h, R_of(h), c


# ---------------- Experiment: hinge on deficit ----------------

def _hinge_phase(h, lam, eps, deadline):
    if time.process_time() >= deadline - 0.5:
        return h
    win = _peak_window(h, pad_frac=0.5, extra=2048)
    ht = _lbfgs_block(h, win, 200, deadline - 0.3, hinge=(lam, eps))
    if time.process_time() < deadline - 0.5:
        ht2 = _lbfgs_all_pos(ht, 100, deadline - 0.3, beta=0.0)
        # keep whichever is better under exact R
        if R_of(ht2) >= R_of(ht):
            ht = ht2
    return ht


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Experiment: hinge on deficit ----
    hinge_best = best.copy()
    hinge_bestR = bestR
    hinge_origin = 'none'
    ladder = [(0.03, 0.05), (0.06, 0.02), (0.10, 0.01), (0.03, 0.004)]
    try:
        cur = best.copy()
        rung_count = 0
        while time.process_time() < deadline - 3.0:
            for (lam, eps) in ladder:
                if time.process_time() >= deadline - 3.0:
                    break
                ht = _hinge_phase(cur, lam, eps, deadline - 2.0)
                r = R_of(ht)
                rung_count += 1
                print("hinge lam=%.3f eps=%.4f: R=%.9f" % (lam, eps, r))
                if r > hinge_bestR + 1e-13:
                    hinge_best, hinge_bestR = ht.copy(), r
                    hinge_origin = 'hinge(%.2f,%.3f)' % (lam, eps)
                cur = ht
            # lam=0 exact polish
            if time.process_time() < deadline - 2.0:
                ht = _lbfgs_all_pos(cur, 300, deadline - 1.5, beta=0.0)
                r = R_of(ht)
                print("hinge lam=0 polish: R=%.9f" % r)
                if r > hinge_bestR + 1e-13:
                    hinge_best, hinge_bestR = ht.copy(), r
                    hinge_origin = 'hinge+polish'
                cur = ht
            # beta=1e7 peak-window pass
            if time.process_time() < deadline - 1.5:
                win = _peak_window(cur, pad_frac=0.5, extra=2048)
                ht = _lbfgs_block(cur, win, 200, deadline - 1.0, beta=1e7)
                r = R_of(ht)
                print("hinge beta=1e7 pass: R=%.9f" % r)
                if r > hinge_bestR + 1e-13:
                    hinge_best, hinge_bestR = ht.copy(), r
                    hinge_origin = 'hinge+beta'
                cur = ht
            if rung_count > 40:
                break
    except Exception as e:
        print("hinge stage failed: %s" % e)

    print("hinge best: R=%.9f origin=%s (start %.9f)" %
          (hinge_bestR, hinge_origin, start_bestR))

    if hinge_bestR > bestR + 1e-13:
        best, bestR = hinge_best.copy(), hinge_bestR
        origin = hinge_origin

    # ---- Base's proven machinery on the best array ----
    if time.process_time() < deadline - 8.0:
        ht, rt = run_cycle(best, bestR, deadline - 8.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+cycle'
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Alternating polishes on best ----
    try:
        for _ in range(100):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+all0'
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+all7'
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
