    i0 = int(active.min()); i1 = int(active.max())
    L = i1 - i0 + 1
    lo = i0 + int(0.10 * L); hi = i0 + int(0.90 * L)
    if hi <= lo:
        return best, bestR
    free = np.arange(lo, hi + 1)
    betas = [1e4, 3e4, 1e5, 3e5, 1e6, 3e6, 1e7]
    cur = h; curR = bestR
    bestArr = best.copy(); bestR2 = bestR
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_block(cur, free, 80, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR2 + 1e-15:
            bestArr, bestR2 = ht.copy(), r
        cur, curR = ht, r
    return bestArr, bestR2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- NEW: interior-beta phase -- widen the peak band ----
    if time.process_time() < deadline - 20.0:
        ht, rt = _interior_beta_phase(best, bestR, deadline - 15.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin += '+ibeta'
        print("interior-beta R=%.9f band01=%.3f" %
              (bestR, _band_frac(best, 0.001)))

    # ---- NEW: grow the array by subdividing the peak region ----
    # Subdivide each cell of the peak region into 2, keeping heights.
    if time.process_time() < deadline - 12.0:
        try:
            Lf = _knots(best)
            mxk = Lf.max()
            idx = np.flatnonzero(Lf >= 0.9 * mxk)
            if idx.size > 0:
                a, b = int(idx.min()), int(idx.max())
                a = max(0, a - 2); b = min(best.size - 1, b + 2)
                if b > a:
                    left = best[:a]
                    mid = best[a:b + 1]
                    right = best[b + 1:]
                    mid2 = np.repeat(mid, 2) * 0.5
                    hg = np.concatenate([left, mid2, right])
                    hg = _rescale(hg)
                    rg = R_of(hg)
                    print("grow N=%d R=%.9f" % (hg.size, rg))
                    if rg > bestR - 1e-6:
                        hg2 = _lbfgs_all_pos(hg, 400, deadline - 8.0, beta=0.0)
                        rg2 = R_of(hg2)
                        print("grow-polish R=%.9f" % rg2)
                        if rg2 > bestR + 1e-13:
                            best, bestR = hg2, rg2
                            origin += '+grow'
        except Exception as e:
            print("grow failed: %s" % e)

    # ---- Main polish loop: alternate peak-window and full L-BFGS ----
    while time.process_time() < deadline - 1.0:
        try:
            win = _peak_window(best, pad_frac=0.08, extra=128)
            ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin += '+pw0'
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(best, pad_frac=0.15, extra=128)
            ht = _lbfgs_block(best, win, 200, deadline - 0.5, beta=1e8)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin += '+pw7'
            if time.process_time() >= deadline - 1.0:
                break
            ht, rt = run_cycle(best, bestR, deadline - 0.5)
            if rt > bestR + 1e-13:
                best, bestR = ht, rt
                origin += '+cycle'
            else:
                # small perturbation to escape local optimum
                hb = best.copy()
                nz = np.flatnonzero(hb > 0)
                if nz.size > 10:
                    k = max(1, nz.size // 200)
                    pick = np.random.choice(nz, size=k, replace=False)
                    hb[pick] *= (1.0 + 0.02 * np.random.randn(k))
                    hb = _rescale(np.clip(hb, 0, None))
                    rp = R_of(hb)
                    if rp > bestR - 1e-6:
                        ht2, rt2 = run_cycle(hb, rp, deadline - 0.5)
                        if rt2 > bestR + 1e-13:
                            best, bestR = ht2, rt2
                            origin += '+pert'
        except Exception as e:
            print("polish loop failed: %s" % e)
            break

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve

# ---------- exact evaluation ----------

def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)

def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))

def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den

def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf

def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]

def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)

def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad

def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad

def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb

def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))

def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)

def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)

def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out

def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))

# ---------- resampling / grid change ----------

def _resample_to(h, N):
    """Resample a step-function height array onto N equal steps (mass preserving)."""
    n = h.size
    if n == N:
        return h.copy()
    # cumulative mass at old step boundaries
    cum = np.concatenate(([0.0], np.cumsum(h)))
    total = cum[-1]
    if total <= 0:
        return np.zeros(N)
    # new boundaries in old-index coordinates
    x_new = np.arange(N + 1) * (n / N)
    # interpolate cumulative mass (piecewise linear in old-index space)
    xs = np.arange(n + 1, dtype=float)
    mass = np.interp(x_new, xs, cum)
    return np.diff(mass)

def _expand(h, factor):
    """Upsample by integer factor with piecewise-constant replication."""
    if factor <= 1:
        return h.copy()
    return np.repeat(h, factor).astype(float)

# ---------- refinement phases ----------

def _run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 600, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 96, 1e8), (0.20, 128, 1e8),
              (0.35, 192, 1e8), (0.55, 320, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=200, deadline=deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 250, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    return best, bestR

def _interior_beta_phase(best, bestR, deadline):
    h = np.clip(best, 0, None)
    mx = h.max()
    if mx <= 0:
        return best, bestR
    active = np.flatnonzero(h > 1e-6 * mx)
    if active.size < 4:
        return best, bestR
    i0 = int(active.min())
    i1 = int(active.max())
    L = i1 - i0 + 1
    lo = i0 + int(0.10 * L)
    hi = i0 + int(0.90 * L)
    if hi <= lo:
        return best, bestR
    free = np.arange(lo, hi + 1)
    betas = [1e4, 3e4, 1e5, 3e5, 1e6, 3e6, 1e7]
    cur = h
    curR = bestR
    bestArr = best.copy()
    bestR2 = bestR
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_block(cur, free, 80, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR2 + 1e-15:
            bestArr, bestR2 = ht.copy(), r
        cur, curR = ht, r
    return bestArr, bestR2

# ---------- main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Grid-change exploration: resample onto coarser/finer grids and refine ----
    # A coarser grid with the same shape can sometimes allow escape from a local max
    # because the parameterisation is different. We try a range of N and keep the best.
    N0 = best.size
    grid_candidates = []
    for frac in (0.25, 0.5, 0.75, 1.5, 2.0):
        Nf = int(round(N0 * frac))
        if 64 <= Nf <= 1000000 and Nf != N0:
            grid_candidates.append(Nf)

    sweep_best = None
    sweep_bestR = -1.0
    sweep_bestN = None
    sweep_deadline = min(deadline - 0.5, t0 + budget_seconds * 0.45)

    for Nf in grid_candidates:
        if time.process_time() >= sweep_deadline - 0.5:
            break
        try:
            hr = _resample_to(best, Nf)
            r0 = R_of(hr)
            # short polish on the new grid
            t_end = min(sweep_deadline, time.process_time() + 3.0)
            hp = _lbfgs_all_pos(_seed_zeros(hr), 400, t_end, beta=0.0)
            rp = R_of(hp)
            print("grid N=%d: R0=%.9f -> %.9f" % (Nf, r0, rp))
            if rp > sweep_bestR:
                sweep_best, sweep_bestR, sweep_bestN = hp.copy(), rp, Nf
            if rp > bestR + 1e-14:
                best, bestR = hp.copy(), rp
                origin = 'grid(N=%d)' % Nf
        except Exception as e:
            print("grid N=%d failed: %s" % (Nf, e))

    # Also try expanding best by integer factor then re-refining (finer grid).
    for factor in (2, 3):
        if time.process_time() >= sweep_deadline - 0.5:
            break
        Nf = best.size * factor
        if Nf > 1000000:
            continue
        try:
            hr = _expand(best, factor)
            t_end = min(sweep_deadline, time.process_time() + 3.0)
            hp = _lbfgs_all_pos(hr, 400, t_end, beta=0.0)
            rp = R_of(hp)
            print("expand x%d: R=%.9f" % (factor, rp))
            if rp > sweep_bestR:
                sweep_best, sweep_bestR, sweep_bestN = hp.copy(), rp, Nf
            if rp > bestR + 1e-14:
                best, bestR = hp.copy(), rp
                origin = 'expand(x%d)' % factor
        except Exception as e:
            print("expand x%d failed: %s" % (factor, e))

    print("grid sweep done: best R=%.9f (N=%s), current best R=%.9f (N=%d)" %
          (sweep_bestR, sweep_bestN, bestR, best.size))

    # ---- Base polishing on best ----
    if time.process_time() < deadline - 8.0:
        ht, rt = _run_cycle(best, bestR, deadline - 8.0)
        if rt > bestR + 1e-14:
            best, bestR = ht, rt
            origin = origin + '+cycle'
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Interior beta phase on current best ----
    if time.process_time() < deadline - 2.0:
        ht, rt = _interior_beta_phase(best, bestR, deadline - 2.0)
        if rt > bestR + 1e-14:
            best, bestR = ht, rt
            origin = origin + '+ibeta'

    # ---- Alternating polish until deadline ----
    while time.process_time() < deadline - 1.0:
        try:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 200, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
                origin = origin + '+pw0'
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 200, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
                origin = origin + '+pw7'
            if time.process_time() >= deadline - 1.0:
                break
            ht, rt = _run_cycle(best, bestR, deadline - 0.5)
            if rt > bestR + 1e-14:
                best, bestR = ht, rt
                origin = origin + '+cycle'
            else:
                break
        except Exception as e:
            print("polish loop failed: %s" % e)
            break

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    if sweep_best is not None and sweep_bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": sweep_best}
    return {"best": best, "alternative": best}

