    if res is None:
        return h0, None
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    h2 = _rescale(h2)
    info = {'val0': val0, 'val1': res.fun,
            'step': float(np.linalg.norm(res.x - x0))}
