        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Experiment: hinge on deficit ----
    hinge_best = best.copy()
    hinge_bestR = bestR
    hinge_origin = 'none'
    ladder = [(0.03, 0.05), (0.06, 0.02), (0.10, 0.01), (0.03, 0.004)]
    try:
        cur = best.copy()
        rung_count = 0
        while time.process_time() < deadline - 3.0:
            for (lam, eps) in ladder:
                if time.process_time() >= deadline - 3.0:
                    break
                ht = _hinge_phase(cur, lam, eps, deadline - 2.0)
                r = R_of(ht)
                rung_count += 1
                print("hinge lam=%.3f eps=%.4f: R=%.9f" % (lam, eps, r))
                if r > hinge_bestR + 1e-13:
                    hinge_best, hinge_bestR = ht.copy(), r
                    hinge_origin = 'hinge(%.2f,%.3f)' % (lam, eps)
