        v0, g0 = _fun_grad(h)
        return v0, g0, (lambda v: np.zeros(n))
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)

    mask = (h > 0).astype(float)

    def hessp(v):
        v = np.asarray(v, dtype=float)
        v = v * mask
        if n > 1500:
            c = fftconvolve(h, v)
        else:
            c = np.convolve(h, v)
        dLf = np.zeros(K)
        m = min(K, 2 * n - 1)
        dLf[:m] = 2.0 * c[:m]
        u = float(w @ dLf)
        dq2 = (4.0 * dLf) / 3.0
        dq2[1:] += dLf[:-1] / 3.0
        dq2[:-1] += dLf[1:] / 3.0
        diff = float(dq @ dLf)
        kv = -dq2 / num + diff * dq / (num * num)
        kv += beta * (w * (dLf - u)) / sm - w * u / (sm * sm)
        out = _backprop(kv, v) - 2.0 * v.sum() / (s * s)
        return out * mask

    return val, grad, hessp


def _fun_grad_hinge(h, lam, eps):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    M = Lf[m]
    if M <= 0:
        return _fun_grad(h)
    K = Lf.size
    u = np.maximum((1.0 - eps) * M - Lf, 0.0) / M
    q = float(np.mean(u * u)) + 1e-12
    gLf = -dq / num
    gLf[m] += 1.0 / M
    du_dM = (1.0 - eps) / M - u / M
    dq_dM = float(np.mean(2.0 * u * du_dM))
    gLf[m] += (lam / q) * dq_dM
    gLf += -(2.0 * lam / (M * K * q)) * u
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M) + lam * np.log(q)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tight=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    if tight:
        opts['ftol'] = 0.0
        opts['gtol'] = 0.0
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, hinge=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if hinge is not None:
        lam, eps = hinge
        fg = (lambda hh: _fun_grad_hinge(hh, lam, eps))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------------- Experiment: log-space optimization ----------------

def _fun_grad_log(u, beta=0.0):
    u = np.clip(u, -25.0, 3.0)
    h = np.exp(u)
    if beta > 0:
        val, g_h = _fun_grad_beta(h, beta)
    else:
        val, g_h = _fun_grad(h)
    return val, g_h * h


def _lbfgs_log(u0, maxiter, deadline, beta=0.0, free=None):
    if time.process_time() >= deadline - 0.3:
        return u0
    u = np.clip(np.asarray(u0, dtype=float), -25.0, 3.0)
    if free is None:
        active = np.arange(u.size)
    else:
        active = np.asarray(free, dtype=int)
        if active.size == 0:
            return u0
    x0 = u[active].copy()

    def f(x):
        uu = u.copy()
        uu[active] = np.clip(x, -25.0, 3.0)
        val, g = _fun_grad_log(uu, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-25.0, 3.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return u0
    if res is None:
        return u0
    u2 = u.copy()
    u2[active] = np.clip(res.x, -25.0, 3.0)
    return u2


def _log_ladder(h, deadline, bestR, best):
    """Run the log-space ladder; return (best, bestR, log_best, log_bestR)."""
    if h.sum() <= 0:
        return best, bestR, None, bestR
    hmax = h.max()
    u0 = np.log(np.clip(h, 0.0, None) + 1e-8 * hmax)
    h_init = np.exp(np.clip(u0, -25.0, 3.0))
    r_init = R_of(_rescale(h_init))
    print("log init exact R=%.9f (start %.9f)" % (r_init, bestR))

    log_best = best.copy()
    log_bestR = bestR
    u_cur = u0.copy()

    # (a) beta=0 exact-max
    if time.process_time() < deadline - 0.5:
        u_cur = _lbfgs_log(u_cur, 600, deadline - 0.5, beta=0.0)
        hh = _rescale(np.exp(np.clip(u_cur, -25.0, 3.0)))
        r = R_of(hh)
        print("log beta=0: R=%.9f" % r)
        if r > log_bestR + 1e-13:
            log_best, log_bestR = hh.copy(), r

    # (b) beta ladder
    for beta in (1e5, 1e6, 1e7):
        if time.process_time() >= deadline - 0.5:
            break
        u_cur = _lbfgs_log(u_cur, 400, deadline - 0.5, beta=beta)
        hh = _rescale(np.exp(np.clip(u_cur, -25.0, 3.0)))
        r = R_of(hh)
        print("log beta=%.0e: R=%.9f" % (beta, r))
        if r > log_bestR + 1e-13:
            log_best, log_bestR = hh.copy(), r

    # (c) peak-window block in log space
    if time.process_time() < deadline - 0.5:
        hh_cur = _rescale(np.exp(np.clip(u_cur, -25.0, 3.0)))
        win = _peak_window(hh_cur, pad_frac=0.25, extra=512)
        for beta in (0.0, 1e7):
            if time.process_time() >= deadline - 0.5:
                break
            u_cur = _lbfgs_log(u_cur, 300, deadline - 0.5, beta=beta,
                               free=win)
            hh = _rescale(np.exp(np.clip(u_cur, -25.0, 3.0)))
            r = R_of(hh)
            print("log win beta=%.0e: R=%.9f" % (beta, r))
            if r > log_bestR + 1e-13:
                log_best, log_bestR = hh.copy(), r

    return best, bestR, log_best, log_bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    log_best = None
    log_bestR = 0.0

    # ---- Experiment: log-space ladder (looped while time remains) ----
    try:
        cur = best.copy()
        loop = 0
        while time.process_time() < deadline - 6.0:
            loop += 1
            _, _, lb, lbR = _log_ladder(cur, deadline - 5.0, bestR, best)
            if lb is not None and lbR > log_bestR + 1e-13:
                log_best, log_bestR = lb.copy(), lbR
            if lb is not None and lbR > bestR + 1e-13:
                best, bestR = lb.copy(), lbR
                origin = 'log(loop%d)' % loop
                cur = best.copy()
            else:
                # no improvement; break to save time for base machinery
                break
            if loop >= 3:
                break
    except Exception as e:
        print("log stage failed: %s" % e)

    print("log best: R=%.9f (start %.9f)" % (log_bestR, start_bestR))

    # ---- Base run_cycle on best ----
    if time.process_time() < deadline - 8.0:
        try:
            ht, rt = run_cycle(best, bestR, deadline - 6.0)
            if rt > bestR + 1e-13:
                best, bestR = ht, rt
                origin = origin + '+cycle'
            print("base cycle R=%.7f" % bestR)
        except Exception as e:
            print("cycle failed: %s" % e)

    # ---- Final linear-space sharp polish ----
    try:
        for _ in range(100):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+all0'
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+all7'
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+pk0'
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+pk7'
    except Exception as e:
        print("polish loop failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if log_best is not None and log_bestR > start_bestR + 1e-13 and bestR <= start_bestR + 1e-13:
        return {"best": best, "alternative": log_best}
    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": log_best if log_best is not None else best}

import numpy as np
import time
import random
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_hinge(h, lam, eps):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    M = Lf[m]
    if M <= 0:
        return _fun_grad(h)
    K = Lf.size
    u = np.maximum((1.0 - eps) * M - Lf, 0.0) / M
    q = float(np.mean(u * u)) + 1e-12
    gLf = -dq / num
    gLf[m] += 1.0 / M
    du_dM = (1.0 - eps) / M - u / M
    dq_dM = float(np.mean(2.0 * u * du_dM))
    gLf[m] += (lam / q) * dq_dM
    gLf += -(2.0 * lam / (M * K * q)) * u
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M) + lam * np.log(q)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, hinge=None):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if hinge is not None:
        lam, eps = hinge
        fg = (lambda hh: _fun_grad_hinge(hh, lam, eps))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.1)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 0.0, 'gtol': 0.0})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _to_log(h):
    h = np.clip(h, 0, None)
    mx = h.max()
    if mx <= 0:
        return h
    return np.log(np.maximum(h, 1e-12 * mx))


def _from_log(z):
    return np.exp(np.clip(z, -40.0, 40.0))


def _burst(h0, rng, deadline):
    """One randomized burst. Returns (h_new, tag)."""
    space = 'log' if rng.random() < 0.5 else 'linear'
    obj_choice = rng.choice(['exact', '1e4', '1e5', '1e6', '1e7'])
    beta = 0.0 if obj_choice == 'exact' else float(obj_choice)
    use_hinge = rng.random() < 0.25
    if rng.random() < 0.5:
        free = np.arange(h0.size)
        win_tag = 'all'
    else:
        pad = rng.uniform(0.03, 0.6)
        extra = rng.choice([64, 512, 2048])
        free = _peak_window(h0, pad_frac=pad, extra=int(extra))
        win_tag = 'win(%.2f,%d)' % (pad, extra)

    hinge = None
    if use_hinge:
        lam = rng.uniform(0.01, 0.1)
        eps = rng.uniform(0.005, 0.05)
        hinge = (lam, eps)

    tag = '%s/%s/%s' % (space, obj_choice, win_tag)
    if hinge is not None:
        tag += '/hinge(%.3f,%.3f)' % hinge

    if space == 'log':
        z0 = _to_log(h0)
        # optimize in log space: parametrize h = exp(z) rescaled
        active = np.asarray(free, dtype=int)
        if active.size == 0:
            return h0, tag
        z = z0.copy()

        if hinge is not None:
            lam, eps = hinge
            fg = (lambda hh: _fun_grad_hinge(hh, lam, eps))
        elif beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

        def f(za):
            hh = _from_log(z)
            hh[active] = _from_log(za)
            hh = _rescale(hh)
            val, g = fg(hh)
            # chain through rescale: hh = raw/sqrt(mx); approx ignore rescale factor
            # gradient wrt z: g * h (since dh/dz = h)
            gz = g * hh
            return val, gz[active]

        cb = _make_cb(deadline - 0.1)
        try:
            res = minimize(f, z[active], jac=True, method='L-BFGS-B',
                           bounds=[(-40.0, 40.0)] * active.size,
                           callback=cb,
                           options={'maxiter': 150, 'maxfun': 300,
                                    'ftol': 0.0, 'gtol': 0.0})
            z[active] = res.x
        except (TimeoutError, Exception):
            pass
        h = _from_log(z)
        return _rescale(h), tag
    else:
        h = _lbfgs_block(h0, free, 150, deadline, beta=beta, hinge=hinge)
        return h, tag


def _symmetric_fold(h, deadline):
    """Mirror-average, polish, un-mirror."""
    n = h.size
    hm = 0.5 * (h + h[::-1])
    ht = _lbfgs_block(hm, np.arange(n), 150, deadline, beta=0.0)
    return ht


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    rng = random.Random(1234567)

    accepted = 0
    bursts = 0
    accepted_tags = []
    try:
        while time.process_time() < deadline - 0.6:
            bursts += 1
            burst_deadline = min(deadline - 0.5,
                                 time.process_time() + 3.5)
            try:
                if bursts % 5 == 0:
                    ht = _symmetric_fold(best, burst_deadline)
                    tag = 'symfold'
                else:
                    ht, tag = _burst(best, rng, burst_deadline)
            except Exception as e:
                print("burst failed: %s" % e)
                continue
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
                accepted += 1
                accepted_tags.append(tag)
                print("burst %d ACCEPT R=%.9f tag=%s" % (bursts, bestR, tag))
            if bursts % 4 == 0:
                print("burst %d: R=%.9f acc=%d" % (bursts, bestR, accepted))
    except Exception as e:
        print("main loop failed: %s" % e)

    # final exact polish
    try:
        if time.process_time() < deadline - 0.4:
            ht = _lbfgs_block(best, np.arange(best.size), 200,
                              deadline - 0.3, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                print("final polish R=%.9f" % bestR)
    except Exception:
        pass

    print("final R=%.7f accepted=%d/%d (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, accepted, bursts, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))
    if accepted_tags:
        print("accepted tags: " + " | ".join(accepted_tags[-12:]))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": start_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fg_hess(h, beta):
    s = h.sum()
    n = h.size
    if s <= 0:
        return 1e18, np.zeros(n), (lambda v: np.zeros(n))
    num, dq, Lf = _num_and_dq(h)
    K = Lf.size
    mx = Lf.max()
    if mx <= 0:
        v0, g0 = _fun_grad(h)
        return v0, g0, (lambda v: np.zeros(n))
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)

    mask = (h > 0).astype(float)

    def hessp(v):
        v = np.asarray(v, dtype=float)
        v = v * mask
        if n > 1500:
            c = fftconvolve(h, v)
        else:
            c = np.convolve(h, v)
        dLf = np.zeros(K)
        m = min(K, 2 * n - 1)
        dLf[:m] = 2.0 * c[:m]
        u = float(w @ dLf)
        dq2 = (4.0 * dLf) / 3.0
        dq2[1:] += dLf[:-1] / 3.0
        dq2[:-1] += dLf[1:] / 3.0
        diff = float(dq @ dLf)
        kv = -dq2 / num + diff * dq / (num * num)
        kv += beta * (w * (dLf - u)) / sm - w * u / (sm * sm)
        out = _backprop(kv, v) - 2.0 * v.sum() / (s * s)
        return out * mask

    return val, grad, hessp


def _fun_grad_hinge(h, lam, eps):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    M = Lf[m]
    if M <= 0:
        return _fun_grad(h)
    K = Lf.size
    u = np.maximum((1.0 - eps) * M - Lf, 0.0) / M
    q = float(np.mean(u * u)) + 1e-12
    gLf = -dq / num
    gLf[m] += 1.0 / M
    du_dM = (1.0 - eps) / M - u / M
    dq_dM = float(np.mean(2.0 * u * du_dM))
    gLf[m] += (lam / q) * dq_dM
    gLf += -(2.0 * lam / (M * K * q)) * u
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M) + lam * np.log(q)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tight=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    if tight:
        opts['ftol'] = 0.0
        opts['gtol'] = 0.0
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, hinge=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if hinge is not None:
        lam, eps = hinge
        fg = (lambda hh: _fun_grad_hinge(hh, lam, eps))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------------- Experiment: symmetric (mirror) parametrization ----------------

def _mirror(u):
    """Build full symmetric array of length 2*len(u) from half-array u."""
    m = u.size
    return np.concatenate((u, u[::-1]))


def _fold(h):
    """Fold a full array to its symmetric half: u_j = (h[j] + h[N-1-j])/2."""
    N = h.size
    m = N // 2
    u = 0.5 * (h[:m] + h[N - 1 - m:][::-1])
    return u


def _fun_grad_fold(u):
    h = _mirror(u)
    val, g = _fun_grad(h)
    N = h.size
    m = u.size
    gu = g[:m] + g[N - 1 - m:][::-1]
    return val, gu


def _fun_grad_fold_beta(u, beta):
    h = _mirror(u)
    val, g = _fun_grad_beta(h, beta)
    N = h.size
    m = u.size
    gu = g[:m] + g[N - 1 - m:][::-1]
    return val, gu


def _lbfgs_fold_all(u0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return u0
    u = np.clip(u0, 0, None)
    if u.sum() <= 0:
        return u0
    m = u.size
    if beta > 0:
        fg = (lambda uu: _fun_grad_fold_beta(uu, beta))
    else:
        fg = _fun_grad_fold

    def f(x):
        uu = np.clip(x, 0.0, None)
        val, g = fg(uu)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * m,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return u0
    if res is None:
        return u0
    return _rescale(_mirror(np.clip(res.x, 0.0, None)))[:m]


def _lbfgs_fold_block(u0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return u0
    u = np.clip(u0, 0, None)
    if u.sum() <= 0:
        return u0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return u0
    x0 = u[active].copy()
    if beta > 0:
        fg = (lambda uu: _fun_grad_fold_beta(uu, beta))
    else:
        fg = _fun_grad_fold

    def f(x):
        uu = u.copy()
        uu[active] = np.clip(x, 0.0, None)
        val, g = fg(uu)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return u0
    if res is None:
        return u0
    u2 = u.copy()
    u2[active] = np.clip(res.x, 0.0, None)
    return u2


def _fold_window(h, pad_frac, extra):
    """Peak window on full h, folded to half-index set."""
    win = _peak_window(h, pad_frac=pad_frac, extra=extra)
    N = h.size
    m = N // 2
    half = set()
    for i in win:
        if i < m:
            half.add(int(i))
        else:
            half.add(int(N - 1 - i))
    return np.array(sorted(half), dtype=int)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    sym_best = None
    sym_bestR = 0.0

    # ---- Experiment: symmetric (mirror) parametrization ----
    try:
        N = best.size
        if N % 2 == 1:
            # pad to even length by appending a zero
            best_pad = np.concatenate((best, [0.0]))
        else:
            best_pad = best.copy()
        u0 = _fold(best_pad)
        h_sym0 = _mirror(u0)
        R_fold0 = R_of(h_sym0)
        print("fold R=%.9f (start %.9f, delta %.2e)" %
              (R_fold0, start_bestR, R_fold0 - start_bestR))
        if R_fold0 > sym_bestR:
            sym_best, sym_bestR = h_sym0.copy(), R_fold0

        # (a) full L-BFGS-B on u, beta=0
        if time.process_time() < deadline - 4.0:
            u = _lbfgs_fold_all(u0, 800, deadline - 4.0, beta=0.0)
            h = _mirror(u)
            r = R_of(h)
            print("fold all beta=0: R=%.9f" % r)
            if r > sym_bestR + 1e-13:
                sym_best, sym_bestR = h.copy(), r
            u_cur = u
        else:
            u_cur = u0

        # (b) beta ladder on folded peak window
        for beta in (1e5, 1e6, 1e7):
            if time.process_time() >= deadline - 4.0:
                break
            win = _fold_window(_mirror(u_cur), pad_frac=0.25, extra=512)
            u = _lbfgs_fold_block(u_cur, win, 250, deadline - 4.0, beta=beta)
            h = _mirror(u)
            r = R_of(h)
            print("fold win beta=%.0e: R=%.9f" % (beta, r))
            if r > sym_bestR + 1e-13:
                sym_best, sym_bestR = h.copy(), r
            u_cur = u

        # (c) un-mirror and run base run_cycle on full array
        if sym_best is not None and time.process_time() < deadline - 6.0:
            h_un = sym_best.copy()
            if h_un.size != best.size:
                # trim/pad back to original length
                if h_un.size > best.size:
                    h_un = h_un[:best.size]
                else:
                    h_un = np.concatenate((h_un, np.zeros(best.size - h_un.size)))
            ht, rt = run_cycle(h_un, R_of(h_un), deadline - 6.0)
            print("fold+cycle R=%.9f" % rt)
            if rt > bestR + 1e-13:
                best, bestR = ht.copy(), rt
                origin = 'fold+cycle'
            if rt > sym_bestR + 1e-13:
                sym_best, sym_bestR = ht.copy(), rt
    except Exception as e:
        print("fold stage failed: %s" % e)

    # ---- Alpha-blend ladder: allow asymmetry ----
    try:
        h_start = start_best.copy()
        if sym_best is not None and sym_best.size == h_start.size:
            for alpha in (0.75, 0.5, 0.25):
                if time.process_time() >= deadline - 2.0:
                    break
                h_a = (1.0 - alpha) * sym_best + alpha * h_start
                h_a = _rescale(h_a)
                r0 = R_of(h_a)
                ht, rt = run_cycle(h_a, r0, deadline - 1.5)
                print("alpha=%.2f cycle: R=%.9f" % (alpha, rt))
                if rt > bestR + 1e-13:
                    best, bestR = ht.copy(), rt
                    origin = 'alpha%.2f+cycle' % alpha
    except Exception as e:
        print("alpha stage failed: %s" % e)

    # ---- Base's proven machinery on the best array ----
    if time.process_time() < deadline - 6.0:
        ht, rt = run_cycle(best, bestR, deadline - 6.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+cycle'
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Alternating polishes on best ----
    try:
        for _ in range(100):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+all0'
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+all7'
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+pk0'
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+pk7'
    except Exception as e:
        print("polish loop failed: %s" % e)

    # ---- Outer-window passes ----
    try:
        n = best.size
        k = min(2000, n // 4)
        if k > 0:
            outer = np.concatenate((np.arange(0, k), np.arange(n - k, n)))
            for beta in (0.0, 1e7):
                if time.process_time() >= deadline - 0.5:
                    break
                ht = _lbfgs_block(best, outer, 200, deadline - 0.5, beta=beta)
                r = R_of(ht)
                print("outer pass beta=%.0e: R=%.9f" % (beta, r))
                if r > bestR + 1e-13:
                    best, bestR = ht, r
                    origin = origin + '+outer%.0e' % beta
    except Exception as e:
        print("outer pass failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if sym_best is not None and sym_best.size == best.size and sym_bestR < bestR - 1e-13:
        return {"best": best, "alternative": sym_best}
    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": sym_best if sym_best is not None else best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_soft(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, free, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = np.clip(h[active], 0.0, None)

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    hard = t0 + budget_seconds * 0.96

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
        else:
            base = None
    else:
        base = None

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)

    best = base.copy()
    bestR = R_of(best)
    start_best = best.copy()
    start_bestR = bestR
    n = best.size
    print("base R=%.9f N=%d" % (bestR, best.size))

    # Key change: dense global polish over ALL coordinates first (start's
    # program only ran its coarse polish once and then cycled).  Then tighten
    # with a softmax ladder and repeated full-coordinate polish, since the
    # start was already a local optimum for the hard-max objective.  A
    # softmax(temperature) ladder smooths the L_inf term, letting the optimizer
    # escape the flat-top plateau that the hard max pins it to.
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 12.0)
        hf = _lbfgs(best, np.arange(n), 800, cap, _fun_grad)
        rf = R_of(hf)
        if rf > bestR:
            best, bestR = hf, rf
        print("dense -> %.9f" % bestR)

    # Softmax ladder over ALL coordinates, several temperatures.
    for beta in (1e2, 3e2, 1e3, 3e3, 1e4, 3e4, 1e5, 3e5):
        if time.process_time() >= deadline - 1.0:
            break
        cap = min(deadline - 0.5, time.process_time() + 5.0)
        fg = (lambda hh, b=beta: _fun_grad_soft(hh, b))
        hb = _lbfgs(best, np.arange(n), 300, cap, fg)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
            print("soft beta=%.0e -> %.9f" % (beta, rb))

    # Repeated dense + peak-window polish until no gain.
    cycle = 0
    while time.process_time() < deadline - 1.0:
        cycle += 1
        prev = bestR
        cap = min(deadline - 0.5, time.process_time() + 4.0)
        hf = _lbfgs(best, np.arange(n), 400, cap, _fun_grad)
        rf = R_of(hf)
        if rf > bestR:
            best, bestR = hf, rf
        for frac in (0.04, 0.08, 0.15, 0.30):
            if time.process_time() >= deadline - 1.0:
                break
            free = _peak_window(best, frac)
            cap = min(deadline - 0.5, time.process_time() + 2.5)
            hp = _lbfgs(best, free, 200, cap, _fun_grad)
            rp = R_of(hp)
            if rp > bestR:
                best, bestR = hp, rp
        if bestR <= prev + 1e-13:
            break
        print("cycle %d -> %.9f" % (cycle, bestR))

    if time.process_time() < hard - 1.0:
        cap = min(hard - 0.5, time.process_time() + 2.0)
        hf = _lbfgs(best, np.arange(n), 200, cap, _fun_grad)
        rf = R_of(hf)
        if rf > bestR:
            best, bestR = hf, rf

    print("final R=%.9f N=%d" % (bestR, best.size))
    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    return {"best": start_best, "alternative": best}

