    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0, 0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0, 0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 3 * maxiter,
            'ftol': 0.0, 'gtol': 0.0}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0, -1
    if res is None:
        return h0, -1
    return _rescale(np.clip(res.x, 0.0, None)), int(res.nit)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0, 0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0, 0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0, 0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 3 * maxiter,
                                'ftol': 0.0, 'gtol': 0.0})
    except (TimeoutError, Exception):
        return h0, -1
    if res is None:
        return h0, -1
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2), int(res.nit)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    work = start_best.copy()
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    def _consider(ht, tag, nit):
        nonlocal work, best, bestR, origin
        r = R_of(ht)
        print("stage %s: nit=%d R=%.9f" % (tag, nit, r))
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = tag
        else:
            work = ht

    # Stage 1: one long full beta=0 descent.
    if time.process_time() < deadline - 0.5:
        ht, nit = _lbfgs_all_pos(work, 20000, deadline - 0.3, beta=0.0)
        _consider(ht, "long_all0", nit)

    # Stage 2: one long peak-window block at beta=1e7.
    if time.process_time() < deadline - 0.5:
        win = _peak_window(work, pad_frac=0.20, extra=256)
        ht, nit = _lbfgs_block(work, win, 20000, deadline - 0.3, beta=1e7)
        _consider(ht, "long_pk0.20", nit)

    # Stage 3: another long full beta=0 descent.
    if time.process_time() < deadline - 0.5:
        ht, nit = _lbfgs_all_pos(work, 20000, deadline - 0.3, beta=0.0)
        _consider(ht, "long_all0_b", nit)

    # Stage 4: optional single pad=0.12 window block if time remains.
    if time.process_time() < deadline - 6.0:
        win = _peak_window(work, pad_frac=0.12, extra=128)
        ht, nit = _lbfgs_block(work, win, 20000, deadline - 0.3, beta=1e7)
        _consider(ht, "long_pk0.12", nit)

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    if work is not None and work.size == start_best.size:
        return {"best": best, "alternative": work}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tight=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    if tight:
        opts['ftol'] = 0.0
        opts['gtol'] = 0.0
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


# ---------- Key new idea: knot-flip / rebalance "gradient mode" ----------
# Coordinate-wise exact-ish move: for each index i, we can compute dR/dh_i
# analytically cheaply from the knot values, then do a *projected* step
# that is allowed to zero out entries. This flips zeros <-> positive in
# a way L-BFGS-B rarely does (it stalls at active-set boundaries).

def _knot_grad(h):
    """Return per-height gradient of log R using knot representation."""
    s = h.sum()
    if s <= 0:
        return None
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _coordinate_sweep(h, n_sweeps, deadline):
    """Greedy coordinate-wise moves with adaptive step. Can flip zeros."""
    h = np.clip(h, 0, None).astype(float)
    if h.sum() <= 0:
        return h
    n = h.size
    for _ in range(n_sweeps):
        if time.process_time() >= deadline - 0.5:
            break
        g = _knot_grad(h)
        if g is None:
            break
        # hill-climb: try moving each coordinate in direction -g (R increases
        # since we minimize -log R, so moving h_i by -g_i * step)
        # Use a cheap step: scale by mean magnitude
        scale = max(1e-12, np.mean(np.abs(h)))
        # Only touch coordinates with large |g| relative to typical
        thresh = np.percentile(np.abs(g), 90.0)
        idx = np.flatnonzero(np.abs(g) >= thresh)
        improved = False
        base = R_of(h)
        step0 = 0.01 * scale
        for i in idx:
            best_delta = 0.0
            best_r = base
            for mult in (1.0, 0.3, 3.0, 10.0, 0.1):
                delta = -step0 * mult * g[i] / max(1e-12, np.abs(g[i]))
                delta = -step0 * mult * np.sign(g[i])
                nh = h[i] + delta
                if nh < 0:
                    nh = 0.0
                if nh == h[i]:
                    continue
                h[i] = nh
                r = R_of(h)
                if r > best_r + 1e-14:
                    best_r = r
                    best_delta = delta
                h[i] -= delta
            if best_delta != 0.0:
                h[i] = max(0.0, h[i] + best_delta)
                improved = True
        if not improved:
            break
    return _rescale(h)


def _zero_flip_sweep(h, deadline, n_tries=200):
    """Randomly zero-out small entries and try to recover with L-BFGS."""
    h = _rescale(np.clip(h, 0, None))
    if h.sum() <= 0:
        return h
    best = h.copy()
    bestR = R_of(best)
    rng = np.random.default_rng(12345)
    n = h.size
    for _ in range(n_tries):
        if time.process_time() >= deadline - 1.0:
            break
        hh = best.copy()
        # pick a small-magnitude region and zero it
        k = rng.integers(1, max(2, n // 200))
        start_i = rng.integers(0, max(1, n - k))
        hh[start_i:start_i + k] = 0.0
        # small perturbation to escape
        hh += rng.normal(0, 1e-4 * hh.mean() + 1e-12, size=n)
        hh = np.clip(hh, 0, None)
        hh = _lbfgs_all_pos(hh, 200, deadline - 0.5, beta=0.0)
        r = R_of(hh)
        if r > bestR + 1e-13:
            best, bestR = hh, r
    return best


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ==== NEW: coordinate-wise sweep that can flip zeros ====
    try:
        if time.process_time() < deadline - 10.0:
            hc = _coordinate_sweep(best, 3, deadline - 10.0)
            rc = R_of(hc)
            print("coord sweep R=%.9f (delta %.2e)" % (rc, rc - bestR))
            if rc > bestR + 1e-13:
                best, bestR = hc, rc
                origin = 'coord'
    except Exception as e:
        print("coord sweep failed: %s" % e)

    # ==== NEW: zero-flip random perturbations + reoptimize ====
    try:
        if time.process_time() < deadline - 20.0:
            hz = _zero_flip_sweep(best, deadline - 15.0, n_tries=60)
            rz = R_of(hz)
            print("zero-flip R=%.9f (delta %.2e)" % (rz, rz - bestR))
            if rz > bestR + 1e-13:
                best, bestR = hz, rz
                origin = origin + '+zflip'
    except Exception as e:
        print("zero-flip failed: %s" % e)

    # ==== base cycle ====
    if time.process_time() < deadline - 8.0:
        ht, rt = run_cycle(best, bestR, deadline - 8.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+cycle'
        print("cycle R=%.7f" % bestR)

    # ==== alternating polish with coordinate sweeps interleaved ====
    try:
        for it in range(200):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+all0'
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+all7'
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+pk0'
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+pk7'
            # occasional coordinate sweep to escape L-BFGS stalls
            if (it % 3 == 2) and time.process_time() < deadline - 2.0:
                hc = _coordinate_sweep(best, 1, deadline - 1.5)
                rc = R_of(hc)
                if rc > bestR + 1e-13:
                    best, bestR = hc, rc
                    origin = origin + '+cs'
    except Exception as e:
        print("polish loop failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

