        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolong(h, N1):
    """Resample step function h (uniform widths) to N1 steps, preserving integral."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    if n == N1:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N1) / N1
    tgt = np.linspace(0.0, total, N1 + 1)
    idx = np.searchsorted(c, tgt, side='right') - 1
    idx = np.clip(idx, 0, n - 1)
    out = h[idx].copy()
    s = out.sum()
    if s > 0:
        out *= total / s
    return out


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 600, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.15, 128, 1e8), (0.35, 256, 1e8),
              (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: prolongation ladder - refine at increasing resolution.
    # This is the main new idea: search on a coarse grid (fast), then
    # prolong to finer grid and polish. Lets finer detail emerge cheaply.
    N0 = best.size
    levels = [N0]
    if N0 < 40000:
        levels.append(min(40000, N0 * 3))
    if N0 < 200000 and levels[-1] < 200000:
        levels.append(200000)

    for li, N in enumerate(levels):
        now = time.process_time()
        if now >= deadline - 3.0:
            break
        # allocate time proportionally: coarser levels get less
        frac = 0.20 if li == 0 else (0.30 if li == 1 else 0.45)
        rung_dl = min(deadline - 3.0, now + (deadline - 3.0 - now) * frac)
        h = _prolong(best, N) if N != best.size else best.copy()
        hR = R_of(h)
        if hR >= bestR - 1e-9:
            best, bestR = h, hR
        best, bestR = run_cycle(best, bestR, rung_dl)
        print("level N=%d R=%.7f" % (best.size, bestR))

    # Phase 2: continuous polishing at final resolution until deadline.
    stall = 0
    while time.process_time() < deadline - 1.5 and stall < 4:
        prev = bestR
        best, bestR = run_cycle(best, bestR, deadline - 1.5)
        if bestR - prev < 5e-10:
            stall += 1
        else:
            stall = 0

    # Final push: high-beta peak sharpening + full polish.
    if time.process_time() < deadline - 0.8:
        win = _peak_window(best, tol=0.95, pad_frac=0.5, extra=1024)
        ht = _lbfgs_block(best, win, maxiter=400, deadline=deadline - 0.6,
                          beta=1e8)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_band(h, delta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    B = Lf >= (1.0 - delta) * mx
    nB = int(B.sum())
    if nB == 0:
        return _fun_grad(h)
    Lb = Lf[B]
    Lb_safe = np.clip(Lb, 1e-300, None)
    val = -np.log(num) + 2.0 * np.log(s) + np.mean(np.log(Lb_safe))
    gLf = -dq / num
    gLf[B] += (1.0 / nB) / Lb_safe
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _fun_grad_band_down(h, delta, lam):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    B = Lf >= (1.0 - delta) * mx
    nB = int(B.sum())
    if nB == 0:
        return _fun_grad(h)
    T = Lf[B].mean()
    r = (Lf[B] - T) / mx
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + lam * np.mean(r * r)
    gLf = -dq / num
    m = int(np.argmax(Lf))
    gLf[m] += 1.0 / mx
    gLf[B] += lam * 2.0 * r / (nB * mx)
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_log_band_down(h0, maxiter, deadline, delta, lam):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_band_down(hh, delta, lam)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _report(tag, h, delta):
    Lf = _knots(h)
    mx = Lf.max()
    s = h.sum()
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    B = Lf >= (1.0 - delta) * mx
    nB = int(B.sum())
    bmean = float(Lf[B].mean() / mx) if nB else 0.0
    r = R_of(h)
    print("  %s R=%.7f mx=%.6f num=%.6f |B|=%d mean/max=%.5f" %
          (tag, r, mx, num, nB, bmean))
    return r


# ---------------------------------------------------------------------------
# NEW: shape-gradient / symmetry analysis + high-resolution reparametrisation
# ---------------------------------------------------------------------------

def _interp_resample(h, N):
    """Resample heights to N points via cumulative-mass interpolation."""
    n = h.size
    if n == N:
        return h.copy()
    # cumulative integral of h (piecewise constant on unit steps)
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    # new cumulative at equally spaced points scaled to same total
    xs = np.linspace(0.0, n, N + 1)
    cs = np.interp(xs, np.arange(n + 1, dtype=float), c)
    out = np.diff(cs)
    out = np.clip(out, 0, None)
    if out.sum() <= 0:
        return np.ones(N)
    return out * (total / out.sum())


def _upsample(h, factor):
    """Refine heights by linear (in t) interpolation, factor times more steps."""
    n = h.size
    N = n * factor
    # treat h as samples of a continuous envelope; upscale via cumulative
    return _interp_resample(h, N)


def _rebalance_peak(h, deadline, rounds, delta=0.02, lam=1.0):
    """Apply band-down + sharp alternating polish repeatedly."""
    cur = h
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        hd = _lbfgs_log_band_down(cur, 100, deadline, delta, lam)
        hs = _lbfgs_log(hd, 12, deadline)
        if R_of(hs) >= R_of(cur) - 1e-14:
            cur = hs
        else:
            cur = hs if R_of(hs) > R_of(cur) else cur
    return cur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    best = None
    bestR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    # NEW: work at a higher resolution than the start, so the search has
    # more degrees of freedom to smooth the flat top and shape the tails.
    N0 = best.size
    if N0 < 60000:
        targetN = min(60000, max(N0 + 1, int(N0 * 1.5)))
        refined = _upsample(best, 2)
        if refined.size > targetN:
            refined = _interp_resample(refined, targetN)
        refinedR = R_of(refined)
        print("refined R=%.7f (N=%d)" % (refinedR, refined.size))
        if refinedR >= bestR - 1e-12:
            best = refined
            bestR = refinedR

    cur = best.copy()
    curR = bestR

    # Main loop: alternate band-down (flatten the near-max plateau) with
    # sharp polish, and periodically re-refine resolution.
    schedule = [(0.03, 1.0), (0.05, 3.0), (0.02, 1.5), (0.08, 5.0)]
    pass_no = 0
    while time.process_time() < deadline - 2.0:
        pass_no += 1
        for (delta, lam) in schedule:
            if time.process_time() >= deadline - 2.0:
                break
            hd = _lbfgs_log_band_down(cur, 100, deadline, delta, lam)
            if time.process_time() < deadline - 1.5:
                hs = _lbfgs_log(hd, 12, deadline)
            else:
                hs = hd
            if time.process_time() < deadline - 1.0:
                hp = _window_polish_peak(hs, deadline, 0.10, 32, maxiter=100)
            else:
                hp = hs
            rp = R_of(hp)
            if rp > curR + 3e-13:
                cur, curR = hp, rp
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
                    print("  pass %d NEW BEST R=%.7f" % (pass_no, bestR))
        # NEW: occasionally try a finer resolution to escape local optimum
        if pass_no % 2 == 0 and best.size < 90000 and \
                time.process_time() < deadline - 5.0:
            bigger = _upsample(best, 2)
            if bigger.size <= 100000:
                rb = R_of(bigger)
                if rb >= bestR - 1e-10:
                    cur = bigger
                    curR = rb
                    print("  pass %d upsample to N=%d R=%.7f" %
                          (pass_no, bigger.size, rb))
        print("  pass %d R=%.7f N=%d" % (pass_no, curR, cur.size))

    # Final sharp polish at best resolution
    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 200, deadline)
        rf = R_of(hf)
        _report("final", hf, 0.05)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _edge_extend(h, K, rho, side='both'):
    """Add geometric decay tails beyond outermost active cells."""
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return h
    thr = 1e-9 * mx
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return h
    i0 = int(idx.min()); i1 = int(idx.max())
    hL = h[i0]; hR = h[i1]
    do_left = side in ('both', 'left')
    do_right = side in ('both', 'right')
    for k in range(1, K + 1):
        if do_left and i0 - k >= 0 and h[i0 - k] == 0.0:
            h[i0 - k] = hL * (rho ** k)
        if do_right and i1 + k < n and h[i1 + k] == 0.0:
            h[i1 + k] = hR * (rho ** k)
    return _rescale(h)


def _support(h):
    mx = h.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(h > 1e-9 * mx)
    if idx.size == 0:
        return 0, h.size - 1
    return int(idx.min()), int(idx.max())


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    """p1233's beta ladder + pad schedule on `work`."""
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    reserve = 8.0

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Baseline cycle on the unextended start.
    work0, best0, bestR0, origin0 = _run_cycle(
        start_best.copy(), best.copy(), bestR, deadline - reserve, 'base')
    if bestR0 > bestR + 1e-14:
        best, bestR, origin = best0, bestR0, origin0
    print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    alt_best = None
    alt_bestR = -1.0

    # Iterative extend -> polish rounds, feeding best back as next input.
    for rnd in range(3):
        if time.process_time() >= deadline - reserve - 1.0:
            break
        K = 2048 * (rnd + 1)
        rhos = [0.99, 0.995, 0.999]
        i0, i1 = _support(best)
        print("round %d: input i0=%d i1=%d R=%.9f" % (rnd, i0, i1, bestR))
        round_best = best.copy()
        round_bestR = bestR
        round_origin = origin
        # two-sided variants
        for rho in rhos:
            if time.process_time() >= deadline - reserve - 0.5:
                break
            ext = _edge_extend(best, K, rho, side='both')
            r_ext = R_of(ext)
            w, b, br, org = _run_cycle(
                ext, ext.copy(), r_ext, deadline - reserve,
                'r%d_b_%g' % (rnd, rho),
                tag='r%d_b%g_' % (rnd, rho))
            if br > round_bestR + 1e-14:
                round_best, round_bestR, round_origin = b, br, org
            if br > alt_bestR and br < bestR - 1e-14:
                alt_best, alt_bestR = b, br
        # one-sided variants
        for side in ('left', 'right'):
            if time.process_time() >= deadline - reserve - 0.5:
                break
            ext = _edge_extend(best, K, 0.995, side=side)
            r_ext = R_of(ext)
            w, b, br, org = _run_cycle(
                ext, ext.copy(), r_ext, deadline - reserve,
                'r%d_%s' % (rnd, side),
                tag='r%d_%s_' % (rnd, side))
            if br > round_bestR + 1e-14:
                round_best, round_bestR, round_origin = b, br, org
            if br > alt_bestR and br < bestR - 1e-14:
                alt_best, alt_bestR = b, br
        if round_bestR > bestR + 1e-14:
            best, bestR, origin = round_best, round_bestR, round_origin
        j0, j1 = _support(best)
        print("round %d: out i0=%d i1=%d best R=%.9f origin=%s" %
              (rnd, j0, j1, bestR, origin))

    # Reserve: one full beta=1e7 pass + one pad-window polish on overall best.
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht, r, origin + '+fin_b'
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.15, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2, r2, origin + '+fin_pk'

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    if bestR > start_bestR + 1e-12:
        if alt_best is not None and alt_best.size == best.size:
            return {"best": best, "alternative": alt_best}
        return best
    if alt_best is not None and alt_best.size == start_best.size:
        return {"best": best, "alternative": alt_best}
    return best

import numpy as np
