    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolong(h, N1):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    if n == N1:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N1) / N1
    tgt = np.linspace(0.0, total, N1 + 1)
    idx = np.searchsorted(c, tgt, side='right') - 1
    idx = np.clip(idx, 0, n - 1)
    out = h[idx].copy()
    s = out.sum()
    if s > 0:
        out *= total / s
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    cur = start_best.copy()
    curR = start_bestR

    # Phase 1: heavy refinement on the given start (its own N), sharpening
    # the peak with increasing beta so we converge to a true single-max shape.
    betas = [1e4, 1e5, 1e6, 1e7, 1e8]
    cyc = 0
    while time.process_time() < deadline - 8.0:
        cyc += 1
        r_before = curR
        for b in betas:
            if time.process_time() >= deadline - 8.0:
                break
            hb = _lbfgs_all_pos(cur, 200, deadline, beta=b)
            rb = R_of(hb)
            if rb > curR + 1e-14:
                cur, curR = hb, rb
        # unconstrained polish
        hs = _lbfgs_all_pos(cur, 300, deadline)
        rs = R_of(hs)
        if rs > curR + 1e-14:
            cur, curR = hs, rs
        # local window polish around peak
        free = _peak_window(cur, tol=0.9999, pad_frac=0.5, extra=512)
        hw = _lbfgs_block(cur, free, 300, deadline, beta=1e8)
        rw = R_of(hw)
        if rw > curR + 1e-14:
            cur, curR = hw, rw
        hw2 = _lbfgs_block(cur, free, 300, deadline)
        rw2 = R_of(hw2)
        if rw2 > curR + 1e-14:
            cur, curR = hw2, rw2

        if curR > bestR + 1e-14:
            best, bestR = cur.copy(), curR
        print("phase1 cyc %d R %.7f->%.7f (zeros %.1f%%)"
              % (cyc, r_before, curR, 100.0 * np.mean(cur <= 0)))
        if curR - r_before < 1e-12:
            break

    # Phase 2: try doubling resolution and re-refining — more degrees of
    # freedom may allow a sharper peak / better plateau.
    while time.process_time() < deadline - 3.0:
        n0 = best.size
        if n0 * 2 > 1000000:
            break
        N1 = min(n0 * 2, 1000000)
        hi = _prolong(best, N1)
        hi = _rescale(hi)
        r_hi0 = R_of(hi)
        # refine at higher resolution
        for b in [1e5, 1e6, 1e7, 1e8]:
            if time.process_time() >= deadline - 3.0:
                break
            hb = _lbfgs_all_pos(hi, 200, deadline, beta=b)
            rb = R_of(hb)
            if rb > r_hi0:
                hi, r_hi0 = hb, rb
        hs = _lbfgs_all_pos(hi, 300, deadline)
        rs = R_of(hs)
        if rs > r_hi0:
            hi, r_hi0 = hs, rs
        free = _peak_window(hi, tol=0.9999, pad_frac=0.5, extra=1024)
        hw = _lbfgs_block(hi, free, 300, deadline, beta=1e8)
        rw = R_of(hw)
        if rw > r_hi0:
            hi, r_hi0 = hw, rw
        print("phase2 N %d->%d R %.7f (was %.7f)"
              % (n0, N1, r_hi0, bestR))
        if r_hi0 > bestR + 1e-13:
            best, bestR = hi, r_hi0
            cur, curR = hi.copy(), r_hi0
        else:
            break

    # Final polish
    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_all_pos(best, 300, deadline, beta=1e8)
        rf = R_of(hf)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf
        free = _peak_window(best, tol=0.99999, pad_frac=0.3, extra=256)
        hw = _lbfgs_block(best, free, 300, deadline)
        rw = R_of(hw)
        if rw > bestR + 1e-14:
            best, bestR = hw, rw

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _support_bounds(h):
    mx = h.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(h > 1e-9 * mx)
    if idx.size == 0:
        return 0, h.size - 1
    return int(idx.min()), int(idx.max())


def _repair(h, touched, deadline, beta=1e7):
    """Cheap repair: window polish around touched index, then global if improved."""
    n = h.size
    lo = max(0, touched - 192)
    hi = min(n - 1, touched + 192)
    win = np.arange(lo, hi + 1)
    r0 = R_of(h)
    ht = _lbfgs_block(h, win, 150, deadline - 0.3, beta=beta)
    r1 = R_of(ht)
    if r1 > r0 + 1e-14:
        ht2 = _lbfgs_all_pos(ht, 100, deadline - 0.3, beta=0.0)
        r2 = R_of(ht2)
        if r2 > r1:
            return ht2, r2
        return ht, r1
    return h, r0


def _enumerate_hops(h, deadline):
    """Yield (candidate_h, touched_index, kind) cheap combinatorial moves."""
    n = h.size
    mx = h.max()
    if mx <= 0:
        return
    mean = h.mean()
    pos = np.flatnonzero(h > 1e-12 * mx)
    zero_mask = h <= 1e-12 * mx

    # Splits: top 24 positive cells, move fraction into a zero neighbour.
    if pos.size > 0:
        top = pos[np.argsort(-h[pos])[:24]]
        for i in top:
            hi_val = h[i]
            for j in (i - 1, i + 1):
                if 0 <= j < n and zero_mask[j]:
                    for f in (0.25, 0.5, 0.75):
                        hc = h.copy()
                        move = f * hi_val
                        hc[i] = hi_val - move
                        hc[j] = move
                        yield _rescale(hc), int(i), "split"
                        if time.process_time() > deadline:
                            return

    # Merges: adjacent positive pairs, 24 smallest sums, add both into i.
    if pos.size > 1:
        pairs = []
        for i in pos:
            if i + 1 < n and h[i + 1] > 1e-12 * mx:
                pairs.append((h[i] + h[i + 1], int(i)))
        pairs.sort()
        for _, i in pairs[:24]:
            hc = h.copy()
            hc[i] = h[i] + h[i + 1]
            hc[i + 1] = 0.0
            yield _rescale(hc), int(i), "merge"
            if time.process_time() > deadline:
                return

    # Births: 8 largest-gradient zero cells.
    try:
        _, g = _fun_grad(h)
    except Exception:
        return
    zero_idx = np.flatnonzero(zero_mask)
    if zero_idx.size > 0:
        gz = g[zero_idx]
        order = np.argsort(-np.abs(gz))[:8]
        for k in order:
            j = int(zero_idx[k])
            hc = h.copy()
            hc[j] = 1e-3 * mean
            yield _rescale(hc), j, "birth"
            if time.process_time() > deadline:
                return


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    hop_deadline = deadline - 6.0

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Combinatorial accept-only hop loop.
    work = best.copy()
    workR = bestR
    hop_count = 0
    accepted = 0
    while time.process_time() < hop_deadline:
        improved_this_round = False
        for cand, touched, kind in _enumerate_hops(work, hop_deadline):
            if time.process_time() >= hop_deadline:
                break
            hc, rc = _repair(cand, touched, deadline)
            if rc > workR + 1e-12:
                delta = rc - workR
                work, workR = hc, rc
                accepted += 1
                improved_this_round = True
                i0, i1 = _support_bounds(work)
                zf = 100.0 * np.mean(work <= 1e-12 * work.max())
                print("hop %s: dR=%.2e R=%.9f zeros=%.1f%% sup=[%d,%d]" %
                      (kind, delta, workR, zf, i0, i1))
                if workR > bestR + 1e-14:
                    best, bestR, origin = work.copy(), workR, "hop_" + kind
                break  # restart enumeration from new work
        hop_count += 1
        if not improved_this_round:
            break

    print("hops: accepted=%d R=%.9f (start %.9f)" %
          (accepted, bestR, start_bestR))

    # Final polish with p1243's cycle.
    if time.process_time() < deadline - 0.5:
        w, b, br, org = _run_cycle(best.copy(), best.copy(), bestR,
                                   deadline, 'final', tag='f_')
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return best

