        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _active_span(h):
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return 0, 0
    return int(nz.min()), int(nz.max())


def _edge_extend_geom(h, side, K, rho):
    """Geometric continuation beyond outermost active cells on given side(s)."""
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    i0, i1 = _active_span(h)
    if h[i0] <= 0 or h[i1] <= 0:
        return h
    hL = h[i0]; hR = h[i1]
    if side in ('left', 'both'):
        for k in range(1, K + 1):
            j = i0 - k
            if j < 0:
                break
            if h[j] == 0.0:
                h[j] = hL * (rho ** k)
    if side in ('right', 'both'):
        for k in range(1, K + 1):
            j = i1 + k
            if j >= n:
                break
            if h[j] == 0.0:
                h[j] = hR * (rho ** k)
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    trials = [
        ('left', 2048, 0.995),
        ('left', 4096, 0.999),
        ('both', 2048, 0.99),
        ('both', 4096, 0.9995),
        ('right', 2048, 0.995),
    ]

    for (side, K, rho) in trials:
        if time.process_time() >= deadline - 2.0:
            break
        trial_deadline = min(deadline - 0.5,
                             time.process_time() + 8.0)
        i0a, i1a = _active_span(best)
        ext = _edge_extend_geom(best, side, K, rho)
        r_ext = R_of(ext)
        i0b, i1b = _active_span(ext)

        # cheap polish: peak-window beta block, then one all-pos beta=0 pass
        if time.process_time() < trial_deadline - 1.0:
            win = _peak_window(ext, pad_frac=0.30, extra=128)
            ht = _lbfgs_block(ext, win, 200, trial_deadline, beta=1e7)
            r1 = R_of(ht)
            if r1 > r_ext:
                ext, r_ext = ht, r1
        if time.process_time() < trial_deadline - 0.5:
            ht2 = _lbfgs_all_pos(ext, 100, trial_deadline, beta=0.0)
            r2 = R_of(ht2)
            if r2 > r_ext:
                ext, r_ext = ht2, r2

        i0c, i1c = _active_span(ext)
        print("edge side=%s K=%d rho=%g: span %d..%d -> %d..%d R=%.9f"
              % (side, K, rho, i0a, i1a, i0c, i1c, r_ext))

        if r_ext > bestR + 1e-14:
            best, bestR = ext, r_ext
            origin = 'edge_%s_%d_%g' % (side, K, rho)
            print("edge NEW BEST R=%.9f" % bestR)
        elif r_ext > alt_bestR and r_ext > start_bestR + 1e-14:
            alt_best, alt_bestR = ext, r_ext

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _densify(h, c):
    dense = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    act = dense > 0
    if not np.any(act):
        return dense
    lvl = c * dense[act].mean()
    dense[~act] = lvl
    return _rescale(dense)


def _densify_ladder(dense, deadline, tag=""):
    work = dense.copy()
    best = dense.copy()
    bestR = R_of(dense)
    origin = tag + "seed"
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 1.0:
            break
        ht = _lbfgs_all_pos(work, 120, deadline - 1.0, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    for it, pad in enumerate([0.30, 0.15, 0.08]):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 150, deadline - 1.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
    if time.process_time() < deadline - 1.0:
        ht2 = _lbfgs_all_pos(work, 80, deadline - 1.0, beta=0.0)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            work, best, bestR = ht2, ht2.copy(), r2
            origin = "%sall0" % tag
    return work, best, bestR, origin


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_bestR = bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # (2) one cheap peak-window polish
    if time.process_time() < deadline - 1.0:
        win = _peak_window(best, pad_frac=0.30, extra=128)
        ht = _lbfgs_block(best, win, 200, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
            origin = 'pk0'
        print("peak polish: R=%.9f origin=%s" % (bestR, origin))

    # (3) densification sweep
    for c in [0.001, 0.005, 0.02, 0.05]:
        if time.process_time() >= deadline - 2.0:
            break
        branch_deadline = min(deadline - 0.5, time.process_time() + 10.0)
        dense = _densify(best, c)
        r0 = R_of(dense)
        nz0 = int(np.sum(dense == 0))
        zf0 = nz0 / float(dense.size)
        w, b, br, org = _densify_ladder(dense, branch_deadline,
                                        tag='dens%g' % c)
        nz = int(np.sum(b == 0))
        zf = nz / float(b.size)
        print("dens c=%g: seed R=%.9f zeros=%.4f -> R=%.9f zeros=%.4f origin=%s"
              % (c, r0, zf0, br, zf, org))
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("dens c=%g NEW BEST R=%.9f" % (c, bestR))
        elif br > alt_bestR and br > start_bestR + 1e-14:
            alt_best, alt_bestR = b, br

    # If time remains, run a short baseline cycle on the best
    if time.process_time() < deadline - 2.0:
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(best, 200, deadline - 0.5, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
                origin = 'tailbeta%g' % beta
        if time.process_time() < deadline - 1.0:
            ht = _lbfgs_all_pos(best, 150, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
                origin = 'tailall0'

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

