def _prolong(h, N1):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    if n == N1:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N1) / N1
    tgt = np.linspace(0.0, total, N1 + 1)
    idx = np.searchsorted(c, tgt, side='right') - 1
    idx = np.clip(idx, 0, n - 1)
    out = h[idx].copy()
    s = out.sum()
    if s > 0:
        out *= total / s
    return out


def _refine(h, deadline, bestR):
    """Coordinate-ascent on individual heights: for each index, try scaling
    a small group of entries by a factor chosen by 1-D search. Cheap, direct,
    and complements the gradient polishing."""
    n = h.size
    h = h.copy()
    Rcur = R_of(h)
    factors = np.array([0.85, 0.92, 0.97, 1.0, 1.03, 1.08, 1.15])
    improved = True
    passes = 0
    while improved and passes < 6:
        improved = False
        passes += 1
        order = np.argsort(-h)
        for i in order:
            if time.process_time() > deadline:
                return h, Rcur
            if h[i] <= 0:
                continue
            base = h[i]
            bestf = 1.0
            bestRl = Rcur
            for f in factors:
                if f == 1.0:
                    continue
                h[i] = base * f
                r = R_of(h)
                if r > bestRl:
                    bestRl = r
                    bestf = f
            h[i] = base * bestf
            if bestRl > Rcur + 1e-15:
                Rcur = bestRl
                improved = True
    return _rescale(h), R_of(_rescale(h))


