            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    work = start_best.copy()

    # Phase A: full-array beta polish.
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "beta%g" % beta
        print("beta%g: R=%.9f" % (beta, r))

    # Phase B: interior block beta-continuation polish on positive indices.
    free = np.flatnonzero(work > 0)
    if free.size == 0:
        free = np.arange(work.size)
    for beta in [1e4, 1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_block(work, free, 200, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "int%g" % beta
        print("int beta%g: R=%.9f" % (beta, r))

    # Phase B(b): sharp beta=0 polish.
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(work, 400, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "sharp0"
        print("sharp0: R=%.9f" % r)

    # Phase C: peak-window pad cycle.
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "pk%d" % it
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "pk%d+all0" % it
        print("cycle %d pad=%.2f: R=%.9f" % (it, pad, bestR))

    # Phase D (new): direct coordinate-wise multiplicative refinement of the
    # current best. This is a different search direction from L-BFGS gradient
    # steps and squeezes out residual gains along individual heights.
    if time.process_time() < deadline - 1.0:
        hd, rd = _refine(work, deadline - 0.5, bestR)
        if rd > bestR + 1e-14:
            work, best, bestR = hd, hd.copy(), rd
            origin = origin + "+refine"
        print("refine: R=%.9f" % rd)
        # polish after refinement
        if time.process_time() < deadline - 0.6:
            ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
                origin = origin + "+rfin"
            print("rfin: R=%.9f" % r)

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    if work is not None and work.size == start_best.size:
        return {"best": best, "alternative": work}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


# -------- New core idea: graded refinement of the peak region ----------
# Instead of interpolating a window by an integer factor (which duplicates
# resolution everywhere), we refine only the peak neighbourhood by inserting
# knots at midpoints and initialising new heights by linear interpolation.
# The peak region of f*f is where the binding constraint sits, so extra
# resolution there lets the optimizer lower ||f*f||_inf without paying
# the ||f*f||_2^2 cost of a coarser shoulder.  We drive this with a short
# beta-polish, then run full-array L-BFGS.

def _refine_segment(h, lo, hi):
    """Insert midpoint knots in h[lo:hi+1] by linear interpolation."""
    seg = h[lo:hi + 1]
    m = seg.size
    if m < 2:
        return h, lo, hi
    new_seg = np.empty(2 * m - 1)
    new_seg[0::2] = seg
    new_seg[1::2] = 0.5 * (seg[:-1] + seg[1:])
    out = np.concatenate((h[:lo], new_seg, h[hi + 1:]))
    return out, lo, lo + new_seg.size - 1


def _peak_h_window(h, frac):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= 0.95 * mx)
    lo_k = max(0, idx.min() // 2 - int(0.05 * h.size))
    hi_k = min(h.size - 1, idx.max() // 2 + int(0.05 * h.size))
    width = hi_k - lo_k
    lo = max(0, lo_k - int(frac * width))
    hi = min(h.size - 1, hi_k + int(frac * width))
    return lo, hi


def _graded_refine_phase(best, bestR, deadline, log):
    cur = best
    curR = bestR
    out = best.copy()
    outR = bestR
    for it in range(6):
        if time.process_time() >= deadline - 0.6:
            break
        lo, hi = _peak_h_window(cur, 0.35)
        if (hi - lo + 1) > 300000:
            break
        hu, lo2, hi2 = _refine_segment(cur, lo, hi)
        hu = _rescale(hu)
        r0 = R_of(hu)
        # polish the refined window with a moderate beta to lower the peak
        win = np.arange(max(0, lo2 - 128), min(hu.size, hi2 + 128))
        ht = _lbfgs_block(hu, win, 120, deadline - 0.6, beta=1e6)
        r = R_of(ht)
        log("refine #%d: N=%d pre=%.9f post=%.9f (cur %.9f)" %
            (it, hu.size, r0, r, curR))
        if r > outR + 1e-13:
            out, outR = ht.copy(), r
        if r > curR + 1e-13:
            cur, curR = ht.copy(), r
        else:
            # try a full polish before giving up on this refine
            if time.process_time() < deadline - 0.6:
                ht2 = _lbfgs_all_pos(hu, 150, deadline - 0.6, beta=0.0)
                r2 = R_of(ht2)
                if r2 > outR + 1e-13:
                    out, outR = ht2.copy(), r2
                if r2 > curR + 1e-13:
                    cur, curR = ht2.copy(), r2
                else:
                    break
    return out, outR


def _sharpen_phase(best, bestR, deadline, log):
    out = best.copy()
    outR = bestR
    cur = best
    curR = bestR
    for seed in (11, 12, 13):
        if time.process_time() >= deadline - 0.6:
            break
        hs = _seed_zeros(cur)
        win = _peak_window(hs, pad_frac=0.25, extra=192)
        ht = _lbfgs_block(hs, win, 200, deadline - 0.6, beta=1e7)
        r = R_of(ht)
        log("sharpen s=%d: post=%.9f (cur %.9f)" % (seed, r, curR))
        if r > outR + 1e-13:
            out, outR = ht.copy(), r
        if r > curR + 1e-13:
            cur, curR = ht.copy(), r
    return out, outR


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 600, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e6), (0.10, 96, 1e7),
              (0.20, 128, 1e7), (0.35, 192, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, 200, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        hs = _seed_zeros(best)
        ht = _lbfgs_all_pos(hs, 250, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    def log(msg):
        print(msg)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    log("base R=%.7f (N=%d)" % (bestR, best.size))

    # New idea 1: graded peak refinement
    refined = None
    if time.process_time() < deadline - 4.0:
        try:
            ht, rt = _graded_refine_phase(best, bestR,
                                          min(deadline - 4.0,
                                              t0 + budget_seconds * 0.55),
                                          log)
            refined = ht
            if rt > bestR + 1e-13:
                best, bestR = ht, rt
                origin += '+refine'
            log("after refine: R=%.9f N=%d" % (bestR, best.size))
        except Exception as e:
            log("refine failed: %s" % e)

    # New idea 2: sharpening with seeded zeros on refined shape
    if time.process_time() < deadline - 4.0:
        try:
            ht, rt = _sharpen_phase(best, bestR,
                                    min(deadline - 4.0,
                                        t0 + budget_seconds * 0.70), log)
            if rt > bestR + 1e-13:
                best, bestR = ht, rt
                origin += '+sharp'
            log("after sharpen: R=%.9f" % bestR)
        except Exception as e:
            log("sharpen failed: %s" % e)

    # Base cycle
    if time.process_time() < deadline - 5.0:
        try:
            ht, rt = run_cycle(best, bestR, deadline - 5.0)
            if rt > bestR + 1e-13:
                best, bestR = ht, rt
                origin += '+cycle'
            log("cycle R=%.7f N=%d" % (bestR, best.size))
        except Exception as e:
            log("cycle failed: %s" % e)

    # Alternating polish
    try:
        for _ in range(100):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin += '+all0'
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 200, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin += '+all7'
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 200, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin += '+pk7'
    except Exception as e:
        log("polish failed: %s" % e)

    log("final R=%.7f origin=%s (N=%d)" % (bestR, origin, best.size))

    if refined is not None and bestR < start_bestR - 1e-13:
        return {"best": best, "alternative": refined}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _densify(h, c):
    dense = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    act = dense > 0
    if not np.any(act):
        return dense
    lvl = c * dense[act].mean()
    dense[~act] = lvl
    return _rescale(dense)


def _prolong(h):
    out = np.empty(h.size * 2)
    out[0::2] = h
    out[1::2] = h
    return out


def _polish(h, deadline, rounds=3):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(best)
        cap = min(deadline - 0.3, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 150, cap)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.5)
        hp = _lbfgs_all_pos(best, 250, cap)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp, rp
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    start_best = base.copy()
    start_bestR = baseR
    print("base R=%.9f (N=%d)" % (baseR, base.size))

    best = base.copy()
    bestR = baseR

    # --- Phase 1: densify then beta-ladder polish (new idea) ---
    for c in [0.02, 0.05, 0.1]:
        if time.process_time() >= deadline - 6.0:
            break
        hd = _densify(base, c)
        r0 = R_of(hd)
        work = hd.copy()
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= deadline - 5.0:
                break
            cap = min(deadline - 4.0, time.process_time() + 3.0)
            ht = _lbfgs_all_pos(work, 150, cap, beta=beta)
            r = R_of(ht)
            if r > r0:
                work = ht
                r0 = r
        if r0 > bestR + 1e-14:
            hp, rp = _polish(work, deadline)
            print("densify c=%.3f raw=%.9f polished=%.9f" % (c, r0, rp))
            if rp > bestR + 1e-14:
                best, bestR = hp, rp
                print("  new best=%.9f" % bestR)

    # --- Phase 2: prolong to finer grid ---
    if best.size < 500000 and time.process_time() < deadline - 8.0:
        hN = _prolong(best)
        hN, rN = _polish(hN, deadline, rounds=2)
        print("prolonged R=%.9f" % rN)
        if rN > bestR + 1e-14:
            best, bestR = hN, rN

    # --- Phase 3: local block perturbation polish ---
    rng = np.random.RandomState(999)
    M = best.size
    while time.process_time() < deadline - 3.0:
        a = rng.randint(0, M - 1)
        w = rng.randint(max(1, M // 40), max(2, M // 8))
        b = min(M, a + w)
        if b <= a:
            continue
        hmod = best.copy()
        if rng.randint(0, 2) == 0:
            hmod[a:b] = 0.0
        else:
            hmod[a:b] *= float(rng.uniform(0.2, 0.8))
        hmod = _rescale(hmod)
        cap = min(deadline - 2.0, time.process_time() + 2.0)
        ht = _lbfgs_block(hmod, np.arange(max(0, a - 64), min(M, b + 64)),
                          80, cap)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
            print("  improve %.9f" % bestR)

    print("final best=%.9f (N=%d) start=%.9f" % (bestR, best.size, start_bestR))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_band(h, thr, M):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    mask = Lf >= thr * mx
    cnt = mask.sum()
    if cnt == 0:
        return 0.0, np.zeros(h.size)
    dq_band = np.zeros_like(Lf)
    dq_band[mask] = 2.0 * (Lf[mask] - M) / cnt
    grad = _backprop(dq_band, h)
    val = np.sum((Lf[mask] - M) ** 2) / cnt
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_band(h0, thr, M, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad_band(hh, thr, M)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _edge_extend_pow(h, K, p):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return h
    thr = 1e-9 * mx
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return h
    i0 = int(idx.min()); i1 = int(idx.max())
    hL = h[i0]; hR = h[i1]
    for k in range(1, K + 1):
        w = (1.0 + k) ** (-p)
        if i0 - k >= 0 and h[i0 - k] == 0.0:
            h[i0 - k] = hL * w
        if i1 + k < n and h[i1 + k] == 0.0:
            h[i1 + k] = hR * w
    return _rescale(h)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _densify(h, c):
    dense = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    act = dense > 0
    if not np.any(act):
        return dense
    lvl = c * dense[act].mean()
    dense[~act] = lvl
    return _rescale(dense)


def _densify_ladder(dense, deadline, tag=""):
    work = dense.copy()
    best = dense.copy()
    bestR = R_of(dense)
    origin = tag + "seed"
    for beta in [1e4, 1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 1.0:
            break
        ht = _lbfgs_all_pos(work, 400, deadline - 1.0, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    for it, pad in enumerate([0.30, 0.15, 0.08]):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 1.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 1.2:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 1.0, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _band_share(h, frac=0.01):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - frac) * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: baseline cycle on start
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            start_best.copy(), best.copy(), bestR, deadline, 'base')
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Phase D: densification experiment
    for c in [0.002, 0.02]:
        if time.process_time() >= deadline - 2.0:
            break
        dense = _densify(start_best, c)
        r0 = R_of(dense)
        nz0 = int(np.sum(dense == 0))
        if time.process_time() >= deadline - 1.5:
            break
        w, b, br, org = _densify_ladder(dense, deadline - 0.5,
                                        tag='dens%g' % c)
        nz = int(np.sum(b == 0))
        print("dens c=%g: seed R=%.9f zeros=%d -> R=%.9f zeros=%d origin=%s"
              % (c, r0, nz0, br, nz, org))
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("dens c=%g NEW BEST R=%.9f" % (c, bestR))
        elif br > alt_bestR and br > start_bestR + 1e-14:
            alt_best, alt_bestR = b, br

    # Phase BAND: band least-squares experiment
    for thr in [0.90, 0.95]:
        if time.process_time() >= deadline - 3.0:
            break
        work = best.copy()
        Lf = _knots(work)
        M = float(Lf.max())
        r_before = R_of(work)
        share_before = _band_share(work, 0.01)
        hb = _lbfgs_band(work, thr, M, 250, deadline - 2.0)
        r_band = R_of(hb)
        share_band = _band_share(hb, 0.01)
        # short standard ladder
        ht = _lbfgs_all_pos(hb, 200, deadline - 1.5, beta=1e6)
        if R_of(ht) < r_band:
            ht = hb
        ht2 = _lbfgs_all_pos(ht, 200, deadline - 1.2, beta=1e7)
        if R_of(ht2) >= R_of(ht):
            ht = ht2
        if time.process_time() < deadline - 1.0:
            win = _peak_window(ht, pad_frac=0.15, extra=128)
            ht3 = _lbfgs_block(ht, win, 300, deadline - 0.8, beta=1e7)
            if R_of(ht3) >= R_of(ht):
                ht = ht3
        if time.process_time() < deadline - 0.8:
            ht4 = _lbfgs_all_pos(ht, 200, deadline - 0.6, beta=0.0)
            if R_of(ht4) >= R_of(ht):
                ht = ht4
        r_after = R_of(ht)
        share_after = _band_share(ht, 0.01)
        print("band thr=%.2f: R %.9f -> band %.9f -> refined %.9f | "
              "1%%-share %.4f -> %.4f -> %.4f"
              % (thr, r_before, r_band, r_after,
                 share_before, share_band, share_after))
        if r_after > bestR + 1e-14:
            best, bestR, origin = ht, r_after, 'band%g' % thr
            print("band thr=%.2f NEW BEST R=%.9f" % (thr, bestR))
        elif r_after > alt_bestR and r_after > start_bestR + 1e-14:
            alt_best, alt_bestR = ht, r_after

    # Phase B: random multi-start perturbations of the best
    rng = np.random.default_rng(12345)
    amps = [0.01, 0.03, 0.05, 0.08, 0.12, 0.02, 0.04, 0.06, 0.10, 0.15]

    for trial, amp in enumerate(amps):
        if time.process_time() >= deadline - 1.0:
            break
        seed = _random_perturb(best, rng, amp)
        r_seed = R_of(seed)
        w, b, br, org = _run_cycle(seed, seed.copy(), r_seed, deadline,
                                   'rand%d' % trial)
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("rand%d amp=%.3f: R=%.9f NEW BEST" % (trial, amp, bestR))
        else:
            if br > alt_bestR:
                alt_best, alt_bestR = b, br
            print("rand%d amp=%.3f: R=%.9f (best %.9f)" % (trial, amp, br, bestR))

    # Phase C: power-law edge extension sweep if time remains
    if time.process_time() < deadline - 2.0:
        for (K, p) in [(2048, 3.0), (2048, 2.0)]:
            if time.process_time() >= deadline - 1.0:
                break
            ext = _edge_extend_pow(best, K, p)
            r_ext = R_of(ext)
            w, b, br, org = _run_cycle(ext, ext.copy(), r_ext, deadline,
                                       'pow%d_%g' % (K, p))
            if br > bestR + 1e-14:
                best, bestR, origin = b, br, org
            elif br > alt_bestR:
                alt_best, alt_bestR = b, br

    # Final window sweep on overall best
    if time.process_time() < deadline - 1.0:
        win = _peak_window(best, pad_frac=0.15, extra=128)
        ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht, r, origin + '+finalwin'

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _asym_windows(h, tol=0.995, extra=128):
    """Return left-anchored and right-anchored windows around the near-max set."""
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return []
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    s = max(hi - lo, 1)
    pad = max(extra, int(2 * s))
    wins = []
    # left-anchored: extend far to the left, keep right edge
    l_lo = max(0, lo - pad)
    wins.append(np.arange(l_lo, hi + 1))
    # right-anchored: extend far to the right, keep left edge
    r_hi = min(h.size - 1, hi + pad)
    wins.append(np.arange(lo, r_hi + 1))
    return wins


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_bestR = bestR
    work = best.copy()
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    pads = [0.02, 0.05, 0.08, 0.12, 0.20, 0.30, 0.45, 0.60, 0.90]
    n_accept = 0
    accept_log = []
    sweep = 0

    while time.process_time() < deadline - 1.5:
        sweep += 1
        accepted_this_sweep = 0

        # Build the list of candidate windows for this sweep.
        cands = []
        for pad in pads:
            cands.append(('pad%g' % pad,
                          _peak_window(work, tol=0.9995, pad_frac=pad,
                                       extra=128)))
        # tol=0.99 windows
        for pad in [0.05, 0.15, 0.30]:
            cands.append(('tol99_%g' % pad,
                          _peak_window(work, tol=0.99, pad_frac=pad,
                                       extra=128)))
        # asymmetric anchored windows
        for wi, w in enumerate(_asym_windows(work, tol=0.995, extra=128)):
            cands.append(('asym%d' % wi, w))

        for tag, win in cands:
            if time.process_time() >= deadline - 1.2:
                break
            ht = _lbfgs_block(work, win, 200, deadline - 1.2, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
                n_accept += 1
                accepted_this_sweep += 1
                accept_log.append((tag, r))
                print("accept %s: R=%.9f (sweep %d)" % (tag, bestR, sweep))
                if n_accept % 3 == 0:
                    if time.process_time() < deadline - 1.2:
                        ht2 = _lbfgs_all_pos(work, 300, deadline - 1.2,
                                             beta=0.0)
                        r2 = R_of(ht2)
                        if r2 > bestR + 1e-14:
                            work, best, bestR = ht2, ht2.copy(), r2
                            n_accept += 1
                            accepted_this_sweep += 1
                            accept_log.append(('all0', r2))
                            print("accept all0: R=%.9f" % bestR)

        if accepted_this_sweep == 0:
            # reset to best and continue
            work = best.copy()

    # Final long beta=0 run if time remains.
    if time.process_time() < deadline - 1.0:
        rem = deadline - 1.0 - time.process_time()
        if rem > 8.0:
            ht = _lbfgs_all_pos(best, 3000, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
                print("final all0: R=%.9f" % bestR)

    print("accepted %d windows; final R=%.9f (start %.9f, N=%d)"
          % (n_accept, bestR, start_bestR, best.size))

    result = {"best": best}
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _argmax_frac(h):
    Lf = _knots(h)
    if Lf.size <= 2:
        return 0.0
    m = int(np.argmax(Lf))
    return m / float(Lf.size - 1)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _densify(h, c):
    dense = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    act = dense > 0
    if not np.any(act):
        return dense
    lvl = c * dense[act].mean()
    dense[~act] = lvl
    return _rescale(dense)


def _densify_ladder(dense, deadline, tag=""):
    work = dense.copy()
    best = dense.copy()
    bestR = R_of(dense)
    origin = tag + "seed"
    for beta in [1e4, 1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 1.0:
            break
        ht = _lbfgs_all_pos(work, 400, deadline - 1.0, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    for it, pad in enumerate([0.30, 0.15, 0.08]):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 1.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 1.2:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 1.0, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _tilt_cycle(t, deadline, tag):
    """Cheap cycle: beta ladder, peak window, beta=0 polish."""
    work = t.copy()
    best = t.copy()
    bestR = R_of(t)
    origin = tag
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(work, 200, deadline - 0.3, beta=1e6)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = tag + "b6"
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(work, 200, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = tag + "b7"
    if time.process_time() < deadline - 0.5:
        win = _peak_window(work, pad_frac=0.2, extra=128)
        ht = _lbfgs_block(work, win, 200, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = tag + "pk"
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(work, 150, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = tag + "b0"
    return best, bestR, origin


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: baseline cycle on start
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            start_best.copy(), best.copy(), bestR, deadline, 'base')
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Phase D: densification experiment
    for c in [0.002, 0.02]:
        if time.process_time() >= deadline - 2.0:
            break
        dense = _densify(start_best, c)
        r0 = R_of(dense)
        nz0 = int(np.sum(dense == 0))
        if time.process_time() >= deadline - 1.5:
            break
        w, b, br, org = _densify_ladder(dense, deadline - 0.5,
                                        tag='dens%g' % c)
        nz = int(np.sum(b == 0))
        print("dens c=%g: seed R=%.9f zeros=%d -> R=%.9f zeros=%d origin=%s"
              % (c, r0, nz0, br, nz, org))
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("dens c=%g NEW BEST R=%.9f" % (c, bestR))
        elif br > alt_bestR and br > start_bestR + 1e-14:
            alt_best, alt_bestR = b, br

    # Phase B: random multi-start perturbations
    rng = np.random.default_rng(12345)
    amps = [0.01, 0.03, 0.05, 0.08, 0.12, 0.02, 0.04, 0.06, 0.10, 0.15]

    for trial, amp in enumerate(amps):
        if time.process_time() >= deadline - 1.0:
            break
        seed = _random_perturb(best, rng, amp)
        r_seed = R_of(seed)
        w, b, br, org = _run_cycle(seed, seed.copy(), r_seed, deadline,
                                   'rand%d' % trial)
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("rand%d amp=%.3f: R=%.9f NEW BEST" % (trial, amp, bestR))
        else:
            if br > alt_bestR:
                alt_best, alt_bestR = b, br
            print("rand%d amp=%.3f: R=%.9f (best %.9f)" % (trial, amp, br, bestR))

    # Phase C: power-law edge extension sweep
    if time.process_time() < deadline - 2.0:
        for (K, p) in [(2048, 3.0), (2048, 2.0)]:
            if time.process_time() >= deadline - 1.0:
                break
            ext = _edge_extend_pow(best, K, p)
            r_ext = R_of(ext)
            w, b, br, org = _run_cycle(ext, ext.copy(), r_ext, deadline,
                                       'pow%d_%g' % (K, p))
            if br > bestR + 1e-14:
                best, bestR, origin = b, br, org
            elif br > alt_bestR:
                alt_best, alt_bestR = b, br

    # Phase E: global exponential tilt experiment
    N = best.size
    i = np.arange(N, dtype=float)
    u = 2.0 * i / max(1.0, (N - 1)) - 1.0
    trials = []
    for kind in ['lin', 'quad']:
        for c in [-0.9, -0.45, -0.2, 0.2, 0.45, 0.9]:
            trials.append((kind, c))

    tilt_alt = None
    tilt_altR = -1.0
    idx = 0
    while time.process_time() < deadline - 1.0:
        kind, c = trials[idx % len(trials)]
        idx += 1
        now = time.process_time()
        remaining = max(1, len(trials) - (idx % len(trials)) + 1)
        cap = now + max(0.5, (deadline - 1.0 - now) / remaining)
        sub_deadline = min(cap, deadline - 1.0)
        t = best.copy()
        if kind == 'lin':
            t *= np.exp(np.clip(c * u, -60.0, 60.0))
        else:
            t *= np.exp(np.clip(c * u * u, -60.0, 60.0))
        t = _rescale(np.clip(t, 0, None))
        r_seed = R_of(t)
        b, br, org = _tilt_cycle(t, sub_deadline, 'tilt_%s%g' % (kind, c))
        frac = _argmax_frac(b)
        print("tilt %s c=%+.2f: seed R=%.9f -> R=%.9f argmax_frac=%.3f origin=%s"
              % (kind, c, r_seed, br, frac, org))
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("tilt %s c=%+.2f NEW BEST R=%.9f argmax_frac=%.3f"
                  % (kind, c, bestR, frac))
        elif br > tilt_altR and br > start_bestR + 1e-14:
            tilt_alt, tilt_altR = b, br

    # Final window sweep on best
    if time.process_time() < deadline - 0.5:
        for pad in [0.2, 0.1, 0.05]:
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht = _lbfgs_block(best, win, 300, deadline - 0.3, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
                origin = "final_pk%g" % pad
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_all_pos(best, 200, deadline - 0.3, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
                origin = "final_b0"

    if tilt_alt is not None and tilt_alt.size == best.size and tilt_altR < bestR:
        if alt_best is None or tilt_altR > alt_bestR:
            alt_best, alt_bestR = tilt_alt, tilt_altR

    print("final R=%.9f origin=%s (start %.9f, N=%d) argmax_frac=%.3f" %
          (bestR, origin, start_bestR, best.size, _argmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result


def _edge_extend_pow(h, K, p):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return h
    thr = 1e-9 * mx
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return h
    i0 = int(idx.min()); i1 = int(idx.max())
    hL = h[i0]; hR = h[i1]
    for k in range(1, K + 1):
        w = (1.0 + k) ** (-p)
        if i0 - k >= 0 and h[i0 - k] == 0.0:
            h[i0 - k] = hL * w
        if i1 + k < n and h[i1 + k] == 0.0:
            h[i1 + k] = hR * w
    return _rescale(h)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _revive_zeros(h, lo, hi, radius=256, factor=1e-3):
    h = h.copy()
    win = h[lo:hi]
    zeros = np.flatnonzero(win <= 0)
    if zeros.size == 0:
        return h
    pos_idx = np.flatnonzero(win > 0)
    if pos_idx.size == 0:
        return h
    pos_vals = win[pos_idx]
    for z in zeros:
        left = np.searchsorted(pos_idx, z - radius, side='left')
        right = np.searchsorted(pos_idx, z + radius, side='right')
        if right > left:
            lm = pos_vals[left:right].mean()
        else:
            lm = pos_vals.mean()
        win[z] = factor * lm
    h[lo:hi] = win
    return h


def _perturb_window(h, lo, hi, rng, sigma=0.35):
    h = h.copy()
    n = h.size
    lo = max(0, int(lo))
    hi = min(n, int(hi))
    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(4, 9))
    widths = rng.uniform(0.02, 0.10, size=nblocks)
    widths = widths / widths.sum()
    cuts = np.cumsum(widths * W).astype(int)
    cuts = np.clip(cuts, 1, W - 1)
    cuts = np.unique(cuts)
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, sigma))
        h[a:c] *= fac
    h = _revive_zeros(h, lo, hi, radius=256, factor=1e-3)
    return _rescale(h)


def _polish_chain(h, deadline):
    cur = h
    cur_r = R_of(cur)

    def _try(cand):
        nonlocal cur, cur_r
        if cand is None:
            return
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r

    if time.process_time() < deadline - 0.5:
        _try(_lbfgs_log(cur, maxiter=1200, deadline=deadline))
    for beta in (400.0, 1500.0, 4000.0):
        if time.process_time() >= deadline - 0.5:
            break
        _try(_lbfgs_sm(cur, beta, maxiter=300, deadline=deadline))
    if time.process_time() < deadline - 0.5:
        _try(_lbfgs_log(cur, maxiter=800, deadline=deadline))
    for frac in (0.05, 0.10, 0.20):
        if time.process_time() >= deadline - 0.5:
            break
        _try(_window_polish_peak(cur, deadline, frac, 8, maxiter=400, beta=None))
    return cur, cur_r


def _asym_windows(h, tol=0.995, extra=128):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return []
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    s = max(hi - lo, 1)
    pad = max(extra, int(2 * s))
    wins = []
    l_lo = max(0, lo - pad)
    wins.append(np.arange(l_lo, hi + 1))
    r_hi = min(h.size - 1, hi + pad)
    wins.append(np.arange(lo, r_hi + 1))
    return wins


def _asym_polish(h, deadline):
    cur = h
    cur_r = R_of(cur)
    for free in _asym_windows(cur):
        if time.process_time() >= deadline - 0.5:
            break
        cand = _lbfgs_block(cur, free, maxiter=500, deadline=deadline, beta=None)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= deadline - 0.5:
            break
        cand = _lbfgs_block(cur, free, maxiter=400, deadline=deadline, beta=1500.0)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _extend_and_polish(h, deadline, factor=2):
    """Upsample (linear interp) to a finer grid, then polish."""
    n = h.size
    n2 = min(int(n * factor), 1000000)
    if n2 <= n:
        return h, R_of(h)
    x_old = np.linspace(0.0, 1.0, n, endpoint=False)
    x_new = np.linspace(0.0, 1.0, n2, endpoint=False)
    h2 = np.interp(x_new, x_old, h)
    h2 = _rescale(h2)
    if time.process_time() < deadline - 0.5:
        h2 = _lbfgs_log(h2, maxiter=400, deadline=deadline)
    return h2, R_of(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    base = start_arr.copy()
    base_r = R_of(base)
    best = base.copy()
    best_r = base_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # 1) Try grid extension (finer resolution) - a genuinely different line.
    if time.process_time() < hard_end - 2.0 and base.size < 500000:
        try:
            hx, rx = _extend_and_polish(base, hard_end, factor=2)
            print("extend R=%.6f N=%d (base %.6f)" % (rx, hx.size, base_r))
            _consider(hx, rx)
            if rx > base_r - 1e-4:
                # continue polishing on the extended grid
                hx, rx = _polish_chain(hx, hard_end)
                print("extend+chain R=%.6f N=%d" % (rx, hx.size))
                _consider(hx, rx)
                if rx > best_r:
                    base = hx
                    base_r = rx
        except Exception:
            pass

    # 2) Asymmetric window polish on the best so far.
    if time.process_time() < hard_end - 1.0:
        try:
            ha, ra = _asym_polish(best, hard_end)
            print("asym R=%.6f (best %.6f)" % (ra, best_r))
            _consider(ha, ra)
        except Exception:
            pass

    # 3) Perturbation search on the current best.
    cur = best.copy()
    cur_r = best_r
    n = cur.size
    seed = 0
    while time.process_time() < hard_end - 1.0 and seed < 40:
        rng = np.random.default_rng(9100 + seed)
        lo = int(rng.uniform(0.0, 0.5) * n)
        hi = min(n, lo + n // 2)
        hp = _perturb_window(cur, lo, hi, rng, sigma=0.35)
        hp, rp = _polish_chain(hp, hard_end)
        _consider(hp, rp)
        if rp > cur_r:
            cur, cur_r = hp, rp
        seed += 1

    print("final R=%.6f N=%d | base R=%.6f N=%d"
          % (best_r, best.size, base_r, base.size))

    if best_r < base_r:
        best = base.copy()
        best_r = base_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: baseline cycle on start
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            start_best.copy(), best.copy(), bestR, deadline, 'base')
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Phase B: random multi-start perturbations of the best
    rng = np.random.default_rng(98765)
    amps = [0.01, 0.03, 0.05, 0.08, 0.12, 0.02, 0.04, 0.06, 0.10, 0.15]
    for trial, amp in enumerate(amps):
        if time.process_time() >= deadline - 1.0:
            break
        seed = _random_perturb(best, rng, amp)
        r_seed = R_of(seed)
        w, b, br, org = _run_cycle(seed, seed.copy(), r_seed, deadline,
                                   'rand%d' % trial)
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("rand%d amp=%.3f: R=%.9f NEW BEST" % (trial, amp, bestR))
        else:
            if br > alt_bestR:
                alt_best, alt_bestR = b, br
            print("rand%d amp=%.3f: R=%.9f (best %.9f)" % (trial, amp, br, bestR))

    # Final window sweep on overall best
    if time.process_time() < deadline - 1.0:
        win = _peak_window(best, pad_frac=0.15, extra=128)
        ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht, r, origin + '+finalwin'

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


# ---- experiment: 2x splitting with unequal subcells ----

def _split2(h, d):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    h2 = np.empty(2 * n, dtype=float)
    h2[0::2] = h * (1.0 - d)
    h2[1::2] = h * (1.0 + d)
    return _rescale(h2)


def _d_alternating(n, amp=0.02):
    d = np.empty(n)
    d[0::2] = amp
    d[1::2] = -amp
    return d


def _d_uniform(n, rng, amp=0.05):
    return rng.uniform(-amp, amp, n)


def _d_localized(h, rng, amp=0.05):
    n = h.size
    d = np.zeros(n)
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return _d_uniform(n, rng, amp)
    band = np.flatnonzero(Lf >= 0.9 * mx)
    if band.size == 0:
        return _d_uniform(n, rng, amp)
    lo = max(0, band.min() - 1)
    hi = min(n - 1, band.max())
    d[lo:hi + 1] = rng.uniform(-amp, amp, hi - lo + 1)
    return d


def _run_split_ladder(h2, deadline, tag=""):
    work = h2.copy()
    best = h2.copy()
    bestR = R_of(h2)
    origin = tag + "seed"
    for beta in [1e4, 1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 1.2:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 1.2, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    for it, pad in enumerate([0.30, 0.15, 0.08]):
        if time.process_time() >= deadline - 1.2:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 300, deadline - 1.2, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
    if time.process_time() < deadline - 1.2:
        ht = _lbfgs_all_pos(work, 300, deadline - 1.2, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sall0" % tag
    return work, best, bestR, origin


def _subpair_equal(h2, tol=1e-8):
    a = h2[0::2]; b = h2[1::2]
    return bool(np.all(np.abs(a - b) <= tol * (np.abs(a) + np.abs(b) + 1e-30)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: baseline cycle on start (keep what base does well)
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            start_best.copy(), best.copy(), bestR, deadline, 'base')
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # ---- Experiment: 2x splitting with unequal subcells ----
    rng = np.random.default_rng(2024)
    n = start_best.size
    seeds = []
    seeds.append(('alt', _d_alternating(n, 0.02)))
    seeds.append(('uni', _d_uniform(n, rng, 0.05)))
    seeds.append(('loc', _d_localized(start_best, rng, 0.05)))

    split_best = None
    split_bestR = -1.0
    split_origin = ''

    for tag, d in seeds:
        if time.process_time() >= deadline - 2.0:
            break
        h2 = _split2(start_best, d)
        r0 = R_of(h2)
        w, b, br, org = _run_split_ladder(h2, deadline - 0.5, tag='split_%s' % tag)
        eq = _subpair_equal(b)
        print("split %s: seed R=%.9f -> R=%.9f (N2=%d) origin=%s subpair_equal=%s"
              % (tag, r0, br, b.size, org, eq))
        if br > split_bestR:
            split_best, split_bestR, split_origin = b, br, org
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("split %s NEW BEST R=%.9f" % (tag, bestR))
        elif br > alt_bestR and br > start_bestR + 1e-14:
            alt_best, alt_bestR = b, br

    if split_best is not None:
        eq = _subpair_equal(split_best)
        print("best split N2=%d R=%.9f subpair_equal=%s (start %.9f)"
              % (split_best.size, split_bestR, eq, start_bestR))

    # Final window sweep on overall best
    if time.process_time() < deadline - 1.0:
        win = _peak_window(best, pad_frac=0.15, extra=128)
        ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht, r, origin + '+finalwin'

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

