    # Phase 3: try refining to 2x resolution and re-optimize (may beat the
    # current best because the finer grid allows sharper structure).
    if time.process_time() < deadline - 2.0 and bestH.size < 500000:
        hr = _refine(bestH)
        rr = R_of(hr)
        if rr > bestR + 1e-12:
            bestH, bestR = hr, rr
