    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _revive_zeros(h, lo, hi, radius=256, factor=1e-3):
    h = h.copy()
    win = h[lo:hi]
    zeros = np.flatnonzero(win <= 0)
    if zeros.size == 0:
        return h
    pos_idx = np.flatnonzero(win > 0)
    if pos_idx.size == 0:
        return h
    pos_vals = win[pos_idx]
    for z in zeros:
        left = np.searchsorted(pos_idx, z - radius, side='left')
        right = np.searchsorted(pos_idx, z + radius, side='right')
        if right > left:
            lm = pos_vals[left:right].mean()
        else:
            lm = pos_vals.mean()
        win[z] = factor * lm
    h[lo:hi] = win
    return h


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _extend_and_polish(h, deadline, factor=2):
    n = h.size
    n2 = min(int(n * factor), 1000000)
    if n2 <= n:
        return h, R_of(h)
    x_old = np.linspace(0.0, 1.0, n, endpoint=False)
    x_new = np.linspace(0.0, 1.0, n2, endpoint=False)
    h2 = np.interp(x_new, x_old, h)
    h2 = _rescale(h2)
    if time.process_time() < deadline - 0.5:
        h2 = _lbfgs_log(h2, maxiter=300, deadline=deadline)
    return h2, R_of(h2)


def _smooth_refine(h, deadline):
    """Smoothing homotopy: gradually sharpen max via increasing beta."""
    cur = h
    cur_r = R_of(cur)
    for beta in (200.0, 800.0, 3000.0, 10000.0, 30000.0):
        if time.process_time() >= deadline - 0.5:
            break
        cand = _lbfgs_sm(cur, beta, maxiter=250, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    if time.process_time() < deadline - 0.5:
        cand = _lbfgs_log(cur, maxiter=600, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.0
    hard_end = deadline - 0.3

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    base = start_arr.copy()
    base_r = R_of(base)
    best = base.copy()
    best_r = base_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if cand is None or cand.size == 0:
            return
        if r > best_r + 1e-15:
            best, best_r = cand.copy(), r
        elif r > alt_r + 1e-15:
            alternative, alt_r = cand.copy(), r

    # 1) Grid extension for finer resolution (genuinely different line).
    if time.process_time() < hard_end - 2.0 and base.size < 500000:
        try:
            hx, rx = _extend_and_polish(base, hard_end, factor=2)
            print("extend R=%.6f N=%d (base %.6f)" % (rx, hx.size, base_r))
            _consider(hx, rx)
            if rx > base_r - 1e-4:
                hx, rx = _smooth_refine(hx, hard_end)
                print("extend+smooth R=%.6f N=%d" % (rx, hx.size))
                _consider(hx, rx)
        except Exception:
            pass

    # 2) Smoothing homotopy on the best so far.
    if time.process_time() < hard_end - 1.0:
        try:
            hs, rs = _smooth_refine(best, hard_end)
            print("smooth R=%.6f (best %.6f)" % (rs, best_r))
            _consider(hs, rs)
        except Exception:
            pass

    # 3) Perturbation search: block-perturb windows and re-polish.
    cur = best.copy()
    cur_r = best_r
    n = cur.size
    seed = 0
    while time.process_time() < hard_end - 1.0 and seed < 60:
        rng = np.random.default_rng(9100 + seed)
        # Focus perturbation on the peak region plus surroundings.
        lo_pk, hi_pk = _peak_region(cur, tol=0.99)
        span = max(hi_pk - lo_pk, 1)
        pad = int(rng.uniform(0.3, 1.5) * span) + 8
        lo = max(0, lo_pk - pad)
        hi = min(n, hi_pk + pad + 1)
        W = hi - lo
        if W < 8:
            seed += 1
            continue
        hp = cur.copy()
        nblocks = int(rng.integers(4, 10))
        widths = rng.uniform(0.02, 0.12, size=nblocks)
        widths = widths / widths.sum()
        cuts = np.cumsum(widths * W).astype(int)
        cuts = np.clip(cuts, 1, W - 1)
        cuts = np.unique(cuts)
        edges = np.concatenate(([0], cuts, [W]))
        for b in range(edges.size - 1):
            a = lo + edges[b]
            c = lo + edges[b + 1]
            if c <= a:
                continue
            fac = np.exp(rng.normal(0.0, 0.35))
            hp[a:c] *= fac
        hp = _revive_zeros(hp, lo, hi, radius=256, factor=1e-3)
        hp = _rescale(hp)
        hp, rp = _smooth_refine(hp, hard_end)
        _consider(hp, rp)
        if rp > cur_r:
            cur, cur_r = hp, rp
        seed += 1

    print("final R=%.6f N=%d | base R=%.6f N=%d"
          % (best_r, best.size, base_r, base.size))

    if best_r < base_r:
        best = base.copy()
        best_r = base_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _edge_extend(h, K, rho):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return h
    thr = 1e-9 * mx
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return h
    i0 = int(idx.min()); i1 = int(idx.max())
    hL = h[i0]; hR = h[i1]
    for k in range(1, K + 1):
        if i0 - k >= 0 and h[i0 - k] == 0.0:
            h[i0 - k] = hL * (rho ** k)
        if i1 + k < n and h[i1 + k] == 0.0:
            h[i1 + k] = hR * (rho ** k)
    return _rescale(h)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _refine_split(h, jitter):
    n = h.size
    out = np.zeros(2 * n)
    sign = np.where(np.arange(n) % 2 == 0, 1.0, -1.0)
    fac = 1.0 + jitter * sign
    out[0::2] = h * fac
    out[1::2] = h * (2.0 - fac)
    return out


def _fine_schedule(h2, deadline, tag=""):
    work = h2.copy()
    best = h2.copy()
    bestR = R_of(h2)
    origin = tag + "start"
    r_start = bestR

    for _pass in range(2):
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(work, 200, deadline - 0.3, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
                origin = "%sbeta%g_p%d" % (tag, beta, _pass)
    r_ladder = bestR

    pads = [0.20, 0.12, 0.10, 0.08, 0.15, 0.06]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 200, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 200, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    r_pad = bestR

    if time.process_time() < deadline - 1.0:
        ext = _edge_extend(work, 2048, 0.995)
        r_ext = R_of(ext)
        if r_ext > bestR + 1e-14:
            work, best, bestR = ext, ext.copy(), r_ext
            origin = tag + "ext"
        for it, pad in enumerate([0.10, 0.08, 0.06]):
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(work, pad_frac=pad, extra=128)
            ht = _lbfgs_block(work, win, 200, deadline - 0.3, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
                origin = "%sextpk%d" % (tag, it)
    return work, best, bestR, origin, r_start, r_ladder, r_pad


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    work0, best0, bestR0, origin0 = _run_cycle(
        start_best.copy(), best.copy(), bestR, deadline, 'base')
    if bestR0 > bestR + 1e-14:
        best, bestR, origin = best0, bestR0, origin0
    print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # NEW: try multiple distinct jitter seeds on the *best* so far, not just start.
    # Also try a mild multiplicative perturbation as an alternative basin.
    jitters = [0.0, 0.005, 0.02, -0.01, 0.035]
    results = {}
    rng = np.random.default_rng(12345)
    for jitter in jitters:
        if time.process_time() >= deadline - 1.0:
            break
        src = best if bestR > start_bestR + 1e-12 else start_best
        h2 = _refine_split(src, jitter)
        h2 = _rescale(h2)
        tag = "j%g_" % jitter
        w, b, br, org, rs, rl, rp = _fine_schedule(h2, deadline, tag=tag)
        results[jitter] = (b, br, org)
        print("jitter=%.3f: start R=%.9f ladder R=%.9f pad R=%.9f final R=%.9f N=%d"
              % (jitter, rs, rl, rp, br, b.size))
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org

    # NEW: local coordinate-descent style polish — repeatedly optimize narrow
    # windows of fixed width around the peak, which can nudge knots past plateaus.
    if time.process_time() < deadline - 1.5:
        Lf = _knots(best)
        pk = int(np.argmax(Lf))
        n = best.size
        for frac in [0.05, 0.03, 0.02, 0.04]:
            if time.process_time() >= deadline - 1.0:
                break
            half = max(64, int(n * frac))
            lo = max(0, pk - half); hi = min(n, pk + half)
            win = np.arange(lo, hi)
            ht = _lbfgs_block(best, win, 300, deadline - 0.3, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
                origin = "narrow%.2f" % frac

    if results:
        best_j = max(results.keys(), key=lambda k: results[k][1])
        work = results[best_j][0].copy()
        curR = results[best_j][1]
        pads = [0.10, 0.08, 0.06, 0.12, 0.15, 0.20]
        it = 0
        while time.process_time() < deadline - 1.0:
            pad = pads[it % len(pads)]
            it += 1
            win = _peak_window(work, pad_frac=pad, extra=128)
            ht = _lbfgs_block(work, win, 200, deadline - 0.3, beta=1e7)
            r = R_of(ht)
            if r > curR + 1e-14:
                work, curR = ht, r
                if curR > bestR + 1e-14:
                    best, bestR, origin = ht.copy(), curR, "final_pad%d" % it
            if time.process_time() < deadline - 0.6:
                ht2 = _lbfgs_all_pos(work, 200, deadline - 0.3, beta=0.0)
                r2 = R_of(ht2)
                if r2 > curR + 1e-14:
                    work, curR = ht2, r2
                    if curR > bestR + 1e-14:
                        best, bestR, origin = ht2.copy(), curR, "final_all0_%d" % it

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    alt = None
    if results:
        best_j = max(results.keys(), key=lambda k: results[k][1])
        alt = results[best_j][0]
    if alt is not None:
        return {"best": best, "alternative": alt}
    return best

