    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_bestR = bestR
    start_best = best.copy()
    origin = 'start'
    Lf0 = _knots(best)
    argmax0 = float(np.argmax(Lf0)) / max(1, Lf0.size - 1)
    print("base R=%.9f (N=%d, argmax=%.4f, zero_frac=%.3f)" %
          (bestR, best.size, argmax0, _zero_frac(best)))

    # Shortened baseline: three beta passes then pads [0.30, 0.15, 0.08],
    # with the beta=0 global pass only at the first pad.
    base_deadline = deadline - 35.0
    if time.process_time() < base_deadline - 0.5:
        work = best.copy()
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= base_deadline - 0.3:
                break
            ht = _lbfgs_all_pos(work, 300, base_deadline - 0.2, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
                origin = "basebeta%g" % beta
        for it, pad in enumerate([0.30, 0.15, 0.08]):
            if time.process_time() >= base_deadline - 0.3:
                break
            win = _peak_window(work, pad_frac=pad, extra=128)
            ht = _lbfgs_block(work, win, 400, base_deadline - 0.2, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
                origin = "basepk%d" % it
            if it == 0 and time.process_time() < base_deadline - 0.4:
                ht2 = _lbfgs_all_pos(work, 300, base_deadline - 0.2, beta=0.0)
                r2 = R_of(ht2)
                if r2 > bestR + 1e-14:
                    work, best, bestR = ht2, ht2.copy(), r2
                    origin = "basepk0+all0"
                else:
                    work = ht2 if r2 >= r else work
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Main loop: deadline-bounded window cycling with randomized window params.
    rng = np.random.default_rng(20240117)
    rounds = 0
    accepts = 0
    while time.process_time() < deadline - 0.6:
        pad = float(10.0 ** rng.uniform(-1.3, -0.25))
        tol = float(rng.uniform(0.985, 0.99995))
        extra = int(10.0 ** rng.uniform(1.8, 2.7))
        win = _peak_window(best, tol=tol, pad_frac=pad, extra=extra)
        ht = _lbfgs_block(best, win, 400, deadline - 0.4, beta=1e7)
        ht = _lbfgs_all_pos(ht, 250, deadline - 0.4, beta=0.0)
        if rounds % 4 == 3 and time.process_time() < deadline - 0.6:
            ht = _lbfgs_all_pos(ht, 250, deadline - 0.4, beta=1e6)
            ht = _lbfgs_all_pos(ht, 250, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        rounds += 1
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            accepts += 1
            origin = "round%d_p%.3f_t%.4f_e%d" % (rounds, pad, tol, extra)
            print("round %d pad=%.3f tol=%.4f extra=%d R=%.9f NEW BEST" %
                  (rounds, pad, tol, extra, r))
        elif rounds % 5 == 0:
            print("round %d pad=%.3f tol=%.4f extra=%d R=%.9f (best %.9f)" %
                  (rounds, pad, tol, extra, r, bestR))

    Lf = _knots(best)
    argmax = float(np.argmax(Lf)) / max(1, Lf.size - 1)
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f, argmax=%.4f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best), argmax))
    print("rounds=%d accepts=%d" % (rounds, accepts))

    result = {"best": best}
    if bestR < start_bestR - 1e-15:
        result["alternative"] = start_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _zero_frac(h):
    return float(np.mean(h == 0))


def _half_cycle(c, bestR, deadline, tag=""):
    """Alternation on the half-resolution quotient c."""
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase A: half-resolution quotient polish on start ----
    N = best.size
    if N % 2 == 0 and N >= 4 and time.process_time() < deadline - 2.0:
        h0 = best.copy()
        resid = float(np.max(np.abs(h0[0::2] - h0[1::2]))) if N else 0.0
        print("initial staircase residual max|h0[0::2]-h0[1::2]| = %.3e" % resid)
        c = h0[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        # spend ~65% of budget on half-res alternation
        half_deadline = t0 + budget_seconds * 0.65
        rounds = 0
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
            if time.process_time() >= half_deadline - 1.0:
                break
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        # lift
        h_lift = np.repeat(best_c, 2)
        h_lift = _rescale(h_lift)
        r_lift = R_of(h_lift)
        print("lifted R=%.9f" % r_lift)
        # beta ladder at full N
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift+ladder'
            print("lift+ladder NEW BEST R=%.9f" % bestR)
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            print("lift+ladder R=%.9f (best %.9f)" % (r, bestR))

    # ---- Phase B: pair-breaking rounds ----
    rng = np.random.default_rng(424242)
    deltas = [1e-2, 3e-3, 1e-3, 1e-2, 3e-3, 1e-3, 3e-3, 1e-3]
    for trial, delta in enumerate(deltas):
        if time.process_time() >= deadline - 1.0:
            break
        N2 = best.size // 2
        if N2 < 1:
            break
        d = delta * rng.standard_normal(N2)
        hb = best.copy()
        hb[0::2] *= (1.0 + d)
        hb[1::2] *= (1.0 - d)
        hb = _rescale(hb)
        win = _peak_window(hb, pad_frac=0.15, extra=128)
        hb = _lbfgs_block(hb, win, 400, deadline - 0.5, beta=1e7)
        hb = _lbfgs_all_pos(hb, 300, deadline - 0.5, beta=0.0)
        for pad in [0.25, 0.10]:
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(hb, pad_frac=pad, extra=128)
            hb = _lbfgs_block(hb, win, 400, deadline - 0.5, beta=1e7)
            hb = _lbfgs_all_pos(hb, 300, deadline - 0.5, beta=0.0)
        r = R_of(hb)
        asym = float(np.max(np.abs(hb[0::2] - hb[1::2])))
        if r > bestR + 1e-14:
            best, bestR, origin = hb.copy(), r, 'pairbreak_d%.0e' % delta
            print("pairbreak d=%.0e std=%.3e R=%.9f NEW BEST asym=%.3e" %
                  (delta, float(np.std(d)), bestR, asym))
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = hb.copy(), r
            print("pairbreak d=%.0e std=%.3e R=%.9f (best %.9f) asym=%.3e" %
                  (delta, float(np.std(d)), r, bestR, asym))

    # ---- Final window sweep ----
    if time.process_time() < deadline - 1.0:
        win = _peak_window(best, pad_frac=0.15, extra=128)
        ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht, r, origin + '+finalwin'

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _zero_frac(h):
    return float(np.mean(h == 0))


def _maxmean(h):
    pos = h[h > 0]
    if pos.size == 0:
        return 0.0
    return float(pos.max() / max(pos.mean(), 1e-300))


def _polish_full(hp, deadline):
    """Full recipe: beta ramp then window sweep. Returns best found."""
    h = hp
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            return h
        h = _lbfgs_all_pos(h, 400, deadline - 0.5, beta=beta)
    best = h
    bestR = R_of(h)
    for pad in [0.30, 0.20, 0.15, 0.10, 0.08]:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, 400, deadline - 0.5, beta=1e7)
        if time.process_time() < deadline - 0.6:
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
        h = ht if r >= R_of(h) else h
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    best = base.copy()
    bestR = baseR
    origin = 'start'
    print("base R=%.9f (N=%d) maxmean=%.2f zero_frac=%.3f" %
          (bestR, best.size, _maxmean(best), _zero_frac(best)))

    alt_best = None
    alt_bestR = -1.0

    # Experiment: power compression sweep
    compressed_win = None
    compressed_winR = -1.0
    for p in [0.5, 0.4, 0.3]:
        if time.process_time() >= deadline - 2.0:
            break
        hp = np.where(base > 0, np.power(base, p), 0.0)
        hp = _rescale(hp)
        print("p=%.2f start maxmean=%.2f zero_frac=%.3f R=%.9f" %
              (p, _maxmean(hp), _zero_frac(hp), R_of(hp)))
        # reserve time: don't let one p eat everything
        sub_deadline = min(deadline - 1.0,
                           time.process_time() + (deadline - time.process_time()) / 3.0)
        ht = _polish_full(hp, sub_deadline)
        r = R_of(ht)
        print("p=%.2f polished maxmean=%.2f zero_frac=%.3f R=%.9f (best %.9f)" %
              (p, _maxmean(ht), _zero_frac(ht), r, bestR))
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            origin = "compress_p%.2f" % p
            print("  NEW BEST from p=%.2f" % p)
        if r > compressed_winR:
            compressed_win, compressed_winR = ht.copy(), r
        if r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # If compression beat start, run alternating window loop from it
    if compressed_win is not None and compressed_winR > baseR + 1e-14:
        print("compression succeeded; alternating window loop")
        work, b, br, org = _run_cycle(
            compressed_win.copy(), best.copy(), bestR, deadline, 'comp')
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
        print("after alternating: R=%.9f origin=%s" % (bestR, origin))
    else:
        # Fallback: plain baseline cycle from base
        if time.process_time() < deadline - 1.0:
            work0, best0, bestR0, origin0 = _run_cycle(
                base.copy(), best.copy(), bestR, deadline, 'base')
            if bestR0 > bestR + 1e-14:
                best, bestR, origin = best0, bestR0, origin0
            print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Final window sweep on overall best
    if time.process_time() < deadline - 1.0:
        win = _peak_window(best, pad_frac=0.15, extra=128)
        ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht, r, origin + '+finalwin'

    print("final R=%.9f origin=%s (start %.9f, N=%d, maxmean=%.2f, zero_frac=%.3f)" %
          (bestR, origin, baseR, best.size, _maxmean(best), _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _run_cycle(work, best, bestR, deadline, origin, tag="", pads=None):
    if pads is None:
        pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _zero_frac(h):
    return float(np.mean(h == 0))


def _resample(h, N):
    # linear resample of step heights to N steps (mass-preserving in shape)
    n = h.size
    if n == N:
        return h.copy()
    xp = (np.arange(n) + 0.5) / n
    x = (np.arange(N) + 0.5) / N
    return np.interp(x, xp, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: shorter baseline cycle
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            start_best.copy(), best.copy(), bestR, deadline, 'base',
            pads=[0.30, 0.15, 0.08])
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Phase B: densification ladder
    arr_walk = best.copy()
    r_walk = bestR
    dense_final = best.copy()
    if time.process_time() < deadline - 2.0:
        base_state = best.copy()
        pos = base_state[base_state > 0]
        mean_act = float(pos.mean()) if pos.size > 0 else 1.0
        work = base_state.copy()
        for c in [1e-3, 3e-3, 1e-2, 3e-2, 1e-1, 3e-1]:
            if time.process_time() >= deadline - 2.0:
                break
            work[work == 0] = c * mean_act
            work = _rescale(work)
            for beta in [1e5, 1e6, 1e7]:
                if time.process_time() >= deadline - 2.0:
                    break
                work = _lbfgs_all_pos(work, 150, deadline - 2.0, beta=beta)
            r = R_of(work)
            print("walk c=%.0e R=%.9f zero_frac=%.3f" %
                  (c, r, _zero_frac(work)))
            if r > r_walk + 1e-14:
                r_walk = r
                arr_walk = work.copy()
            dense_final = work.copy()

    # Phase C: refined cycle from arr_walk
    if time.process_time() < deadline - 1.0:
        w, b, br, org = _run_cycle(
            arr_walk.copy(), arr_walk.copy(), r_walk, deadline, 'walk',
            pads=[0.30, 0.15, 0.08])
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("walk-cycle: R=%.9f NEW BEST zero_frac=%.3f" %
                  (bestR, _zero_frac(best)))
        else:
            if br > alt_bestR:
                alt_best, alt_bestR = b, br
            print("walk-cycle: R=%.9f (best %.9f)" % (br, bestR))

    # Phase D: dense cycle if time allows
    if time.process_time() < deadline - 1.0:
        rd = R_of(dense_final)
        w, b, br, org = _run_cycle(
            dense_final.copy(), dense_final.copy(), rd, deadline, 'dense',
            pads=[0.30, 0.15, 0.08])
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("dense-cycle: R=%.9f NEW BEST zero_frac=%.3f" %
                  (bestR, _zero_frac(best)))
        else:
            if br > alt_bestR:
                alt_best, alt_bestR = b, br
            print("dense-cycle: R=%.9f (best %.9f)" % (br, bestR))

    # Phase E (NEW): resample best to a few different resolutions and polish.
    # This explores nearby shapes at coarser/finer grids, which can escape
    # the particular local optimum at the original grid size.
    if time.process_time() < deadline - 1.5 and best.size > 100:
        n0 = best.size
        factors = [0.5, 0.75, 1.5, 2.0]
        for fac in factors:
            if time.process_time() >= deadline - 1.5:
                break
            N2 = int(round(n0 * fac))
            if N2 < 16 or N2 > 1000000:
                continue
            hr = _resample(best, N2)
            hr = _rescale(hr)
            rr = R_of(hr)
            # small polish
            for beta in [1e6, 1e7]:
                if time.process_time() >= deadline - 1.5:
                    break
                hr = _lbfgs_all_pos(hr, 200, deadline - 1.5, beta=beta)
            rr = R_of(hr)
            print("resample x%.2f N=%d R=%.9f" % (fac, N2, rr))
            if rr > bestR + 1e-14 and hr.size == best.size:
                best, bestR, origin = hr, rr, "resample%.2f" % fac
            elif rr > bestR + 1e-14:
                # different size: adopt if better (scoring accepts any N)
                if hr.size <= 1000000:
                    best, bestR, origin = hr, rr, "resample%.2f" % fac
            else:
                if hr.size == best.size and rr > alt_bestR:
                    alt_best, alt_bestR = hr, rr

    # Phase F (NEW): random perturb + polish restarts around best, cheap.
    if time.process_time() < deadline - 1.0:
        tries = 0
        while time.process_time() < deadline - 1.0 and tries < 6:
            tries += 1
            amp = 0.01 + 0.03 * rng.random()
            hp = _random_perturb(best, rng, amp)
            for beta in [1e6, 1e7]:
                if time.process_time() >= deadline - 1.0:
                    break
                hp = _lbfgs_all_pos(hp, 200, deadline - 1.0, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                best, bestR, origin = hp, rp, "perturb%d" % tries
                print("perturb%d amp=%.3f R=%.9f NEW BEST" % (tries, amp, rp))
            else:
                if rp > alt_bestR and hp.size == best.size:
                    alt_best, alt_bestR = hp, rp

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _smooth(h, w):
    if w <= 1:
        return h
    ker = np.ones(w) / w
    return np.convolve(h, ker, mode='same')


def _upsample(h, factor):
    n = h.size
    m = n * factor
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(m) + 0.5) / m
    return np.interp(x_new, x_old, h)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(int(t0 * 1e6) & 0xFFFFFFFF)

    start_best = None
    start_bestR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
            print("base R=%.9f (N=%d)" % (start_bestR, start_best.size))

    bestH = start_best.copy() if start_best is not None else None
    bestRH = start_bestR
    altH = None
    altRH = 0.0

    if bestH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        bestH = _rescale(h)
        bestRH = R_of(bestH)

    # Strategy: try upsampling the start to a finer grid to allow more freedom,
    # then apply beta-smoothed LBFGS focusing on the peak plateau.
    up_attempts = []
    if start_best is not None:
        for factor in (2, 3):
            if time.process_time() > deadline - 25.0:
                break
            up = _rescale(_upsample(start_best, factor))
            up_attempts.append((factor, up, R_of(up)))

    # Evaluate each upsample candidate with a short beta polish
    for factor, up, r_up in up_attempts:
        if time.process_time() > deadline - 22.0:
            break
        hs = _lbfgs_all_pos(up, 200, min(deadline - 18.0,
                                         time.process_time() + 5.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-10:
            bestH, bestRH = hs, rs
            print("  upsample x%d polished R=%.9f" % (factor, bestRH))
        elif rs > altRH + 1e-10:
            altH, altRH = hs, rs

    # beta-smoothed polish on the peak (maximize smooth approximation
    # of L_inf, which helps when the peak is a broad plateau).
    if time.process_time() < deadline - 15.0:
        for beta in (1e4, 1e5, 1e6):
            if time.process_time() > deadline - 12.0:
                break
            hs = _lbfgs_all_pos(bestH, 200, min(deadline - 10.0,
                                              time.process_time() + 4.0),
                                beta=beta)
            rs = R_of(hs)
            if rs > bestRH + 1e-13:
                bestH, bestRH = hs, rs
                print("  beta=%.0e R=%.9f" % (beta, bestRH))
            elif rs > altRH + 1e-13:
                altH, altRH = hs, rs

    # Peak-window block polish: only free the region around the max of f*f,
    # which is where L_inf is achieved and where local growth helps most.
    for frac in (0.06, 0.10, 0.15, 0.22):
        if time.process_time() > deadline - 4.0:
            break
        free = _peak_window(bestH, tol=0.9995, pad_frac=frac, extra=128)
        hp = _lbfgs_block(bestH, free, 250,
                          min(deadline - 2.0, time.process_time() + 3.0),
                          beta=0.0)
        rp = R_of(hp)
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp, rp
            print("  peak frac=%.2f R=%.9f" % (frac, bestRH))
        elif rp > altRH + 1e-13:
            altH, altRH = hp, rp

    # Final full LBFGS with remaining time
    if time.process_time() < deadline - 2.0:
        hs = _lbfgs_all_pos(bestH, 500, deadline - 0.5, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs, rs
            print("  final full R=%.9f" % bestRH)
        elif rs > altRH + 1e-13:
            altH, altRH = hs, rs

    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if start_best is None:
        return bestH
    if bestRH > start_bestR + 1e-12:
        return {"best": bestH, "alternative": start_best}
    # Didn't beat start; still offer any genuinely different construction
    if altH is not None and altRH > 0:
        return {"best": start_best, "alternative": altH}
    return {"best": start_best, "alternative": bestH if bestH is not None else start_best}

