    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.15, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _zero_frac(h):
    return float(np.mean(h == 0))


def _newton_polish(best, bestR, deadline):
    win = _peak_window(best, pad_frac=0.25, extra=256)
    free = win[best[win] > 0]
    if free.size < 2:
        return best, bestR, False
    z0 = np.log(np.clip(best[free], 1e-300, None))
    base = best.copy()

    def fz(z):
        hh = base.copy()
        hh[free] = np.exp(np.clip(z, -700, 700))
        val, g = _fun_grad(hh)
        return val, g[free] * hh[free]

    def gz(z):
        return fz(z)[1]

    def hessp(z, p):
        try:
            nz = np.linalg.norm(z)
            np_ = np.linalg.norm(p)
            eps = 1e-6 * (1.0 + nz) / max(np_, 1e-30)
            gp = gz(z + eps * p)
            gm = gz(z - eps * p)
            return (gp - gm) / (2.0 * eps)
        except Exception:
            return p

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(fz, z0, jac=True, hessp=hessp, method='trust-krylov',
                       callback=cb,
                       options={'maxiter': 60, 'gtol': 1e-10,
                                'initial_tr_radius': 1e-3})
    except (TimeoutError, Exception):
        return best, bestR, False
    if res is None:
        return best, bestR, False
    ht = base.copy()
    ht[free] = np.exp(np.clip(res.x, -700, 700))
    ht = _rescale(np.clip(ht, 0.0, None))
    r = R_of(ht)
    if r > bestR + 1e-14:
        return ht, r, True
    return best, bestR, False


def _refine(h, deadline, rng, nsteps=400):
    """Block-coordinate ascent: sweep windows, optimizing each with L-BFGS.
    Different structure from the peak-window polish: covers whole support."""
    best = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    bestR = R_of(best)
    n = best.size
    # window sizes relative to N
    sizes = [max(64, n // 32), max(128, n // 16), max(256, n // 8)]
    for sz in sizes:
        if time.process_time() >= deadline - 0.5:
            break
        stride = max(1, sz // 2)
        starts = list(range(0, max(1, n - sz + 1), stride))
        if starts[-1] + sz < n:
            starts.append(n - sz)
        rng.shuffle(starts)
        for lo in starts:
            if time.process_time() >= deadline - 0.3:
                break
            win = np.arange(lo, min(n, lo + sz))
            ht = _lbfgs_block(best, win, 60, deadline - 0.2, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: shortened baseline cycle on start
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            start_best.copy(), best.copy(), bestR, deadline, 'base')
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Phase B: block-coordinate sweep over whole support (new idea)
    if time.process_time() < deadline - 2.0:
        ht, r = _refine(best, deadline, np.random.default_rng(12345))
        if r > bestR + 1e-14:
            best, bestR = ht, r
            origin = origin + '+sweep'
            print("sweep: R=%.9f NEW BEST" % bestR)
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # Phase C: Newton polish on peak window
    newton_gain = False
    if time.process_time() < deadline - 2.0:
        ht, r, gain = _newton_polish(best, bestR, deadline)
        if gain:
            best, bestR = ht, r
            origin = origin + '+newton'
            newton_gain = True
            print("newton: NEW BEST R=%.9f" % bestR)
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # Phase D: consolidate with pad-window polishes + beta=0 global
    pads = [0.25, 0.15, 0.10, 0.20, 0.08, 0.30, 0.12]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.6:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = origin + '+pk%.2f' % pad
            print("pad=%.2f: R=%.9f NEW BEST" % (pad, bestR))
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR = ht2.copy(), r2
                origin = origin + '+all0'
                print("all0 after pad=%.2f: R=%.9f NEW BEST" % (pad, bestR))
            else:
                if r2 > alt_bestR:
                    alt_best, alt_bestR = ht2.copy(), r2

    # Phase E: another block-sweep refinement pass if time remains
    if time.process_time() < deadline - 3.0:
        ht, r = _refine(best, deadline, np.random.default_rng(777))
        if r > bestR + 1e-14:
            best, bestR = ht, r
            origin = origin + '+sweep2'
            print("sweep2: R=%.9f NEW BEST" % bestR)
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    if newton_gain and time.process_time() < deadline - 1.0:
        ht, r, gain = _newton_polish(best, bestR, deadline)
        if gain:
            best, bestR = ht, r
            origin = origin + '+newton2'
            print("newton2: NEW BEST R=%.9f" % bestR)
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _zero_frac(h):
    return float(np.mean(h == 0))


def _half_cycle(c, bestR, deadline, tag=""):
    """Alternation on the half-resolution quotient c."""
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _sharp_cycle(c, bestR, deadline, tag=""):
    """Sharp-pad alternation on a quotient."""
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.10, 0.08, 0.06, 0.05, 0.04]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    N = best.size
    h0 = best.copy()

    # ---- Detect periodicity at 2 and 4 ----
    r2 = 0.0
    r4 = 0.0
    c2 = None
    c4 = None
    if N % 2 == 0 and N >= 4:
        c2 = h0[0::2].copy()
        r2 = float(np.max(np.abs(c2[0::2] - c2[1::2]))) if c2.size >= 2 else 0.0
    if c2 is not None and c2.size % 2 == 0 and c2.size >= 4:
        c4 = c2[0::2].copy()
        r4 = float(np.max(np.abs(c4[0::2] - c4[1::2]))) if c4.size >= 2 else 0.0
    print("periodicity r2=%.3e r4=%.3e (N=%d, c2=%s, c4=%s)" %
          (r2, r4, N,
           c2.size if c2 is not None else -1,
           c4.size if c4 is not None else -1))

    use_quarter = (c4 is not None and r4 < 1e-9 and c4.size >= 4096)

    if use_quarter:
        branch = 'quarter'
        print("branch=quarter (r4~0, c4.size=%d)" % c4.size)
        quarter_deadline = t0 + budget_seconds * 0.70
        work_c = c4.copy()
        best_c = c4.copy()
        best_cR = R_of(c4)
        rounds = 0
        while time.process_time() < quarter_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, quarter_deadline, tag='q%d' % rounds)
            rounds += 1
            if time.process_time() >= quarter_deadline - 1.0:
                break
        print("quarter rounds=%d R(c4)=%.9f" % (rounds, best_cR))

        # lift c4 -> c2' at N/2, one beta ladder
        c2_lift = np.repeat(best_c, 2)
        c2_lift = _rescale(c2_lift)
        c2_liftR = R_of(c2_lift)
        ht = c2_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r_half = R_of(ht)
        # recompress-or-keep by R_of
        if r_half > c2_liftR + 1e-14:
            c2_best = ht.copy()
            c2_bestR = r_half
        else:
            c2_best = c2_lift
            c2_bestR = c2_liftR
        print("lift c4->c2 R=%.9f (kept %.9f)" % (r_half, c2_bestR))

        # lift to full N, one beta ladder
        h_full = np.repeat(c2_best, 2)
        h_full = _rescale(h_full)
        ht = h_full
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r_full = R_of(ht)
        if r_full > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r_full, 'quarter+lift'
            print("quarter+lift NEW BEST R=%.9f" % bestR)
        else:
            if r_full > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r_full
            print("quarter+lift R=%.9f (best %.9f)" % (r_full, bestR))

    else:
        branch = 'half'
        print("branch=half (r4=%.3e)" % r4)
        half_deadline = t0 + budget_seconds * 0.85
        if c2 is not None and c2.size >= 4:
            work_c = c2.copy()
            best_c = c2.copy()
            best_cR = R_of(c2)
            rounds = 0
            while time.process_time() < half_deadline - 1.0:
                work_c, best_c, best_cR, org = _half_cycle(
                    work_c, best_cR, half_deadline, tag='h%d' % rounds)
                rounds += 1
                if time.process_time() >= half_deadline - 1.0:
                    break
            print("half rounds=%d R(c2)=%.9f" % (rounds, best_cR))

            # lift to full N, beta ladder
            h_lift = np.repeat(best_c, 2)
            h_lift = _rescale(h_lift)
            ht = h_lift
            for beta in [1e6, 1e7]:
                if time.process_time() >= deadline - 1.0:
                    break
                ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, 'half+lift'
                print("half+lift NEW BEST R=%.9f" % bestR)
            else:
                if r > alt_bestR:
                    alt_best, alt_bestR = ht.copy(), r
                print("half+lift R=%.9f (best %.9f)" % (r, bestR))

            # sharp pads on c2
            if time.process_time() < deadline - 1.0:
                work_c2, best_c2, best_c2R, org = _sharp_cycle(
                    best_c, best_cR, deadline, tag='sharp')
                h_full = np.repeat(best_c2, 2)
                h_full = _rescale(h_full)
                ht = h_full
                for beta in [1e6, 1e7]:
                    if time.process_time() >= deadline - 1.0:
                        break
                    ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
                r = R_of(ht)
                if r > bestR + 1e-14:
                    best, bestR, origin = ht.copy(), r, 'half+sharp+lift'
                    print("half+sharp+lift NEW BEST R=%.9f" % bestR)
                else:
                    if r > alt_bestR:
                        alt_best, alt_bestR = ht.copy(), r
                    print("half+sharp+lift R=%.9f (best %.9f)" % (r, bestR))

    print("final R=%.9f origin=%s branch=%s r2=%.3e r4=%.3e (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, branch, r2, r4, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
