                accepted_this_pass += 1
                print("pad %.2f ACCEPT R(c)=%.9f (+%.2e)" %
                      (pad, ccR, r_cand - ccR))
                if accepted_total % 3 == 0 and time.process_time() < deadline - 1.0:
                    cand2 = _lbfgs_all_pos(cc, 300, deadline - 0.3, beta=0.0)
                    r2 = R_of(cand2)
                    if r2 > ccR + 1e-14:
                        cc = cand2
                        ccR = r2
                        print("  all0 ACCEPT R(c)=%.9f" % ccR)
        # re-lift and compare at full N
        if time.process_time() < deadline - 1.0:
            h_lift = _rescale(np.repeat(cc, 2))
            r_lift = R_of(h_lift)
            if r_lift > bestR + 1e-14:
                best, bestR, origin = h_lift.copy(), r_lift, 'quotient_pass%d' % pass_no
                print("pass %d lift NEW BEST R=%.9f" % (pass_no, bestR))
            else:
                if r_lift > alt_bestR:
                    alt_best, alt_bestR = h_lift.copy(), r_lift
        if accepted_this_pass == 0:
            # no progress this pass; try a small full-N polish to escape
            if time.process_time() < deadline - 1.0:
                cand = _lbfgs_all_pos(cc, 300, deadline - 0.3, beta=1e7)
                r_cand = R_of(cand)
                if r_cand > ccR + 1e-14:
                    cc = cand
                    ccR = r_cand
                    accepted_total += 1
                    print("escape all-beta ACCEPT R(c)=%.9f" % ccR)
                    continue
            break

    # final lift
    h_final = _rescale(np.repeat(cc, 2))
    r_final = R_of(h_final)
    if r_final > bestR + 1e-14:
        best, bestR, origin = h_final.copy(), r_final, origin + '+final'
