def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift_and_polish(c, deadline):
    """Lift half-res quotient c to full res and polish. Returns (h, R)."""
    h_lift = _rescale(np.repeat(c, 2))
    ht = h_lift
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(ht, 400, deadline - 0.5, beta=1e6)
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(ht, 400, deadline - 0.5, beta=1e7)
    if time.process_time() < deadline - 1.0:
        win = _peak_window(ht, pad_frac=0.12, extra=128)
        ht = _lbfgs_block(ht, win, 400, deadline - 0.3, beta=1e7)
    return ht, R_of(ht)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    N = best.size
    if N % 2 != 0 or N < 4:
        # fallback: just polish the start
        ht = _lbfgs_all_pos(best, 600, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > bestR:
            best, bestR = ht, r
        return {"best": best}

    h0 = best.copy()
    c = h0[0::2].copy()
    c = _rescale(c)
    cR = R_of(c)
    print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))

    # ---- Phase 1: time-chunked quotient polish with lift checkpoints ----
    checkpoints = [0.16, 0.24, 0.32, 0.40, 0.48]
    cp_idx = 0
    chunk_end = t0 + budget_seconds * 0.50
    chunk_count = 0
    best_cut = None
    while time.process_time() < chunk_end - 1.0:
        now = time.process_time()
        slice_deadline = min(deadline - 6.0, now + 2.5)
        if slice_deadline <= now + 0.2:
            break
        c, c_best, cR, org = _half_cycle(c, cR, slice_deadline, tag='chunk%d' % chunk_count)
        chunk_count += 1
        # check if we crossed a checkpoint
        frac = (time.process_time() - t0) / budget_seconds
        while cp_idx < len(checkpoints) and frac >= checkpoints[cp_idx]:
            cut = checkpoints[cp_idx]
            cp_idx += 1
            if time.process_time() >= deadline - 4.0:
                break
            ht, r = _lift_and_polish(c, deadline - 4.0)
            print("cut=%.2f lifted R=%.9f (best %.9f)" % (cut, r, bestR))
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, 'cut%.2f' % cut
                best_cut = cut
                print("cut=%.2f NEW BEST R=%.9f" % (cut, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # final lift of the current quotient
    if time.process_time() < deadline - 4.0:
        ht, r = _lift_and_polish(c, deadline - 4.0)
        print("final lift R=%.9f (best %.9f)" % (r, bestR))
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'final_lift'
            print("final lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: full-N peak-block polish passes ----
    pads = [0.15, 0.10, 0.08, 0.06, 0.05, 0.04]
    work = best.copy()
    workR = bestR
    for pass_i in range(2):
        if time.process_time() >= deadline - 1.0:
            break
        for pad in pads:
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(work, pad_frac=pad, extra=128)
            ht = _lbfgs_block(work, win, 400, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > workR + 1e-14:
                work, workR = ht, r
                if r > bestR + 1e-14:
                    best, bestR, origin = ht.copy(), r, origin + '+pk%d' % pass_i
                    print("pass%d pad=%.2f NEW BEST R=%.9f" % (pass_i, pad, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        if time.process_time() < deadline - 1.0:
            ht = _lbfgs_all_pos(work, 400, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > workR + 1e-14:
                work, workR = ht, r
                if r > bestR + 1e-14:
                    best, bestR, origin = ht.copy(), r, origin + '+all0p%d' % pass_i
                    print("pass%d all0 NEW BEST R=%.9f" % (pass_i, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    if best_cut is not None:
        print("winning cutoff=%.2f" % best_cut)
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)[:2 * h.size - 1]
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]
    b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return float(num / den)


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]
    b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    """Optimise in log-space so zeros can revive; smooth-peak via beta."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    x0 = np.log(np.maximum(h, 1e-9))

    def f(x):
        hh = np.exp(np.clip(x, -40.0, 40.0))
        if beta > 0:
            return _fun_grad_beta(hh, beta)
        return _fun_grad(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(np.clip(res.x, -40.0, 40.0)))


def _peak_window(h, tol=0.999, pad_frac=0.5, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _lbfgs_block(h0, active, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(active, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolongate(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    xs = np.linspace(0.0, total, N + 1)
    out = np.interp(xs, c, np.arange(M + 1, dtype=float))
    idx = np.clip(np.floor(out).astype(int), 0, M - 1)
    return np.maximum(h[idx], 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    def time_left():
        return time.process_time() < deadline

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            bestR = R_of(best)

    if best is None:
        best = np.ones(64)
        bestR = R_of(best)

    h = best.copy()
    alt = None
    altR = -1.0

    def try_accept(cand):
        nonlocal best, bestR, alt, altR
        rc = R_of(cand)
        if rc > bestR + 1e-14:
            bestR = rc
            best = cand.copy()
            return True
        if rc > altR + 1e-14 and rc < bestR - 1e-9:
            altR = rc
            alt = cand.copy()
        return False

    # Increase resolution, refine with mixed log/smooth/block optimisers.
    levels = (8000, 32000, 96000, 200000)
    for li, N in enumerate(levels):
        if not time_left():
            break
        h = _prolongate(h, N)
        try_accept(h)
        it = 1500 if li == 0 else 700
        it_s = 300 if li == 0 else 200
        if time_left():
            c = _lbfgs_log(h, it, deadline)
            if R_of(c) > R_of(h):
                h = c
            try_accept(h)
        for beta in (50, 300, 1500, 8000):
            if not time_left():
                break
            c = _lbfgs_log(h, it_s, deadline, beta=beta)
            if R_of(c) > R_of(h):
                h = c
            try_accept(h)
        # Block refinement on the peak region.
        for tol, pad in ((0.9995, 0.5), (0.999, 0.6), (0.995, 0.8)):
            if not time_left():
                break
            win = _peak_window(h, tol=tol, pad_frac=pad, extra=max(8, N // 400))
            for beta in (0.0, 500.0, 5000.0):
                if not time_left():
                    break
                c = _lbfgs_block(h, win, it_s, deadline, beta=beta)
                if R_of(c) > R_of(h):
                    h = c
                try_accept(h)

    # Final polishing on best.
    fracs = (0.10, 0.25, 0.40, 0.15, 0.55)
    fi = 0
    while time_left():
        c = _lbfgs_log(best, 400, deadline)
        if R_of(c) > R_of(best):
            best = c
            bestR = R_of(best)
        else:
            try_accept(c)
        if not time_left():
            break
        n = best.size
        f = fracs[fi % len(fracs)]
        fi += 1
        L = _knots(best)
        k = int(np.argmax(L))
        half = max(2, int(f * n))
        lo = max(0, (k - half) // 2 - 16)
        hi = min(n, (k + half) // 2 + 17)
        if hi - lo >= 2:
            c = _lbfgs_block(best, np.arange(lo, hi), 300, deadline)
            if R_of(c) > R_of(best):
                best = c
                bestR = R_of(best)
            else:
                try_accept(c)
        if not time_left():
            break
        c = _lbfgs_log(best, 300, deadline, beta=3000.0)
        if R_of(c) > R_of(best):
            best = c
            bestR = R_of(best)
        else:
            try_accept(c)

    if alt is not None and altR > 0 and altR < bestR - 1e-9:
        return {"best": best, "alternative": alt}
    return best

