            print("lift+ladder R=%.9f (best %.9f)" % (r, bestR))

    # ---- Phase 2: full-N perturb-then-polish restarts ----
    restarts_done = 0
    accepted_count = 0
    rng = np.random.default_rng(11)
    amps = [0.0015, 0.003, 0.006]
