          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0, free=None):
    if time.process_time() >= deadline - 0.25:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    if free is None:
        active = None
        x0 = h
    else:
        active = np.asarray(free, dtype=int)
        if active.size == 0:
            return h0
        x0 = h[active].copy()

    def f(x):
        if active is None:
            hh = np.clip(x, 0.0, None)
            val, g = fg(hh)
            return val, g
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    n = x0.size
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    if active is None:
        return _rescale(np.clip(res.x, 0.0, None))
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _accept(best, bestR, ht):
    r = R_of(ht)
    if r > bestR + 1e-13:
        return ht.copy(), r
    return best, bestR


def _grow_support(best, deadline):
    """Upsample the construction: refine N by linear interpolation, giving
    the optimiser fresh degrees of freedom to sharpen the peak region."""
    if time.process_time() >= deadline - 0.5:
        return best
    n = best.size
    if n >= 400000:
        return best
    # grow by factor 2 (capped)
    m = min(400000, 2 * n)
    xi = np.linspace(0.0, 1.0, n)
    xo = np.linspace(0.0, 1.0, m)
    hg = np.interp(xo, xi, best)
    hg = np.clip(hg, 0, None)
    if hg.sum() <= 0:
        return best
    return _rescale(hg)


def _prune_and_refine(best, bestR, deadline, keep_frac, maxiter=250):
    if time.process_time() >= deadline - 0.3:
        return best, bestR
    h = best.copy()
    nz = h > 0
    if not np.any(nz):
        return best, bestR
    idx = np.flatnonzero(nz)
    vals = h[idx]
    order = np.argsort(vals)
    nkeep = max(1, int(len(idx) * keep_frac))
    kill = idx[order[:len(idx) - nkeep]]
    hp = h.copy()
    hp[kill] = 0.0
    hp = _seed_zeros(hp)
    ht = _lbfgs(hp, maxiter, deadline, beta=0.0)
    return _accept(best, bestR, ht)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        best, bestR = _accept(best, bestR, _lbfgs(best, 800, deadline - 0.4, beta=0.0))
    if time.process_time() < deadline - 0.4:
        best, bestR = _accept(best, bestR, _lbfgs(best, 400, deadline - 0.4, beta=1e7))
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        best, bestR = _accept(best, bestR,
                              _lbfgs(best, 250, deadline - 0.4, beta=beta, free=win))
    if time.process_time() < deadline - 0.4:
        best, bestR = _accept(best, bestR, _lbfgs(_seed_zeros(best), 300, deadline - 0.4, beta=0.0))
    return best, bestR


def _prune_cycle(best, bestR, deadline):
    for keep in (0.85, 0.7, 0.55, 0.4):
        if time.process_time() >= deadline - 0.4:
            break
        best, bestR = _prune_and_refine(best, bestR, deadline - 0.4, keep, maxiter=250)
    if time.process_time() < deadline - 0.4:
        best, bestR = _accept(best, bestR, _lbfgs(best, 300, deadline - 0.4, beta=0.0))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW: try support refinement (upsampling) as a fresh line of search
    alt = None
    altR = 0.0
    if time.process_time() < deadline - 20.0:
        hg = _grow_support(best, deadline - 15.0)
        hgR = R_of(hg)
        hg = _lbfgs(hg, 600, deadline - 12.0, beta=0.0)
        hgR = R_of(hg)
        if hgR > bestR + 1e-10:
            best, bestR = hg.copy(), hgR
            print("grow R=%.7f (N=%d)" % (bestR, best.size))
        else:
            alt, altR = hg.copy(), hgR

    if time.process_time() < deadline - 3.0:
        best, bestR = run_cycle(best, bestR, deadline - 3.0)
        print("base cycle R=%.7f" % bestR)

    if time.process_time() < deadline - 2.5:
        best, bestR = _prune_cycle(best, bestR, deadline - 2.5)
        print("prune cycle R=%.7f (zeros %.1f%%)" %
              (bestR, 100.0 * np.mean(best <= 0)))

    last_print = time.process_time()
    while time.process_time() < deadline - 1.2:
        prevR = bestR
        if time.process_time() < deadline - 1.2:
            best, bestR = run_cycle(best, bestR, deadline - 1.2)
        if bestR - prevR < 1e-10:
            if time.process_time() < deadline - 1.0:
                best, bestR = _prune_cycle(best, bestR, deadline - 1.0)
        if time.process_time() - last_print > 8.0:
            last_print = time.process_time()
            print("iter R=%.7f zeros %.1f%%" %
                  (bestR, 100.0 * np.mean(best <= 0)))

    if time.process_time() < deadline - 0.5:
        best, bestR = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

