    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift_extrap(cpol, gamma, N):
    c = np.asarray(cpol, dtype=float)
    m = c.size
    cs = np.concatenate(([c[0]], c, [c[-1]]))
    d = np.diff(cs)
    u = np.zeros(N)
    ev = np.empty(m)
    od = np.empty(m)
    ev[:] = c + gamma * d[:m]
    od[:] = c - gamma * d[1:m + 1]
    ev = np.clip(ev, 0.0, None)
    od = np.clip(od, 0.0, None)
    n_ev = u[0::2].size
    n_od = u[1::2].size
    u[0::2][:min(n_ev, m)] = ev[:min(n_ev, m)]
    if n_ev > m:
        u[0::2][m:] = ev[-1]
    u[1::2][:min(n_od, m)] = od[:min(n_od, m)]
    if n_od > m:
        u[1::2][m:] = od[-1]
    return _rescale(u)


def _polish_final(best, bestR, deadline):
    for pad in [0.10, 0.06, 0.04]:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR = ht2.copy(), r2
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def _maybe_alt(h2, r2):
        nonlocal alt_best, alt_bestR
        if r2 > alt_bestR:
            alt_best, alt_bestR = h2.copy(), r2

    # ---- Phase 1: doubling-resolution lift work ----
    # Take the full-N start, extract its even/odd rows as a quotient, optimise
    # the quotient, then extrapolating-lift to 2N and fold back. This explores a
    # finer grid than the current start, which is the main lever for tiny gains.
    N0 = best.size
    if N0 % 2 == 0 and N0 >= 4:
        m = N0 // 2
        c = 0.5 * (best[0::2][:m] + best[1::2][:m])
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.22
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))

        # Try a few gammas for the extrapolating lift to 2N, then fold back to N.
        gammas = [0.0, 0.5, -0.5, 0.25, -0.25]
        lift_end = t0 + budget_seconds * 0.55
        for gi, gamma in enumerate(gammas):
            if time.process_time() >= lift_end - 1.0:
                break
            now = time.process_time()
            slice_dl = min(lift_end, now + 3.0)
            if slice_dl <= now + 0.5:
                break
            try:
                u = _lift_extrap(best_c, gamma, 2 * N0)
                r_pre = R_of(u)
                if time.process_time() < slice_dl - 0.4:
                    u = _lbfgs_all_pos(u, 250, slice_dl - 0.3, beta=1e6)
                if time.process_time() < slice_dl - 0.4:
                    u = _lbfgs_all_pos(u, 250, slice_dl - 0.3, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    win = _peak_window(u, pad_frac=0.08, extra=256)
                    u = _lbfgs_block(u, win, 250, slice_dl - 0.3, beta=1e7)
                # fold 2N back to N
                h2 = _rescale(0.5 * (u[0::2] + u[1::2]))[:N0]
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 250, slice_dl - 0.3, beta=1e6)
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 250, slice_dl - 0.3, beta=1e7)
                r_fold = R_of(h2)
                print("lift g=%.2f r_pre=%.9f r_fold=%.9f (best %.9f)" %
                      (gamma, r_pre, r_fold, bestR))
                if r_fold > bestR + 1e-13:
                    best, bestR, origin = h2.copy(), r_fold, 'lift_g%.2f' % gamma
                    print("  lift NEW BEST R=%.9f" % bestR)
                else:
                    _maybe_alt(h2, r_fold)
            except Exception as e:
                print("lift g=%.2f exception %s" % (gamma, e))

    # ---- Phase 2: 3x3 grid over (alpha, gamma) on the current best ----
    N = best.size
    m = N // 2
    if N % 2 == 0 and N >= 4 and m >= 2:
        alphas = [0.25, 0.5, 0.75]
        gammas = [-0.5, 0.0, 0.5]
        pairs = [(a, g) for a in alphas for g in gammas]
        cycle_end = deadline - 5.0
        pair_idx = 0
        max_pairs = 18
        while pair_idx < max_pairs and time.process_time() < cycle_end - 1.0:
            alpha, gamma = pairs[pair_idx % len(pairs)]
            pair_idx += 1
            now = time.process_time()
            slice_dl = min(cycle_end, now + 2.5)
            if slice_dl <= now + 0.5:
                break
            try:
                a_ev = best[0::2][:m]
                b_od = best[1::2][:m]
                L = min(a_ev.size, b_od.size)
                c = alpha * a_ev[:L] + (1.0 - alpha) * b_od[:L]
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
                cR0 = R_of(c)
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='a%.2fg%.2f' % (alpha, gamma),
                    pads=[0.30, 0.20, 0.12])
                u = _lift_extrap(cand_c, gamma, N)
                r_pre = R_of(u)
                if time.process_time() < slice_dl - 0.4:
                    u = _lbfgs_all_pos(u, 200, slice_dl - 0.3, beta=1e6)
                if time.process_time() < slice_dl - 0.4:
                    u = _lbfgs_all_pos(u, 200, slice_dl - 0.3, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    win = _peak_window(u, pad_frac=0.10, extra=256)
                    u = _lbfgs_block(u, win, 200, slice_dl - 0.3, beta=1e7)
                r_2n = R_of(u)
                h2 = _rescale(u.reshape(m, 2).mean(axis=0))
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 200, slice_dl - 0.3, beta=1e6)
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 200, slice_dl - 0.3, beta=1e7)
                r_fold = R_of(h2)
                print("grid a=%.2f g=%.2f R(c)=%.9f r_pre=%.9f r_2N=%.9f r_fold=%.9f (best %.9f)" %
                      (alpha, gamma, cand_cR, r_pre, r_2n, r_fold, bestR))
                if r_fold > bestR + 1e-13:
                    best, bestR, origin = h2.copy(), r_fold, 'grid_a%.2fg%.2f' % (alpha, gamma)
                    print("  grid NEW BEST R=%.9f" % bestR)
                else:
                    _maybe_alt(h2, r_fold)
            except Exception as e:
                print("grid a=%.2f g=%.2f exception %s" % (alpha, gamma, e))

    # ---- Phase 3: peak polish ----
    if time.process_time() < deadline - 1.0:
        best, bestR = _polish_final(best, bestR, deadline - 2.0)

    # ---- Phase 3b: randomized 2N lift multi-start ----
    phase3b_start = t0 + budget_seconds * 0.55
    phase3b_end = min(t0 + budget_seconds * 0.72, deadline - 4.0)
    if time.process_time() < phase3b_start:
        while time.process_time() < phase3b_start - 0.05:
            time.sleep(0.01)
    if time.process_time() < phase3b_end - 1.0 and best.size >= 2:
        n = best.size
        sigmas = [0.02, 0.05, 0.10, 0.03]
        rnd = 0
        while time.process_time() < phase3b_end - 1.0:
            sigma = sigmas[rnd % len(sigmas)]
            rnd += 1
            now = time.process_time()
            slice_dl = min(now + 2.0, deadline - 3.0)
            if slice_dl <= now + 0.3:
                break
            try:
                d = np.clip(sigma * np.random.randn(n), -0.6, 0.6)
                u = np.empty(2 * n)
                u[0::2] = best * (1.0 + d)
                u[1::2] = best * (1.0 - d)
                u = _rescale(u)
                u = _lbfgs_all_pos(u, 120, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    win = _peak_window(u, pad_frac=0.10, extra=128)
                    u = _lbfgs_block(u, win, 150, slice_dl, beta=1e7)
                h2 = _rescale(0.5 * (u[0::2] + u[1::2]))[:n]
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e6)
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e7)
                r_fold = R_of(h2)
                if r_fold > bestR + 1e-13:
                    best, bestR, origin = h2.copy(), r_fold, 'rnd%d' % rnd
                    print("  rnd NEW BEST R=%.9f" % bestR)
                else:
                    _maybe_alt(h2, r_fold)
            except Exception as e:
                print("rnd %d exception %s" % (rnd, e))

    # ---- Phase 4: final peak polish + trailing beta=0 ----
    if time.process_time() < deadline - 1.0:
        best, bestR = _polish_final(best, bestR, deadline)

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift_extrap(cpol, gamma, N):
    c = np.asarray(cpol, dtype=float)
    m = c.size
    cs = np.concatenate(([c[0]], c, [c[-1]]))
    d = np.diff(cs)
    u = np.zeros(N)
    ev = np.empty(m)
    od = np.empty(m)
    ev[:] = c + gamma * d[:m]
    od[:] = c - gamma * d[1:m + 1]
    ev = np.clip(ev, 0.0, None)
    od = np.clip(od, 0.0, None)
    n_ev = u[0::2].size
    n_od = u[1::2].size
    u[0::2][:min(n_ev, m)] = ev[:min(n_ev, m)]
    if n_ev > m:
        u[0::2][m:] = ev[-1]
    u[1::2][:min(n_od, m)] = od[:min(n_od, m)]
    if n_od > m:
        u[1::2][m:] = od[-1]
    return _rescale(u)


def _polish_final(best, bestR, deadline):
    for pad in [0.10, 0.06, 0.04]:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR = ht2.copy(), r2
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def _maybe_alt(h2, r2):
        nonlocal alt_best, alt_bestR
        if r2 > alt_bestR:
            alt_best, alt_bestR = h2.copy(), r2

    # ---- Phase 1: doubling-resolution lift work ----
    # Take the full-N start, extract its even/odd rows as a quotient, optimise
    # the quotient, then extrapolating-lift to 2N and fold back. This explores a
    # finer grid than the current start, which is the main lever for tiny gains.
    N0 = best.size
    if N0 % 2 == 0 and N0 >= 4:
        m = N0 // 2
        c = 0.5 * (best[0::2][:m] + best[1::2][:m])
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.22
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))

        # Try a few gammas for the extrapolating lift to 2N, then fold back to N.
        gammas = [0.0, 0.5, -0.5, 0.25, -0.25]
        lift_end = t0 + budget_seconds * 0.55
        for gi, gamma in enumerate(gammas):
            if time.process_time() >= lift_end - 1.0:
                break
            now = time.process_time()
            slice_dl = min(lift_end, now + 3.0)
            if slice_dl <= now + 0.5:
                break
            try:
                u = _lift_extrap(best_c, gamma, 2 * N0)
                r_pre = R_of(u)
                if time.process_time() < slice_dl - 0.4:
                    u = _lbfgs_all_pos(u, 250, slice_dl - 0.3, beta=1e6)
                if time.process_time() < slice_dl - 0.4:
                    u = _lbfgs_all_pos(u, 250, slice_dl - 0.3, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    win = _peak_window(u, pad_frac=0.08, extra=256)
                    u = _lbfgs_block(u, win, 250, slice_dl - 0.3, beta=1e7)
                # fold 2N back to N
                h2 = _rescale(0.5 * (u[0::2] + u[1::2]))[:N0]
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 250, slice_dl - 0.3, beta=1e6)
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 250, slice_dl - 0.3, beta=1e7)
                r_fold = R_of(h2)
                print("lift g=%.2f r_pre=%.9f r_fold=%.9f (best %.9f)" %
                      (gamma, r_pre, r_fold, bestR))
                if r_fold > bestR + 1e-13:
                    best, bestR, origin = h2.copy(), r_fold, 'lift_g%.2f' % gamma
                    print("  lift NEW BEST R=%.9f" % bestR)
                else:
                    _maybe_alt(h2, r_fold)
            except Exception as e:
                print("lift g=%.2f exception %s" % (gamma, e))

    # ---- Phase 2: 3x3 grid over (alpha, gamma) on the current best ----
    N = best.size
    m = N // 2
    if N % 2 == 0 and N >= 4 and m >= 2:
        alphas = [0.25, 0.5, 0.75]
        gammas = [-0.5, 0.0, 0.5]
        pairs = [(a, g) for a in alphas for g in gammas]
        cycle_end = deadline - 5.0
        pair_idx = 0
        max_pairs = 18
        while pair_idx < max_pairs and time.process_time() < cycle_end - 1.0:
            alpha, gamma = pairs[pair_idx % len(pairs)]
            pair_idx += 1
            now = time.process_time()
            slice_dl = min(cycle_end, now + 2.5)
            if slice_dl <= now + 0.5:
                break
            try:
                a_ev = best[0::2][:m]
                b_od = best[1::2][:m]
                L = min(a_ev.size, b_od.size)
                c = alpha * a_ev[:L] + (1.0 - alpha) * b_od[:L]
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
                cR0 = R_of(c)
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='a%.2fg%.2f' % (alpha, gamma),
                    pads=[0.30, 0.20, 0.12])
                u = _lift_extrap(cand_c, gamma, N)
                r_pre = R_of(u)
                if time.process_time() < slice_dl - 0.4:
                    u = _lbfgs_all_pos(u, 200, slice_dl - 0.3, beta=1e6)
                if time.process_time() < slice_dl - 0.4:
                    u = _lbfgs_all_pos(u, 200, slice_dl - 0.3, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    win = _peak_window(u, pad_frac=0.10, extra=256)
                    u = _lbfgs_block(u, win, 200, slice_dl - 0.3, beta=1e7)
                r_2n = R_of(u)
                h2 = _rescale(u.reshape(m, 2).mean(axis=0))
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 200, slice_dl - 0.3, beta=1e6)
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 200, slice_dl - 0.3, beta=1e7)
                r_fold = R_of(h2)
                print("grid a=%.2f g=%.2f R(c)=%.9f r_pre=%.9f r_2N=%.9f r_fold=%.9f (best %.9f)" %
                      (alpha, gamma, cand_cR, r_pre, r_2n, r_fold, bestR))
                if r_fold > bestR + 1e-13:
                    best, bestR, origin = h2.copy(), r_fold, 'grid_a%.2fg%.2f' % (alpha, gamma)
                    print("  grid NEW BEST R=%.9f" % bestR)
                else:
                    _maybe_alt(h2, r_fold)
            except Exception as e:
                print("grid a=%.2f g=%.2f exception %s" % (alpha, gamma, e))

    # ---- Phase 3: peak polish ----
    if time.process_time() < deadline - 1.0:
        best, bestR = _polish_final(best, bestR, deadline - 2.0)

    # ---- Phase 3b: randomized 2N lift multi-start ----
    phase3b_start = t0 + budget_seconds * 0.55
    phase3b_end = min(t0 + budget_seconds * 0.72, deadline - 4.0)
    if time.process_time() < phase3b_start:
        while time.process_time() < phase3b_start - 0.05:
            time.sleep(0.01)
    if time.process_time() < phase3b_end - 1.0 and best.size >= 2:
        n = best.size
        sigmas = [0.02, 0.05, 0.10, 0.03]
        rnd = 0
        while time.process_time() < phase3b_end - 1.0:
            sigma = sigmas[rnd % len(sigmas)]
            rnd += 1
            now = time.process_time()
            slice_dl = min(now + 2.0, deadline - 3.0)
            if slice_dl <= now + 0.3:
                break
            try:
                d = np.clip(sigma * np.random.randn(n), -0.6, 0.6)
                u = np.empty(2 * n)
                u[0::2] = best * (1.0 + d)
                u[1::2] = best * (1.0 - d)
                u = _rescale(u)
                u = _lbfgs_all_pos(u, 120, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    win = _peak_window(u, pad_frac=0.10, extra=128)
                    u = _lbfgs_block(u, win, 150, slice_dl, beta=1e7)
                h2 = _rescale(0.5 * (u[0::2] + u[1::2]))[:n]
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e6)
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e7)
                r_fold = R_of(h2)
                if r_fold > bestR + 1e-13:
                    best, bestR, origin = h2.copy(), r_fold, 'rnd%d' % rnd
                    print("  rnd NEW BEST R=%.9f" % bestR)
                else:
                    _maybe_alt(h2, r_fold)
            except Exception as e:
                print("rnd %d exception %s" % (rnd, e))

    # ---- Phase 4: final peak polish + trailing beta=0 ----
    if time.process_time() < deadline - 1.0:
        best, bestR = _polish_final(best, bestR, deadline)

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _flat_frac(h, tol=0.001):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _extend_side(best, side, K, deadline):
    """Build ramped extension of K cells on given side, polish, return (h, R)."""
    n = best.size
    A = np.flatnonzero(best > 0)
    if A.size < 2:
        return best, R_of(best)
    lo = int(A[0]); hi = int(A[-1])
    if side == 'left':
        h2 = np.concatenate((np.zeros(K), best))
        v0 = best[lo]
        if v0 <= 0:
            return best, R_of(best)
        s = (best[lo + 1] - best[lo]) / v0 if lo + 1 < n else 0.0
        s = float(np.clip(s, -1.0, 1.0))
        j = np.arange(K, dtype=float)
        vals = v0 * (1.0 + (K - j) / K * s)
        vals = np.clip(vals, 0.0, 1.5 * v0)
        h2[:K] = vals
        newcells = np.arange(K)
    else:
        h2 = np.concatenate((best, np.zeros(K)))
        v0 = best[hi]
        if v0 <= 0:
            return best, R_of(best)
        s = (best[hi] - best[hi - 1]) / v0 if hi - 1 >= 0 else 0.0
        s = float(np.clip(s, -1.0, 1.0))
        j = np.arange(K, dtype=float)
        vals = v0 * (1.0 + (j + 1) / K * s)
        vals = np.clip(vals, 0.0, 1.5 * v0)
        h2[n:] = vals
        newcells = np.arange(n, n + K)
    h2 = _rescale(h2)
    # polish new cells
    h2 = _lbfgs_block(h2, newcells, 200, deadline, beta=1e7)
    for beta in [1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        h2 = _lbfgs_all_pos(h2, 300, deadline - 0.3, beta=beta)
    if time.process_time() < deadline - 0.5:
        win = _peak_window(h2, pad_frac=0.08, extra=128)
        h2 = _lbfgs_block(h2, win, 400, deadline - 0.3, beta=1e7)
    return h2, R_of(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient search ----
    best_c = None
    best_cR = -1.0
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.25
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: 3-variant rotation of extract/lift cycles ----
    N = best.size
    m = N // 2
    cyc = 0
    variant_hits = [0.0, 0.0, 0.0]
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 5.0
        max_cycles = 6
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 4.0, now + 0.07 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]
                b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception as e:
                print("cycle %d variant %d exception %s" % (cyc, k, e))
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception as e:
                print("lift %d variant %d exception %s" % (cyc, k, e))
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                variant_hits[k] = max(variant_hits[k], r)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            if r > bestR - 1e-5:
                variant_hits[k] = max(variant_hits[k], r)
        print("rotation cycles=%d wR=%s" %
              (cyc, ["%.9f" % x for x in wR]))

    # ---- Phase 3: reserve last ~5s for peak-window + beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    # ---- Phase 3x (NEW): ramped support extension ----
    ext_start = t0 + budget_seconds * 0.40
    ext_end = deadline - 6.0
    if time.process_time() < ext_start:
        while time.process_time() < ext_start - 0.05:
            time.sleep(0.01)
    if time.process_time() < ext_end - 1.0 and best.size >= 4:
        Lf0 = _knots(best)
        print("ext: start inf=%.6f flat0.1%%=%.4f N=%d" %
              (Lf0.max(), _flat_frac(best), best.size))
        side_gain = {'left': 0.0, 'right': 0.0}
        rnd = 0
        max_rounds = 8
        while rnd < max_rounds and time.process_time() < ext_end - 1.0:
            rnd += 1
            side = 'left' if (rnd % 2 == 1) else 'right'
            improved_this = False
            for K in (16, 32, 64):
                if time.process_time() >= ext_end - 1.0:
                    break
                now = time.process_time()
                slice_dl = min(ext_end, now + max(1.5, 0.08 * budget_seconds))
                if slice_dl <= now + 0.5:
                    break
                base_arr = best.copy()
                base_R = bestR
                inf_before = _knots(base_arr).max()
                try:
                    h2, r2 = _extend_side(base_arr, side, K, slice_dl)
                except Exception as e:
                    print("ext %s K=%d exception %s" % (side, K, e))
                    continue
                inf_after = _knots(h2).max() if h2.size > 0 else 0.0
                print("ext r%d %s K=%d R=%.9f (best %.9f) inf %.6f->%.6f flat %.4f" %
                      (rnd, side, K, r2, bestR, inf_before, inf_after,
                       _flat_frac(h2)))
                if r2 > bestR + 1e-13:
                    side_gain[side] += (r2 - bestR)
                    best, bestR = h2.copy(), r2
                    origin = 'ext_%s%d' % (side, K)
                    improved_this = True
                    print("  ext NEW BEST R=%.9f (%s K=%d)" % (bestR, side, K))
                elif r2 > alt_bestR:
                    alt_best, alt_bestR = h2.copy(), r2
            if not improved_this:
                # try other side once before giving up
                side2 = 'right' if side == 'left' else 'left'
                if time.process_time() >= ext_end - 1.0:
                    break
                for K in (16, 32):
                    if time.process_time() >= ext_end - 1.0:
                        break
                    now = time.process_time()
                    slice_dl = min(ext_end, now + max(1.5, 0.08 * budget_seconds))
                    if slice_dl <= now + 0.5:
                        break
                    try:
                        h2, r2 = _extend_side(best.copy(), side2, K, slice_dl)
                    except Exception:
                        continue
                    if r2 > bestR + 1e-13:
                        side_gain[side2] += (r2 - bestR)
                        best, bestR = h2.copy(), r2
                        origin = 'ext_%s%d' % (side2, K)
                        improved_this = True
                        print("  ext NEW BEST R=%.9f (%s K=%d)" % (bestR, side2, K))
                    elif r2 > alt_bestR:
                        alt_best, alt_bestR = h2.copy(), r2
                if not improved_this:
                    break
        # shrink round: drop outermost 16 cells on side that improved least
        if time.process_time() < ext_end - 1.0 and best.size > 32:
            drop_side = 'left' if side_gain['left'] <= side_gain['right'] else 'right'
            Kd = min(16, best.size // 4)
            if drop_side == 'left':
                h2 = best[Kd:].copy()
            else:
                h2 = best[:-Kd].copy()
            h2 = _rescale(h2)
            now = time.process_time()
            slice_dl = min(ext_end, now + max(1.5, 0.08 * budget_seconds))
            if slice_dl > now + 0.5:
                for beta in [1e6, 1e7]:
                    if time.process_time() >= slice_dl - 0.5:
                        break
                    h2 = _lbfgs_all_pos(h2, 300, slice_dl - 0.3, beta=beta)
                if time.process_time() < slice_dl - 0.5:
                    win = _peak_window(h2, pad_frac=0.08, extra=128)
                    h2 = _lbfgs_block(h2, win, 400, slice_dl - 0.3, beta=1e7)
                r2 = R_of(h2)
                print("shrink %s Kd=%d R=%.9f (best %.9f)" %
                      (drop_side, Kd, r2, bestR))
                if r2 > bestR + 1e-13:
                    best, bestR = h2.copy(), r2
                    origin = 'shrink_%s' % drop_side
                    print("  shrink NEW BEST R=%.9f" % bestR)
                elif r2 > alt_bestR:
                    alt_best, alt_bestR = h2.copy(), r2
        print("ext done rounds=%d side_gain L=%.2e R=%.2e bestR=%.9f N=%d" %
              (rnd, side_gain['left'], side_gain['right'], bestR, best.size))

    # ---- Phase 4: final peak pads + beta=0 ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _refine(h, r, deadline, tag="", rounds=6):
    """Iterate: smooth-max ascent + local peak-window block refinement."""
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        improved = False
        for beta in (1e4, 1e5, 1e6):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(h, 200, deadline - 0.3, beta=beta)
            rt = R_of(ht)
            if rt > r + 1e-14:
                h, r, improved = ht, rt, True
        for pad in (0.30, 0.15, 0.07, 0.03):
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(h, pad_frac=pad)
            ht = _lbfgs_block(h, win, 300, deadline - 0.3)
            rt = R_of(ht)
            if rt > r + 1e-14:
                h, r, improved = ht, rt, True
        if not improved:
            break
    return h, r


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    return np.clip(np.diff(c_new), 0.0, None)


def _smooth_tilt(h, slope, center=0.5):
    n = h.size
    x = np.linspace(0.0, 1.0, n)
    return _rescale(h * np.exp(slope * (x - center)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    best = None
    best_r = -1.0

    # ---- Phase 1: refine start directly ----
    if start_arr is not None:
        h = start_arr.copy()
        r = R_of(h)
        print("start base R=%.6f N=%d" % (r, h.size))
        h, r = _refine(h, r, deadline - 2.0, "start")
        if r > best_r:
            best, best_r = h, r
        print("start-refined R=%.6f (was %.6f)" % (best_r, start_r))

    # ---- Phase 2: tilted perturbations of the start ----
    if start_arr is not None and time.process_time() < deadline - 8.0:
        for slope in (0.15, -0.15, 0.40, -0.40):
            if time.process_time() >= deadline - 5.0:
                break
            cand = _smooth_tilt(start_arr, slope)
            cand, r2 = _refine(cand, R_of(cand), deadline - 1.0, "tilt", rounds=3)
            if r2 > best_r:
                best, best_r = cand, r2
        if best_r > start_r + 1e-12:
            print("tilt improved R=%.6f" % best_r)

    # ---- Phase 3: prolongation to larger N ----
    if best is not None and time.process_time() < deadline - 8.0:
        for m in (best.size * 2, min(best.size * 4, 1 << 20)):
            if m <= best.size or time.process_time() >= deadline - 6.0:
                continue
            cand = _rescale(_prolong(best, int(m)))
            cand, r2 = _refine(cand, R_of(cand), deadline - 2.0, "prolong", rounds=4)
            if r2 > best_r:
                best, best_r = cand, r2
                print("prolong N=%d R=%.6f" % (best.size, best_r))

    # ---- Fallback fresh build ----
    if best is None:
        N = 256
        x = np.linspace(0, 1, N)
        h = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        cur_r = R_of(h)
        while N <= 65536 and time.process_time() < deadline - 4.0:
            h, cur_r = _refine(h, cur_r, deadline - 2.0, "fresh", rounds=3)
            N *= 2
            h = _rescale(_prolong(h, N))
            cur_r = R_of(h)
        best, best_r = h, cur_r

    # ---- Final push until deadline ----
    if best is not None:
        best, best_r = _refine(best, best_r, deadline - 0.2, "final", rounds=20)

    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    if start_arr is not None:
        if best is not None and best_r > start_r + 1e-12:
            return {"best": _rescale(best), "alternative": _rescale(start_arr)}
        if best is not None and not np.array_equal(best, start_arr) and best_r > 0:
            return {"best": _rescale(start_arr), "alternative": _rescale(best)}
        return _rescale(start_arr)
    return _rescale(best)

