        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _zf(h):
    return float(np.mean(h == 0))


def _upsample2(h):
    n = h.size
    out = np.empty(2 * n - 1)
    out[0::2] = h
    out[1::2] = 0.5 * (h[:-1] + h[1:])
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def _maybe_record(cand):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        r = R_of(cand)
        if r > bestR + 1e-13:
            best, bestR = cand.copy(), r
            origin = 'up'
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- KEY NEW IDEA: work at DOUBLE resolution ----
    # Build a 2x-refined candidate from best via linear interpolation of the
    # autoconvolution peak region, then optimise at full resolution. This lets
    # the optimiser discover finer detail than the start's grid, which is the
    # only way to gain the last few e-6 on a saturated construction.
    if time.process_time() < deadline - 2.0:
        N0 = best.size
        h2 = _upsample2(best)
        h2 = _rescale(np.clip(h2, 0, None))
        r2 = R_of(h2)
        print("upsample R=%.9f (vs %.9f)" % (r2, bestR))
        # refine at doubled resolution
        slice_dl = min(deadline - 1.0, time.process_time() + 0.35 * budget_seconds)
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= slice_dl - 0.5:
                break
            h2 = _lbfgs_all_pos(h2, 400, slice_dl - 0.3, beta=beta)
        r2 = R_of(h2)
        print("upsample refined R=%.9f" % r2)
        if r2 > bestR + 1e-13:
            best, bestR, origin = h2.copy(), r2, 'up2x'
            print("  UPSAMPLE NEW BEST R=%.9f" % bestR)
        elif r2 > alt_bestR:
            alt_best, alt_bestR = h2.copy(), r2

    # ---- Phase 1: half-resolution quotient search (from best) ----
    best_c = None
    best_cR = -1.0
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = min(deadline - 5.0, time.process_time() + 0.18 * budget_seconds)
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: rotation of extract/lift cycles ----
    N = best.size
    m = N // 2
    cyc = 0
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 5.0
        max_cycles = 6
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 4.0, now + 0.06 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]
                b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception as e:
                print("cycle %d variant %d exception %s" % (cyc, k, e))
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception as e:
                print("lift %d variant %d exception %s" % (cyc, k, e))
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        print("rotation cycles=%d wR=%s" %
              (cyc, ["%.9f" % x for x in wR]))

    # ---- Phase 3: staged perturb+polish chain, all remaining time ----
    rng = np.random.RandomState(246813579)
    attempt = 0
    accepted_total = 0
    chain_end = deadline - 3.0

    while time.process_time() < chain_end - 1.0:
        now = time.process_time()
        slice_dl = min(now + 2.5, chain_end)
        if slice_dl <= now + 0.5:
            break
        attempt += 1
        try:
            # Mix of strategies: block perturbation, upsample, peak polish
            choice = rng.randint(4)
            cand = best.copy()
            Ncur = cand.size
            if choice == 0:
                # block perturbation on active region
                Bopts = [max(8, Ncur // 200), max(8, Ncur // 60),
                         max(8, Ncur // 20)]
                B = Bopts[rng.randint(len(Bopts))]
                sigma = [0.004, 0.015, 0.05][rng.randint(3)]
                eps = [3e-3, 1e-2][rng.randint(2)]
                thr = [1e-4, 1e-3, 3e-3][rng.randint(3)]
                nz = np.flatnonzero(cand > 0)
                if nz.size < 4:
                    continue
                mean_act = cand[nz].mean()
                if Ncur <= B:
                    s0, Bc = 0, Ncur
                else:
                    s0 = rng.randint(0, Ncur - B + 1)
                    Bc = B
                blk = cand[s0:s0 + Bc] * np.exp(sigma * rng.randn(Bc))
                z = (blk == 0)
                if np.any(z):
                    blk[z] = eps * mean_act
                cand[s0:s0 + Bc] = blk
                cand = _rescale(np.clip(cand, 0, None))
                win = _peak_window(cand, pad_frac=0.05, extra=128)
                cand = _lbfgs_block(cand, win, 250, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    cand = _lbfgs_all_pos(cand, 200, slice_dl, beta=0.0)
                mx = cand.max()
                if mx > 0:
                    cand[cand < thr * mx] = 0.0
                cand = _rescale(np.clip(cand, 0, None))
                if time.process_time() < slice_dl - 0.4:
                    cand = _lbfgs_all_pos(cand, 150, slice_dl, beta=1e7)
            elif choice == 1:
                # upsample-then-optimise (fine detail discovery)
                h2 = _upsample2(cand)
                h2 = _rescale(np.clip(h2, 0, None))
                for beta in [1e6, 1e7, 0.0]:
                    if time.process_time() >= slice_dl - 0.4:
                        break
                    h2 = _lbfgs_all_pos(h2, 250, slice_dl - 0.3, beta=beta)
                cand = h2  # different size
            elif choice == 2:
                # dilate then average (variant B from original)
                h2 = np.zeros(2 * Ncur - 1)
                h2[0::2] = cand
                h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e6)
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e7)
                ev = h2[0::2]
                od = h2[1::2]
                L = min(ev.size, od.size)
                new = 0.5 * (ev[:L] + od[:L])
                if new.size < Ncur:
                    new = np.concatenate(
                        (new, np.full(Ncur - new.size, new[-1])))
                cand = _rescale(np.clip(new[:Ncur], 0, None))
                if time.process_time() < slice_dl - 0.4:
                    cand = _lbfgs_all_pos(cand, 250, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    cand = _lbfgs_all_pos(cand, 150, slice_dl, beta=0.0)
            else:
                # peak-window polish at multiple scales
                for pad in [0.10, 0.05, 0.03]:
                    if time.process_time() >= slice_dl - 0.5:
                        break
                    win = _peak_window(cand, pad_frac=pad, extra=128)
                    cand = _lbfgs_block(cand, win, 300, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    cand = _lbfgs_all_pos(cand, 200, slice_dl, beta=0.0)
            r2 = R_of(cand)
            acc = r2 > bestR + 1e-13
            if acc:
                best, bestR = cand.copy(), r2
                origin = 'chain%d' % attempt
                accepted_total += 1
                print("chain acc choice=%d R=%.9f (best %.9f)" %
                      (choice, r2, bestR))
            elif r2 > alt_bestR and cand.size == best.size:
                alt_best, alt_bestR = cand.copy(), r2
        except Exception as e:
            print("chain attempt %d exception %s" % (attempt, e))
            continue

    print("chain attempts=%d accepted=%d bestR=%.9f" %
          (attempt, accepted_total, bestR))

    # ---- Final polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR and ht2.size == best.size:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR and ht.size == best.size:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR \
            and alt_bestR > -1:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _zf(h):
    return float(np.mean(h == 0))


def _upsample2(h):
    n = h.size
    out = np.empty(2 * n - 1)
    out[0::2] = h
    out[1::2] = 0.5 * (h[:-1] + h[1:])
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def _maybe_record(cand):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        r = R_of(cand)
        if r > bestR + 1e-13:
            best, bestR = cand.copy(), r
            origin = 'up'
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- KEY NEW IDEA: work at DOUBLE resolution ----
    # Build a 2x-refined candidate from best via linear interpolation of the
    # autoconvolution peak region, then optimise at full resolution. This lets
    # the optimiser discover finer detail than the start's grid, which is the
    # only way to gain the last few e-6 on a saturated construction.
    if time.process_time() < deadline - 2.0:
        N0 = best.size
        h2 = _upsample2(best)
        h2 = _rescale(np.clip(h2, 0, None))
        r2 = R_of(h2)
        print("upsample R=%.9f (vs %.9f)" % (r2, bestR))
        # refine at doubled resolution
        slice_dl = min(deadline - 1.0, time.process_time() + 0.35 * budget_seconds)
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= slice_dl - 0.5:
                break
            h2 = _lbfgs_all_pos(h2, 400, slice_dl - 0.3, beta=beta)
        r2 = R_of(h2)
        print("upsample refined R=%.9f" % r2)
        if r2 > bestR + 1e-13:
            best, bestR, origin = h2.copy(), r2, 'up2x'
            print("  UPSAMPLE NEW BEST R=%.9f" % bestR)
        elif r2 > alt_bestR:
            alt_best, alt_bestR = h2.copy(), r2

    # ---- Phase 1: half-resolution quotient search (from best) ----
    best_c = None
    best_cR = -1.0
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = min(deadline - 5.0, time.process_time() + 0.18 * budget_seconds)
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: rotation of extract/lift cycles ----
    N = best.size
    m = N // 2
    cyc = 0
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 5.0
        max_cycles = 6
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 4.0, now + 0.06 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]
                b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception as e:
                print("cycle %d variant %d exception %s" % (cyc, k, e))
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception as e:
                print("lift %d variant %d exception %s" % (cyc, k, e))
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        print("rotation cycles=%d wR=%s" %
              (cyc, ["%.9f" % x for x in wR]))

    # ---- Phase 3: staged perturb+polish chain, all remaining time ----
    rng = np.random.RandomState(246813579)
    attempt = 0
    accepted_total = 0
    chain_end = deadline - 3.0

    while time.process_time() < chain_end - 1.0:
        now = time.process_time()
        slice_dl = min(now + 2.5, chain_end)
        if slice_dl <= now + 0.5:
            break
        attempt += 1
        try:
            # Mix of strategies: block perturbation, upsample, peak polish
            choice = rng.randint(4)
            cand = best.copy()
            Ncur = cand.size
            if choice == 0:
                # block perturbation on active region
                Bopts = [max(8, Ncur // 200), max(8, Ncur // 60),
                         max(8, Ncur // 20)]
                B = Bopts[rng.randint(len(Bopts))]
                sigma = [0.004, 0.015, 0.05][rng.randint(3)]
                eps = [3e-3, 1e-2][rng.randint(2)]
                thr = [1e-4, 1e-3, 3e-3][rng.randint(3)]
                nz = np.flatnonzero(cand > 0)
                if nz.size < 4:
                    continue
                mean_act = cand[nz].mean()
                if Ncur <= B:
                    s0, Bc = 0, Ncur
                else:
                    s0 = rng.randint(0, Ncur - B + 1)
                    Bc = B
                blk = cand[s0:s0 + Bc] * np.exp(sigma * rng.randn(Bc))
                z = (blk == 0)
                if np.any(z):
                    blk[z] = eps * mean_act
                cand[s0:s0 + Bc] = blk
                cand = _rescale(np.clip(cand, 0, None))
                win = _peak_window(cand, pad_frac=0.05, extra=128)
                cand = _lbfgs_block(cand, win, 250, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    cand = _lbfgs_all_pos(cand, 200, slice_dl, beta=0.0)
                mx = cand.max()
                if mx > 0:
                    cand[cand < thr * mx] = 0.0
                cand = _rescale(np.clip(cand, 0, None))
                if time.process_time() < slice_dl - 0.4:
                    cand = _lbfgs_all_pos(cand, 150, slice_dl, beta=1e7)
            elif choice == 1:
                # upsample-then-optimise (fine detail discovery)
                h2 = _upsample2(cand)
                h2 = _rescale(np.clip(h2, 0, None))
                for beta in [1e6, 1e7, 0.0]:
                    if time.process_time() >= slice_dl - 0.4:
                        break
                    h2 = _lbfgs_all_pos(h2, 250, slice_dl - 0.3, beta=beta)
                cand = h2  # different size
            elif choice == 2:
                # dilate then average (variant B from original)
                h2 = np.zeros(2 * Ncur - 1)
                h2[0::2] = cand
                h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e6)
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e7)
                ev = h2[0::2]
                od = h2[1::2]
                L = min(ev.size, od.size)
                new = 0.5 * (ev[:L] + od[:L])
                if new.size < Ncur:
                    new = np.concatenate(
                        (new, np.full(Ncur - new.size, new[-1])))
                cand = _rescale(np.clip(new[:Ncur], 0, None))
                if time.process_time() < slice_dl - 0.4:
                    cand = _lbfgs_all_pos(cand, 250, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    cand = _lbfgs_all_pos(cand, 150, slice_dl, beta=0.0)
            else:
                # peak-window polish at multiple scales
                for pad in [0.10, 0.05, 0.03]:
                    if time.process_time() >= slice_dl - 0.5:
                        break
                    win = _peak_window(cand, pad_frac=pad, extra=128)
                    cand = _lbfgs_block(cand, win, 300, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    cand = _lbfgs_all_pos(cand, 200, slice_dl, beta=0.0)
            r2 = R_of(cand)
            acc = r2 > bestR + 1e-13
            if acc:
                best, bestR = cand.copy(), r2
                origin = 'chain%d' % attempt
                accepted_total += 1
                print("chain acc choice=%d R=%.9f (best %.9f)" %
                      (choice, r2, bestR))
            elif r2 > alt_bestR and cand.size == best.size:
                alt_best, alt_bestR = cand.copy(), r2
        except Exception as e:
            print("chain attempt %d exception %s" % (attempt, e))
            continue

    print("chain attempts=%d accepted=%d bestR=%.9f" %
          (attempt, accepted_total, bestR))

    # ---- Final polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR and ht2.size == best.size:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR and ht.size == best.size:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR \
            and alt_bestR > -1:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _fold_back(h3, N):
    F = np.concatenate(([0.0], np.cumsum(h3)))
    L = h3.size
    xs = np.linspace(0.0, L, N + 1)
    vals = np.interp(xs, np.arange(L + 1, dtype=float), F)
    out = np.diff(vals)
    return _rescale(np.clip(out, 0.0, None))


def _near_max_shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient search (cut to 0.30*budget) ----
    best_c = None
    best_cR = -1.0
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.15
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: 3-variant rotation, cut to finish by t0+0.30*budget ----
    N = best.size
    m = N // 2
    cyc = 0
    variant_hits = [0.0, 0.0, 0.0]
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = t0 + budget_seconds * 0.30
        max_cycles = 6
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(cycle_end, now + 0.05 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]
                b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception as e:
                print("cycle %d variant %d exception %s" % (cyc, k, e))
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception as e:
                print("lift %d variant %d exception %s" % (cyc, k, e))
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                variant_hits[k] = max(variant_hits[k], r)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            if r > bestR - 1e-5:
                variant_hits[k] = max(variant_hits[k], r)
        print("rotation cycles=%d wR=%s" %
              (cyc, ["%.9f" % x for x in wR]))

    # ---- Phase 3: 2x midpoint-split refinement at N2 = 2*N ----
    N = best.size
    N2 = 2 * N
    rng = np.random.RandomState(4242)
    a = 0.08 * rng.randn(N)
    h2 = np.empty(N2)
    h2[0::2] = best * (1.0 + a)
    h2[1::2] = best * (1.0 - a)
    h2 = _rescale(np.clip(h2, 0.0, None))
    r2 = R_of(h2)
    print("N2=%d initial R@N2=%.9f (start %.9f)" % (N2, r2, start_bestR))

    bestN2 = h2.copy()
    bestN2R = r2
    origin2 = 'split'

    def _round(h2, bestN2, bestN2R, origin2, tag):
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            h2 = _lbfgs_all_pos(h2, 150, deadline - 0.5, beta=beta)
        if time.process_time() < deadline - 1.0:
            win = _peak_window(h2, pad_frac=0.08, extra=512)
            h2 = _lbfgs_block(h2, win, 250, deadline - 0.5, beta=1e7)
        if time.process_time() < deadline - 1.0:
            win = _peak_window(h2, pad_frac=0.04, extra=256)
            h2 = _lbfgs_block(h2, win, 250, deadline - 0.5, beta=1e7)
        if time.process_time() < deadline - 1.0:
            h2 = _lbfgs_all_pos(h2, 200, deadline - 0.5, beta=0.0)
        r = R_of(h2)
        folded = _fold_back(h2, N)
        rfold = R_of(folded)
        zf = float(np.mean(h2 == 0))
        sh = _near_max_shares(h2)
        print("%s R@N2=%.9f foldedR=%.9f zf=%.4f shares=%.4f/%.4f/%.4f"
              % (tag, r, rfold, zf, sh[0], sh[1], sh[2]))
        if r > bestN2R + 1e-14:
            bestN2, bestN2R, origin2 = h2.copy(), r, tag
        return h2, bestN2, bestN2R, origin2, folded, rfold

    h2, bestN2, bestN2R, origin2, folded, rfold = _round(
        h2, bestN2, bestN2R, origin2, 'round1')

    # second round
    if time.process_time() < deadline - 2.0:
        h2, bestN2, bestN2R, origin2, folded, rfold = _round(
            bestN2, bestN2, bestN2R, origin2, 'round2')

    # ---- Phase 4: alternate full-res beta polishes with peak windows at N2 ----
    pads = [0.06, 0.03]
    pi = 0
    while time.process_time() < deadline - 5.5:
        now = time.process_time()
        if now >= deadline - 5.5:
            break
        if pi % 2 == 0:
            ht = _lbfgs_all_pos(bestN2, 200, deadline - 5.0, beta=1e7)
        else:
            ht = _lbfgs_all_pos(bestN2, 200, deadline - 5.0, beta=0.0)
        r = R_of(ht)
        if r > bestN2R + 1e-14:
            bestN2, bestN2R, origin2 = ht.copy(), r, origin2 + '+full'
            print("full polish NEW BEST R@N2=%.9f" % bestN2R)
        pad = pads[pi % 2]
        win = _peak_window(bestN2, pad_frac=pad, extra=256)
        ht = _lbfgs_block(bestN2, win, 250, deadline - 5.0, beta=1e7)
        r = R_of(ht)
        if r > bestN2R + 1e-14:
            bestN2, bestN2R, origin2 = ht.copy(), r, origin2 + '+pk'
            print("peak pad=%.2f NEW BEST R@N2=%.9f" % (pad, bestN2R))
        pi += 1

    # ---- Phase 5: reserve last ~5s for final beta=0 at N2 ----
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(bestN2, 400, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestN2R + 1e-14:
            bestN2, bestN2R, origin2 = ht.copy(), r, origin2 + '+b0'
            print("final beta0 NEW BEST R@N2=%.9f" % bestN2R)

    # cross-check folded
    folded = _fold_back(bestN2, N)
    rfold = R_of(folded)
    print("final N2=%d R@N2=%.9f foldedR=%.9f zf=%.4f shares=%.4f/%.4f/%.4f"
          % (N2, bestN2R, rfold, float(np.mean(bestN2 == 0)),
             *_near_max_shares(bestN2)))

    # Decide what to return
    result = {}
    if bestN2R > bestR + 1e-14:
        # N2 array is better
        if rfold > bestN2R + 1e-14:
            result["best"] = folded
            print("returning folded N=%d R=%.9f" % (folded.size, rfold))
        else:
            result["best"] = bestN2
            print("returning N2=%d R=%.9f origin=%s" % (N2, bestN2R, origin2))
    else:
        result["best"] = best
        print("returning start N=%d R=%.9f (N2 did not improve)" % (best.size, bestR))
        if bestN2R > -1:
            result["alternative"] = bestN2
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _fold_back(h3, N):
    F = np.concatenate(([0.0], np.cumsum(h3)))
    L = h3.size
    xs = np.linspace(0.0, L, N + 1)
    vals = np.interp(xs, np.arange(L + 1, dtype=float), F)
    out = np.diff(vals)
    return _rescale(np.clip(out, 0.0, None))


def _near_max_shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient search (cut to 0.30*budget) ----
    best_c = None
    best_cR = -1.0
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.15
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: 3-variant rotation, cut to finish by t0+0.30*budget ----
    N = best.size
    m = N // 2
    cyc = 0
    variant_hits = [0.0, 0.0, 0.0]
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = t0 + budget_seconds * 0.30
        max_cycles = 6
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(cycle_end, now + 0.05 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]
                b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception as e:
                print("cycle %d variant %d exception %s" % (cyc, k, e))
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception as e:
                print("lift %d variant %d exception %s" % (cyc, k, e))
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                variant_hits[k] = max(variant_hits[k], r)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            if r > bestR - 1e-5:
                variant_hits[k] = max(variant_hits[k], r)
        print("rotation cycles=%d wR=%s" %
              (cyc, ["%.9f" % x for x in wR]))

    # ---- Phase 3: 2x midpoint-split refinement at N2 = 2*N ----
    N = best.size
    N2 = 2 * N
    rng = np.random.RandomState(4242)
    a = 0.08 * rng.randn(N)
    h2 = np.empty(N2)
    h2[0::2] = best * (1.0 + a)
    h2[1::2] = best * (1.0 - a)
    h2 = _rescale(np.clip(h2, 0.0, None))
    r2 = R_of(h2)
    print("N2=%d initial R@N2=%.9f (start %.9f)" % (N2, r2, start_bestR))

    bestN2 = h2.copy()
    bestN2R = r2
    origin2 = 'split'

    def _round(h2, bestN2, bestN2R, origin2, tag):
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            h2 = _lbfgs_all_pos(h2, 150, deadline - 0.5, beta=beta)
        if time.process_time() < deadline - 1.0:
            win = _peak_window(h2, pad_frac=0.08, extra=512)
            h2 = _lbfgs_block(h2, win, 250, deadline - 0.5, beta=1e7)
        if time.process_time() < deadline - 1.0:
            win = _peak_window(h2, pad_frac=0.04, extra=256)
            h2 = _lbfgs_block(h2, win, 250, deadline - 0.5, beta=1e7)
        if time.process_time() < deadline - 1.0:
            h2 = _lbfgs_all_pos(h2, 200, deadline - 0.5, beta=0.0)
        r = R_of(h2)
        folded = _fold_back(h2, N)
        rfold = R_of(folded)
        zf = float(np.mean(h2 == 0))
        sh = _near_max_shares(h2)
        print("%s R@N2=%.9f foldedR=%.9f zf=%.4f shares=%.4f/%.4f/%.4f"
              % (tag, r, rfold, zf, sh[0], sh[1], sh[2]))
        if r > bestN2R + 1e-14:
            bestN2, bestN2R, origin2 = h2.copy(), r, tag
        return h2, bestN2, bestN2R, origin2, folded, rfold

    h2, bestN2, bestN2R, origin2, folded, rfold = _round(
        h2, bestN2, bestN2R, origin2, 'round1')

    # second round
    if time.process_time() < deadline - 2.0:
        h2, bestN2, bestN2R, origin2, folded, rfold = _round(
            bestN2, bestN2, bestN2R, origin2, 'round2')

    # ---- Phase 4: alternate full-res beta polishes with peak windows at N2 ----
    pads = [0.06, 0.03]
    pi = 0
    while time.process_time() < deadline - 5.5:
        now = time.process_time()
        if now >= deadline - 5.5:
            break
        if pi % 2 == 0:
            ht = _lbfgs_all_pos(bestN2, 200, deadline - 5.0, beta=1e7)
        else:
            ht = _lbfgs_all_pos(bestN2, 200, deadline - 5.0, beta=0.0)
        r = R_of(ht)
        if r > bestN2R + 1e-14:
            bestN2, bestN2R, origin2 = ht.copy(), r, origin2 + '+full'
            print("full polish NEW BEST R@N2=%.9f" % bestN2R)
        pad = pads[pi % 2]
        win = _peak_window(bestN2, pad_frac=pad, extra=256)
        ht = _lbfgs_block(bestN2, win, 250, deadline - 5.0, beta=1e7)
        r = R_of(ht)
        if r > bestN2R + 1e-14:
            bestN2, bestN2R, origin2 = ht.copy(), r, origin2 + '+pk'
            print("peak pad=%.2f NEW BEST R@N2=%.9f" % (pad, bestN2R))
        pi += 1

    # ---- Phase 5: reserve last ~5s for final beta=0 at N2 ----
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(bestN2, 400, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestN2R + 1e-14:
            bestN2, bestN2R, origin2 = ht.copy(), r, origin2 + '+b0'
            print("final beta0 NEW BEST R@N2=%.9f" % bestN2R)

    # cross-check folded
    folded = _fold_back(bestN2, N)
    rfold = R_of(folded)
    print("final N2=%d R@N2=%.9f foldedR=%.9f zf=%.4f shares=%.4f/%.4f/%.4f"
          % (N2, bestN2R, rfold, float(np.mean(bestN2 == 0)),
             *_near_max_shares(bestN2)))

    # Decide what to return
    result = {}
    if bestN2R > bestR + 1e-14:
        # N2 array is better
        if rfold > bestN2R + 1e-14:
            result["best"] = folded
            print("returning folded N=%d R=%.9f" % (folded.size, rfold))
        else:
            result["best"] = bestN2
            print("returning N2=%d R=%.9f origin=%s" % (N2, bestN2R, origin2))
    else:
        result["best"] = best
        print("returning start N=%d R=%.9f (N2 did not improve)" % (best.size, bestR))
        if bestN2R > -1:
            result["alternative"] = bestN2
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _fold_back(h3, N):
    F = np.concatenate(([0.0], np.cumsum(h3)))
    L = h3.size
    xs = np.linspace(0.0, L, N + 1)
    vals = np.interp(xs, np.arange(L + 1, dtype=float), F)
    out = np.diff(vals)
    return _rescale(np.clip(out, 0.0, None))


def _split3(q, rng):
    N = q.size
    L = (3 * N) // 2
    h3 = np.zeros(L)
    nfull = L // 3
    w = np.exp(0.45 * rng.randn(3))
    w = w * (3.0 / w.sum())
    for i in range(nfull):
        h3[3 * i:3 * i + 3] = q[i] * w
    rem = L - 3 * nfull
    if rem > 0:
        h3[3 * nfull:] = q[nfull] * w[:rem]
    return _rescale(h3)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient polish (short) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.25
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: non-commensurate 3/2 split-lift rounds ----
    jit_start = t0 + budget_seconds * 0.30
    jit_end = deadline - 7.0
    if time.process_time() < jit_start:
        while time.process_time() < jit_start - 0.05:
            time.sleep(0.01)
    if time.process_time() < jit_end - 1.0 and best.size >= 8:
        rnd = 0
        while time.process_time() < jit_end - 1.0:
            now = time.process_time()
            slice_dl = min(now + 7.0, deadline - 7.0)
            if slice_dl <= now + 0.8:
                break
            Ncur = best.size
            rng = np.random.RandomState(97531 + rnd)
            h3 = _split3(best, rng)
            L = h3.size
            for beta in [1e5, 1e6, 1e7]:
                if time.process_time() >= slice_dl - 0.6:
                    break
                h3 = _lbfgs_all_pos(h3, 120, slice_dl - 0.3, beta=beta)
            if time.process_time() < slice_dl - 0.6:
                win = _peak_window(h3, pad_frac=0.08, extra=512)
                h3 = _lbfgs_block(h3, win, 250, slice_dl - 0.3, beta=1e7)
            if time.process_time() < slice_dl - 0.6:
                win = _peak_window(h3, pad_frac=0.04, extra=256)
                h3 = _lbfgs_block(h3, win, 250, slice_dl - 0.3, beta=1e7)
            rL = R_of(h3)

            # every second round: nested 9N/4 expansion before folding
            if (rnd % 2 == 1) and time.process_time() < slice_dl - 0.6:
                rng2 = np.random.RandomState(97531 + rnd + 1000)
                h3b = _split3(h3, rng2)
                if time.process_time() < slice_dl - 0.5:
                    h3b = _lbfgs_all_pos(h3b, 100, slice_dl - 0.3, beta=1e7)
                h3 = h3b
                rL = R_of(h3)

            folded = _fold_back(h3, Ncur)
            if time.process_time() < slice_dl - 0.5:
                win = _peak_window(folded, pad_frac=0.05, extra=128)
                folded = _lbfgs_block(folded, win, 200, slice_dl - 0.3, beta=1e7)
            if time.process_time() < slice_dl - 0.5:
                folded = _lbfgs_all_pos(folded, 200, slice_dl - 0.3, beta=0.0)
            r2 = R_of(folded)
            zf = float(np.mean(folded == 0))
            if r2 > bestR + 1e-13 and 0.60 <= zf <= 0.74:
                best, bestR = folded.copy(), r2
                origin = 'nc3_2_r%d' % rnd
                print("nc round %d R@L=%.9f foldedR=%.9f zf=%.4f ACCEPT best=%.9f"
                      % (rnd, rL, r2, zf, bestR))
            else:
                print("nc round %d R@L=%.9f foldedR=%.9f zf=%.4f reject (best %.9f)"
                      % (rnd, rL, r2, zf, bestR))
                if r2 > alt_bestR:
                    alt_best, alt_bestR = folded.copy(), r2
            rnd += 1

    # ---- Phase 3: final pad ladder + beta=1e7 / beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _fold_back(h3, N):
    F = np.concatenate(([0.0], np.cumsum(h3)))
    L = h3.size
    xs = np.linspace(0.0, L, N + 1)
    vals = np.interp(xs, np.arange(L + 1, dtype=float), F)
    out = np.diff(vals)
    return _rescale(np.clip(out, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient search (shrunk to 0.38 budget) ----
    phase12_end = t0 + budget_seconds * 0.38
    best_c = None
    best_cR = -1.0
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < phase12_end - 1.5:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = min(t0 + budget_seconds * 0.18, phase12_end - 1.0)
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= phase12_end - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, phase12_end - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: 3-variant rotation (shrunk, ends by phase12_end) ----
    N = best.size
    m = N // 2
    cyc = 0
    variant_hits = [0.0, 0.0, 0.0]
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = phase12_end
        max_cycles = 3
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(cycle_end - 0.5, now + 0.06 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]
                b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception as e:
                print("cycle %d variant %d exception %s" % (cyc, k, e))
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception as e:
                print("lift %d variant %d exception %s" % (cyc, k, e))
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                variant_hits[k] = max(variant_hits[k], r)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        print("rotation cycles=%d wR=%s" %
              (cyc, ["%.9f" % x for x in wR]))

    # ---- Phase 3j: non-commensurate ratio portfolio ----
    jit_start = t0 + budget_seconds * 0.38
    jit_end = deadline - 7.0
    if time.process_time() < jit_start:
        while time.process_time() < jit_start - 0.05:
            time.sleep(0.01)
    if time.process_time() < jit_end - 1.0 and best.size >= 8 and best.size % 2 == 0:
        rng = np.random.RandomState(24681357)
        Ncur = best.size
        ratios = [1.5, 1.25, 1.75, 1.5]
        for rnd, f in enumerate(ratios):
            now = time.process_time()
            if now >= jit_end - 1.0:
                break
            slice_dl = min(now + 6.0, deadline - 7.0)
            if slice_dl <= now + 0.8:
                break
            if f == 1.5:
                q = best[0::2].copy()
            else:
                q = best[0::4].copy()
            if q.size < 2:
                continue
            nsub = int(round(2 * f))
            L = q.size * nsub
            w = np.exp(0.35 * rng.randn(nsub))
            w = w * (nsub / w.sum())
            h3 = np.zeros(L)
            for i in range(q.size):
                h3[i * nsub:(i + 1) * nsub] = q[i] * w
            h3 = _rescale(h3)
            for beta in [1e5, 1e6, 1e7]:
                if time.process_time() >= slice_dl - 0.6:
                    break
                h3 = _lbfgs_all_pos(h3, 150, slice_dl - 0.3, beta=beta)
            if time.process_time() < slice_dl - 0.6:
                win = _peak_window(h3, pad_frac=0.05, extra=256)
                h3 = _lbfgs_block(h3, win, 200, slice_dl - 0.3, beta=1e7)
            rL = R_of(h3)
            folded = _fold_back(h3, Ncur)
            rfold = R_of(folded)
            if time.process_time() < slice_dl - 0.5:
                win = _peak_window(folded, pad_frac=0.05, extra=128)
                folded = _lbfgs_block(folded, win, 200, slice_dl - 0.3, beta=1e7)
            if time.process_time() < slice_dl - 0.5:
                folded = _lbfgs_all_pos(folded, 200, slice_dl - 0.3, beta=0.0)
            r2 = R_of(folded)
            zf = float(np.mean(folded == 0))
            accepted = False
            if r2 > bestR + 1e-13 and 0.60 <= zf <= 0.74:
                best, bestR = folded.copy(), r2
                origin = 'nc_f%.2f_r%d' % (f, rnd)
                accepted = True
            else:
                if r2 > alt_bestR:
                    alt_best, alt_bestR = folded.copy(), r2
            print("nc round %d f=%.2f L=%d R@L=%.9f foldedR=%.9f zf=%.4f %s (best %.9f)"
                  % (rnd, f, L, rL, r2, zf,
                     "ACCEPT" if accepted else "reject", bestR))

    # ---- Phase 4: final peak pads + beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag=""):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    for it, pad in enumerate([0.30, 0.20, 0.15, 0.10, 0.08]):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _fold_back(h3, N):
    F = np.concatenate(([0.0], np.cumsum(h3)))
    L = h3.size
    xs = np.linspace(0.0, L, N + 1)
    vals = np.interp(xs, np.arange(L + 1, dtype=float), F)
    out = np.diff(vals)
    return _rescale(np.clip(out, 0.0, None))


def _split3(q, rng):
    N = q.size
    L = (3 * N) // 2
    h3 = np.zeros(L)
    nfull = L // 3
    w = np.exp(0.45 * rng.randn(3))
    w = w * (3.0 / w.sum())
    for i in range(nfull):
        h3[3 * i:3 * i + 3] = q[i] * w
    rem = L - 3 * nfull
    if rem > 0:
        h3[3 * nfull:] = q[nfull] * w[:rem]
    return _rescale(h3)


def _refine(best, bestR, deadline, alt_state):
    """Local polish: peak-window blocks + all-pos, updating best and alt."""
    for pad in [0.10, 0.06, 0.04]:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR = ht2.copy(), r2
        elif r2 > alt_state[1]:
            alt_state[0], alt_state[1] = ht2.copy(), r2
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
        elif r > alt_state[1]:
            alt_state[0], alt_state[1] = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_state = [None, -1.0]

    # ---- Phase 1: half-resolution polish ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        half_deadline = t0 + budget_seconds * 0.22
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_state[1]:
            alt_state[0], alt_state[1] = ht.copy(), r

    # ---- Phase 2: 3/2 split-lift rounds ----
    jit_end = deadline - 7.0
    if time.process_time() < jit_end - 1.0 and best.size >= 8:
        rnd = 0
        while time.process_time() < jit_end - 1.0:
            now = time.process_time()
            slice_dl = min(now + 7.0, deadline - 7.0)
            if slice_dl <= now + 0.8:
                break
            Ncur = best.size
            rng = np.random.RandomState(97531 + rnd)
            h3 = _split3(best, rng)
            for beta in [1e5, 1e6, 1e7]:
                if time.process_time() >= slice_dl - 0.6:
                    break
                h3 = _lbfgs_all_pos(h3, 120, slice_dl - 0.3, beta=beta)
            if time.process_time() < slice_dl - 0.6:
                win = _peak_window(h3, pad_frac=0.08, extra=512)
                h3 = _lbfgs_block(h3, win, 250, slice_dl - 0.3, beta=1e7)
            if time.process_time() < slice_dl - 0.6:
                win = _peak_window(h3, pad_frac=0.04, extra=256)
                h3 = _lbfgs_block(h3, win, 250, slice_dl - 0.3, beta=1e7)
            rL = R_of(h3)
            if (rnd % 2 == 1) and time.process_time() < slice_dl - 0.6:
                rng2 = np.random.RandomState(97531 + rnd + 1000)
                h3b = _split3(h3, rng2)
                if time.process_time() < slice_dl - 0.5:
                    h3b = _lbfgs_all_pos(h3b, 100, slice_dl - 0.3, beta=1e7)
                h3 = h3b
                rL = R_of(h3)
            folded = _fold_back(h3, Ncur)
            if time.process_time() < slice_dl - 0.5:
                win = _peak_window(folded, pad_frac=0.05, extra=128)
                folded = _lbfgs_block(folded, win, 200, slice_dl - 0.3, beta=1e7)
            if time.process_time() < slice_dl - 0.5:
                folded = _lbfgs_all_pos(folded, 200, slice_dl - 0.3, beta=0.0)
            r2 = R_of(folded)
            zf = float(np.mean(folded == 0))
            if r2 > bestR + 1e-13 and 0.60 <= zf <= 0.74:
                best, bestR = folded.copy(), r2
                origin = 'nc3_2_r%d' % rnd
                print("nc r%d foldR=%.9f zf=%.3f ACCEPT best=%.9f"
                      % (rnd, r2, zf, bestR))
            else:
                print("nc r%d foldR=%.9f zf=%.3f reject (best %.9f)"
                      % (rnd, r2, zf, bestR))
                if r2 > alt_state[1]:
                    alt_state[0], alt_state[1] = folded.copy(), r2
            rnd += 1

    # ---- Phase 3: final polish ----
    best, bestR = _refine(best, bestR, deadline, alt_state)

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if (alt_state[0] is not None and alt_state[0].size == best.size
            and alt_state[1] < bestR):
        result["alternative"] = alt_state[0]
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _active_span(h):
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return 0, 0
    return int(nz.min()), int(nz.max())


def _edge_extend_geom(h, side, K, rho):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    i0, i1 = _active_span(h)
    if h[i0] <= 0 or h[i1] <= 0:
        return h
    hL = h[i0]; hR = h[i1]
    if side in ('left', 'both'):
        for k in range(1, K + 1):
            j = i0 - k
            if j < 0:
                break
            if h[j] == 0.0:
                h[j] = hL * (rho ** k)
    if side in ('right', 'both'):
        for k in range(1, K + 1):
            j = i1 + k
            if j >= n:
                break
            if h[j] == 0.0:
                h[j] = hR * (rho ** k)
    return _rescale(h)


def _upsample(h, factor):
    if factor <= 1:
        return h.copy()
    n = h.size
    newn = (n - 1) * factor + 1
    xo = np.arange(n, dtype=float)
    xn = np.linspace(0, n - 1, newn)
    return np.interp(xn, xo, h)


def _half_cycle(c, bestR, deadline, tag=""):
    """Multi-beta + shrinking peak-window polish; returns (best, bestR, origin)."""
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    for pad in [0.30, 0.20, 0.15, 0.10, 0.08]:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad)
        ht = _lbfgs_block(work, win, 250, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spad%g" % (tag, pad)
        else:
            work = ht  # keep moving
    # final all-pos at true objective
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(work, 200, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
            origin = tag + "final"
    return best, bestR, origin


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_bestR = bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # --- Main loop: repeated half-cycles with alternating beta-anneal and
    #     shrinking peak window, plus occasional upsample of the best.
    round_idx = 0
    while time.process_time() < deadline - 2.0:
        round_idx += 1
        # Reserve time for one half-cycle
        remaining = deadline - time.process_time()
        # Allocate a chunk ~ remaining / 3, but at least 4s
        chunk = max(4.0, remaining / 3.0)
        sub_deadline = min(deadline - 0.5, time.process_time() + chunk)

        cand, r_c, org = _half_cycle(best, bestR, sub_deadline,
                                     tag="r%d" % round_idx)
        improved = r_c > bestR + 1e-14
        if improved:
            best, bestR, origin = cand, r_c, org
            print("round %d NEW R=%.9f (%s, N=%d)"
                  % (round_idx, bestR, origin, best.size))
        else:
            # keep the slightly-better work if it helped vs best
            if r_c > bestR:
                best, bestR = cand, r_c
            # Try edge extension as an alternative if it's still better than start
            if (alt_best is None or r_c > alt_bestR) and r_c > start_bestR + 1e-14:
                alt_best, alt_bestR = cand, r_c

        # Try upsampling + polish if we have budget and resolution headroom
        if (time.process_time() < deadline - 5.0
                and best.size < 400000):
            target = min(1000000, best.size * 2)
            up = _upsample(best, 2)
            if up.size <= 1000000:
                sub2 = min(deadline - 0.5, time.process_time() + chunk * 0.8)
                up2, r_u, org_u = _half_cycle(up, R_of(up), sub2,
                                              tag="up%d" % round_idx)
                print("upsample N %d -> %d R=%.9f"
                      % (best.size, up2.size, r_u))
                if r_u > bestR + 1e-14:
                    best, bestR, origin = up2, r_u, org_u + "_up"
                elif r_u > alt_bestR and r_u > start_bestR + 1e-14:
                    alt_best, alt_bestR = up2, r_u

        # Occasionally try edge extension on current best
        if time.process_time() < deadline - 3.0 and (round_idx % 2 == 0):
            for (side, K, rho) in [('both', 4096, 0.9995),
                                   ('both', 2048, 0.995)]:
                if time.process_time() >= deadline - 2.0:
                    break
                ext = _edge_extend_geom(best, side, K, rho)
                sub3 = min(deadline - 0.5, time.process_time() + chunk * 0.6)
                ext2, r_e, org_e = _half_cycle(ext, R_of(ext), sub3,
                                               tag="ext_%s_%d_%g"
                                               % (side, K, rho))
                print("edge %s K=%d rho=%g R=%.9f" % (side, K, rho, r_e))
                if r_e > bestR + 1e-14:
                    best, bestR, origin = ext2, r_e, org_e
                elif r_e > alt_bestR and r_e > start_bestR + 1e-14:
                    alt_best, alt_bestR = ext2, r_e

    print("final R=%.9f origin=%s (start %.9f, N=%d)"
          % (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size != best.size:
        result["alternative"] = alt_best
    elif alt_best is not None and alt_bestR < bestR - 1e-12:
        result["alternative"] = alt_best
    return result

