        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish(best, bestR, deadline):
    for pad in [0.10, 0.06, 0.04]:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR = ht2.copy(), r2
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    return best, bestR


def _lift_extrap(cpol, gamma, N):
    c = np.asarray(cpol, dtype=float)
    m = c.size
    cs = np.concatenate(([c[0]], c, [c[-1]]))
    d = np.diff(cs)
    u = np.zeros(N)
    ev = np.clip(c + gamma * d[:m], 0.0, None)
    od = np.clip(c - gamma * d[1:m + 1], 0.0, None)
    n_ev = u[0::2].size
    n_od = u[1::2].size
    u[0::2][:min(n_ev, m)] = ev[:min(n_ev, m)]
    if n_ev > m:
        u[0::2][m:] = ev[-1]
    u[1::2][:min(n_od, m)] = od[:min(n_od, m)]
    if n_od > m:
        u[1::2][m:] = od[-1]
    return _rescale(u)


def _smooth_upsample(h, factor):
    """Upsample by `factor` using smooth (linear) interpolation - a genuinely
    different lift from the extrapolating even/odd split, so it explores
    a different basin."""
    n = h.size
    m = n * factor
    xi = np.linspace(0, n - 1, m)
    u = np.interp(xi, np.arange(n), h)
    return _rescale(np.clip(u, 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def _maybe_alt(h2, r2):
        nonlocal alt_best, alt_bestR
        if r2 > alt_bestR:
            alt_best, alt_bestR = h2.copy(), r2

    N0 = best.size

    # ---- Phase A: smooth-upsampled lift (new idea) ----
    # Upsample the full-N start to 2N by linear interpolation, polish the
    # 2N construction directly (no fold-back), then fold to N. This reaches
    # a basin the even/odd extrapolation lift misses.
    if N0 >= 8 and N0 <= 400000:
        up_end = t0 + budget_seconds * 0.30
        factor = 2
        u = _smooth_upsample(best, factor)
        r_up0 = R_of(u)
        print("upsample x%d r_pre=%.9f" % (factor, r_up0))
        while time.process_time() < up_end - 1.0:
            now = time.process_time()
            slice_dl = min(up_end, now + 4.0)
            if slice_dl <= now + 0.5:
                break
            ut = _lbfgs_all_pos(u, 300, slice_dl - 0.3, beta=1e6)
            if time.process_time() < slice_dl - 0.4:
                ut = _lbfgs_all_pos(ut, 300, slice_dl - 0.3, beta=1e7)
            if time.process_time() < slice_dl - 0.4:
                win = _peak_window(ut, pad_frac=0.10, extra=256)
                ut = _lbfgs_block(ut, win, 300, slice_dl - 0.3, beta=1e7)
            r_up = R_of(ut)
            if r_up > r_up0 + 1e-13:
                u, r_up0 = ut, r_up
            # fold back to N
            h2 = _rescale(0.5 * (u[0::2] + u[1::2]))[:N0]
            if time.process_time() < slice_dl - 0.4:
                h2 = _lbfgs_all_pos(h2, 250, slice_dl - 0.3, beta=1e6)
            if time.process_time() < slice_dl - 0.4:
                h2 = _lbfgs_all_pos(h2, 250, slice_dl - 0.3, beta=1e7)
            r_fold = R_of(h2)
            print("  upsample r_2N=%.9f r_fold=%.9f (best %.9f)" %
                  (r_up, r_fold, bestR))
            if r_fold > bestR + 1e-13:
                best, bestR, origin = h2.copy(), r_fold, 'upsample'
                print("  upsample NEW BEST R=%.9f" % bestR)
            else:
                _maybe_alt(h2, r_fold)

    # ---- Phase B: half-res quotient optimisation + extrapolating lift ----
    if N0 % 2 == 0 and N0 >= 4 and time.process_time() < deadline - 10.0:
        m = N0 // 2
        c = 0.5 * (best[0::2][:m] + best[1::2][:m])
        cR = R_of(c)
        half_deadline = t0 + budget_seconds * 0.55
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            for beta in [1e5, 1e6, 1e7]:
                if time.process_time() >= half_deadline - 0.5:
                    break
                ht = _lbfgs_all_pos(work_c, 300, half_deadline - 0.3, beta=beta)
                r = R_of(ht)
                if r > best_cR + 1e-14:
                    work_c, best_c, best_cR = ht, ht.copy(), r
            for pad in [0.30, 0.20, 0.15, 0.10, 0.08]:
                if time.process_time() >= half_deadline - 0.5:
                    break
                win = _peak_window(work_c, pad_frac=pad, extra=128)
                ht = _lbfgs_block(work_c, win, 400, half_deadline - 0.3, beta=1e7)
                r = R_of(ht)
                if r > best_cR + 1e-14:
                    work_c, best_c, best_cR = ht, ht.copy(), r
                if time.process_time() < half_deadline - 0.6:
                    ht2 = _lbfgs_all_pos(work_c, 300, half_deadline - 0.3, beta=0.0)
                    r2 = R_of(ht2)
                    if r2 > best_cR + 1e-14:
                        work_c, best_c, best_cR = ht2, ht2.copy(), r2
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))

        gammas = [0.0, 0.5, -0.5, 0.25, -0.25]
        lift_end = t0 + budget_seconds * 0.80
        for gamma in gammas:
            if time.process_time() >= lift_end - 1.0:
                break
            now = time.process_time()
            slice_dl = min(lift_end, now + 3.0)
            if slice_dl <= now + 0.5:
                break
            try:
                u = _lift_extrap(best_c, gamma, N0)
                r_pre = R_of(u)
                if time.process_time() < slice_dl - 0.4:
                    u = _lbfgs_all_pos(u, 250, slice_dl - 0.3, beta=1e6)
                if time.process_time() < slice_dl - 0.4:
                    u = _lbfgs_all_pos(u, 250, slice_dl - 0.3, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    win = _peak_window(u, pad_frac=0.08, extra=256)
                    u = _lbfgs_block(u, win, 250, slice_dl - 0.3, beta=1e7)
                r_2n = R_of(u)
                h2 = _rescale(0.5 * (u[0::2] + u[1::2]))[:N0]
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 250, slice_dl - 0.3, beta=1e6)
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 250, slice_dl - 0.3, beta=1e7)
                r_fold = R_of(h2)
                print("lift g=%.2f r_pre=%.9f r_2N=%.9f r_fold=%.9f (best %.9f)" %
                      (gamma, r_pre, r_2n, r_fold, bestR))
                if r_fold > bestR + 1e-13:
                    best, bestR, origin = h2.copy(), r_fold, 'lift_g%.2f' % gamma
                    print("  lift NEW BEST R=%.9f" % bestR)
                else:
                    _maybe_alt(h2, r_fold)
            except Exception as e:
                print("lift g=%.2f exception %s" % (gamma, e))

    # ---- Phase C: peak polish ----
    if time.process_time() < deadline - 1.0:
        best, bestR = _polish(best, bestR, deadline - 2.0)

    # ---- Phase D: randomized perturbation multi-start ----
    rnd_end = deadline - 3.0
    if time.process_time() < rnd_end - 1.0 and best.size >= 2:
        n = best.size
        sigmas = [0.02, 0.05, 0.10, 0.03]
        rnd = 0
        while time.process_time() < rnd_end - 1.0:
            sigma = sigmas[rnd % len(sigmas)]
            rnd += 1
            now = time.process_time()
            slice_dl = min(now + 2.0, deadline - 2.0)
            if slice_dl <= now + 0.3:
                break
            try:
                d = np.clip(sigma * np.random.randn(n), -0.6, 0.6)
                u = np.empty(2 * n)
                u[0::2] = best * (1.0 + d)
                u[1::2] = best * (1.0 - d)
                u = _rescale(u)
                u = _lbfgs_all_pos(u, 120, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    win = _peak_window(u, pad_frac=0.10, extra=128)
                    u = _lbfgs_block(u, win, 150, slice_dl, beta=1e7)
                h2 = _rescale(0.5 * (u[0::2] + u[1::2]))[:n]
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e6)
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e7)
                r_fold = R_of(h2)
                if r_fold > bestR + 1e-13:
                    best, bestR, origin = h2.copy(), r_fold, 'rnd%d' % rnd
                    print("  rnd NEW BEST R=%.9f" % bestR)
                else:
                    _maybe_alt(h2, r_fold)
            except Exception as e:
                print("rnd %d exception %s" % (rnd, e))

    # ---- Phase E: final polish ----
    if time.process_time() < deadline - 1.0:
        best, bestR = _polish(best, bestR, deadline)

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _fold_back(h3, N):
    F = np.concatenate(([0.0], np.cumsum(h3)))
    L = h3.size
    xs = np.linspace(0.0, L, N + 1)
    vals = np.interp(xs, np.arange(L + 1, dtype=float), F)
    out = np.diff(vals)
    return _rescale(np.clip(out, 0.0, None))


def _split3_half(c, rng):
    """Build L=3*m array from half-quotient c (size m) with fresh sub-cell weights."""
    m = c.size
    L = 3 * m
    h3 = np.zeros(L)
    w = np.exp(0.35 * rng.randn(3))
    w = w * (3.0 / w.sum())
    for i in range(m):
        h3[3 * i:3 * i + 3] = c[i] * w
    return _rescale(h3)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient polish (short) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.25
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: half-quotient 3:2 non-commensurate lift rounds ----
    jit_start = t0 + budget_seconds * 0.30
    jit_end = deadline - 7.0
    if time.process_time() < jit_start:
        while time.process_time() < jit_start - 0.05:
            time.sleep(0.01)
    if time.process_time() < jit_end - 1.0 and best.size >= 8 and best.size % 2 == 0:
        rnd = 0
        while rnd < 4 and time.process_time() < jit_end - 1.0:
            now = time.process_time()
            slice_dl = min(now + 6.0, deadline - 7.0)
            if slice_dl <= now + 0.8:
                break
            Ncur = best.size
            c = best[0::2].copy()
            m = c.size
            rng = np.random.RandomState(24681357 + rnd)
            h3 = _split3_half(c, rng)
            L = h3.size
            for beta in [1e5, 1e6, 1e7]:
