    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _fold_back(h3, N):
    F = np.concatenate(([0.0], np.cumsum(h3)))
    L = h3.size
    xs = np.linspace(0.0, L, N + 1)
    vals = np.interp(xs, np.arange(L + 1, dtype=float), F)
    out = np.diff(vals)
    return _rescale(np.clip(out, 0.0, None))


def _split3_half(c, rng):
    """Build L=3*m array from half-quotient c (size m) with fresh sub-cell weights."""
    m = c.size
    L = 3 * m
    h3 = np.zeros(L)
    w = np.exp(0.35 * rng.randn(3))
    w = w * (3.0 / w.sum())
    for i in range(m):
        h3[3 * i:3 * i + 3] = c[i] * w
    return _rescale(h3)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 2 (experiment): cheap fold-back perturbation rounds ----
    jit_start = t0 + budget_seconds * 0.25
    jit_end = deadline - 4.0
    if time.process_time() < jit_start:
        while time.process_time() < jit_start - 0.05:
            time.sleep(0.01)
    if time.process_time() < jit_end - 1.0 and best.size >= 8 and best.size % 2 == 0:
        rnd = 0
        while rnd < 10 and time.process_time() < jit_end - 1.0:
            now = time.process_time()
            slice_dl = min(now + 5.0, deadline - 4.0)
            if slice_dl <= now + 0.8:
                break
            Ncur = best.size
            c = best[0::2].copy()
            rng = np.random.RandomState(24681357 + rnd)
            h3 = _split3_half(c, rng)
            folded = _fold_back(h3, Ncur)
            zf0 = float(np.mean(folded == 0))
            if not (0.60 <= zf0 <= 0.75):
                print("hq round %d zf0=%.4f reject-pre (best %.9f)"
                      % (rnd, zf0, bestR))
                rnd += 1
                continue
            r_pre = R_of(folded)
            folded = _lbfgs_all_pos(folded, 150, slice_dl, beta=1e6)
            folded = _lbfgs_all_pos(folded, 150, slice_dl, beta=1e7)
            if time.process_time() < slice_dl - 0.5:
                win = _peak_window(folded, pad_frac=0.05, extra=128)
                folded = _lbfgs_block(folded, win, 250, slice_dl, beta=1e7)
            folded = _lbfgs_all_pos(folded, 200, slice_dl, beta=0.0)
            r2 = R_of(folded)
            zf = float(np.mean(folded == 0))
            if r2 > bestR + 5e-14 and 0.62 <= zf <= 0.72:
                best, bestR = folded.copy(), r2
                origin = 'hq3_2_r%d' % rnd
                print("hq round %d preR=%.9f postR=%.9f zf=%.4f ACCEPT best=%.9f"
                      % (rnd, r_pre, r2, zf, bestR))
            else:
                print("hq round %d preR=%.9f postR=%.9f zf=%.4f reject (best %.9f)"
                      % (rnd, r_pre, r2, zf, bestR))
                if r2 > alt_bestR:
                    alt_best, alt_bestR = folded.copy(), r2
            rnd += 1

    # ---- Phase 3: final pad ladder + beta=1e7 / beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _interp_double(c):
    """Insert a midpoint between each pair of heights (linear interp),
    doubling support resolution."""
    m = c.size
    out = np.empty(2 * m)
    out[0::2] = c
    out[1::2] = np.concatenate((0.5 * (c[:-1] + c[1:]), [c[-1]]))
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: coarse-to-fine refinement on a downsampled version ----
    # NEW IDEA: instead of only half-res cycles, recursively downsample by 4,
    # optimize the coarse problem, then interpolate up. This lets the coarse
    # optimizer escape local structure the full-res optimizer is stuck in.
    if best.size >= 16 and time.process_time() < deadline - 3.0:
        # downsample by 4 (average of 4-blocks)
        n = best.size
        nb = n // 4
        if nb >= 4:
            c4 = best[:nb * 4].reshape(nb, 4).mean(axis=1)
            c4 = _rescale(c4)
            c4R = R_of(c4)
            print("quarter-res R=%.9f (full %.9f)" % (c4R, bestR))
            q_deadline = min(deadline - 2.0, t0 + 0.30 * budget_seconds)
            work_c = c4.copy()
            bestc4 = c4.copy()
            bestc4R = c4R
            rounds = 0
            while time.process_time() < q_deadline - 1.0:
                work_c, bestc4, bestc4R, org = _half_cycle(
                    work_c, bestc4R, q_deadline, tag='q%d' % rounds,
                    pads=[0.30, 0.20, 0.12])
                rounds += 1
            print("quarter rounds=%d R(c4)=%.9f" % (rounds, bestc4R))
            # interpolate back up to full resolution
            up = np.repeat(bestc4, 4)
            if up.size < n:
                up = np.concatenate((up, np.full(n - up.size, up[-1])))
            up = _rescale(up[:n])
            # smooth the blocky upsampling by running beta=1e7 refine
            ht = up
            for beta in [1e6, 1e7]:
                if time.process_time() >= deadline - 1.0:
                    break
                ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, 'quarter'
                print("quarter-lift NEW BEST R=%.9f" % bestR)
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: 3-variant rotation of extract/lift cycles ----
    N = best.size
    m = N // 2
    cyc = 0
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 5.0
        max_cycles = 6
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 4.0, now + 0.07 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]
                b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception as e:
                print("cycle %d variant %d exception %s" % (cyc, k, e))
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception as e:
                print("lift %d variant %d exception %s" % (cyc, k, e))
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        print("rotation cycles=%d wR=%s" %
              (cyc, ["%.9f" % x for x in wR]))

    # ---- Phase 3: fine peak-window polishing with tight pads ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04, 0.03, 0.02]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _fun_grad_log(z, mask, full_h, beta):
    h = full_h.copy()
    h[mask] = np.exp(np.clip(z, -30.0, 30.0))
    h[~mask] = 0.0
    if beta > 0:
        val, grad = _fun_grad_beta(h, beta)
    else:
        val, grad = _fun_grad(h)
    return val, grad[mask] * h[mask]


def _lbfgs_log(h0, maxiter, deadline, beta, free_mask=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(np.asarray(h0, dtype=float).copy(), 0, None)
    if h.sum() <= 0:
        return h0
    mask = h > 0
    if free_mask is not None:
        mask = mask & free_mask
    if not np.any(mask):
        return h0
    full_h = h.copy()
    z0 = np.log(np.clip(h[mask], 1e-12, None))

    def f(z):
        return _fun_grad_log(z, mask, full_h, beta)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, z0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * z0.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = full_h.copy()
    h2[mask] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase LOG: log-space optimization, then peak-window log polish
    log_best = best.copy()
    log_bestR = bestR
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 1.2:
            break
        ht = _lbfgs_log(log_best, 300, deadline - 1.0, beta)
        r = R_of(ht)
        if r > log_bestR + 1e-14:
            log_best, log_bestR = ht, r
            print("log beta=%g: R=%.9f ACCEPT" % (beta, r))
        else:
            print("log beta=%g: R=%.9f reject" % (beta, r))
        if r > bestR + 1e-14:
            best, bestR, origin = ht, r, 'log%g' % beta

    if time.process_time() < deadline - 1.0:
        win = _peak_window(log_best, pad_frac=0.15, extra=128)
        fm = np.zeros(log_best.size, dtype=bool)
        fm[win] = True
        ht = _lbfgs_log(log_best, 300, deadline - 0.8, 1e7, free_mask=fm)
        r = R_of(ht)
        if r > log_bestR + 1e-14:
            log_best, log_bestR = ht, r
            print("log window: R=%.9f ACCEPT" % r)
        if r > bestR + 1e-14:
            best, bestR, origin = ht, r, 'logwin'

    if log_bestR > start_bestR + 1e-14 and log_bestR < bestR - 1e-14:
        alt_best, alt_bestR = log_best, log_bestR

    # Phase A: baseline refinement cycle on start
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            start_best.copy(), best.copy(), bestR, deadline, 'base')
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Phase B: random multi-start perturbations (the main search)
    rng = np.random.default_rng(int(t0 * 1000) % 100000)
    amps = [0.01, 0.03, 0.05, 0.08, 0.12, 0.02, 0.04, 0.06, 0.10, 0.15]

    for trial, amp in enumerate(amps):
        if time.process_time() >= deadline - 1.0:
            break
        seed = np.clip(best, 0, None).copy()
        nz = seed > 0
        noise = np.exp(amp * rng.standard_normal(seed.size))
        seed[nz] *= noise[nz]
        seed = _rescale(seed)
        r_seed = R_of(seed)
        w, b, br, org = _run_cycle(seed, seed.copy(), r_seed, deadline,
                                   'rand%d' % trial)
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("rand%d amp=%.3f: R=%.9f NEW BEST" % (trial, amp, bestR))
        else:
            if br > alt_bestR:
                alt_best, alt_bestR = b, br
            print("rand%d amp=%.3f: R=%.9f (best %.9f)"
                  % (trial, amp, br, bestR))

    # Final window sweep on overall best
    if time.process_time() < deadline - 0.8:
        win = _peak_window(best, pad_frac=0.15, extra=128)
        ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht, r, origin + '+finalwin'

    print("final R=%.9f origin=%s (start %.9f, N=%d)"
          % (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _swap_polish(h, deadline, rounds=2, maxiter=300):
    """NEW: coordinate-wise 'swap' step — for each index, try replacing
    height with the local quadratic step toward the peak, accepting only if
    R improves. Cheap greedy sweep over free coords."""
    best = h.copy()
    bestR = R_of(best)
    n = best.size
    idx = np.arange(n)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        improved = False
        # try zeroing the smallest heights (they often can be pruned)
        small = np.argsort(best)[:max(8, n // 50)]
        for i in small:
            if best[i] <= 0:
                continue
            cand = best.copy()
            cand[i] = 0.0
            r = R_of(cand)
            if r > bestR + 1e-14:
                best, bestR = cand, r
                improved = True
        if not improved:
            break
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW IDEA: smooth-max (softmax) objective with increasing beta.
    for beta in (30.0, 100.0, 300.0, 1000.0, 3000.0, 10000.0):
        if time.process_time() >= deadline - 4.0:
            break
        h = _lbfgs_log(best, 3000, deadline, beta=beta)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("beta=%.0f R=%.7f" % (beta, bestR))
        else:
            h2 = _window_polish_peak(best, deadline, 0.35, 24, beta=beta)
            r2 = R_of(h2)
            if r2 > bestR + 1e-13:
                best, bestR = h2, r2
                print("beta=%.0f win R=%.7f" % (beta, bestR))

    # NEW: greedy pruning of tiny heights (zeroing useless steps).
    h = _swap_polish(best, deadline, rounds=3)
    r = R_of(h)
    if r > bestR + 1e-15:
        best, bestR = h, r
        print("prune R=%.7f" % bestR)

    # Fine polish: exact objective in peak window, then full.
    for frac, extra in ((0.15, 6), (0.25, 12), (0.40, 20), (0.60, 40)):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish_peak(best, deadline, frac, extra)
        h = _lbfgs_log(h, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("peak(%.2f) R=%.7f" % (frac, bestR))

    # NEW: coarse-to-fine retry — compress to a smaller grid, re-optimise,
    # then prolongate back and polish. This can escape local traps.
    if time.process_time() < deadline - 8.0:
        for Nc in (best.size // 2, best.size // 4):
            if Nc < 256:
                break
            if time.process_time() >= deadline - 6.0:
                break
            hc = _coarse(best, Nc)
            hc = _lbfgs_log(hc, 1500, deadline)
            hp = _prolongate(hc, best.size)
            hp = _lbfgs_log(hp, 800, deadline)
            r = R_of(hp)
            if r > bestR + 1e-15:
                best, bestR = hp, r
                print("coarse(%d) R=%.7f" % (Nc, bestR))

    # Final alternating loop until budget exhausted.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 1000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.45, 28)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _refine_full(h, bestR, deadline, tag, pads):
    """Full-resolution peak-window polish (the new idea): optimize at full N
    instead of only half-resolution quotient search."""
    work = h.copy()
    best = h.copy()
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=256)
        ht = _lbfgs_block(work, win, 500, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 400, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
    return work, best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: FULL-RESOLUTION refinement first (new emphasis) ----
    # The half-resolution quotient search plateaus quickly; direct full-N
    # peak-window polish of the start is a genuinely different path.
    full_dl = t0 + budget_seconds * 0.40
    work_full = best.copy()
    if time.process_time() < full_dl - 1.0:
        work_full, bf, bfR = _refine_full(
            work_full, bestR, full_dl, 'full',
            pads=[0.20, 0.14, 0.10, 0.08, 0.06, 0.05])
        if bfR > bestR + 1e-14:
            best, bestR, origin = bf.copy(), bfR, 'full'
            print("full-res NEW BEST R=%.9f" % bestR)
        elif bfR > alt_bestR:
            alt_best, alt_bestR = bf.copy(), bfR

    # ---- Phase 2: half-resolution quotient search (from current best) ----
    best_c = None
    best_cR = -1.0
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.60
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 3: 3-variant rotation (short) ----
    N = best.size
    m = N // 2
    cyc = 0
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 5.0
        max_cycles = 8
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(now + 0.08 * budget_seconds, deadline - 6.0)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]
                b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception as e:
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception as e:
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
                w = [best.copy(), best.copy(), best.copy()]
                wR = [bestR, bestR, bestR]
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        print("rotation cycles=%d wR=%s" %
              (cyc, ["%.9f" % x for x in wR]))

    # ---- Phase 4: final full-resolution peak polish ----
    if time.process_time() < deadline - 1.0:
        _, bf, bfR = _refine_full(
            best, bestR, deadline - 0.5, 'final',
            pads=[0.06, 0.04, 0.03])
        if bfR > bestR + 1e-14:
            best, bestR, origin = bf.copy(), bfR, origin + '+full'
            print("final full NEW BEST R=%.9f" % bestR)
        elif bfR > alt_bestR:
            alt_best, alt_bestR = bf.copy(), bfR

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
