        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _sharpen(h):
    """Map each cell i to a single fine cell at 2i (width halved, spacing kept)."""
    n = h.size
    out = np.zeros(2 * n)
    out[0::2] = 2.0 * h
    return _rescale(out)


def _sharpen_shift(h):
    """Map each cell i to fine cell 2i+1 (shifted variant)."""
    n = h.size
    out = np.zeros(2 * n + 2)
    out[1:2 * n + 1:2] = 2.0 * h
    return _rescale(out)


def _polish_ladder(h, deadline, iters, pads):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            return h
        h = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            return h
        win = _peak_window(h, pad_frac=pad, extra=128)
        h = _lbfgs_block(h, win, iters + 50, deadline - 0.3, beta=1e7)
    if time.process_time() < deadline - 0.5:
        h = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=0.0)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: sharpen (half-width) to 2N ----
    h2 = _sharpen(best)
    r0 = R_of(h2)
    print("sharpen r0=%.9f (N=%d, base %.9f)" % (r0, h2.size, bestR))

    # Polish the 2x state
    dl2 = min(deadline - 0.5, t0 + budget_seconds * 0.55)
    h2p = _polish_ladder(h2.copy(), dl2, 250, [0.20, 0.10, 0.06])
    r2p = R_of(h2p)
    print("sharpen polished R=%.9f (N=%d)" % (r2p, h2p.size))

    cand_h, cand_R = h2p, r2p
    if r2p > bestR + 1e-14:
        best, bestR, origin = h2p.copy(), r2p, 'sharpen2x'
        print("sharpen2x NEW BEST R=%.9f" % bestR)
    elif r2p > alt_bestR:
        alt_best, alt_bestR = h2p.copy(), r2p

    # ---- Phase 2: sharpen again to 4N if time remains ----
    if time.process_time() < t0 + budget_seconds * 0.60:
        h4 = _sharpen(h2p)
        r4_0 = R_of(h4)
        print("sharpen4x r0=%.9f (N=%d)" % (r4_0, h4.size))
        dl4 = deadline - 5.0
        h4p = _polish_ladder(h4.copy(), dl4, 150, [0.10, 0.06])
        r4p = R_of(h4p)
        print("sharpen4x polished R=%.9f (N=%d)" % (r4p, h4p.size))
        if r4p > bestR + 1e-14:
            best, bestR, origin = h4p.copy(), r4p, 'sharpen4x'
            print("sharpen4x NEW BEST R=%.9f" % bestR)
        elif r4p > alt_bestR:
            alt_best, alt_bestR = h4p.copy(), r4p

    # ---- Phase 3: final beta=0 polish of winner ----
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("final beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _polish_quotient(c, deadline, maxiter=100):
    for beta in [1e6, 1e7, 0.0]:
        if time.process_time() >= deadline - 0.5:
            break
        c = _lbfgs_all_pos(c, maxiter, deadline, beta=beta)
    return c


def _lift_repeat(c):
    return _rescale(np.repeat(c, 2))


def _lift_odd(c):
    n = c.size
    h = np.zeros(2 * n + 2)
    h[1:2 * n + 1] = np.repeat(c, 2)
    return _rescale(h)


def _rotation_variants(best):
    n = best.size
    variants = []
    c_even = best[0::2].copy()
    variants.append(('even', c_even, _lift_repeat))
    if n >= 3:
        c_odd = best[1::2].copy()
        variants.append(('odd', c_odd, _lift_odd))
    m = min(best[0::2].size, best[1::2].size)
    c_avg = 0.5 * (best[0::2][:m] + best[1::2][:m])
    variants.append(('avg', c_avg, _lift_repeat))
    return variants


# ---------------- sub-cell shift machinery ----------------

def _find_runs(h, min_frac=0.02):
    nz = h > 0
    if not nz.any():
        return []
    mx = h.max()
    thr = min_frac * mx
    runs = []
    i = 0
    n = h.size
    while i < n:
        if nz[i]:
            j = i
            while j + 1 < n and nz[j + 1]:
                j += 1
            mass = h[i:j + 1].sum()
            if mass >= thr:
                runs.append((i, j, mass))
            i = j + 1
        else:
            i += 1
    return runs


def _shift_run(h, i, j, delta):
    """Shift profile h[i:j+1] by delta cells (fractional), preserving mass."""
    prof = h[i:j + 1].copy()
    n = h.size
    out = h.copy()
    out[i:j + 1] = 0.0
    # target positions: original index + delta
    for k in range(prof.size):
        pos = (i + k) + delta
        lo = int(np.floor(pos))
        frac = pos - lo
        if 0 <= lo < n:
            out[lo] += prof[k] * (1.0 - frac)
        if 0 <= lo + 1 < n:
            out[lo + 1] += prof[k] * frac
    return np.clip(out, 0.0, None)


def _repair_window(h, i, j, deadline, iters=80):
    win = np.arange(max(0, i - 48), min(h.size, j + 49))
    pk = _peak_window(h, 0.10, 64)
    win = np.union1d(win, pk)
    return _lbfgs_block(h, win, iters, deadline, beta=1e7)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient polish (short, keep base behaviour) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.15
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: sub-cell spike-shift sweeps ----
    sweep_deadline = deadline - 3.0
    rng = np.random.RandomState(12345)
    sweep = 0
    while time.process_time() < sweep_deadline - 1.0:
        runs = _find_runs(best, min_frac=0.02)
        if not runs:
            break
        order = list(range(len(runs)))
        rng.shuffle(order)
        best_move_h = None
        best_move_R = bestR
        best_move_info = None
        tried = 0
        for ri in order:
            if time.process_time() > sweep_deadline - 1.5:
                break
            i, j, mass = runs[ri]
            for delta in (0.5, -0.5):
                if time.process_time() > sweep_deadline - 1.5:
                    break
                cand = _shift_run(best, i, j, delta)
                if cand.sum() <= 0:
                    continue
                cand = _rescale(cand)
                cand = _repair_window(cand, i, j, sweep_deadline - 0.5, iters=80)
                r = R_of(cand)
                tried += 1
                if r > best_move_R + 1e-9:
                    best_move_h = cand
                    best_move_R = r
                    best_move_info = (i, j, delta)
        if best_move_h is not None:
            best = best_move_h
            bestR = best_move_R
            origin = 'shift'
            print("sweep %d tried=%d ACCEPT delta=%+.1f [%d,%d] R=%.9f"
                  % (sweep, tried, best_move_info[2], best_move_info[0],
                     best_move_info[1], bestR))
        else:
            print("sweep %d tried=%d no improvement best=%.9f"
                  % (sweep, tried, bestR))

        # every 5 sweeps: full-N beta ladder + pad-0.06 polish
        if sweep % 5 == 4 and time.process_time() < sweep_deadline - 1.0:
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= sweep_deadline - 0.8:
                    break
                ht = _lbfgs_all_pos(best, 200, sweep_deadline - 0.5, beta=beta)
                r = R_of(ht)
                if r > bestR + 1e-14:
                    best, bestR, origin = ht.copy(), r, origin + '+lad'
            if time.process_time() < sweep_deadline - 0.8:
                win = _peak_window(best, 0.06, 128)
                ht = _lbfgs_block(best, win, 300, sweep_deadline - 0.5, beta=1e7)
                r = R_of(ht)
                if r > bestR + 1e-14:
                    best, bestR, origin = ht.copy(), r, origin + '+pk'
            print("sweep %d post-ladder R=%.9f" % (sweep, bestR))
        sweep += 1

    # ---- Phase 3: final pad ladder + beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

