            maybe_update(hp, rp, "peak")

    # ---- Phase 2: alternating global + peak-window refinement ----
    it = 0
    loop_end = deadline - 2.5
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if maybe_update(hs, rs, "iter%d global" % it):
            continue
        if time.process_time() < loop_end - 1.0:
            pads = [0.40, 0.25, 0.15, 0.10, 0.06]
            pad = pads[it % len(pads)]
            free = _peak_window(bestH, pad_frac=pad, extra=384)
            cap = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 200, cap, beta=0.0)
            rp = R_of(hp)
            maybe_update(hp, rp, "iter%d peak pad=%.2f" % (it, pad))

    # ---- Phase 3: one more refinement step if budget remains ----
    if time.process_time() < deadline - 1.5 and bestH.size <= 480000:
        hr = _rescale(_refine(bestH))
        rr = R_of(hr)
        if rr > bestR - 1e-9:
            cap = min(deadline - 0.5, time.process_time() + 6.0)
            hs = _lbfgs_log(hr, 200, cap, beta=0.0)
            rs = R_of(hs)
            print("  refine -> R=%.9f (was %.9f)" % (rs, bestR))
            maybe_update(hs, rs, "refine")

    # ---- Final polish ----
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hs = _lbfgs_log(bestH, 100, cap, beta=0.0)
        rs = R_of(hs)
        maybe_update(hs, rs, "final")

    print("done bestR=%.9f altR=%.9f baseR=%.9f N=%d" %
          (bestR, alternativeR, baseR, bestH.size))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": alternative}
    else:
        return {"best": baseH, "alternative": alternative}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r

    # ---- Phase A: half-resolution quotient polish ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.18
        work_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # ---- Phase B: high-beta sharpening ladder ----
    # The inf-norm constraint is the bottleneck. A very high beta makes the
    # soft-max almost exact, sharpening the flat peak into a sharper ridge;
    # this small structural change frees up the 2-norm and raises R.
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=350)
        offer(ht, 'sharp')

    # ---- Phase C: sub-cell spike-shift sweeps ----
    def _find_runs(h, min_frac=0.02):
        nz = h > 0
        if not nz.any():
            return []
        thr = min_frac * h.max()
        runs = []
        i, n = 0, h.size
        while i < n:
            if nz[i]:
                j = i
                while j + 1 < n and nz[j + 1]:
                    j += 1
                if h[i:j + 1].sum() >= thr:
                    runs.append((i, j))
                i = j + 1
            else:
                i += 1
        return runs

    def _shift_run(h, i, j, delta):
        prof = h[i:j + 1].copy()
        n = h.size
        out = h.copy()
        out[i:j + 1] = 0.0
        for k in range(prof.size):
            pos = (i + k) + delta
            lo = int(np.floor(pos))
            frac = pos - lo
            if 0 <= lo < n:
                out[lo] += prof[k] * (1.0 - frac)
            if 0 <= lo + 1 < n:
                out[lo + 1] += prof[k] * frac
        return np.clip(out, 0.0, None)

    def _repair(h, i, j, dl, iters=80):
        win = np.arange(max(0, i - 48), min(h.size, j + 49))
        pk = _peak_window(h, 0.10, 64)
        win = np.union1d(win, pk)
        return _lbfgs_block(h, win, iters, dl, beta=1e7)

    sweep_deadline = deadline - 3.0
    rng = np.random.RandomState(12345)
    sweep = 0
    while time.process_time() < sweep_deadline - 1.0:
        runs = _find_runs(best, min_frac=0.02)
        if not runs:
            break
        order = list(range(len(runs)))
        rng.shuffle(order)
        moved = None
        movedR = bestR
        tried = 0
        for ri in order:
            if time.process_time() > sweep_deadline - 1.5:
                break
            i, j = runs[ri]
            for delta in (0.5, -0.5):
                if time.process_time() > sweep_deadline - 1.5:
                    break
                cand = _shift_run(best, i, j, delta)
                if cand.sum() <= 0:
                    continue
                cand = _rescale(cand)
                cand = _repair(cand, i, j, sweep_deadline - 0.5, iters=80)
                r = R_of(cand)
                tried += 1
                if r > movedR + 1e-9:
                    moved, movedR = cand, r
        if moved is not None:
            best, bestR = moved, movedR
            print("sweep %d tried=%d ACCEPT R=%.9f" % (sweep, tried, bestR))
        else:
            print("sweep %d tried=%d no improvement best=%.9f" % (sweep, tried, bestR))

        if sweep % 4 == 3 and time.process_time() < sweep_deadline - 1.0:
            ht = _polish_ladder(best, sweep_deadline - 0.5,
                                betas=(1e7, 1e8, 0.0), iters=200)
            if R_of(ht) > bestR + 1e-14:
                best, bestR = ht, R_of(ht)
            win = _peak_window(best, 0.06, 128)
            ht = _lbfgs_block(best, win, 300, sweep_deadline - 0.5, beta=1e7)
            if R_of(ht) > bestR + 1e-14:
                best, bestR = ht, R_of(ht)
            print("sweep %d post-ladder R=%.9f" % (sweep, bestR))
        sweep += 1

    # ---- Phase D: final high-beta + pad ladder ----
    ht = _polish_ladder(best, deadline - 1.0, betas=(1e8, 1e9, 0.0), iters=350)
    offer(ht, 'finalhi')
    ht = _peak_ladder(best, deadline - 0.6, pads=(0.10, 0.06, 0.04), iters=400)
    offer(ht, 'finalpk')
    ht = _polish_ladder(best, deadline - 0.3, betas=(0.0,), iters=300)
    offer(ht, 'finalb0')

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

