def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _support_window(h, thresh_rel=1e-3, pad_frac=0.02, extra=8):
    """Window around the support of h (nonzero heights), padded."""
    nz = np.flatnonzero(h > thresh_rel * h.max())
    if nz.size == 0:
        return np.arange(h.size)
    lo = max(0, nz.min() - 1)
    hi = min(h.size - 1, nz.max() + 1)
    pad = max(extra, int((hi - lo) * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _lbfgs_free_support(h0, maxiter, deadline, beta=0.0, thresh_rel=1e-3):
    """L-BFGS restricted to currently-nonzero (support) coordinates."""
    win = _support_window(h0, thresh_rel)
    return _lbfgs_block(h0, win, maxiter, deadline, beta=beta)


def _polish_quotient(c, deadline, maxiter=100):
    for beta in [1e6, 1e7, 0.0]:
        if time.process_time() >= deadline - 0.5:
            break
        c = _lbfgs_all_pos(c, maxiter, deadline, beta=beta)
    return c


def _lift_repeat(c):
    return _rescale(np.repeat(c, 2))


def _lift_odd(c):
    n = c.size
    h = np.zeros(2 * n + 2)
    h[1:2 * n + 1] = np.repeat(c, 2)
    return _rescale(h)


def _rotation_variants(best):
    n = best.size
    variants = []
    c_even = best[0::2].copy()
    variants.append(('even', c_even, _lift_repeat))
    if n >= 3:
        c_odd = best[1::2].copy()
        variants.append(('odd', c_odd, _lift_odd))
    m = min(best[0::2].size, best[1::2].size)
    c_avg = 0.5 * (best[0::2][:m] + best[1::2][:m])
    variants.append(('avg', c_avg, _lift_repeat))
    return variants


def _stride3_cycle(best, bestR, deadline, cyc):
    N = best.size
    m = N // 3
    if m < 4:
        return None, -1.0
    c = best[0:3 * m].reshape(m, 3).sum(axis=1)
    c = _rescale(c)
    dl = deadline
    if time.process_time() >= dl - 1.0:
        return None, -1.0
    c = _lbfgs_all_pos(c, 120, dl, beta=1e6)
    if time.process_time() < dl - 1.0:
        c = _lbfgs_all_pos(c, 120, dl, beta=1e7)
    if time.process_time() < dl - 1.0:
        c = _lbfgs_all_pos(c, 120, dl, beta=0.0)

    hA = np.zeros(N)
    hA[:3 * m] = np.repeat(c, 3)
    hA = _rescale(hA)
    rA = R_of(hA)

    rs = np.random.RandomState(31337 + cyc)
    w = np.exp(0.35 * rs.randn(3))
    w = w * 3.0 / w.sum()
    hB = np.zeros(N)
    hB[:3 * m] = np.repeat(c, 3) * np.tile(w, m)
    hB = _rescale(hB)
    rB = R_of(hB)

    h = hB if rB > rA else hA

    if time.process_time() < dl - 1.0:
        h = _lbfgs_all_pos(h, 150, dl, beta=1e6)
    if time.process_time() < dl - 1.0:
        h = _lbfgs_all_pos(h, 150, dl, beta=1e7)
    if time.process_time() < dl - 1.0:
        h = _lbfgs_block(h, _peak_window(h, 0.06, 128), 250, dl, beta=1e7)
    if time.process_time() < dl - 1.0:
        h = _lbfgs_all_pos(h, 200, dl, beta=0.0)
    return h, R_of(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1 (NEW): support-restricted polish. Big lever: most of the
    # support is zero. Optimising only nonzero coords is much cheaper per
    # iteration and avoids the flat gradient on zeroed steps. ----
    phase1_end = t0 + budget_seconds * 0.55
    work = best.copy()
    # start from a peak-window over the support region too (helps sharp peak)
    for _ in range(4):
        if time.process_time() >= phase1_end - 1.0:
            break
        ht = _lbfgs_free_support(work, 400, phase1_end - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = 'sup7'
        ht = _lbfgs_free_support(work, 400, phase1_end - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = 'sup0'
        # a peak-localised pass too
        win = _peak_window(work, pad_frac=0.05, extra=128)
        ht = _lbfgs_block(work, win, 400, phase1_end - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = 'pk7'
    print("phase1 R=%.9f origin=%s" % (bestR, origin))

    # ---- Phase 2: stride-3 mass fold + stride-2 rotation cycles ----
    cascade_start = t0 + budget_seconds * 0.55
    cascade_end = deadline - 3.0
    if time.process_time() < cascade_start:
        while time.process_time() < cascade_start - 0.05:
            time.sleep(0.005)

    cyc = 0
    while cyc < 2 and time.process_time() < cascade_end - 1.0:
        now = time.process_time()
        slice_dl = min(now + 10.0, deadline - 4.0)
        if slice_dl <= now + 0.8:
            break

        h3, r3 = _stride3_cycle(best, bestR, slice_dl, cyc)
        if h3 is not None:
            if r3 > bestR + 5e-14:
                best, bestR, origin = h3.copy(), r3, 's3_%d' % cyc
                print("stride3 cyc%d ACCEPT R=%.9f" % (cyc, bestR))
            elif r3 > alt_bestR:
                alt_best, alt_bestR = h3.copy(), r3

        if time.process_time() < slice_dl - 1.0:
            variants = _rotation_variants(best)
            order = ['even', 'odd', 'avg']
            rot = cyc % len(order)
            order = order[rot:] + order[:rot]
            vmap = {name: (c, lift) for name, c, lift in variants}
            rot_best_h = None
            rot_bestR = -1.0
            for name in order:
                if time.process_time() > slice_dl - 1.5:
                    break
                c, lift = vmap[name]
                c = _polish_quotient(c, slice_dl - 0.8, maxiter=80)
                if time.process_time() > slice_dl - 1.5:
                    break
                h = lift(c)
                if time.process_time() < slice_dl - 1.5:
                    h = _lbfgs_all_pos(h, 120, slice_dl - 0.8, beta=1e7)
                r = R_of(h)
                if r > rot_bestR:
                    rot_best_h, rot_bestR = h, r
            if rot_best_h is not None:
                if rot_bestR > bestR + 5e-14:
                    best, bestR, origin = rot_best_h.copy(), rot_bestR, 'rot_%d' % cyc
                    print("cycle %d rot ACCEPT best=%.9f" % (cyc, bestR))
                elif rot_bestR > alt_bestR:
                    alt_best, alt_bestR = rot_best_h.copy(), rot_bestR
        cyc += 1

    # ---- Phase 3: final support + peak ladder ----
    for pad in [0.10, 0.06, 0.04]:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR, origin = ht2.copy(), r2, origin + '+pk'
            print("final peak NEW BEST R=%.9f" % bestR)
        elif r2 > alt_bestR:
            alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_free_support(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+sup0'
            print("trailing support0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s, N=%d)" % (bestR, tag, best.size))
        elif r > alt_bestR and cand.size != best.size:
            alt_best, alt_bestR = cand.copy(), r

    # ---- Phase A: half-resolution quotient polish ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.15
        work_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # ---- Phase B: high-beta sharpening ladder ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=350)
        offer(ht, 'sharp')

    # ---- Experiment: keep fine (2x / 3x) parametrisation, never fold back ----
    fine_best = None
    fine_bestR = -1.0

    def offer_fine(cand, tag):
        nonlocal fine_best, fine_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return
        r = R_of(cand)
        if r > fine_bestR + 1e-14:
            fine_best, fine_bestR = cand.copy(), r
            print("FINE R=%.9f (%s, N=%d)" % (fine_bestR, tag, fine_best.size))

    # coarse argmax knot index m
    Lc = _knots(best)
    m = int(np.argmax(Lc))

    fine_deadline = deadline - 5.0
    n_rounds = 0
    while time.process_time() < fine_deadline - 2.0 and n_rounds < 2:
        h2 = _rescale(np.repeat(best, 2))
        r2 = R_of(h2)
        # verify exact reproduction
        if abs(r2 - bestR) > 1e-9:
            print("warn: repeat R mismatch %.3e" % (r2 - bestR))
        # (a) window polish on fine grid
        center = 2 * m
        lo = max(0, center - 900)
        hi = min(h2.size - 1, center + 900)
        win = np.arange(lo, hi + 1)
        for beta in (1e8, 1e7, 0.0):
            if time.process_time() >= fine_deadline - 1.0:
                break
            ht = _lbfgs_block(h2, win, 400, fine_deadline - 0.5, beta=beta)
            if R_of(ht) > R_of(h2) + 1e-14:
                h2 = ht
        # (b) polish + peak ladders on fine grid
        h2 = _polish_ladder(h2, fine_deadline - 0.5,
                            betas=(1e7, 1e8, 0.0), iters=250)
        h2 = _peak_ladder(h2, fine_deadline - 0.3, pads=(0.10, 0.06), iters=200)
        offer_fine(h2, '2x')
        n_rounds += 1

    # 3x attempt if time remains
    if time.process_time() < deadline - 6.0:
        h3 = _rescale(np.repeat(best, 3))
        h3 = _polish_ladder(h3, deadline - 3.0, betas=(1e7, 0.0), iters=200)
        h3 = _peak_ladder(h3, deadline - 2.0, pads=(0.10, 0.06), iters=150)
        offer_fine(h3, '3x')

    # ---- Phase C: sub-cell spike-shift sweeps on coarse best ----
    def _find_runs(h, min_frac=0.02):
        nz = h > 0
        if not nz.any():
            return []
        thr = min_frac * h.max()
        runs = []
        i, n = 0, h.size
        while i < n:
            if nz[i]:
                j = i
                while j + 1 < n and nz[j + 1]:
                    j += 1
                if h[i:j + 1].sum() >= thr:
                    runs.append((i, j))
                i = j + 1
            else:
                i += 1
        return runs

    def _shift_run(h, i, j, delta):
        prof = h[i:j + 1].copy()
        n = h.size
        out = h.copy()
        out[i:j + 1] = 0.0
        for k in range(prof.size):
            pos = (i + k) + delta
            lo = int(np.floor(pos))
            frac = pos - lo
            if 0 <= lo < n:
                out[lo] += prof[k] * (1.0 - frac)
            if 0 <= lo + 1 < n:
                out[lo + 1] += prof[k] * frac
        return np.clip(out, 0.0, None)

    def _repair(h, i, j, dl, iters=80):
        win = np.arange(max(0, i - 48), min(h.size, j + 49))
        pk = _peak_window(h, 0.10, 64)
        win = np.union1d(win, pk)
        return _lbfgs_block(h, win, iters, dl, beta=1e7)

    sweep_deadline = deadline - 3.0
    rng = np.random.RandomState(12345)
    sweep = 0
    while time.process_time() < sweep_deadline - 1.0:
        runs = _find_runs(best, min_frac=0.02)
        if not runs:
            break
        order = list(range(len(runs)))
        rng.shuffle(order)
        moved = None
        movedR = bestR
        tried = 0
        for ri in order:
            if time.process_time() > sweep_deadline - 1.5:
                break
            i, j = runs[ri]
            for delta in (0.5, -0.5):
                if time.process_time() > sweep_deadline - 1.5:
                    break
                cand = _shift_run(best, i, j, delta)
                if cand.sum() <= 0:
                    continue
                cand = _rescale(cand)
                cand = _repair(cand, i, j, sweep_deadline - 0.5, iters=80)
                r = R_of(cand)
                tried += 1
                if r > movedR + 1e-9:
                    moved, movedR = cand, r
        if moved is not None:
            best, bestR = moved, movedR
            print("sweep %d tried=%d ACCEPT R=%.9f" % (sweep, tried, bestR))
        else:
            print("sweep %d tried=%d no improvement best=%.9f" % (sweep, tried, bestR))

        if sweep % 4 == 3 and time.process_time() < sweep_deadline - 1.0:
            ht = _polish_ladder(best, sweep_deadline - 0.5,
                                betas=(1e7, 1e8, 0.0), iters=200)
            if R_of(ht) > bestR + 1e-14:
                best, bestR = ht, R_of(ht)
            win = _peak_window(best, 0.06, 128)
            ht = _lbfgs_block(best, win, 300, sweep_deadline - 0.5, beta=1e7)
            if R_of(ht) > bestR + 1e-14:
                best, bestR = ht, R_of(ht)
            print("sweep %d post-ladder R=%.9f" % (sweep, bestR))
        sweep += 1

    # ---- Phase D: final high-beta + pad ladder on coarse ----
    ht = _polish_ladder(best, deadline - 1.0, betas=(1e8, 1e9, 0.0), iters=350)
    offer(ht, 'finalhi')
    ht = _peak_ladder(best, deadline - 0.6, pads=(0.10, 0.06, 0.04), iters=400)
    offer(ht, 'finalpk')
    ht = _polish_ladder(best, deadline - 0.3, betas=(0.0,), iters=300)
    offer(ht, 'finalb0')

    # ---- choose overall best among coarse, fine ----
    overall = best
    overallR = bestR
    if fine_best is not None and fine_bestR > overallR + 1e-14:
        overall, overallR = fine_best, fine_bestR
        print("using FINE result R=%.9f N=%d" % (overallR, overall.size))

    print("final R=%.9f (start %.9f, N=%d)" % (overallR, start_bestR, overall.size))

    result = {"best": overall}
    if fine_best is not None and fine_best.size != overall.size:
        result["alternative"] = fine_best
    elif alt_best is not None and alt_best.size != overall.size:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r

    # ---- Phase A: half-resolution quotient polish (kept from base) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.18
        work_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # ---- Phase B: high-beta sharpening ladder (kept from base) ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=350)
        offer(ht, 'sharp')

    # ---- Phase C: NEW — deficit-band window free-optimise-prune ----
    def _band_window(h, lo_frac, hi_frac, pad_cells=150):
        """Largest contiguous run of knots with lo_frac*M <= g <= hi_frac*M,
        mapped to cells with padding."""
        Lf = _knots(h)
        M = Lf.max()
        if M <= 0:
            return None
        mask = (Lf >= lo_frac * M) & (Lf <= hi_frac * M)
        idx = np.flatnonzero(mask)
        if idx.size == 0:
            return None
        # largest contiguous run in knot index space
        breaks = np.flatnonzero(np.diff(idx) > 1)
        starts = np.concatenate(([0], breaks + 1))
        ends = np.concatenate((breaks, [idx.size - 1]))
        lens = ends - starts + 1
        k = int(np.argmax(lens))
        ka = int(idx[starts[k]])
        kb = int(idx[ends[k]])
        n = h.size
        lo = max(0, ka // 2 - pad_cells)
        hi = min(n - 1, kb // 2 + pad_cells)
        if hi <= lo:
            return None
        return lo, hi

    def _prune_in_window(h, lo, hi, thresh_frac=1e-4):
        out = h.copy()
        seg = out[lo:hi + 1]
        active = seg[seg > 0]
        if active.size == 0:
            return _rescale(out)
        thr = thresh_frac * active.mean()
        seg[seg < thr] = 0.0
        out[lo:hi + 1] = seg
        return _rescale(out)

    def _band_round(h, lo_frac, hi_frac, dl):
        bw = _band_window(h, lo_frac, hi_frac)
        if bw is None:
            return h, R_of(h)
        lo, hi = bw
        win = np.arange(lo, hi + 1)
        cur = h
        curR = R_of(cur)
        for beta in (1e8, 1e7, 0.0):
            if time.process_time() > dl - 0.5:
                break
            ht = _lbfgs_block(cur, win, 400, dl - 0.3, beta=beta)
            ht = _prune_in_window(ht, lo, hi)
            ht = _polish_ladder(ht, dl, betas=(1e7, 0.0), iters=200)
            r = R_of(ht)
            if r > curR + 1e-14:
                cur, curR = ht, r
        return cur, curR

    win_deadline = deadline - 6.0
    zf0 = _zero_frac(best)
    am0 = _argmax_frac(best)
    nm0 = _nearmax_frac(best)
    print("pre-band zero_frac=%.4f argmax_frac=%.4f nearmax5=%.4f"
          % (zf0, am0, nm0))

    bands = [(0.35, 0.65), (0.65, 0.90)]
    for rnd in range(4):
        if time.process_time() > win_deadline - 1.0:
            break
        lo_frac, hi_frac = bands[rnd % 2]
        cand, candR = _band_round(best, lo_frac, hi_frac, win_deadline)
        if candR > bestR + 1e-14:
            cand = _peak_ladder(cand, win_deadline, pads=(0.10, 0.06), iters=150)
            candR = R_of(cand)
            nm = _nearmax_frac(cand)
            zf = _zero_frac(cand)
            print("band[%.2f,%.2f] rnd=%d R=%.9f zero_frac=%.4f nearmax5=%.4f"
                  % (lo_frac, hi_frac, rnd, candR, zf, nm))
            offer(cand, 'band%d' % rnd)
        else:
            print("band[%.2f,%.2f] rnd=%d no gain (R=%.9f)"
                  % (lo_frac, hi_frac, rnd, candR))

    # ---- Phase D: final polish ----
    ht = _polish_ladder(best, deadline - 1.0, betas=(1e8, 0.0), iters=250)
    offer(ht, 'finalhi')
    ht = _peak_ladder(best, deadline - 0.6, pads=(0.06, 0.04), iters=300)
    offer(ht, 'finalpk')
    ht = _polish_ladder(best, deadline - 0.3, betas=(0.0,), iters=300)
    offer(ht, 'finalb0')

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
