                if n > mk:
                    h_new[mk:] = best[mk:]
                h_new = _rescale(h_new)
                h_new = _polish_ladder(h_new, stride_deadline - 0.3,
                                       betas=(1e6, 1e7, 1e8, 0.0), iters=250)
                h_new = _peak_ladder(h_new, stride_deadline - 0.3,
                                     pads=(0.10, 0.06), iters=200)
                r = R_of(h_new)
                if r > best_candR:
                    best_cand, best_candR = h_new, r
            if best_cand is not None:
                if best_candR > bestR + 1e-14:
                    best, bestR = best_cand.copy(), best_candR
                    accepted_strides.append(k)
                    any_progress = True
                    print("stride %d ACCEPT R=%.9f (c %.9f->%.9f)" %
                          (k, bestR, cR0, cR))
                else:
                    if best_candR > alt_bestR and best_cand.size == best.size:
                        alt_best, alt_bestR = best_cand.copy(), best_candR
                    print("stride %d no accept R=%.9f (c %.9f->%.9f, best %.9f)" %
                          (k, best_candR, cR0, cR, bestR))
        if not any_progress:
            break
    if accepted_strides:
        print("accepted strides: %s" % (accepted_strides,))

    # ---- Phase D: final high-beta + pad ladder ----
    ht = _polish_ladder(best, deadline - 1.0, betas=(1e8, 1e9, 0.0), iters=350)
    offer(ht, 'finalhi')
    ht = _peak_ladder(best, deadline - 0.6, pads=(0.10, 0.06, 0.04), iters=400)
    offer(ht, 'finalpk')
    ht = _polish_ladder(best, deadline - 0.3, betas=(0.0,), iters=300)
    offer(ht, 'finalb0')

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 300, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def _upsample_linear(h, N_big):
    """Smooth linear-interp upsample of heights (not mass-conserving) — new basin."""
    n = h.size
    x = np.linspace(0.0, 1.0, n)
    xb = np.linspace(0.0, 1.0, N_big)
    return np.clip(np.interp(xb, x, h), 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(20240607)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(64)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    alt = None
    alt_r = -1.0

    # NEW: try smooth upsampling to a larger grid to escape the current basin.
    if cur.size >= 64 and cur.size <= 200000 and time.process_time() < deadline - 25.0:
        Nbig = min(4 * cur.size, 200000)
        up = _upsample_linear(cur, Nbig)
        up = _rescale(up)
        # short log-space refine to settle
        up = _lbfgs_log(up, 200, min(deadline - 20.0, time.process_time() + 6.0))
        up_r = R_of(up)
        print("  upsample R = %.6f (N=%d)" % (up_r, up.size))
        if up_r > cur_r:
            cur, cur_r = up, up_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        else:
            alt, alt_r = up, up_r

    # Coarsen-refine branch (kept from original)
    if cur.size >= 128 and time.process_time() < deadline - 20.0:
        c = _rescale(_coarsen(cur, max(64, cur.size // 2)))
        c = _lbfgs_log(c, 300, deadline)
        c = _rescale(_prolongate(c, cur.size))
        c = _lbfgs_log(c, 300, deadline)
        r = R_of(c)
        if r > cur_r:
            cur, cur_r = c, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif alt is None or r > alt_r:
            alt, alt_r = c, r
        print("  coarsen-refine R = %.6f" % r)

    # Main alternating loop
    last_r = cur_r
    stagn = 0
    while time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(cur, 800, deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

        if cur_r <= last_r + 1e-9:
            stagn += 1
        else:
            stagn = 0
        last_r = cur_r

        if time.process_time() >= deadline - 1.0:
            break

        for frac in (0.03, 0.08, 0.15, 0.30):
            if time.process_time() >= deadline - 1.0:
                break
            free = _peak_window(cur, frac=frac)
            cand = _lbfgs_block(cur, free, 400, deadline)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r

        if stagn >= 2 and time.process_time() < deadline - 5.0:
            seed = _rescale(_prolongate(_coarsen(best, max(64, best.size // 2)), best.size))
            nz = np.flatnonzero(seed > 0)
            if nz.size:
                seed[nz] *= np.exp(rng.normal(0.0, min(0.05 * (stagn + 1), 0.2), nz.size))
            seed = _rescale(seed)
            cand = _lbfgs_log(seed, 600, deadline)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r
                stagn = 0
            else:
                cur = best.copy(); cur_r = best_r
                stagn = 0

    if time.process_time() < deadline - 0.5:
        bp, br = _polish(best, deadline)
        if br > best_r:
            best, best_r = bp, br

    if alt is not None and alt_r > best_r:
        best, best_r = alt.copy(), alt_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None and alt is not None and alt_r > 0 and alt_r < best_r:
        return {"best": best, "alternative": alt}
    return best

