    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r
        print("smooth R=%.8f" % best_r)

    # Peak-region alternating polish with smooth then plain objective.
    cur = _peak_polish(cur, deadline - 1.5)
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r
        print("peak   R=%.8f" % best_r)

    # If time remains, do a coarse-level exploration and prolongate, only
    # replacing if it strictly beats the incumbent.
    rng = np.random.default_rng(424242)
    while time.process_time() < deadline - 4.0:
        N = cur.size
        Nc = min(4000, N)
        hc = _coarsen(cur, Nc)
