    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline):
    round_no = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        best_cand = None
        best_cand_R = bestR
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
        else:
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    cur = R_of(h)
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > cur + 1e-14:
            h, cur = ht, r
    return h, cur


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    cur = R_of(h)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > cur + 1e-14:
            h, cur = ht, r
    return h, cur


def _extend_support(base, baseR, pad, deadline, decay=60.0):
    """Graded exponential continuation of the toes, then polish."""
    h = np.clip(np.asarray(base, dtype=float), 0, None).copy()
    if h.sum() <= 0:
        return h, baseR
    s0, s1 = _active_support(h)
    n = h.size
    A_L = float(np.max(h[s0:s0 + 8])) if s0 + 8 <= n else float(h[s0])
    A_R = float(np.max(h[max(0, s1 - 7):s1 + 1]))
    if A_L <= 0:
        A_L = float(h.max())
    if A_R <= 0:
        A_R = float(h.max())

    left = A_L * np.exp(-np.arange(pad, 0, -1, dtype=float) / decay)
    right = A_R * np.exp(-np.arange(1, pad + 1, dtype=float) / decay)
    h2 = np.concatenate([left, h, right])
    h2 = _rescale(h2)
    new_n = h2.size

    edge = min(2000, n)
    free = np.concatenate([
        np.arange(0, pad + edge),
        np.arange(new_n - pad - edge, new_n),
    ])
    free = np.unique(free)
    if time.process_time() < deadline - 0.5:
        h2 = _lbfgs_block(h2, free, 400, deadline - 0.5, beta=0.0)
    if time.process_time() < deadline - 0.5:
        h2 = _lbfgs_all_pos(h2, 400, deadline - 0.5, beta=0.0)

    r2 = R_of(h2)
    best, bestR = (h2, r2) if r2 > baseR + 1e-13 else (base, baseR)

    best, bestR = _peak_ladder(best, deadline, pads=(0.10, 0.05, 0.03),
                               iters=250)
    best, bestR = _polish_ladder(best, deadline, betas=(1e7, 0.0), iters=300)
    return best, bestR


def _dip_moves(best, bestR, deadline):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()
    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None
    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b)
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b)
    if best_h is None:
        return best, bestR
    a, b = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        return hp, rp
    if best_r > bestR + 1e-12:
        return best_h, best_r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- Graded support extension (main new idea) ----
    for pad in (8000, 4000):
        if time.process_time() >= deadline - 20.0:
            break
        try:
            eh, er = _extend_support(best, bestR, pad, deadline - 12.0)
            b01 = _band_frac(eh, 0.001)
            b1 = _band_frac(eh, 0.01)
            print("extend pad=%d: R=%.7f band01=%.2f%% band1=%.2f%%"
                  % (pad, er, 100 * b01, 100 * b1))
            if er > bestR + 1e-13:
                best, bestR = eh.copy(), er
            elif eh.size != best.size and er > altR:
                alt_cand, altR = eh.copy(), er
        except Exception as e:
            print("extend pad=%d failed: %s" % (pad, e))

    # ---- base cycle ----
    if time.process_time() < deadline - 8.0:
        best, bestR = run_cycle(best, bestR, deadline - 8.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- greedy edit loop (structural changes) ----
    if time.process_time() < deadline - 6.0:
        bg, bgr = _greedy_edit_loop(best, bestR, deadline - 6.0)
        if bgr > bestR + 1e-13:
            best, bestR = bg, bgr
            print("greedy edits win R=%.7f" % bestR)

    # ---- dip moves ----
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        before = bestR
        best, bestR = _dip_moves(best, bestR, deadline - 6.0)
        if bestR <= before + 1e-13:
            break
        now = time.process_time()
        if now - last_mini > 25.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop R=%.7f" % bestR)

    if time.process_time() < deadline - 0.5:
        best, bestR = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if alt_cand is not None and altR > start_bestR + 1e-13 and \
            altR <= bestR + 1e-13:
        return {"best": best, "alternative": alt_cand}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.99, pad_frac=0.10, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def polish(h, deadline, rounds=3):
    if time.process_time() > deadline - 0.5:
        return h
    h = _lbfgs_all_pos(h, 500, deadline)
    R = R_of(h)
    for beta in (50.0, 200.0, 800.0, 3000.0):
        if time.process_time() > deadline - 0.5:
            break
        hb = _lbfgs_all_pos(h, 200, deadline, beta=beta)
        Rb = R_of(hb)
        if Rb > R:
            R = Rb
            h = hb
    if time.process_time() < deadline - 0.5:
        h2 = _lbfgs_all_pos(h, 300, deadline)
        if R_of(h2) > R:
            h = h2
    for _ in range(rounds):
        if time.process_time() > deadline - 0.5:
            break
        win = _peak_window(h)
        h2 = _lbfgs_block(h, win, 300, deadline)
        if R_of(h2) > R_of(h):
            h = h2
    return h


def _beta_ladder(h, betas, iters, deadline):
    for beta in betas:
        if time.process_time() > deadline - 0.5:
            break
        h = _lbfgs_all_pos(h, iters, deadline, beta=beta)
    return h


def _prune(h, frac=0.03):
    h = np.clip(h, 0, None)
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h
    k = int(round(frac * nz.size))
    if k <= 0:
        return h
    vals = h[nz]
    order = np.argsort(vals)
    kill = nz[order[:k]]
    h = h.copy()
    h[kill] = 0.0
    return _rescale(h)


def _interlace_upsample(h, rng):
    N = h.size
    N2 = 2 * N
    u = 0.5 + 0.2 * np.sin(rng.uniform(0, 2 * np.pi, N))
    u = np.clip(u, 0.05, 0.95)
    hn = np.zeros(N2)
    hn[0::2] = h * (1.0 - u)
    hn[1::2] = h * u
    s = hn.sum()
    if s > 0:
        hn /= s
    return hn


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 3.0
    rng = np.random.default_rng(12345)

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best_h = s.copy()
            best_R = R_of(best_h)

    if best_h is None:
        Nbase = 4096
        x = np.linspace(0.0, 1.0, Nbase)
        cur = np.exp(-((x - 0.5) ** 2) / 0.02)
        cur /= cur.sum()
        best_h = cur.copy()
        best_R = R_of(cur)
    else:
        cur = best_h.copy()

    cur = polish(cur, min(deadline, t0 + budget_seconds * 0.30))
    R = R_of(cur)
    print("seed polish R =", R, "N =", len(cur))
    if R > best_R:
        best_R = R; best_h = cur.copy()

    for rnd in range(3):
        if time.process_time() > deadline - 4.0:
            break
        # (a) full-array beta ladder
        cur = _beta_ladder(cur, (1e6, 1e7, 1e8, 0.0), 250, deadline)
        R = R_of(cur)
        if R > best_R:
            best_R = R; best_h = cur.copy()
        # (b) prune smallest 3% of nonzero
        cur = _prune(cur, 0.03)
        R = R_of(cur)
        if R > best_R:
            best_R = R; best_h = cur.copy()
        # (c) peak polish at beta=1e7
        if time.process_time() < deadline - 4.0:
            win = _peak_window(cur, tol=0.99, pad_frac=0.10)
            h2 = _lbfgs_block(cur, win, 300, deadline, beta=1e7)
            if R_of(h2) > R_of(cur):
                cur = h2
            win = _peak_window(cur, tol=0.99, pad_frac=0.06)
            h2 = _lbfgs_block(cur, win, 300, deadline, beta=1e7)
            if R_of(h2) > R_of(cur):
                cur = h2
            R = R_of(cur)
            if R > best_R:
                best_R = R; best_h = cur.copy()
        # (d) interlace-upsample 2x + one beta ladder
        if time.process_time() < deadline - 4.0:
            up = _interlace_upsample(cur, rng)
            up = _beta_ladder(up, (1e6, 1e7, 0.0), 200, deadline)
            Rup = R_of(up)
            if Rup > R_of(cur) + 1e-14:
                cur = up
                R = Rup
                if R > best_R:
                    best_R = R; best_h = cur.copy()
        nz_frac = float(np.mean(cur <= 0))
        mean = cur.mean()
        mx = cur.max()
        print("round", rnd, "R =", R_of(cur), "N =", len(cur),
              "zero_frac =", round(nz_frac, 4),
              "max/mean =", round(mx / mean if mean > 0 else 0, 2))

    if time.process_time() < deadline - 0.5:
        hf = polish(best_h, deadline)
        Rf = R_of(hf)
        if Rf > best_R:
            best_R = Rf
            best_h = hf

    print("best R =", best_R, "N =", len(best_h))
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _mass_resample(h, Nnew):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    N = h.size
    if N == Nnew:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(Nnew) / Nnew
    x = np.linspace(0.0, 1.0, Nnew + 1)
    src_x = np.linspace(0.0, 1.0, N + 1)
    target_c = np.interp(x, src_x, c)
    out = np.diff(target_c)
    out = np.clip(out, 0, None)
    if out.sum() <= 0:
        return np.ones(Nnew) / Nnew
    return out * (total / out.sum())


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f N=%d" % (bestR, best.size))

    bestH = best.copy()
    bestRH = bestR

    # (A) Fine-grid lift candidates. Try resample + polish at several sizes.
    if time.process_time() < deadline - 25.0:
        candidates = []
        for factor in (2, 4, 8):
            if time.process_time() > deadline - 20.0:
                break
            Nnew = min(1000000, bestH.size * factor)
            if Nnew == bestH.size:
                continue
            h_lift = _mass_resample(bestH, Nnew)
            h_lift = _rescale(h_lift)
            sub_dl = min(deadline - 15.0, time.process_time() + 6.0)
            h_pol = _lbfgs_all_pos(h_lift, 200, sub_dl, beta=1e7)
            r_pol = R_of(h_pol)
            print("  lift x%d N=%d Rpol=%.7f" % (factor, Nnew, r_pol))
            candidates.append((r_pol, h_pol))
            if r_pol > bestRH + 1e-13:
                bestH, bestRH = h_pol.copy(), r_pol
        # Also try direct start on existing N with soft-max ladder
        if time.process_time() < deadline - 15.0:
            h_lad = _polish_ladder(bestH, min(deadline - 12.0,
                                              time.process_time() + 8.0),
                                   betas=(1e5, 1e6, 1e7, 0.0), iters=250)
            r_lad = R_of(h_lad)
            print("  soft-ladder R=%.7f" % r_lad)
            if r_lad > bestRH + 1e-13:
                bestH, bestRH = h_lad.copy(), r_lad

    # (B) Peak-window block refinement - concentrates effort near argmax.
    if time.process_time() < deadline - 8.0:
        h_pk = _peak_ladder(bestH, min(deadline - 6.0, time.process_time() + 10.0),
                            pads=(0.20, 0.12, 0.07, 0.04, 0.02), iters=300)
        r_pk = R_of(h_pk)
        print("  peak-ladder R=%.7f" % r_pk)
        if r_pk > bestRH + 1e-13:
            bestH, bestRH = h_pk.copy(), r_pk

    # (C) Alternating soft/hard loop until time runs out.
    round_i = 0
    while time.process_time() < deadline - 3.0:
        round_i += 1
        prev = bestRH
        if time.process_time() < deadline - 2.5:
            sub_dl = min(deadline - 1.5, time.process_time() + 4.0)
            h_s = _lbfgs_all_pos(bestH, 200, sub_dl, beta=1e7)
            r = R_of(h_s)
            if r > bestRH + 1e-13:
                bestH, bestRH = h_s.copy(), r
        if time.process_time() < deadline - 1.5:
            sub_dl = min(deadline - 1.0, time.process_time() + 3.0)
            h_h = _lbfgs_all_pos(bestH, 200, sub_dl, beta=0.0)
            r = R_of(h_h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h_h.copy(), r
        print("  round %d R=%.7f (dR=%.2e)" % (round_i, bestRH, bestRH - prev))
        if bestRH - prev < 1e-10:
            if time.process_time() < deadline - 3.0:
                rng = np.random.default_rng(round_i)
                h_j = bestH * (1.0 + 0.005 * rng.standard_normal(bestH.size))
                h_j = _rescale(h_j)
                if R_of(h_j) > bestRH - 1e-7:
                    bestH = h_j
            else:
                break

    if time.process_time() < deadline - 0.8:
        h = _lbfgs_all_pos(bestH, 500, deadline - 0.4, beta=0.0)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH
    else:
        best = start_best
        bestR = start_bestR

    Lf = _knots(best)
    mx = Lf.max(); m = int(np.argmax(Lf))
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.3e argmax=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": bestH if bestRH > start_bestR - 1e-6 else None}

