    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _fold_to_N(f3, N):
    """Cumulative-mass resampling of f3 (length 3m) onto N bins."""
    m3 = f3.size
    cum = np.concatenate(([0.0], np.cumsum(f3)))
    total = cum[-1]
    if total <= 0:
        return np.zeros(N)
    edges = np.linspace(0.0, total, N + 1)
    # bin index in f3 for each edge
    idx = np.searchsorted(cum, edges, side='right') - 1
    idx = np.clip(idx, 0, m3 - 1)
    # mass of each f3 cell
    cell = f3[idx]
    # approximate: output height = mass per output bin / width
    # width of output bin in f3 units = m3/N
    w = m3 / N
    out = (total / N) / w * np.ones(N)  # placeholder
    # Better: distribute mass proportionally
    # For each output bin, integrate f3 over its interval [a,b] in f3 coords
    a = np.linspace(0.0, m3, N + 1)
    # integrate piecewise-constant f3 over [a_i, a_{i+1}]
    res = np.zeros(N)
    for i in range(N):
        lo = a[i]; hi = a[i + 1]
        jlo = int(np.floor(lo)); jhi = int(np.floor(hi))
        if jlo == jhi:
            res[i] = f3[min(jlo, m3 - 1)] * (hi - lo)
        else:
            res[i] += f3[min(jlo, m3 - 1)] * (jlo + 1 - lo)
            for j in range(jlo + 1, jhi):
                res[i] += f3[j]
            if jhi < m3:
                res[i] += f3[jhi] * (hi - jhi)
    # height = mass / bin-width(=1 in output units); output bin width = 1
    return res


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Phase B: high-beta sharpening ladder (kept from base) ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=350)
        offer(ht, 'sharp')

    # ---- Phase E: 3:2 lift loop with alternating parity ----
    lift_deadline = deadline - 8.0
    lift_rounds = 0
    while lift_rounds < 6 and time.process_time() < lift_deadline:
        lift_rounds += 1
        N = best.size
        m = N // 2
        if m < 4:
            break
        parity = lift_rounds % 2  # odd rounds -> odd stride, even rounds -> even stride
        if parity == 1:
            c = best[1::2].copy()
            tag = 'oddlift'
        else:
            c = best[0::2].copy()
            tag = 'evenlift'
        if c.size < 4:
            continue
        c = _rescale(c)
        # (b) polish c
        c = _polish_ladder(c, lift_deadline, betas=(1e6, 1e7, 0.0), iters=300)
        c = _peak_ladder(c, lift_deadline, pads=(0.20, 0.12, 0.08), iters=300)
        # (c) build f3 with fresh log-normal sub-cell weights
        w = np.clip(np.exp(rng.normal(0.0, 0.45, size=3)), 0.2, 5.0)
        f3 = np.zeros(3 * c.size)
        for k in range(3):
            f3[k::3] = c * w[k]
        f3 = _rescale(f3)
        # (d) polish f3
        f3 = _polish_ladder(f3, lift_deadline, betas=(1e7, 1e8, 0.0), iters=300)
        f3 = _peak_ladder(f3, lift_deadline, pads=(0.10, 0.06), iters=250)
        # (e) fold back to N
        h_fold = _fold_to_N(f3, N)
        h_fold = _rescale(h_fold)
        h_fold = _polish_ladder(h_fold, lift_deadline, betas=(1e8, 0.0), iters=250)
        h_fold = _peak_ladder(h_fold, lift_deadline, pads=(0.06, 0.04), iters=250)
        # (f) accept
        r = R_of(h_fold)
        if h_fold.size == best.size and r > bestR + 1e-14:
            best, bestR = h_fold.copy(), r
            print("NEW BEST R=%.9f (%s round=%d)" % (bestR, tag, lift_rounds))
        else:
            print("lift round %d (%s) no gain R=%.9f" % (lift_rounds, tag, r))

    print("lift rounds=%d" % lift_rounds)

    # ---- Final Phase A: half-quotient polish ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = min(deadline - 2.0, time.process_time() + budget_seconds * 0.15)
        work_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # ---- Final sharp ladder ----
    ht = _polish_ladder(best, deadline - 1.0, betas=(1e8, 1e9, 0.0), iters=250)
    offer(ht, 'finalhi')

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _interlace(h, w):
    k = len(w)
    n = h.size
    out = np.empty(k * n, dtype=float)
    for j in range(k):
        out[j::k] = h * w[j]
    return out


def _fold(hk, k):
    n = hk.size // k
    return hk[:k * n].reshape(n, k).sum(axis=1)


def _opt_weights(h, k, deadline, max_evals=60):
    """Optimize k per-phase weights (w0..w_{k-1}) with w0=1."""
    best_w = np.ones(k)
    best_r = R_of(_interlace(h, best_w))
    evals = 1
    grid = np.array([0.6, 0.8, 1.0, 1.25, 1.6])
    # coordinate-wise coarse scan for k-1 weights
    for j in range(1, k):
        for g in grid:
            if evals >= max_evals or time.process_time() > deadline - 0.5:
                break
            w = best_w.copy()
            w[j] = g
            r = R_of(_interlace(h, w))
            evals += 1
            if r > best_r:
                best_r, best_w = r, w
    # Nelder-Mead refine
    if evals < max_evals and time.process_time() < deadline - 1.0:
        def neg_r(x):
            w = np.ones(k)
            for j in range(1, k):
                w[j] = max(1e-3, x[j - 1])
            return -R_of(_interlace(h, w))
        try:
            x0 = best_w[1:].copy()
            res = minimize(neg_r, x0, method='Nelder-Mead',
                           options={'xatol': 1e-4, 'fatol': 1e-11,
                                    'maxiter': 60, 'maxfev': max(20, max_evals - evals)})
            if res is not None and np.isfinite(res.fun):
                w = np.ones(k)
                for j in range(1, k):
                    w[j] = max(1e-3, res.x[j - 1])
                r = R_of(_interlace(h, w))
                if r > best_r:
                    best_r, best_w = r, w
        except Exception:
            pass
    return best_w, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Phase A: half-res quotient polish ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.16
        work_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # ---- Phase B: high-beta sharpening ladder ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=350)
        offer(ht, 'sharp')

    # ---- Phase C: multi-k interlaced lift with per-phase weights ----
    # Try k=2,3,4 (each fits within 1e6 steps), pick the best lift or fold.
    lift_deadline = deadline - 5.0
    if time.process_time() < lift_deadline - 2.0:
        best_lift = None
        best_liftR = -1.0
        best_lift_k = 1
        for k in (2, 3, 4):
            if best.size * k > 1000000:
                continue
            if time.process_time() > lift_deadline - 2.0:
                break
            w, r_w = _opt_weights(best, k, lift_deadline - 1.0, max_evals=50)
            hk = _rescale(_interlace(best, w))
            hk = _polish_ladder(hk, lift_deadline - 0.6,
                                betas=(1e6, 1e7, 0.0), iters=250)
            hk = _peak_ladder(hk, lift_deadline - 0.4,
                              pads=(0.10, 0.06, 0.04), iters=250)
            rk = R_of(hk)
            if rk > best_liftR:
                best_lift, best_liftR, best_lift_k = hk, rk, k
            print("lift%d weights=%s R=%.9f" % (k, np.round(w, 3), rk))
        if best_lift is not None and time.process_time() < deadline - 2.0:
            # fold back
            hfold = _rescale(_fold(best_lift, best_lift_k))
            hfold = _polish_ladder(hfold, deadline - 1.5, betas=(1e7, 0.0), iters=300)
            hfold = _peak_ladder(hfold, deadline - 1.0, pads=(0.08, 0.05), iters=300)
            rf = R_of(hfold)
            print("multi-k best k=%d R(3N)=%.9f R(fold)=%.9f"
                  % (best_lift_k, best_liftR, rf))
            if best_liftR >= rf:
                offer(best_lift, 'lift%d' % best_lift_k)
                offer(hfold, 'lift%d-fold-alt' % best_lift_k)
            else:
                offer(hfold, 'lift%d-fold' % best_lift_k)
                offer(best_lift, 'lift%d-alt' % best_lift_k)

    # ---- Phase D: final polish ----
    ht = _polish_ladder(best, deadline - 1.0, betas=(1e8, 0.0), iters=250)
    offer(ht, 'finalhi')
    ht = _peak_ladder(best, deadline - 0.6, pads=(0.06, 0.04), iters=300)
    offer(ht, 'finalpk')
    ht = _polish_ladder(best, deadline - 0.3, betas=(0.0,), iters=300)
    offer(ht, 'finalb0')

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _resample_to(h, N):
    """Cumulative-mass resampling of step function h to N equal steps."""
    h = np.clip(h, 0, None)
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.zeros(N)
    # target cumulative masses at the N+1 edges of the new grid
    tgt = np.linspace(0.0, total, N + 1)
    # interpolate inverse CDF at edges, then differences = new heights
    edges = np.interp(tgt, c, np.arange(n + 1, dtype=float))
    newh = np.diff(edges)
    return np.clip(newh, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Stride-3 cascade: 3-fold average quotient, polish, re-interlace ----
    N = best.size
    s3_deadline = deadline - 8.0
    rounds3 = 0
    acc3 = 0
    while time.process_time() < s3_deadline - 1.0 and rounds3 < 5:
        rounds3 += 1
        m = N // 3
        if m < 8:
            break
        # (a) mass-preserving 3-fold average
        c = best[0:3 * m].reshape(m, 3).mean(axis=1)
        c = _rescale(c)
        cR0 = R_of(c)
        # (b) polish quotient
        c = _polish_ladder(c, s3_deadline - 0.5,
                           betas=(1e6, 1e7, 0.0), iters=300)
        c = _peak_ladder(c, s3_deadline - 0.5,
                         pads=(0.25, 0.15, 0.10, 0.06), iters=300)
        cR1 = R_of(c)
        if time.process_time() >= s3_deadline - 0.5:
            break
        # (c) re-interlace with free per-phase weights
        w = np.clip(np.exp(rng.normal(0.0, 0.45, 3)), 0.2, 5.0)
        f3 = np.repeat(c, 3) * np.tile(w, m)
        f3 = _rescale(f3)
        # (d) polish the fine re-interlaced construction
        f3 = _polish_ladder(f3, s3_deadline - 0.5,
                            betas=(1e7, 1e8, 0.0), iters=300)
        f3 = _peak_ladder(f3, s3_deadline - 0.5,
                          pads=(0.10, 0.06), iters=250)
        # (e) fold back to exactly N
        cand = _resample_to(f3, N)
        cand = _rescale(cand)
        cand = _polish_ladder(cand, s3_deadline - 0.5,
                              betas=(1e8, 0.0), iters=250)
        cand = _peak_ladder(cand, s3_deadline - 0.5,
                            pads=(0.06, 0.04), iters=250)
        # (f) accept
        r = R_of(cand)
        if cand.size == best.size and r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            acc3 += 1
            print("stride3 round=%d accepted R=%.9f (c %.9f->%.9f, zero_frac=%.4f)"
                  % (rounds3, bestR, cR0, cR1, _zero_frac(best)))
        else:
            print("stride3 round=%d no accept R=%.9f (c %.9f->%.9f)"
                  % (rounds3, r, cR0, cR1))
        if time.process_time() >= s3_deadline - 1.0:
            break

    print("stride3 rounds=%d accepted=%d" % (rounds3, acc3))

    # ---- Phase A: half-resolution quotient polish ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = min(deadline - 2.0,
                            time.process_time() + budget_seconds * 0.10)
        work_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline - 1.0, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # ---- Final high-beta sharpening ladder ----
    ht = _polish_ladder(best, deadline - 1.0,
                        betas=(1e8, 1e9, 1e10, 0.0), iters=350)
    offer(ht, 'finalhi')

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    m = L.max()
    if m <= 0:
        return -1.0
    a = L[:-1]; b = L[1:]
    sq = np.sum(a * a + a * b + b * b) / 3.0
    return float(sq / (s * s * m))


def _num_and_dq(h):
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(L)
    dq[:-1] += (2.0 * a + b) / 3.0
    dq[1:] += (a + 2.0 * b) / 3.0
    return num, dq, L


def _backprop(gL, h):
    g = gL[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(g, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(g, h, mode='valid')[:n]


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, L = _num_and_dq(h)
    k = int(np.argmax(L))
    m = L[k]
    if m <= 0 or num <= 0:
        return 1e18, np.zeros(h.size)
    gL = -dq / num
    gL[k] += 1.0 / m
    gh = _backprop(gL, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(m)
    return val, gh


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(np.asarray(h0, dtype=float), 0, None)
    if h.sum() <= 0:
        return h0
    u0 = np.log(np.clip(h, 1e-12, None))

    def f(u):
        hh = np.exp(np.clip(u, -50.0, 50.0))
        val, g = _fun_grad(hh)
        return val, g * hh

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    return np.exp(np.clip(res.x, -50.0, 50.0))


def _lbfgs_block(h0, lo, hi, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(np.asarray(h0, dtype=float), 0, None)
    if h.sum() <= 0 or hi <= lo:
        return h0
    x0 = np.log(np.clip(h[lo:hi], 1e-12, None))

    def f(x):
        hh = h.copy()
        hh[lo:hi] = np.exp(np.clip(x, -50.0, 50.0))
        val, g = _fun_grad(hh)
        return val, g[lo:hi] * hh[lo:hi]

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    out = h.copy()
    out[lo:hi] = np.exp(np.clip(res.x, -50.0, 50.0))
    return out


def _resample_lin(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    edges = np.linspace(0.0, total, N + 1)
    vals = np.interp(edges, c, np.arange(M + 1, dtype=float))
    F = np.interp(vals, np.arange(M + 1, dtype=float), c)
    width = edges[1] - edges[0]
    out = np.diff(F) / width
    return np.maximum(out, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    def left():
        return deadline - time.process_time()

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            bestR = _R_of(best)

    if best is None:
        best = np.ones(256)
        bestR = _R_of(best)

    cur = best.copy()
    curR = bestR

    # Fine full polish at the current (large) resolution first.
    c = _lbfgs_log(cur, 400, deadline)
    r = _R_of(c)
    if r > curR:
        cur, curR = c, r
    if curR > bestR:
        best, bestR = cur.copy(), curR

    # Multi-resolution ladder: refine at finer resolutions to add detail.
    base_n = max(64, cur.size)
    targets = []
    for mult in (1.0, 1.5, 2.0, 3.0):
        N = int(base_n * mult)
        if 32 <= N <= 100000:
            targets.append(N)
    targets = sorted(set(targets))

    for N in targets:
        if left() < 1.0:
            break
        cand = _resample_lin(cur, N) if N != cur.size else cur.copy()
        r0 = _R_of(cand)
        if r0 < curR - 0.05:
            continue
        it = max(60, min(300, int(left() * 15)))
        c1 = _lbfgs_log(cand, it, deadline)
        r1 = _R_of(c1)
        if r1 > r0:
            cand, r0 = c1, r1
        if r0 > curR:
            cur, curR = cand, r0
        if curR > bestR:
            best, bestR = cur.copy(), curR

    # Window polish loop on best, targeting the peak region.
    fracs = (0.03, 0.06, 0.10, 0.18, 0.30)
    fi = 0
    while left() > 0.4:
        n = best.size
        L = _knots(best)
        k = int(np.argmax(L))
        f = fracs[fi % len(fracs)]
        fi += 1
        half = max(4, int(f * n))
        lo = max(0, (k - half) // 2 - 6)
        hi = min(n, (k + half) // 2 + 7)
        it = max(40, min(400, int(left() * 20)))
        cand = _lbfgs_block(best, lo, hi, it, deadline)
        r = _R_of(cand)
        if r > bestR:
            best, bestR = cand, r
        if fi % 4 == 0 and left() > 1.0:
            it = max(60, min(300, int(left() * 15)))
            cand = _lbfgs_log(best, it, deadline)
            r = _R_of(cand)
            if r > bestR:
                best, bestR = cand, r

    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.3, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, betas, iters, deadline):
    work = h
    workR = R_of(work)
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, iters, deadline, beta=beta)
        r = R_of(ht)
        if r > workR + 1e-14:
            work, workR = ht, r
    return work, workR


def _peak_ladder(h, pads, iters, deadline):
    work = h
    workR = R_of(work)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad)
        ht = _lbfgs_block(work, win, iters, deadline)
        r = R_of(ht)
        if r > workR + 1e-14:
            work, workR = ht, r
    return work, workR


def _interlace_32(c, targetN, rng):
    # build a finer array of size targetN from coarse c via 3:2 non-commensurate
    # interlace with fresh sub-cell weights (log-normal jitter)
    n = c.size
    x = np.linspace(0.0, 1.0, n + 1)
    xf = np.linspace(0.0, 1.0, targetN + 1)
    xc = 0.5 * (x[:-1] + x[1:])
    xfc = 0.5 * (xf[:-1] + xf[1:])
    h = np.interp(xfc, xc, c)
    # fresh log-normal jitter per cell, scaled by local magnitude
    jit = rng.normal(0.0, 0.08, size=targetN)
    h = h * np.exp(jit)
    return np.clip(h, 0, None)


def _fold_back(h_fine, targetN):
    n = h_fine.size
    if n == targetN:
        return h_fine.copy()
    # integrate fine cells into targetN coarse cells (mass preserving)
    edges = np.linspace(0, n, targetN + 1)
    out = np.zeros(targetN)
    for i in range(targetN):
        lo = int(np.floor(edges[i]))
        hi = int(np.ceil(edges[i + 1]))
        lo = max(0, min(n - 1, lo))
        hi = max(lo + 1, min(n, hi))
        seg = h_fine[lo:hi]
        out[i] = seg.mean() if seg.size > 0 else 0.0
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    N0 = best.size
    print("base R=%.7f N=%d" % (bestR, N0))

    rng = np.random.RandomState(12345)

    # Lift loop: half-quotient polish, 3:2 interlace, fold back, sharpen.
    rnd = 0
    while rnd < 5 and time.process_time() < deadline - 8.0:
        rnd += 1
        sub = min(deadline - 6.0, time.process_time() + 10.0)
        # (a) half-quotient
        if rnd % 2 == 1:
            c = best[0::2].copy()
        else:
            c = best[1::2].copy()
        c = _rescale(c)
        c, cR = _polish_ladder(c, (1e6, 1e7, 0.0), 250, sub)
        c, cR = _peak_ladder(c, (0.20, 0.12, 0.08), 250, sub)
        # (b) interlace to 3:2 finer
        targetN = max(c.size + 1, (3 * c.size) // 2)
        h_fine = _interlace_32(c, targetN, rng)
        h_fine = _rescale(h_fine)
        h_fine, fR = _polish_ladder(h_fine, (1e7, 0.0), 200, sub)
        # (c) fold back to N0 and sharpen
        h_back = _fold_back(h_fine, N0)
        h_back = _rescale(h_back)
        h_back, bR = _polish_ladder(h_back, (1e8, 0.0), 250, sub)
        h_back, bR = _peak_ladder(h_back, (0.06, 0.04), 250, sub)
        # (d) accept
        if bR > bestR + 1e-14:
            best, bestR = h_back.copy(), bR
            Lf = _knots(best)
            argm = float(np.argmax(Lf)) / best.size
            zf = float(np.mean(best <= 1e-12))
            print("lift.%d R=%.7f zf=%.4f argm=%.4f" % (rnd, bestR, zf, argm))
        else:
            print("lift.%d R=%.7f (no accept, best=%.7f)" % (rnd, bR, bestR))

    # Remaining budget: sharp ladder
    if time.process_time() < deadline - 1.0:
        sub = deadline - 0.5
        ht, r = _polish_ladder(best, (1e8, 1e9, 1e10, 0.0), 350, sub)
        if r > bestR + 1e-14:
            best, bestR = ht, r
        print("sharp R=%.7f (best=%.7f)" % (r, bestR))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
