    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _up_resample(h, N_big):
    n = h.size
    if n == N_big:
        return h.copy()
    x = np.linspace(0.0, 1.0, n)
    xb = np.linspace(0.0, 1.0, N_big)
    hb = np.interp(xb, x, h)
    return np.clip(hb, 0.0, None)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
    else:
        base = None

    if base is not None and base.size > 0 and base.sum() > 0:
        best = _rescale(base)
        bestR = R_of(best)
    else:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW IDEA: refine the start by resampling onto a MODERATE grid (not 2x,
    # which dilutes the sharp peak), then polishing with a sharp log-barrier
    # ladder, then going back down.  The key insight is that the peak's
    # resolution is what matters, and moving to a coarser grid aligns the
    # peak with grid points, giving L-BFGS a smoother landscape to descend.

    # Stage 1: peak-focused polish on the original grid.
    if time.process_time() < deadline - 30.0:
        h = _peak_ladder(best, deadline - 20.0, pads=(0.20, 0.10, 0.05), iters=300)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
        print("peak ladder R=%.7f" % bestR)

    # Stage 2: coarse resample (0.75x) then re-polish, then upsample to 1.5x.
    # Coarsening helps align the peak; upsampling gives finer resolution.
    for factor in (0.75, 1.5, 2.0):
        if time.process_time() >= deadline - 15.0:
            break
        N_new = int(best.size * factor)
        if N_new < 16 or N_new > 1000000:
            continue
        hr = _up_resample(best, N_new)
        hr = _rescale(hr)
        rr = R_of(hr)
        # sharp barrier ladder on resampled grid
        for beta in (1e6, 1e7, 0.0):
            if time.process_time() >= deadline - 14.0:
                break
            win = _peak_window(hr, pad_frac=0.3, extra=64)
            ht = _lbfgs_block(hr, win, 300, deadline - 2.0, beta=beta)
            if R_of(ht) > rr + 1e-14:
                hr = ht
                rr = R_of(hr)
        if rr > bestR + 1e-13:
            best, bestR = hr.copy(), rr
            print("resample %.2fx R=%.7f (N=%d)" % (factor, bestR, best.size))

    # Stage 3: final sharp polish on current grid, alternating with peak ladder.
    for _ in range(8):
        if time.process_time() >= deadline - 1.5:
            break
        h = _peak_ladder(best, deadline - 0.5, pads=(0.08, 0.04, 0.02), iters=400)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
        else:
            # try a global sharp pass
            win = np.arange(best.size)
            h = _lbfgs_block(best, win, 500, deadline - 0.5, beta=0.0)
            r = R_of(h)
            if r > bestR + 1e-13:
                best, bestR = h, r
                print("final sharp R=%.7f" % bestR)
            else:
                break

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-5 else None}

