    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_sm(hh, beta)) if beta else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xc = np.linspace(0.0, 1.0, Nc + 1)
    Sc = np.interp(xc, xs, S)
    Sc = np.maximum.accumulate(Sc)
    hc = np.clip(np.diff(Sc), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _block_perturb(h, rng, nblocks_lo=6, nblocks_hi=12, sigma=0.30):
    h = h.copy()
    n = h.size
    if n < 4:
        return h
    nblocks = int(rng.integers(nblocks_lo, nblocks_hi + 1))
    W = n
    cuts = np.sort(rng.choice(np.arange(1, W), size=min(nblocks - 1, W - 1),
                              replace=False))
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(len(edges) - 1):
        a = edges[b]
        c = edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, sigma))
        h[a:c] *= fac
    pos = h[h > 0]
    if pos.size > 0:
        local_mean = pos.mean()
        z = h <= 0
        if np.any(z):
            h[z] = 1e-3 * local_mean
    return _rescale(h)


def _smooth_perturb(h, rng, sigma=0.05, nmodes=6):
    """Smooth multiplicative perturbation via low-frequency sinusoid sum."""
    n = h.size
    x = np.linspace(0.0, np.pi, n)
    field = np.zeros(n)
    for _ in range(nmodes):
        k = rng.integers(1, 8)
        ph = rng.uniform(0, 2 * np.pi)
        amp = rng.normal(0.0, 1.0)
        field += amp * np.sin(k * x + ph)
    field = field / (np.abs(field).max() + 1e-12)
    h = h * np.exp(sigma * field)
    return _rescale(h)


def _sharpen(h, deadline):
    """Increase resolution: prolongate to 2x and refine log-param."""
    n = h.size
    if n >= 200000:
        return h
    h2 = _prolongate(h, 2 * n)
    return _lbfgs_log(h2, maxiter=400, deadline=deadline)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(98765)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal cur, cur_r, best, best_r, alternative, alt_r
        if r > cur_r:
            cur, cur_r = cand, r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    hard_end = deadline - 0.5
    N = cur.size
    Nc = min(8000, N)

    # ---------------- Experiment 1: sharpen resolution + smooth perturb ----
    try:
        base = cur.copy()
        # Sharpen: do one doubling and refine
        if time.process_time() < hard_end - 8.0:
            base = _sharpen(base, hard_end - 6.0)
        base_r = R_of(base)
        if base_r > cur_r:
            cur, cur_r = base, base_r
            _consider(base, base_r)

        # Smooth perturbation search around the sharpened base
        best_sm = base
        best_sm_r = base_r
        n_trials = 12
        for seed in range(n_trials):
            if time.process_time() >= hard_end - 3.0:
                break
            rng_s = np.random.default_rng(5000 + seed)
            hs = _smooth_perturb(base, rng_s, sigma=0.04 + 0.03 * (seed % 3),
                                 nmodes=5 + seed % 4)
            hs = _lbfgs_log(hs, maxiter=400, deadline=hard_end - 2.0,
                            beta=None)
            rs = R_of(hs)
            if rs > best_sm_r:
                best_sm, best_sm_r = hs, rs
        _consider(best_sm, best_sm_r)
        print("smooth R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    # ---------------- Experiment 2: coarse envelope block moves -----------
    try:
        hc0 = _coarsen(cur, Nc)
        coarse_cands = []
        n_seeds = 6
        for seed in range(n_seeds):
            if time.process_time() >= hard_end - 2.0:
                break
            rng_s = np.random.default_rng(2000 + seed)
            hc = _block_perturb(hc0, rng_s)
            hc = _lbfgs_log(hc, maxiter=600, deadline=hard_end)
            rc = R_of(hc)
            coarse_cands.append((rc, hc))
        coarse_cands.sort(key=lambda t: -t[0])
        top = coarse_cands[:2]

        for rc, hc in top:
            if time.process_time() >= hard_end - 1.0:
                break
            h = _prolongate(hc, N)
            for beta in (300.0, 800.0, 2000.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_log(h, maxiter=300, deadline=hard_end, beta=beta)
                if R_of(c) >= R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=600, deadline=hard_end)
                if R_of(c) >= R_of(h):
                    h = c
            for frac in (0.15, 0.30):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, 8, maxiter=400,
                                        beta=None)
                if R_of(c) >= R_of(h):
                    h = c
            _consider(h, R_of(h))
        print("experiment R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    # ---------------- Fallback: base-style refinement if time remains ------
    try:
        while time.process_time() < hard_end - 1.0:
            h = cur.copy()
            for beta in (120.0, 60.0, 30.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_log(h, maxiter=250, deadline=hard_end, beta=beta)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=600, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, extra,
                                        maxiter=400, beta=None)
                if R_of(c) > R_of(h):
                    h = c
            _consider(h, R_of(h))
            if time.process_time() >= hard_end - 1.0:
                break
        print("fallback R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    if best_r < R_of(start_arr):
        best = start_arr.copy()
        best_r = R_of(best)

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _nearmax_frac_001(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= 0.999 * mx))


def _fold_back(h_fine, n_target):
    n = h_fine.size
    if n == n_target:
        return h_fine.copy()
    cm = np.cumsum(h_fine)
    if cm[-1] <= 0:
        return np.zeros(n_target)
    cm = cm / cm[-1]
    t = (np.arange(n_target) + 0.5) / n_target
    idx = np.searchsorted(cm, t)
    idx = np.clip(idx, 0, n - 1)
    return h_fine[idx].astype(float)


def _interlace(h, rng, amp=0.25):
    """Build 2N array: h2[2i]=h[i]*w0[i], h2[2i+1]=h[i]*w1[i]."""
    N = h.size
    w0 = np.exp(amp * rng.standard_normal(N))
    w1 = np.exp(amp * rng.standard_normal(N))
    h2 = np.empty(2 * N, dtype=float)
    h2[0::2] = h * w0
    h2[1::2] = h * w1
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    def offer(cand, tag):
        nonlocal best, bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        return False

    # ---- Phase A: half-resolution quotient polish ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.18
        work_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # ---- Phase B: high-beta sharpening ladder ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=350)
        offer(ht, 'sharp')

    # ---- Fine-resolution track ----
    N = best.size
    fine_best = None
    fine_bestR = -1.0
    coarse_seed = best.copy()

    fine_deadline = deadline - 8.0
    rounds = 0
    while time.process_time() < fine_deadline - 2.0 and rounds < 4:
        rounds += 1
        h2 = _interlace(coarse_seed, rng, amp=0.25)
        h2 = _rescale(h2)
        h2 = _polish_ladder(h2, fine_deadline,
                            betas=(1e6, 1e7, 1e8, 0.0), iters=300)
        h2 = _peak_ladder(h2, fine_deadline,
                          pads=(0.10, 0.06, 0.04), iters=300)
        r2 = R_of(h2)
        print("fine round=%d R=%.9f" % (rounds, r2))
        if r2 > fine_bestR + 1e-14:
            fine_best, fine_bestR = h2.copy(), r2
        # next coarse seed: fold back and brief polish
        if time.process_time() < fine_deadline - 2.0:
            hc = _fold_back(fine_best, N)
            hc = _rescale(hc)
            hc = _polish_ladder(hc, fine_deadline, betas=(1e7, 0.0), iters=150)
            coarse_seed = hc

    # ---- Final fine high-beta ladder ----
    if fine_best is not None and time.process_time() < deadline - 2.0:
        hf = _polish_ladder(fine_best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=350)
        hf = _peak_ladder(hf, deadline - 0.5, pads=(0.05, 0.03), iters=300)
        rf = R_of(hf)
        if rf > fine_bestR + 1e-14:
            fine_best, fine_bestR = hf.copy(), rf

    # ---- Compare and return ----
    result = {"best": best}
    if fine_best is not None:
        folded = _fold_back(fine_best, N)
        folded = _rescale(folded)
        r_fold = R_of(folded)
        print("fine R=%.9f (N=%d) vs coarse-fold R=%.9f (N=%d) vs best R=%.9f"
              % (fine_bestR, fine_best.size, r_fold, N, bestR))
        print("fine nearmax5=%.4f nearmax0.1=%.4f zero_frac=%.4f"
              % (_nearmax_frac(fine_best), _nearmax_frac_001(fine_best),
                 _zero_frac(fine_best)))
        if fine_bestR > bestR + 1e-14:
            result["best"] = fine_best
            result["alternative"] = best
            print("RETURN fine (gain %.3e)" % (fine_bestR - bestR))
        else:
            result["alternative"] = fine_best
            print("RETURN coarse (fine did not beat)")

    print("final R=%.9f (start %.9f)" % (R_of(result["best"]), start_bestR))
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    """Optimise active (positive) heights in log-space, positivity-preserving."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _argmax_pos(h):
    Lf = _knots(h)
    return int(np.argmax(Lf)) / max(1, Lf.size - 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


# ---- Restriction / prolongation (area-averaging, mass-preserving) ----

def _restrict(h, k):
    n = h.size
    m = (n + k - 1) // k
    out = np.empty(m)
    for i in range(m):
        lo = i * k
        hi = min(lo + k, n)
        out[i] = h[lo:hi].mean()
    return out


def _prolong(hc, k, n_full):
    out = np.repeat(hc, k)
    if out.size >= n_full:
        return _rescale(out[:n_full])
    pad = n_full - out.size
    return _rescale(np.concatenate((out, np.full(pad, out[-1]))))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None and np.asarray(start).size > 0 and np.sum(start) > 0:
        base = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        best = base.copy()
        bestR = R_of(best)
    else:
        N = 4096
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f N=%d argmax=%.4f" % (bestR, best.size, _argmax_pos(best)))

    def try_new(name, cand):
        nonlocal best, bestR
        if cand is None:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("  %s NEW R=%.9f N=%d argmax=%.4f" %
                  (name, bestR, best.size, _argmax_pos(best)))
            return True
        return False

    loop_end = deadline - 0.5
    n_full = best.size

    # ---- Coarse restriction / optimize / prolongation ladder ----
    cycle = 0
    while time.process_time() < loop_end - 4.0:
        cycle += 1
        improved_this_cycle = False
        for k in (2, 3, 4, 5, 7):
            if time.process_time() >= loop_end - 4.0:
                break
            hc = _restrict(best, k)
            if hc.size < 8:
                continue
            cap = min(loop_end, time.process_time() + 3.0)
            hc = _lbfgs_log(hc, 150, cap, beta=0.0)
            r_after_coarse = R_of(hc)
            for beta in (1e5, 1e6, 1e7):
                if time.process_time() >= loop_end - 4.0:
                    break
                cap = min(loop_end, time.process_time() + 1.5)
                hq = _lbfgs_log(hc, 120, cap, beta=beta)
                if R_of(hq) > R_of(hc):
                    hc = hq
            hp = _prolong(hc, k, n_full)
            cap = min(loop_end, time.process_time() + 2.5)
            hp = _peak_ladder(hp, cap)
            rp = R_of(hp)
            print("  k=%d c=%d R_coarse=%.9f R_prolong=%.9f" %
                  (k, cycle, r_after_coarse, rp))
            if rp > bestR + 1e-14:
                if try_new("k=%d c=%d" % (k, cycle), hp):
                    improved_this_cycle = True
        if not improved_this_cycle:
            if time.process_time() < loop_end - 2.0:
                cap = min(loop_end, time.process_time() + 3.0)
                hf = _lbfgs_log(best, 250, cap, beta=0.0)
                try_new("full c=%d" % cycle, hf)

    # ---- Final long polish: peak ladder + full log pass ----
    if time.process_time() < loop_end:
        cap = min(loop_end, time.process_time() + 6.0)
        hf = _lbfgs_log(best, 600, cap, beta=0.0)
        try_new("final lbfgs", hf)
    if time.process_time() < loop_end:
        hp = _peak_ladder(best, loop_end, pads=(0.05, 0.03, 0.02, 0.015), iters=500)
        try_new("final peak", hp)

    if bestR < start_bestR:
        best, bestR = start_best, start_bestR

    print("final R=%.9f N=%d argmax=%.4f" % (bestR, best.size, _argmax_pos(best)))

    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
