def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift_stride(c, s, rng=None):
    N = c.size * s
    if rng is None:
        return _rescale(np.repeat(c, s))
    w = np.exp(0.25 * rng.randn(s))
    w = w * (s / w.sum())
    out = np.repeat(c, s) * np.tile(w, c.size)
    return _rescale(np.clip(out, 0.0, None))


def _smooth_extend(h, factor, rng):
    """Insert `factor-1` interpolated points between each pair, with jitter."""
    n = h.size
    N = n * factor
    x_old = np.arange(n, dtype=float)
    x_new = np.arange(N, dtype=float) / factor
    out = np.interp(x_new, x_old, h)
    # small multiplicative jitter to break symmetry
    out *= np.exp(0.15 * rng.randn(N))
    return _rescale(np.clip(out, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient polish ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.25
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: alternating-stride quotient polish + lift ----
    jit_start = t0 + budget_seconds * 0.28
    jit_end = deadline - 7.0
    if time.process_time() < jit_start:
        while time.process_time() < jit_start - 0.05:
            time.sleep(0.01)
    cycle = [2, 4, 2, 8, 4, 2]
    if time.process_time() < jit_end - 1.0 and best.size >= 8:
        rnd = 0
        while time.process_time() < jit_end - 1.0:
            now = time.process_time()
            slice_dl = min(now + 5.5, deadline - 7.0)
            if slice_dl <= now + 0.8:
                break
            s = cycle[rnd % len(cycle)]
            Ncur = best.size
            if Ncur % s != 0:
                s = 2
                if Ncur % 2 != 0:
                    break
            c = best[0::s].copy()
            cR0 = R_of(c)
            work_c, best_c, best_cR, org = _half_cycle(
                c, cR0, slice_dl - 0.5, tag='s%d_%d' % (s, rnd))
            if time.process_time() >= slice_dl - 0.4:
                rnd += 1
                continue
            rng = None if rnd == 0 else np.random.RandomState(4000 + rnd)
            h = _lift_stride(best_c, s, rng)
            if time.process_time() < slice_dl - 0.3:
                h = _lbfgs_all_pos(h, 120, slice_dl - 0.2, beta=1e6)
            if time.process_time() < slice_dl - 0.3:
                h = _lbfgs_all_pos(h, 120, slice_dl - 0.2, beta=1e7)
            if time.process_time() < slice_dl - 0.3:
                win = _peak_window(h, pad_frac=0.06, extra=128)
                h = _lbfgs_block(h, win, 180, slice_dl - 0.2, beta=1e7)
            if time.process_time() < slice_dl - 0.3:
                h = _lbfgs_all_pos(h, 120, slice_dl - 0.2, beta=0.0)
            r = R_of(h)
            acc = False
            if h.size == best.size and r > bestR + 1e-13:
                best, bestR = h.copy(), r
                origin = 'stride%d_r%d' % (s, rnd)
                acc = True
            elif r > alt_bestR:
                alt_best, alt_bestR = h.copy(), r
            print("stride %d round %d R(c)=%.9f postLift=%.9f %s (best %.9f)"
                  % (s, rnd, best_cR, r, "ACCEPT" if acc else "reject", bestR))
            rnd += 1

    # ---- Phase 2b: refinement at higher resolution (upsample + polish) ----
    # Take best, upsample by factor 2 with interpolation + jitter, polish.
    # This is a genuinely different structural change: it grows N, giving the
    # optimiser finer degrees of freedom around the peak region.
    refine_end = deadline - 3.5
    if time.process_time() < refine_end - 1.5 and best.size < 500000:
        rng = np.random.RandomState(777)
        factor = 2
        h_up = _smooth_extend(best, factor, rng)
        r0 = R_of(h_up)
        # Polish: peak-focused then all-pos
        for beta in [1e6, 1e7]:
            if time.process_time() >= refine_end - 0.8:
                break
            h_up = _lbfgs_all_pos(h_up, 250, refine_end - 0.4, beta=beta)
        if time.process_time() < refine_end - 0.6:
            win = _peak_window(h_up, pad_frac=0.05, extra=256)
            h_up = _lbfgs_block(h_up, win, 300, refine_end - 0.3, beta=1e7)
        if time.process_time() < refine_end - 0.4:
            h_up = _lbfgs_all_pos(h_up, 200, refine_end - 0.2, beta=0.0)
        r1 = R_of(h_up)
        print("refine x%d R: %.9f -> %.9f (best %.9f)" % (factor, r0, r1, bestR))
        if r1 > bestR + 1e-13:
            best, bestR = h_up.copy(), r1
            origin = 'refine_x%d' % factor
            print("refine NEW BEST R=%.9f" % bestR)
        elif r1 > alt_bestR:
            alt_best, alt_bestR = h_up.copy(), r1

    # ---- Phase 3: final pad ladder + beta ladder ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _interlace_32(c, n_target, rng):
    m = c.size
    if m < 2:
        return np.repeat(c, max(1, n_target // max(1, m)))[:n_target]
    cm = np.cumsum(c)
    cm = cm / cm[-1]
    t = (np.arange(n_target) + 0.5) / n_target
    jitter = np.exp(0.02 * rng.standard_normal(n_target))
    t = np.clip(t * jitter, 1e-9, 1 - 1e-9)
    idx = np.searchsorted(cm, t)
    idx = np.clip(idx, 0, m - 1)
    return c[idx].astype(float)


def _fold_back(h_fine, n_target):
    n = h_fine.size
    if n == n_target:
        return h_fine.copy()
    cm = np.cumsum(h_fine)
    if cm[-1] <= 0:
        return np.zeros(n_target)
    cm = cm / cm[-1]
    t = (np.arange(n_target) + 0.5) / n_target
    idx = np.searchsorted(cm, t)
    idx = np.clip(idx, 0, n - 1)
    return h_fine[idx].astype(float)


def _transport(h, rng, amp, kind):
    """Mass-conserving adjacent-cell transport perturbation."""
    h = np.clip(h, 0, None).copy()
    N = h.size
    if N < 2:
        return h
    if kind == 'pair':
        active = np.flatnonzero(h > 0)
        if active.size == 0:
            return h
        K = max(1, int(0.01 * active.size))
        K = min(K, active.size)
        sel = rng.choice(active, size=K, replace=False)
        d = amp * h[sel] * rng.standard_normal(K)
        for i, di in zip(sel, d):
            if i + 1 < N:
                h[i] -= di
                h[i + 1] += di
            else:
                h[i] -= di
                h[i - 1] += di
        h = np.clip(h, 0, None)
    else:  # 'walk'
        width = max(2, int(0.1 * N))
        if width >= N:
            lo = 0
            hi = N
        else:
            lo = int(rng.integers(0, N - width + 1))
            hi = lo + width
        w = np.cumsum(rng.standard_normal(hi - lo))
        w = w - w.mean()
        mx = np.abs(w).max()
        if mx > 0:
            w = w / mx
        band = h[lo:hi]
        h[lo:hi] = band + amp * band * w
        h = np.clip(h, 0, None)
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(987654321)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Phase A: half-resolution polish (kept from base) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.15
        work_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # ---- Phase T: mass-conserving transport escape (the experiment) ----
    transport_deadline = deadline - 7.0
    amps = [0.30, 0.30, 0.15, 0.15, 0.08, 0.08, 0.04, 0.04,
            0.02, 0.02, 0.01, 0.01, 0.005, 0.005]
    kinds = ['pair', 'walk']
    accepted = 0
    for cyc in range(14):
        if time.process_time() >= transport_deadline - 2.0:
            break
        amp = amps[cyc % len(amps)]
        kind = kinds[cyc % 2]
        ht = _transport(best, rng, amp, kind)
        ht = _polish_ladder(ht, transport_deadline, betas=(1e6, 1e7, 0.0), iters=200)
        ht = _peak_ladder(ht, transport_deadline, pads=(0.10, 0.06, 0.04), iters=200)
        r = R_of(ht)
        improved = r > bestR + 1e-14
        if improved:
            best, bestR = ht.copy(), r
            accepted += 1
            print("NEW BEST (transport) R=%.9f cyc=%d amp=%.3f kind=%s"
                  % (bestR, cyc, amp, kind))
        else:
            print("transport cyc=%d amp=%.3f kind=%s R=%.9f (best %.9f) rejected"
                  % (cyc, amp, kind, r, bestR))

        # Every third cycle: 3:2 interlace lift
        if cyc % 3 == 2 and time.process_time() < transport_deadline - 3.0:
            N = best.size
            if N >= 4:
                c = best[0::2].copy()
                c = _polish_ladder(c, transport_deadline, betas=(1e6, 1e7, 0.0), iters=150)
                n_fine = max(4, 3 * c.size // 2)
                w = np.exp(0.02 * rng.standard_normal(n_fine))
                h_fine = _interlace_32(c, n_fine, rng) * w
                h_fine = _rescale(h_fine)
                h_fine = _polish_ladder(h_fine, transport_deadline,
                                        betas=(1e7, 0.0), iters=150)
                h_back = _fold_back(h_fine, N)
                h_back = _rescale(h_back)
                h_back = _peak_ladder(h_back, transport_deadline,
                                      pads=(0.06, 0.04), iters=200)
                r2 = R_of(h_back)
                if r2 > bestR + 1e-14:
                    best, bestR = h_back.copy(), r2
                    accepted += 1
                    print("NEW BEST (lift) R=%.9f cyc=%d" % (bestR, cyc))
                else:
                    print("lift cyc=%d R=%.9f (best %.9f) rejected"
                          % (cyc, r2, bestR))

    print("transport cycles accepted=%d" % accepted)

    # ---- Final polish ----
    ht = _polish_ladder(best, deadline - 1.0, betas=(1e8, 1e9, 1e10, 0.0), iters=300)
    if R_of(ht) > bestR + 1e-14:
        best, bestR = ht.copy(), R_of(ht)
        print("NEW BEST (finalhi) R=%.9f" % bestR)
    ht2 = _peak_ladder(best, deadline - 0.5, pads=(0.06, 0.04), iters=250)
    if R_of(ht2) > bestR + 1e-14:
        best, bestR = ht2.copy(), R_of(ht2)
        print("NEW BEST (finalpeak) R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

