def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- New idea: shrink-to-smaller-N then re-prolong-refine ----
    # A smaller N lets L-BFGS move masses more freely (each step moves a
    # larger fraction of mass), escaping the local basin that traps the
    # fine-grained optimum, then we prolong back and re-optimise.
    alt_best = None
    alt_bestR = 0.0
    if start_best is not None and start_best.size > 64:
        for frac in (0.25, 0.5):
            if time.process_time() >= deadline - 5.0:
                break
            Nn = max(256, int(start_best.size * frac))
            hs = _shrink(start_best, Nn)
            hd = min(deadline - 3.0, time.process_time() + budget_seconds * 0.10)
            hs, rs = run_cycle(hs, R_of(hs), hd)
            # prolong back to original N and refine
            if time.process_time() < deadline - 3.0:
                hp = _prolong(hs, start_best.size)
                hd2 = min(deadline - 1.0, time.process_time() + budget_seconds * 0.10)
                hp, rp = run_cycle(hp, R_of(hp), hd2)
                if rp > alt_bestR:
                    alt_best, alt_bestR = hp, rp
                print("shrink frac=%.2f N=%d -> R=%.7f (prolonged)" % (frac, Nn, rp))

    # ---- Main pipeline: run_cycle on start_best ----
    if time.process_time() < deadline - 1.5:
        b, bR = run_cycle(best, bestR, deadline - 1.0)
        if bR > bestR:
            best, bestR = b, bR

    # ---- Warp restarts ----
    for gamma in (0.92, 1.08):
        if time.process_time() >= deadline - 2.0:
            break
        hw = _warp(start_best, gamma)
        hd = min(deadline - 1.0, time.process_time() + budget_seconds * 0.06)
        cur, curR = run_cycle(hw, R_of(hw), hd)
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR
            print("warp gamma=%.2f R=%.7f" % (gamma, curR))

