        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _interlace_32(c, n_target, rng):
    m = c.size
    if m < 2:
        return np.repeat(c, max(1, n_target // max(1, m)))[:n_target]
    cm = np.cumsum(c)
    cm = cm / cm[-1]
    t = (np.arange(n_target) + 0.5) / n_target
    jitter = np.exp(0.02 * rng.standard_normal(n_target))
    t = np.clip(t * jitter, 1e-9, 1 - 1e-9)
    idx = np.searchsorted(cm, t)
    idx = np.clip(idx, 0, m - 1)
    return c[idx].astype(float)


def _fold_back(h_fine, n_target):
    n = h_fine.size
    if n == n_target:
        return h_fine.copy()
    cm = np.cumsum(h_fine)
    if cm[-1] <= 0:
        return np.zeros(n_target)
    cm = cm / cm[-1]
    t = (np.arange(n_target) + 0.5) / n_target
    idx = np.searchsorted(cm, t)
    idx = np.clip(idx, 0, n - 1)
    return h_fine[idx].astype(float)


def _roundtrip_from_fine(h_fine, N, dl):
    h_back = _fold_back(h_fine, N)
    h_back = _rescale(h_back)
    h_back = _polish_ladder(h_back, dl, betas=(1e7, 1e8, 0.0), iters=250)
    h_back = _peak_ladder(h_back, dl, pads=(0.08, 0.05), iters=250)
    return h_back


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    N = best.size

    # ---- Phase S: sub-cell (2x) lift with free weights, the main new idea ----
    # Represent best as 2x-resolution by repeat, then optimise all 2N free weights
    # with a beta ladder, and fold back to N. This explores the finer shape space
    # that a pure 2x-repeat cannot reach.
    sub_deadline = t0 + budget_seconds * 0.40
    if time.process_time() < sub_deadline - 2.0 and N >= 4:
        h_fine0 = np.repeat(best, 2)
        h_fine0 = _rescale(h_fine0)
        # small jitter to break symmetry
        h_fine0 *= np.exp(0.05 * rng.standard_normal(h_fine0.size))
        h_fine0 = _rescale(h_fine0)
        h_fine = _polish_ladder(h_fine0, sub_deadline,
                                betas=(1e6, 1e7, 1e8, 0.0), iters=250)
        # fold back
        h_back = _rescale(_fold_back(h_fine, N))
        h_back = _polish_ladder(h_back, sub_deadline,
                                betas=(1e7, 1e8, 0.0), iters=250)
        h_back = _peak_ladder(h_back, sub_deadline, pads=(0.08, 0.05, 0.03), iters=250)
        offer(h_back, 'sub2x')
        print("sub2x done R=%.9f" % R_of(h_back))

    # ---- Phase H: half-resolution quotient lift (3:2) ----
    half_deadline = t0 + budget_seconds * 0.60
    if time.process_time() < half_deadline - 2.0 and N >= 4:
        c = best[0::2].copy()
        c = _polish_ladder(c, half_deadline - 1.0,
                           betas=(1e6, 1e7, 0.0), iters=250)
        c = _peak_ladder(c, half_deadline - 1.0,
                         pads=(0.20, 0.12, 0.08), iters=250)
        h_fine = _interlace_32(c, 3 * c.size // 2, rng)
        h_fine = _rescale(h_fine)
        h_fine = _polish_ladder(h_fine, half_deadline - 1.0,
                                betas=(1e7, 1e8, 0.0), iters=250)
        h_back = _roundtrip_from_fine(h_fine, N, half_deadline - 0.5)
        offer(h_back, 'half32')
        print("half32 done R=%.9f" % R_of(h_back))

    # ---- Phase T: 1.5x fine lift with fold back (another route to sub-cells) ----
    t_deadline = t0 + budget_seconds * 0.78
    if time.process_time() < t_deadline - 2.0 and N >= 4:
        m = int(1.5 * N)
        h_fine = _interlace_32(best, m, rng)
        h_fine = _rescale(h_fine)
        h_fine = _polish_ladder(h_fine, t_deadline - 1.0,
                                betas=(1e7, 1e8, 0.0), iters=200)
        h_back = _roundtrip_from_fine(h_fine, N, t_deadline - 0.5)
        offer(h_back, 'fine15')
        print("fine15 done R=%.9f" % R_of(h_back))

    # ---- Phase F: high-beta sharpening on best ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=350)
        offer(ht, 'sharp')
        ht2 = _peak_ladder(best, deadline - 0.5, pads=(0.06, 0.04, 0.02), iters=250)
        offer(ht2, 'finalpeak')

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best), _argmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _newton_polish(best, bestR, deadline):
    win = _peak_window(best, pad_frac=0.25, extra=256)
    free = win[best[win] > 0]
    if free.size < 2:
        return best, bestR, False
    z0 = np.log(np.clip(best[free], 1e-300, None))
    base = best.copy()

    def fz(z):
        hh = base.copy()
        hh[free] = np.exp(np.clip(z, -700, 700))
        val, g = _fun_grad(hh)
        return val, g[free] * hh[free]

    def gz(z):
        return fz(z)[1]

    def hessp(z, p):
        try:
            nz = np.linalg.norm(z)
            np_ = np.linalg.norm(p)
            eps = 1e-6 * (1.0 + nz) / max(np_, 1e-30)
            gp = gz(z + eps * p)
            gm = gz(z - eps * p)
            return (gp - gm) / (2.0 * eps)
        except Exception:
            return p

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(fz, z0, jac=True, hessp=hessp, method='trust-krylov',
                       callback=cb,
                       options={'maxiter': 60, 'gtol': 1e-10,
                                'initial_tr_radius': 1e-3})
    except (TimeoutError, Exception):
        return best, bestR, False
    if res is None:
        return best, bestR, False
    ht = base.copy()
    ht[free] = np.exp(np.clip(res.x, -700, 700))
    ht = _rescale(np.clip(ht, 0.0, None))
    r = R_of(ht)
    if r > bestR + 1e-14:
        return ht, r, True
    return best, bestR, False


def _zero_frac(h):
    return float(np.mean(h == 0))


def _support_grow(h, rng, deadline, bestR):
    """Try adding support at the edges / filling zeros with small bumps."""
    n = h.size
    best, bestR_out = h, bestR
    for trial in range(6):
        if time.process_time() >= deadline - 0.6:
            break
        cand = h.copy()
        mode = trial % 3
        if mode == 0:
            # thicken support by appending a ramp at the right
            k = max(8, n // 200)
            tail = cand[-k:].copy()
            add = np.linspace(tail.mean() if tail.size else 0.0,
                              tail.mean() * 0.5 if tail.size else 0.0, k)
            cand = np.concatenate([cand, np.clip(add, 0, None) * 0.3])
        elif mode == 1:
            # fill zeros in support with tiny random bumps
            z = np.flatnonzero(cand == 0)
            if z.size == 0:
                continue
            pick = rng.choice(z, size=min(z.size, max(4, n // 100)), replace=False)
            scale = cand[cand > 0].mean() if np.any(cand > 0) else 1.0
            cand[pick] = scale * 0.01 * np.exp(rng.standard_normal(pick.size))
        else:
            # perturb positive heights multiplicatively
            nz = cand > 0
            if not np.any(nz):
                continue
            cand[nz] *= np.exp(0.05 * rng.standard_normal(nz.sum()))
        cand = _rescale(np.clip(cand, 0, None))
        r0 = R_of(cand)
        if r0 <= bestR_out:
            continue
        # then polish
        ht = _lbfgs_all_pos(cand, 200, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR_out + 1e-14:
            best, bestR_out = ht, r
    return best, bestR_out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: baseline cycle on start
    for beta in [1e6, 1e7, 0.0]:
        if time.process_time() >= deadline - 0.6:
            break
        ht = _lbfgs_all_pos(best, 250, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = "beta%g" % beta
            print("beta=%g: R=%.9f" % (beta, bestR))
    for it, pad in enumerate([0.20, 0.12, 0.08]):
        if time.process_time() >= deadline - 0.6:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 350, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = "pk%d" % it
            print("pk%d: R=%.9f" % (it, bestR))

    # Phase B: Newton polish
    if time.process_time() < deadline - 2.0:
        ht, r, gain = _newton_polish(best, bestR, deadline)
        if gain:
            best, bestR = ht, r
            origin = origin + '+newton'
            print("newton: R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # Phase C: support-growing random restarts (the new idea)
    # Cycle: grow support / perturb, re-polish, keep only improvements.
    while time.process_time() < deadline - 2.0:
        cand, r = _support_grow(best, rng, deadline, bestR)
        if r > bestR + 1e-14:
            best, bestR = cand, r
            origin = origin + '+grow'
            print("grow: R=%.9f" % bestR)
        # short polish on current best
        if time.process_time() >= deadline - 1.0:
            break
        for beta in [1e7, 0.0]:
            if time.process_time() >= deadline - 0.6:
                break
            ht = _lbfgs_all_pos(best, 200, deadline - 0.3, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
                origin = origin + '+p%g' % beta
                print("polish beta=%g: R=%.9f" % (beta, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # Phase D: final peak polishes
    for pad in [0.15, 0.10, 0.08, 0.20, 0.12]:
        if time.process_time() >= deadline - 0.6:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 350, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = origin + '+pk%.2f' % pad
            print("pad=%.2f: R=%.9f" % (pad, bestR))
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _grad_only(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    dnum = _backprop(dq, h)
    dm = np.zeros(h.size)
    k = m - 1
    if 0 <= k < 2 * h.size - 1:
        for j in range(max(0, k - h.size + 1), min(h.size, k + 1)):
            dm[j] = 2.0 * h[k - j]
    ds = np.ones(h.size)
    den = s * s * Lm
    dR = dnum / den - num * (2 * s * Lm * ds + s * s * dm) / (den * den)
    return dR


def _smooth_polish(h, deadline, iters=400):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    R = R_of(h)
    step = 1e-3 * h.max() / (np.abs(_grad_only(h)).max() + 1e-30)
    for it in range(iters):
        if time.process_time() > deadline - 0.3:
            break
        g = _grad_only(h)
        gn = np.max(np.abs(g))
        if gn <= 0:
            break
        step = min(step, 1e-2 * h.max() / gn)
        h2 = np.clip(h + step * g, 0, None)
        R2 = R_of(h2)
        if R2 > R:
            h = h2
            R = R2
            step *= 1.5
        else:
            step *= 0.5
            if step * gn < 1e-12 * h.max():
                break
    return _rescale(h)


def _peak_window_polish(h, deadline, pad, iters=250):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    k = m - 1
    lo = max(0, k - int(pad * n))
    hi = min(n, k + int(pad * n) + 1)
    if hi - lo < 8:
        return h
    sub = h[lo:hi].copy()
    base = h.copy()

    def f(x):
        hh = base.copy()
        hh[lo:hi] = np.clip(x, 0.0, None)
        s = hh.sum()
        if s <= 0:
            return 1e18, np.zeros_like(x)
        num, dq, Lf2 = _num_and_dq(hh)
        mm = int(np.argmax(Lf2))
        Lm = Lf2[mm]
        gLf = -dq / num
        gLf[mm] += 1.0 / Lm
        grad_full = _backprop(gLf, hh) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad_full[lo:hi]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, sub, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * sub.size,
                       callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    out = base.copy()
    out[lo:hi] = np.clip(res.x, 0.0, None)
    return _rescale(out)


def _stats(h):
    h = np.clip(np.asarray(h, float), 0, None)
    zf = float(np.mean(h <= 1e-12))
    mx = h.max()
    mean = h.mean()
    ratio = mx / mean if mean > 0 else 0.0
    Lf = _knots(h)
    Lm = Lf.max()
    nearmax5 = float(np.mean(Lf >= 0.95 * Lm)) if Lm > 0 else 0.0
    return zf, ratio, nearmax5


def _flat_phase(h, deadline, gamma, maxiter=250):
    """Gamma-compressed flat-target alternating projection on f*f."""
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    n = h.size
    base = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        s = hh.sum()
        if s <= 0:
            return 1e18, np.zeros_like(x)
        Lf = _knots(hh)
        M = Lf.max()
        if M <= 0:
            return 1e18, np.zeros_like(x)
        inner = Lf[1:-1]
        g = np.clip(inner / M, 1e-9, 1.0)
        T = M * (g ** gamma)
        diff = inner - T
        E = np.sum(diff * diff) / (M * M)
        gLf = np.zeros_like(Lf)
        gLf[1:-1] = diff / (M * M)
        grad = _backprop(gLf, hh)
        return E, grad

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, base, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    return _rescale(np.clip(res.x, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_h = None
    start_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            start_h = s.copy()
            start_R = R_of(s)

    if start_h is None:
        N = 512
        x = (np.arange(N) + 0.5) / N
        seed = np.exp(-((x - 0.5) ** 2) / (2 * 0.15 ** 2))
        h = _rescale(seed)
        for N2 in [1024, 2048, 4096, 8192, 16384, 32768]:
            idx = (np.arange(N2) * N // N2).astype(int)
            h = h[idx]
            N = N2
            if time.process_time() > deadline - 1.0:
                break
            h = _smooth_polish(h, deadline, 200)
        best = h
        bestR = R_of(h)
        zf, ratio, nm5 = _stats(best)
        print("R=%.6f N=%d zf=%.3f mx/mn=%.2f nm5=%.3f" % (bestR, len(best), zf, ratio, nm5))
        return best

    cur = start_h.copy()
    curR = start_R
    bestR = start_R
    best_h = start_h.copy()

    # Gamma-compressed flat-target sweep
    for gamma in (0.85, 0.70, 0.55, 0.40):
        if time.process_time() > deadline - 6.0:
            break
        R_before = R_of(cur)
        h = _flat_phase(cur, deadline, gamma, maxiter=250)
        if time.process_time() < deadline - 5.0:
            h2 = _lbfgs(h, 300, deadline, beta=1e7)
            if R_of(h2) >= R_of(h) - 1e-12:
                h = h2
            h2 = _lbfgs(h, 300, deadline, beta=0.0)
            if R_of(h2) >= R_of(h) - 1e-12:
                h = h2
        if time.process_time() < deadline - 4.0:
            for pad in (0.15, 0.10):
                if time.process_time() > deadline - 4.0:
                    break
                h2 = _peak_window_polish(h, deadline, pad, iters=250)
                if R_of(h2) >= R_of(h) - 1e-12:
                    h = h2
        R_after = R_of(h)
        zf, ratio, nm5 = _stats(h)
        print("gamma %.2f R_before=%.6f R_after=%.6f zf=%.3f mx/mn=%.2f nm5=%.3f"
              % (gamma, R_before, R_after, zf, ratio, nm5))
        if R_after > curR + 1e-12:
            cur = h
            curR = R_after
            if curR > bestR:
                bestR = curR
                best_h = cur.copy()

    # Final polish on best
    if time.process_time() < deadline - 3.0:
        h = best_h.copy()
        for beta in (1e8, 0.0):
            if time.process_time() > deadline - 2.0:
                break
            h2 = _lbfgs(h, 300, deadline, beta=beta)
            if R_of(h2) >= R_of(h) - 1e-12:
                h = h2
        for pad in (0.15, 0.10):
            if time.process_time() > deadline - 1.0:
                break
            h2 = _peak_window_polish(h, deadline, pad, iters=250)
            if R_of(h2) >= R_of(h) - 1e-12:
                h = h2
        R_h = R_of(h)
        if R_h > bestR:
            bestR = R_h
            best_h = h

    zf, ratio, nm5 = _stats(best_h)
    print("FINAL R=%.6f N=%d zf=%.3f mx/mn=%.2f nm5=%.3f"
          % (bestR, len(best_h), zf, ratio, nm5))

    if bestR > start_R:
        return {"best": best_h, "alternative": start_h}
    else:
        return {"best": start_h, "alternative": best_h}

